def _wallbox_budget_freshness_contract(ts_or_age: float, now_ts: Optional[float] = None) -> Dict[str, Any]:
    if now_ts is not None:
        try:
            ts = float(ts_or_age or 0.0)
            now = float(now_ts)
            if now < ts:
                return {
                    "age_s": now - ts,
                    "ok": False,
                    "stale": True,
                    "timeout": True,
                    "valid": False,
                    "reason": "timestamp_future",
                }
            age = now - ts
        except (TypeError, ValueError):
            age = 0.0
    else:
        age = max(0.0, float(ts_or_age or 0.0))

    stale = age >= 15.0
    timeout = age >= 45.0
    ok = not stale
    reason = "ok" if ok else ("timeout" if timeout else "stale")

    return {
        "age_s": age,
        "ok": ok,
        "stale": stale,
        "timeout": timeout,
        "valid": not timeout,
        "reason": reason,
    }


def _wallbox_budget_display_contract(
    effective_budget_w: Any,
    gross_group_budget_w: Any,
    public_mode: Any,
    cycle_token: Any,
    *,
    source_revision: Any = "",
    reason: Any = "controller_budget",
) -> Dict[str, Any]:
    """Bindet einen vollständig berechneten UI-Budgetwert an genau einen Zyklus.

    Der Vertrag verändert keine Regelentscheidung. Er lässt das Frontend nur
    zwischen einem echten 0-W-Entscheid und einem unvollständigen/vermischten
    Übergangspayload unterscheiden. Ältere Frontends ignorieren das Zusatzfeld.
    """
    try:
        effective_w = float(effective_budget_w)
        gross_w = float(gross_group_budget_w)
        mode = int(float(public_mode))
    except (TypeError, ValueError, OverflowError):
        effective_w = float("nan")
        gross_w = float("nan")
        mode = 0

    token = str(cycle_token or "").strip()
    source = str(source_revision or "").strip()
    reason_code = str(reason or "controller_budget").strip() or "controller_budget"
    source_valid = bool(
        not source
        or (source.startswith("sha256:") and len(source) == 71)
    )
    valid = bool(
        token
        and len(token) <= 128
        and mode in (0, 2, 3, 4, 5, 12)
        and source_valid
        and math.isfinite(effective_w)
        and math.isfinite(gross_w)
        and effective_w >= 0.0
        and gross_w >= 0.0
    )
    material = {
        "schema_version": "wallbox_budget_display_v1",
        "cycle_token": token,
        "source_revision": source,
        "public_mode": mode,
        "effective_budget_w": round(max(0.0, effective_w), 3) if valid else None,
        "gross_group_budget_w": round(max(0.0, gross_w), 3) if valid else None,
        "reason": reason_code,
    }
    revision = revision_hash(material) if valid else ""
    is_zero = bool(valid and material["effective_budget_w"] <= 0.0)
    return {
        **material,
        "valid": valid,
        "revision": revision,
        "source_bound": bool(
            source.startswith("sha256:")
            and len(source) == 71
        ),
        "zero_semantics": (
            "safety_or_control" if is_zero else
            ("positive_budget" if valid else "unbound_transition")
        ),
    }


def write_status(state_dict):
    """Schreibt immer einen ausdrücklichen Budget-Anzeigevertrag.

    Frühe Start-/Fehlerzustände besitzen noch keinen vollständig berechneten
    Budgetzyklus. Sie werden deshalb als ``unbound_transition`` veröffentlicht
    und können von neuen Oberflächen nicht mit einem echten 0-W-Entscheid
    verwechselt werden. Alte Oberflächen ignorieren das zusätzliche Feld.
    """
    payload = dict(state_dict or {})
    if "wb_budget_display_contract" not in payload:
        payload["wb_budget_display_contract"] = _wallbox_budget_display_contract(
            None,
            None,
            payload.get("wb_mode_active", payload.get("wb_mode", 0)),
            "",
            reason="unbound_transition",
        )
    return _write_status_raw(payload)


def _wallbox_storage_budget_identity_contract(budget: Any) -> Dict[str, Any]:
    if not isinstance(budget, dict) or not budget:
        return {"valid": False, "reason": "budget_missing_or_invalid"}

    budget_w = budget.get("budget_w")
    ts = budget.get("ts")
    if type(budget_w) is not int or type(ts) is not int:
        return {"valid": False, "reason": "producer_identity_decision_type_or_budget_mismatch"}

    identity = budget.get("producer_identity")
    if not isinstance(identity, dict):
        return {"valid": False, "reason": "producer_identity_missing"}

    if identity.get("decision_owner") != "storage_manager":
        return {"valid": False, "reason": "producer_identity_owner_mismatch"}

    if identity.get("decision_effect") != "flexible_consumer_power_budget":
        return {"valid": False, "reason": "producer_identity_effect_mismatch"}

    if identity.get("authorized_wallbox_budget_w") != budget_w or identity.get("decision_ts") != ts:
        return {"valid": False, "reason": "producer_identity_decision_type_or_budget_mismatch"}

    consumer_allocations = budget.get("consumer_allocations")
    if not isinstance(consumer_allocations, dict):
        return {"valid": False, "reason": "consumer_allocations_missing"}
    if consumer_allocations.get("wallbox") != identity.get("authorized_wallbox_budget_w"):
        return {"valid": False, "reason": "wallbox_allocation_scopes_conflict"}

    consumer_contract = budget.get("consumer_budget_contract")
    accounting_validation = validate_consumer_budget_contract(
        consumer_contract
    )
    if accounting_validation.get("valid") is not True:
        return {
            "valid": False,
            "reason": "consumer_budget_contract_invalid",
        }
    command_validation = validate_consumer_command_allocations(
        consumer_contract
    )
    if command_validation.get("valid") is not True:
        return {
            "valid": False,
            "reason": "consumer_command_contract_invalid",
        }

    accounting_allocations = dict(
        accounting_validation.get("allocations") or {}
    )
    command_allocations = dict(
        command_validation.get("allocations") or {}
    )
    energy_score = budget.get("energy_score")
    if not isinstance(energy_score, dict):
        return {"valid": False, "reason": "energy_score_missing"}
    if (
        budget.get("consumer_accounting_allocations")
        != accounting_allocations
        or energy_score.get("consumer_accounting_allocations")
        != accounting_allocations
    ):
        return {
            "valid": False,
            "reason": "consumer_accounting_scopes_conflict",
        }
    if (
        consumer_allocations != command_allocations
        or energy_score.get("consumer_allocations") != command_allocations
    ):
        return {
            "valid": False,
            "reason": "consumer_command_scopes_conflict",
        }
    identity_allocations = {
        "wallbox": identity.get("authorized_wallbox_budget_w"),
        "heatpump": identity.get("authorized_heatpump_budget_w"),
        "heater": identity.get("authorized_heater_budget_w"),
    }
    if identity_allocations != command_allocations:
        return {
            "valid": False,
            "reason": "consumer_identity_allocations_conflict",
        }

    gen_material = {k: v for k, v in identity.items() if k != "decision_generation"}
    if identity.get("decision_generation") != revision_hash(gen_material):
        return {"valid": False, "reason": "producer_identity_generation_mismatch"}

    binding_status = identity.get("binding_status")
    binding_keys = ("plan_id", "slot_id", "action_id")
    if binding_status == "bound":
        for k in binding_keys:
            val = identity.get(k)
            if not isinstance(val, str) or not val.startswith("sha256:"):
                return {"valid": False, "reason": "producer_identity_plan_binding_mismatch"}
    elif binding_status == "not_applicable":
        for k in binding_keys:
            if identity.get(k) != "not_applicable":
                return {"valid": False, "reason": "producer_identity_plan_binding_mismatch"}
    else:
        return {"valid": False, "reason": "producer_identity_plan_binding_mismatch"}

    rev_material = {k: v for k, v in budget.items() if k != "budget_revision"}
    if budget.get("budget_revision") != revision_hash(rev_material):
        return {"valid": False, "reason": "budget_revision_missing_or_mismatch"}

    return {
        "valid": True,
        "reason": "valid",
        "decision_generation": identity.get("decision_generation"),
        "producer_identity": dict(identity),
    }


def _wallbox_storage_power_budget_contract(
    budget: Any,
    freshness: Any = None,
    stale_limit_w: float = 4140.0,
    live_sample_invalid: bool = False,
) -> Dict[str, Any]:
    if live_sample_invalid:
        return {
            "valid": False,
            "available_w": 0.0,
            "continuation_only": False,
            "source": "invalid",
            "reason": "live_sample_invalid",
        }

    if not isinstance(freshness, dict) or freshness.get("timeout") or not freshness.get("valid", True):
        return {
            "valid": False,
            "available_w": 0.0,
            "continuation_only": False,
            "source": "invalid",
            "reason": "budget_timeout",
        }

    if not isinstance(budget, dict) or budget.get("schema_version") != "wb_pv_budget_control_v2":
        return {
            "valid": False,
            "available_w": 0.0,
            "continuation_only": False,
            "source": "invalid",
            "reason": "budget_schema_invalid",
        }
    if (
        budget.get("force_wallbox_stop") is True
        or budget.get("predump_floor_hold") is True
        or bool(str(budget.get("runtime_block_reason") or "").strip())
    ):
        return {
            "valid": False,
            "available_w": 0.0,
            "continuation_only": False,
            "source": "invalid",
            "reason": "budget_safety_block",
        }

    identity_result = _wallbox_storage_budget_identity_contract(budget)
    if not identity_result.get("valid"):
        return {
            "valid": False,
            "available_w": 0.0,
            "continuation_only": False,
            "source": "invalid",
            "reason": identity_result.get("reason", "identity_invalid"),
        }

    budget_w = float(budget.get("budget_w", 0))
    if freshness.get("stale"):
        return {
            "valid": True,
            "available_w": min(budget_w, float(stale_limit_w)),
            "continuation_only": True,
            "stale": True,
            "source": "stale_control_v2_continuation",
            "reason": "valid",
            "owner": "storage_manager",
            "producer_identity": identity_result.get("producer_identity"),
            "decision_generation": identity_result.get(
                "decision_generation"
            ),
        }

    return {
        "valid": True,
        "available_w": budget_w,
        "continuation_only": False,
        "stale": False,
        "source": "fresh_control_v2",
        "reason": "valid",
        "owner": "storage_manager",
        "producer_identity": identity_result.get("producer_identity"),
        "decision_generation": identity_result.get("decision_generation"),
    }


def _wallbox_grid_funded_safety_envelope_contract(
    budget: Any,
    freshness: Any,
    *,
    live_sample_invalid: bool = False,
    storage_grid_hold_active: bool = False,
) -> Dict[str, Any]:
    """Prüft nur den Safety-Umschlag, nicht das PV-Flexbudget.

    Ein fremder Verbraucher darf den gemeinsamen Flexbudget-Vertrag auf 0 W
    setzen, ohne damit eine explizit netzfinanzierte Wallbox zu verbieten. Die
    Quelle, Aktualität und wallboxbezogene Projektion müssen dennoch lückenlos
    gebunden sein; fehlende oder widersprüchliche Felder schließen das Gate.
    """

    result = {
        "valid": False,
        "reason": "missing",
        "producer_identity_valid": False,
        "ifc_readback_blocked": True,
        "ifc_readback_block_reason": "ifc_gate_missing",
    }
    if live_sample_invalid:
        result["reason"] = "live_sample_invalid"
        return result
    if not isinstance(freshness, dict):
        result["reason"] = "freshness_missing"
        return result
    if (
        freshness.get("ok") is not True
        or freshness.get("stale") is not False
        or freshness.get("timeout") is not False
        or freshness.get("valid") is not True
    ):
        result["reason"] = "budget_not_fresh"
        return result
    freshness_age_s = freshness.get("age_s")
    if (
        type(freshness_age_s) not in (int, float)
        or not math.isfinite(float(freshness_age_s))
        or not 0.0 <= float(freshness_age_s) < 15.0
    ):
        result["reason"] = "freshness_age_invalid"
        return result
    if not isinstance(budget, dict):
        result["reason"] = "budget_missing"
        return result
    if budget.get("schema_version") != "wb_pv_budget_control_v2":
        result["reason"] = "budget_schema_invalid"
        return result
    budget_w = budget.get("budget_w")
    decision_ts = budget.get("ts")
    if (
        type(budget_w) is not int
        or type(decision_ts) is not int
        or budget_w < 0
        or decision_ts <= 0
    ):
        result["reason"] = "budget_value_or_ts_invalid"
        return result
    budget_state = str(budget.get("state") or "").strip().lower()
    storage_state = str(budget.get("storage_state") or "").strip().lower()
    hard_state_active = bool(
        budget_state == "ifc_grid_hold"
        or storage_state == "ifc_grid_hold"
        or budget_state == "wallbox_predump_floor_hold"
        or storage_state == "wallbox_predump_floor_hold"
        or budget_state.startswith("pre_discharge")
        or storage_state.startswith("pre_discharge")
    )
    if (
        storage_grid_hold_active
        or hard_state_active
    ):
        result["reason"] = "storage_hard_state"
        return result
    if (
        budget.get("force_wallbox_stop") is True
        or budget.get("predump_floor_hold") is True
        or budget.get("predump_active") is True
        or budget.get("live_sample_invalid") is not False
        or bool(str(budget.get("runtime_block_reason") or "").strip())
    ):
        result["reason"] = "storage_safety_block"
        return result

    identity = budget.get("producer_identity")
    if not isinstance(identity, dict):
        result["reason"] = "producer_identity_missing"
        return result
    generation_material = {
        key: value
        for key, value in identity.items()
        if key != "decision_generation"
    }
    identity_wallbox_w = identity.get("authorized_wallbox_budget_w")
    identity_valid = bool(
        identity.get("schema_version")
        == "storage_consumer_budget_identity_v1"
        and identity.get("decision_owner") == "storage_manager"
        and identity.get("decision_effect")
        == "flexible_consumer_power_budget"
        and identity.get("decision_ts") == decision_ts
        and type(identity_wallbox_w) is int
        and identity_wallbox_w >= 0
        and identity_wallbox_w == budget_w
        and identity.get("decision_generation")
        == revision_hash(generation_material)
    )
    result["producer_identity_valid"] = identity_valid
    if not identity_valid:
        result["reason"] = "producer_identity_invalid"
        return result

    consumer_allocations = budget.get("consumer_allocations")
    energy_score = budget.get("energy_score")
    energy_allocations = (
        energy_score.get("consumer_allocations")
        if isinstance(energy_score, dict)
        else None
    )
    consumer_wallbox_w = (
        consumer_allocations.get("wallbox")
        if isinstance(consumer_allocations, dict)
        else None
    )
    energy_wallbox_w = (
        energy_allocations.get("wallbox")
        if isinstance(energy_allocations, dict)
        else None
    )
    if (
        not isinstance(consumer_allocations, dict)
        or not isinstance(energy_allocations, dict)
        or type(consumer_wallbox_w) is not int
        or type(energy_wallbox_w) is not int
        or consumer_wallbox_w < 0
        or energy_wallbox_w < 0
        or consumer_wallbox_w != budget_w
        or energy_wallbox_w != budget_w
    ):
        result["reason"] = "wallbox_projection_mismatch"
        return result
    revision_material = {
        key: value for key, value in budget.items() if key != "budget_revision"
    }
    if budget.get("budget_revision") != revision_hash(revision_material):
        result["reason"] = "budget_revision_invalid"
        return result

    ifc_gate = budget.get("wallbox_ifc_readback_gate")
    if not isinstance(ifc_gate, dict):
        result["reason"] = "ifc_gate_missing"
        return result
    if (
        ifc_gate.get("schema") != "wallbox_ifc_readback_gate_v1"
        or type(ifc_gate.get("contract_version")) is not int
        or ifc_gate.get("contract_version") != 2
        or type(ifc_gate.get("required")) is not bool
        or type(ifc_gate.get("released")) is not bool
    ):
        result["reason"] = "ifc_gate_contract_invalid"
        return result
    ifc_status = str(ifc_gate.get("status") or "")
    ifc_reason = str(ifc_gate.get("block_reason") or "")
    ifc_released = bool(
        ifc_gate.get("released") is True
        and not ifc_reason
        and (
            (
                ifc_gate.get("required") is False
                and ifc_status == "not_required"
            )
            or (
                ifc_gate.get("required") is True
                and ifc_status == "confirmed"
            )
        )
    )
    result["ifc_readback_blocked"] = not ifc_released
    result["ifc_readback_block_reason"] = ifc_reason
    if not ifc_released:
        result["reason"] = "ifc_gate_blocked"
        return result

    result["valid"] = True
    result["reason"] = "valid"
    return result


def _wallbox_grid_funded_authority_contract(
    *,
    controllable_charger_ids: Any,
    price_optimized_charger_ids: Any,
    manual_pause_by_id: Any,
    effective_public_wb_mode: Any,
    price_boost_wallbox_active: bool,
    effective_allow_grid: bool,
    grid_unlocked_all_controllable: bool,
    safety_envelope_valid: bool,
    hard_blocked: bool,
    predump_wallbox_active: bool,
    storage_predump_active: bool,
    storage_grid_hold_active: bool,
) -> Dict[str, Any]:
    """Bindet globale Netzfreigabe an jeden tatsächlich steuerbaren Ausgang."""

    try:
        controllable = {
            int(value)
            for value in (controllable_charger_ids or ())
            if int(value) > 0
        }
        price_optimized = {
            int(value)
            for value in (price_optimized_charger_ids or ())
            if int(value) > 0
        }
    except (TypeError, ValueError):
        controllable = set()
        price_optimized = set()
    manual_pause_contract_valid = isinstance(manual_pause_by_id, dict)
    paused = manual_pause_by_id if manual_pause_contract_valid else {}
    scope_ids = {
        charger_id
        for charger_id in controllable
        if not bool(paused.get(charger_id, paused.get(str(charger_id), False)))
    }
    raw_mode_active = bool(
        price_boost_wallbox_active
        or effective_allow_grid
        or grid_unlocked_all_controllable
    )
    outputs_bound = bool(scope_ids and scope_ids.issubset(price_optimized))
    blockers = []
    try:
        if isinstance(effective_public_wb_mode, bool):
            raise ValueError("bool_is_not_mode")
        public_mode_value = float(effective_public_wb_mode)
        public_mode = (
            int(public_mode_value)
            if math.isfinite(public_mode_value)
            and public_mode_value.is_integer()
            else MODE_OFF
        )
    except (TypeError, ValueError, OverflowError):
        public_mode = MODE_OFF
    if public_mode == MODE_OFF:
        blockers.append("mode_off")
    if not raw_mode_active:
        blockers.append("grid_mode_not_active")
    if not scope_ids:
        blockers.append("no_controllable_output")
    if not outputs_bound:
        blockers.append("grid_output_scope_not_fully_bound")
    if not manual_pause_contract_valid:
        blockers.append("manual_pause_contract_invalid")
    if safety_envelope_valid is not True:
        blockers.append("safety_envelope_invalid")
    if hard_blocked:
        blockers.append("hard_blocked")
    if predump_wallbox_active or storage_predump_active:
        blockers.append("predump_active")
    if storage_grid_hold_active:
        blockers.append("storage_grid_hold_active")
    return {
        "contract": "grid_funded_wallbox_authority_v1",
        "authorized": not blockers,
        "raw_mode_active": raw_mode_active,
        "outputs_bound": outputs_bound,
        "scope_ids": sorted(scope_ids),
        "price_optimized_ids": sorted(price_optimized),
        "blockers": blockers,
    }


def _fresh_curve_forecast_budget(
    budget: Any,
    *,
    budget_ok: bool,
    live_sample_invalid: bool,
) -> Dict[str, Any]:
    """Gibt Forecast-Felder nur aus einem frischen Control-v2-Budget frei."""

    data = budget if isinstance(budget, dict) else {}
    if (
        not budget_ok
        or live_sample_invalid
        or data.get("schema_version") != "wb_pv_budget_control_v2"
    ):
        return {}
    return data


def _wallbox_transient_invalid_budget_hard_blocked(
    *,
    emergency_stop_active: bool = False,
    budget_timeout: bool = False,
    budget_identity_valid: bool = True,
    wallbox_ifc_readback_blocked: bool = False,
    wallbox_ifc_readback_block_reason: str = "",
    force_wallbox_stop: bool = False,
    predump_floor_hold: bool = False,
    runtime_block_reason: str = "",
    explicit_valid_zero: bool = False,
) -> bool:
    if emergency_stop_active or budget_timeout or force_wallbox_stop or predump_floor_hold or explicit_valid_zero:
        return True
    if runtime_block_reason:
        return True
    if wallbox_ifc_readback_blocked:
        if not budget_identity_valid and wallbox_ifc_readback_block_reason == "ifc_budget_not_fresh":
            return False
        return True
    return False


_TRANSIENT_GRID_PM_OUTPUT_ANCHOR_KEY = "_transient_grid_pm_output_anchor"
_TRANSIENT_GRID_PM_OUTPUT_EPISODE_KEY = "_transient_grid_pm_output_episode"


def _wallbox_transient_grid_pm_output_hold_contract(
    c_data,
    status,
    live,
    live_plausibility,
    budget,
    *,
    now_ts,
    budget_ok,
    budget_timeout,
    budget_identity_valid,
    authorized_budget_w,
    live_snapshot_fresh,
    hard_blocked,
    min_amp=6,
    max_hold_s=10.0,
    max_import_w=150.0,
):
    """Bindet einen kurzen reinen Ausgangshalt an genau einen PM-Glitch.

    Der Vertrag autorisiert ausdrücklich keinen neuen Hardwarebefehl. Er darf
    nur verhindern, dass ein bereits belegter positiver Wallboxausgang wegen
    genau eines widersprüchlichen Grid-/PM-Bilds als 0-A-Stopp interpretiert
    wird. Ein gültiger Nullvertrag, echte Netzaufnahme oder jede andere
    Schutzkante bleibt damit unverändert vorrangig.
    """

    box = c_data if isinstance(c_data, dict) else {}
    st = status if isinstance(status, dict) else {}
    live_data = live if isinstance(live, dict) else {}
    plausibility = (
        live_plausibility if isinstance(live_plausibility, dict) else {}
    )
    budget_data = budget if isinstance(budget, dict) else {}
    now_value = _cfg_float(now_ts, 0.0)
    minimum_amp = max(6.0, _cfg_float(min_amp, 6.0))
    hold_limit_s = min(10.0, max(0.0, _cfg_float(max_hold_s, 10.0)))
    import_limit_w = max(0.0, _cfg_float(max_import_w, 150.0))
    charger = box.get("charger")
    charger_class = charger.__class__.__name__ if charger is not None else ""
    openwb_pro = charger_class == "OpenWBProCharger"
    family = "openwb_pro" if openwb_pro else "unsupported"
    session_id = str(box.get("_openwb_pro_plug_session_id") or "")
    status_fresh = _wallbox_start_hold_status_fresh(st)
    connected = _wb_status_connected(st)
    reported_amp = _fresh_wallbox_reported_current_amp(st)
    reported_amp = 0.0 if reported_amp is None else float(reported_amp)
    manager_amp = max(0.0, _cfg_float(box.get("current_set_amp"), 0.0))
    observed_phases = max(
        1,
        _valid_phase_count(st.get("phases_in_use"), 0),
        _valid_phase_count(st.get("phases_actual"), 0),
        _valid_phase_count(st.get("phases_target"), 0),
    )
    held_amp = max(reported_amp, manager_amp)
    revision = str(budget_data.get("budget_revision") or "")
    identity = (
        budget_data.get("producer_identity")
        if isinstance(budget_data.get("producer_identity"), dict)
        else {}
    )
    generation = str(identity.get("decision_generation") or "")
    minimum_budget_w = minimum_amp * 230.0 * float(observed_phases)
    positive_readback = bool(
        held_amp >= minimum_amp
        and (
            openwb_pro and reported_amp >= minimum_amp
        )
    )

    reasons = {
        str(item)
        for item in (plausibility.get("reasons") or [])
        if str(item or "").strip()
    }
    exact_pm_glitch = reasons == {"grid_pm_delta_high"}
    runtime_blockers = {
        token.strip()
        for token in str(
            budget_data.get("runtime_block_reason") or ""
        ).split(",")
        if token.strip()
    }
    pm_runtime_blockers = {
        "live_sample_invalid",
        "grid_power_invalid",
        "budget_data_invalid",
    }
    result = {
        "contract": "wallbox_transient_grid_pm_output_hold_v1",
        "active": False,
        "output_hold_only": False,
        "new_output_authorized": False,
        "family": family,
        "reason": "not_applicable",
        "hold_amp": held_amp,
        "session_id": session_id,
        "max_hold_s": hold_limit_s,
    }

    # Nur ein vollständig gültiger positiver Zentralvertrag plus frischer
    # Geräte-Readback darf den Anker eines späteren No-Write-Halts bilden.
    if not exact_pm_glitch:
        box.pop(_TRANSIENT_GRID_PM_OUTPUT_EPISODE_KEY, None)
        anchor_allowed = bool(
            family != "unsupported"
            and math.isfinite(now_value)
            and now_value > 0.0
            and budget_ok
            and not budget_timeout
            and budget_identity_valid
            and live_snapshot_fresh
            and not hard_blocked
            and status_fresh
            and connected
            and session_id
            and positive_readback
            and _cfg_float(authorized_budget_w, 0.0) + 0.001
            >= minimum_budget_w
            and revision.startswith("sha256:")
            and len(revision) == 71
            and generation.startswith("sha256:")
        )
        if anchor_allowed:
            box[_TRANSIENT_GRID_PM_OUTPUT_ANCHOR_KEY] = {
                "contract": "wallbox_transient_grid_pm_output_anchor_v1",
                "ts": now_value,
                "family": family,
                "session_id": session_id,
                "hold_amp": held_amp,
                "observed_phases": observed_phases,
                "budget_revision": revision,
                "decision_generation": generation,
                "source": "fresh_budget_and_device_readback",
            }
            result["reason"] = "fresh_anchor_bound"
        else:
            box.pop(_TRANSIENT_GRID_PM_OUTPUT_ANCHOR_KEY, None)
        box["_transient_grid_pm_output_hold_contract"] = dict(result)
        return result

    anchor = box.get(_TRANSIENT_GRID_PM_OUTPUT_ANCHOR_KEY)
    anchor = anchor if isinstance(anchor, dict) else {}

    # Ein unmittelbar zuvor bestätigter positiver I/O-Beleg überbrückt auch
    # die erste ungültige Live-Runde nach einem Start. Er ist kein neues
    # Budget: Der Executor hatte den Befehl bereits durch alle Deckel geführt.
    if not anchor:
        receipt = box.get("_last_executed_command")
        receipt = receipt if isinstance(receipt, dict) else {}
        receipt_ts = _cfg_float(receipt.get("ts"), 0.0)
        receipt_amp = _cfg_float(receipt.get("amp"), 0.0)
        receipt_method = str(receipt.get("method") or "")
        receipt_session_id = str(receipt.get("plug_session_id") or "")
        start_current_session_id = str(
            box.get("_openwb_pro_start_current_session_id") or ""
        )
        start_current_issued_ts = _cfg_float(
            box.get("_openwb_pro_start_current_issued_ts"),
            0.0,
        )
        receipt_age_s = now_value - receipt_ts
        receipt_matches = bool(
            family != "unsupported"
            and session_id
            and start_current_session_id == session_id
            and start_current_issued_ts > 0.0
            and start_current_issued_ts <= receipt_ts + 0.001
            and (
                not receipt_session_id
                or receipt_session_id == session_id
            )
            and status_fresh
            and connected
            and positive_readback
            and receipt_method in _EFFECTIVE_CURRENT_METHODS
            and receipt_amp >= minimum_amp
            and math.isfinite(receipt_age_s)
            and 0.0 <= receipt_age_s <= hold_limit_s
            and openwb_pro
        )
        if receipt_matches:
            anchor = {
                "contract": "wallbox_transient_grid_pm_output_anchor_v1",
                "ts": receipt_ts,
                "family": family,
                "session_id": session_id,
                "hold_amp": min(held_amp, receipt_amp),
                "observed_phases": observed_phases,
                "budget_revision": "receipt_bound",
                "decision_generation": "receipt_bound",
                "source": "recent_positive_wire_receipt_and_device_readback",
            }
            box[_TRANSIENT_GRID_PM_OUTPUT_ANCHOR_KEY] = dict(anchor)

    grid_w = _cfg_float(
        live_data.get("Grid_Power", live_data.get("Grid")),
        float("nan"),
    )
    pm_w = _cfg_float(
        live_data.get(
            "grid_pm_sum_w",
            (
                live_data.get("Power_Plausibility", {}).get("grid_pm_sum_w")
                if isinstance(live_data.get("Power_Plausibility"), dict)
                else None
            ),
        ),
        float("nan"),
    )
    anchor_ts = _cfg_float(anchor.get("ts"), 0.0)
    anchor_age_s = now_value - anchor_ts
    anchor_session = str(anchor.get("session_id") or "")
    anchor_family = str(anchor.get("family") or "")
    episode = box.get(_TRANSIENT_GRID_PM_OUTPUT_EPISODE_KEY)
    episode = episode if isinstance(episode, dict) else {}
    if (
        str(episode.get("session_id") or "") != session_id
        or _cfg_float(episode.get("anchor_ts"), 0.0) != anchor_ts
    ):
        episode = {
            "contract": "wallbox_transient_grid_pm_output_episode_v1",
            "started_ts": now_value,
            "anchor_ts": anchor_ts,
            "session_id": session_id,
        }
        box[_TRANSIENT_GRID_PM_OUTPUT_EPISODE_KEY] = dict(episode)
    episode_age_s = now_value - _cfg_float(episode.get("started_ts"), 0.0)

    blockers = []
    if family == "unsupported":
        blockers.append("unsupported_wallbox_family")
    if not budget_ok or budget_timeout or not budget_identity_valid:
        blockers.append("budget_not_fresh_and_bound")
    if not live_snapshot_fresh:
        blockers.append("live_snapshot_stale")
    if hard_blocked:
        blockers.append("hard_blocked")
    if runtime_blockers and not runtime_blockers.issubset(
        pm_runtime_blockers
    ):
        blockers.append("runtime_block_not_pm_scoped")
    if not status_fresh:
        blockers.append("device_status_not_fresh")
    if not connected or not session_id:
        blockers.append("plug_session_not_bound")
    if not positive_readback:
        blockers.append("positive_output_not_confirmed")
    if not anchor or anchor_family != family or anchor_session != session_id:
        blockers.append("positive_anchor_not_bound")
    if (
        not math.isfinite(anchor_age_s)
        or anchor_age_s < 0.0
        or anchor_age_s > hold_limit_s
        or not math.isfinite(episode_age_s)
        or episode_age_s < 0.0
        or episode_age_s > hold_limit_s
    ):
        blockers.append("hold_window_expired")
    if not bool(live_data.get("Grid_PM_Available", False)):
        blockers.append("grid_pm_not_available")
    if not math.isfinite(grid_w) or not math.isfinite(pm_w):
        blockers.append("grid_signals_not_finite")
    elif grid_w > import_limit_w or pm_w > import_limit_w:
        blockers.append("grid_import_not_excluded")

    if blockers:
        result.update({
            "reason": blockers[0],
            "blockers": blockers,
            "anchor_age_s": anchor_age_s,
            "episode_age_s": episode_age_s,
            "grid_w": grid_w if math.isfinite(grid_w) else None,
            "grid_pm_w": pm_w if math.isfinite(pm_w) else None,
        })
        box["_transient_grid_pm_output_hold_contract"] = dict(result)
        return result

    result.update({
        "active": True,
        "output_hold_only": True,
        "new_output_authorized": False,
        "reason": "single_grid_pm_delta_high_no_write_hold",
        "hold_amp": min(
            held_amp,
            max(0.0, _cfg_float(anchor.get("hold_amp"), 0.0)),
        ),
        "anchor_age_s": anchor_age_s,
        "episode_age_s": episode_age_s,
        "grid_w": grid_w,
        "grid_pm_w": pm_w,
        "budget_revision": str(anchor.get("budget_revision") or ""),
        "decision_generation": str(
            anchor.get("decision_generation") or ""
        ),
    })
    box["_transient_grid_pm_output_hold_contract"] = dict(result)
    return result


def _fresh_storage_wallbox_budget_w(
    budget_contract,
    *,
    effective_budget_w=0.0,
    budget_ok=True,
    live_sample_invalid=False,
    ifc_readback_blocked=False,
    max_age_s=10.0,
    now_ts=0.0,
) -> float:
    if not budget_ok or live_sample_invalid or ifc_readback_blocked:
        return 0.0
    if not isinstance(budget_contract, dict) or not budget_contract:
        return 0.0
    schema = budget_contract.get("schema_version")
    if schema != "wb_pv_budget_control_v2":
        return 0.0
    ts = budget_contract.get("ts")
    if not isinstance(ts, (int, float)) or ts <= 0:
        return 0.0
    now = float(now_ts or time.time())
    age = now - float(ts)
    if age < 0.0 or age > float(max_age_s):
        return 0.0
    if budget_contract.get("force_wallbox_stop") or budget_contract.get("predump_floor_hold"):
        return 0.0
    try:
        val = float(effective_budget_w)
        if math.isnan(val) or math.isinf(val):
            return 0.0
        bw = float(budget_contract.get("budget_w", 0.0))
        if math.isnan(bw) or math.isinf(bw):
            return 0.0
        return max(0.0, val)
    except (TypeError, ValueError):
        return 0.0


def _storage_wallbox_budget_minimum_w(budget_payload: dict = None, config_dict: dict = None) -> float:
    if not isinstance(budget_payload, dict):
        budget_payload = {}
    if not isinstance(config_dict, dict):
        config_dict = {}

    for key in ("wb_min_required_w", "min_required_w"):
        val = budget_payload.get(key)
        if val is not None:
            try:
                num = float(val)
                if num > 0.0:
                    return num
            except (TypeError, ValueError):
                pass

    min_amp = config_dict.get("wbminladestrom", 6)
    try:
        min_amp = float(min_amp)
    except (TypeError, ValueError):
        min_amp = 6.0

    phases = budget_payload.get("phases", config_dict.get("phases", 1))
    try:
        phases = int(phases)
    except (TypeError, ValueError):
        phases = 1

    return max(1380.0, min_amp * 230.0 * max(1, phases))


def _wallbox_primary_observe_only_by_id(chargers, effective_modes):
    """Markiert extern geführte openWB-Primary-Pfade als reine Beobachter."""

    modes = effective_modes if isinstance(effective_modes, dict) else {}
    result = {}
    for item in chargers or []:
        data = item if isinstance(item, dict) else {}
        wb_id = data.get("id") if data else getattr(item, "id", None)
        if wb_id is None:
            continue
        charger = data.get("charger") if data else getattr(item, "charger", None)
        mode = normalize_wb_mode(modes.get(wb_id, modes.get(str(wb_id), 0)))
        result[wb_id] = bool(
            bool(data.get("_physical_output_blocked", False))
            or (
                charger is not None
                and charger.__class__.__name__ == "OpenWBCharger"
                and getattr(charger, "primary_mode_enabled", False)
                and mode in (MODE_CURVE, MODE_TARGET)
            )
        )
    return result


def _wallbox_allocation_eligibility_contract(
    chargers,
    effective_modes,
    status_by_id=None,
    locked_by_id=None,
    manual_pause_by_id=None,
    observe_only_by_id=None,
    battery_departure_blocked_ids=None,
    max_amp_by_id=None,
    min_amp=6,
):
    """Bindet jede Gruppenallokation an den aktuellen Ladepunktvertrag."""

    statuses = status_by_id if isinstance(status_by_id, dict) else {}
    locked = locked_by_id if isinstance(locked_by_id, dict) else {}
    paused = manual_pause_by_id if isinstance(manual_pause_by_id, dict) else {}
    observed = (
        observe_only_by_id if isinstance(observe_only_by_id, dict) else {}
    )
    departure_blocked = set(battery_departure_blocked_ids or ())
    maximums = max_amp_by_id if isinstance(max_amp_by_id, dict) else {}
    modes = dict(effective_modes or {})
    allocatable_by_id = {}
    slots = {}
    try:
        minimum_amp = max(0, int(min_amp))
    except (TypeError, ValueError):
        minimum_amp = 6

    for item in chargers or []:
        data = item if isinstance(item, dict) else {}
        wb_id = data.get("id") if data else getattr(item, "id", None)
        if wb_id is None:
            continue
        mode = normalize_wb_mode(modes.get(wb_id, modes.get(str(wb_id), 0)))
        status = statuses.get(wb_id, statuses.get(str(wb_id)))
        status = status if isinstance(status, dict) else None
        bev_blocked = bool(
            data.get("_bev_full_blocked", False)
            if data
            else getattr(item, "_bev_full_blocked", False)
        )
        blockers = []
        if mode == MODE_OFF:
            blockers.append("mode_off_or_observe")
        if bev_blocked:
            blockers.append("vehicle_full_or_ended")
        if bool(paused.get(wb_id, paused.get(str(wb_id), False))):
            blockers.append("manual_pause")
        if bool(observed.get(wb_id, observed.get(str(wb_id), False))):
            blockers.append("external_primary_observe_only")
        if bool(data.get("_physical_output_blocked", False)):
            blockers.append("physical_output_identity_blocked")
        if wb_id in departure_blocked or str(wb_id) in departure_blocked:
            blockers.append("battery_departure_blocked")
        if bool(locked.get(wb_id, locked.get(str(wb_id), False))):
            blockers.append("wallbox_locked")
        try:
            maximum_amp = int(
                maximums.get(wb_id, maximums.get(str(wb_id), minimum_amp))
            )
        except (TypeError, ValueError):
            maximum_amp = 0
        if maximum_amp < minimum_amp:
            blockers.append("wallbox_current_limit_below_minimum")
        if status is None:
            blockers.append("wallbox_status_missing")
        elif (
            status.get("driver_status_valid") is False
            or bool(status.get("driver_status_stale", False))
            or bool(status.get("driver_status_degraded", False))
            or bool(status.get("driver_status_glitch", False))
            or status.get("valid") is False
            or bool(status.get("stale", False))
        ):
            blockers.append("wallbox_status_not_fresh")

        allocatable = not blockers
        allocatable_by_id[wb_id] = allocatable
        if not allocatable:
            modes[wb_id] = MODE_OFF
        slots[wb_id] = {
            "allocatable": allocatable,
            "blockers": tuple(blockers),
            "effective_mode": modes.get(wb_id, MODE_OFF),
            "minimum_amp": minimum_amp,
            "maximum_amp": max(0, maximum_amp),
        }
    return {
        "effective_modes": modes,
        "allocatable_by_id": allocatable_by_id,
        "slots": slots,
    }


def _wallbox_min_current_group_owner_contract(
    chargers,
    statuses,
    charge_modes,
    *,
    allocatable_by_id=None,
    priority_mode=0,
    min_amp=6,
    allocation_contract=None,
):
    """Wählt genau einen Stopkandidaten für das gemeinsame PCC-Integral."""

    modes = charge_modes if isinstance(charge_modes, dict) else {}
    allocatable = (
        allocatable_by_id
        if isinstance(allocatable_by_id, dict)
        else None
    )
    allocation = (
        allocation_contract
        if isinstance(allocation_contract, dict)
        else {}
    )
    slots = allocation.get("slots")
    slots = slots if isinstance(slots, dict) else {}
    try:
        minimum_amp = max(1, int(round(float(min_amp or 6))))
    except (TypeError, ValueError):
        minimum_amp = 6
    try:
        priority_id = int(round(float(priority_mode or 0)))
    except (TypeError, ValueError):
        priority_id = 0
    if priority_id not in (1, 2):
        priority_id = 0

    charger_by_id = {}
    for item in chargers or []:
        data = item if isinstance(item, dict) else {}
        try:
            wb_id = int(data.get("id", 0) or 0)
        except (TypeError, ValueError):
            wb_id = 0
        if wb_id > 0:
            charger_by_id[wb_id] = data

    status_by_id = {}
    for item in statuses or []:
        entry = item if isinstance(item, dict) else {}
        try:
            wb_id = int(entry.get("id", 0) or 0)
        except (TypeError, ValueError):
            wb_id = 0
        status = entry.get("status")
        if wb_id > 0 and isinstance(status, dict):
            status_by_id[wb_id] = status

    candidates = []
    for wb_id in sorted(charger_by_id):
        data = charger_by_id[wb_id]
        status = status_by_id.get(wb_id)
        if not isinstance(status, dict):
            continue
        mode = normalize_wb_mode(
            modes.get(wb_id, modes.get(str(wb_id), MODE_OFF))
        )
        if mode == MODE_OFF:
            continue
        if allocatable is not None and not bool(
            allocatable.get(wb_id, allocatable.get(str(wb_id), False))
        ):
            continue
        if (
            status.get("driver_status_valid") is not True
            or bool(status.get("driver_status_stale", False))
            or bool(status.get("driver_status_degraded", False))
            or bool(status.get("driver_status_glitch", False))
            or status.get("valid") is False
            or bool(status.get("stale", False))
            or not _wb_status_connected(status)
            or not _wb_status_real_charging(status)
            or data.get("_wb_stop_sent_active") is True
        ):
            continue
        reported_amp = max(
            _cfg_float(status.get("offered_current_raw"), 0.0),
            _cfg_float(status.get("offered_current"), 0.0),
            _cfg_float(status.get("evse_current"), 0.0),
            _cfg_float(status.get("amp"), 0.0),
        )
        effective_amp = (
            reported_amp
            if reported_amp > 0.0
            else _cfg_float(data.get("current_set_amp"), 0.0)
        )
        if effective_amp <= 0.0 or effective_amp > minimum_amp + 1e-6:
            continue
        phases = _wallbox_observed_phase_count(status)
        phases = phases if phases in (1, 2, 3) else 1
        slot = slots.get(wb_id, slots.get(str(wb_id)))
        allocated = (
            slot.get("allocated") is True
            if isinstance(slot, dict)
            else None
        )
        session_id = str(
            data.get(wallbox_start_hold.SESSION_KEY)
            or data.get("_openwb_pro_plug_session_id")
            or ""
        )
        candidates.append({
            "id": wb_id,
            "phases": phases,
            "minimum_power_w": float(minimum_amp * 230 * phases),
            "allocated": allocated,
            "priority": bool(priority_id and wb_id == priority_id),
            "plug_session_id": session_id,
        })

    unallocated = [
        item for item in candidates if item.get("allocated") is False
    ]
    if unallocated:
        owner = max(
            unallocated,
            key=lambda item: (item["minimum_power_w"], item["id"]),
        )
        owner_reason = "unallocated_candidate_first"
    elif priority_id and any(item["id"] == priority_id for item in candidates):
        non_priority = [
            item for item in candidates if item["id"] != priority_id
        ]
        pool = non_priority or candidates
        owner = max(
            pool,
            key=lambda item: (item["minimum_power_w"], item["id"]),
        ) if pool else None
        owner_reason = (
            "protect_priority_candidate"
            if non_priority
            else "only_priority_candidate"
        )
    else:
        owner = max(
            candidates,
            key=lambda item: (item["minimum_power_w"], item["id"]),
        ) if candidates else None
        owner_reason = (
            "largest_minimum_load_first"
            if owner is not None
            else "no_minimum_current_candidate"
        )

    owner_id = int((owner or {}).get("id", 0) or 0)
    candidate_ids = [int(item["id"]) for item in candidates]
    retained_ids = [
        candidate_id
        for candidate_id in candidate_ids
        if candidate_id != owner_id
    ]
    candidate_material = [
        {
            "id": int(item["id"]),
            "phases": int(item["phases"]),
            "minimum_power_w": round(float(item["minimum_power_w"]), 3),
            "allocated": item.get("allocated"),
        }
        for item in candidates
    ]
    session_material = [
        {
            "id": int(item["id"]),
            "plug_session_id": str(item.get("plug_session_id") or ""),
        }
        for item in candidates
    ]

    def _signature(value):
        encoded = json.dumps(
            value,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
        return "sha256:" + hashlib.sha256(encoded).hexdigest()

    return {
        "contract": "wallbox_min_current_group_owner_v1",
        "owner_id": owner_id,
        "owner_reason": owner_reason,
        "candidate_ids": candidate_ids,
        "retained_candidate_ids": retained_ids,
        "priority_id": priority_id,
        "minimum_amp": minimum_amp,
        "energy_meter_charger_id": 0,
        "energy_meter_scope": "pcc_group_once",
        "candidate_signature": _signature(candidate_material),
        "session_signature": _signature(session_material),
        "candidates": candidate_material,
    }


def _wallbox_min_current_group_generation_contract(
    runtime,
    owner_contract,
    chargers,
    statuses,
    allocation_contract=None,
):
    """Bindet den Gruppenowner erst im Folgezyklus und löscht alte Energie."""

    group = owner_contract if isinstance(owner_contract, dict) else {}
    allocation = (
        allocation_contract
        if isinstance(allocation_contract, dict)
        else {}
    )
    previous = getattr(
        runtime,
        "_min_current_group_generation_state",
        None,
    )
    previous = dict(previous) if isinstance(previous, dict) else {}
    try:
        owner_id = max(0, int(group.get("owner_id", 0) or 0))
    except (TypeError, ValueError):
        owner_id = 0
    candidate_signature = str(group.get("candidate_signature") or "")
    session_signature = str(group.get("session_signature") or "")

    cycle_tokens = {
        str(item.get("_wallbox_cycle_token") or "")
        for item in (chargers or [])
        if isinstance(item, dict)
    }
    cycle_token = next(iter(cycle_tokens)) if len(cycle_tokens) == 1 else ""
    cycle_valid = bool(cycle_token and "" not in cycle_tokens)

    stop_by_id = {}
    for item in chargers or []:
        data = item if isinstance(item, dict) else {}
        try:
            wb_id = int(data.get("id", 0) or 0)
            stop_ts = float(data.get("_last_stop_toggle_ts", 0.0) or 0.0)
        except (TypeError, ValueError):
            continue
        if wb_id > 0:
            stop_by_id[wb_id] = stop_ts

    slots = allocation.get("slots")
    slots = slots if isinstance(slots, dict) else {}
    allocation_material = []
    for raw_id, raw_slot in slots.items():
        slot = raw_slot if isinstance(raw_slot, dict) else {}
        try:
            wb_id = int(raw_id)
        except (TypeError, ValueError):
            continue
        allocation_material.append({
            "id": wb_id,
            "allocated": slot.get("allocated") is True,
            "effective_amp": _cfg_float(
                slot.get("effective_amp", slot.get("allocated_amp", 0.0)),
                0.0,
            ),
        })
    allocation_material.sort(key=lambda item: item["id"])
    allocation_signature = "sha256:" + hashlib.sha256(
        json.dumps(
            allocation_material,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()

    reset_reason = ""
    changed_stop_ids = []
    if not previous:
        reset_reason = "generation_initialized"
    elif not cycle_valid:
        reset_reason = "cycle_token_missing_or_split"
    elif owner_id != int(previous.get("owner_id", 0) or 0):
        reset_reason = "owner_changed"
    elif session_signature != str(previous.get("session_signature") or ""):
        reset_reason = "session_changed"
    elif candidate_signature != str(
        previous.get("candidate_signature") or ""
    ):
        reset_reason = "candidate_signature_changed"
    else:
        previous_stops = previous.get("stop_by_id")
        previous_stops = (
            previous_stops if isinstance(previous_stops, dict) else {}
        )
        changed_stop_ids = sorted(
            wb_id
            for wb_id in set(previous_stops) | set(stop_by_id)
            if _cfg_float(previous_stops.get(wb_id), 0.0)
            != _cfg_float(stop_by_id.get(wb_id), 0.0)
        )
        if changed_stop_ids:
            reset_reason = (
                "owner_stop_observed"
                if int(previous.get("owner_id", 0) or 0)
                in changed_stop_ids
                else "foreign_stop_observed"
            )
        elif allocation_signature != str(
            previous.get("allocation_signature") or ""
        ):
            reset_reason = "allocation_changed"

    generation = max(0, int(previous.get("binding_generation", 0) or 0))
    binding_ready = bool(previous.get("binding_ready", False))
    reset_cycle_token = str(previous.get("reset_cycle_token") or "")
    if reset_reason:
        generation += 1
        binding_ready = False
        reset_cycle_token = cycle_token
        reset_integral = getattr(
            runtime,
            "reset_min_current_import_integral",
            None,
        )
        if callable(reset_integral):
            reset_integral(0)
            reset_ids = set(group.get("candidate_ids") or ())
            reset_ids.update(previous.get("candidate_ids") or ())
            for candidate_id in reset_ids:
                try:
                    reset_integral(int(candidate_id))
                except (TypeError, ValueError):
                    continue
    elif (
        not binding_ready
        and cycle_valid
        and cycle_token != reset_cycle_token
        and owner_id > 0
    ):
        binding_ready = True

    state = {
        "owner_id": owner_id,
        "candidate_ids": list(group.get("candidate_ids") or ()),
        "candidate_signature": candidate_signature,
        "session_signature": session_signature,
        "allocation_signature": allocation_signature,
        "stop_by_id": stop_by_id,
        "binding_generation": generation,
        "binding_ready": binding_ready,
        "reset_cycle_token": reset_cycle_token,
        "cycle_token": cycle_token,
    }
    setattr(runtime, "_min_current_group_generation_state", state)
    effective_owner_id = owner_id if binding_ready and cycle_valid else 0
    result = {
        "contract": "wallbox_min_current_group_generation_v1",
        "binding_generation": generation,
        "binding_ready": bool(binding_ready and cycle_valid),
        "effective_owner_id": effective_owner_id,
        "configured_owner_id": owner_id,
        "reset_reason": reset_reason,
        "changed_stop_ids": changed_stop_ids,
        "cycle_token": cycle_token,
        "energy_meter_charger_id": 0,
        "energy_meter_scope": "pcc_group_once",
    }
    for item in chargers or []:
        if not isinstance(item, dict):
            continue
        item["_min_current_group_owner_contract"] = dict(group)
        item["_min_current_group_generation_contract"] = dict(result)
    return result


def _wallbox_status_fresh_real_charging(status):
    st = status if isinstance(status, dict) else {}
    return bool(
        st.get("driver_status_valid") is True
        and not bool(st.get("driver_status_stale", False))
        and not bool(st.get("driver_status_degraded", False))
        and not bool(st.get("driver_status_glitch", False))
        and st.get("valid") is not False
        and not bool(st.get("stale", False))
        and _wb_status_real_charging(st)
    )


def _wallbox_unique_running_storage_source_contract(
    configured_group_ids,
    statuses_by_id,
    charge_modes,
    *,
    storage_group_cap_w,
    data_fresh,
    safety_binding_valid,
    base_source_binding_key,
):
    """Ordnet einen absoluten Storage-Quellendeckel genau einem Läufer zu.

    Der Multi-Wallbox-Allokator darf den Ausgang weiterhin auf einen kleineren
    Watt-/Ampere-Sollwert begrenzen. Für den reinen Quellen-Wh-Wächter ist
    dieser Ausgangswert aber kein neuer Storage-Gesamtdeckel. Der absolute
    Storage-Rahmen darf nur dann einem Ladepunkt zugeordnet werden, wenn exakt
    eine Wallbox direkt messbar lädt und alle anderen konfigurierten
    Ladepunkte im selben Zyklus frisch als wirklich inaktiv belegt sind.

    Der Vertrag besitzt ausdrücklich keine Ausgangsautorität. Bei zwei
    Läufern, einer Messlücke oder einer unklaren Idle-Wallbox bleibt die
    Quellenabrechnung unbekannt; der unabhängige PCC-/Netz-Wh-Wächter bleibt
    davon unberührt.
    """

    result = {
        "contract": "wallbox_unique_running_storage_source_v1",
        "active": False,
        "valid": False,
        "owner_id": 0,
        "cap_by_id": {},
        "storage_group_cap_w": None,
        "source_ceiling_w": None,
        "binding_key": "",
        "status_sample_keys": {},
        "reason": "source_group_not_evaluated",
        "blockers": [],
        "output_authority": False,
    }
    group_ids = set()
    for raw_id in configured_group_ids or ():
        if isinstance(raw_id, bool):
            result["blockers"].append("configured_id_invalid")
            continue
        try:
            wb_id = int(raw_id)
        except (TypeError, ValueError, OverflowError):
            result["blockers"].append("configured_id_invalid")
            continue
        if wb_id <= 0 or wb_id in group_ids:
            result["blockers"].append("configured_id_invalid_or_duplicate")
            continue
        group_ids.add(wb_id)
    if len(group_ids) < 2:
        result["blockers"].append("configured_group_missing")

    if isinstance(storage_group_cap_w, bool) or storage_group_cap_w is None:
        group_cap_w = None
    else:
        try:
            group_cap_w = float(storage_group_cap_w)
        except (TypeError, ValueError, OverflowError):
            group_cap_w = None
    if group_cap_w is None or not math.isfinite(group_cap_w) or group_cap_w < 0.0:
        result["blockers"].append("storage_group_cap_invalid")
    else:
        result["storage_group_cap_w"] = round(group_cap_w, 6)
        result["source_ceiling_w"] = round(group_cap_w, 6)

    if data_fresh is not True:
        result["blockers"].append("source_data_not_fresh")
    if safety_binding_valid is not True:
        result["blockers"].append("storage_safety_binding_invalid")
    base_binding = str(base_source_binding_key or "")
    if not (
        base_binding.startswith("sha256:")
        and len(base_binding) == 71
        and all(char in "0123456789abcdef" for char in base_binding[7:])
    ):
        result["blockers"].append("base_source_binding_invalid")

    statuses = statuses_by_id if isinstance(statuses_by_id, dict) else {}
    modes = charge_modes if isinstance(charge_modes, dict) else {}
    active_ids = []
    for wb_id in sorted(group_ids):
        status = statuses.get(wb_id)
        if not isinstance(status, dict):
            result["blockers"].append("wb%d:status_missing" % wb_id)
            continue
        sample = wallbox_source_watt_cap.status_sample_binding(status)
        result["status_sample_keys"][wb_id] = str(
            sample.get("sample_key") or ""
        )
        if sample.get("valid") is not True:
            result["blockers"].append("wb%d:status_sample_unbound" % wb_id)
            continue

        if _wallbox_status_fresh_real_charging(status):
            measurement = wallbox_source_watt_cap.measured_power_evidence(
                status
            )
            if measurement.get("valid") is not True:
                result["blockers"].append(
                    "wb%d:direct_power_unbound" % wb_id
                )
                continue
            active_ids.append(wb_id)
            continue

        charge_contract = status.get("charge_contract")
        if not isinstance(charge_contract, dict):
            charge_contract = wallbox_decision.charge_observation_contract(
                status
            )
        direct_raw_power_w = max(
            0.0,
            *(
                abs(_cfg_float(status.get(key), 0.0))
                for key in (
                    "real_power_w",
                    "power_w",
                    "phase_power_sum_w",
                    "phase_power_l1_w",
                    "phase_power_l2_w",
                    "phase_power_l3_w",
                )
            ),
        )
        idle_proven = bool(
            str(charge_contract.get("truth") or "") == "not_charging"
            and not bool(status.get("charging", False))
            and not bool(status.get("charge_state", False))
            and not bool(status.get("device_working", False))
            and not bool(status.get("alg_charging", False))
            and status.get("phase_power_verified") is not True
            and direct_raw_power_w <= 100.0
        )
        if not idle_proven:
            result["blockers"].append("wb%d:idle_not_proven" % wb_id)

    if len(active_ids) != 1:
        result["blockers"].append(
            "unique_running_wallbox_missing"
            if not active_ids
            else "multiple_running_wallboxes"
        )
    owner_id = active_ids[0] if len(active_ids) == 1 else 0
    if owner_id > 0 and not storage_floor_mode(
        modes.get(owner_id, modes.get(str(owner_id), MODE_OFF))
    ):
        result["blockers"].append("running_wallbox_not_storage_eligible")

    if result["blockers"]:
        result["reason"] = result["blockers"][0]
        return result

    cap_by_id = {
        wb_id: round(group_cap_w if wb_id == owner_id else 0.0, 6)
        for wb_id in sorted(group_ids)
    }
    binding_material = {
        "contract": result["contract"],
        "base_source_binding_key": base_binding,
        "configured_ids": sorted(group_ids),
        "owner_id": owner_id,
        "cap_by_id": cap_by_id,
        "storage_group_cap_w": round(group_cap_w, 6),
        "status_sample_keys": [
            [wb_id, result["status_sample_keys"][wb_id]]
            for wb_id in sorted(group_ids)
        ],
    }
    result.update({
        "active": True,
        "valid": True,
        "owner_id": owner_id,
        "cap_by_id": cap_by_id,
        "binding_key": revision_hash(binding_material),
        "reason": "unique_running_storage_source_bound",
    })
    return result


def _wallbox_source_accounting_projection_contract(
    wb_id,
    *,
    default_cap_w,
    default_ceiling_w,
    default_group_budget_w,
    default_cap_basis,
    default_binding_key,
    storage_group_cap_w,
    multi_scope,
    unique_running_contract,
):
    """Projiziert ausschließlich den Quellenrahmen, nie den Ausgangsdeckel."""

    charger_id = int(_cfg_float(wb_id, 0.0))
    default_group_w = max(
        0.0,
        _cfg_float(default_group_budget_w, 0.0),
    )
    storage_group_w = max(
        0.0,
        _cfg_float(storage_group_cap_w, 0.0),
    )
    decoupled = bool(
        multi_scope
        and storage_group_w > default_group_w + 1e-6
    )
    result = {
        "contract": "wallbox_source_accounting_projection_v1",
        "source_cap_w": max(0.0, _cfg_float(default_cap_w, 0.0)),
        "source_ceiling_w": max(
            0.0,
            _cfg_float(default_ceiling_w, default_group_w),
        ),
        "source_group_budget_w": default_group_w,
        "cap_basis": str(default_cap_basis or ""),
        "source_binding_key": str(default_binding_key or ""),
        "source_contract_available": True,
        "decoupled": decoupled,
        "unique_owner_bound": False,
        "reason": "default_source_projection",
        "output_authority": False,
    }
    if not decoupled:
        return result

    unique = (
        unique_running_contract
        if isinstance(unique_running_contract, dict)
        else {}
    )
    if not (
        unique.get("valid") is True
        and int(_cfg_float(unique.get("owner_id"), 0.0)) == charger_id
        and charger_id > 0
    ):
        result.update({
            "source_contract_available": False,
            "reason": "decoupled_source_owner_unbound",
        })
        return result

    cap_by_id = unique.get("cap_by_id")
    cap_by_id = cap_by_id if isinstance(cap_by_id, dict) else {}
    source_cap_w = _cfg_float(cap_by_id.get(charger_id), -1.0)
    source_ceiling_w = _cfg_float(unique.get("source_ceiling_w"), -1.0)
    source_group_budget_w = _cfg_float(
        unique.get("storage_group_cap_w"),
        -1.0,
    )
    binding_key = str(unique.get("binding_key") or "")
    if not (
        source_cap_w >= 0.0
        and source_ceiling_w >= source_cap_w
        and source_group_budget_w >= source_ceiling_w
        and binding_key.startswith("sha256:")
    ):
        result.update({
            "source_contract_available": False,
            "reason": "unique_source_projection_invalid",
        })
        return result

    result.update({
        "source_cap_w": source_cap_w,
        "source_ceiling_w": source_ceiling_w,
        "source_group_budget_w": source_group_budget_w,
        "cap_basis": "unique_running_storage_group_cap",
        "source_binding_key": binding_key,
        "source_contract_available": True,
        "unique_owner_bound": True,
        "reason": "unique_running_storage_source_projection",
    })
    return result


def _wallbox_reservation_phase_contract(status):
    st = status if isinstance(status, dict) else {}
    observed = _wallbox_observed_phase_count(st)
    reservation = observed
    source = "observed"
    if reservation not in (1, 2, 3):
        for key in (
            "phase_effective_phases",
            "phases_target",
            "number_phases",
            "connected_phases",
        ):
            try:
                candidate = int(float(st.get(key, 0) or 0))
            except (TypeError, ValueError):
                candidate = 0
            if candidate in (1, 2, 3):
                reservation = candidate
                source = key
                break
    if reservation not in (1, 2, 3):
        reservation = 3
        source = "unknown_conservative_3p"
    return observed, reservation, source


def _wallbox_positive_output_receipt_contract(c_data, status):
    data = c_data if isinstance(c_data, dict) else {}
    st = status if isinstance(status, dict) else {}
    receipt = data.get("_last_executed_command")
    receipt = receipt if isinstance(receipt, dict) else {}
    method = str(receipt.get("method") or "")
    try:
        amp = max(0.0, float(receipt.get("amp", 0.0) or 0.0))
        command_ts = float(receipt.get("ts", 0.0) or 0.0)
        sample_ts = max(
            float(st.get("driver_status_last_sample_ts", 0.0) or 0.0),
            float(st.get("driver_status_last_ok_ts", 0.0) or 0.0),
        )
    except (TypeError, ValueError):
        amp = 0.0
        command_ts = 0.0
        sample_ts = 0.0
    age_s = sample_ts - command_ts
    confirmed = bool(
        method in {
            "set_amp_and_state",
            "set_direct_current",
            "set_amp_sonnenmodus",
            "set_amp_autonomous_solar",
        }
        and amp > 0.0
        and command_ts > 0.0
        and sample_ts > 0.0
        and 0.0 <= age_s <= 15.0
    )
    return {
        "confirmed": confirmed,
        "amp": amp if confirmed else 0.0,
        "command_ts": command_ts,
        "sample_ts": sample_ts,
        "age_s": age_s if command_ts > 0.0 and sample_ts > 0.0 else None,
    }


def _wallbox_grace_running_reservation_contract(c_data, status):
    """Reserviert nur belegte Last eines nicht neu allokierbaren Ladepunkts."""

    data = c_data if isinstance(c_data, dict) else {}
    st = status if isinstance(status, dict) else {}
    degraded = bool(
        st.get("driver_status_valid") is False
        and st.get("driver_status_degraded") is True
        and not bool(st.get("driver_status_stale", False))
        and not bool(st.get("driver_status_glitch", False))
        and not bool(st.get("stale", False))
    )
    fresh = bool(
        st
        and st.get("driver_status_valid") is not False
        and not bool(st.get("driver_status_stale", False))
        and not bool(st.get("driver_status_degraded", False))
        and not bool(st.get("driver_status_glitch", False))
        and st.get("valid") is not False
        and not bool(st.get("stale", False))
    )
    try:
        status_age_s = max(0.0, float(st.get("driver_status_age_s", 0.0) or 0.0))
    except (TypeError, ValueError):
        status_age_s = 999999.0
    grace_measurement_current = bool(degraded and status_age_s <= 45.0)
    grace_receipt_current = bool(degraded and status_age_s <= 15.0)

    phase_sum_w = 0.0
    for key in (
        "real_power_w",
        "power_w",
        "phase_power_sum_w",
    ):
        try:
            phase_sum_w = max(phase_sum_w, float(st.get(key, 0.0) or 0.0))
        except (TypeError, ValueError):
            pass
    try:
        measured_phase_sum_w = sum(
            max(0.0, float(st.get(key, 0.0) or 0.0))
            for key in (
                "phase_power_l1_w",
                "phase_power_l2_w",
                "phase_power_l3_w",
            )
        )
    except (TypeError, ValueError):
        measured_phase_sum_w = 0.0
    phase_sum_w = max(phase_sum_w, measured_phase_sum_w)
    charge_contract = (
        st.get("charge_contract")
        if isinstance(st.get("charge_contract"), dict)
        else {}
    )
    try:
        phase_sum_w = max(
            phase_sum_w,
            float(charge_contract.get("power_w", 0.0) or 0.0),
        )
    except (TypeError, ValueError):
        pass
    hardware_charging = bool(
        st.get("charging")
        or st.get("charge_state")
        or charge_contract.get("hardware_charging")
        or charge_contract.get("is_charging")
    )
    physical_running = bool(
        phase_sum_w > 50.0
        and (
            hardware_charging
            or bool(st.get("phase_power_verified", False))
            or charge_contract.get("truth") == "charging"
        )
    )
    measured_w = phase_sum_w if physical_running else 0.0
    observed_phases, reservation_phases, phase_source = (
        _wallbox_reservation_phase_contract(st)
    )
    receipt = _wallbox_positive_output_receipt_contract(data, st)
    command_ceiling_w = (
        float(receipt.get("amp", 0.0) or 0.0)
        * 230.0
        * reservation_phases
        if receipt.get("confirmed")
        else 0.0
    )

    active = False
    reserve_w = 0.0
    source = "not_running_or_status_unusable"
    if (grace_measurement_current or fresh) and measured_w > 0.0:
        reserve_w = measured_w
        active = True
        source = (
            "last_good_real_power"
            if grace_measurement_current
            else "fresh_unmanaged_real_power"
        )
        if grace_receipt_current and command_ceiling_w > measured_w:
            reserve_w = command_ceiling_w
            source = "last_good_real_power_and_command_ceiling"
    elif (grace_receipt_current or fresh) and receipt.get("confirmed"):
        reserve_w = command_ceiling_w
        active = reserve_w > 0.0
        source = (
            "confirmed_output_after_idle_readback"
            if grace_receipt_current
            else "bound_transition_current_phase_estimate"
        )
    elif grace_measurement_current and hardware_charging:
        source = "grace_running_without_power_evidence"
    elif fresh and hardware_charging:
        source = "fresh_unmanaged_running_without_power_evidence"

    return {
        "active": bool(active),
        "reserve_w": max(0.0, float(reserve_w)),
        "source": source,
        "allocation_class": (
            "status_grace_running"
            if grace_measurement_current
            else "fresh_unmanaged_running"
            if fresh
            else "not_reservable"
        ),
        "physical_running_last_good": bool(physical_running),
        "hardware_charging_last_good": bool(hardware_charging),
        "confirmed_positive_output": bool(receipt.get("confirmed")),
        "transition_receipt_bound": bool(receipt.get("confirmed")),
        "transition_receipt_age_s": receipt.get("age_s"),
        "last_command_age_s": receipt.get("age_s"),
        "observed_phases": int(observed_phases or 0),
        "reservation_phases": int(reservation_phases),
        "reservation_phase_source": phase_source,
    }


def _wallbox_grace_running_allocation_budget(
    gross_budget_w,
    chargers,
    statuses,
    *,
    allocatable_by_id=None,
):
    """Zieht belegte fremde/Grace-Last genau einmal vom Gruppenrahmen ab."""

    try:
        gross_w = max(0.0, float(gross_budget_w or 0.0))
    except (TypeError, ValueError):
        gross_w = 0.0
    allocatable = (
        allocatable_by_id if isinstance(allocatable_by_id, dict) else None
    )
    charger_by_id = {}
    for item in chargers or []:
        data = item if isinstance(item, dict) else {}
        wb_id = data.get("id") if data else getattr(item, "id", None)
        if wb_id is not None:
            charger_by_id[wb_id] = data if data else item

    reservations = {}
    reserved_w = 0.0
    for item in sorted(
        (entry for entry in (statuses or []) if isinstance(entry, dict)),
        key=lambda entry: int(entry.get("id", 0) or 0),
    ):
        wb_id = item.get("id")
        if wb_id is None:
            continue
        status = item.get("status")
        grace = bool(
            isinstance(status, dict)
            and status.get("driver_status_valid") is False
            and status.get("driver_status_degraded") is True
            and not bool(status.get("driver_status_stale", False))
        )
        unmanaged = bool(
            allocatable is not None
            and not allocatable.get(wb_id, allocatable.get(str(wb_id), False))
        )
        if not (grace or unmanaged):
            continue
        reservation = _wallbox_grace_running_reservation_contract(
            charger_by_id.get(wb_id, {}),
            status,
        )
        requested_w = max(
            0.0,
            float(reservation.get("reserve_w", 0.0) or 0.0),
        )
        granted_w = min(requested_w, max(0.0, gross_w - reserved_w))
        reservation = dict(reservation)
        reservation["reserve_w"] = granted_w
        reservation["active"] = bool(
            reservation.get("active") and granted_w > 0.0
        )
        reservations[wb_id] = reservation
        reserved_w += granted_w

    managed_w = max(0.0, gross_w - reserved_w)
    ledger = {
        "schema_version": "wallbox_group_power_ledger_v1",
        "gross_group_budget_w": gross_w,
        "reserved_w": reserved_w,
        "unmanaged_reserved_w": reserved_w,
        "managed_budget_w": managed_w,
        "reservations": reservations,
    }
    return managed_w, ledger


def _wallbox_group_allocation_conservation_contract(
    gross_budget_w,
    ledger,
    allocations,
):
    """Beweist die Gruppenwattbilanz typisiert und ohne Imputation."""

    try:
        gross_w = float(gross_budget_w)
        reserved_w = float(
            (ledger or {}).get("unmanaged_reserved_w", 0.0)
        )
    except (TypeError, ValueError):
        gross_w = -1.0
        reserved_w = -1.0
    targets_w = 0.0
    typed = bool(
        isinstance(ledger, dict)
        and isinstance(allocations, dict)
        and math.isfinite(gross_w)
        and math.isfinite(reserved_w)
        and gross_w >= 0.0
        and reserved_w >= 0.0
    )
    for item in (allocations or {}).values() if isinstance(allocations, dict) else ():
        if not isinstance(item, dict):
            typed = False
            continue
        try:
            target_w = float(item.get("target_power_w", 0.0))
        except (TypeError, ValueError):
            target_w = -1.0
        if not math.isfinite(target_w) or target_w < 0.0:
            typed = False
        else:
            targets_w += target_w
    conserved = bool(
        typed
        and reserved_w <= gross_w + 1e-6
        and reserved_w + targets_w <= gross_w + 1e-6
    )
    return {
        "valid": conserved,
        "gross_group_budget_w": max(0.0, gross_w),
        "unmanaged_reserved_w": max(0.0, reserved_w),
        "target_power_sum_w": max(0.0, targets_w),
        "accounted_power_sum_w": max(0.0, reserved_w + targets_w),
        "reason": (
            "wallbox_group_power_conserved"
            if conserved
            else "wallbox_group_power_overallocated"
        ),
    }


def _wallbox_group_allocation_fail_closed_contract(
    configured_group_ids,
    gross_budget_w,
    phase_count_by_id=None,
    error=None,
):
    """Bindet bei einem Gruppenfehler die gesamte Aktorautorität auf null."""

    group_ids = set()
    for charger_id in configured_group_ids or ():
        try:
            normalized_id = int(charger_id)
        except (TypeError, ValueError):
            continue
        if normalized_id > 0:
            group_ids.add(normalized_id)
    try:
        gross_w = max(0.0, float(gross_budget_w or 0.0))
    except (TypeError, ValueError):
        gross_w = 0.0
    if not math.isfinite(gross_w):
        gross_w = 0.0
    phases_by_id = phase_count_by_id or {}
    allocations = {}
    for charger_id in sorted(group_ids):
        try:
            target_phases = max(
                0,
                int(phases_by_id.get(charger_id, 0) or 0),
            )
        except (TypeError, ValueError):
            target_phases = 0
        allocations[charger_id] = {
            "target_amp": 0,
            "target_amp_per_phase": 0,
            "target_power_w": 0.0,
            "target_phases": target_phases,
            "state": 1,
            "reason": "group_allocation_not_ready",
        }
    ledger = {
        "schema_version": "wallbox_group_power_ledger_v1",
        "gross_group_budget_w": gross_w,
        "reserved_w": gross_w,
        "unmanaged_reserved_w": gross_w,
        "managed_budget_w": 0.0,
        "reservations": {},
        "fail_closed_hold_w": gross_w,
        "allocation_ready": False,
        "failure": type(error).__name__ if error is not None else "unknown",
    }
    conservation = _wallbox_group_allocation_conservation_contract(
        gross_w,
        ledger,
        allocations,
    )
    conservation["fail_closed_targets"] = True
    ledger["conservation"] = dict(conservation)
    return {
        "ready": False,
        "allocations": allocations,
        "ledger": ledger,
        "conservation": conservation,
    }


def _wallbox_group_allocation_exception_guard(
    configured_group_ids,
    gross_budget_w,
    phase_count_by_id,
    operation,
):
    """Führt einen Produktvorlauf aus und projiziert Exceptions fail-closed."""

    try:
        result = operation()
    except Exception as error:
        return _wallbox_group_allocation_fail_closed_contract(
            configured_group_ids,
            gross_budget_w,
            phase_count_by_id,
            error,
        )
    return {
        "ready": True,
        "result": result,
    }


def _wallbox_group_authority_caps_contract(
    configured_group_ids,
    allocation_ready,
    allocations,
):
    """Projiziert die einzige Gruppenautorität auf Watt- und Ampere-Deckel."""

    group_ids = set()
    for charger_id in configured_group_ids or ():
        try:
            normalized_id = int(charger_id)
        except (TypeError, ValueError):
            continue
        if normalized_id > 0:
            group_ids.add(normalized_id)
    ready = bool(allocation_ready and isinstance(allocations, dict))
    if ready:
        try:
            allocation_ids = set()
            for raw_id in allocations:
                if isinstance(raw_id, bool):
                    raise ValueError("wallbox_group_allocation_id_invalid")
                normalized_id = int(raw_id)
                if normalized_id <= 0 or normalized_id in allocation_ids:
                    raise ValueError(
                        "wallbox_group_allocation_id_alias_collision"
                    )
                allocation_ids.add(normalized_id)
        except (TypeError, ValueError):
            ready = False
    watt_caps = {}
    amp_caps = {}
    state_by_id = {}
    for charger_id in sorted(group_ids):
        allocation = allocations.get(charger_id) if ready else None
        try:
            target_w = float((allocation or {}).get("target_power_w", 0.0))
            target_amp = int(float((allocation or {}).get("target_amp", 0)))
            target_state = int(float((allocation or {}).get("state", 1)))
        except (AttributeError, TypeError, ValueError):
            target_w = 0.0
            target_amp = 0
            target_state = 1
        if (
            not ready
            or not isinstance(allocation, dict)
            or not math.isfinite(target_w)
            or target_w < 0.0
            or target_amp < 0
        ):
            target_w = 0.0
            target_amp = 0
            target_state = 1
        watt_caps[charger_id] = target_w
        amp_caps[charger_id] = target_amp
        state_by_id[charger_id] = target_state
    return {
        "contract": "wallbox_group_authority_caps_v1",
        "ready": ready,
        "watt_caps_by_id": watt_caps,
        "amp_caps_by_id": amp_caps,
        "state_by_id": state_by_id,
    }


def _canonical_wallbox_allocation_map(
    allocations,
    configured_group_ids,
    phase_count_by_id=None,
):
    """Bindet alle Gruppenallokationen einmalig an positive Integer-IDs.

    JSON-nahe Producer dürfen kanonische Dezimalstrings liefern. Ungültige
    Schlüssel, fremde Ladepunkte und Alias-Kollisionen bleiben dagegen ein
    Gruppenfehler; einzelne Consumer dürfen diese Mehrdeutigkeit nicht durch
    eigene int-/str-Fallbacks unterschiedlich auslegen.
    """

    if not isinstance(allocations, dict):
        raise TypeError("wallbox_group_allocations_not_mapping")
    configured = set()
    for raw_id in configured_group_ids or ():
        if isinstance(raw_id, bool):
            raise ValueError("wallbox_group_configured_id_invalid")
        try:
            charger_id = int(raw_id)
        except (TypeError, ValueError) as exc:
            raise ValueError("wallbox_group_configured_id_invalid") from exc
        if charger_id <= 0:
            raise ValueError("wallbox_group_configured_id_invalid")
        configured.add(charger_id)

    canonical = {}
    for raw_id, allocation in allocations.items():
        if isinstance(raw_id, bool):
            raise ValueError("wallbox_group_allocation_id_invalid")
        if isinstance(raw_id, int):
            charger_id = raw_id
        elif isinstance(raw_id, str):
            text_id = raw_id.strip()
            if not text_id.isdecimal() or str(int(text_id)) != text_id:
                raise ValueError("wallbox_group_allocation_id_invalid")
            charger_id = int(text_id)
        else:
            raise ValueError("wallbox_group_allocation_id_invalid")
        if charger_id <= 0 or (configured and charger_id not in configured):
            raise ValueError("wallbox_group_allocation_id_out_of_scope")
        if charger_id in canonical:
            raise ValueError("wallbox_group_allocation_id_alias_collision")
        if not isinstance(allocation, dict):
            raise TypeError("wallbox_group_allocation_slot_invalid")
        canonical[charger_id] = dict(allocation)
    phases_by_id = (
        phase_count_by_id if isinstance(phase_count_by_id, dict) else {}
    )
    for charger_id in sorted(configured.difference(canonical)):
        target_phases = max(
            0,
            int(_cfg_float(phases_by_id.get(charger_id), 0.0)),
        )
        canonical[charger_id] = {
            "target_amp": 0,
            "target_amp_per_phase": 0,
            "target_power_w": 0.0,
            "target_phases": target_phases,
            "state": 1,
        }
    return canonical


def _wallbox_manager_allocate_group_budget(
    available_w: float,
    wb_instances: list,
    raw_wb_list: list,
    min_amp: int,
    max_amp: int,
    wb_mode_map: dict,
    disabled_or_price_set: set = None,
    allocatable_by_id: dict = None,
    max_amp_by_id: dict = None,
    phase_count_by_id: dict = None,
    watts_per_amp_by_id: dict = None,
    continuation_only: bool = False,
    output_hold_only: bool = False,
) -> tuple:
    allocations = {}
    total_managed_w = float(available_w)
    continuation_slots = {}
    continuation_remaining_w = max(0.0, float(available_w or 0.0))
    disabled_or_price_set = disabled_or_price_set or set()
    allocatable_by_id = allocatable_by_id or {}
    max_amp_by_id = max_amp_by_id or {}
    phase_count_by_id = phase_count_by_id or {}

    wb_items = []
    for item in raw_wb_list:
        wb_id = item.get("id")
        if allocatable_by_id and not allocatable_by_id.get(wb_id, True):
            continue
        if normalize_wb_mode(wb_mode_map.get(wb_id, MODE_OFF)) == MODE_OFF:
            continue
        status = item.get("status", {})
        phases = phase_count_by_id.get(wb_id, 3)
        w_per_amp = float(phases * 230)
        car = status.get("car", 0)
        is_charging = bool(_wallbox_status_fresh_real_charging(status))
        wb_max_a = max_amp_by_id.get(wb_id, max_amp)
        wb_min_a = 6 if min_amp == 0 else min_amp
        wb_items.append({
            "id": wb_id,
            "status": status,
            "phases": phases,
            "w_per_amp": w_per_amp,
            "car": car,
            "is_charging": is_charging,
            "max_amp": wb_max_a,
            "min_amp": wb_min_a,
            "min_w": float(wb_min_a * w_per_amp),
        })

    target_powers = {}
    target_amps = {}
    if not output_hold_only and not continuation_only and available_w > 0.0 and wb_items:
        total_min_w = sum(wb["min_w"] for wb in wb_items)
        if available_w < total_min_w:
            rem = available_w
            sorted_wb = sorted(wb_items, key=lambda x: x["min_w"])
            for wb in sorted_wb:
                if rem >= wb["min_w"]:
                    target_powers[wb["id"]] = wb["min_w"]
                    target_amps[wb["id"]] = wb["min_amp"]
                    rem -= wb["min_w"]
                else:
                    target_powers[wb["id"]] = 0.0
                    target_amps[wb["id"]] = 0
        else:
            # First assign min_amp to all eligible wallboxes
            for wb in wb_items:
                target_amps[wb["id"]] = wb["min_amp"]
                target_powers[wb["id"]] = wb["min_w"]
            rem = available_w - total_min_w

            # Distribute remaining budget up to max_amp, prioritizing 1-phase wallboxes
            sorted_wb_items = sorted(wb_items, key=lambda x: (x["phases"], x["id"]))
            for wb in sorted_wb_items:
                wb_id = wb["id"]
                w_pa = wb["w_per_amp"]
                while target_amps[wb_id] < wb["max_amp"] and rem >= w_pa:
                    target_amps[wb_id] += 1
                    target_powers[wb_id] += w_pa
                    rem -= w_pa

    for wb in wb_items:
        wb_id = wb["id"]
        status = wb["status"]
        phases = wb["phases"]
        is_charging = wb["is_charging"]

        if output_hold_only:
            target_amp = 0
            alloc_w = 0.0
            allocated = False
            reason = "output_hold_only"
        elif continuation_only:
            continuation_authorized = bool(
                wb_id in disabled_or_price_set or is_charging
            )
            if continuation_authorized and continuation_remaining_w >= wb["min_w"]:
                target_amp = 6
                alloc_w = 6.0 * wb["w_per_amp"]
                allocated = True
                continuation_remaining_w -= alloc_w
                reason = (
                    "explicit_price_owner"
                    if wb_id in disabled_or_price_set
                    else "fresh_running_continuation"
                )
            else:
                target_amp = 0
                alloc_w = 0.0
                allocated = False
                reason = (
                    "stale_budget_group_cap_exhausted"
                    if continuation_authorized
                    else "stale_budget_cannot_start"
                )
        else:
            if available_w <= 0.0:
                target_amp = 0
                alloc_w = 0.0
                allocated = False
                reason = "zero_available_budget"
            else:
                target_amp = target_amps.get(wb_id, 0)
                alloc_w = target_powers.get(wb_id, float(target_amp * wb["w_per_amp"]))
                allocated = alloc_w > 0
                reason = "normal_allocation"

        allocations[wb_id] = {
            "target_amp": target_amp,
            "target_amp_per_phase": target_amp,
            "target_phases": phases,
            "allocated": allocated,
            "allocated_w": alloc_w,
            "target_power_w": alloc_w,
        }

        if continuation_only:
            continuation_slots[wb_id] = {
                "reason": reason,
                "allowed": allocated,
                "target_amp": target_amp,
                "fresh_running_readback": bool(
                    reason == "fresh_running_continuation"
                ),
                "explicit_price_owner": bool(
                    reason == "explicit_price_owner"
                ),
            }

    ledger = {
        "continuation_slots": continuation_slots,
        "gross_group_budget_w": float(available_w),
        "managed_budget_w": float(available_w),
    }
    return allocations, total_managed_w, ledger
