def _valid_phase_count(value, default=0):
    return wallbox_decision.valid_phase_count(value, default)

def _truthy_config(value):
    return str(value).strip().lower() in ("1", "true", "yes", "on", "ja")

def _falsey_config(value):
    return str(value).strip().lower() in ("0", "false", "no", "off", "nein")


def _wallbox_type_explicitly_disabled(config, key):
    """Nur ausdrückliche Aus-Aliasse sind ein dauerhaftes Nutzer-Veto.

    Fehlende und historisch leere Typ-Keys bleiben Legacy-ambig. Sie dürfen
    WB2 aber nur über den frischen, eindeutigen openWB-Discovery-Vertrag
    aktivieren; alte IP-/Topic-Werte allein reichen dafür nicht aus.
    """
    if not isinstance(config, dict) or key not in config:
        return False
    raw = str(config.get(key) or "").strip().lower()
    return raw in DISABLED_WALLBOX_TYPES


def _openwb_controller_identity(ip):
    host = str(ip or "").strip().lower()
    if not host:
        return ""
    return "sha256:" + hashlib.sha256(
        ("openwb-controller|" + host).encode("utf-8")
    ).hexdigest()


def _openwb_configured_cp_id(config, wb_id):
    """Liest nur bestehende CP-Konfigurationspfade mit Slot-Vorrang."""

    cfg = config if isinstance(config, dict) else {}
    try:
        charger_id = int(wb_id or 1)
    except (TypeError, ValueError):
        charger_id = 1
    prefix = str(cfg.get(f"wb{charger_id}_topic_prefix", "") or "").strip()
    if prefix:
        match = re.search(r"(?:chargepoint|lp)[/\\](\d+)", prefix)
        if match:
            cp_id = int(match.group(1))
            if cp_id > 0:
                return cp_id
    if charger_id == 1:
        raw = str(cfg.get("wb_native_cp_id", "") or "").strip()
        if raw.isdigit() and int(raw) > 0:
            return int(raw)
    return 0


def _unique_positive_openwb_chargepoints(discovered):
    """Normalisiert ausschließlich eindeutige positive SimpleAPI-CP-IDs."""

    result = []
    seen = set()
    for item in discovered if isinstance(discovered, (list, tuple)) else ():
        if not isinstance(item, dict):
            continue
        try:
            cp_id = int(item.get("id", 0) or 0)
        except (TypeError, ValueError):
            continue
        if cp_id <= 0 or cp_id in seen:
            continue
        seen.add(cp_id)
        normalized = dict(item)
        normalized["id"] = cp_id
        result.append(normalized)
    result.sort(key=lambda entry: entry["id"])
    return result


_PERSISTENT_WALLBOX_STRUCTURE_KEYS = (
    "wb_native_type",
    "wb_native_ip",
    "wb_native_type2",
    "wb_native_ip2",
    "wb_MQTT_Topic",
    "wb_native_cp_id",
    "wb1_topic_prefix",
    "wb2_topic_prefix",
)


def _persistent_wallbox_structure_snapshot(config):
    """Bindet ausschließlich persistente Strukturwerte, nie Runtime-Discovery."""

    cfg = config if isinstance(config, dict) else {}
    return {
        key: str(cfg.get(key, "") or "")
        for key in _PERSISTENT_WALLBOX_STRUCTURE_KEYS
    }


def _runtime_wallbox_discovery_overlay(runtime_config, persistent_config):
    """Bewahrt einen rein ephemeren Discovery-Overlay bei Parameter-Reloads."""

    runtime = runtime_config if isinstance(runtime_config, dict) else {}
    persistent = persistent_config if isinstance(persistent_config, dict) else {}
    contract = runtime.get("_wb2_openwb_discovery_contract")
    if not isinstance(contract, dict):
        return {}
    overlay = {"_wb2_openwb_discovery_contract": dict(contract)}
    for key in (
        "wb_native_type",
        "wb_native_ip",
        "wb1_topic_prefix",
        "wb_native_type2",
        "wb_native_ip2",
        "wb2_topic_prefix",
    ):
        if runtime.get(key) != persistent.get(key):
            overlay[key] = runtime.get(key)
    return overlay


def _bind_legacy_openwb_dual_discovery(config, discovered, now_ts=None):
    """Bindet ein Legacy-WB2 nur im RAM an zwei frisch entdeckte CPs.

    Die Funktion persistiert nichts. Ein expliziter WB2-Typ bleibt
    unverändert; ein Aus-Alias ist ein hartes Veto. Alte IP-/Topic-Reste sind
    kein Discovery-Beleg.
    """

    if not isinstance(config, dict):
        return False
    config.pop("_wb2_openwb_discovery_contract", None)
    if str(config.get("wb_native_type", "") or "").strip().lower() != "openwb":
        return False
    if _wallbox_type_explicitly_disabled(config, "wb_native_type2"):
        return False
    if str(config.get("wb_native_type2", "") or "").strip():
        return False

    primary_ip = str(config.get("wb_native_ip", "") or "").strip()
    legacy_ip2 = str(config.get("wb_native_ip2", "") or "").strip()
    if not primary_ip or (legacy_ip2 and legacy_ip2 != primary_ip):
        return False
    chargepoints = _unique_positive_openwb_chargepoints(discovered)
    if len(chargepoints) != 2:
        return False
    by_id = {entry["id"]: entry for entry in chargepoints}
    cp1 = _openwb_configured_cp_id(config, 1)
    if cp1:
        if cp1 not in by_id:
            return False
    else:
        cp1 = chargepoints[0]["id"]
        config["wb1_topic_prefix"] = f"openWB/simpleAPI/chargepoint/{cp1}"
    cp2_entry = next((entry for entry in chargepoints if entry["id"] != cp1), None)
    if cp2_entry is None:
        return False

    cp2 = cp2_entry["id"]
    detected_at = int(float(now_ts if now_ts is not None else time.time()))
    config["wb_native_type2"] = "openwb"
    config["wb_native_ip2"] = primary_ip
    config["wb2_topic_prefix"] = f"openWB/simpleAPI/chargepoint/{cp2}"
    config["_wb2_openwb_discovery_contract"] = {
        "schema_version": "openwb_chargepoint_discovery_v1",
        "valid": True,
        "source": "manager_simpleapi_direct",
        "detected_at": detected_at,
        "controller_identity": _openwb_controller_identity(primary_ip),
        "cp_id": cp2,
        "peer_cp_id": cp1,
        "status_confirmed": False,
        "status_confirmed_ts": 0,
    }
    return True


def _refresh_wallbox_physical_output_contracts(chargers):
    """Vergibt pro physischem openWB-Ausgang höchstens einen Schreiber."""

    prior_by_controller = {}
    contracts = {}
    ordered = sorted(
        (item for item in (chargers or []) if isinstance(item, dict)),
        key=lambda item: int(item.get("id", 0) or 0),
    )
    for c_data in ordered:
        charger = c_data.get("charger")
        if charger is None or charger.__class__.__name__ != "OpenWBCharger":
            c_data.pop("_physical_output_contract", None)
            c_data.pop("_physical_output_blocked", None)
            c_data.pop("_physical_output_block_reason", None)
            continue
        wb_id = int(c_data.get("id", 0) or 0)
        identity = (
            charger.physical_output_identity_contract()
            if hasattr(charger, "physical_output_identity_contract")
            else {}
        )
        identity = identity if isinstance(identity, dict) else {}
        controller_identity = str(identity.get("controller_identity") or "")
        endpoint_kind = str(identity.get("endpoint_kind") or "")
        output_identity = str(identity.get("identity") or "")
        discovery = getattr(charger, "state", {}).get(
            "chargepoint_discovery_contract", {}
        )
        discovery = discovery if isinstance(discovery, dict) else {}
        auto_bound = bool(identity.get("auto_discovery_bound") is True)
        blockers = []
        if identity.get("valid") is not True:
            blockers.append("physical_output_identity_unproven")
        if auto_bound and not (
            identity.get("valid") is True
            and identity.get("auto_discovery_status_confirmed") is True
            and discovery.get("status_confirmed") is True
        ):
            blockers.append("auto_discovery_status_not_confirmed")
        if auto_bound and str(
            discovery.get("controller_identity") or ""
        ) != controller_identity:
            blockers.append("auto_discovery_controller_binding_invalid")

        prior = prior_by_controller.get(controller_identity) if controller_identity else None
        if prior is not None:
            prior_identity = prior.get("identity", {})
            prior_kind = str(prior_identity.get("endpoint_kind") or "")
            prior_output_identity = str(prior_identity.get("identity") or "")
            if not (
                identity.get("valid") is True
                and prior_identity.get("valid") is True
                and output_identity
                and prior_output_identity
            ):
                blockers.append("physical_output_identity_unproven")
            elif endpoint_kind != prior_kind:
                blockers.append("same_controller_cross_surface_unproven")
            elif output_identity == prior_output_identity:
                blockers.append("duplicate_physical_output_identity")
            if auto_bound:
                try:
                    peer_cp = int(discovery.get("peer_cp_id", 0) or 0)
                    current_cp = int(identity.get("cp_id", 0) or 0)
                    prior_cp = int(prior_identity.get("cp_id", 0) or 0)
                except (TypeError, ValueError):
                    peer_cp = current_cp = prior_cp = 0
                if not (
                    peer_cp > 0
                    and current_cp > 0
                    and prior_cp == peer_cp
                    and current_cp != prior_cp
                ):
                    blockers.append("auto_discovery_peer_binding_invalid")
        elif auto_bound:
            blockers.append("auto_discovery_peer_output_missing")

        # Der zuerst konfigurierte Ladepunkt behält deterministisch die
        # Autorität. Jede spätere unklare oder kollidierende Instanz ist nur
        # Beobachter und bleibt auch an der tiefsten Treiber-I/O-Kante gesperrt.
        blocked = bool(blockers)
        reason = blockers[0] if blockers else ""
        contract = {
            "schema_version": "wallbox_physical_output_binding_v1",
            "valid": bool(identity.get("valid") is True),
            "wb_id": wb_id,
            "output_allowed": not blocked,
            "observe_only": blocked,
            "blockers": blockers,
            "reason": reason or "unique_physical_output",
            "identity": output_identity,
            "controller_identity": controller_identity,
            "endpoint_kind": endpoint_kind,
            "cp_id": identity.get("cp_id", 0),
            "identity_contract": dict(identity),
        }
        c_data["_physical_output_contract"] = contract
        c_data["_physical_output_blocked"] = blocked
        c_data["_physical_output_block_reason"] = reason
        charger._physical_output_blocked = blocked
        charger._physical_output_block_reason = reason
        if isinstance(getattr(charger, "state", None), dict):
            charger.state["physical_output_identity"] = dict(identity)
            charger.state["physical_output_contract"] = dict(contract)
            charger.state["physical_output_blocked"] = blocked
            charger.state["physical_output_block_reason"] = reason
        contracts[wb_id] = contract
        if controller_identity and controller_identity not in prior_by_controller:
            prior_by_controller[controller_identity] = {
                "wb_id": wb_id,
                "identity": identity,
            }
    return contracts


def _wallbox_runtime_topology_contract(
    config,
    chargers,
    statuses,
    wb_modes,
    manual_pause=None,
    now_ts=None,
):
    """Attestiert die aktuelle Manager-Topologie für interne Verbraucher."""

    cfg = config if isinstance(config, dict) else {}
    pause = manual_pause if isinstance(manual_pause, dict) else {}
    modes = wb_modes if isinstance(wb_modes, dict) else {}
    now_value = int(float(time.time() if now_ts is None else now_ts))
    boxes = {
        int(item.get("id", 0) or 0): item
        for item in (chargers or [])
        if isinstance(item, dict) and int(item.get("id", 0) or 0) in (1, 2)
    }
    status_by_id = {
        int(item.get("id", 0) or 0): item.get("status")
        for item in (statuses or [])
        if isinstance(item, dict) and int(item.get("id", 0) or 0) in (1, 2)
    }
    configured_ids = sorted(boxes)
    active_ids = sorted(
        wb_id
        for wb_id, box in boxes.items()
        if normalize_wb_mode(modes.get(wb_id, 0)) != MODE_OFF
        and not bool(pause.get(wb_id, False))
        and not bool(box.get("_physical_output_blocked", False))
    )
    result = {
        "schema_version": "wallbox_runtime_topology_v1",
        "valid": True,
        "manager_ts": now_value,
        "configured_wb_ids": configured_ids,
        "active_mode_wb_ids": active_ids,
    }

    discovery = cfg.get("_wb2_openwb_discovery_contract")
    wb1_box = boxes.get(1, {})
    wb2_box = boxes.get(2, {})
    wb1_output = wb1_box.get("_physical_output_contract")
    wb2_output = wb2_box.get("_physical_output_contract")
    wb1_status = status_by_id.get(1)
    wb2_status = status_by_id.get(2)
    if isinstance(discovery, dict):
        wb1_output = wb1_output if isinstance(wb1_output, dict) else {}
        wb2_output = wb2_output if isinstance(wb2_output, dict) else {}
        wb1_status = wb1_status if isinstance(wb1_status, dict) else {}
        wb2_status = wb2_status if isinstance(wb2_status, dict) else {}
        try:
            cp_id = int(discovery.get("cp_id", 0) or 0)
            peer_cp_id = int(discovery.get("peer_cp_id", 0) or 0)
            detected_at = float(discovery.get("detected_at", 0.0) or 0.0)
            confirmed_ts = float(
                discovery.get("status_confirmed_ts", 0.0) or 0.0
            )
        except (TypeError, ValueError):
            cp_id = peer_cp_id = 0
            detected_at = confirmed_ts = 0.0
        wb1_identity = str(wb1_output.get("identity") or "")
        wb2_identity = str(wb2_output.get("identity") or "")
        wb1_controller = str(wb1_output.get("controller_identity") or "")
        wb2_controller = str(wb2_output.get("controller_identity") or "")
        wb1_kind = str(wb1_output.get("endpoint_kind") or "")
        wb2_kind = str(wb2_output.get("endpoint_kind") or "")
        runtime_valid = bool(
            discovery.get("valid") is True
            and discovery.get("status_confirmed") is True
            and cp_id > 0
            and peer_cp_id > 0
            and cp_id != peer_cp_id
            and detected_at > 0.0
            and confirmed_ts >= detected_at
            and wb1_status.get("driver_status_valid") is True
            and wb1_status.get("driver_status_stale") is False
            and wb2_status.get("driver_status_valid") is True
            and wb2_status.get("driver_status_stale") is False
            and wb1_output.get("valid") is True
            and wb1_output.get("output_allowed") is True
            and wb2_output.get("valid") is True
            and wb2_output.get("output_allowed") is True
            and int(wb1_output.get("cp_id", 0) or 0) == peer_cp_id
            and int(wb2_output.get("cp_id", 0) or 0) == cp_id
            and wb1_identity
            and wb2_identity
            and wb1_identity != wb2_identity
            and wb1_controller
            and wb1_controller == wb2_controller
            and wb1_kind
            and wb1_kind == wb2_kind
        )
        result["runtime_wb2"] = {
            "schema_version": "wallbox_runtime_wb2_v1",
            "valid": runtime_valid,
            "source": str(discovery.get("source") or ""),
            "detected_at": detected_at,
            "status_confirmed": bool(
                discovery.get("status_confirmed") is True
            ),
            "status_confirmed_ts": confirmed_ts,
            "controller_identity": wb2_controller,
            "endpoint_kind": wb2_kind,
            "cp_id": cp_id,
            "peer_cp_id": peer_cp_id,
            "physical_output_identity": wb2_identity,
            "peer_physical_output_identity": wb1_identity,
            "physical_output_allowed": bool(
                wb2_output.get("output_allowed") is True
            ),
        }
    return result


def _deduplicated_measured_wallbox_power(statuses):
    """Summiert Messleistung; exakt identische physische Ausgänge nur einmal."""

    unbound_power_w = 0.0
    power_by_identity = {}
    charging_active = False
    for item in statuses or []:
        if not isinstance(item, dict):
            continue
        status = item.get("status")
        if not _wb_status_real_charging(status):
            continue
        charging_active = True
        power_w = max(0.0, float(_wb_status_real_power(status) or 0.0))
        output = (
            status.get("physical_output_contract")
            if isinstance(status, dict)
            else None
        )
        if not isinstance(output, dict) or output.get("valid") is not True:
            unbound_power_w += power_w
            continue
        identity = str(output.get("identity") or "")
        controller = str(output.get("controller_identity") or "")
        endpoint_kind = str(output.get("endpoint_kind") or "")
        if not identity or not controller or not endpoint_kind:
            unbound_power_w += power_w
            continue
        key = (controller, endpoint_kind, identity)
        power_by_identity[key] = max(power_by_identity.get(key, 0.0), power_w)
    return unbound_power_w + sum(power_by_identity.values()), charging_active


def _openwb_phase_switch_capability(charger_class_name, status=None, config=None):
    """Return whether Python may send 1p/3p commands to this wallbox.

    openWB Pro exposes phase switching via connect.php and is an EVSE-like
    actuator. A normal openWB is a full energy manager; E3DC-Control only
    sends Secondary current + heartbeat and never internal phase commands.
    """
    return wallbox_decision.openwb_phase_switch_capability(charger_class_name, status, config)


def _wallbox_phase_switch_capability(charger_class_name, status=None, config=None):
    """Return the diagnostic phase switching surface for any wallbox type."""

    return wallbox_decision.wallbox_phase_switch_capability(charger_class_name, status, config)


def _apply_phase_contract_to_status(status, contract):
    if status is None or not isinstance(contract, dict):
        return status
    status["phase_contract"] = contract
    status["phase_actual_phases"] = int(contract.get("actual_phases", 0) or 0)
    status["phase_actual_source"] = str(contract.get("actual_source", "") or "")
    status["phase_effective_phases"] = int(contract.get("effective_phases", 0) or 0)
    status["phase_effective_source"] = str(contract.get("effective_source", "") or "")
    status["phase_cable_phases"] = int(contract.get("cable_phases", 0) or 0)
    status["phase_vehicle_max_phases"] = int(contract.get("vehicle_max_phases", 0) or 0)
    status["phase_wallbox_phases"] = int(contract.get("wallbox_phases", 0) or 0)
    status["phase_can_switch"] = bool(contract.get("can_switch_phases", False))
    status["phase_switch_capability"] = str(contract.get("phase_switch_capability", status.get("phase_switch_capability", "")) or "")
    status["phase_switch_source"] = str(contract.get("phase_switch_source", status.get("phase_switch_source", "")) or "")
    status["api_surface"] = str(contract.get("api_surface", status.get("api_surface", "")) or "")
    status["can_switch_phases"] = bool(contract.get("can_switch_phases", status.get("can_switch_phases", False)))
    return status


def _wallbox_charge_observation_contract(status=None, c_data=None, *, now_ts=None):
    previous = {}
    if isinstance(c_data, dict):
        previous = c_data.get("_charge_energy_sample")
        if not isinstance(previous, dict):
            previous = {}
    contract = wallbox_decision.charge_observation_contract(
        status,
        previous=previous,
        now_ts=time.time() if now_ts is None else now_ts,
    )
    if isinstance(c_data, dict):
        sample = contract.get("energy_sample")
        if isinstance(sample, dict):
            c_data["_charge_energy_sample"] = sample
        c_data["_charge_contract"] = contract
    return contract


def _apply_charge_contract_to_status(status, contract):
    if status is None or not isinstance(contract, dict):
        return status
    status["charge_contract"] = contract
    status["charge_truth"] = str(contract.get("truth", "not_charging") or "not_charging")
    status["charge_is_charging"] = bool(contract.get("is_charging", False))
    status["charge_counts_as_real"] = bool(contract.get("counts_as_real_charge", False))
    status["charge_confidence"] = str(contract.get("confidence", "") or "")
    status["charge_source"] = str(contract.get("source", "") or "")
    status["charge_power_w"] = round(float(contract.get("power_w", 0.0) or 0.0), 1)
    status["charge_raw_power_w"] = round(float(contract.get("raw_power_w", 0.0) or 0.0), 1)
    status["phantom_power_w"] = round(float(contract.get("phantom_power_w", 0.0) or 0.0), 1)
    status["charge_energy_increasing"] = bool(contract.get("energy_increasing", False))
    status["charge_energy_delta_wh"] = round(float(contract.get("energy_delta_wh", 0.0) or 0.0), 3)
    status["charge_energy_source"] = str(contract.get("energy_source", "") or "")
    return status


def _wallbox_charge_end_release_token(config, charger_id, public_mode=None):
    cfg = config or {}
    try:
        cid = int(charger_id or 1)
    except Exception:
        cid = 1
    def _number(value):
        if value is None or str(value).strip() == "":
            return None
        try:
            number = float(value)
        except (TypeError, ValueError):
            return str(value).strip()
        if not math.isfinite(number):
            return str(value).strip()
        if abs(number - round(number)) < 1e-9:
            return int(round(number))
        return round(number, 6)

    effective_global_max_amp = _amp_limit(
        cfg.get("wbmaxladestrom", cfg.get("wb_max_amp", 16)),
        16,
    )
    effective_max_amp = _charger_max_amp(
        cfg,
        cid,
        effective_global_max_amp,
    )
    target_unit = str(
        cfg.get(f"wb{cid}_target_unit", cfg.get("car_target_unit", "soc"))
        or "soc"
    ).strip().lower()
    if target_unit not in {"soc", "kwh"}:
        target_unit = "soc"
    _departure_hour, _departure_minute, effective_departure_time = _parse_hhmm(
        cfg.get(
            f"wb{cid}_battery_departure_time",
            cfg.get("wb_battery_departure_time", BATTERY_DEPARTURE_DEFAULT_TIME),
        )
    )

    fields = {
        "mode": normalize_wb_mode(public_mode if public_mode is not None else cfg.get(f"wb{cid}_mode", 0)),
        "global_max_amp": _number(effective_global_max_amp),
        "max_amp": _number(effective_max_amp),
        "target_soc": _number(cfg.get(f"wb{cid}_target_soc", cfg.get("car_target_soc", ""))),
        "target_unit": target_unit,
        "target_kwh": _number(cfg.get(f"wb{cid}_target_kwh", cfg.get("car_target_kwh", 0.0)) or 0.0),
        "max_soc": _number(cfg.get(f"wb{cid}_max_soc_si", cfg.get("car_max_soc_si", ""))),
        "departure_target_soc": _number(
            cfg.get(f"wb{cid}_battery_departure_target_soc", cfg.get("wb_battery_departure_target_soc", ""))
        ),
        "departure_time": effective_departure_time,
        "charge_power": _number(cfg.get(f"wb{cid}_charge_power", cfg.get("car_charge_power", ""))),
        "capacity": _number(cfg.get(f"wb{cid}_capacity", cfg.get("car_capacity", ""))),
        "car_id": str(cfg.get(f"wb{cid}_car_id", "")).strip(),
    }
    return json.dumps(fields, sort_keys=True, separators=(",", ":"))


def _detect_wallbox_charge_end_user_release(c_data, config, charger_id, public_mode=None):
    if not isinstance(c_data, dict):
        return ""
    token = _wallbox_charge_end_release_token(config, charger_id, public_mode)
    previous = str(c_data.get("_charge_end_release_token") or "")
    c_data["_charge_end_release_token"] = token
    if previous and previous != token and bool(c_data.get("_bev_full_blocked", False)):
        return "wallbox_php_limit_or_profile_change"
    return ""


def _apply_charge_end_contract_to_status(status, contract):
    if status is None or not isinstance(contract, dict):
        return status
    status["charge_end_contract"] = contract
    status["charge_end_latched"] = bool(contract.get("latched", False))
    status["charge_end_action"] = str(contract.get("action", "") or "")
    status["charge_end_reason"] = str(contract.get("reason", "") or "")
    status["charge_end_exception"] = str(contract.get("exception", "") or "")
    status["charge_end_start_blocked"] = bool(contract.get("start_blocked", False))
    return status


def _clear_wallbox_charge_end_latch(c_data, reason=""):
    if not isinstance(c_data, dict):
        return
    floor_anchor_active = _native_e3dc_floor_zero_anchor_active(c_data)
    c_data["_bev_full_blocked"] = False
    c_data["_bev_full_block_reason"] = ""
    c_data.pop("_charge_end_latched_plug_session_id", None)
    c_data.pop("_charge_end_latched_ts", None)
    c_data["_charge_end_release_reason"] = str(reason or "")
    c_data["_charge_end_release_ts"] = time.time()
    if not floor_anchor_active:
        c_data["abort_count"] = 0
        c_data["abort_cooldown_ts"] = 0.0
    c_data["_openwb_start_reject_soft_until"] = 0.0
    if floor_anchor_active:
        _record_native_e3dc_floor_hardstop_not_yet_effective(
            c_data,
            source="charge_end_latch_release_blocked",
        )
    else:
        c_data["_wb_stop_sent_active"] = False
    for key in _CHARGE_END_RUNTIME_EPHEMERAL_KEYS:
        c_data.pop(key, None)


_CHARGE_END_TERMINAL_REASONS = frozenset({
    "vehicle_charge_ended",
    "start_rejected",
    "target_soc_reached",
    "target_kwh_reached",
    "battery_departure_target_reached",
})

_CHARGE_END_RUNTIME_EPHEMERAL_KEYS = (
    "_charge_end_persist_receipt",
    "_charge_end_persist_failed",
    "_charge_end_persisted_before_stop_ts",
    "_charge_end_last_stop_sample_ts",
    "_charge_end_last_output_attempt_sample_ts",
    "_charge_end_last_stop_attempt_ts",
    "_charge_end_stop_retry_count",
    "_charge_end_stop_retry_exhausted",
    "_charge_end_stop_recovery_hold",
    "_charge_end_stop_output_not_issued",
    "_charge_end_stop_episode_completed_ts",
    "_native_charge_end_stop_contract",
)


def _wallbox_disconnect_runtime_reset_authorized(c_data, status):
    """Bestätigt eine physische Trennung, bevor Laufzeitbelege verfallen."""

    data = c_data if isinstance(c_data, dict) else {}
    st = status if isinstance(status, dict) else {}
    fresh_disconnected = bool(
        st
        and st.get("driver_status_valid") is True
        and not bool(st.get("driver_status_stale", False))
        and not bool(st.get("driver_status_glitch", False))
        and not _wb_status_connected(st)
    )
    if not fresh_disconnected:
        return False
    if openwb_pro_session.is_openwb_pro_charger(data.get("charger")):
        edge = data.get("_openwb_pro_start_session_edge_contract")
        edge = edge if isinstance(edge, dict) else {}
        return bool(
            edge.get("disconnect_confirmed", False)
            and edge.get("persisted", False)
        )
    return data.get("_wallbox_disconnect_confirmed") is True


def _reset_wallbox_confirmed_disconnect_runtime(c_data):
    """Setzt nur fahrzeugbezogene Laufzeitbelege einer bestätigten Trennung."""

    data = c_data if isinstance(c_data, dict) else {}
    data["is_charging"] = False
    data["current_set_amp"] = 0
    data["_pv_mode_active"] = False
    data["_session_1p_only"] = False
    data["_phase_change_seen_session"] = False
    data["_real_charge_since"] = 0.0
    data["_had_real_charge_in_session"] = False
    data["_aha_real_charge_confirmed"] = False
    data["_aha_real_charge_confirmed_since"] = 0.0
    data["_openwb_zero_budget_since"] = 0.0
    data["_openwb_start_retry_count"] = 0


def _wallbox_stop_readback_confirmed(status):
    """Bestätigt einen Ziel-Stop ausschließlich aus frischer Hardwarephysik."""

    st = status if isinstance(status, dict) else {}
    if not (
        st
        and st.get("driver_status_valid") is True
        and not bool(st.get("driver_status_stale", False))
        and not bool(st.get("driver_status_glitch", False))
    ):
        return False
    offered_amp = max(
        _cfg_float(st.get("amp"), 0.0),
        _cfg_float(st.get("offered_current_raw"), 0.0),
        _cfg_float(st.get("offered_current"), 0.0),
        _cfg_float(st.get("evse_current"), 0.0),
    )
    driver_variant = str(st.get("driver_variant") or "").strip().lower()
    native_e3dc = bool(
        driver_variant.startswith("e3dc")
        or str(st.get("driver_status_source") or "").startswith("rscp_")
        or "alg_seen" in st
    )
    return bool(
        not _wb_status_real_charging(st)
        and _wb_status_real_power(st) <= 50.0
        # E3DC meldet auch im Stillstand einen statischen 6-A-Rahmen. Der
        # frische ALG-/Leistungszustand ist dort der Stop-Readback; die 6 A
        # sind kein fortgesetztes Ladeangebot.
        and (native_e3dc or offered_amp <= 0.2)
    )


def _wallbox_stop_readback_state(status):
    """Typisiert einen Stop-Readback als ``active``, ``stopped`` oder ``unknown``."""

    st = status if isinstance(status, dict) else {}
    if not (
        st
        and st.get("driver_status_valid") is True
        and not bool(st.get("driver_status_stale", False))
        and not bool(st.get("driver_status_glitch", False))
    ):
        return "unknown"
    if _wb_status_real_charging(st) or _wb_status_real_power(st) > 250.0:
        return "active"
    if _wallbox_stop_readback_confirmed(st):
        return "stopped"
    offered_amp = max(
        _cfg_float(st.get("amp"), 0.0),
        _cfg_float(st.get("offered_current_raw"), 0.0),
        _cfg_float(st.get("offered_current"), 0.0),
        _cfg_float(st.get("evse_current"), 0.0),
    )
    if offered_amp > 0.2:
        return "active"
    return "unknown"


def _charge_end_persist_identity(c_data, reason):
    data = c_data if isinstance(c_data, dict) else {}
    return {
        "reason": str(reason or ""),
        "latched_ts": float(data.get("_charge_end_latched_ts", 0.0) or 0.0),
        "plug_session_id": str(
            data.get("_charge_end_latched_plug_session_id") or ""
        ),
        "release_token": str(data.get("_charge_end_release_token") or ""),
    }


def _ensure_wallbox_latch_persisted(chargers, c_data, reason):
    """Beweist vor jedem Stopversuch denselben crashfesten Latch."""

    data = c_data if isinstance(c_data, dict) else {}
    reason_code = str(reason or "")
    if not (
        data.get("_bev_full_blocked") is True
        and str(data.get("_bev_full_block_reason") or "") == reason_code
    ):
        data["_charge_end_persist_failed"] = "latch_identity_mismatch"
        return False
    identity = _charge_end_persist_identity(data, reason_code)
    receipt = data.get("_charge_end_persist_receipt")
    if (
        isinstance(receipt, dict)
        and receipt.get("identity") == identity
        and not data.get("_charge_end_persist_failed")
    ):
        return True
    if not _save_wallbox_abort_state(chargers):
        data["_charge_end_persist_failed"] = "abort_state_write_failed"
        return False
    persisted_ts = time.time()
    data.pop("_charge_end_persist_failed", None)
    data["_charge_end_persisted_before_stop_ts"] = persisted_ts
    data["_charge_end_persist_receipt"] = {
        "contract": "wallbox_charge_end_persist_receipt_v1",
        "identity": identity,
        "persisted_ts": persisted_ts,
    }
    return True


def _enforce_wallbox_latched_stop(
    chargers,
    c_data,
    status,
    *,
    c_id,
    reason,
    stop_sender=None,
    now_ts=None,
):
    """Setzt einen gespeicherten Latch nur gegen frischen aktiven Readback durch."""

    data = c_data if isinstance(c_data, dict) else {}
    now_value = float(now_ts if now_ts is not None else time.time())
    result = {
        "persisted": False,
        "readback_state": _wallbox_stop_readback_state(status),
        "stop_attempted": False,
        "stop_handled": False,
        "retry_blocked": "",
    }
    if not _ensure_wallbox_latch_persisted(chargers, data, reason):
        result["retry_blocked"] = "latch_not_persisted"
        return result
    result["persisted"] = True
    native_toggle_driver = bool(
        e3dc_session.is_e3dc_native_charger(data.get("charger"))
    )
    native_stop_contract = data.get("_native_charge_end_stop_contract")
    native_stop_contract = (
        native_stop_contract
        if isinstance(native_stop_contract, dict)
        and native_stop_contract.get("contract")
        == "wallbox_native_stop_edge_wal_v1"
        else {}
    )
    st = status if isinstance(status, dict) else {}
    sample_ts = _cfg_float(st.get("driver_status_last_sample_ts"), 0.0)
    if result["readback_state"] == "stopped":
        if native_stop_contract:
            native_readback_barrier_ts = max(
                _cfg_float(native_stop_contract.get("created_ts"), 0.0),
                _cfg_float(native_stop_contract.get("wire_receipt_ts"), 0.0),
            )
            native_readback_time_valid = bool(
                math.isfinite(sample_ts)
                and sample_ts > 0.0
                and sample_ts <= now_value + 2.0
                and now_value - sample_ts <= 15.0
                and sample_ts > native_readback_barrier_ts
            )
            if not native_readback_time_valid:
                data["_charge_end_stop_recovery_hold"] = {
                    "contract": "wallbox_charge_end_stop_recovery_v1",
                    "reason": str(reason or "bev_full_blocked"),
                    "blocker": "native_stop_readback_not_after_edge",
                    "sample_ts": sample_ts,
                    "barrier_ts": native_readback_barrier_ts,
                }
                result["retry_blocked"] = "native_stop_readback_not_after_edge"
                return result
        result["stop_handled"] = True
        data["_wb_stop_sent_active"] = True
        data["_charge_end_stop_episode_completed_ts"] = now_value
        native_completion_persist_failed = False
        if native_stop_contract:
            previous_native_contract = dict(native_stop_contract)
            data.pop("_native_charge_end_stop_contract", None)
            if not _save_wallbox_abort_state(chargers):
                data["_native_charge_end_stop_contract"] = previous_native_contract
                native_completion_persist_failed = True
                result["retry_blocked"] = "native_stop_completion_persist_failed"
        for key in (
            "_charge_end_last_stop_sample_ts",
            "_charge_end_last_output_attempt_sample_ts",
            "_charge_end_last_stop_attempt_ts",
            "_charge_end_stop_retry_count",
            "_charge_end_stop_retry_exhausted",
            "_charge_end_stop_recovery_hold",
            "_charge_end_stop_output_not_issued",
        ):
            data.pop(key, None)
        if native_completion_persist_failed:
            data["_charge_end_stop_recovery_hold"] = {
                "contract": "wallbox_charge_end_stop_recovery_v1",
                "reason": str(reason or "bev_full_blocked"),
                "blocker": "native_stop_completion_persist_failed",
            }
        return result
    if result["readback_state"] != "active":
        result["retry_blocked"] = "readback_unknown"
        return result

    if (
        sample_ts <= 0.0
        or sample_ts > now_value + 2.0
        or now_value - sample_ts > 15.0
    ):
        result["retry_blocked"] = "readback_time_invalid"
        return result
    if native_toggle_driver and native_stop_contract:
        data["_charge_end_stop_recovery_hold"] = {
            "contract": "wallbox_charge_end_stop_recovery_v1",
            "reason": str(reason or "bev_full_blocked"),
            "blocker": "native_stop_edge_awaiting_readback",
            "native_state": str(native_stop_contract.get("state") or "pending"),
            "sample_ts": sample_ts,
        }
        result["retry_blocked"] = "native_stop_edge_awaiting_readback"
        return result
    last_sample_ts = _cfg_float(data.get("_charge_end_last_stop_sample_ts"), 0.0)
    last_attempt_sample_ts = _cfg_float(
        data.get("_charge_end_last_output_attempt_sample_ts"),
        0.0,
    )
    last_attempt_ts = _cfg_float(data.get("_charge_end_last_stop_attempt_ts"), 0.0)
    retry_count = max(0, int(data.get("_charge_end_stop_retry_count", 0) or 0))
    if sample_ts <= max(last_sample_ts, last_attempt_sample_ts):
        result["retry_blocked"] = "readback_not_newer"
        return result
    if last_attempt_ts > 0.0 and sample_ts <= last_attempt_ts:
        result["retry_blocked"] = "readback_not_after_stop"
        return result
    if last_attempt_ts > 0.0 and now_value - last_attempt_ts < 10.0:
        result["retry_blocked"] = "retry_min_interval"
        return result
    if retry_count >= 3:
        data["_charge_end_stop_retry_exhausted"] = True
        data["_charge_end_stop_recovery_hold"] = {
            "contract": "wallbox_charge_end_stop_recovery_v1",
            "reason": str(reason or "bev_full_blocked"),
            "confirmed_output_count": retry_count,
            "last_output_ts": last_attempt_ts,
            "last_sample_ts": last_sample_ts,
        }
        result["retry_blocked"] = "confirmed_output_retry_limit"
        return result

    if native_toggle_driver:
        native_plug_session_id = str(
            data.get("_charge_end_latched_plug_session_id") or ""
        )
        native_release_token = str(
            data.get("_charge_end_release_token") or ""
        )
        if not native_plug_session_id or not native_release_token:
            data["_charge_end_stop_recovery_hold"] = {
                "contract": "wallbox_charge_end_stop_recovery_v1",
                "reason": str(reason or "bev_full_blocked"),
                "blocker": "native_stop_identity_missing",
            }
            result["retry_blocked"] = "native_stop_identity_missing"
            return result
        native_stop_contract = {
            "contract": "wallbox_native_stop_edge_wal_v1",
            "state": "pending",
            "reason": str(reason or "bev_full_blocked"),
            "plug_session_id": native_plug_session_id,
            "release_token": native_release_token,
            "sample_ts": sample_ts,
            "created_ts": now_value,
            "wire_receipt_seq": 0,
            "wire_receipt_ts": 0.0,
        }
        data["_native_charge_end_stop_contract"] = native_stop_contract
        if not _save_wallbox_abort_state(chargers):
            data["_charge_end_stop_recovery_hold"] = {
                "contract": "wallbox_charge_end_stop_recovery_v1",
                "reason": str(reason or "bev_full_blocked"),
                "blocker": "native_stop_wal_persist_failed",
            }
            result["retry_blocked"] = "native_stop_wal_persist_failed"
            return result

    internal_sender = stop_sender is None
    sender = stop_sender or _send_wallbox_stop_command
    output_reason = _bev_full_block_stop_reason(data)
    previous_receipt = data.get("_last_executed_command")
    data.pop("_wallbox_driver_dispatch_contract", None)
    result["stop_attempted"] = True
    data["_charge_end_last_output_attempt_sample_ts"] = sample_ts
    data["_charge_end_last_stop_attempt_ts"] = now_value
    sender_ok = False
    try:
        sender_ok = bool(sender(data, c_id=c_id, reason=output_reason))
    except Exception as exc:
        data["_charge_end_stop_error"] = exc.__class__.__name__
    receipt = data.get("_last_executed_command")
    cycle_token = str(data.get("_wallbox_cycle_token") or "")
    receipt_method = (
        str(receipt.get("method") or "")
        if isinstance(receipt, dict)
        else ""
    )
    native_stop_receipt_valid = bool(
        receipt_method != "set_amp_sonnenmodus"
        or (
            receipt.get("force_state") == 1
            and receipt.get("wire_receipt_contract")
            == "e3dc_wbchar6_wire_receipt_v1"
            and receipt.get("wire_receipt_new") is True
            and int(receipt.get("wire_receipt_seq", 0) or 0) > 0
            and int(receipt.get("wire_abort_flag", 0) or 0) == 1
            and receipt.get("wire_heartbeat") is False
            and receipt.get("stop_edge_issued") is True
            and _cfg_float(receipt.get("wire_receipt_ts"), 0.0) > sample_ts
        )
    )
    receipt_valid = bool(
        sender_ok
        and cycle_token
        and isinstance(receipt, dict)
        and receipt is not previous_receipt
        and receipt_method
        in (
            "set_amp_and_state",
            "set_amp_sonnenmodus",
            "set_direct_current",
        )
        and str(receipt.get("reason") or "") == output_reason
        and str(receipt.get("cycle_token") or "") == cycle_token
        and _cfg_float(receipt.get("ts"), 0.0) > sample_ts
        and native_stop_receipt_valid
    )
    result["output_receipt_valid"] = receipt_valid
    if receipt_valid:
        if native_toggle_driver:
            native_stop_contract.update({
                "state": "issued_unconfirmed",
                "wire_receipt_seq": int(
                    receipt.get("wire_receipt_seq", 0) or 0
                ),
                "wire_receipt_ts": _cfg_float(
                    receipt.get("wire_receipt_ts"),
                    0.0,
                ),
            })
            data["_native_charge_end_stop_contract"] = native_stop_contract
            if not _save_wallbox_abort_state(chargers):
                data["_charge_end_stop_recovery_hold"] = {
                    "contract": "wallbox_charge_end_stop_recovery_v1",
                    "reason": str(reason or "bev_full_blocked"),
                    "blocker": "native_stop_receipt_persist_failed",
                }
        data["_charge_end_last_stop_sample_ts"] = sample_ts
        data["_charge_end_stop_retry_count"] = retry_count + 1
        data.pop("_charge_end_stop_output_not_issued", None)
        result["stop_handled"] = True
        data["_wb_stop_sent_active"] = True
    else:
        dispatch_contract = data.get("_wallbox_driver_dispatch_contract")
        dispatch_contract = (
            dispatch_contract
            if isinstance(dispatch_contract, dict)
            and dispatch_contract.get("contract")
            == "wallbox_driver_dispatch_contract_v1"
            and str(dispatch_contract.get("reason") or "") == output_reason
            and str(dispatch_contract.get("cycle_token") or "") == cycle_token
            else {}
        )
        proven_prewire_no_output = bool(
            native_toggle_driver
            and not sender_ok
            and (
                (
                    dispatch_contract
                    and dispatch_contract.get("wire_attempted") is False
                )
                or (internal_sender and not dispatch_contract)
            )
        )
        explicit_native_no_edge = bool(
            native_toggle_driver
            and sender_ok
            and isinstance(receipt, dict)
            and receipt is not previous_receipt
            and receipt_method == "set_amp_sonnenmodus"
            and receipt.get("wire_receipt_contract")
            == "e3dc_wbchar6_wire_receipt_v1"
            and receipt.get("wire_receipt_new") is True
            and int(receipt.get("wire_abort_flag", 0) or 0) == 0
            and receipt.get("stop_edge_issued") is False
        )
        if explicit_native_no_edge:
            data.pop("_native_charge_end_stop_contract", None)
            if not _save_wallbox_abort_state(chargers):
                data["_native_charge_end_stop_contract"] = native_stop_contract
                data["_charge_end_stop_recovery_hold"] = {
                    "contract": "wallbox_charge_end_stop_recovery_v1",
                    "reason": str(reason or "bev_full_blocked"),
                    "blocker": "native_no_edge_clear_persist_failed",
                }
        elif proven_prewire_no_output:
            data.pop("_native_charge_end_stop_contract", None)
            if not _save_wallbox_abort_state(chargers):
                data["_native_charge_end_stop_contract"] = native_stop_contract
                data["_charge_end_stop_recovery_hold"] = {
                    "contract": "wallbox_charge_end_stop_recovery_v1",
                    "reason": str(reason or "bev_full_blocked"),
                    "blocker": "native_prewire_clear_persist_failed",
                }
        elif native_toggle_driver:
            data["_charge_end_stop_recovery_hold"] = {
                "contract": "wallbox_charge_end_stop_recovery_v1",
                "reason": str(reason or "bev_full_blocked"),
                "blocker": "native_stop_output_ambiguous",
            }
        data["_charge_end_stop_output_not_issued"] = {
            "reason": output_reason,
            "attempt_ts": now_value,
            "sample_ts": sample_ts,
            "sender_ok": sender_ok,
        }
        result["retry_blocked"] = "output_not_issued"
    return result


def _wallbox_charge_end_stop_diagnostics(c_data):
    data = c_data if isinstance(c_data, dict) else {}
    recovery = data.get("_charge_end_stop_recovery_hold")
    not_issued = data.get("_charge_end_stop_output_not_issued")
    native_stop_contract = data.get("_native_charge_end_stop_contract")
    return {
        "charge_end_persist_failed": str(
            data.get("_charge_end_persist_failed") or ""
        ),
        "charge_end_stop_retry_count": max(
            0,
            int(data.get("_charge_end_stop_retry_count", 0) or 0),
        ),
        "charge_end_stop_retry_exhausted": bool(
            data.get("_charge_end_stop_retry_exhausted", False)
        ),
        "charge_end_stop_recovery_hold": (
            dict(recovery) if isinstance(recovery, dict) else {}
        ),
        "charge_end_stop_output_not_issued": (
            dict(not_issued) if isinstance(not_issued, dict) else {}
        ),
        "charge_end_native_stop_contract": (
            dict(native_stop_contract)
            if isinstance(native_stop_contract, dict)
            else {}
        ),
    }


def _commit_prepared_wallbox_abort_mutation(
    chargers,
    c_data,
    *,
    before,
    disk_preimage,
    name,
):
    """Persistiert eine vorbereitete Latch-Mutation mit Datei-Rollback."""

    data = c_data if isinstance(c_data, dict) else {}
    previous = before if isinstance(before, dict) else dict(data)
    preimage = disk_preimage if isinstance(disk_preimage, dict) else {}
    if not preimage.get("valid", False):
        data.clear()
        data.update(previous)
        data["_charge_end_release_persist_failed"] = "%s:preimage_invalid" % name
        return {"committed": False, "restored": False, "reason": "preimage_invalid"}
    if _save_wallbox_abort_state(chargers):
        data.pop("_charge_end_release_persist_failed", None)
        return {"committed": True, "restored": False, "reason": "committed"}

    data.clear()
    data.update(previous)
    restored = bool(
        _restore_wallbox_state_file_preimage(WB_ABORT_STATE_FILE, preimage)
    )
    data["_charge_end_release_persist_failed"] = str(name or "abort_release")
    if restored:
        return {"committed": False, "restored": True, "reason": "save_failed_restored"}

    # Ein ambiger Commit darf auch nach einem späteren Manager-Neustart nicht
    # als freigegeben erscheinen. Der Recovery-Hold ersetzt ausschließlich
    # die unklare Release-Generation; Nutzer-/Safety-Ausgänge bleiben gesperrt.
    data["_bev_full_blocked"] = True
    data["_bev_full_block_reason"] = "abort_state_recovery_hold"
    data["_charge_end_restore_error"] = "%s:disk_restore_failed" % name
    recovery_saved = bool(_save_wallbox_abort_state(chargers))
    return {
        "committed": False,
        "restored": False,
        "recovery_saved": recovery_saved,
        "reason": "disk_restore_failed_recovery_hold",
    }


def _clear_wallbox_vehicle_finished_candidates(c_data):
    """Löscht ausschließlich noch nicht terminale Ladeende-Kandidaten."""

    if not isinstance(c_data, dict):
        return
    for key in (
        "_vehicle_finished_candidate",
        "_vehicle_finished_candidate_contract",
        "_vehicle_finished_candidate_ready",
        "_openwb_pro_vehicle_finished_candidate",
        "_openwb_pro_vehicle_finished_contract",
    ):
        c_data.pop(key, None)


def _observe_generic_wallbox_plug_episode(
    c_data,
    status,
    *,
    now_ts=None,
    chargers=None,
):
    """Entprellt Ab-/Anstecken für Wallboxen ohne eigene Stecksession-ID.

    Stale/Glitch ist keine physische Trennung. Erst drei fortschreitende,
    frische Disconnect-Frames über mindestens zehn Sekunden terminalisieren
    die alte Episode; der folgende frische Reconnect erzeugt eine neue ID.
    """

    data = c_data if isinstance(c_data, dict) else {}
    st = status if isinstance(status, dict) else {}
    charger = data.get("charger")
    if openwb_pro_session.is_openwb_pro_charger(charger):
        return {"action": "delegated_openwb_pro", "rotated": False}
    if (
        not str(data.get("_wallbox_plug_episode_id") or "")
        and data.get("_bev_full_blocked") is True
        and str(data.get("_bev_full_block_reason") or "")
        in _CHARGE_END_TERMINAL_REASONS
        and str(data.get("_charge_end_latched_plug_session_id") or "")
    ):
        # Nach einem Manager-Neustart bleibt die alte, persistierte Episode
        # bis zur bestätigten Trennung maßgeblich. Eine neue Runtime-ID wäre
        # sonst kein Beleg dafür, dass tatsächlich neu angesteckt wurde.
        data["_wallbox_plug_episode_id"] = str(
            data.get("_charge_end_latched_plug_session_id")
        )
    now_value = float(now_ts if now_ts is not None else time.time())
    fresh = bool(
        st
        and st.get("driver_status_valid") is True
        and not bool(st.get("driver_status_stale", False))
        and not bool(st.get("driver_status_glitch", False))
    )
    if not fresh:
        data.pop("_wallbox_disconnect_candidate", None)
        return {"action": "hold_unknown", "rotated": False}

    connected = _wb_status_connected(st)
    sample_ts = float(st.get("driver_status_last_sample_ts", now_value) or now_value)
    candidate = data.get("_wallbox_disconnect_candidate")
    candidate = dict(candidate) if isinstance(candidate, dict) else {}
    if not connected:
        if float(candidate.get("first_ts", 0.0) or 0.0) <= 0.0:
            candidate = {
                "first_ts": now_value,
                "first_sample_ts": sample_ts,
                "last_sample_ts": sample_ts,
                "frames": 1,
            }
        elif sample_ts > float(candidate.get("last_sample_ts", 0.0) or 0.0):
            candidate["last_sample_ts"] = sample_ts
            candidate["frames"] = int(candidate.get("frames", 1) or 1) + 1
        elapsed_s = max(
            0.0,
            float(candidate.get("last_sample_ts", sample_ts) or sample_ts)
            - float(candidate.get("first_sample_ts", sample_ts) or sample_ts),
        )
        confirmed = bool(
            int(candidate.get("frames", 0) or 0) >= 3
            and elapsed_s >= 10.0
        )
        candidate["confirmed"] = confirmed
        data["_wallbox_disconnect_candidate"] = candidate
        data["_wallbox_disconnect_confirmed"] = confirmed
        return {
            "action": "disconnect_confirmed" if confirmed else "disconnect_candidate",
            "rotated": False,
            "frames": int(candidate.get("frames", 0) or 0),
            "elapsed_s": elapsed_s,
        }

    if data.get("_wallbox_disconnect_confirmed") is True:
        before = dict(data)
        disk_preimage = _snapshot_wallbox_state_file_preimage(
            WB_ABORT_STATE_FILE
        )
        previous_reason = str(data.get("_bev_full_block_reason") or "")
        previous_episode_id = str(data.get("_wallbox_plug_episode_id") or "")
        latched_episode_id = str(
            data.get("_charge_end_latched_plug_session_id") or ""
        )
        release_terminal_latch = bool(
            data.get("_bev_full_blocked") is True
            and previous_reason in _CHARGE_END_TERMINAL_REASONS
            and previous_episode_id
            and latched_episode_id == previous_episode_id
            and not _native_e3dc_floor_zero_anchor_active(data)
        )
        new_episode_id = "wb%s:%d" % (
            int(data.get("id", 0) or 0),
            time.time_ns(),
        )
        prior_floor_replug_evidence = (
            _validated_native_e3dc_floor_replug_evidence(
                data.get("_native_e3dc_floor_replug_evidence"),
                current_episode_id=previous_episode_id,
            )
        )
        data["_wallbox_plug_episode_id"] = new_episode_id
        floor_anchor = data.get("_manager_zero_anchor_contract")
        floor_anchor = (
            floor_anchor if isinstance(floor_anchor, dict) else {}
        )
        if (
            _native_e3dc_floor_zero_anchor_active(data)
            and floor_anchor.get("reason_code")
            == "wbminsoc_floor_battery_stop"
            and (
                str(floor_anchor.get("plug_session_id") or "")
                == previous_episode_id
                or bool(prior_floor_replug_evidence)
            )
        ):
            replug_origin_id = str(
                prior_floor_replug_evidence.get("previous_episode_id")
                or previous_episode_id
            )
            floor_replug_evidence = _native_e3dc_floor_replug_evidence(
                floor_anchor,
                previous_episode_id=replug_origin_id,
                new_episode_id=new_episode_id,
                now_ts=now_value,
            )
            if floor_replug_evidence:
                data["_native_e3dc_floor_replug_evidence"] = dict(
                    floor_replug_evidence
                )
            else:
                data.pop("_native_e3dc_floor_replug_evidence", None)
        else:
            data.pop("_native_e3dc_floor_replug_evidence", None)
        data.pop("_wallbox_disconnect_candidate", None)
        data["_wallbox_disconnect_confirmed"] = False
        _clear_wallbox_vehicle_finished_candidates(data)
        _reset_wallbox_confirmed_disconnect_runtime(data)
        if release_terminal_latch:
            _clear_wallbox_charge_end_latch(data, "confirmed_replug")
        if release_terminal_latch:
            data["_manager_zero_anchor_active"] = False
            data.pop("_manager_zero_anchor_contract", None)
        persistence = (
            _commit_prepared_wallbox_abort_mutation(
                chargers,
                data,
                before=before,
                disk_preimage=disk_preimage,
                name="confirmed_replug",
            )
            if chargers is not None
            else {"committed": True, "reason": "runtime_only"}
        )
        if not persistence.get("committed", False):
            return {
                "action": "replug_persist_failed",
                "rotated": False,
                "persistence": persistence,
            }
        data.pop("_charge_end_release_persist_failed", None)
        return {
            "action": "replug_rotated",
            "rotated": True,
            "previous_episode_id": previous_episode_id,
            "new_episode_id": new_episode_id,
            "terminal_latch_released": release_terminal_latch,
        }

    data.pop("_wallbox_disconnect_candidate", None)
    if not str(data.get("_wallbox_plug_episode_id") or ""):
        data["_wallbox_plug_episode_id"] = "wb%s:%d" % (
            int(data.get("id", 0) or 0),
            time.time_ns(),
        )
    return {"action": "connected", "rotated": False}


def _webui_emergency_flag_token(path):
    """Liefere eine nicht erratene Identität der aktuellen NOT-AUS-Flanke."""

    try:
        flags = os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0)
        fd = os.open(path, flags)
        try:
            info = os.fstat(fd)
            if not stat.S_ISREG(info.st_mode) or info.st_size > 4096:
                return "", "emergency_flag_not_regular"
            chunks = []
            remaining = 4097
            while remaining > 0:
                chunk = os.read(fd, min(remaining, 4096))
                if not chunk:
                    break
                chunks.append(chunk)
                remaining -= len(chunk)
            if remaining <= 0:
                return "", "emergency_flag_too_large"
            payload = b"".join(chunks)
            identity = "%d:%d:%d:%d:" % (
                int(info.st_dev),
                int(info.st_ino),
                int(info.st_mtime_ns),
                int(info.st_size),
            )
            return hashlib.sha256(identity.encode("ascii") + payload).hexdigest(), ""
        finally:
            os.close(fd)
    except FileNotFoundError:
        return "", "emergency_flag_missing"
    except OSError as exc:
        return "", "emergency_flag_unreadable:%s" % exc.__class__.__name__


def _read_webui_emergency_episode_state(path):
    if not os.path.lexists(path):
        return {}, ""
    try:
        info = os.lstat(path)
        if not stat.S_ISREG(info.st_mode) or stat.S_ISLNK(info.st_mode):
            return {}, "emergency_episode_state_not_regular"
        flags = os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0)
        fd = os.open(path, flags)
        try:
            payload = b""
            while len(payload) <= 16384:
                chunk = os.read(fd, 4096)
                if not chunk:
                    break
                payload += chunk
            if len(payload) > 16384:
                return {}, "emergency_episode_state_too_large"
        finally:
            os.close(fd)
        state = json.loads(payload.decode("utf-8"))
        if not isinstance(state, dict) or state.get("schema") != "wallbox_emergency_output_episode_v1":
            return {}, "emergency_episode_state_invalid"
        attempted = state.get("attempted_wb_ids")
        if not isinstance(attempted, list) or any(
            not isinstance(item, int) or item <= 0 for item in attempted
        ):
            return {}, "emergency_episode_state_invalid"
        wb_status = state.get("wb_status", {})
        allowed_status = {"intent_persisted", "confirmed", "unknown_fail_closed"}
        if not isinstance(wb_status, dict) or any(
            not str(key).isdigit()
            or int(key) <= 0
            or value not in allowed_status
            for key, value in wb_status.items()
        ):
            return {}, "emergency_episode_state_invalid"
        if any(str(item) not in wb_status for item in attempted):
            return {}, "emergency_episode_state_invalid"
        return state, ""
    except (OSError, UnicodeError, ValueError, TypeError):
        return {}, "emergency_episode_state_invalid"


def _write_webui_emergency_episode_state(path, state):
    """Persistiere den Output-Intent vor I/O, niemals zyklisch."""

    tmp = ""
    try:
        directory = os.path.dirname(path)
        directory_info = os.lstat(directory)
        if not stat.S_ISDIR(directory_info.st_mode) or stat.S_ISLNK(directory_info.st_mode):
            return False
        if os.path.lexists(path):
            target_info = os.lstat(path)
            if not stat.S_ISREG(target_info.st_mode) or stat.S_ISLNK(target_info.st_mode):
                return False
        payload = json.dumps(
            state, ensure_ascii=False, sort_keys=True, separators=(",", ":")
        ) + "\n"
        tmp = "%s.tmp.%d" % (path, os.getpid())
        flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
        fd = os.open(tmp, flags, 0o664)
        try:
            os.write(fd, payload.encode("utf-8"))
            os.fsync(fd)
        finally:
            os.close(fd)
        os.chmod(tmp, 0o664)
        os.replace(tmp, path)
        dir_fd = os.open(directory, os.O_RDONLY)
        try:
            os.fsync(dir_fd)
        finally:
            os.close(dir_fd)
        return True
    except OSError:
        try:
            if tmp and os.path.lexists(tmp):
                os.unlink(tmp)
        except OSError:
            pass
        return False


def _claim_webui_emergency_episode(c_data, flag_path, state_path=None):
    """Beanspruche genau einen Emergency-I/O-Versuch je Flag-Flanke/WB."""

    data = c_data if isinstance(c_data, dict) else {}
    wb_id = int(data.get("id", 0) or 0)
    if wb_id <= 0:
        return False, "invalid_wallbox_id"
    token, token_error = _webui_emergency_flag_token(flag_path)
    if token_error:
        data["_webui_emergency_episode_blocked"] = token_error
        return False, token_error
    if data.get("_webui_emergency_episode_state_blocked_token") == token:
        return False, "episode_state_io_latched"
    target = state_path or WEBUI_EMERGENCY_EPISODE_STATE_FILE
    state, state_error = _read_webui_emergency_episode_state(target)
    if state_error:
        data["_webui_emergency_episode_state_blocked_token"] = token
        data["_webui_emergency_episode_blocked"] = state_error
        return False, state_error
    attempted = set()
    if state.get("episode_token") == token:
        attempted = {int(item) for item in state.get("attempted_wb_ids", [])}
    if wb_id in attempted:
        data["_webui_emergency_episode_token"] = token
        data["_webui_emergency_output_attempted"] = True
        data["_webui_emergency_output_result"] = str(
            state.get("wb_status", {}).get(str(wb_id), "intent_persisted")
        )
        return False, "episode_already_attempted"

    attempted.add(wb_id)
    next_state = {
        "schema": "wallbox_emergency_output_episode_v1",
        "episode_token": token,
        "attempted_wb_ids": sorted(attempted),
        "wb_status": {
            **(
                dict(state.get("wb_status", {}))
                if state.get("episode_token") == token
                else {}
            ),
            str(wb_id): "intent_persisted",
        },
    }
    if not _write_webui_emergency_episode_state(target, next_state):
        data["_webui_emergency_episode_state_blocked_token"] = token
        data["_webui_emergency_episode_blocked"] = "episode_intent_persist_failed"
        return False, "episode_intent_persist_failed"
    data["_webui_emergency_episode_token"] = token
    data["_webui_emergency_output_attempted"] = True
    data["_webui_emergency_output_result"] = "intent_persisted"
    data.pop("_webui_emergency_episode_blocked", None)
    return True, "episode_claimed"


def _record_webui_emergency_episode_result(c_data, flag_path, result, state_path=None):
    """Schreibe das Ergebnis einmalig, ohne fremde WB-Resultate zu verlieren."""

    data = c_data if isinstance(c_data, dict) else {}
    wb_id = int(data.get("id", 0) or 0)
    status = str(result or "unknown_fail_closed")
    if status not in ("confirmed", "unknown_fail_closed") or wb_id <= 0:
        status = "unknown_fail_closed"
    token, token_error = _webui_emergency_flag_token(flag_path)
    if token_error:
        data["_webui_emergency_output_result"] = "intent_persisted"
        return False
    target = state_path or WEBUI_EMERGENCY_EPISODE_STATE_FILE
    state, state_error = _read_webui_emergency_episode_state(target)
    if (
        state_error
        or state.get("episode_token") != token
        or wb_id not in set(state.get("attempted_wb_ids", []))
    ):
        data["_webui_emergency_output_result"] = "intent_persisted"
        return False
    wb_status = dict(state.get("wb_status", {}))
    if wb_status.get(str(wb_id)) == status:
        data["_webui_emergency_output_result"] = status
        return True
    wb_status[str(wb_id)] = status
    next_state = dict(state)
    next_state["wb_status"] = wb_status
    if not _write_webui_emergency_episode_state(target, next_state):
        data["_webui_emergency_output_result"] = "intent_persisted"
        data["_webui_emergency_episode_blocked"] = "episode_result_persist_failed"
        return False
    data["_webui_emergency_output_result"] = status
    return True


def _clear_webui_emergency_episode_latch(c_data):
    data = c_data if isinstance(c_data, dict) else {}
    for key in (
        "_webui_emergency_episode_token",
        "_webui_emergency_output_attempted",
        "_webui_emergency_output_result",
        "_webui_emergency_episode_blocked",
        "_webui_emergency_episode_state_blocked_token",
    ):
        data.pop(key, None)


def _apply_webui_emergency_stop_episode(chargers, flag_path, state_path=None):
    """Halte NOT-AUS sichtbar, aber sende je physischer Flag-Flanke nur einmal."""

    boxes = chargers if isinstance(chargers, list) else []
    active = os.path.lexists(flag_path)
    if not active:
        for data in boxes:
            _clear_webui_emergency_episode_latch(data)
        return False

    for data in boxes:
        if not isinstance(data, dict):
            continue
        c_id = int(data.get("id", 0) or 0)
        charger = data.get("charger")
        claimed, claim_reason = _claim_webui_emergency_episode(
            data, flag_path, state_path=state_path
        )
        confirmed_output = False
        if claimed:
            result = False
            try:
                if hasattr(charger, "emergency_stop"):
                    result = bool(_execute_wallbox_driver_command(
                        data,
                        {"method": "emergency_stop", "reason": "emergency_stop"},
                        c_id=c_id,
                    ))
                else:
                    result = bool(_send_wallbox_stop_command(
                        data,
                        c_id=c_id,
                        reason="emergency_stop",
                        stop_authority=wallbox_decision.final_stop_authority_contract(),
                        require_typed_stop_authority=True,
                    ))
            except Exception as exc:
                logger.warning("WB%d NOT-AUS Stop fehlgeschlagen: %s" % (c_id, exc))
            _record_webui_emergency_episode_result(
                data,
                flag_path,
                "confirmed" if result else "unknown_fail_closed",
                state_path=state_path,
            )
            confirmed_output = bool(result)
        elif claim_reason not in ("episode_already_attempted",):
            logger.error(
                "WB%d NOT-AUS Ausgang fail-closed blockiert: %s",
                c_id,
                claim_reason,
            )
        if confirmed_output:
            data["current_set_amp"] = 0
            data["is_charging"] = False
            data["_pv_mode_active"] = False
            data["_wb_stop_sent_active"] = True
            data["_predump_gate_stop_sent"] = True
    return True


def _wallbox_charge_end_latch_contract(
    c_data,
    status=None,
    *,
    now_ts=None,
    config=None,
    charger_id=None,
    public_mode=None,
    had_confirmed_charge=None,
    allow_new_latch=False,
    user_release_exception="",
    vehicle_changed=False,
    disconnected_release=False,
    mode_off=False,
    start_verifying=False,
    manager_stop_active=False,
    grace_active=False,
    target_soc_reached=False,
    target_reached_reason="",
    external_restart_confirmed=False,
    diagnostic_only=False,
):
    if not isinstance(c_data, dict):
        return {}
    cid = charger_id if charger_id is not None else c_data.get("id", 1)
    release_exception = str(user_release_exception or "")
    if not diagnostic_only and not release_exception and config is not None:
        release_exception = _detect_wallbox_charge_end_user_release(c_data, config, cid, public_mode)
    protected_start_reject_episode = {}
    if (
        bool(c_data.get("_bev_full_blocked", False))
        and str(c_data.get("_bev_full_block_reason") or "")
        == "start_rejected"
        and release_exception
    ):
        protected_start_reject_episode = (
            _openwb_pro_start_reject_episode_contract(
                c_data,
                config if isinstance(config, dict) else {},
                now_ts=now_ts,
            )
        )
    if (
        protected_start_reject_episode.get("complete") is True
        and protected_start_reject_episode.get("session_bound") is True
        and int(protected_start_reject_episode.get("sent_count", 0) or 0) == 3
        and int(protected_start_reject_episode.get("max_retries", 0) or 0) == 3
        and str(protected_start_reject_episode.get("plug_session_id") or "")
        == str(c_data.get("_charge_end_latched_plug_session_id") or "")
    ):
        # Ein allgemeiner Mode-/Limit-/Profil-Token ist für eine verbrauchte
        # openWB-Pro-3/3-Episode keine Freigabeautorität. Nur der separat
        # versiegelte Same-Session-Mode-5-Request oder ein bestätigter Replug
        # darf diesen Latch lösen.
        c_data["_start_rejected_generic_release_blocked"] = {
            "exception": release_exception,
            "hardware_write": False,
        }
        release_exception = ""
    phase_transition_grace = _wallbox_phase_transition_grace_active(c_data, status, now_ts=now_ts)
    openwb_pro_transient_grace = False
    if openwb_pro_session.is_openwb_pro_charger(c_data.get("charger")):
        phase_sequence = c_data.get("_openwb_pro_phase_sequence")
        openwb_pro_transient_grace = bool(
            (isinstance(phase_sequence, dict) and phase_sequence and str(phase_sequence.get("stage") or "") != "ready")
            or float(c_data.get("_openwb_pro_start_wakeup_allowed_after", 0.0) or 0.0)
            > float(now_ts if now_ts is not None else time.time())
        )
    if had_confirmed_charge is None:
        had_confirmed_charge = bool(c_data.get("_aha_real_charge_confirmed", False))
    contract = wallbox_decision.charge_end_latch_contract(
        status,
        previous_latched=bool(c_data.get("_bev_full_blocked", False)),
        previous_reason=str(c_data.get("_bev_full_block_reason") or ""),
        had_confirmed_charge=bool(had_confirmed_charge),
        allow_new_latch=bool(allow_new_latch),
        user_release_exception=release_exception,
        vehicle_changed=bool(vehicle_changed),
        # Ein einzelner disconnected-Frame darf einen persistierten
        # Ladeende-Latch nicht lösen. Der bestätigte Disconnect/Reconnect
        # wird separat entprellt und erst in der dual persistierten
        # Sessionrotation terminalisiert.
        disconnected_release=bool(
            disconnected_release
            and not bool(c_data.get("_bev_full_blocked", False))
        ),
        mode_off=bool(mode_off),
        start_verifying=bool(start_verifying),
        manager_stop_active=bool(manager_stop_active),
        grace_active=bool(grace_active or phase_transition_grace or openwb_pro_transient_grace),
        target_soc_reached=bool(target_soc_reached),
        target_reached_reason=str(target_reached_reason or ""),
        external_restart_confirmed=bool(external_restart_confirmed),
        now_ts=time.time() if now_ts is None else now_ts,
    )
    _apply_charge_end_contract_to_status(status, contract)
    if diagnostic_only:
        return contract
    c_data["_charge_end_contract"] = contract
    action = str(contract.get("action", "") or "")
    if action == "clear":
        _clear_wallbox_charge_end_latch(c_data, contract.get("exception", ""))
    elif action == "latch":
        for key in _CHARGE_END_RUNTIME_EPHEMERAL_KEYS:
            c_data.pop(key, None)
        c_data["_bev_full_blocked"] = True
        c_data["_bev_full_block_reason"] = str(contract.get("reason") or "vehicle_charge_ended")
        c_data["_charge_end_latched_ts"] = float(contract.get("ts", time.time()) or time.time())
        c_data["_charge_end_manager_output_after_latch"] = False
        if openwb_pro_session.is_openwb_pro_charger(c_data.get("charger")):
            latched_plug_session_id = str(
                c_data.get("_openwb_pro_plug_session_id")
                or c_data.get("_session_vehicle_binding_id")
                or c_data.get("_wallbox_plug_episode_id")
                or ""
            )
        else:
            # Eine stabile Fahrzeug-/RFID-ID ist keine physische Steckkante.
            # Nicht-Pro-Latches werden deshalb ausschließlich an die bereits
            # entprellte generische Steckepisode gebunden.
            latched_plug_session_id = str(
                c_data.get("_wallbox_plug_episode_id") or ""
            )
        c_data["_charge_end_latched_plug_session_id"] = (
            latched_plug_session_id
        )
    return contract


def _wallbox_transient_hold_contract(
    c_data,
    status=None,
    *,
    now_ts=None,
    phase_grace_s=360.0,
    openwb_phase_capable=None,
    current_amp=0,
    current_set_amp=None,
    hw_charging=None,
    hw_power_w=None,
    phase_wait_active=False,
    start_hold_active=False,
    native_start_grace_active=False,
    priority_forced_stop=False,
    mode_off=False,
    budget_timeout=False,
):
    if not isinstance(c_data, dict):
        return {}
    st = status or {}
    now = time.time() if now_ts is None else float(now_ts or 0.0)
    last_switch = float(c_data.get("_last_phase_switch_ts", 0.0) or 0.0)
    phase_age_s = (now - last_switch) if last_switch > 0.0 and now > 0.0 else 999999.0
    charger = c_data.get("charger")
    charger_class = charger.__class__.__name__ if charger is not None else str(c_data.get("_charger_class_name", "") or "")
    driver_variant = str(getattr(charger, "driver_variant", "") or st.get("driver_variant", "") or "")
    phase_capable = bool(
        openwb_phase_capable
        if openwb_phase_capable is not None
        else (
            hasattr(charger, "set_phases")
            or charger_class == "OpenWBProCharger"
        )
    )
    target = _valid_phase_count(st.get("phases_target"), 0)
    if not target:
        target = _valid_phase_count(c_data.get("_phase_target_cmd"), 0)
    offered = max(
        _cfg_float(st.get("amp"), 0.0),
        _cfg_float(st.get("offered_current_raw"), 0.0),
        _cfg_float(st.get("offered_current"), 0.0),
    )
    if current_set_amp is None:
        current_set_amp = c_data.get("current_set_amp", 0.0)
    if hw_charging is None:
        hw_charging = _wb_status_real_charging(st)
    if hw_power_w is None:
        hw_power_w = _wb_status_real_power(st)
    return wallbox_decision.transient_hold_contract(
        st,
        charger_connected=_wb_status_connected(st),
        hw_charging=bool(hw_charging),
        hw_power_w=hw_power_w,
        current_amp=current_amp,
        current_set_amp=current_set_amp,
        offered_amp=offered,
        phase_capable=phase_capable,
        phase_target=target,
        phase_actual=st.get("phases_actual", 0),
        phases_in_use=st.get("phases_in_use", st.get("number_phases", 0)),
        phase_command_age_s=phase_age_s,
        phase_command_grace_s=phase_grace_s,
        phase_wait_active=bool(phase_wait_active),
        start_hold_active=bool(start_hold_active),
        native_start_grace_active=bool(native_start_grace_active),
        priority_forced_stop=bool(priority_forced_stop),
        mode_off=bool(mode_off),
        budget_timeout=bool(budget_timeout),
    )


def _wallbox_phase_transition_grace_active(c_data, status=None, *, now_ts=None, grace_s=360.0):
    """Return true while a commanded phase switch may interrupt charging."""
    contract = _wallbox_transient_hold_contract(
        c_data,
        status,
        now_ts=now_ts,
        phase_grace_s=grace_s,
    )
    return bool(contract.get("phase_transition_grace_active", False))


def _openwb_phase_command_grace_active(c_data, status=None, *, now_ts=None, grace_s=120.0):
    """Return true shortly after an openWB phase command was sent."""
    contract = _wallbox_transient_hold_contract(
        c_data,
        status,
        now_ts=now_ts,
        phase_grace_s=grace_s,
        openwb_phase_capable=True,
    )
    return bool(contract.get("phase_transition_offer_active", False))


def _apply_running_ramp_contract(
    c_data,
    start_stop_decision,
    *,
    target_amp,
    current_amp,
    current_set_amp,
    charger_connected,
    hw_charging,
    hw_power_w,
    now_ts,
    min_amp=6,
    max_amp=16,
    ramp_interval_s=7.0,
    up_step_a=1,
    down_step_a=1,
    current_step_amp=None,
    bypass=False,
):
    if not isinstance(c_data, dict):
        return float(target_amp or 0), start_stop_decision
    stable_owner = c_data.get("_stable_wallbox_amp_contract")
    stable_owner_active = bool(
        isinstance(stable_owner, dict)
        and stable_owner.get("schema_version") == "wallbox_stable_amp_v1"
    )
    effective_step = (
        _current_step_amp_for_charger(c_data.get("charger"), default=1.0)
        if current_step_amp is None
        else _normalize_current_step_amp(current_step_amp, default=1.0)
    )
    contract = wallbox_decision.running_charge_ramp_contract(
        target_amp=target_amp,
        current_amp=current_amp,
        current_set_amp=current_set_amp,
        charger_connected=charger_connected,
        hw_charging=hw_charging,
        hw_power_w=hw_power_w,
        now_ts=now_ts,
        last_ramp_ts=c_data.get("_running_ramp_last_ts", 0.0),
        min_amp=min_amp,
        max_amp=max_amp,
        ramp_interval_s=ramp_interval_s,
        up_step_a=up_step_a,
        down_step_a=down_step_a,
        current_step_amp=effective_step,
        # Der per-WB-Stabilitätsvertrag hat den Strom in diesem Zyklus bereits
        # begrenzt. Die historische Running-Rampe bleibt als Diagnoseprojektion
        # erhalten, darf denselben Sollwert aber nicht ein zweites Mal auf
        # +/-1 A pro 15-30 s abbremsen.
        bypass=bool(bypass or stable_owner_active),
    )
    contract["output_owner"] = (
        "stable_wallbox_amp_contract"
        if stable_owner_active
        else "running_charge_ramp_contract"
    )
    contract["single_owner_bypass"] = bool(stable_owner_active)
    c_data["_ramp_contract"] = contract
    if contract.get("changed"):
        c_data["_running_ramp_last_ts"] = float(contract.get("next_ramp_ts", now_ts) or now_ts)
    applied_amp = float(contract.get("applied_amp", target_amp) or 0.0)
    if isinstance(start_stop_decision, dict) and abs(float(target_amp or 0.0) - applied_amp) > 1e-6:
        start_stop_decision = dict(start_stop_decision)
        start_stop_decision["raw_target_amp"] = float(target_amp or 0.0)
        start_stop_decision["target_amp"] = applied_amp
        if float(start_stop_decision.get("hold_amp", 0) or 0) > 0:
            start_stop_decision["hold_amp"] = applied_amp
        start_stop_decision["ramp_contract"] = contract
        start_stop_decision["ramp_limited"] = bool(contract.get("limited", False))
        start_stop_decision["reason"] = "%s+ramp_%s" % (
            str(start_stop_decision.get("reason", start_stop_decision.get("action", "set_current")) or "set_current"),
            str(contract.get("reason", "limited") or "limited"),
        )
    return applied_amp, start_stop_decision


def _remember_phase_target(c_data, phases, now_ts=None, hold_s=900.0):
    """Remember our last phase command while openWB reports stale targets."""
    if not isinstance(c_data, dict):
        return
    phases = _valid_phase_count(phases, 0)
    if not phases:
        c_data["_phase_target_cmd"] = 0
        c_data["_phase_target_cmd_until"] = 0.0
        return
    now_ts = time.time() if now_ts is None else float(now_ts)
    c_data["_phase_target_cmd"] = int(phases)
    c_data["_phase_target_cmd_until"] = now_ts + max(30.0, float(hold_s or 0.0))


def _openwb_pro_phase_change_veto_until(c_data):
    """Liefert ausschließlich die Frist gegen eine neue Phasenkante.

    Der elektromechanische openWB-Pro-Cooldown darf niemals einen positiven
    Sollstrom am bereits bestätigten Phasenziel sperren. Die Policy muss ihn
    aber aus denselben persistierten Belegen wie der Executor erkennen, damit
    sie während der Schutzfrist keinen unerfüllbaren ``set_phases``-Plan vor
    den Stromstart stellt.
    """

    data = c_data if isinstance(c_data, dict) else {}
    reservation = data.get("_wallbox_phase_transition_reservation")
    reservation_cooldown_until = 0.0
    if isinstance(reservation, dict) and reservation.get("active") is True:
        reservation_cooldown_until = _cfg_float(
            reservation.get("cooldown_until_ts"),
            0.0,
        )
    return max(
        _cfg_float(data.get("_phase_3p_block_until"), 0.0),
        _cfg_float(
            data.get("_openwb_pro_phase_change_block_until"),
            0.0,
        ),
        reservation_cooldown_until,
    )


def _effective_phase_target(status, c_data, now_ts=None):
    """Return the phase target that must be used for physical budget checks."""
    now_ts = time.time() if now_ts is None else float(now_ts)
    if isinstance(c_data, dict):
        cmd = _valid_phase_count(c_data.get("_phase_target_cmd"), 0)
        until = float(c_data.get("_phase_target_cmd_until", 0.0) or 0.0)
        if cmd and now_ts <= until:
            return cmd
        if until and now_ts > until:
            c_data["_phase_target_cmd"] = 0
            c_data["_phase_target_cmd_until"] = 0.0
    return _valid_phase_count((status or {}).get("phases_target"), 0)


def _openwb_pro_curve_direct_phases(status, c_data, detected_phases=1, now_ts=None):
    st = status or {}
    detected = _valid_phase_count(detected_phases, 1) or 1
    now_ts = time.time() if now_ts is None else float(now_ts)
    remembered_target = 0
    if isinstance(c_data, dict):
        until = float(c_data.get("_phase_target_cmd_until", 0.0) or 0.0)
        if until and now_ts <= until:
            remembered_target = _valid_phase_count(c_data.get("_phase_target_cmd"), 0)
    target = _valid_phase_count(st.get("phases_target"), 0)
    actual = _valid_phase_count(st.get("phases_actual"), 0)
    in_use = _valid_phase_count(st.get("phases_in_use"), 0)
    current_set = 0.0
    if isinstance(c_data, dict):
        try:
            current_set = float(c_data.get("current_set_amp", 0.0) or 0.0)
        except (TypeError, ValueError):
            current_set = 0.0
    try:
        offered = float(st.get("amp", st.get("offered_current", 0.0)) or 0.0)
    except (TypeError, ValueError):
        offered = 0.0
    active_or_offered = bool(
        remembered_target
        or _wb_status_real_charging(st)
        or _wb_status_real_power(st) > 500.0
        or offered >= 5.5
        or current_set >= 5.5
    )
    if remembered_target in (1, 3):
        return remembered_target
    if active_or_offered and target in (1, 3):
        return target
    if in_use in (1, 3):
        return in_use
    if actual in (1, 3):
        return actual
    return detected


def _phase_transition_pending_for_start_reject(
    c_data,
    *,
    now_ts=None,
    phase_confirm_timeout_s=120.0,
    phase_effective_hold_s=0.0,
):
    """Return true while a bounded phase transition may hide charge power."""
    if not isinstance(c_data, dict):
        return False
    try:
        now_value = time.time() if now_ts is None else float(now_ts)
        confirm_s = max(30.0, float(phase_confirm_timeout_s or 0.0))
        hold_s = max(0.0, float(phase_effective_hold_s or 0.0))
        grace_s = max(confirm_s, hold_s) + 60.0
        pending_since = float(c_data.get("_phase_3p_pending_since", 0.0) or 0.0)
        last_switch = float(c_data.get("_last_phase_switch_ts", 0.0) or 0.0)
    except (TypeError, ValueError):
        return False

    sequence = c_data.get("_openwb_pro_phase_sequence")
    reservation = c_data.get("_wallbox_phase_transition_reservation")
    if isinstance(sequence, dict) and sequence and isinstance(reservation, dict):
        try:
            sequence_target = int(sequence.get("target", 0) or 0)
            reservation_target = int(reservation.get("target_phases", 0) or 0)
            charger_id = int(c_data.get("id", 0) or 0)
            reservation_wb_id = int(reservation.get("wb_id", 0) or 0)
            lease_until = float(
                reservation.get(
                    "lease_until_ts",
                    reservation.get("expires_ts", 0.0),
                )
                or 0.0
            )
        except (TypeError, ValueError):
            sequence_target = 0
            reservation_target = 0
            charger_id = 0
            reservation_wb_id = -1
            lease_until = 0.0
        reservation_id = str(
            reservation.get("reservation_id")
            or reservation.get("transition_id")
            or ""
        )
        grant_state = str(reservation.get("grant_state") or "")
        if (
            reservation.get("active") is True
            and reservation.get("owner") == "wallbox_manager"
            and reservation.get("source") == "openwb_pro_phase_sequence"
            and charger_id > 0
            and reservation_wb_id == charger_id
            and reservation_id
            and sequence_target in (1, 3)
            and reservation_target == sequence_target
            and grant_state in ("granted", "committed")
            and lease_until > 0.0
            and 0.0 <= lease_until - now_value <= 900.0
        ):
            return True

    if pending_since > 0.0 and 0.0 <= now_value - pending_since <= grace_s:
        return True
    if last_switch > 0.0 and 0.0 <= now_value - last_switch <= min(grace_s, confirm_s + 30.0):
        return True
    return False
def _wallbox_executable_budget(
    status=None,
    c_data=None,
    *,
    config=None,
    charger_id=1,
    allowed_w=0.0,
    detected_phases=1,
    min_amp=6,
    vehicle_max_phases=0,
    phase_cap_phases=0,
    phase_switch_phases=0,
    phase_target=0,
    openwb_phase_capable=False,
    can_switch_to_1p=False,
    require_one_phase=False,
    grid_unlocked=False,
    autonomous_pv_only=False,
    phase_capability=None,
    vehicle_phase_capability=None,
    charger_class_name="",
    driver_variant="",
):
    """Return whether the current budget can physically start or hold charging.

    This is deliberately a small physics gate: 6A * 230V * active phases is
    the minimum useful load. openWB/openWB Pro may avoid a 3p deadlock by first
    switching to 1p when the 1p minimum is available.
    """
    return wallbox_decision.wallbox_executable_budget(
        status,
        c_data,
        config=config,
        charger_id=charger_id,
        allowed_w=allowed_w,
        detected_phases=detected_phases,
        min_amp=min_amp,
        vehicle_max_phases=vehicle_max_phases,
        phase_cap_phases=phase_cap_phases,
        phase_switch_phases=phase_switch_phases,
        phase_target=phase_target,
        openwb_phase_capable=openwb_phase_capable,
        can_switch_to_1p=can_switch_to_1p,
        require_one_phase=require_one_phase,
        grid_unlocked=grid_unlocked,
        autonomous_pv_only=autonomous_pv_only,
        phase_capability=phase_capability,
        vehicle_phase_capability=vehicle_phase_capability,
        charger_class_name=charger_class_name,
        driver_variant=driver_variant,
    )


def _bind_autonomous_solar_output_contract(c_data, physical_budget):
    """Versiegelt die vom Manager gewählte efy-Solarübergabe je Zyklus."""

    box = c_data if isinstance(c_data, dict) else {}
    contract = wallbox_decision.autonomous_solar_output_contract(
        physical_budget,
    )
    contract["cycle_token"] = str(box.get("_wallbox_cycle_token") or "")
    box["_autonomous_solar_output_contract"] = dict(contract)
    return contract


def _current_autonomous_solar_output_contract(c_data):
    """Liefert nur den vollständig aktuellen Mode-1-Vertrag dieses Zyklus."""

    box = c_data if isinstance(c_data, dict) else {}
    output = box.get("_autonomous_solar_output_contract")
    physical = box.get("_physical_budget")
    phase = (
        physical.get("phase_contract")
        if isinstance(physical, dict)
        and isinstance(physical.get("phase_contract"), dict)
        else {}
    )
    token = str(box.get("_wallbox_cycle_token") or "")
    if not (
        token
        and isinstance(output, dict)
        and output.get("contract") == "wallbox_autonomous_solar_output_v1"
        and output.get("active") is True
        and str(output.get("cycle_token") or "") == token
        and output.get("method") == "set_amp_autonomous_solar"
        and output.get("protocol_mode") == "wbchar6_solar_mode"
        and output.get("watt_budget_semantics") == "autonomous_pv_sink"
        and output.get("strict_watt_cap") is False
        and isinstance(physical, dict)
        and physical.get("autonomous_phase_handoff") is True
        and physical.get("autonomous_1p_ready") is True
        and physical.get("grid_unlocked") is False
        and physical.get("strict_watt_cap") is False
        and physical.get("watt_budget_semantics") == "autonomous_pv_sink"
        and physical.get("autonomous_phase_handoff_method")
        == "set_amp_autonomous_solar"
        and physical.get("autonomous_phase_protocol_mode")
        == "wbchar6_solar_mode"
        and phase.get("autonomous_phase_switch_capable") is True
        and phase.get("autonomous_phase_switch_source")
        == wallbox_decision.EFY_WBCHAR6_AUTONOMOUS_SOURCE
        and phase.get("autonomous_phase_switch_provenance")
        == wallbox_decision.EFY_WBCHAR6_PROVENANCE
        and phase.get("autonomous_phase_handoff_method")
        == "set_amp_autonomous_solar"
        and phase.get("autonomous_phase_protocol_mode")
        == "wbchar6_solar_mode"
        and hasattr(box.get("charger"), "set_amp_autonomous_solar")
    ):
        return {}
    return dict(output)


def _native_solar_output_method(c_data):
    """Wählt Mode 2, Mode 1 oder bewusst keinen Hardwareausgang."""

    box = c_data if isinstance(c_data, dict) else {}
    contract = box.get("_autonomous_solar_output_contract")
    if _current_autonomous_solar_output_contract(box):
        return "set_amp_autonomous_solar"
    physical = box.get("_physical_budget")
    token = str(box.get("_wallbox_cycle_token") or "")
    current_normal = bool(
        token
        and isinstance(contract, dict)
        and contract.get("contract") == "wallbox_autonomous_solar_output_v1"
        and contract.get("active") is False
        and str(contract.get("cycle_token") or "") == token
        and contract.get("method") == "set_amp_sonnenmodus"
        and contract.get("strict_watt_cap") is True
        and isinstance(physical, dict)
        and physical.get("strict_watt_cap") is True
        and physical.get("watt_budget_semantics") == "strict_phase_projection"
    )
    if current_normal:
        return "set_amp_sonnenmodus"
    charger = box.get("charger")
    stale_autonomous = bool(
        isinstance(contract, dict)
        and contract.get("contract") == "wallbox_autonomous_solar_output_v1"
        and contract.get("active") is True
    )
    driver_mode_1 = bool(
        getattr(charger, "sonnenmodus", False) is True
        or getattr(charger, "_last_extern_mode", None) == 1
    )
    if stale_autonomous or driver_mode_1:
        return ""
    return "set_amp_sonnenmodus"


def _native_group_deficit_current_output_method(c_data, status=None):
    """Erhält für eine Absenkung den belegten laufenden WBchar6-Modus.

    Ein Storage-Deckel von 0 setzt den Treiber absichtlich auf Ausgangsstille.
    Das darf eine bereits physisch laufende Ladung nicht aus dem zentralen
    Abwärtsregler entfernen. In diesem Fall wird der Modus ausschließlich aus
    dem frischen RSCP-Readback wiederaufgenommen. Fehlt diese Evidenz, bleibt
    der Ausgang gesperrt; insbesondere fällt eine efy nicht still von ihrer
    Eigenautomatik auf den externen Mode-2-Pfad zurück.
    """

    box = c_data if isinstance(c_data, dict) else {}
    st = status if isinstance(status, dict) else {}
    charger = box.get("charger")
    if not e3dc_session.is_e3dc_native_charger(charger):
        return ""
    autonomous = _current_autonomous_solar_output_contract(box)
    sun_mode_active = (
        st.get("sun_mode_active")
        if type(st.get("sun_mode_active")) is bool
        else None
    )
    if sun_mode_active is True:
        if autonomous:
            return "set_amp_autonomous_solar"
        # Multi Connect/efy bildet den belegten Mode 1 nur über den
        # explizit versiegelten autonomen Ausgang ab. Dessen generische
        # ``set_amp_sonnenmodus``-Methode sendet dagegen Mode 2.
        if hasattr(charger, "set_amp_autonomous_solar"):
            return ""
        return "set_amp_sonnenmodus"
    if sun_mode_active is False:
        return "set_amp_and_state"

    # Ohne frischen Modus-Readback darf nur eine noch aktive, nicht durch den
    # Storage-Deckel pausierte Managergeneration fortgesetzt werden.
    if getattr(charger, "external_suspended", True) is True:
        return ""
    if autonomous:
        return "set_amp_autonomous_solar"
    if getattr(charger, "sonnenmodus", False) is True:
        if hasattr(charger, "set_amp_autonomous_solar"):
            return ""
        return "set_amp_sonnenmodus"
    return "set_amp_and_state"


def _rebind_autonomous_solar_watt_authority(c_data, *, min_amp=6):
    """Projiziert nur einen aktuellen efy-Floor-Vertrag auf die 1p-Wattkante."""

    box = c_data if isinstance(c_data, dict) else {}
    output = _current_autonomous_solar_output_contract(box)
    cap = box.get("_authorized_wallbox_watt_output_cap")
    if not (
        output
        and isinstance(cap, dict)
        and cap.get("active") is True
        and cap.get("cycle_token") == box.get("_wallbox_cycle_token")
    ):
        return False
    ready = bool(_cfg_float(cap.get("cap_w"), 0.0) + 1e-9 >= float(min_amp) * 230.0)
    box["_autonomous_solar_watt_projection"] = {
        "contract": "efy_autonomous_solar_watt_projection_v1",
        "active": ready,
        "method": "set_amp_autonomous_solar",
        "phases": 1,
        "watt_budget_semantics": "autonomous_pv_sink",
        "strict_watt_cap": False,
        "cycle_token": box.get("_wallbox_cycle_token"),
    }
    command_gate.set_storage_power_budget_hard_block(
        box.get("charger"),
        not ready,
        reason="efy_autonomous_floor_budget_below_1p_minimum",
    )
    return ready


def _seal_autonomous_solar_driver_command(c_data, command):
    """Versiegelt Mode 1 erst an der letzten Manager-I/O-Kante."""

    box = c_data if isinstance(c_data, dict) else {}
    cmd = command if isinstance(command, dict) else {}
    if str(cmd.get("method") or "") != "set_amp_autonomous_solar":
        return True
    output = _current_autonomous_solar_output_contract(box)
    if not output:
        return False
    requested_amp = max(0.0, _cfg_float(cmd.get("amp"), 0.0))
    try:
        force_state = (
            None
            if cmd.get("force_state") is None
            else int(round(float(cmd.get("force_state"))))
        )
    except (TypeError, ValueError):
        force_state = None
    positive_charge_output = bool(requested_amp > 0.0 and force_state != 1)
    if positive_charge_output:
        reservation = box.get("_multi_allocation_output_cap")
        reservation = reservation if isinstance(reservation, dict) else {}
        cycle_token = str(box.get("_wallbox_cycle_token") or "")
        try:
            reserved_vector = tuple(
                float(value)
                for value in reservation.get(
                    "reserved_phase_vector_a",
                    (),
                )
            )
        except (TypeError, ValueError):
            reserved_vector = ()
        reservation_current = bool(
            reservation.get("active") is True
            and cycle_token
            and str(reservation.get("cycle_token") or "") == cycle_token
            and int(
                _cfg_float(
                    reservation.get("electrical_reservation_phases"),
                    0.0,
                )
            ) == 3
            and _cfg_float(reservation.get("cap_amp"), 0.0)
            + 1e-9
            >= requested_amp
            and len(reserved_vector) == 3
            and all(
                math.isfinite(value) and value + 1e-9 >= requested_amp
                for value in reserved_vector
            )
        )
        box["_electrical_capacity_output_gate"] = {
            "contract": "wallbox_electrical_capacity_output_gate_v1",
            "active": reservation_current,
            "requested_amp": requested_amp,
            "electrical_reservation_phases": int(
                _cfg_float(
                    reservation.get("electrical_reservation_phases"),
                    0.0,
                )
            ),
            "reserved_phase_vector_a": reserved_vector,
            "cycle_token": cycle_token,
            "reason": (
                "current_electrical_capacity_reserved"
                if reservation_current
                else "electrical_capacity_reservation_missing_or_stale"
            ),
        }
        if not reservation_current:
            return False
    authority = _wallbox_command_executor.seal_autonomous_solar_dispatch(
        box.get("charger") or cmd.get("charger"),
        output,
        cycle_token=box.get("_wallbox_cycle_token"),
        amp=cmd.get("amp", 0.0),
        force_state=cmd.get("force_state"),
    )
    if not authority:
        return False
    cmd["_autonomous_solar_dispatch_authority"] = authority
    return True

def _openwb_physical_amp_down_required(
    public_mode,
    current_amp,
    cap_amp,
    grid_power_w,
    *,
    charger_is_openwb_like=False,
    grid_allowed=False,
    price_active=False,
    price_boost_active=False,
    predump_active=False,
    threshold_w=-250.0,
):
    """Return whether an openWB-like charger must follow a lower physical cap now."""
    try:
        current_i = int(round(float(current_amp or 0)))
    except (TypeError, ValueError):
        current_i = 0
    try:
        cap_i = int(round(float(cap_amp or 0)))
    except (TypeError, ValueError):
        cap_i = 0
    try:
        grid_w = float(grid_power_w or 0.0)
    except (TypeError, ValueError):
        grid_w = 0.0
    try:
        threshold = float(threshold_w if threshold_w is not None else -250.0)
    except (TypeError, ValueError):
        threshold = -250.0

    return bool(
        charger_is_openwb_like
        and storage_floor_mode(public_mode)
        and cap_i > 0
        and current_i > cap_i
        and grid_w > threshold
        and not (grid_allowed or price_active or price_boost_active or predump_active)
    )

def _log_state_once(state_obj, slot, key, message, level="info", min_interval_s=0.0):
    """Log normal control states only when their semantic state changes."""
    now_ts = time.time()
    store = state_obj.setdefault("_quiet_log_state", {})
    prev = store.get(slot) or {}
    due = bool(min_interval_s and now_ts - float(prev.get("ts", 0.0) or 0.0) >= min_interval_s)
    if prev.get("key") == key and not due:
        return False
    getattr(logger, level)(message)
    store[slot] = {"key": key, "ts": now_ts}
    return True

