def _native_wallbox_type_label(current_label, wb_details):
    """Stellt die E3/DC-Produktfamilie getrennt vom gemeinsamen RSCP-Backend bereit."""
    details = wb_details if isinstance(wb_details, list) else []
    if len(details) != 1:
        return current_label
    detail = details[0] if isinstance(details[0], dict) else {}
    if detail.get("e3dc_transport") != "e3dc_rscp_via_home_power_station":
        return current_label
    family = str(detail.get("e3dc_device_family") or "unknown").strip().lower()
    return {
        "efy": "E3/DC Wallbox efy",
        "easy_connect": "E3/DC Easy Connect",
        "multi_connect": "E3/DC Multi Connect",
        "multi_connect_ii": "E3/DC Multi Connect II",
    }.get(family, "E3/DC Wallbox")

def _wallbox_global_max_amp(config, fallback_amp=16):
    global_amp = _amp_limit((config or {}).get("wbmaxladestrom", (config or {}).get("wb_max_amp", fallback_amp)), fallback_amp)
    limits = [global_amp]
    for cid in (1, 2):
        for key in (f"wb{cid}_max_amp", f"wb{cid}_maxladestrom"):
            raw = (config or {}).get(key)
            if raw is not None and str(raw).strip() != "":
                limits.append(_amp_limit(raw, global_amp))
                break
    return max(limits)

def _openwb_pro_start_verify_guard_override(c_data, command, now_ts=None, reason=""):
    """Allow narrow openWB Pro start/retry keepalives through the chatter guard."""
    box = c_data if isinstance(c_data, dict) else {}
    cmd = command if isinstance(command, dict) else {}
    if not openwb_pro_session.is_openwb_pro_charger(box.get("charger")):
        return False
    now_value = time.time() if now_ts is None else float(now_ts)
    session = box.get("_openwb_pro_session") if isinstance(box.get("_openwb_pro_session"), dict) else {}
    contract = openwb_pro_session.start_retry_guard_contract(
        cmd,
        box,
        session=session,
        now_ts=now_value,
        reason=reason,
    )
    box["_openwb_pro_start_retry_guard_contract"] = contract
    return bool(contract.get("allow_override", False))


def _wallbox_driver_observe_only_noop(c_data, command):
    """Erkenne nur den kanonischen, bereits ausgangslosen Planner-NOOP."""
    box = c_data if isinstance(c_data, dict) else {}
    cmd = command if isinstance(command, dict) else {}
    if str(cmd.get("kind") or "").strip() != "observe_only":
        return False
    if cmd.get("method") not in (None, ""):
        return False
    charger = box.get("charger") or cmd.get("charger")
    if charger is None:
        return False
    ctx = getattr(charger, "_command_gate_context", None)
    if not isinstance(ctx, dict) or not bool(ctx.get("observe_only", False)):
        return False
    if _emergency_wallbox_output_command(cmd):
        return False
    if command_gate.is_default_release_allowed(charger):
        return False
    return True


def _discard_wallbox_command_guard_pending(c_data):
    """Verwirf eine nur bewertete Guard-Absicht ohne persistente Historie."""

    box = c_data if isinstance(c_data, dict) else {}
    pending = box.pop("_command_guard_pending_commit", None)
    if isinstance(pending, dict):
        box["_command_guard_uncommitted_intent"] = dict(
            pending.get("decision") or {}
        )


def _commit_wallbox_command_guard_after_receipt(
    c_data,
    command,
    *,
    previous_receipt=None,
    stop_receipt_confirmed=False,
):
    """Committe Guard-Historie erst nach gleichzyklischem Ausgangsbeleg."""

    box = c_data if isinstance(c_data, dict) else {}
    cmd = command if isinstance(command, dict) else {}
    pending = box.get("_command_guard_pending_commit")
    if not isinstance(pending, dict):
        return False
    cycle_token = str(box.get("_wallbox_cycle_token") or "")
    if (
        not cycle_token
        or str(pending.get("cycle_token") or "") != cycle_token
    ):
        _discard_wallbox_command_guard_pending(box)
        return False
    decision = pending.get("decision")
    if not isinstance(decision, dict) or decision.get("allowed") is not True:
        _discard_wallbox_command_guard_pending(box)
        return False
    canonical_stop = _canonical_guarded_stop_command(cmd)
    if canonical_stop and not stop_receipt_confirmed:
        return False
    receipt = box.get("_last_executed_command")
    if not stop_receipt_confirmed:
        expected_method = str(
            pending.get("expected_method")
            or cmd.get("method")
            or cmd.get("kind")
            or ""
        )
        expected_reason = str(
            pending.get("expected_reason")
            or decision.get("reason")
            or cmd.get("reason")
            or expected_method
        )
        if not (
            isinstance(receipt, dict)
            and receipt is not previous_receipt
            and str(receipt.get("cycle_token") or "") == cycle_token
            and str(receipt.get("method") or "") == expected_method
            and str(receipt.get("reason") or "") == expected_reason
        ):
            return False
    try:
        control_command_guard.commit_wallbox_command_decision(
            decision,
            start_stop_gap_s=int(pending.get("start_stop_gap_s", 180) or 180),
            phase_gap_s=int(pending.get("phase_gap_s", 300) or 300),
        )
    except Exception as exc:
        box["_command_guard_commit_error"] = {
            "reason": str(exc),
            "cycle_token": cycle_token,
        }
        _discard_wallbox_command_guard_pending(box)
        return False
    box.pop("_command_guard_pending_commit", None)
    box.pop("_command_guard_uncommitted_intent", None)
    box.pop("_command_guard_commit_error", None)
    box["_command_guard_decision"] = decision
    return True


def _wallbox_command_guard_allows(c_data, command, c_id=None, reason=""):
    """Inline safety guard before a command reaches a real wallbox driver."""
    box = c_data if isinstance(c_data, dict) else {}
    cmd = command if isinstance(command, dict) else {}
    if bool(cmd.get("_control_guard_checked", False)):
        return True
    try:
        wb_id = int(c_id if c_id is not None else box.get("id", cmd.get("wb_id", 0)) or 0)
    except Exception:
        wb_id = 0
    if _openwb_pro_mode0_output_binding_matches(box, cmd):
        decision = {
            "ts": round(time.time(), 3),
            "service": "control_command_guard",
            "domain": "wallbox",
            "actor": "wallbox:%d" % max(0, wb_id),
            "wb_id": int(wb_id),
            "action": str(cmd.get("method") or "MODE0_SAFE_HANDOFF"),
            "allowed": True,
            "decision": "typed_mode0_safe_handoff",
            "reason": "mode0_default_release",
            "block_reason": "",
            "target_reachable": bool(cmd.get("target_reachable", True)),
            "command": {
                key: cmd.get(key)
                for key in ("kind", "method", "max_amp", "enabled", "reason")
                if key in cmd
            },
            "candidate_event": None,
            "violations": [],
        }
        box["_command_guard_decision"] = decision
        cmd["_control_guard_checked"] = True
        cmd["command_guard"] = decision
        return True
    if _wallbox_driver_observe_only_noop(box, cmd):
        decision = {
            "ts": round(time.time(), 3),
            "service": "control_command_guard",
            "domain": "wallbox",
            "actor": "wallbox:%d" % max(0, wb_id),
            "wb_id": int(wb_id),
            "action": "NOOP",
            "allowed": True,
            "decision": "observe_only_noop",
            "reason": str(reason or cmd.get("reason") or "openwb_primary_observe_only"),
            "block_reason": "",
            "target_reachable": bool(cmd.get("target_reachable", True)),
            "command": {
                key: cmd.get(key)
                for key in ("kind", "method", "amp", "force_state", "reason")
                if key in cmd
            },
            "candidate_event": None,
            "violations": [],
        }
        box["_command_guard_decision"] = decision
        cmd["_control_guard_checked"] = True
        cmd["command_guard"] = decision
        return True
    try:
        start_stop_gap_s = max(
            0,
            int(round(_cfg_float(box.get("_command_guard_start_stop_gap_s"), 180.0))),
        )
        phase_gap_s = max(
            0,
            int(round(_cfg_float(box.get("_command_guard_phase_gap_s"), 300.0))),
        )
        guard_cmd = cmd
        guard_reason = reason or str(cmd.get("reason", ""))
        if _openwb_pro_start_verify_guard_override(box, cmd, reason=guard_reason):
            guard_cmd = dict(cmd)
            guard_cmd["_guard_allow_restart_after_stop"] = True
            if "openwb_pro_start_verifying" not in guard_reason:
                guard_reason = (guard_reason + " openwb_pro_start_verifying").strip()
        guard_method = str(guard_cmd.get("method") or guard_cmd.get("kind") or "").strip()
        if (
            guard_method in (
                "set_current",
                "set_amp_and_state",
                "set_amp_sonnenmodus",
                "set_amp_autonomous_solar",
                "set_direct_current",
            )
            and _cfg_float(guard_cmd.get("amp"), 0.0) > 0.0
            and bool(box.get("is_charging", False))
        ):
            if guard_cmd is cmd:
                guard_cmd = dict(cmd)
            guard_cmd["_guard_actor_active"] = True
        decision = control_command_guard.evaluate_wallbox_command(
            guard_cmd,
            wb_id=wb_id,
            reason=guard_reason,
            target_reachable=bool(guard_cmd.get("target_reachable", True)),
            start_stop_gap_s=start_stop_gap_s,
            phase_gap_s=phase_gap_s,
            commit=False,
        )
    except Exception as exc:
        emergency_bypass = _emergency_wallbox_output_command(cmd)
        decision = {
            "ts": round(time.time(), 3),
            "service": "control_command_guard",
            "domain": "wallbox",
            "actor": "wallbox:%d" % max(0, wb_id),
            "wb_id": int(wb_id),
            "action": str(cmd.get("method") or cmd.get("kind") or "UNKNOWN"),
            "allowed": bool(emergency_bypass),
            "decision": (
                "guard_error_emergency_bypass"
                if emergency_bypass
                else "guard_error_fail_closed"
            ),
            "reason": str(reason or cmd.get("reason") or "command_guard_error"),
            "block_reason": (
                ""
                if emergency_bypass
                else "command_guard_internal_error"
            ),
            "target_reachable": bool(cmd.get("target_reachable", True)),
            "command": {
                key: cmd.get(key)
                for key in ("kind", "method", "amp", "force_state", "reason")
                if key in cmd
            },
            "candidate_event": None,
            "violations": ([] if emergency_bypass else ["guard_internal_error"]),
            "error_type": exc.__class__.__name__,
        }
        _discard_wallbox_command_guard_pending(box)
        box["_command_guard_decision"] = decision
        cmd["_control_guard_checked"] = True
        cmd["command_guard"] = decision
        logger.error(
            "WB%s Command-Guard intern fehlgeschlagen (%s); %s.",
            wb_id if wb_id else "?",
            exc.__class__.__name__,
            (
                "typisierter Sicherheits-Stopp bleibt freigegeben"
                if emergency_bypass
                else "Hardwareausgang fail-closed blockiert"
            ),
        )
        return bool(emergency_bypass)
    box["_command_guard_decision"] = decision
    cmd["_control_guard_checked"] = True
    cmd["command_guard"] = decision
    if decision.get("allowed", True):
        box["_command_guard_pending_commit"] = {
            "decision": decision,
            "cycle_token": str(box.get("_wallbox_cycle_token") or ""),
            "wb_id": int(wb_id),
            "start_stop_gap_s": int(start_stop_gap_s),
            "phase_gap_s": int(phase_gap_s),
            "expected_method": str(
                cmd.get("method") or cmd.get("kind") or ""
            ),
            "expected_reason": str(
                cmd.get("reason")
                or reason
                or cmd.get("method")
                or cmd.get("kind")
                or ""
            ),
        }
        return True
    control_command_guard.commit_wallbox_command_decision(
        decision,
        start_stop_gap_s=start_stop_gap_s,
        phase_gap_s=phase_gap_s,
    )
    now_value = time.time()
    last_log = float(box.get("_last_command_guard_block_log_ts", 0.0) or 0.0)
    if now_value - last_log >= 30.0:
        box["_last_command_guard_block_log_ts"] = now_value
        if wb_id:
            logger.warning(
                "WB%d Command-Guard blockiert %s (%s)",
                wb_id,
                cmd.get("kind", cmd.get("method", "driver_command")),
                decision.get("block_reason", "command_chatter_guard"),
            )
        else:
            logger.warning(
                "Wallbox Command-Guard blockiert %s (%s)",
                cmd.get("kind", cmd.get("method", "driver_command")),
                decision.get("block_reason", "command_chatter_guard"),
            )
    return False


def _wallbox_command_guard_is_observe_only_noop(c_data, command):
    box = c_data if isinstance(c_data, dict) else {}
    cmd = command if isinstance(command, dict) else {}
    decision = cmd.get("command_guard")
    if not isinstance(decision, dict):
        decision = box.get("_command_guard_decision")
    return bool(isinstance(decision, dict) and decision.get("decision") == "observe_only_noop")


def _guard_e3dc_native_driver_edge(box, command, *, charger=None, c_id=None, reason=""):
    """Strip unsafe E3DC-native start/stop toggle impulses before driver IO."""

    data = box if isinstance(box, dict) else {}
    cmd = dict(command or {})
    active_charger = charger if charger is not None else data.get("charger")
    if not e3dc_session.is_e3dc_native_charger(active_charger):
        return cmd, {"action": "not_e3dc_native", "execute": True}
    if cmd.get("_native_e3dc_floor_start_edge_marker"):
        # Der experimentelle Floor-Marker besitzt in diesem Release keinerlei
        # Ausgangsautorität. Auch ein formal alter/gültiger Marker darf weder
        # den Session-Guard umgehen noch als force_state=2 bis zum Treiber
        # gelangen.
        release = _native_e3dc_floor_retry_not_released_contract(
            data,
            source="native_edge_guard",
        )
        data[
            "_native_e3dc_floor_zero_anchor_retry_release"
        ] = dict(release)
        decision = {
            "action": "floor_start_edge_not_released",
            "execute": False,
            "reason": str(release.get("reason") or "EVIDENCE_LIMIT"),
            "release_status": "EVIDENCE_LIMIT",
            "hardware_output_allowed": False,
            "ts": time.time(),
        }
        data["_e3dc_edge_guard_decision"] = dict(decision)
        return cmd, decision

    contract_box = data
    if data.get("charger") is None and active_charger is not None:
        contract_box = dict(data)
        contract_box["charger"] = active_charger
    contract = _wallbox_e3dc_native_production_contract(contract_box, None, None)
    if contract.get("enabled", False):
        data["_e3dc_native_contract"] = contract

    session = data.get("_e3dc_session") if isinstance(data.get("_e3dc_session"), dict) else None
    driver_bounded_start_retry_ready = False
    try:
        force_state = cmd.get("force_state")
        force_state = None if force_state is None else int(round(float(force_state)))
    except (TypeError, ValueError):
        force_state = None
    bounded_retry_gate = getattr(active_charger, "e3dc_bounded_start_retry_ready", None)
    if force_state == 2 and callable(bounded_retry_gate):
        try:
            driver_bounded_start_retry_ready = bool(bounded_retry_gate())
        except Exception:
            driver_bounded_start_retry_ready = False
    if (
        driver_bounded_start_retry_ready
        and isinstance(session, dict)
        and not session.get("start_blocked", False)
    ):
        # Der Session-Guard bleibt für Sperr-, Ende- und Stoppzustände maßgeblich.
        # Bei einer Easy Connect mit frischem physischem STOP-Readback besitzt
        # jedoch allein der Treiber Versuchsanzahl und Wiederholungsabstand.
        session = dict(session)
        session["can_send_start_toggle"] = True
    typed_stop_authority = bool(
        _canonical_guarded_stop_command(cmd)
        and _valid_typed_wallbox_stop_authority(cmd.get("stop_authority"))
    )
    verified_active_charge = _e3dc_native_verified_active_charge(data)
    guard = e3dc_session.guard_edge_command(
        cmd,
        session,
        hard_stop_allowed=bool(
            verified_active_charge
            and (
                _native_e3dc_hard_stop_allowed(reason)
                or typed_stop_authority
            )
        ),
        verified_active_charge=verified_active_charge,
        min_amp=cmd.get("min_amp", data.get("min_amp", 6)),
    )
    guarded_cmd = guard.get("command", cmd)
    decision = guard.get("decision", {}) if isinstance(guard, dict) else {}
    decision = dict(decision if isinstance(decision, dict) else {})
    decision["driver_bounded_start_retry_ready"] = bool(driver_bounded_start_retry_ready)
    decision["typed_stop_authority"] = bool(typed_stop_authority)
    decision["typed_stop_verified_active_charge"] = bool(
        typed_stop_authority and verified_active_charge
    )
    decision["reason"] = str(reason or cmd.get("reason") or cmd.get("method") or "")
    decision["ts"] = time.time()
    data["_e3dc_edge_guard_decision"] = decision

    action = str(decision.get("action") or "unchanged")
    if action not in ("unchanged", "start_toggle_allowed", "stop_toggle_allowed"):
        last_log = float(data.get("_e3dc_edge_guard_last_log_ts", 0.0) or 0.0)
        now_value = float(decision.get("ts", time.time()) or time.time())
        if now_value - last_log >= 30.0:
            data["_e3dc_edge_guard_last_log_ts"] = now_value
            logger.info(
                "WB%s E3DC-Flankengate: %s (%s, Session=%s, force %s->%s, amp %s->%s)"
                % (
                    c_id if c_id is not None else "?",
                    action,
                    decision.get("reason", ""),
                    decision.get("session_state", ""),
                    decision.get("original_force_state"),
                    decision.get("force_state"),
                    decision.get("original_amp"),
                    decision.get("amp"),
                )
            )
    return guarded_cmd, decision


def _openwb_pro_driver_status(box, charger=None):
    active = charger if charger is not None else (box or {}).get("charger")
    state = getattr(active, "state", None)
    return state if isinstance(state, dict) else {}


def _openwb_pro_fresh_connected_output_status(
    box,
    charger,
    *,
    action,
    c_id=None,
):
    """Bindet einen echten Anschluss-Read unmittelbar vor einer Pro-Ausgabe."""

    data = box if isinstance(box, dict) else {}
    active = charger if charger is not None else data.get("charger")
    now_ts = time.time()
    raw_status = None
    read_error = ""
    try:
        raw_status = active.get_status() if active is not None else None
    except Exception as exc:
        read_error = exc.__class__.__name__
    status = _wallbox_driver_status_or_stale(
        data,
        raw_status,
        now_ts=now_ts,
        stale_guard_s=0.0,
    )
    raw_fresh = bool(
        isinstance(raw_status, dict)
        and raw_status
        and raw_status.get("driver_status_valid") is not False
        and raw_status.get("driver_status_stale") is not True
        and raw_status.get("driver_status_degraded") is not True
        and raw_status.get("driver_status_plausible") is not False
        and raw_status.get("driver_status_glitch") is not True
    )
    normalized_fresh = bool(
        isinstance(status, dict)
        and status.get("driver_status_valid") is True
        and status.get("driver_status_stale") is not True
        and status.get("driver_status_degraded") is not True
        and status.get("driver_status_plausible") is not False
        and status.get("driver_status_glitch") is not True
    )
    try:
        car_state = int(status.get("car", 0) or 0)
    except (TypeError, ValueError):
        car_state = 0
    connected = bool(
        raw_fresh
        and normalized_fresh
        and (status.get("plug_state") is True or car_state == 2)
    )
    data["_openwb_pro_connected_output_gate"] = {
        "contract": "openwb_pro_connected_output_gate_v1",
        "action": str(action or ""),
        "allowed": connected,
        "fresh": bool(raw_fresh and normalized_fresh),
        "connected": connected,
        "read_error": read_error,
        "ts": now_ts,
    }
    if not connected:
        logger.info(
            "WB%s openWB-Pro-Ausgang %s ohne frischen Anschlussbeleg blockiert.",
            c_id if c_id is not None else data.get("id", "?"),
            str(action or "output"),
        )
    return status, connected


def _openwb_pro_phase_output_capability_gate(
    box,
    charger,
    *,
    c_id=None,
    action="set_phases",
):
    """Bindet jeden Pro-Phasenausgang an frische Herstellerbelege.

    Die Existenz einer Python-Methode ist keine Gerätefähigkeit. Vor einer
    Sequenz – und damit insbesondere vor deren 0-A-Flanke – müssen die
    offizielle ``connect.php``-Fläche, IEC-61851-Signalisierung und ein
    optionales Fahrzeugprofil-Veto frisch bestätigt sein. HLC/ISO-15118
    bleibt entsprechend dem openWB-Core immer gesperrt.
    """

    data = box if isinstance(box, dict) else {}
    active = charger if charger is not None else data.get("charger")
    status, connected = _openwb_pro_fresh_connected_output_status(
        data,
        active,
        action=str(action or "set_phases"),
        c_id=c_id,
    )
    config = (
        data.get("_openwb_pro_config")
        if isinstance(data.get("_openwb_pro_config"), dict)
        else {}
    )
    capability = _openwb_phase_switch_capability(
        active.__class__.__name__ if active is not None else "",
        status,
        config,
    )
    vehicle_capability = VehicleManager.vehicle_phase_capability(
        status=status,
        profiles=_load_saved_car_profiles(),
        config=config,
        charger_id=(c_id if c_id is not None else data.get("id", 1)),
    )
    vehicle_veto_contract = wallbox_decision.vehicle_phase_switch_veto_contract(
        vehicle_capability,
        status,
    )
    vehicle_veto = vehicle_veto_contract.get("active") is True
    method_present = bool(active is not None and hasattr(active, "set_phases"))
    allowed = bool(
        connected
        and method_present
        and capability.get("can_switch") is True
        and not vehicle_veto
    )
    if not connected:
        blocker = "fresh_connected_status_missing"
    elif not method_present:
        blocker = "driver_set_phases_missing"
    elif capability.get("can_switch") is not True:
        blocker = str(capability.get("blocker") or "phase_capability_unverified")
    elif vehicle_veto:
        blocker = "vehicle_profile_phase_switch_veto"
    else:
        blocker = ""
    cycle_token = str(data.get("_wallbox_cycle_token") or "")
    capability_diagnostic = dict(capability)
    vehicle_capability_diagnostic = dict(vehicle_capability)
    vehicle_veto_diagnostic = dict(vehicle_veto_contract)
    for diagnostic in (
        capability_diagnostic,
        vehicle_capability_diagnostic,
        vehicle_veto_diagnostic,
    ):
        diagnostic["cycle_token"] = cycle_token
    contract = {
        "contract": "openwb_pro_phase_output_capability_gate_v1",
        "action": str(action or "set_phases"),
        "allowed": allowed,
        "blocker": blocker,
        "connected": bool(connected),
        "method_present": method_present,
        "phase_capability": capability_diagnostic,
        "vehicle_phase_capability": vehicle_capability_diagnostic,
        "vehicle_phase_switch_veto": vehicle_veto_diagnostic,
        "cycle_token": cycle_token,
        "ts": time.time(),
    }
    data["_openwb_pro_phase_output_capability_gate"] = contract
    data["_vehicle_phase_capability"] = vehicle_capability_diagnostic
    data["_vehicle_phase_switch_veto"] = vehicle_veto_diagnostic
    if not allowed:
        data["_wallbox_driver_dispatch_contract"] = {
            **(
                data.get("_wallbox_driver_dispatch_contract")
                if isinstance(data.get("_wallbox_driver_dispatch_contract"), dict)
                else {}
            ),
            "blocked": True,
            "blocker": blocker,
            "wire_attempted": False,
        }
        logger.info(
            "WB%s openWB-Pro-Phasenausgang fail-closed blockiert (%s).",
            c_id if c_id is not None else data.get("id", "?"),
            blocker,
        )
    return contract, status


def _openwb_pro_status_connected_idle(box, charger=None):
    st = _openwb_pro_driver_status(box, charger)
    connected = bool(st.get("plug_state") or st.get("car") == 2)
    real_power_w = max(
        _cfg_float(st.get("real_power_w"), 0.0),
        _cfg_float(st.get("phase_power_sum_w"), 0.0),
        _cfg_float(st.get("power_w"), 0.0),
    )
    charging = bool(st.get("charging") or st.get("charge_state") or real_power_w > 500.0)
    return connected, charging, real_power_w


def _openwb_pro_cp_payload_from_config(config=None, status=None):
    return openwb_pro_session.start_cp_interrupt_payload(config, status)


def _openwb_pro_phase_cp_payload_from_config(config=None, status=None):
    return openwb_pro_session.phase_cp_interrupt_payload(config, status)


def _openwb_pro_control_time_sample(
    *,
    wall_ts=None,
    monotonic_ts=None,
    boot_id=None,
    process_epoch_id=None,
):
    """Liefert die injizierbare Zeitprobe der Phasen-Schutzverträge."""

    return control_time.sample(
        wall_ts=wall_ts,
        monotonic_ts=monotonic_ts,
        boot_id=(
            _wallbox_phase_boot_id()
            if boot_id is None
            else boot_id
        ),
        process_epoch_id=process_epoch_id,
    )


def _phase_output_intent(data, action, contract, now_ts):
    proposal = contract if isinstance(contract, dict) else {}
    command = proposal.get("command") if isinstance(proposal.get("command"), dict) else {}
    reservation = data.get("_wallbox_phase_transition_reservation")
    transition_id = (
        str(reservation.get("transition_id") or "")
        if isinstance(reservation, dict)
        else ""
    )
    intent = {
        "schema": "openwb_pro_phase_output_intent_v1",
        "intent_id": "%s:%s:%d" % (
            transition_id or str(data.get("id", 0) or 0),
            str(action or "phase_output"),
            time.monotonic_ns(),
        ),
        "action": str(action or "phase_output"),
        "method": str((command or {}).get("method") or ""),
        "target": int(
            (command or {}).get(
                "phases",
                (command or {}).get(
                    "target_phases",
                    proposal.get("target", 0),
                ),
            )
            or 0
        ),
        "duration_s": int((command or {}).get("duration", 0) or 0),
        "wall_ts": float(now_ts),
        "transition_id": transition_id,
    }
    sequence = proposal.get("sequence")
    if isinstance(sequence, dict) and sequence:
        intent["sequence_after"] = sequence
    sequence_patch = proposal.get("sequence_patch")
    if isinstance(sequence_patch, dict) and sequence_patch:
        intent["sequence_patch"] = sequence_patch
    data["_openwb_pro_phase_output_intent"] = intent
    data.pop("_openwb_pro_phase_output_ack", None)
    return intent


def _phase_output_recovery_hold(data, reason, intent=None):
    intent_item = intent if isinstance(intent, dict) else {}
    reservation = data.get("_wallbox_phase_transition_reservation")
    reservation = reservation if isinstance(reservation, dict) else {}
    reservation_id = str(
        reservation.get("transition_id")
        or reservation.get("reservation_id")
        or ""
    )
    hold = {
        "active": True,
        "reason": str(reason or "phase_output_unconfirmed"),
        "target": int(intent_item.get("target", 0) or 0),
        "intent_id": str(intent_item.get("intent_id") or ""),
        "reservation_id": reservation_id,
        "transition_id": reservation_id,
    }
    data["_openwb_pro_phase_recovery_hold"] = hold
    data["_openwb_pro_phase_sequence_stage"] = "recovery_hold"
    wallbox_phase_transition.set_stage(
        data,
        "recovery_hold",
        now_ts=time.time(),
        reason_code=hold["reason"],
    )


def _persist_phase_output_intent(data, action, contract, now_ts):
    intent = _phase_output_intent(data, action, contract, now_ts)
    reservation = data.get("_wallbox_phase_transition_reservation")
    if not wallbox_phase_transition.grant_is_sufficient(reservation):
        _phase_output_recovery_hold(
            data,
            "phase_output_without_sufficient_grant",
            intent,
        )
        _save_wallbox_phase_state([data])
        return None
    committed = wallbox_phase_transition.mark_committed(
        data,
        stage=("set_phase" if action == "send_phase" else "ramp_to_zero"),
        now_ts=now_ts,
    )
    if not (
        str(committed.get("grant_state") or "") == "committed"
        and int(committed.get("requested_w", 0) or 0) > 0
        and int(committed.get("committed_w", 0) or 0)
        >= int(committed.get("requested_w", 0) or 0)
    ):
        _phase_output_recovery_hold(
            data,
            "phase_output_commit_failed",
            intent,
        )
        _save_wallbox_phase_state([data])
        return None
    committed = dict(committed)
    committed.update({
        "commit_source": "openwb_pro_internal_phase_output_intent",
        "commit_intent_id": str(intent.get("intent_id") or ""),
        "commit_action": str(action or ""),
    })
    data["_wallbox_phase_transition_reservation"] = committed
    if _save_wallbox_phase_state([data]):
        return intent
    _phase_output_recovery_hold(data, "phase_intent_persist_failed", intent)
    return None


def _persist_phase_output_ack(data, intent, success, reason=""):
    intent_item = intent if isinstance(intent, dict) else {}
    intent_patch = intent_item.get("sequence_patch")
    intent_patch = intent_patch if isinstance(intent_patch, dict) else {}
    wire_receipt_ts = max(
        _cfg_float(intent_item.get("wire_receipt_ts"), 0.0),
        _cfg_float(intent_patch.get("wire_receipt_ts"), 0.0),
    )
    ack = {
        "schema": "openwb_pro_phase_output_ack_v1",
        "intent_id": str(intent_item.get("intent_id") or ""),
        "success": bool(success),
        "reason": str(reason or ("confirmed" if success else "driver_result_unconfirmed")),
        "wall_ts": time.time(),
        **(
            {"wire_receipt_ts": wire_receipt_ts}
            if wire_receipt_ts > 0.0
            else {}
        ),
    }
    data["_openwb_pro_phase_output_ack"] = ack
    if not success:
        _phase_output_recovery_hold(data, ack["reason"], intent)
    if not _save_wallbox_phase_state([data]):
        _phase_output_recovery_hold(data, "phase_ack_persist_failed", intent)
        return False
    return bool(success)


def _bind_openwb_pro_phase_post_receipt(
    data,
    intent,
    contract,
    previous_receipt,
    *,
    target,
    now_ts,
    config=None,
):
    """Bindet den bestätigten openWB-Pro-POST vor Sequenz-ACK persistent."""

    intent_item = intent if isinstance(intent, dict) else {}
    proposal = contract if isinstance(contract, dict) else {}
    command = proposal.get("command")
    command = command if isinstance(command, dict) else {}
    receipt = data.get("_last_executed_command")
    dispatch = data.get("_wallbox_driver_dispatch_contract")
    dispatch = dispatch if isinstance(dispatch, dict) else {}
    cycle_token = str(data.get("_wallbox_cycle_token") or "")
    receipt_ts = _cfg_float(
        receipt.get("ts") if isinstance(receipt, dict) else 0.0,
        0.0,
    )
    intent_ts = _cfg_float(intent_item.get("wall_ts"), 0.0)
    now_value = _cfg_float(now_ts, 0.0)
    valid = bool(
        cycle_token
        and isinstance(receipt, dict)
        and receipt is not previous_receipt
        and str(receipt.get("method") or "") == "set_phases"
        and int(_cfg_float(receipt.get("target_phases"), 0.0)) == int(target)
        and str(receipt.get("reason") or "") == "openwb_pro_phase_target"
        and str(receipt.get("cycle_token") or "") == cycle_token
        and receipt_ts > 0.0
        and math.isfinite(receipt_ts)
        and receipt_ts >= intent_ts > 0.0
        and receipt_ts <= now_value + 1.0
        and command.get("_require_wire_receipt") is True
        and command.get("_openwb_pro_sequence_internal") is True
        and dispatch.get("contract") == "wallbox_driver_dispatch_contract_v1"
        and dispatch.get("wire_attempted") is True
        and str(dispatch.get("method") or "") == "set_phases"
        and str(dispatch.get("reason") or "") == "openwb_pro_phase_target"
        and str(dispatch.get("cycle_token") or "") == cycle_token
    )
    if not valid:
        _phase_output_recovery_hold(
            data,
            "phase_target_wire_receipt_missing",
            intent_item,
        )
        _save_wallbox_phase_state([data])
        return None, None

    bound_contract = deepcopy(proposal)
    sequence_patch = dict(bound_contract.get("sequence_patch") or {})
    cfg = config if isinstance(config, dict) else {}
    phase_settle_s = max(
        openwb_pro_session.phase_min_settle_s(cfg),
        _cfg_float(
            sequence_patch.get("phase_settle_s"),
            bound_contract.get("target_settle_s"),
        ),
    )
    restart_delay_s = openwb_pro_session.phase_restart_delay_s(cfg)
    phase_cooldown_s = openwb_pro_session.phase_wait_s(cfg)
    cooldown_reservation = wallbox_phase_transition.bind_wire_cooldown(
        data,
        reservation_id=str(intent_item.get("transition_id") or ""),
        target_phases=target,
        wire_receipt_ts=receipt_ts,
        cooldown_s=phase_cooldown_s,
    )
    if not cooldown_reservation:
        _phase_output_recovery_hold(
            data,
            "phase_target_cooldown_binding_failed",
            intent_item,
        )
        _save_wallbox_phase_state([data])
        return None, None
    stage_timer = openwb_pro_session._phase_stage_timer(
        "restart_delay",
        phase_settle_s + restart_delay_s,
        None,
        _openwb_pro_control_time_sample(wall_ts=receipt_ts),
    )
    sequence_patch.update({
        "phase_sent_ts": receipt_ts,
        "wire_receipt_ts": receipt_ts,
        "phase_settle_s": phase_settle_s,
        "current_allowed_after": (
            receipt_ts + phase_settle_s + restart_delay_s
        ),
        "phase_change_block_until": receipt_ts + phase_cooldown_s,
        **(
            {openwb_pro_session.PHASE_STAGE_TIMEBASE_KEY: stage_timer}
            if isinstance(stage_timer, dict)
            else {}
        ),
    })
    bound_contract["sequence_patch"] = sequence_patch
    bound_contract["phase_wait_config"] = {
        "openwb_pro_phase_wait_s": phase_cooldown_s,
    }
    bound_intent = deepcopy(intent_item)
    bound_intent.update({
        "wire_receipt_ts": receipt_ts,
        "wire_receipt_contract": "openwb_pro_manager_post_receipt_v1",
        "sequence_patch": dict(sequence_patch),
    })
    data["_openwb_pro_phase_output_intent"] = bound_intent
    if not _save_wallbox_phase_state([data]):
        _phase_output_recovery_hold(
            data,
            "phase_target_wire_receipt_persist_failed",
            bound_intent,
        )
        return None, None
    return bound_contract, bound_intent


def _phase_output_recovery_generation_bound(data, hold, intent, status=None):
    """Bindet einen Recovery-ACK fail-closed an genau eine Reservation."""

    reservation = data.get("_wallbox_phase_transition_reservation")
    if not isinstance(reservation, dict) or reservation.get("active") is not True:
        return False
    reservation_id = str(reservation.get("reservation_id") or "")
    transition_id = str(reservation.get("transition_id") or "")
    wb_id = int(_cfg_float(reservation.get("wb_id"), 0.0))
    data_wb_id = int(_cfg_float(data.get("id"), 0.0))
    reservation_target = _valid_phase_count(
        reservation.get("target_phases"),
        0,
    )
    action = str(intent.get("action") or "")
    method = str(intent.get("method") or "")
    target = _valid_phase_count(intent.get("target"), 0)
    intent_id = str(intent.get("intent_id") or "")
    intent_transition_id = str(intent.get("transition_id") or "")
    intent_generation_bound = bool(
        intent_id.startswith(
            "%s:%s:" % (reservation_id, action)
        )
        and intent_transition_id == reservation_id
    )
    method_bound = bool(
        (action == "send_zero" and method == "set_amp_and_state")
        or (action == "send_phase" and method == "set_phases")
    )
    sequence_after = intent.get("sequence_after")
    sequence_after = (
        sequence_after if isinstance(sequence_after, dict) else {}
    )
    active_sequence = data.get("_openwb_pro_phase_sequence")
    active_sequence = (
        active_sequence if isinstance(active_sequence, dict) else {}
    )
    sequence_patch = intent.get("sequence_patch")
    sequence_patch = (
        sequence_patch if isinstance(sequence_patch, dict) else {}
    )
    hold_intent_id = str(hold.get("intent_id") or "")
    hold_reservation_id = str(hold.get("reservation_id") or "")
    hold_transition_id = str(hold.get("transition_id") or "")
    hold_target = _valid_phase_count(hold.get("target"), 0)
    hold_reason = str(hold.get("reason") or "")
    sequence_bound = bool(
        (
            action == "send_zero"
            and sequence_after.get("stage") == "zero_wait"
            and _valid_phase_count(sequence_after.get("target"), 0)
            == reservation_target
        )
        or (
            action == "send_phase"
            and sequence_patch.get("stage") == "restart_delay"
            and (
                _valid_phase_count(active_sequence.get("target"), 0) == reservation_target
                or (hold_reason == "process_restart_recovery_hold" and target in (1, 3))
            )
        )
    )
    ack = data.get("_openwb_pro_phase_output_ack")
    ack = ack if isinstance(ack, dict) else {}
    ack_success = ack.get("success")
    ack_reason = str(ack.get("reason") or "")
    negative_ack_reason = {
        "send_zero": "phase_zero_unconfirmed",
        "send_phase": "phase_target_unconfirmed",
    }.get(action, "")
    ack_bound = bool(
        ack.get("schema") == "openwb_pro_phase_output_ack_v1"
        and str(ack.get("intent_id") or "") == intent_id
        and (ack_success is True or ack_success is False)
    )
    recovery_reason_bound = bool(
        (
            ack_bound
            and (
                (
                    hold_reason == negative_ack_reason
                    and ack_success is False
                    and ack_reason == negative_ack_reason
                )
                or (
                    hold_reason == "phase_ack_persist_failed"
                    and (
                        (ack_success is True and ack_reason == "confirmed")
                        or (
                            ack_success is False
                            and ack_reason == negative_ack_reason
                        )
                    )
                )
            )
        )
        or (
            hold_reason == "process_restart_recovery_hold"
            and (
                (
                    str(hold.get("recovery_class") or "")
                    == "output_ambiguous"
                    and ack_bound
                    and ack_success is False
                    and negative_ack_reason
                    and ack_reason == negative_ack_reason
                )
                or (
                    action == "send_zero"
                    and openwb_pro_session.phase_zero_readback_confirmed(
                        status
                    )
                )
                or (
                    action == "send_phase"
                    and openwb_pro_session.phase_target_readback_confirmed(
                        status,
                        target,
                    )
                )
            )
        )
    )
    return bool(
        reservation.get("schema_version") == "wallbox_phase_transition_v2"
        and reservation_id
        and transition_id == reservation_id
        and wb_id > 0
        and wb_id == data_wb_id
        and reservation.get("owner") == "wallbox_manager"
        and reservation.get("source") == "openwb_pro_phase_sequence"
        and reservation.get("stage") == "recovery_hold"
        and reservation_target in (1, 3)
        and intent.get("schema") == "openwb_pro_phase_output_intent_v1"
        and intent_id
        and intent_generation_bound
        and method_bound
        and sequence_bound
        and (
            target == reservation_target
            or (hold_reason == "process_restart_recovery_hold" and target in (1, 3))
        )
        and (hold_intent_id == intent_id or (hold_reason == "process_restart_recovery_hold" and not hold_intent_id))
        and (hold_reservation_id == reservation_id or (hold_reason == "process_restart_recovery_hold" and not hold_reservation_id))
        and (hold_transition_id == reservation_id or (hold_reason == "process_restart_recovery_hold" and not hold_transition_id))
        and (hold_target == target or (hold_reason == "process_restart_recovery_hold" and (hold_target == 0 or hold_target in (1, 3))))
        and recovery_reason_bound
    )


def _phase_output_recovery_post_intent_readback(status, intent, now_ts):
    """Belegt für einen 0-A-Recovery einen frischen GET nach dem Intent."""

    st = status if isinstance(status, dict) else {}
    intent_item = intent if isinstance(intent, dict) else {}
    intent_ts = _cfg_float(intent_item.get("wall_ts"), 0.0)
    readback_ts = _cfg_float(st.get("driver_status_last_ok_ts"), 0.0)
    now_value = _cfg_float(now_ts, 0.0)
    if intent_ts > 100_000_000_000.0:
        intent_ts /= 1000.0
    if readback_ts > 100_000_000_000.0:
        readback_ts /= 1000.0
    return bool(
        math.isfinite(intent_ts)
        and math.isfinite(readback_ts)
        and math.isfinite(now_value)
        and intent_ts > 0.0
        and intent_ts <= now_value + 1.0
        and readback_ts > intent_ts
    )


def _resolve_stranded_phase_zero_recovery(
    data,
    status,
    hold,
    intent,
    *,
    now_ts,
):
    """Terminalisiert einen alten 0-A-Intent vor einer neuen No-output-Generation.

    Ältere Stände konnten nach Ablauf einer Reservierungslease eine neue
    ``await_budget``-Generation anlegen, während der negative ``send_zero``-
    ACK der Vorgängergeneration global erhalten blieb. Die alte Generation
    darf ausschließlich anhand ihres eigenen Intent-/ACK-Paars und eines
    frischen post-intent 0-A/0-W-Readbacks geschlossen werden. Die nachfolgende
    Reservierung bleibt dabei unverändert aktiv und erhält keinen Cooldown.
    """

    box = data if isinstance(data, dict) else {}
    st = status if isinstance(status, dict) else {}
    hold_item = hold if isinstance(hold, dict) else {}
    intent_item = intent if isinstance(intent, dict) else {}
    ack = box.get("_openwb_pro_phase_output_ack")
    ack = ack if isinstance(ack, dict) else {}
    reservation = box.get("_wallbox_phase_transition_reservation")
    reservation = reservation if isinstance(reservation, dict) else {}
    grant = box.get("_phase_transition_grant")
    grant = grant if isinstance(grant, dict) else {}

    old_id = str(intent_item.get("transition_id") or "")
    intent_id = str(intent_item.get("intent_id") or "")
    current_id = str(
        reservation.get("transition_id")
        or reservation.get("reservation_id")
        or ""
    )
    target = _valid_phase_count(intent_item.get("target"), 0)
    sequence_after = intent_item.get("sequence_after")
    sequence_after = sequence_after if isinstance(sequence_after, dict) else {}
    intent_ts = _cfg_float(intent_item.get("wall_ts"), 0.0)
    ack_ts = _cfg_float(ack.get("wall_ts"), 0.0)
    started_ts = _cfg_float(reservation.get("started_ts"), 0.0)
    readback_ts = _cfg_float(st.get("driver_status_last_ok_ts"), 0.0)
    now_value = _cfg_float(now_ts, 0.0)
    if intent_ts > 100_000_000_000.0:
        intent_ts /= 1000.0
    if ack_ts > 100_000_000_000.0:
        ack_ts /= 1000.0
    if started_ts > 100_000_000_000.0:
        started_ts /= 1000.0
    if readback_ts > 100_000_000_000.0:
        readback_ts /= 1000.0

    active_sequence = box.get("_openwb_pro_phase_sequence")
    active_restart = box.get("_openwb_pro_phase_restart_authorized")
    last_executed = box.get("_last_executed_command")
    last_executed = last_executed if isinstance(last_executed, dict) else {}
    last_output_ts = _cfg_float(last_executed.get("ts"), 0.0)
    if last_output_ts > 100_000_000_000.0:
        last_output_ts /= 1000.0
    last_output_after_successor = bool(
        str(last_executed.get("method") or "")
        in (
            "set_phases",
            "set_amp_and_state",
            "set_current",
            "set_direct_current",
            "trigger_cp_interrupt",
            "cp_interrupt",
        )
        and (last_output_ts <= 0.0 or last_output_ts >= started_ts)
    )
    cooldown_receipt_ts = _cfg_float(
        reservation.get("cooldown_wire_receipt_ts"),
        0.0,
    )

    exact = bool(
        reservation.get("schema_version")
        == "wallbox_phase_transition_v2"
        and reservation.get("active") is True
        and str(reservation.get("stage") or "") == "await_budget"
        and current_id
        and current_id != old_id
        and str(reservation.get("reservation_id") or "") == current_id
        and str(reservation.get("transition_id") or "") == current_id
        and int(_cfg_float(reservation.get("wb_id"), 0.0))
        == int(_cfg_float(box.get("id"), 0.0))
        and int(_cfg_float(reservation.get("wb_id"), 0.0)) > 0
        and str(reservation.get("owner") or "") == "wallbox_manager"
        and str(reservation.get("source") or "")
        == "openwb_pro_phase_sequence"
        and _valid_phase_count(reservation.get("target_phases"), 0) == target
        and target in (1, 3)
        and str(reservation.get("grant_state") or "") == "waiting"
        and int(_cfg_float(reservation.get("requested_w"), 0.0)) > 0
        and int(_cfg_float(reservation.get("granted_w"), 0.0)) == 0
        and int(_cfg_float(reservation.get("committed_w"), 0.0)) == 0
        and _cfg_float(reservation.get("committed_ts"), 0.0) <= 0.0
        and int(_cfg_float(reservation.get("valid_frames"), 0.0)) == 0
        and cooldown_receipt_ts <= 0.0
        and not str(reservation.get("cooldown_source") or "")
        and grant
        and str(grant.get("reservation_id") or "") == current_id
        and str(grant.get("grant_state") or "") == "waiting"
        and int(_cfg_float(grant.get("granted_w"), 0.0)) == 0
        and hold_item.get("active") is True
        and str(hold_item.get("reason") or "") == "phase_zero_unconfirmed"
        and str(hold_item.get("reservation_id") or "") == old_id
        and str(hold_item.get("transition_id") or "") == old_id
        and str(hold_item.get("intent_id") or "") == intent_id
        and _valid_phase_count(hold_item.get("target"), 0) == target
        and intent_item.get("schema") == "openwb_pro_phase_output_intent_v1"
        and old_id
        and intent_id.startswith(old_id + ":send_zero:")
        and str(intent_item.get("action") or "") == "send_zero"
        and str(intent_item.get("method") or "") == "set_amp_and_state"
        and sequence_after.get("stage") == "zero_wait"
        and _valid_phase_count(sequence_after.get("target"), 0) == target
        and ack.get("schema") == "openwb_pro_phase_output_ack_v1"
        and str(ack.get("intent_id") or "") == intent_id
        and ack.get("success") is False
        and str(ack.get("reason") or "") == "phase_zero_unconfirmed"
        and all(
            math.isfinite(value) and value > 0.0
            for value in (intent_ts, ack_ts, started_ts, readback_ts, now_value)
        )
        and intent_ts <= ack_ts < started_ts
        and readback_ts > max(intent_ts, ack_ts)
        and readback_ts <= now_value + 1.0
        and openwb_pro_session.phase_zero_readback_confirmed(st)
        and openwb_pro_session.status_connected(st)
        and _cfg_float(box.get("current_set_amp"), 0.0) <= 0.5
        and not (isinstance(active_sequence, dict) and active_sequence)
        and not (
            isinstance(active_restart, dict)
            and active_restart.get("active") is True
        )
        and not last_output_after_successor
    )
    if not exact:
        return False

    touched_keys = (
        "_wallbox_phase_transition_reservation",
        "_openwb_pro_phase_output_intent",
        "_openwb_pro_phase_output_ack",
        "_openwb_pro_phase_recovery_hold",
        "_openwb_pro_phase_sequence_stage",
        "_openwb_pro_phase_stranded_zero_recovery",
    )
    previous = {
        key: (key in box, deepcopy(box.get(key)))
        for key in touched_keys
    }
    successor = dict(reservation)
    successor["cooldown_until_ts"] = 0.0
    successor.pop("cooldown_wire_receipt_ts", None)
    successor.pop("cooldown_source", None)
    box["_wallbox_phase_transition_reservation"] = successor
    box.pop("_openwb_pro_phase_output_intent", None)
    box.pop("_openwb_pro_phase_output_ack", None)
    box.pop("_openwb_pro_phase_recovery_hold", None)
    box["_openwb_pro_phase_sequence_stage"] = "await_budget"
    box["_openwb_pro_phase_stranded_zero_recovery"] = {
        "schema": "openwb_pro_phase_stranded_zero_recovery_v1",
        "old_transition_id": old_id,
        "successor_transition_id": current_id,
        "intent_id": intent_id,
        "target": target,
        "intent_ts": intent_ts,
        "readback_ts": readback_ts,
        "recovered_ts": now_value,
        "zero_readback_confirmed": True,
        "successor_preserved": True,
        "hardware_write": False,
    }
    if _save_wallbox_phase_state([box]):
        return True
    for key, (present, value) in previous.items():
        if present:
            box[key] = value
        else:
            box.pop(key, None)
    return False


def _resolve_failed_openwb_pro_phase_target_recovery(
    data,
    status,
    cfg,
    *,
    now_ts=None,
):
    """Beendet einen belegten negativen ``phasetarget``-ACK ohne Geräte-I/O.

    Ein fehlgeschlagener POST darf weder als erfolgreicher Phasenwechsel noch
    als Beginn des 480-s-Hardware-Cooldowns gelten. Bleibt die Pro danach aber
    über zwei getrennte, frische GET-Frames verbunden und physisch ruhig auf
    ihrem bisherigen Ziel, ist genau diese fehlgeschlagene Ausgangsgeneration
    terminal. Der Ladestrom bleibt in diesem Zyklus bei 0 A; erst die normale
    Policy des Folgezyklus darf auf der bestätigten Fallbackphase wieder Strom
    anbieten.
    """

    box = data if isinstance(data, dict) else {}
    st = status if isinstance(status, dict) else {}
    config = cfg if isinstance(cfg, dict) else {}
    now_value = time.time() if now_ts is None else _cfg_float(now_ts, 0.0)
    hold = box.get("_openwb_pro_phase_recovery_hold")
    hold = hold if isinstance(hold, dict) else {}
    intent = box.get("_openwb_pro_phase_output_intent")
    intent = intent if isinstance(intent, dict) else {}
    ack = box.get("_openwb_pro_phase_output_ack")
    ack = ack if isinstance(ack, dict) else {}
    reservation = box.get("_wallbox_phase_transition_reservation")
    reservation = reservation if isinstance(reservation, dict) else {}
    sequence = box.get("_openwb_pro_phase_sequence")
    sequence = sequence if isinstance(sequence, dict) else {}
    sequence_patch = intent.get("sequence_patch")
    sequence_patch = sequence_patch if isinstance(sequence_patch, dict) else {}

    intent_id = str(intent.get("intent_id") or "")
    requested_target = _valid_phase_count(intent.get("target"), 0)
    fallback_target = _valid_phase_count(st.get("phases_target"), 0)
    intent_ts = _cfg_float(intent.get("wall_ts"), 0.0)
    ack_ts = _cfg_float(ack.get("wall_ts"), 0.0)
    readback_ts = _cfg_float(st.get("driver_status_last_ok_ts"), 0.0)
    for name, value in (
        ("intent_ts", intent_ts),
        ("ack_ts", ack_ts),
        ("readback_ts", readback_ts),
    ):
        if value > 100_000_000_000.0:
            value /= 1000.0
        if name == "intent_ts":
            intent_ts = value
        elif name == "ack_ts":
            ack_ts = value
        else:
            readback_ts = value

    hold_reason = str(hold.get("reason") or "")
    restart_reclassified_negative_ack = bool(
        hold_reason == "process_restart_recovery_hold"
        and str(hold.get("recovery_class") or "") == "output_ambiguous"
        and str(reservation.get("stage") or "") == "recovery_hold"
        and str(reservation.get("blocker") or "") in (
            "process_restart_recovery_hold",
            "phase_transition_timebase_unbound",
        )
        and str(reservation.get("reason") or "")
        == "process_restart_recovery_hold"
        and str(reservation.get("reason_code") or "")
        == "process_restart_recovery_hold"
    )

    candidate_key = "_openwb_pro_failed_phase_target_candidate"
    exact_generation = bool(
        hold.get("active") is True
        and _phase_output_recovery_generation_bound(
            box,
            hold,
            intent,
            status=st,
        )
        and str(intent.get("action") or "") == "send_phase"
        and str(intent.get("method") or "") == "set_phases"
        and requested_target in (1, 3)
        and (
            hold_reason == "phase_target_unconfirmed"
            or restart_reclassified_negative_ack
        )
        and ack.get("schema") == "openwb_pro_phase_output_ack_v1"
        and str(ack.get("intent_id") or "") == intent_id
        and ack.get("success") is False
        and str(ack.get("reason") or "") == "phase_target_unconfirmed"
        and all(
            math.isfinite(value) and value > 0.0
            for value in (now_value, intent_ts, ack_ts, readback_ts)
        )
        and intent_ts <= ack_ts < readback_ts <= now_value + 1.0
        and _cfg_float(intent.get("wire_receipt_ts"), 0.0) <= 0.0
        and _cfg_float(sequence_patch.get("wire_receipt_ts"), 0.0) <= 0.0
        and _cfg_float(sequence_patch.get("phase_sent_ts"), 0.0) <= 0.0
        and _cfg_float(sequence.get("wire_receipt_ts"), 0.0) <= 0.0
        and _cfg_float(sequence.get("phase_sent_ts"), 0.0) <= 0.0
        and _cfg_float(ack.get("wire_receipt_ts"), 0.0) <= 0.0
        and _cfg_float(
            reservation.get("cooldown_wire_receipt_ts"),
            0.0,
        )
        <= 0.0
        and _cfg_float(reservation.get("cooldown_until_ts"), 0.0) <= 0.0
        and not str(reservation.get("cooldown_source") or "")
        and _cfg_float(box.get("current_set_amp"), 0.0) <= 0.5
    )
    quiet_fallback = bool(
        exact_generation
        and fallback_target in (1, 3)
        and fallback_target != requested_target
        and openwb_pro_session.phase_zero_readback_confirmed(st)
        and openwb_pro_session.phase_target_readback_confirmed(
            st,
            fallback_target,
        )
        and openwb_pro_session.status_connected(st)
        and st.get("cp_interrupt_isactive") in (False, 0)
        and st.get("driver_status_plausible") is not False
    )
    if not quiet_fallback:
        box.pop(candidate_key, None)
        return False

    transition_id = str(
        reservation.get("transition_id")
        or reservation.get("reservation_id")
        or ""
    )
    candidate = box.get(candidate_key)
    candidate = candidate if isinstance(candidate, dict) else {}
    same_candidate = bool(
        str(candidate.get("intent_id") or "") == intent_id
        and str(candidate.get("transition_id") or "") == transition_id
        and _valid_phase_count(candidate.get("requested_target"), 0)
        == requested_target
        and _valid_phase_count(candidate.get("fallback_target"), 0)
        == fallback_target
    )
    previous_readback_ts = _cfg_float(
        candidate.get("last_readback_ts"),
        0.0,
    )
    if not same_candidate:
        box[candidate_key] = {
            "contract": "openwb_pro_failed_phase_target_candidate_v1",
            "intent_id": intent_id,
            "transition_id": transition_id,
            "requested_target": requested_target,
            "fallback_target": fallback_target,
            "first_readback_ts": readback_ts,
            "last_readback_ts": readback_ts,
            "frames": 1,
        }
        return False
    if readback_ts <= previous_readback_ts:
        return False

    frames = int(_cfg_float(candidate.get("frames"), 0.0)) + 1
    if frames < 2:
        candidate = dict(candidate)
        candidate.update({
            "last_readback_ts": readback_ts,
            "frames": frames,
        })
        box[candidate_key] = candidate
        return False

    cleanup_keys = (
        "_wallbox_phase_transition_reservation",
        "_phase_transition_grant",
        "_openwb_pro_phase_sequence",
        "_openwb_pro_phase_sequence_contract",
        "_openwb_pro_phase_sequence_last",
        "_openwb_pro_phase_sequence_stage",
        "_openwb_pro_phase_sequence_target",
        "_openwb_pro_phase_sequence_current_allowed_after",
        "_openwb_pro_phase_sequence_phase_sent_ts",
        "_openwb_pro_phase_sequence_cp_sent_ts",
        "_openwb_pro_phase_output_intent",
        "_openwb_pro_phase_output_ack",
        "_openwb_pro_phase_recovery_hold",
        "_openwb_pro_phase_restart_authorized",
        "_openwb_pro_phase_wait_target",
        "_openwb_pro_phase_wait_until",
        "_openwb_pro_phase_wait_min_until",
        "_openwb_pro_phase_wait_amp",
        "_openwb_pro_phase_wait_since",
        candidate_key,
    )
    touched_keys = cleanup_keys + (
        "_phase_3p_block_until",
        "_openwb_pro_phase_retry_block_until",
        "_phase_target_cmd",
        "_phase_target_cmd_until",
        "_openwb_pro_start_phase_target",
        "_phase_up_budget_since",
        "_phase_down_since",
        "_openwb_pro_failed_phase_target_recovery",
    )
    phase_preimage = _snapshot_wallbox_state_file_preimage(
        WB_PHASE_STATE_FILE
    )
    if phase_preimage.get("valid") is not True:
        return False
    previous = {
        key: (key in box, deepcopy(box.get(key)))
        for key in touched_keys
    }
    for key in cleanup_keys:
        box.pop(key, None)

    # Das gemeldete Fallbackziel ist kein erfolgreicher Wechsel dieses
    # Versuchs. Es wird lediglich als kurzfristiger Policy-Anker verwendet,
    # damit der Folgezyklus dort wieder Strom anbieten kann, ohne denselben
    # fehlgeschlagenen 3p-Auftrag sofort erneut zu senden.
    retry_backoff_s = max(
        openwb_pro_session.phase_wait_s(config),
        _cfg_float(config.get("wb_phase_retry_block_s"), 900.0),
    )
    # Der Fallback ist ein Geräte-Readback, kein von uns bestätigter
    # Phasenbefehl. Ein möglicherweise älterer Command-Memory wird deshalb
    # ausdrücklich verworfen, damit spätere frische Ziel-Readbacks sofort
    # wieder autoritativ sind.
    _remember_phase_target(box, 0)
    box["_openwb_pro_start_phase_target"] = fallback_target
    if requested_target == 3:
        retry_block_until = now_value + retry_backoff_s
        box["_phase_3p_block_until"] = max(
            _cfg_float(box.get("_phase_3p_block_until"), 0.0),
            retry_block_until,
        )
        box["_openwb_pro_phase_retry_block_until"] = max(
            _cfg_float(
                box.get("_openwb_pro_phase_retry_block_until"),
                0.0,
            ),
            retry_block_until,
        )
        box["_phase_up_budget_since"] = now_value
    else:
        box["_phase_down_since"] = now_value
    box["_openwb_pro_failed_phase_target_recovery"] = {
        "contract": "openwb_pro_failed_phase_target_recovery_v1",
        "intent_id": intent_id,
        "transition_id": transition_id,
        "requested_target": requested_target,
        "fallback_target": fallback_target,
        "first_readback_ts": _cfg_float(
            candidate.get("first_readback_ts"),
            readback_ts,
        ),
        "last_readback_ts": readback_ts,
        "frames": frames,
        "terminalized_ts": now_value,
        "retry_backoff_until_ts": now_value + retry_backoff_s,
        "hardware_write": False,
        "wire_receipt_confirmed": False,
        "hardware_cooldown_started": False,
        "resume_current_next_cycle": True,
        "reclassified_after_process_restart": (
            restart_reclassified_negative_ack
        ),
    }
    if _save_wallbox_phase_state([box]):
        return True

    disk_restored = _restore_wallbox_state_file_preimage(
        WB_PHASE_STATE_FILE,
        phase_preimage,
    )
    for key, (present, value) in previous.items():
        if present:
            box[key] = value
        else:
            box.pop(key, None)
    if not disk_restored:
        _apply_openwb_pro_persistence_recovery_hold(
            box,
            "failed_phase_target_terminal_rollback_failed",
        )
        persistence_hold = box.get(
            "_openwb_pro_session_persistence_recovery_hold"
        )
        if isinstance(persistence_hold, dict):
            persistence_hold["persistence_retry_attempted"] = True
            persistence_hold["persistence_retry_succeeded"] = None
        persistence_retry_succeeded = bool(
            _save_wallbox_phase_state([box])
        )
        if isinstance(persistence_hold, dict):
            persistence_hold["persistence_retry_succeeded"] = (
                persistence_retry_succeeded
            )
    return False


def _resolve_phase_output_recovery(data, status, cfg):
    hold = data.get("_openwb_pro_phase_recovery_hold")
    intent = data.get("_openwb_pro_phase_output_intent")
    if not (isinstance(hold, dict) and hold.get("active") and isinstance(intent, dict)):
        return False
    if not _phase_output_recovery_generation_bound(data, hold, intent, status=status):
        return _resolve_stranded_phase_zero_recovery(
            data,
            status,
            hold,
            intent,
            now_ts=time.time(),
        )
    if _resolve_failed_openwb_pro_phase_target_recovery(
        data,
        status,
        cfg,
        now_ts=time.time(),
    ):
        return True
    action = str(intent.get("action") or "")
    target = _valid_phase_count(intent.get("target"), 0)
    confirmed = False
    proposal = {"action": action, "target": target}
    if action == "send_zero":
        now_value = time.time()
        if not (
            openwb_pro_session.phase_zero_readback_confirmed(status)
            and _phase_output_recovery_post_intent_readback(
                status,
                intent,
                now_value,
            )
        ):
            return False
        sequence = intent.get("sequence_after")
        if isinstance(sequence, dict) and sequence:
            proposal["sequence"] = sequence
            confirmed = True
    elif (
        action == "send_phase"
        and openwb_pro_session.phase_zero_readback_confirmed(status)
        and openwb_pro_session.phase_target_readback_confirmed(status, target)
    ):
        sequence_patch = dict(intent.get("sequence_patch") or {})
        wire_receipt_ts = max(
            _cfg_float(sequence_patch.get("wire_receipt_ts"), 0.0),
            _cfg_float(intent.get("wire_receipt_ts"), 0.0),
        )
        phase_sent_ts = _cfg_float(
            sequence_patch.get("phase_sent_ts"),
            0.0,
        )
        now_value = time.time()
        if not (
            math.isfinite(wire_receipt_ts)
            and math.isfinite(phase_sent_ts)
            and wire_receipt_ts > 0.0
            and abs(phase_sent_ts - wire_receipt_ts) <= 1e-6
            and wire_receipt_ts <= now_value + 1.0
        ):
            return False
        if not openwb_pro_session._post_wire_readback_confirmed(
            status,
            target,
            wire_receipt_ts,
        ):
            return False
        configured_phase_settle_s = openwb_pro_session.phase_min_settle_s(cfg)
        persisted_phase_settle_s = _cfg_float(
            sequence_patch.get("phase_settle_s"),
            0.0,
        )
        persisted_current_allowed_after = _cfg_float(
            sequence_patch.get("current_allowed_after"),
            0.0,
        )
        # Ältere Versionen konnten den 480-s-Phasenwechsel-Cooldown als
        # Wiederanlauf-Settle persistieren. Ein solcher Wert liegt außerhalb
        # des dokumentierten, auf 30 s begrenzten Geräte-Settle-Vertrags. Er
        # wird ausschließlich in die Sperre für den nächsten Phasenwechsel
        # übernommen; ein frischer Ziel-Readback darf den Strom nach der
        # kurzen Gerätewartezeit wieder freigeben.
        legacy_phase_cooldown_conflated = bool(
            math.isfinite(persisted_phase_settle_s)
            and persisted_phase_settle_s > 30.0
        )
        phase_settle_s = (
            configured_phase_settle_s
            if legacy_phase_cooldown_conflated
            else max(configured_phase_settle_s, persisted_phase_settle_s)
        )
        restart_delay_s = openwb_pro_session.phase_restart_delay_s(cfg)
        phase_cooldown_s = openwb_pro_session.phase_wait_s(cfg)
        canonical_current_allowed_after = (
            wire_receipt_ts + phase_settle_s + restart_delay_s
        )
        current_allowed_after = (
            canonical_current_allowed_after
            if legacy_phase_cooldown_conflated
            else max(
                persisted_current_allowed_after,
                canonical_current_allowed_after,
            )
        )
        restart_current_ready = bool(
            current_allowed_after > 0.0
            and now_value >= current_allowed_after
            and openwb_pro_session.status_connected(status)
            and status.get("cp_interrupt_isactive") in (False, 0)
        )
        if not restart_current_ready:
            # Die Recovery bleibt bis zum Ablauf der kurzen Gerätepause
            # Besitzerin der alten Ausgangsgeneration. So wird weder ein
            # Timer neu gestartet noch der Strompfad vorzeitig freigegeben.
            return False
        phase_change_block_until = max(
            _cfg_float(
                sequence_patch.get("phase_change_block_until"),
                0.0,
            ),
            wire_receipt_ts + phase_cooldown_s,
            (
                max(
                    persisted_current_allowed_after,
                    wire_receipt_ts + persisted_phase_settle_s,
                )
                if legacy_phase_cooldown_conflated
                else 0.0
            ),
        )
        clock_sample = _openwb_pro_control_time_sample(
            wall_ts=now_value,
        )
        stage_timer = openwb_pro_session._phase_stage_timer(
            "restart_delay",
            phase_settle_s + restart_delay_s,
            None,
            clock_sample,
        )
        sequence_patch.update({
            "stage": "restart_delay",
            "phase_sent_ts": wire_receipt_ts,
            "wire_receipt_ts": wire_receipt_ts,
            "phase_settle_s": phase_settle_s,
            "current_allowed_after": current_allowed_after,
            "phase_change_block_until": phase_change_block_until,
            **(
                {openwb_pro_session.PHASE_STAGE_TIMEBASE_KEY: stage_timer}
                if isinstance(stage_timer, dict)
                else {}
            ),
        })
        proposal["sequence_patch"] = sequence_patch
        proposal["phase_wait_config"] = {
            "openwb_pro_phase_wait_s": phase_cooldown_s,
        }
        intent = dict(intent)
        intent["wire_receipt_ts"] = wire_receipt_ts
        intent["sequence_patch"] = dict(sequence_patch)
        data["_openwb_pro_phase_output_intent"] = intent
        # Nach einem Managerneustart darf die bereits belegte
        # ``phasetarget``-Kante nicht in einem Zirkelschluss hängen bleiben:
        # 0 A verhindert reale Phasennutzung, während dieselbe reale Nutzung
        # den Wiederanlauf freigeben soll. Ist die kurze Gerätepause bereits
        # abgelaufen und liegt ein frischer, ruhiger Ziel-Readback vor, wird
        # deshalb ausschließlich der Strom-Neustart autorisiert. Die aktive
        # Phasenreservierung bleibt bis zur Bestätigung durch reale Leistung
        # bestehen; der 480-s-Cooldown wird nicht verändert.
        proposal["restart_current_ready"] = restart_current_ready
        confirmed = True
    if not confirmed:
        return False
    sequencer = PhaseSwitchSequencer(data)
    sequencer.acknowledge(proposal, True, config=cfg)
    if action == "send_phase":
        recovered_sequence = data.get("_openwb_pro_phase_sequence")
        recovered_sequence = (
            recovered_sequence
            if isinstance(recovered_sequence, dict)
            else {}
        )
        if not (
            str(recovered_sequence.get("stage") or "")
            == "restart_delay"
            and _cfg_float(
                recovered_sequence.get("wire_receipt_ts"),
                0.0,
            )
            > 0.0
        ):
            return False
        if proposal.get("restart_current_ready") is True:
            data["_openwb_pro_phase_sequence_last"] = dict(
                recovered_sequence
            )
            data["_openwb_pro_phase_sequence"] = {}
            data["_openwb_pro_phase_sequence_stage"] = "ready"
            data["_openwb_pro_phase_sequence_target"] = 0
            data[
                "_openwb_pro_phase_sequence_current_allowed_after"
            ] = 0.0
            openwb_pro_session.clear_phase_wait(data)
            reservation = wallbox_phase_transition.mark_committed(
                data,
                stage="confirm_target",
                now_ts=_cfg_float(intent.get("wall_ts"), now_value),
            )
            reservation = dict(reservation)
            reservation.update({
                "stage_deadline_ts": current_allowed_after,
                "blocker": "",
                "reason_code": "phase_restart_current_pending",
                "reason": "phase_restart_current_pending",
            })
            data["_wallbox_phase_transition_reservation"] = reservation
            data["_openwb_pro_phase_restart_authorized"] = {
                "active": True,
                "target": target,
                "phase_sent_ts": wire_receipt_ts,
                "authorized_ts": now_value,
                "source": "phase_target_settle_readback_confirmed",
                "recovered_after_process_restart": True,
            }
    data.pop("_openwb_pro_phase_recovery_hold", None)
    return _persist_phase_output_ack(
        data,
        intent,
        True,
        reason="recovered_from_fresh_unambiguous_readback",
    )


def _resolve_phase_output_recovery_once_per_cycle(data, status, cfg):
    """Schließt alte Ausgangsevidenz einmal vor jeder Wallbox-Policy."""

    box = data if isinstance(data, dict) else {}
    cycle_token = str(box.get("_wallbox_cycle_token") or "")
    if (
        cycle_token
        and str(box.get("_phase_output_recovery_cycle_token") or "")
        == cycle_token
    ):
        return bool(box.get("_phase_output_recovery_cycle_resolved", False))
    legacy_commit = _normalize_openwb_pro_legacy_phase_commit(
        box,
        status,
        now_ts=time.time(),
    )
    box["_openwb_pro_legacy_phase_commit_normalization"] = legacy_commit
    if legacy_commit.get("normalized") is True:
        # Die alte Ausgangsgeneration ist damit vollständig gebunden. Sie darf
        # nicht anschließend erneut als ungebundene Recovery-Sequenz aufgebaut
        # werden; ein neuer Phasenausgang bleibt in diesem Zyklus gesperrt.
        resolved = True
    elif legacy_commit.get("blockers") == [
        "normalized_commit_persist_failed"
    ]:
        # Nach einem fehlgeschlagenen Persistieren bleibt der Ausgang strikt
        # fail-closed. Die nachgelagerte Recovery darf diesen Fehler nicht durch
        # eine zweite, anders materialisierte Generation überdecken.
        resolved = False
    else:
        resolved = bool(_resolve_phase_output_recovery(box, status, cfg))
    if cycle_token:
        box["_phase_output_recovery_cycle_token"] = cycle_token
        box["_phase_output_recovery_cycle_resolved"] = resolved
    return resolved


def _abort_openwb_pro_phase_transition_before_output(
    data,
    *,
    target,
    reason,
    now_ts,
):
    """Räumt eine noch nicht ausgegebene Phasengeneration atomar ab."""

    box = data if isinstance(data, dict) else {}
    keys = tuple(_OPENWB_PRO_DISCONNECTED_PHASE_TERMINAL_KEYS)
    previous = {
        key: (key in box, deepcopy(box.get(key)))
        for key in keys
    }
    previous_marker = (
        "_openwb_pro_phase_output_abort" in box,
        deepcopy(box.get("_openwb_pro_phase_output_abort")),
    )
    for key in keys:
        box.pop(key, None)
    openwb_pro_session.clear_phase_wait(box)
    box["_openwb_pro_phase_output_abort"] = {
        "contract": "openwb_pro_phase_output_abort_v1",
        "action": "aborted_disconnected_before_phase_output",
        "reason": str(reason or "vehicle_disconnected_before_phase_output"),
        "target": int(target or 0),
        "ts": float(now_ts),
    }
    if _save_wallbox_phase_state([box]):
        return True

    for key, (present, value) in previous.items():
        if present:
            box[key] = value
        else:
            box.pop(key, None)
    marker_present, marker_value = previous_marker
    if marker_present:
        box["_openwb_pro_phase_output_abort"] = marker_value
    else:
        box.pop("_openwb_pro_phase_output_abort", None)
    return False


def _phase_transition_preoutput_evidence(c_data, reservation=None):
    """Belegt eine noch vollständig ausgangslose Phasenreservierung.

    Ein Storage-Grant ist ausschließlich Wattbudget und deshalb noch kein
    Geräteausgang. Dagegen sperrt jede zur aktuellen Generation gehörende
    Sequenz-, Output-, Recovery-, Restart- oder Wake-up-Evidenz eine
    Supersession fail-closed.
    """

    data = c_data if isinstance(c_data, dict) else {}
    item = (
        reservation
        if isinstance(reservation, dict)
        else data.get("_wallbox_phase_transition_reservation")
    )
    item = item if isinstance(item, dict) else {}
    started_ts = _cfg_float(item.get("started_ts"), 0.0)

    def _timestamp_is_bound(value):
        ts = _cfg_float(value, 0.0)
        if ts <= 0.0:
            return False
        return bool(started_ts <= 0.0 or ts >= started_ts)

    wakeup_receipt = data.get("_openwb_pro_start_wakeup_receipt")
    wakeup_receipt = (
        wakeup_receipt if isinstance(wakeup_receipt, dict) else {}
    )
    last_executed = data.get("_last_executed_command")
    last_executed = last_executed if isinstance(last_executed, dict) else {}
    executed_method = str(last_executed.get("method") or "")
    output_methods = (
        "set_phases",
        "set_amp_and_state",
        "set_current",
        "set_direct_current",
        "trigger_cp_interrupt",
        "cp_interrupt",
    )
    executed_output_bound = bool(
        executed_method in output_methods
        and (
            _timestamp_is_bound(last_executed.get("ts"))
            or _cfg_float(last_executed.get("ts"), 0.0) <= 0.0
        )
    )
    wakeup_receipt_has_timestamp = any(
        _cfg_float(wakeup_receipt.get(key), 0.0) > 0.0
        for key in (
            "first_sent_ts",
            "last_sent_ts",
            "current_issued_ts",
        )
    )
    wakeup_receipt_ambiguous = bool(
        wakeup_receipt
        and int(_cfg_float(wakeup_receipt.get("count"), 0.0)) > 0
        and not wakeup_receipt_has_timestamp
    )
    wakeup_count_ambiguous = bool(
        int(_cfg_float(data.get("_openwb_pro_start_wakeup_count"), 0.0)) > 0
        and not wakeup_receipt_has_timestamp
        and _cfg_float(data.get("_openwb_last_cp_start_ts"), 0.0) <= 0.0
        and _cfg_float(data.get("_openwb_pro_start_wakeup_cp_ts"), 0.0) <= 0.0
    )
    wakeup_active = bool(
        _timestamp_is_bound(data.get("_openwb_pro_start_wakeup_cp_ts"))
        or _timestamp_is_bound(
            data.get("_openwb_pro_start_wakeup_allowed_after")
        )
        or _timestamp_is_bound(data.get("_openwb_last_cp_start_ts"))
        or _timestamp_is_bound(data.get("_openwb_pro_start_current_issued_ts"))
        or _timestamp_is_bound(wakeup_receipt.get("first_sent_ts"))
        or _timestamp_is_bound(wakeup_receipt.get("last_sent_ts"))
        or _timestamp_is_bound(wakeup_receipt.get("current_issued_ts"))
        or executed_output_bound
        or wakeup_receipt_ambiguous
        or wakeup_count_ambiguous
        or (
            bool(data.get("_openwb_cp_start_sent", False))
            and not any(
                _cfg_float(value, 0.0) > 0.0
                for value in (
                    data.get("_openwb_last_cp_start_ts"),
                    data.get("_openwb_pro_start_wakeup_cp_ts"),
                    wakeup_receipt.get("last_sent_ts"),
                )
            )
        )
        or bool(data.get("_openwb_pro_start_wakeup_pending", False))
    )
    evidence = wallbox_phase_transition.preoutput_supersession_evidence_contract(
        item,
        sequence=data.get("_openwb_pro_phase_sequence"),
        output_intent=data.get("_openwb_pro_phase_output_intent"),
        output_ack=data.get("_openwb_pro_phase_output_ack"),
        recovery_hold=data.get("_openwb_pro_phase_recovery_hold"),
        restart_authorized=data.get("_openwb_pro_phase_restart_authorized"),
        wakeup_active=wakeup_active,
    )
    if (
        str(item.get("grant_state") or "") == "committed"
        or item.get("committed") is True
    ):
        evidence = dict(evidence)
        evidence["eligible"] = False
        evidence["committed_grant_state"] = True
    return evidence


def _phase_transition_preoutput_grant_ready(c_data):
    """True nur für einen gewährten, aber noch ausgangslosen Phasenvertrag."""

    data = c_data if isinstance(c_data, dict) else {}
    reservation = data.get("_wallbox_phase_transition_reservation")
    if not isinstance(reservation, dict):
        return False
    evidence = _phase_transition_preoutput_evidence(data, reservation)
    return bool(
        evidence.get("eligible") is True
        and wallbox_phase_transition.grant_is_sufficient(reservation)
    )


def _openwb_pro_granted_preoutput_phase_resume_contract(
    c_data,
    status,
    *,
    desired_target,
    budget_ok,
    budget_timeout,
    connected,
    mode_off,
    priority_forced_stop,
    manual_pause,
    locked,
    emergency_stop,
):
    """Bindet einen gewährten, noch ausgangslosen Phasenvertrag erneut ein."""

    data = c_data if isinstance(c_data, dict) else {}
    st = status if isinstance(status, dict) else {}
    reservation = data.get("_wallbox_phase_transition_reservation")
    grant = data.get("_phase_transition_grant")
    reservation = reservation if isinstance(reservation, dict) else {}
    grant = grant if isinstance(grant, dict) else {}
    reservation_id = str(
        reservation.get("reservation_id")
        or reservation.get("transition_id")
        or ""
    )
    requested_w = max(
        0,
        int(_cfg_float(reservation.get("requested_w"), 0.0)),
    )
    granted_w = max(
        0,
        int(_cfg_float(reservation.get("granted_w"), 0.0)),
    )
    target = _valid_phase_count(reservation.get("target_phases"), 0)
    desired = _valid_phase_count(desired_target, 0)
    checks = {
        "openwb_pro_required": openwb_pro_session.is_openwb_pro_charger(
            data.get("charger")
        ),
        "preoutput_grant_required": _phase_transition_preoutput_grant_ready(
            data
        ),
        "reservation_id_required": bool(reservation_id),
        "grant_reservation_match": bool(
            reservation_id
            and str(grant.get("reservation_id") or "") == reservation_id
        ),
        "target_match": bool(target in (1, 3) and desired == target),
        "grant_sufficient": bool(
            requested_w > 0
            and granted_w >= requested_w
            and str(reservation.get("grant_state") or "")
            in ("granted", "committed")
        ),
        "budget_ready": bool(budget_ok) and not bool(budget_timeout),
        "connected": bool(connected)
        and bool(openwb_pro_session.status_connected(st)),
        "fresh_status": bool(st.get("driver_status_valid", False))
        and not bool(st.get("driver_status_stale", False))
        and not bool(st.get("driver_status_degraded", False))
        and not bool(st.get("driver_status_glitch", False)),
        "cp_inactive": st.get("cp_interrupt_isactive") in (False, 0),
        "mode_active": not bool(mode_off),
        "priority_clear": not bool(priority_forced_stop),
        "manual_pause_clear": not bool(manual_pause),
        "lock_clear": not bool(locked),
        "emergency_clear": not bool(emergency_stop),
        "vehicle_not_finished": not bool(data.get("_bev_full_blocked", False)),
        "recovery_clear": not bool(
            isinstance(data.get("_openwb_pro_phase_recovery_hold"), dict)
            and data.get("_openwb_pro_phase_recovery_hold", {}).get(
                "active", False
            )
        ),
    }
    blockers = [name for name, valid in checks.items() if not valid]
    return {
        "contract": "openwb_pro_granted_preoutput_phase_resume_v1",
        "resume": not blockers,
        "target_phases": target,
        "reservation_id": reservation_id,
        "requested_w": requested_w,
        "granted_w": granted_w,
        "blockers": blockers,
    }


def _persist_openwb_pro_legacy_preoutput_evidence_bridge(
    c_data,
    *,
    now_ts=None,
):
    """Versiegelt eine beweisbar ausgangslose Legacy-Reservation einmalig.

    Alte Phasenstatusdateien kennen den transportierbaren Preoutput-Beleg noch
    nicht. Unter einem bereits persistierten Same-Session-Terminal-Latch darf
    die aktuelle vollständige No-output-Evidenz deshalb zuerst an exakt diese
    Reservation gebunden und als eigener Schritt gespeichert werden. Erst ein
    späterer zweiter Persistenzschritt darf die Reservation entfernen.
    """

    data = c_data if isinstance(c_data, dict) else {}
    reservation = data.get("_wallbox_phase_transition_reservation")
    now_value = time.time() if now_ts is None else float(now_ts)
    result = {
        "contract": "openwb_pro_legacy_preoutput_evidence_bridge_v1",
        "matched": False,
        "proof_added": False,
        "persisted": False,
        "blocker": "",
        "ts": now_value,
        "hardware_write": False,
    }
    if not isinstance(reservation, dict) or reservation.get("active") is not True:
        result["blocker"] = "active_reservation_missing"
        return result
    reservation_id = str(
        reservation.get("reservation_id")
        or reservation.get("transition_id")
        or ""
    )
    result["reservation_id"] = reservation_id

    latch_reason = str(data.get("_bev_full_block_reason") or "")
    latch_session_id = str(
        data.get("_charge_end_latched_plug_session_id") or ""
    )
    runtime_session_id = str(
        data.get("_openwb_pro_plug_session_id")
        or data.get("_wallbox_plug_episode_id")
        or ""
    )
    if not (
        data.get("_bev_full_blocked") is True
        and latch_reason in _CHARGE_END_TERMINAL_REASONS
        and latch_session_id
        and runtime_session_id == latch_session_id
    ):
        result["blocker"] = "same_session_terminal_latch_missing"
        return result

    if wallbox_phase_transition.preoutput_supersession_evidence_is_bound(
        reservation
    ):
        result.update({
            "matched": True,
            "persisted": True,
            "proof_already_bound": True,
            "blocker": "",
        })
        return result

    current_evidence = _phase_transition_preoutput_evidence(
        data,
        reservation,
    )
    result["current_evidence"] = dict(current_evidence)
    if current_evidence.get("eligible") is not True:
        result["blocker"] = "current_output_evidence_bound"
        return result

    result["matched"] = True
    phase_preimage = _snapshot_wallbox_state_file_preimage(
        WB_PHASE_STATE_FILE
    )
    if phase_preimage.get("valid") is not True:
        result["blocker"] = "phase_state_preimage_invalid"
        return result
    previous_reservation = deepcopy(reservation)
    bridged_reservation = dict(reservation)
    bridged_reservation["preoutput_supersession_evidence"] = dict(
        current_evidence
    )
    data["_wallbox_phase_transition_reservation"] = bridged_reservation
    if _save_wallbox_phase_state([data]):
        result.update({
            "proof_added": True,
            "persisted": True,
            "blocker": "",
        })
        data["_openwb_pro_legacy_preoutput_evidence_bridge"] = dict(result)
        return result

    disk_restored = _restore_wallbox_state_file_preimage(
        WB_PHASE_STATE_FILE,
        phase_preimage,
    )
    data["_wallbox_phase_transition_reservation"] = previous_reservation
    result["disk_restored"] = bool(disk_restored)
    if not disk_restored:
        _apply_openwb_pro_persistence_recovery_hold(
            data,
            "legacy_preoutput_proof_rollback_failed",
        )
        result["fail_closed"] = True
    result["blocker"] = "proof_persist_failed"
    return result


def _supersede_openwb_pro_preoutput_phase_reservation(
    c_data,
    target_phases,
    *,
    now_ts=None,
    terminal_latch=False,
):
    """Entfernt ausschließlich eine beweisbar ausgangslose Altgeneration.

    Die Bereinigung besitzt keinen Hardwareausgang. Sie wird vor der Rückkehr
    crashfest im Phasenstatus gespeichert und bei einem Schreibfehler im RAM
    vollständig zurückgerollt. Eine bereits gebundene 480-s-Sperre bleibt
    erhalten; committete oder anderweitig ausgangsgebundene Generationen
    werden nie supersediert.
    """

    data = c_data if isinstance(c_data, dict) else {}
    reservation = data.get("_wallbox_phase_transition_reservation")
    result = {
        "contract": "openwb_pro_preoutput_phase_supersession_v1",
        "matched": False,
        "superseded": False,
        "persisted": False,
        "terminal_latch": bool(terminal_latch),
        "blocker": "",
    }
    if not isinstance(reservation, dict) or reservation.get("active") is not True:
        result["blocker"] = "active_reservation_missing"
        return result

    requested_target = _valid_phase_count(target_phases, 0)
    reservation_target = _valid_phase_count(
        reservation.get("target_phases"),
        0,
    )
    result.update({
        "reservation_id": str(
            reservation.get("reservation_id")
            or reservation.get("transition_id")
            or ""
        ),
        "reservation_target": reservation_target,
        "requested_target": requested_target,
    })
    if not terminal_latch and (
        requested_target not in (1, 3)
        or reservation_target == requested_target
    ):
        result["blocker"] = "reservation_target_still_current"
        return result

    persisted_evidence_bound = (
        wallbox_phase_transition.preoutput_supersession_evidence_is_bound(
            reservation
        )
    )
    current_evidence = _phase_transition_preoutput_evidence(
        data,
        reservation,
    )
    result["persisted_evidence_bound"] = bool(persisted_evidence_bound)
    result["current_evidence"] = dict(current_evidence)
    if not persisted_evidence_bound:
        result["blocker"] = "persisted_preoutput_evidence_missing"
        return result
    if current_evidence.get("eligible") is not True:
        result["blocker"] = "current_output_evidence_bound"
        return result

    result["matched"] = True
    phase_preimage = _snapshot_wallbox_state_file_preimage(
        WB_PHASE_STATE_FILE
    )
    if phase_preimage.get("valid") is not True:
        result["blocker"] = "phase_state_preimage_invalid"
        return result
    touched_keys = (
        "_wallbox_phase_transition_reservation",
        "_phase_transition_grant",
        "_phase_3p_block_until",
        "_openwb_pro_phase_change_block_until",
        "_openwb_pro_phase_preoutput_supersession",
    )
    previous = {
        key: (key in data, deepcopy(data.get(key)))
        for key in touched_keys
    }
    now_value = time.time() if now_ts is None else float(now_ts)
    cooldown_until = max(
        _cfg_float(data.get("_phase_3p_block_until"), 0.0),
        _cfg_float(data.get("_openwb_pro_phase_change_block_until"), 0.0),
        _cfg_float(reservation.get("cooldown_until_ts"), 0.0),
    )
    data.pop("_wallbox_phase_transition_reservation", None)
    data.pop("_phase_transition_grant", None)
    if cooldown_until > now_value:
        data["_phase_3p_block_until"] = cooldown_until
        data["_openwb_pro_phase_change_block_until"] = cooldown_until
    supersession_record = {
        **result,
        "superseded": True,
        "persisted": False,
        "superseded_ts": now_value,
        "cooldown_until_ts": cooldown_until,
        "hardware_write": False,
    }
    data["_openwb_pro_phase_preoutput_supersession"] = supersession_record
    if _save_wallbox_phase_state([data]):
        result.update({
            "superseded": True,
            "persisted": True,
            "superseded_ts": now_value,
            "cooldown_until_ts": cooldown_until,
            "hardware_write": False,
        })
        data["_openwb_pro_phase_preoutput_supersession"] = dict(result)
        return result

    disk_restored = _restore_wallbox_state_file_preimage(
        WB_PHASE_STATE_FILE,
        phase_preimage,
    )
    for key, (present, value) in previous.items():
        if present:
            data[key] = value
        else:
            data.pop(key, None)
    result["disk_restored"] = bool(disk_restored)
    if not disk_restored:
        _apply_openwb_pro_persistence_recovery_hold(
            data,
            "preoutput_supersession_rollback_failed",
        )
        result["fail_closed"] = True
    result["blocker"] = "phase_state_persist_failed"
    return result


def _wallbox_group_deficit_snapshot_contract(
    live,
    *,
    live_file=LIVE_DATA_FILE_PY,
    file_revision_ns=None,
    read_meta=None,
):
    """Bindet einen Live-Snapshot an Zeit und echte Dateirevision.

    ``_ts`` ist beim installierten Drei-Sekunden-Writer bereits eindeutig. Die
    Nanosekunden-Mtime macht die Bindung auch bei einem Writer-Neustart in
    derselben Sekunde explizit. Aus Messwerten wird bewusst kein Hash erzeugt.
    Ein neues Dateibild mit nicht monotonem ``_ts`` bleibt im reinen Regler
    dennoch fail-closed und wird nicht bilanziert.
    """

    data = live if isinstance(live, dict) else {}
    sample_ts = _cfg_float(data.get("_ts"), 0.0)
    meta = read_meta if isinstance(read_meta, dict) else None
    signature = None
    signature_source = ""
    if meta is not None:
        raw_signature = meta.get("source_signature")
        try:
            candidate_signature = tuple(int(value) for value in raw_signature)
        except (TypeError, ValueError, OverflowError):
            candidate_signature = ()
        if (
            meta.get("source_signature_confirmed") is True
            and len(candidate_signature) == 3
            and candidate_signature[0] > 0
            and candidate_signature[1] >= 0
            and candidate_signature[2] >= 0
        ):
            signature = candidate_signature
            signature_source = "confirmed_read_signature"
    else:
        try:
            revision_ns = int(file_revision_ns)
        except (TypeError, ValueError, OverflowError):
            try:
                revision_ns = int(os.stat(live_file).st_mtime_ns)
            except (OSError, TypeError, ValueError, OverflowError):
                revision_ns = 0
        if revision_ns > 0:
            signature = (revision_ns, 0, 0)
            signature_source = (
                "explicit_revision"
                if file_revision_ns is not None
                else "legacy_post_read_stat"
            )
    revision_ns = int(signature[0]) if signature is not None else 0
    valid = bool(
        math.isfinite(sample_ts)
        and sample_ts > 0.0
        and signature is not None
        and revision_ns > 0
    )
    if valid and signature_source == "confirmed_read_signature":
        snapshot_id = "live:%d:%d:%d:%d" % (
            int(round(sample_ts * 1_000_000.0)),
            signature[0],
            signature[1],
            signature[2],
        )
    elif valid:
        snapshot_id = "live:%d:%d" % (
            int(round(sample_ts * 1_000_000.0)),
            revision_ns,
        )
    else:
        snapshot_id = ""
    return {
        "contract": "wallbox_group_deficit_snapshot_v1",
        "valid": valid,
        "snapshot_id": snapshot_id,
        "sample_ts": sample_ts if valid else None,
        "file_revision_ns": revision_ns if revision_ns > 0 else None,
        "file_signature": list(signature) if signature is not None else None,
        "source": signature_source or "live_snapshot_identity_missing",
        "read_signature_confirmed": bool(
            signature_source == "confirmed_read_signature"
        ),
        "measurement_hash_used": False,
        "reason": "ok" if valid else "live_snapshot_identity_missing",
    }


def _wallbox_authorized_budget_overrun_contract(
    chargers,
    statuses,
    owner_contract,
    *,
    snapshot,
    charge_modes,
    budget_revision,
    decision_generation,
):
    """Summiert nur vollständig gebundene Slot-Überziehungen.

    Freier Quellenrahmen einer Wallbox darf eine andere Wallbox nicht
    kompensieren. Deshalb wird je Ladepunkt zuerst ``max(0, Messung-Cap)``
    gebildet und erst danach summiert. Der Vertrag ist reine Abrechnung und
    enthält ausdrücklich keine Ausgangs- oder Treiberautorität.
    """

    boxes = [item for item in (chargers or ()) if isinstance(item, dict)]
    status_items = [
        item for item in (statuses or ()) if isinstance(item, dict)
    ]
    owner = owner_contract if isinstance(owner_contract, dict) else {}
    snapshot_data = snapshot if isinstance(snapshot, dict) else {}
    modes = charge_modes if isinstance(charge_modes, dict) else {}
    raw_candidate_ids = list(owner.get("candidate_ids") or ())
    result = {
        "contract": "wallbox_authorized_budget_overrun_v1",
        "available": False,
        "complete": False,
        "value_w": None,
        "accounting": "grid_only",
        "candidate_ids": [],
        "marginal_wb_id": 0,
        "slots": {},
        "blockers": [],
        "output_authority": False,
    }

    candidate_ids = []
    for raw_id in raw_candidate_ids:
        try:
            wb_id = int(raw_id)
        except (TypeError, ValueError, OverflowError):
            wb_id = 0
        if wb_id <= 0 or wb_id in candidate_ids:
            result["blockers"].append("candidate_id_invalid_or_duplicate")
            continue
        candidate_ids.append(wb_id)
    result["candidate_ids"] = sorted(candidate_ids)
    if not candidate_ids:
        result["blockers"].append("candidate_group_empty")

    boxes_by_id = {}
    duplicate_box_ids = set()
    for box in boxes:
        try:
            wb_id = int(box.get("id", 0) or 0)
        except (TypeError, ValueError, OverflowError):
            wb_id = 0
        if wb_id <= 0:
            continue
        if wb_id in boxes_by_id:
            duplicate_box_ids.add(wb_id)
        boxes_by_id[wb_id] = box

    statuses_by_id = {}
    duplicate_status_ids = set()
    for item in status_items:
        try:
            wb_id = int(item.get("id", 0) or 0)
        except (TypeError, ValueError, OverflowError):
            wb_id = 0
        if wb_id <= 0:
            continue
        if wb_id in statuses_by_id:
            duplicate_status_ids.add(wb_id)
        status = item.get("status")
        statuses_by_id[wb_id] = status if isinstance(status, dict) else {}

    candidates_by_id = {
        int(_cfg_float(item.get("id"), 0.0)): item
        for item in (owner.get("candidates") or ())
        if isinstance(item, dict)
        and int(_cfg_float(item.get("id"), 0.0)) > 0
    }
    source_bindings = set()
    total_overrun_w = 0.0
    for wb_id in sorted(candidate_ids):
        slot_blockers = []
        box = boxes_by_id.get(wb_id)
        status = statuses_by_id.get(wb_id)
        candidate = candidates_by_id.get(wb_id)
        if wb_id in duplicate_box_ids or not isinstance(box, dict):
            slot_blockers.append("box_missing_or_duplicate")
        if wb_id in duplicate_status_ids or not isinstance(status, dict):
            slot_blockers.append("status_missing_or_duplicate")
        if not isinstance(candidate, dict):
            slot_blockers.append("owner_candidate_missing")
        if slot_blockers:
            result["slots"][wb_id] = {
                "valid": False,
                "overrun_w": None,
                "blockers": slot_blockers,
            }
            result["blockers"].append("wb%d:%s" % (
                wb_id,
                slot_blockers[0],
            ))
            continue

        session_context = _wallbox_source_session_context(box)
        session_id = str(
            session_context.get("primary_session_id") or ""
        )
        session_context_blocker = str(
            (session_context.get("blockers") or [
                "session_context_invalid"
            ])[0]
        )
        candidate_session_mismatch = bool(
            session_id != str(candidate.get("plug_session_id") or "")
        )
        public_mode = normalize_wb_mode(
            modes.get(wb_id, modes.get(str(wb_id), MODE_OFF))
        )
        cap = box.get("_session_source_watt_cap")
        validation = wallbox_source_watt_cap.validate_source_watt_cap(
            cap,
            expected_wb_id=wb_id,
            expected_plug_session_id=session_id,
            expected_session_context_key=session_context.get(
                "session_context_key"
            ),
            expected_cycle_token=box.get("_wallbox_cycle_token"),
            expected_live_snapshot_id=snapshot_data.get("snapshot_id"),
            expected_status=status,
            expected_budget_revision=budget_revision,
            expected_decision_generation=decision_generation,
            expected_public_mode=public_mode,
        )
        if validation.get("valid") is not True:
            slot_blockers.append(
                str(validation.get("reason") or "source_cap_invalid")
            )
        if session_context.get("valid") is not True:
            slot_blockers.append(session_context_blocker)
        if candidate_session_mismatch:
            slot_blockers.append("plug_session_binding_mismatch")
        measurement = wallbox_source_watt_cap.measured_power_evidence(status)
        if measurement.get("valid") is not True:
            slot_blockers.append(
                str(measurement.get("reason") or "measurement_invalid")
            )

        if slot_blockers:
            result["slots"][wb_id] = {
                "valid": False,
                "overrun_w": None,
                "cap_validation": dict(validation),
                "measurement": dict(measurement),
                "blockers": slot_blockers,
            }
            result["blockers"].append("wb%d:%s" % (
                wb_id,
                slot_blockers[0],
            ))
            continue

        cap_w = float(validation["cap_w"])
        measured_w = float(measurement["power_w"])
        overrun_w = max(0.0, measured_w - cap_w)
        source_binding = str((cap or {}).get("source_binding_key") or "")
        source_bindings.add(source_binding)
        total_overrun_w += overrun_w
        result["slots"][wb_id] = {
            "valid": True,
            "cap_w": round(cap_w, 6),
            "measured_w": round(measured_w, 6),
            "overrun_w": round(overrun_w, 6),
            "source_class": validation.get("source_class"),
            "eligible_budget_tiers": validation.get(
                "eligible_budget_tiers"
            ),
            "cap_basis": validation.get("cap_basis"),
            "measurement_source": measurement.get("source"),
            "sample_key": measurement.get("sample_key"),
        }

    if len(source_bindings) > 1:
        result["blockers"].append("group_source_binding_mismatch")
    if result["blockers"]:
        result["blocker"] = result["blockers"][0]
        result["evidence"] = "incomplete_per_wallbox_source_account"
        return result

    positive_slots = [
        (wb_id, slot)
        for wb_id, slot in result["slots"].items()
        if isinstance(slot, dict)
        and _cfg_float(slot.get("overrun_w"), 0.0) > 0.0
    ]
    marginal_wb_id = 0
    if positive_slots:
        marginal_wb_id = int(max(
            positive_slots,
            key=lambda item: (
                0
                if bool(
                    (candidates_by_id.get(item[0]) or {}).get("priority")
                )
                else 1,
                _cfg_float(item[1].get("overrun_w"), 0.0),
                _cfg_float(item[1].get("measured_w"), 0.0),
                int(item[0]),
            ),
        )[0])

    result.update({
        "available": True,
        "complete": True,
        "value_w": round(total_overrun_w, 6),
        "marginal_wb_id": marginal_wb_id,
        "accounting": "grid_plus_bound_source_priority",
        "blocker": "",
        "evidence": "sum_positive_slot_overruns",
        "source_binding_key": next(iter(source_bindings), ""),
    })
    return result


def _wallbox_group_deficit_actual_phases(status):
    """Liefert nur eine aktuelle physische 1p-/3p-Evidenz.

    ``number_phases`` und ``pha`` beschreiben bei mehreren Treibern lediglich
    Kabel, Ziel oder Konfiguration. Sie dürfen den Defizitregler nicht zu einer
    elektromechanischen Aktion autorisieren.
    """

    st = status if isinstance(status, dict) else {}
    if st.get("phase_power_verified") is True:
        measured = sum(
            1
            for key in (
                "phase_power_l1_w",
                "phase_power_l2_w",
                "phase_power_l3_w",
            )
            if abs(_cfg_float(st.get(key), 0.0)) > 100.0
        )
        if measured in (1, 3):
            return measured, "verified_phase_power"
    for key in (
        "phase_actual_phases",
        "phases_actual",
        "phases_in_use",
    ):
        phases = _valid_phase_count(st.get(key), 0)
        if phases in (1, 3):
            return phases, key
    return 0, "physical_phase_unproven"


def _wallbox_group_deficit_reported_current(
    status,
    actual_phases=0,
    *,
    min_amp=6.0,
    current_step_amp=1.0,
    max_amp=16.0,
):
    """Liefert nur bestätigten Iststrom oder eine physische Ableitung.

    Insbesondere ``PARAM_1[2]`` der E3/DC-Wallbox ist derzeit nur ein rohes,
    semantisch unbestätigtes Byte. Ein daraus projiziertes ``amp`` darf keine
    Hardwareaktion autorisieren. Fehlt ein expliziter Treiber-Readback, wird
    der Strom deshalb ausschließlich aus einer als verifiziert markierten
    Phasenleistung und der belegten Istphasenzahl konservativ abgeleitet. Die
    Ableitung bleibt ohne Same-Frame-Vertrag reine Lade-/Diagnoseevidenz.
    """

    st = status if isinstance(status, dict) else {}
    confirmed_fields = (
        ("accepted_current_a", "accepted_current_confirmed"),
        ("offered_current_raw", "offered_current_confirmed"),
        ("offered_current", "offered_current_confirmed"),
        ("evse_current", "evse_current_confirmed"),
        ("param_current", "param_current_confirmed"),
        ("amp", "amp_readback_confirmed"),
    )
    confirmed = []
    for key, confirmation_key in confirmed_fields:
        if st.get(confirmation_key) is not True:
            continue
        value = _cfg_float(st.get(key), -1.0)
        if value >= 0.0:
            confirmed.append(value)
    if confirmed:
        return max(confirmed), "confirmed_driver_current"

    phases = _valid_phase_count(actual_phases, 0)
    if phases not in (1, 3) or st.get("phase_power_verified") is not True:
        return None, "current_unproven"
    phase_values = [
        abs(_cfg_float(st.get(key), 0.0))
        for key in (
            "phase_power_l1_w",
            "phase_power_l2_w",
            "phase_power_l3_w",
        )
    ]
    active_values = [value for value in phase_values if value > 100.0]
    if len(active_values) != phases:
        return None, "verified_phase_power_count_mismatch"
    # Ohne bestätigten Stromwert darf die Leistung nur eine konservative
    # Untergrenze für den real fließenden Strom liefern. 253 V entsprechen
    # der oberen zulässigen Netzspannung bei 230 V + 10 %; wegen
    # ``P <= U * I`` liegt der reale Strom nicht unter ``P / 253 V``.
    # Eine Ableitung mit 230 V plus Aufrundung könnte dagegen oberhalb des
    # tatsächlich angebotenen Stroms liegen und aus ``CURRENT_DOWN`` einen
    # versteckten Hochregelbefehl machen.
    derived = max(active_values) / 253.0
    if not math.isfinite(derived) or derived <= 0.0:
        return None, "verified_phase_power_current_invalid"
    step = max(0.1, _cfg_float(current_step_amp, 1.0))
    minimum = max(1.0, _cfg_float(min_amp, 6.0))
    maximum = max(minimum, _cfg_float(max_amp, 16.0))
    # Abrunden wahrt die Abregelrichtung auch bei hoher Netzspannung,
    # Messauflösung und cos(phi) < 1. Unterhalb des EVSE-Mindeststroms darf
    # die Ableitung nicht künstlich auf den Mindeststrom angehoben werden:
    # Dort ist sie nur noch Übergangs-/Abschaltevidenz und kein zulässiger
    # positiver Stromausgang. Die bestätigte Hardware-/Konfiggrenze bleibt
    # die obere Grenze.
    quantized = math.floor((derived + 1e-9) / step) * step
    return (
        min(maximum, max(0.0, quantized)),
        "verified_phase_power_current_lower_bound",
    )


def _wallbox_group_deficit_output_current_contract(
    c_data,
    status,
    *,
    min_amp=6.0,
    max_amp=16.0,
):
    """Bindet die Abregelbasis an den realen Ausgang derselben Sitzung.

    Ein gemessener Phasenstrom beziehungsweise eine Leistungsableitung kann
    vom EVSE-Angebot abweichen. Für eine monotone Sollwert-Abregelung zählt
    deshalb zuerst der letzte gebundene Ausgang oder ein frischer direkter
    EVSE-Angebotswert. Ungebundene alte Sitzungen und 0-A-Schattenwerte
    dürfen keine positive Ausgangsautorität erzeugen.
    """

    data = c_data if isinstance(c_data, dict) else {}
    st = status if isinstance(status, dict) else {}
    minimum = max(1.0, _cfg_float(min_amp, 6.0))
    maximum = max(minimum, _cfg_float(max_amp, 16.0))
    current_session_id = _wallbox_group_deficit_current_session_id(data)
    charger = data.get("charger")
    charger_class = charger.__class__.__name__ if charger is not None else ""
    status_fresh = bool(
        st.get("driver_status_valid") is True
        and st.get("driver_status_stale") is not True
        and st.get("driver_status_degraded") is not True
        and st.get("driver_status_glitch") is not True
        and st.get("driver_status_plausible") is not False
        and st.get("valid") is not False
        and st.get("stale") is not True
    )

    receipt_candidate = None
    readback_candidates = []
    receipt = data.get("_last_executed_command")
    receipt = receipt if isinstance(receipt, dict) else {}
    receipt_method = str(receipt.get("method") or "")
    receipt_session_id = str(receipt.get("plug_session_id") or "")
    receipt_session_bound = bool(
        current_session_id
        and receipt_session_id
        and receipt_session_id == current_session_id
    )
    native_stop_receipt = bool(
        receipt_method == "set_amp_sonnenmodus"
        and receipt.get("force_state") == 1
        and receipt.get("wire_receipt_contract")
        == "e3dc_wbchar6_wire_receipt_v1"
        and receipt.get("wire_receipt_new") is True
        and int(_cfg_float(receipt.get("wire_receipt_seq"), 0.0)) > 0
        and int(_cfg_float(receipt.get("wire_abort_flag"), 0.0)) == 1
        and receipt.get("wire_heartbeat") is False
        and receipt.get("stop_edge_issued") is True
    )
    if (
        receipt_method in _EFFECTIVE_CURRENT_METHODS
        and receipt_session_bound
        and not native_stop_receipt
    ):
        receipt_amp = _cfg_float(receipt.get("amp"), -1.0)
        if math.isfinite(receipt_amp) and receipt_amp >= 0.0:
            receipt_candidate = (
                receipt_amp,
                (
                    "same_session_zero_output_receipt"
                    if receipt_amp + 1e-9 < minimum
                    else "same_session_output_receipt"
                ),
                max(0.0, _cfg_float(receipt.get("ts"), 0.0)),
                bool(_cfg_float(receipt.get("ts"), 0.0) > 0.0),
            )

    status_sample_ts = max(
        0.0,
        _cfg_float(st.get("driver_status_last_ok_ts"), 0.0),
        _cfg_float(st.get("driver_status_last_sample_ts"), 0.0),
        _cfg_float(st.get("driver_status_last_good_ts"), 0.0),
        _cfg_float(st.get("native_status_sample_ts"), 0.0),
    )
    confirmed_status_fields = (
        ("offered_current_raw", "offered_current_confirmed"),
        ("offered_current", "offered_current_confirmed"),
        ("evse_current", "evse_current_confirmed"),
        ("amp", "amp_readback_confirmed"),
    )
    if status_fresh:
        for field, confirmation in confirmed_status_fields:
            if st.get(confirmation) is not True or field not in st:
                continue
            if (
                charger_class == "OpenWBProCharger"
                and field in (
                    "offered_current_raw",
                    "offered_current",
                    "evse_current",
                )
            ):
                # Die Pro besitzt dafür unten einen strengeren Vertrag aus
                # connect.php-Fläche, Payload-Gültigkeit und Bestätigungsbit.
                continue
            value = _cfg_float(st.get(field), -1.0)
            if math.isfinite(value) and value >= 0.0:
                readback_candidates.append(
                    (
                        value,
                        "confirmed_status:" + field,
                        status_sample_ts,
                        False,
                    )
                )

        if (
            charger_class == "OpenWBProCharger"
            and st.get("connect_php_payload_valid") is True
            and st.get("offered_current_confirmed") is True
            and str(st.get("api_surface") or "")
            == "openwb_pro_connect_php"
        ):
            # ``offered_current`` ist laut connect.php die offizielle
            # angebotene Stellgröße pro Phase. Nur das tatsächlich
            # vorhandene Rohfeld wird ausgewertet; ein fehlender Wert darf
            # nicht als 0 A erfunden werden.
            direct_offer = _cfg_float(
                st.get("offered_current_raw"),
                -1.0,
            )
            if (
                "offered_current_raw" in st
                and math.isfinite(direct_offer)
                and direct_offer >= 0.0
            ):
                direct_readback_ts = max(
                    0.0,
                    _cfg_float(
                        st.get("offered_current_readback_ts"),
                        0.0,
                    ),
                )
                direct_ts_exact = bool(direct_readback_ts > 0.0)
                if not direct_ts_exact:
                    direct_readback_ts = status_sample_ts
                readback_candidates.append(
                    (
                        direct_offer,
                        "openwb_pro_direct_offer",
                        direct_readback_ts,
                        direct_ts_exact,
                    )
                )
    readback_candidate = None
    if readback_candidates:
        readback_candidate = min(
            readback_candidates,
            key=lambda item: item[0],
        )

    # Status und Wire-Receipt sind kausal geordnete Zustände. Der belegbar
    # neuere ersetzt den älteren; ohne belastbare Zeitordnung gilt das
    # konservative Minimum. So darf weder ein alter 0-A-Stop einen späteren
    # externen Wiederanlauf unsichtbar machen noch ein alter positiver Receipt
    # einen frischen 0-A-Readback überstimmen.
    selected = []
    ordering = "single_source"
    if readback_candidate is not None and receipt_candidate is not None:
        readback_ts = readback_candidate[2]
        receipt_ts = receipt_candidate[2]
        exact_order = bool(
            readback_candidate[3] and receipt_candidate[3]
        )
        order_margin_s = 1e-6 if exact_order else 1.0
        if (
            readback_ts > 0.0
            and receipt_ts > 0.0
            and readback_ts - receipt_ts > order_margin_s
        ):
            selected = [readback_candidate]
            ordering = "newer_readback"
        elif (
            readback_ts > 0.0
            and receipt_ts > 0.0
            and receipt_ts - readback_ts > order_margin_s
        ):
            selected = [receipt_candidate]
            ordering = "newer_wire_receipt"
        else:
            selected = [readback_candidate, receipt_candidate]
            ordering = "unordered_conservative_minimum"
    elif readback_candidate is not None:
        selected = [readback_candidate]
    elif receipt_candidate is not None:
        selected = [receipt_candidate]

    trusted = [
        (min(maximum, value), source, sample_ts, exact_ts)
        for value, source, sample_ts, exact_ts in selected
        if math.isfinite(value) and value >= 0.0
    ]
    if not trusted:
        return {
            "contract": "wallbox_group_deficit_output_current_v1",
            "available": False,
            "ceiling_amp": None,
            "source": "bound_output_current_missing",
            "sources": [],
            "session_id": current_session_id,
            "output_authority": False,
        }

    ceiling_amp, source, source_ts, source_ts_exact = min(
        trusted,
        key=lambda item: item[0],
    )
    if ceiling_amp + 1e-9 < minimum:
        ceiling_amp = 0.0
    return {
        "contract": "wallbox_group_deficit_output_current_v1",
        "available": True,
        "ceiling_amp": round(float(ceiling_amp), 6),
        "source": source,
        "sources": [item[1] for item in trusted],
        "source_ts": source_ts if source_ts > 0.0 else None,
        "source_ts_exact": source_ts_exact,
        "ordering": ordering,
        "session_id": current_session_id,
        "output_authority": False,
    }


_GROUP_DEFICIT_CURRENT_DOWN_SETTLE_SCHEMA = (
    "wallbox_group_deficit_current_down_settle_v1"
)
_GROUP_DEFICIT_CURRENT_DOWN_SETTLE_MAX_S = 10.0
_GROUP_DEFICIT_CURRENT_DOWN_SETTLE_KEY = (
    "_wallbox_group_deficit_current_down_settle"
)


def _wallbox_group_deficit_settle_clock_sample(clock_sample=None):
    supplied = clock_sample if isinstance(clock_sample, dict) else None
    return dict(supplied) if supplied is not None else control_time.sample()


def _wallbox_group_deficit_status_sample_identity(status):
    st = status if isinstance(status, dict) else {}
    return {
        "seq": max(
            0,
            int(_cfg_float(st.get("native_status_sample_seq"), 0.0)),
            int(_cfg_float(st.get("driver_status_sample_seq"), 0.0)),
            int(_cfg_float(st.get("status_seq"), 0.0)),
        ),
        "ts": max(
            0.0,
            _cfg_float(st.get("native_status_sample_ts"), 0.0),
            _cfg_float(st.get("driver_status_last_ok_ts"), 0.0),
            _cfg_float(st.get("driver_status_last_sample_ts"), 0.0),
            _cfg_float(st.get("driver_status_last_good_ts"), 0.0),
            _cfg_float(st.get("offered_current_readback_ts"), 0.0),
            _cfg_float(st.get("accepted_current_readback_ts"), 0.0),
        ),
    }


def _wallbox_group_deficit_confirmed_status_current(c_data, status):
    """Liefert nur einen unzweideutig bestätigten EVSE-Ausgangsstrom."""

    data = c_data if isinstance(c_data, dict) else {}
    st = status if isinstance(status, dict) else {}
    charger = data.get("charger")
    charger_class = charger.__class__.__name__ if charger is not None else ""
    confirmed = []
    for field, flag in (
        ("accepted_current_a", "accepted_current_confirmed"),
        ("evse_current", "evse_current_confirmed"),
        ("param_current", "param_current_confirmed"),
        ("amp", "amp_readback_confirmed"),
    ):
        if st.get(flag) is not True or field not in st:
            continue
        value = _cfg_float(st.get(field), -1.0)
        if math.isfinite(value) and value >= 0.0:
            confirmed.append((value, field))
    if charger_class == "OpenWBProCharger":
        if (
            st.get("connect_php_payload_valid") is True
            and st.get("offered_current_confirmed") is True
            and str(st.get("api_surface") or "")
            == "openwb_pro_connect_php"
            and "offered_current_raw" in st
        ):
            value = _cfg_float(st.get("offered_current_raw"), -1.0)
            if math.isfinite(value) and value >= 0.0:
                confirmed.append((value, "openwb_pro_direct_offer"))
    else:
        for field in ("offered_current_raw", "offered_current"):
            if st.get("offered_current_confirmed") is not True:
                continue
            if field not in st:
                continue
            value = _cfg_float(st.get(field), -1.0)
            if math.isfinite(value) and value >= 0.0:
                confirmed.append((value, field))
    if not confirmed:
        return {"available": False, "value_amp": None, "sources": []}
    # Widersprüchliche bestätigte Felder dürfen keinen 0-A-Veto erfinden.
    return {
        "available": True,
        "value_amp": max(value for value, _ in confirmed),
        "sources": [field for _, field in confirmed],
    }


def _wallbox_group_deficit_phase_sequence_active(
    c_data,
    *,
    now_ts,
    status=None,
):
    """True nur solange bereits eine reale Phasensequenz gebunden ist."""

    data = c_data if isinstance(c_data, dict) else {}
    st = status if isinstance(status, dict) else {}
    if any(
        bool(st.get(key, False))
        for key in (
            "cp_interrupt_isactive",
            "phase_switching",
            "phase_change_active",
            "phase_transition_active",
        )
    ):
        return True
    if bool(data.get("_openwb_pro_cp_interrupt_active", False)):
        return True
    terminal_stages = {"", "ready", "completed", "aborted", "idle", "expired"}
    sequence = data.get("_openwb_pro_phase_sequence")
    if isinstance(sequence, dict) and sequence:
        if str(sequence.get("stage") or "") not in terminal_stages:
            return True
    reservation = data.get("_wallbox_phase_transition_reservation")
    if isinstance(reservation, dict) and reservation.get("active") is True:
        if str(reservation.get("stage") or "") not in terminal_stages:
            return True
    recovery = data.get("_openwb_pro_phase_recovery_hold")
    if isinstance(recovery, dict) and recovery.get("active") is True:
        return True
    return bool(
        _cfg_float(data.get("_openwb_pro_phase_wait_until"), 0.0)
        > _cfg_float(now_ts, 0.0)
    )


def _release_wallbox_group_deficit_current_down_settle(
    c_data,
    *,
    reason,
    now_ts,
):
    """Löst den kurzen No-Output-Vertrag und bewahrt nur Diagnoseevidenz."""

    data = c_data if isinstance(c_data, dict) else {}
    contract = data.pop(_GROUP_DEFICIT_CURRENT_DOWN_SETTLE_KEY, None)
    data["_central_deficit_current_down_settle_active"] = False
    data["_central_deficit_current_down_settle_cycle_token"] = ""
    if not isinstance(contract, dict):
        return {}
    released = dict(contract)
    released.update({
        "active": False,
        "release_reason": str(reason or "released"),
        "released_ts": _cfg_float(now_ts, 0.0),
    })
    data["_wallbox_group_deficit_current_down_settle_last"] = released
    return released


def _mint_wallbox_group_deficit_current_down_settle(
    c_data,
    receipt,
    *,
    candidate,
    status,
    now_ts,
    clock_sample=None,
):
    """Mintet nach einem bestätigten CURRENT_DOWN exakt 10 s No-Output-Zeit."""

    data = c_data if isinstance(c_data, dict) else {}
    wire_receipt = receipt if isinstance(receipt, dict) else {}
    owner = candidate if isinstance(candidate, dict) else {}
    st = status if isinstance(status, dict) else {}
    binding = data.get("_wallbox_group_deficit_action_binding")
    binding = binding if isinstance(binding, dict) else {}
    generation = data.get("_wallbox_group_deficit_generation_contract")
    generation = generation if isinstance(generation, dict) else {}
    now_value = _cfg_float(now_ts, 0.0)
    wb_id = int(_cfg_float(data.get("id"), 0.0))
    session_id = _wallbox_group_deficit_current_session_id(data)
    binding_generation = int(
        _cfg_float(binding.get("binding_generation"), 0.0)
    )
    target_amp = _cfg_float(binding.get("target_amp"), -1.0)
    minimum_amp = max(1.0, _cfg_float(owner.get("minimum_amp"), 6.0))
    action_latch_id = str(binding.get("action_latch_id") or "")
    cycle_token = str(data.get("_wallbox_cycle_token") or "")
    receipt_ts = _cfg_float(wire_receipt.get("ts"), 0.0)
    sample_identity = _wallbox_group_deficit_status_sample_identity(st)
    time_sample = _wallbox_group_deficit_settle_clock_sample(clock_sample)
    time_guard = control_time.begin_guard(
        _GROUP_DEFICIT_CURRENT_DOWN_SETTLE_MAX_S,
        time_sample,
        minimum_s=0.0,
    )
    phase_sequence_active = _wallbox_group_deficit_phase_sequence_active(
        data,
        now_ts=now_value,
        status=st,
    )
    valid = bool(
        now_value > 0.0
        and wb_id > 0
        and session_id
        and cycle_token
        and not phase_sequence_active
        and binding.get("schema") == _GROUP_DEFICIT_ACTION_BINDING_SCHEMA
        and binding.get("active") is True
        and str(binding.get("action") or "")
        == wallbox_deficit_control.ACTION_CURRENT_DOWN
        and int(_cfg_float(binding.get("wb_id"), 0.0)) == wb_id
        and str(binding.get("plug_session_id") or "") == session_id
        and binding_generation > 0
        and action_latch_id.startswith("sha256:")
        and str(binding.get("cycle_token") or "") == cycle_token
        and generation.get("contract")
        == "wallbox_group_deficit_generation_v1"
        and generation.get("binding_ready") is True
        and int(_cfg_float(generation.get("effective_owner_id"), 0.0))
        == wb_id
        and int(_cfg_float(generation.get("binding_generation"), 0.0))
        == binding_generation
        and str(wire_receipt.get("method") or "")
        in (
            "set_amp_and_state",
            "set_current",
            "set_direct_current",
            "set_amp_sonnenmodus",
            "set_amp_autonomous_solar",
        )
        and str(wire_receipt.get("reason") or "")
        == "group_deficit_current_down"
        and str(wire_receipt.get("cycle_token") or "") == cycle_token
        and str(wire_receipt.get("plug_session_id") or "") == session_id
        and abs(_cfg_float(wire_receipt.get("amp"), -1.0) - target_amp)
        <= 0.051
        and receipt_ts > 0.0
        and time_guard.get("valid") is True
        and time_guard.get("fail_closed") is False
        and time_guard.get("active") is True
        and target_amp + 1e-6 >= minimum_amp
    )
    if not valid:
        _release_wallbox_group_deficit_current_down_settle(
            data,
            reason=(
                "phase_sequence_active"
                if phase_sequence_active
                else "current_down_receipt_binding_invalid"
            ),
            now_ts=now_value,
        )
        return {}
    actual_phases = int(_cfg_float(owner.get("actual_phases"), 0.0))
    if actual_phases not in (1, 3):
        actual_phases = 0
    current_step_amp = _normalize_current_step_amp(
        owner.get("current_step_amp"),
        default=1.0,
    )
    receipt_identity = {
        "method": str(wire_receipt.get("method") or ""),
        "reason": str(wire_receipt.get("reason") or ""),
        "amp": _cfg_float(wire_receipt.get("amp"), -1.0),
        "cycle_token": str(wire_receipt.get("cycle_token") or ""),
        "plug_session_id": str(
            wire_receipt.get("plug_session_id") or ""
        ),
        "ts": receipt_ts,
    }
    contract = {
        "schema": _GROUP_DEFICIT_CURRENT_DOWN_SETTLE_SCHEMA,
        "active": True,
        "wb_id": wb_id,
        "plug_session_id": session_id,
        "binding_generation": binding_generation,
        "action_latch_id": action_latch_id,
        "receipt_cycle_token": cycle_token,
        "receipt_method": receipt_identity["method"],
        "receipt_reason": receipt_identity["reason"],
        "receipt_amp": receipt_identity["amp"],
        "receipt_plug_session_id": receipt_identity["plug_session_id"],
        "receipt_ts": receipt_ts,
        "receipt_identity": receipt_identity,
        "receipt_identity_hash": revision_hash(receipt_identity),
        "pre_status_sample_seq": int(sample_identity.get("seq", 0) or 0),
        "pre_status_sample_ts": _cfg_float(
            sample_identity.get("ts"),
            0.0,
        ),
        "time_guard": dict(time_guard),
        "started_ts": now_value,
        "target_amp": target_amp,
        "minimum_amp": minimum_amp,
        "current_step_amp": current_step_amp,
        "actual_phases": actual_phases,
        "no_output": True,
    }
    data[_GROUP_DEFICIT_CURRENT_DOWN_SETTLE_KEY] = contract
    data["_central_deficit_current_down_settle_active"] = True
    data["_central_deficit_current_down_settle_cycle_token"] = cycle_token
    return dict(contract)


def _wallbox_group_deficit_current_down_settle_retention(
    runtime,
    chargers,
    statuses,
    charge_modes,
    *,
    excluded_ids=None,
    priority_mode=0,
    allocation_contract=None,
    min_amp=6,
    live_snapshot_valid=True,
    live_snapshot_fresh=True,
    live_sample_invalid=False,
    now_ts,
    clock_sample=None,
):
    """Hält ausschließlich den Cutover nach einem bestätigten Stromschritt."""

    boxes = [item for item in (chargers or ()) if isinstance(item, dict)]
    status_by_id = {
        int(_cfg_float(item.get("id"), 0.0)): item.get("status")
        for item in (statuses or ())
        if isinstance(item, dict)
        and int(_cfg_float(item.get("id"), 0.0)) > 0
        and isinstance(item.get("status"), dict)
    }
    excluded = {
        int(_cfg_float(value, 0.0))
        for value in (excluded_ids or ())
        if int(_cfg_float(value, 0.0)) > 0
    }
    modes = charge_modes if isinstance(charge_modes, dict) else {}
    allocation = (
        allocation_contract if isinstance(allocation_contract, dict) else {}
    )
    slots = allocation.get("slots")
    slots = slots if isinstance(slots, dict) else {}
    binding_state = getattr(runtime, "group_deficit_binding", None)
    binding_state = binding_state if isinstance(binding_state, dict) else {}
    now_value = _cfg_float(now_ts, 0.0)
    current_clock_sample = _wallbox_group_deficit_settle_clock_sample(
        clock_sample
    )
    minimum = max(1.0, _cfg_float(min_amp, 6.0))
    priority_id = int(_cfg_float(priority_mode, 0.0))
    if priority_id not in (1, 2):
        priority_id = 0

    for data in boxes:
        contract = data.get(_GROUP_DEFICIT_CURRENT_DOWN_SETTLE_KEY)
        if not isinstance(contract, dict) or contract.get("active") is not True:
            continue
        wb_id = int(_cfg_float(data.get("id"), 0.0))
        status = status_by_id.get(wb_id)
        session_id = _wallbox_group_deficit_current_session_id(data)
        action_binding = data.get("_wallbox_group_deficit_action_binding")
        action_binding = (
            action_binding if isinstance(action_binding, dict) else {}
        )
        generation = data.get("_wallbox_group_deficit_generation_contract")
        generation = generation if isinstance(generation, dict) else {}
        dispatch = data.get("_wallbox_group_deficit_action_dispatch")
        dispatch = dispatch if isinstance(dispatch, dict) else {}
        last_receipt = data.get("_last_executed_command")
        last_receipt = last_receipt if isinstance(last_receipt, dict) else {}
        started_ts = _cfg_float(contract.get("started_ts"), 0.0)
        target_amp = _cfg_float(contract.get("target_amp"), -1.0)
        contract_minimum = max(
            minimum,
            _cfg_float(contract.get("minimum_amp"), minimum),
        )
        binding_generation = int(
            _cfg_float(contract.get("binding_generation"), 0.0)
        )
        action_latch_id = str(contract.get("action_latch_id") or "")
        receipt_identity = contract.get("receipt_identity")
        receipt_identity = (
            receipt_identity if isinstance(receipt_identity, dict) else {}
        )
        current_receipt_identity = {
            "method": str(last_receipt.get("method") or ""),
            "reason": str(last_receipt.get("reason") or ""),
            "amp": _cfg_float(last_receipt.get("amp"), -1.0),
            "cycle_token": str(last_receipt.get("cycle_token") or ""),
            "plug_session_id": str(
                last_receipt.get("plug_session_id") or ""
            ),
            "ts": _cfg_float(last_receipt.get("ts"), 0.0),
        }
        receipt_identity_hash = str(
            contract.get("receipt_identity_hash") or ""
        )
        time_guard = contract.get("time_guard")
        time_guard = time_guard if isinstance(time_guard, dict) else {}
        guard_duration_s = _cfg_float(time_guard.get("duration_s"), -1.0)
        release_reason = ""
        if (
            contract.get("schema")
            != _GROUP_DEFICIT_CURRENT_DOWN_SETTLE_SCHEMA
            or wb_id <= 0
            or int(_cfg_float(contract.get("wb_id"), 0.0)) != wb_id
            or not session_id
            or str(contract.get("plug_session_id") or "") != session_id
            or binding_generation <= 0
            or not action_latch_id.startswith("sha256:")
            or started_ts <= 0.0
            or not receipt_identity_hash.startswith("sha256:")
            or revision_hash(receipt_identity) != receipt_identity_hash
            or guard_duration_s <= 0.0
            or guard_duration_s
            > _GROUP_DEFICIT_CURRENT_DOWN_SETTLE_MAX_S + 1e-6
        ):
            release_reason = "settle_contract_invalid"
        elif revision_hash(current_receipt_identity) != receipt_identity_hash:
            release_reason = "output_receipt_replaced"
        elif not (
            dispatch.get("contract")
            == "wallbox_group_deficit_action_dispatch_v1"
            and str(dispatch.get("action") or "")
            == wallbox_deficit_control.ACTION_CURRENT_DOWN
            and dispatch.get("confirmed") is True
            and str(dispatch.get("action_latch_id") or "")
            == action_latch_id
            and str(dispatch.get("cycle_token") or "")
            == str(contract.get("receipt_cycle_token") or "")
        ):
            release_reason = "current_down_dispatch_replaced_or_unconfirmed"
        else:
            evaluated_guard = control_time.evaluate_guard(
                time_guard,
                current_clock_sample,
                minimum_s=0.0,
            )
            if (
                evaluated_guard.get("valid") is not True
                or evaluated_guard.get("fail_closed") is True
                or evaluated_guard.get("rearmed") is True
            ):
                release_reason = "settle_timebase_invalid"
            elif evaluated_guard.get("active") is not True:
                release_reason = "settle_expired"
            else:
                contract = dict(contract)
                contract["time_guard"] = dict(evaluated_guard)
                data[_GROUP_DEFICIT_CURRENT_DOWN_SETTLE_KEY] = contract
        if not release_reason and not bool(live_snapshot_valid):
            release_reason = "live_snapshot_invalid"
        elif not release_reason and (
            not bool(live_snapshot_fresh) or bool(live_sample_invalid)
        ):
            release_reason = "live_snapshot_stale_or_invalid"
        elif not release_reason and normalize_wb_mode(
            modes.get(wb_id, modes.get(str(wb_id), MODE_OFF))
        ) == MODE_OFF:
            release_reason = "mode_off"
        elif not release_reason and wb_id in excluded:
            release_reason = "explicit_or_hard_exclusion"
        elif not release_reason and bool(
            data.get("_physical_output_blocked", False)
            or data.get("_bev_full_blocked", False)
            or data.get("_emergency_stop_active", False)
            or data.get("_notaus_active", False)
            or data.get("_manual_pause_active", False)
        ):
            release_reason = "hard_output_block"
        elif not release_reason and _wallbox_group_deficit_phase_sequence_active(
            data,
            now_ts=now_value,
            status=status,
        ):
            release_reason = "phase_sequence_active"
        elif not release_reason and not (
            action_binding.get("schema")
            == _GROUP_DEFICIT_ACTION_BINDING_SCHEMA
            and action_binding.get("active") is True
            and str(action_binding.get("action") or "")
            == wallbox_deficit_control.ACTION_CURRENT_DOWN
            and int(_cfg_float(action_binding.get("wb_id"), 0.0)) == wb_id
            and str(action_binding.get("plug_session_id") or "")
            == session_id
            and int(
                _cfg_float(action_binding.get("binding_generation"), 0.0)
            )
            == binding_generation
            and str(action_binding.get("action_latch_id") or "")
            == action_latch_id
            and generation.get("contract")
            == "wallbox_group_deficit_generation_v1"
            and int(_cfg_float(generation.get("effective_owner_id"), 0.0))
            == wb_id
            and int(
                _cfg_float(generation.get("binding_generation"), 0.0)
            )
            == binding_generation
            and int(_cfg_float(binding_state.get("owner_id"), 0.0)) == wb_id
            and int(
                _cfg_float(binding_state.get("binding_generation"), 0.0)
            )
            == binding_generation
        ):
            release_reason = "owner_generation_or_latch_changed"
        elif not release_reason:
            slot = slots.get(wb_id, slots.get(str(wb_id)))
            slot = slot if isinstance(slot, dict) else {}
            priority_forced_stop = bool(
                priority_id
                and wb_id != priority_id
                and slot
                and (
                    int(_cfg_float(slot.get("allocated_state"), 1.0)) != 2
                    or _cfg_float(slot.get("allocated_amp"), 0.0)
                    + 1e-6
                    < contract_minimum
                )
            )
            if priority_forced_stop:
                release_reason = "priority_forced_stop"
        if not release_reason:
            status_fresh = bool(
                isinstance(status, dict)
                and status.get("driver_status_valid") is True
                and not bool(status.get("driver_status_stale", False))
                and not bool(status.get("driver_status_degraded", False))
                and not bool(status.get("driver_status_glitch", False))
                and status.get("driver_status_plausible") is not False
                and status.get("valid") is not False
                and not bool(status.get("stale", False))
            )
            if not status_fresh:
                release_reason = "status_not_fresh"
            elif not _wb_status_connected(status):
                release_reason = "vehicle_not_connected"
            elif wallbox_decision.status_charge_truth(status) == "unknown":
                release_reason = "charge_truth_unknown"
        sample_identity = _wallbox_group_deficit_status_sample_identity(
            status
        )
        post_receipt_sample = bool(
            int(sample_identity.get("seq", 0) or 0)
            > int(contract.get("pre_status_sample_seq", 0) or 0)
            or _cfg_float(sample_identity.get("ts"), 0.0)
            > _cfg_float(contract.get("receipt_ts"), 0.0)
        )
        if not release_reason and not post_receipt_sample:
            release_reason = "post_receipt_sample_not_advanced"
        if release_reason:
            _release_wallbox_group_deficit_current_down_settle(
                data,
                reason=release_reason,
                now_ts=now_value,
            )
            continue

        actual_phases = int(_cfg_float(contract.get("actual_phases"), 0.0))
        current_step_amp = _normalize_current_step_amp(
            contract.get("current_step_amp"),
            default=1.0,
        )
        reported_current, current_source = (
            _wallbox_group_deficit_reported_current(
                status,
                actual_phases=actual_phases,
                min_amp=contract_minimum,
                current_step_amp=current_step_amp,
                max_amp=max(
                    contract_minimum,
                    _cfg_float(
                        getattr(data.get("charger"), "max_amp", 32.0),
                        32.0,
                    ),
                ),
            )
        )
        confirmed_output = _wallbox_group_deficit_confirmed_status_current(
            data,
            status,
        )
        confirmed_output_amp = confirmed_output.get("value_amp")
        if (
            confirmed_output.get("available") is True
            and confirmed_output_amp is not None
            and _cfg_float(confirmed_output_amp, 0.0) + 0.051
            < contract_minimum
        ):
            _release_wallbox_group_deficit_current_down_settle(
                data,
                reason="confirmed_output_below_minimum",
                now_ts=now_value,
            )
            continue
        target_confirmed = bool(
            confirmed_output.get("available") is True
            and confirmed_output_amp is not None
            and abs(float(confirmed_output_amp) - target_amp)
            <= max(0.051, current_step_amp / 2.0 + 0.001)
        )
        real_charging = _wallbox_status_fresh_real_charging(status)
        if target_confirmed and real_charging:
            _release_wallbox_group_deficit_current_down_settle(
                data,
                reason="target_current_and_charge_confirmed",
                now_ts=now_value,
            )
            continue

        updated = dict(contract)
        updated.update({
            "last_checked_ts": now_value,
            "target_current_confirmed": target_confirmed,
            "real_charging_confirmed": real_charging,
            "observed_current_amp": (
                round(float(reported_current), 3)
                if reported_current is not None
                else None
            ),
            "observed_current_source": str(current_source or ""),
            "confirmed_output_amp": (
                round(float(confirmed_output_amp), 3)
                if confirmed_output_amp is not None
                else None
            ),
            "confirmed_output_sources": list(
                confirmed_output.get("sources") or ()
            ),
            "post_receipt_sample": post_receipt_sample,
        })
        data[_GROUP_DEFICIT_CURRENT_DOWN_SETTLE_KEY] = updated
        data["_central_deficit_current_down_settle_active"] = True
        data["_central_deficit_current_down_settle_cycle_token"] = str(
            data.get("_wallbox_cycle_token") or ""
        )
        return {
            **updated,
            "owner_id": wb_id,
            "stage": "current_down_settle",
            "fallback_phases": actual_phases,
            "legacy_suppressed": True,
            "new_output_authorized": False,
        }
    return {}


def _wallbox_group_deficit_pending_retention(runtime):
    state = getattr(runtime, "group_deficit_state", None)
    state = state if isinstance(state, dict) else {}
    cascade = state.get("cascade")
    cascade = cascade if isinstance(cascade, dict) else {}
    stage = str(cascade.get("stage") or "")
    if stage not in (
        wallbox_deficit_control.STAGE_PHASE_DOWN_PENDING,
        wallbox_deficit_control.STAGE_STOP_PENDING,
    ):
        return {}
    owner_id = int(_cfg_float(state.get("marginal_wb_id"), 0.0))
    if owner_id <= 0:
        return {}
    if stage == wallbox_deficit_control.STAGE_PHASE_DOWN_PENDING:
        phases = 3
    else:
        topology = str(cascade.get("topology") or "")
        phases = (
            1
            if topology == wallbox_deficit_control.TOPOLOGY_FIXED_ONE
            or str(cascade.get("stage") or "").startswith("one_phase")
            else 3
        )
    return {
        "owner_id": owner_id,
        "stage": stage,
        "fallback_phases": phases,
    }


def _wallbox_group_deficit_owner_contract(
    chargers,
    statuses,
    charge_modes,
    *,
    config,
    vehicle_profiles,
    allocatable_by_id=None,
    priority_mode=0,
    min_amp=6,
    allocation_contract=None,
    excluded_ids=None,
    pending_retention=None,
):
    """Wählt deterministisch den einzigen marginalen PCC-Aktionsbesitzer."""

    modes = charge_modes if isinstance(charge_modes, dict) else {}
    allocatable = (
        allocatable_by_id if isinstance(allocatable_by_id, dict) else None
    )
    allocation = (
        allocation_contract if isinstance(allocation_contract, dict) else {}
    )
    slots = allocation.get("slots")
    slots = slots if isinstance(slots, dict) else {}
    excluded = {
        int(_cfg_float(value, 0.0))
        for value in (excluded_ids or ())
        if int(_cfg_float(value, 0.0)) > 0
    }
    retained = pending_retention if isinstance(pending_retention, dict) else {}
    retained_owner_id = int(_cfg_float(retained.get("owner_id"), 0.0))
    minimum = max(1.0, _cfg_float(min_amp, 6.0))
    priority_id = int(_cfg_float(priority_mode, 0.0))
    if priority_id not in (1, 2):
        priority_id = 0

    status_by_id = {}
    for item in statuses or []:
        entry = item if isinstance(item, dict) else {}
        wb_id = int(_cfg_float(entry.get("id"), 0.0))
        status = entry.get("status")
        if wb_id > 0 and isinstance(status, dict):
            status_by_id[wb_id] = status

    candidates = []
    excluded_diagnostics = {}
    for item in chargers or []:
        data = item if isinstance(item, dict) else {}
        wb_id = int(_cfg_float(data.get("id"), 0.0))
        if wb_id <= 0:
            continue
        status = status_by_id.get(wb_id)
        blockers = []
        if wb_id in excluded:
            blockers.append("explicit_policy_or_safety_exclusion")
        if normalize_wb_mode(
            modes.get(wb_id, modes.get(str(wb_id), MODE_OFF))
        ) == MODE_OFF:
            blockers.append("mode_off")
        # ``allocatable=false`` ist gerade bei Storage-Deckel 0 kein
        # physischer Off-Zustand. Eine bereits ladende Wallbox bleibt als
        # marginaler Defizit-Owner sichtbar; die Allokation beeinflusst nur
        # die deterministische Auswahl weiter unten.
        if bool(
            data.get("_physical_output_blocked", False)
            or data.get("_bev_full_blocked", False)
            or data.get("_emergency_stop_active", False)
            or data.get("_notaus_active", False)
        ):
            blockers.append("hard_output_block")
        # Der alte E3/DC-Floor ist eine abzulösende Legacy-Regel und keine
        # harte Safety-/Aus-Schranke. Er darf den zentralen Owner nicht
        # ausblenden und dadurch seinen eigenen Stop-Pfad wieder aktivieren.
        if not isinstance(status, dict):
            blockers.append("status_missing")
            status = {}
        status_fresh = bool(
            status.get("driver_status_valid") is True
            and not bool(status.get("driver_status_stale", False))
            and not bool(status.get("driver_status_degraded", False))
            and not bool(status.get("driver_status_glitch", False))
            and status.get("driver_status_plausible") is not False
            and status.get("valid") is not False
            and not bool(status.get("stale", False))
        )
        if not status_fresh:
            blockers.append("status_not_fresh")
        connected = _wb_status_connected(status)
        if not connected:
            blockers.append("vehicle_not_connected")

        session_id = str(
            data.get(wallbox_start_hold.SESSION_KEY)
            or data.get("_openwb_pro_plug_session_id")
            or data.get("_wallbox_plug_episode_id")
            or ""
        ).strip()
        if not session_id:
            blockers.append("plug_session_missing")

        pending_owner = bool(
            wb_id == retained_owner_id
            and retained.get("stage")
            in (
                wallbox_deficit_control.STAGE_PHASE_DOWN_PENDING,
                wallbox_deficit_control.STAGE_STOP_PENDING,
            )
        )
        real_charging = _wallbox_status_fresh_real_charging(status)
        if not real_charging and not pending_owner:
            blockers.append("real_charge_not_confirmed")

        actual_phases, phase_source = _wallbox_group_deficit_actual_phases(
            status
        )
        if actual_phases not in (1, 3) and pending_owner:
            actual_phases = int(
                _cfg_float(retained.get("fallback_phases"), 0.0)
            )
            phase_source = "pending_same_session_previous_physics"
        if actual_phases not in (1, 3):
            blockers.append("actual_phase_unproven")

        charger = data.get("charger")
        current_output_blocker = ""
        if (
            charger is not None
            and charger.__class__.__name__ == "OpenWBCharger"
            and getattr(charger, "primary_mode_enabled", False) is True
        ):
            blockers.append("openwb_primary_current_only_output_unproven")
        if (
            e3dc_session.is_e3dc_native_charger(charger)
            and not _native_group_deficit_current_output_method(data, status)
        ):
            # Ein unbekannter oder nicht für diesen Zyklus versiegelter
            # WBchar6-Modus verbietet jeden zentralen Defizitausgang, darf die
            # physisch ladende efy aber nicht aus dem Candidate-Claim werfen.
            # Sonst würden genau dort alte Floor-/Grid-Pfade wieder aktiv.
            current_output_blocker = "native_running_mode_output_unbound"
        current_step_amp = _current_step_amp_for_charger(
            charger,
            default=1.0,
        )
        charger_max_amp = max(
            minimum,
            _cfg_float(
                getattr(charger, "max_amp", data.get("max_amp", 16.0)),
                16.0,
            ),
        )
        reported_current, current_source = (
            _wallbox_group_deficit_reported_current(
                status,
                actual_phases=actual_phases,
                min_amp=minimum,
                current_step_amp=current_step_amp,
                max_amp=charger_max_amp,
            )
        )
        output_current = _wallbox_group_deficit_output_current_contract(
            data,
            status,
            min_amp=minimum,
            max_amp=charger_max_amp,
        )
        if reported_current is None and pending_owner:
            reported_current = max(
                0.0,
                _cfg_float(data.get("current_set_amp"), 0.0),
            )
            current_source = "pending_same_session_previous_command"
        if reported_current is None:
            blockers.append("reported_current_missing")
            effective_current = 0.0
        else:
            physical_current = max(0.0, float(reported_current))
            if output_current.get("available") is True:
                output_ceiling = max(
                    0.0,
                    _cfg_float(output_current.get("ceiling_amp"), 0.0),
                )
                if output_ceiling + 1e-6 < minimum:
                    blockers.append("bound_output_current_below_minimum")
                    effective_current = 0.0
                elif current_source == "confirmed_driver_current":
                    effective_current = min(
                        physical_current,
                        output_ceiling,
                    )
                    current_source = (
                        "confirmed_driver_current_with_output_ceiling"
                    )
                else:
                    # Ein sessionsgebundener Sollausgang ist für die
                    # Monotonie maßgeblich. Die physische Leistungsableitung
                    # belegt weiter die laufende Ladung, darf den bekannten
                    # Sollwert aber weder anheben noch künstlich absenken.
                    effective_current = output_ceiling
                    current_source = str(
                        output_current.get("source")
                        or "bound_output_current"
                    )
            else:
                # Die aus Phasenleistung abgeleitete Größe belegt nur, dass
                # und in welcher Größenordnung gerade geladen wird. Manche
                # Treiber halten fehlende Phasenwerte kurz aus einem Altframe;
                # ohne expliziten Same-Frame-Vertrag wäre sie daher keine
                # sichere Sollwertobergrenze. CURRENT_DOWN bleibt bis zu einem
                # frischen EVSE-Readback oder sitzungsgebundenen Wire-Receipt
                # ausgangsseitig gesperrt.
                effective_current = physical_current
            if real_charging and effective_current + 1e-6 < minimum:
                blockers.append("reported_current_below_minimum")

        charger_class = charger.__class__.__name__ if charger is not None else ""
        phase_capability = _wallbox_phase_switch_capability(
            charger_class,
            status,
            config,
        )
        vehicle_capability = VehicleManager.vehicle_phase_capability(
            status=status,
            profiles=vehicle_profiles,
            config=config,
            charger_id=wb_id,
        )
        vehicle_veto = wallbox_decision.vehicle_phase_switch_veto_contract(
            vehicle_capability,
            status,
        )
        supports_phase_switch = bool(
            charger is not None
            and hasattr(charger, "set_phases")
            and phase_capability.get("can_switch") is True
            and vehicle_veto.get("active") is not True
        )
        slot = slots.get(wb_id, slots.get(str(wb_id)))
        if isinstance(slot, dict) and "allocated" in slot:
            allocated = slot.get("allocated") is True
        elif isinstance(slot, dict) and "allocatable" in slot:
            allocated = slot.get("allocatable") is True
        elif allocatable is not None and (
            wb_id in allocatable or str(wb_id) in allocatable
        ):
            allocated = bool(
                allocatable.get(wb_id, allocatable.get(str(wb_id)))
            )
        else:
            allocated = None
        if blockers:
            excluded_diagnostics[wb_id] = tuple(blockers)
            continue
        candidates.append({
            "id": wb_id,
            "plug_session_id": session_id,
            "minimum_amp": minimum,
            "current_amp": round(effective_current, 3),
            "current_source": current_source,
            "physical_current_amp": (
                round(float(reported_current), 3)
                if reported_current is not None
                else None
            ),
            "output_current_contract": dict(output_current),
            "actual_phases": actual_phases,
            "actual_phase_source": phase_source,
            "current_step_amp": current_step_amp,
            "max_amp": charger_max_amp,
            "power_w": round(
                effective_current * 230.0 * float(actual_phases),
                3,
            ),
            "allocated": allocated,
            "priority": bool(priority_id and wb_id == priority_id),
            "supports_phase_switch": supports_phase_switch,
            "prevent_phase_switch": bool(vehicle_veto.get("active") is True),
            "phase_switch_capability": dict(phase_capability),
            "vehicle_phase_capability": dict(vehicle_capability),
            "vehicle_phase_veto": dict(vehicle_veto),
            "pending_retained": pending_owner,
            "current_output_blocker": current_output_blocker,
            "current_output_ready": not bool(current_output_blocker),
        })

    unallocated = [
        item for item in candidates if item.get("allocated") is False
    ]
    if unallocated:
        owner = max(
            unallocated,
            key=lambda value: (value["power_w"], value["id"]),
        )
        owner_reason = "unallocated_candidate_first"
    elif priority_id and any(
        item["id"] == priority_id for item in candidates
    ):
        non_priority = [
            item for item in candidates if item["id"] != priority_id
        ]
        pool = non_priority or candidates
        owner = max(
            pool,
            key=lambda value: (value["power_w"], value["id"]),
        ) if pool else None
        owner_reason = (
            "protect_priority_candidate"
            if non_priority
            else "only_priority_candidate"
        )
    else:
        owner = max(
            candidates,
            key=lambda value: (value["power_w"], value["id"]),
        ) if candidates else None
        owner_reason = (
            "largest_marginal_load_first"
            if owner is not None
            else "no_deficit_candidate"
        )

    def _signature(value):
        encoded = json.dumps(
            value,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
        return "sha256:" + hashlib.sha256(encoded).hexdigest()

    candidate_ids = [int(item["id"]) for item in candidates]
    owner_id = int((owner or {}).get("id", 0) or 0)
    candidate_material = [
        {
            "id": int(item["id"]),
            "allocated": item.get("allocated"),
        }
        for item in candidates
    ]
    session_material = [
        {
            "id": int(item["id"]),
            "plug_session_id": str(item.get("plug_session_id") or ""),
        }
        for item in candidates
    ]
    return {
        "contract": "wallbox_group_deficit_owner_v1",
        "owner_id": owner_id,
        "owner_reason": owner_reason,
        "candidate_ids": candidate_ids,
        "retained_candidate_ids": [
            candidate_id
            for candidate_id in candidate_ids
            if candidate_id != owner_id
        ],
        "candidate_signature": _signature(candidate_material),
        "session_signature": _signature(session_material),
        "priority_id": priority_id,
        "minimum_amp": minimum,
        "energy_meter_scope": "pcc_group_once",
        "candidates": candidates,
        "excluded": excluded_diagnostics,
    }


def _wallbox_group_deficit_generation_contract(
    runtime,
    owner_contract,
    chargers,
):
    """Bindet den Owner sitzungsfest und erst ab dem nächsten Managerzyklus."""

    group = owner_contract if isinstance(owner_contract, dict) else {}
    previous = getattr(runtime, "group_deficit_binding", None)
    previous = dict(previous) if isinstance(previous, dict) else {}
    candidates = group.get("candidates")
    candidates = candidates if isinstance(candidates, list) else []
    candidate_by_id = {
        int(item.get("id", 0) or 0): item
        for item in candidates
        if isinstance(item, dict) and int(item.get("id", 0) or 0) > 0
    }
    selected_owner_id = int(_cfg_float(group.get("owner_id"), 0.0))
    previous_owner_id = int(_cfg_float(previous.get("owner_id"), 0.0))
    # Solange dieselbe Kandidaten- und Stecksessiongeneration lebt, bleibt der
    # bereits gebundene Owner bestehen. Strom- oder Phasenänderungen dürfen die
    # marginale Verantwortung nicht zwischen zwei Wallboxen springen lassen.
    if (
        previous_owner_id in candidate_by_id
        and str(previous.get("candidate_signature") or "")
        == str(group.get("candidate_signature") or "")
        and str(previous.get("session_signature") or "")
        == str(group.get("session_signature") or "")
    ):
        selected_owner_id = previous_owner_id

    cycle_tokens = {
        str(item.get("_wallbox_cycle_token") or "")
        for item in (chargers or [])
        if isinstance(item, dict)
    }
    cycle_token = next(iter(cycle_tokens)) if len(cycle_tokens) == 1 else ""
    cycle_valid = bool(cycle_token and "" not in cycle_tokens)
    stop_by_id = {
        int(item.get("id", 0) or 0): _cfg_float(
            item.get("_last_stop_toggle_ts"),
            0.0,
        )
        for item in (chargers or [])
        if isinstance(item, dict) and int(item.get("id", 0) or 0) > 0
    }

    def _own_bound_stop_receipt_matches(wb_id, stop_ts):
        """Erkennt nur den eigenen bestätigten Stop dieser Generation."""

        item = next(
            (
                value
                for value in (chargers or [])
                if isinstance(value, dict)
                and int(_cfg_float(value.get("id"), 0.0)) == wb_id
            ),
            {},
        )
        receipt = item.get("_wallbox_group_deficit_stop_receipt_binding")
        receipt = receipt if isinstance(receipt, dict) else {}
        action_binding = item.get("_wallbox_group_deficit_action_binding")
        action_binding = (
            action_binding if isinstance(action_binding, dict) else {}
        )
        candidate = candidate_by_id.get(wb_id)
        candidate = candidate if isinstance(candidate, dict) else {}
        return bool(
            receipt.get("schema")
            == "wallbox_group_deficit_stop_receipt_binding_v1"
            and receipt.get("confirmed") is True
            and wb_id > 0
            and wb_id == previous_owner_id
            and int(_cfg_float(receipt.get("owner_id"), 0.0)) == wb_id
            and int(_cfg_float(receipt.get("wb_id"), 0.0)) == wb_id
            and int(
                _cfg_float(receipt.get("binding_generation"), 0.0)
            )
            == int(_cfg_float(previous.get("binding_generation"), 0.0))
            and str(receipt.get("plug_session_id") or "")
            == str(candidate.get("plug_session_id") or "")
            and str(receipt.get("action_latch_id") or "").startswith(
                "sha256:"
            )
            and str(receipt.get("action_latch_id") or "")
            == str(action_binding.get("action_latch_id") or "")
            and action_binding.get("schema")
            == _GROUP_DEFICIT_ACTION_BINDING_SCHEMA
            and action_binding.get("active") is True
            and str(action_binding.get("action") or "")
            == wallbox_deficit_control.ACTION_STOP
            and int(
                _cfg_float(action_binding.get("binding_generation"), 0.0)
            )
            == int(_cfg_float(previous.get("binding_generation"), 0.0))
            and str(receipt.get("receipt_cycle_token") or "")
            == str(previous.get("cycle_token") or "")
            and _cfg_float(receipt.get("stop_toggle_ts"), 0.0) > 0.0
            and _cfg_float(receipt.get("stop_toggle_ts"), 0.0)
            == _cfg_float(stop_ts, 0.0)
        )

    reset_reason = ""
    if not previous:
        reset_reason = "generation_initialized"
    elif not cycle_valid:
        reset_reason = "cycle_token_missing_or_split"
    elif str(previous.get("candidate_signature") or "") != str(
        group.get("candidate_signature") or ""
    ):
        reset_reason = "candidate_generation_changed"
    elif str(previous.get("session_signature") or "") != str(
        group.get("session_signature") or ""
    ):
        reset_reason = "plug_session_generation_changed"
    elif previous_owner_id not in candidate_by_id:
        reset_reason = "bound_owner_no_longer_candidate"
    else:
        previous_stops = previous.get("stop_by_id")
        previous_stops = previous_stops if isinstance(previous_stops, dict) else {}
        stop_changes = {
            wb_id
            for wb_id in set(previous_stops) | set(stop_by_id)
            if _cfg_float(previous_stops.get(wb_id), 0.0)
            != _cfg_float(stop_by_id.get(wb_id), 0.0)
        }
        unbound_stop_changes = {
            wb_id
            for wb_id in stop_changes
            if not _own_bound_stop_receipt_matches(
                wb_id,
                stop_by_id.get(wb_id),
            )
        }
        if unbound_stop_changes:
            reset_reason = "stop_generation_changed"

    generation = max(
        0,
        int(_cfg_float(previous.get("binding_generation"), 0.0)),
    )
    binding_ready = bool(previous.get("binding_ready", False))
    reset_cycle_token = str(previous.get("reset_cycle_token") or "")
    if reset_reason:
        generation += 1
        binding_ready = False
        reset_cycle_token = cycle_token
        runtime.group_deficit_state = {}
        for item in chargers or []:
            if isinstance(item, dict):
                item.pop("_wallbox_group_deficit_action_binding", None)
                item.pop("_wallbox_group_deficit_downward_authority", None)
                item.pop(
                    "_wallbox_group_deficit_stop_receipt_binding",
                    None,
                )
    elif (
        not binding_ready
        and cycle_valid
        and cycle_token != reset_cycle_token
        and selected_owner_id > 0
    ):
        binding_ready = True

    state = {
        "owner_id": selected_owner_id,
        "candidate_ids": list(group.get("candidate_ids") or ()),
        "candidate_signature": str(group.get("candidate_signature") or ""),
        "session_signature": str(group.get("session_signature") or ""),
        "stop_by_id": stop_by_id,
        "binding_generation": generation,
        "binding_ready": binding_ready,
        "reset_cycle_token": reset_cycle_token,
        "cycle_token": cycle_token,
    }
    runtime.group_deficit_binding = state
    result = {
        "contract": "wallbox_group_deficit_generation_v1",
        "binding_generation": generation,
        "binding_ready": bool(binding_ready and cycle_valid),
        "effective_owner_id": (
            selected_owner_id if binding_ready and cycle_valid else 0
        ),
        "configured_owner_id": selected_owner_id,
        "reset_reason": reset_reason,
        "cycle_token": cycle_token,
        "energy_meter_scope": "pcc_group_once",
    }
    for item in chargers or []:
        if not isinstance(item, dict):
            continue
        item["_wallbox_group_deficit_owner_contract"] = dict(group)
        item["_wallbox_group_deficit_generation_contract"] = dict(result)
    return result


def _openwb_pro_phase_generation_cycle_blocked(c_data):
    """Gilt nur für die exakt gebundene äußere Manager-Zyklusgeneration."""

    data = c_data if isinstance(c_data, dict) else {}
    block = data.get("_openwb_pro_phase_generation_cycle_block")
    cycle_token = str(data.get("_wallbox_cycle_token") or "")
    return bool(
        isinstance(block, dict)
        and block.get("active") is True
        and cycle_token
        and str(block.get("cycle_token") or "") == cycle_token
    )


def _block_openwb_pro_phase_lease_generation(
    c_data,
    status,
    *,
    now_ts,
    clock_sample,
    lease_contract,
    reason,
):
    """Sperrt eine zeitlich ungültige Phasengeneration ohne Hardware-I/O.

    Eine monotonic abgelaufene oder nicht mehr an Boot/Prozess gebundene
    Reservierung darf weder über eine noch günstig wirkende Wallclock noch
    nach einem langsamen Statusabruf an den Treiber gelangen. Vor dem ersten
    Ausgang wird sie terminalisiert; nach einem belegten Ausgang bleibt sie
    zur reinen Readback-Auflösung im Recovery-Hold. In beiden Fällen gilt für
    den kompletten äußeren Managerzyklus ein persistierter Generationsblock.
    """

    data = c_data if isinstance(c_data, dict) else {}
    contract = lease_contract if isinstance(lease_contract, dict) else {}
    now_value = float(now_ts)
    updated_reservation = wallbox_phase_transition.update_reservation(
        data,
        status=status,
        now_ts=now_value,
        connected=openwb_pro_session.status_connected(status),
        clock_sample=clock_sample,
    )
    blocker = str(
        updated_reservation.get("blocker")
        or reason
        or "phase_transition_lease_invalid"
    )
    gate = {
        "contract": "openwb_pro_phase_lease_gate_v1",
        "blocked": True,
        "hardware_write": False,
        "expired": bool(contract.get("expired") is True),
        "timebase_unbound": bool(contract.get("timebase_unbound") is True),
        "lease_source": str(contract.get("source") or ""),
        "stage": str(updated_reservation.get("stage") or ""),
        "blocker": blocker,
        "reason": str(reason or blocker),
        "ts": now_value,
    }
    data["_openwb_pro_phase_lease_gate"] = dict(gate)
    if gate["timebase_unbound"]:
        timebase_gate = dict(gate)
        timebase_gate["contract"] = "openwb_pro_phase_timebase_gate_v1"
        data["_openwb_pro_phase_timebase_gate"] = timebase_gate
    data["_openwb_pro_phase_generation_cycle_block"] = {
        "active": True,
        "cycle_token": str(data.get("_wallbox_cycle_token") or ""),
        "reason": blocker,
        "hardware_write": False,
        "ts": now_value,
    }
    if not _save_wallbox_phase_state([data]):
        _apply_openwb_pro_persistence_recovery_hold(
            data,
            "phase_lease_gate_persist_failed",
        )
    return updated_reservation


def _openwb_pro_phase_sequence_step(
    box,
    command,
    *,
    charger=None,
    c_id=None,
    reason="",
):
    """Führt die sichere openWB-Pro-Phasensequenz aus.

    Laut offizieller connect.php besitzt ``phasetarget`` die Fahrzeugsignalisierung
    und die Phasenwechselpause. Der Manager sequenziert deshalb 0 A -> Warten ->
    phasetarget -> geschützte Wiederanlaufverzögerung -> frischer Phasen-Readback
    -> Strom. Eine getrennte explizite CP-Unterbrechung bleibt der Start-/Wake-up-
    Wiederherstellung vorbehalten und darf nicht auf den geräteeigenen
    Phasenübergang gestapelt werden.
    """

    data = box if isinstance(box, dict) else {}
    cmd = command if isinstance(command, dict) else {}
    active = charger if charger is not None else data.get("charger")
    if not openwb_pro_session.is_openwb_pro_charger(active):
        return None
    target = _valid_phase_count(cmd.get("phases", cmd.get("target_phases", 0)), 0)
    if target not in (1, 3):
        return False

    now_ts = time.time()
    clock_sample = _openwb_pro_control_time_sample(wall_ts=now_ts)
    cfg = data.get("_openwb_pro_config") if isinstance(data.get("_openwb_pro_config"), dict) else {}
    configured_global_max_amp = _amp_limit(
        cfg.get("wbmaxladestrom", cfg.get("wb_max_amp", 16)),
        16,
    )
    configured_max_amp = _charger_max_amp(
        cfg,
        c_id if c_id is not None else data.get("id", 1),
        configured_global_max_amp,
    )
    runtime_max_amp = _cfg_float(data.get("max_amp"), 0.0)
    if 6.0 <= runtime_max_amp <= 32.0:
        configured_max_amp = min(configured_max_amp, int(runtime_max_amp))
    driver_max_amp = _cfg_float(getattr(active, "max_amp", 0.0), 0.0)
    if 6.0 <= driver_max_amp <= 32.0:
        configured_max_amp = min(configured_max_amp, int(driver_max_amp))
    sequence_max_amp = max(6, min(32, int(configured_max_amp or 16)))
    # Die öffentliche Pro-Schnittstelle erlaubt je nach Installation 16 oder
    # 32 A. Ohne explizite Anlagenkonfiguration ist 16 A der konservative
    # Vertrag; die bloße Treiberklasse darf niemals 32 A erfinden.
    # Die Laufzeitbindung aktualisiert echte Treiber bereits vor Status und
    # Policy. Dieser lokale Sequenzvertrag darf deshalb nur eine vorhandene
    # Grenze weiter absenken, aber weder fremde Diagnoseobjekte mutieren noch
    # aus einer fehlenden Treibergrenze eine neue Ausgangsfähigkeit erfinden.
    if hasattr(active, "max_amp"):
        try:
            active.max_amp = min(
                float(getattr(active, "max_amp")),
                float(sequence_max_amp),
            )
        except (TypeError, ValueError):
            pass
    data["_openwb_pro_phase_sequence_max_amp_contract"] = {
        "contract": "openwb_pro_configured_max_current_v1",
        "effective_max_amp": sequence_max_amp,
        "configured_global_max_amp": configured_global_max_amp,
        "runtime_max_amp": runtime_max_amp if runtime_max_amp > 0.0 else None,
        "driver_max_amp": driver_max_amp if driver_max_amp > 0.0 else None,
        "source": "configured_installation_limit",
    }
    hold_s = openwb_pro_session.phase_wait_s(cfg)
    restart_delay_s = openwb_pro_session.phase_restart_delay_s(cfg)
    phase_settle_s = openwb_pro_session.phase_min_settle_s(cfg)
    sequence_reason = str(reason or cmd.get("reason") or "phase_switch")
    sequencer = PhaseSwitchSequencer(data)
    st = _openwb_pro_driver_status(data, active)

    # Recovery besitzt die alte Ausgangsgeneration und muss deshalb vor
    # Supersession und vor dem Storage-Grant-Veto ausgewertet werden. Auch ein
    # erfolgreicher Readback-Abschluss erzeugt in diesem Zyklus keinen neuen
    # Hardwareausgang.
    recovery = data.get("_openwb_pro_phase_recovery_hold")
    if isinstance(recovery, dict) and recovery.get("active"):
        _resolve_phase_output_recovery_once_per_cycle(data, st, cfg)
        return False
    if (
        str(data.get("_wallbox_cycle_token") or "")
        and str(data.get("_phase_output_recovery_cycle_token") or "")
        == str(data.get("_wallbox_cycle_token") or "")
        and data.get("_phase_output_recovery_cycle_resolved") is True
    ):
        # Ein frischer Readback darf die alte Generation schließen, aber im
        # selben Zyklus niemals schon einen neuen Phasenausgang nachschieben.
        return False
    if _openwb_pro_phase_generation_cycle_blocked(data):
        # Eine alte oder abgelaufene Ausgangsgeneration darf auch dann keinen
        # zweiten Versuch im selben äußeren Managerzyklus erhalten, wenn ein
        # Aufrufer zwischenzeitlich eine neue Reservierung projiziert.
        return False

    existing_sequence = data.get("_openwb_pro_phase_sequence")
    existing_target = (
        _valid_phase_count(existing_sequence.get("target"), 0)
        if isinstance(existing_sequence, dict)
        else 0
    )
    passive_block_until = max(
        _cfg_float(data.get("_openwb_pro_phase_wait_until"), 0.0),
        _cfg_float(data.get("_phase_3p_block_until"), 0.0),
        _cfg_float(data.get("_openwb_pro_phase_change_block_until"), 0.0),
    )
    existing_reservation_preview = data.get(
        "_wallbox_phase_transition_reservation"
    )
    existing_reservation_lease_contract = (
        wallbox_phase_transition.reservation_lease_contract(
            existing_reservation_preview,
            now_ts=now_ts,
            clock_sample=clock_sample,
        )
        if isinstance(existing_reservation_preview, dict)
        else {}
    )
    data[
        "_openwb_pro_phase_reservation_lease_contract"
    ] = dict(existing_reservation_lease_contract)
    existing_sequence_expired = bool(
        isinstance(existing_sequence, dict)
        and existing_sequence
        and existing_reservation_lease_contract.get("expired") is True
    )
    if not isinstance(existing_sequence, dict) or not existing_sequence:
        if passive_block_until > now_ts:
            data["_openwb_pro_phase_cooldown_blocked_until"] = passive_block_until
            return False
    elif existing_target != target and not existing_sequence_expired:
        # Dieser Pfad erzeugt keinen Ausgang. Der laufende Zielvertrag muss
        # deshalb ohne neuen Status- oder Capability-Claim Vorrang behalten.
        data["_openwb_pro_phase_target_deferred"] = {
            "active": True,
            "active_target": existing_target,
            "requested_target": target,
            "reason": "active_phase_sequence_owns_transition",
            "ts": now_ts,
        }
        return False

    phase_output_gate, st = _openwb_pro_phase_output_capability_gate(
        data,
        active,
        c_id=c_id,
    )
    if phase_output_gate.get("allowed") is not True:
        return False

    if existing_reservation_lease_contract.get("timebase_unbound") is True:
        _block_openwb_pro_phase_lease_generation(
            data,
            st,
            now_ts=now_ts,
            clock_sample=clock_sample,
            lease_contract=existing_reservation_lease_contract,
            reason="phase_transition_timebase_unbound",
        )
        return False
    if (
        existing_reservation_lease_contract.get("expired") is True
        and not (isinstance(existing_sequence, dict) and existing_sequence)
    ):
        _block_openwb_pro_phase_lease_generation(
            data,
            st,
            now_ts=now_ts,
            clock_sample=clock_sample,
            lease_contract=existing_reservation_lease_contract,
            reason="phase_transition_lease_expired_preoutput",
        )
        return False

    preoutput_supersession = (
        _supersede_openwb_pro_preoutput_phase_reservation(
            data,
            target,
            now_ts=now_ts,
        )
    )
    data["_openwb_pro_phase_preoutput_supersession_contract"] = dict(
        preoutput_supersession
    )
    if (
        preoutput_supersession.get("matched") is True
        and preoutput_supersession.get("superseded") is not True
    ):
        return False

    # ``phases_actual=0`` ist bei einer verbundenen, noch nicht ladenden Pro
    # normal. Wenn connect.php das angeforderte Ziel bereits frisch bestätigt
    # und CP ausdrücklich inaktiv ist, wäre eine neue 0A->phasetarget-Sequenz
    # keine Phasenänderung, sondern ein unnötiger Neustart der kurzen
    # Geräte-Settle-Sequenz. Das vorhandene Ziel wird deshalb rein lesend
    # adoptiert; der 480-s-Puffer bleibt nur für eine weitere Umschaltung.
    if (
        not (isinstance(existing_sequence, dict) and existing_sequence)
        and openwb_pro_session.phase_target_readback_confirmed(st, target)
        and st.get("cp_interrupt_isactive") in (False, 0)
    ):
        noop_candidate = data.get("_openwb_pro_phase_noop_candidate")
        candidate_since = (
            _cfg_float(noop_candidate.get("since_ts"), 0.0)
            if isinstance(noop_candidate, dict)
            and int(noop_candidate.get("target", 0) or 0) == target
            else 0.0
        )
        if candidate_since <= 0.0:
            data["_openwb_pro_phase_noop_candidate"] = {
                "target": target,
                "since_ts": now_ts,
            }
            return False
        if now_ts - candidate_since < openwb_pro_session.phase_target_adoption_settle_s(cfg):
            return False
        data["_openwb_pro_phase_noop_confirmed"] = {
            "target": target,
            "ts": now_ts,
            "source": "fresh_matching_connect_php_target",
        }
        data.pop("_openwb_pro_phase_noop_candidate", None)
        data["_openwb_pro_start_phase_target"] = target
        return True
    data.pop("_openwb_pro_phase_noop_candidate", None)

    # Eine vor einem Managerneustart begonnene Sequenz kann nach Ablauf ihrer
    # Reservierungslease als recovery_hold zurückkehren, obwohl das Gerät das
    # alte Phasenziel inzwischen frisch, verbunden, stromlos und bei inaktivem
    # CP bestätigt. Diesen eindeutig ruhigen Altvertrag terminalisieren wir
    # ohne neue Hardwarekante. Erst der nächste Zyklus darf einen abweichenden
    # neuen Policywunsch als eigene Sequenz beginnen.
    if (
        isinstance(existing_sequence, dict)
        and existing_sequence
        and existing_target in (1, 3)
        and existing_sequence_expired
    ):
        expired_contract = sequencer.propose(
            existing_target,
            now_ts=now_ts,
            current_set_amp=data.get("current_set_amp", 0),
            status=st,
            config=cfg,
            reason=str(existing_sequence.get("reason") or sequence_reason),
            hold_s=hold_s,
            restart_delay_s=restart_delay_s,
            charger_max_amp=sequence_max_amp,
            clock_sample=clock_sample,
        )
        expired_action = str(expired_contract.get("action") or "")
        if expired_action in ("adopt_phase_settle", "wait_restart"):
            # Auch ein abgelaufener Reservierungsvertrag darf den kurzen
            # Geräte-Settle nicht in jedem Zyklus neu beginnen. Erst die
            # bestätigte Übernahme des monotonen Zeitvertrags wird
            # persistiert; es erfolgt hier keinerlei Hardwareausgabe.
            sequencer.acknowledge(
                expired_contract,
                True,
                config=cfg,
            charger_max_amp=sequence_max_amp,
            )
            if not _save_wallbox_phase_state([data]):
                _phase_output_recovery_hold(
                    data,
                    "expired_phase_settle_persist_failed",
                )
            return False
        if expired_action == "ready":
            expired_stage_timer = control_time.evaluate_guard(
                existing_sequence.get(
                    openwb_pro_session.PHASE_STAGE_TIMEBASE_KEY
                ),
                clock_sample,
                minimum_s=0.0,
            )
            expired_reported_amp = _fresh_wallbox_reported_current_amp(st)
            expired_idle_target_confirmed = bool(
                expired_stage_timer.get("schema_version")
                == control_time.GUARD_SCHEMA
                and expired_stage_timer.get("active") is False
                and expired_stage_timer.get("fail_closed") is False
                and expired_reported_amp is not None
                and expired_reported_amp <= 0.5
                and not _wb_status_real_charging(st)
                and _wb_status_real_power(st) <= 100.0
                and openwb_pro_session.phase_target_readback_confirmed(
                    st,
                    existing_target,
                )
                and st.get("cp_interrupt_isactive") in (False, 0)
            )
            if not expired_idle_target_confirmed:
                return False
            sequencer.acknowledge(
                expired_contract,
                True,
                config=cfg,
            charger_max_amp=sequence_max_amp,
            )
            for key in (
                "_wallbox_phase_transition_reservation",
                "_phase_transition_grant",
                "_openwb_pro_phase_output_intent",
                "_openwb_pro_phase_output_ack",
                "_openwb_pro_phase_recovery_hold",
            ):
                data.pop(key, None)
            openwb_pro_session.clear_phase_wait(data)
            data["_openwb_pro_phase_restart_authorized"] = {
                "active": True,
                "target": existing_target,
                "phase_sent_ts": float(
                    existing_sequence.get("phase_sent_ts", 0.0) or 0.0
                ),
                "authorized_ts": now_ts,
                "source": "expired_sequence_fresh_idle_target_confirmed",
            }
            if target != existing_target:
                data["_openwb_pro_phase_target_deferred"] = {
                    "active": True,
                    "active_target": existing_target,
                    "requested_target": target,
                    "reason": "expired_sequence_terminalized_before_new_target",
                    "ts": now_ts,
                }
            else:
                data.pop("_openwb_pro_phase_target_deferred", None)
            terminal_reason = "expired_phase_sequence_restart_deferred"
            data["_openwb_pro_phase_expired_generation_gate"] = {
                "contract": "openwb_pro_phase_expired_generation_gate_v1",
                "blocked": True,
                "hardware_write": False,
                "expired_action": expired_action,
                "active_target": existing_target,
                "requested_target": target,
                "reason": terminal_reason,
                "ts": now_ts,
            }
            data["_openwb_pro_phase_generation_cycle_block"] = {
                "active": True,
                "cycle_token": str(data.get("_wallbox_cycle_token") or ""),
                "reason": terminal_reason,
                "hardware_write": False,
                "ts": now_ts,
            }
            if not _save_wallbox_phase_state([data]):
                _phase_output_recovery_hold(
                    data,
                    "expired_phase_sequence_cleanup_persist_failed",
                )
                return False
            # Der frische Readback darf die Altgeneration bereinigen und den
            # Wiederanlauf für den Folgezyklus vormerken, aber niemals im
            # selben äußeren Zyklus noch einen neuen Stromausgang öffnen.
            return False

        # Jeder andere Schritt würde die abgelaufene Ausgangsgeneration mit
        # ihrem alten Grant erneut bis an den Draht tragen. Diese Generation
        # wechselt deshalb ohne Hardware-I/O in Recovery; eine frische
        # Readback-Auflösung darf erst im Folgezyklus eine neue Reservierung
        # und einen neuen Grant ermöglichen.
        expired_reason = "expired_phase_generation_requires_recovery"
        _phase_output_recovery_hold(data, expired_reason)
        data["_openwb_pro_phase_expired_generation_gate"] = {
            "contract": "openwb_pro_phase_expired_generation_gate_v1",
            "blocked": True,
            "hardware_write": False,
            "expired_action": expired_action,
            "active_target": existing_target,
            "requested_target": target,
            "reason": expired_reason,
            "ts": now_ts,
        }
        data["_openwb_pro_phase_generation_cycle_block"] = {
            "active": True,
            "cycle_token": str(data.get("_wallbox_cycle_token") or ""),
            "reason": expired_reason,
            "hardware_write": False,
            "ts": now_ts,
        }
        if not _save_wallbox_phase_state([data]):
            _apply_openwb_pro_persistence_recovery_hold(
                data,
                "expired_phase_generation_hold_persist_failed",
            )
        return False

    existing_reservation = data.get("_wallbox_phase_transition_reservation")
    reservation_created = False
    if not isinstance(existing_reservation, dict) or not existing_reservation.get("active"):
        existing_reservation = begin_phase_transition_reservation(
            data,
            target,
            status=_openwb_pro_driver_status(data, active),
            now_ts=now_ts,
            zero_settle_s=openwb_pro_session.phase_zero_settle_s(cfg),
            restart_delay_s=restart_delay_s + phase_settle_s,
            charger_max_amp=sequence_max_amp,
            source="openwb_pro_phase_sequence",
            reason=sequence_reason,
            wb_id=c_id if c_id is not None else data.get("id", 0),
            restart_amp=max(
                6.0,
                _cfg_float(data.get("current_set_amp"), 0.0),
                _cfg_float(data.get("_last_openwb_hold_amp"), 0.0),
            ),
            current_step_amp=_current_step_amp_for_charger(active, default=0.1),
            clock_sample=clock_sample,
        )
        reservation_created = bool(existing_reservation)
    if reservation_created:
        stored_reservation = data.get(
            "_wallbox_phase_transition_reservation"
        )
        if isinstance(stored_reservation, dict):
            preoutput_evidence = _phase_transition_preoutput_evidence(
                data,
                stored_reservation,
            )
            if preoutput_evidence.get("eligible") is True:
                stored_reservation = dict(stored_reservation)
                stored_reservation[
                    "preoutput_supersession_evidence"
                ] = dict(preoutput_evidence)
                data[
                    "_wallbox_phase_transition_reservation"
                ] = stored_reservation
                existing_reservation = stored_reservation
        if not _save_wallbox_phase_state([data]):
            _phase_output_recovery_hold(data, "phase_reservation_persist_failed")
            return False
    grant = data.get("_phase_transition_grant")
    if isinstance(grant, dict):
        existing_reservation = wallbox_phase_transition.apply_grant(
            data,
            grant,
            now_ts=now_ts,
        )
    if not wallbox_phase_transition.grant_is_sufficient(existing_reservation):
        if wallbox_phase_transition.grant_recovery_blocked(
            existing_reservation
        ):
            data["_openwb_pro_phase_generation_cycle_block"] = {
                "active": True,
                "cycle_token": str(data.get("_wallbox_cycle_token") or ""),
                "reason": str(
                    existing_reservation.get("blocker")
                    or "phase_generation_recovery_hold"
                ),
                "hardware_write": False,
                "ts": now_ts,
            }
        else:
            wallbox_phase_transition.set_stage(
                data,
                "await_budget",
                now_ts=now_ts,
            )
        return False

    contract = sequencer.propose(
        target,
        now_ts=now_ts,
        current_set_amp=data.get("current_set_amp", 0),
        status=st,
        config=cfg,
        reason=sequence_reason,
        hold_s=hold_s,
        restart_delay_s=restart_delay_s,
            charger_max_amp=sequence_max_amp,
        clock_sample=clock_sample,
    )
    action = str(contract.get("action") or "invalid")
    if action == "abort_disconnected_before_phase_output":
        _abort_openwb_pro_phase_transition_before_output(
            data,
            target=target,
            reason=str(
                contract.get("reason")
                or "vehicle_disconnected_before_phase_output"
            ),
            now_ts=now_ts,
        )
        return False
    if action == "wait_connection_readback":
        return False
    if action in ("send_zero", "send_phase"):
        edge_gate, edge_status = _openwb_pro_phase_output_capability_gate(
            data,
            active,
            c_id=c_id,
            action=action,
        )
        # Die Lease-Probe muss nach dem potentiell langsamen Hersteller-GET
        # liegen. Eine davor genommene Monotonicprobe würde eine während des
        # GET abgelaufene Reservierung bis zum Wire-Ausgang durchreichen.
        output_now = time.time()
        output_clock_sample = _openwb_pro_control_time_sample(
            wall_ts=output_now,
        )
        edge_reservation = data.get(
            "_wallbox_phase_transition_reservation"
        )
        edge_lease_contract = (
            wallbox_phase_transition.reservation_lease_contract(
                edge_reservation,
                now_ts=output_now,
                clock_sample=output_clock_sample,
            )
            if isinstance(edge_reservation, dict)
            else {}
        )
        data[
            "_openwb_pro_phase_wire_edge_lease_contract"
        ] = dict(edge_lease_contract)
        if (
            edge_lease_contract.get("expired") is True
            or edge_lease_contract.get("timebase_unbound") is True
        ):
            _block_openwb_pro_phase_lease_generation(
                data,
                edge_status,
                now_ts=output_now,
                clock_sample=output_clock_sample,
                lease_contract=edge_lease_contract,
                reason=(
                    "phase_transition_timebase_unbound_at_wire_edge"
                    if edge_lease_contract.get("timebase_unbound") is True
                    else "phase_transition_lease_expired_at_wire_edge"
                ),
            )
            return False
        edge_connected = bool(edge_gate.get("allowed") is True)
        edge_contract = sequencer.propose(
            target,
            now_ts=output_now,
            current_set_amp=data.get("current_set_amp", 0),
            status=edge_status,
            config=cfg,
            reason=sequence_reason,
            hold_s=hold_s,
            restart_delay_s=restart_delay_s,
            charger_max_amp=sequence_max_amp,
            clock_sample=output_clock_sample,
        )
        edge_action = str(edge_contract.get("action") or "invalid")
        data["_openwb_pro_phase_output_recheck"] = {
            "contract": "openwb_pro_phase_output_recheck_v1",
            "requested_action": action,
            "edge_action": edge_action,
            "connected": bool(edge_connected),
            "capability_allowed": bool(edge_gate.get("allowed") is True),
            "capability_blocker": str(edge_gate.get("blocker") or ""),
            "ts": output_now,
        }
        if not edge_connected or edge_action != action:
            if edge_action == "abort_disconnected_before_phase_output":
                _abort_openwb_pro_phase_transition_before_output(
                    data,
                    target=target,
                    reason=str(
                        edge_contract.get("reason")
                        or "vehicle_disconnected_before_phase_output"
                    ),
                    now_ts=output_now,
                )
            return False
        contract = edge_contract
        now_ts = output_now
    if action == "send_zero":
        intent = _persist_phase_output_intent(
            data, action, contract, now_ts
        )
        if not intent:
            return False
        ok_zero = _execute_wallbox_driver_command(
            data,
            contract.get("command") or {},
            c_id=c_id,
            reason="openwb_pro_phase_zero",
        )
        if ok_zero:
            sequencer.acknowledge(
                contract,
                True,
                config=cfg,
            charger_max_amp=sequence_max_amp,
            )
            if not _persist_phase_output_ack(data, intent, True):
                return False
            logger.info(
                "WB%s openWB Pro Phasenwechsel vorbereitet: 0A gesetzt, %ds Beruhigungszeit vor phasetarget=%dp"
                % (
                    c_id if c_id is not None else "?",
                    int(round(float(contract.get("zero_settle_s", 0.0) or 0.0))),
                    target,
                )
            )
        else:
            _persist_phase_output_ack(data, intent, False, "phase_zero_unconfirmed")
        return False
    if action in ("wait_zero", "wait_zero_readback"):
        sequencer.acknowledge(contract)
        return False
    if action == "send_phase":
        wallbox_phase_transition.set_stage(data, "set_phase", now_ts=now_ts)
        intent = _persist_phase_output_intent(
            data, action, contract, now_ts
        )
        if not intent:
            return False
        previous_phase_receipt = data.get("_last_executed_command")
        ok_phase = _execute_wallbox_driver_command(
            data,
            contract.get("command") or {},
            c_id=c_id,
            reason="openwb_pro_phase_target",
        )
        if not ok_phase:
            _persist_phase_output_ack(data, intent, False, "phase_target_unconfirmed")
            return False
        contract, intent = _bind_openwb_pro_phase_post_receipt(
            data,
            intent,
            contract,
            previous_phase_receipt,
            target=target,
            now_ts=time.time(),
            config=cfg,
        )
        if not isinstance(contract, dict) or not isinstance(intent, dict):
            return False
        sequencer.acknowledge(
            contract,
            True,
            config=cfg,
            charger_max_amp=sequence_max_amp,
        )
        acknowledged_sequence = data.get("_openwb_pro_phase_sequence")
        acknowledged_sequence = (
            acknowledged_sequence
            if isinstance(acknowledged_sequence, dict)
            else {}
        )
        wire_receipt_ts = _cfg_float(
            (intent.get("sequence_patch") or {}).get("wire_receipt_ts"),
            0.0,
        )
        if not (
            str(acknowledged_sequence.get("stage") or "")
            == "restart_delay"
            and _cfg_float(
                acknowledged_sequence.get("phase_sent_ts"),
                0.0,
            )
            == wire_receipt_ts
            and _cfg_float(
                acknowledged_sequence.get("wire_receipt_ts"),
                0.0,
            )
            == wire_receipt_ts
            and wire_receipt_ts > 0.0
        ):
            _phase_output_recovery_hold(
                data,
                "phase_target_sequence_ack_failed",
                intent,
            )
            _save_wallbox_phase_state([data])
            return False
        if not _persist_phase_output_ack(data, intent, True):
            return False
        logger.info(
            "WB%s openWB Pro Phasenwechsel: phasetarget=%dp nach 0A-Beruhigung gesetzt"
            % (c_id if c_id is not None else "?", target)
        )
        return False
    if action in ("wait_phase_readback",):
        sequencer.acknowledge(contract)
        return False
    if action == "adopt_phase_settle":
        sequencer.acknowledge(
            contract,
            True,
            config=cfg,
            charger_max_amp=sequence_max_amp,
        )
        if not _save_wallbox_phase_state([data]):
            _phase_output_recovery_hold(data, "legacy_phase_settle_persist_failed")
        return False
    if action in (
        "wait_restart",
        "wait_fresh_readback",
        "wait_cp_inactive",
        "wait_target_phase",
    ):
        sequencer.acknowledge(contract)
        return False
    if action == "ready":
        sequencer.acknowledge(contract)
        data["_openwb_pro_phase_restart_authorized"] = {
            "active": True,
            "target": target,
            "phase_sent_ts": float(
                (contract.get("sequence") or {}).get("phase_sent_ts", 0.0) or 0.0
            ),
            "authorized_ts": now_ts,
            "source": "phase_target_settle_readback_confirmed",
        }
        if not _save_wallbox_phase_state([data]):
            _phase_output_recovery_hold(data, "phase_ready_persist_failed")
            return False
        return True
    return False


def _openwb_pro_start_wakeup_ready(box, command, *, charger=None, c_id=None, reason=""):
    data = box if isinstance(box, dict) else {}
    cmd = command if isinstance(command, dict) else {}
    active = charger if charger is not None else data.get("charger")
    if not openwb_pro_session.is_openwb_pro_charger(active):
        return True
    if _openwb_pro_phase_generation_cycle_blocked(data):
        return False
    method = str(cmd.get("method") or cmd.get("kind") or "").strip()
    now_ts = time.time()
    st, cfg = _openwb_pro_status_with_vehicle_cp_capability(
        data,
        _openwb_pro_driver_status(data, active),
        charger_id=(c_id if c_id is not None else data.get("id", 1)),
    )
    phase_restart = data.get("_openwb_pro_phase_restart_authorized")
    if isinstance(phase_restart, dict) and phase_restart.get("active"):
        target = _valid_phase_count(phase_restart.get("target"), 0)
        return bool(
            openwb_pro_session.phase_target_readback_confirmed(st, target)
            and st.get("cp_interrupt_isactive") in (False, 0)
        )
    cp_payload = _openwb_pro_cp_payload_from_config(cfg, st)
    contract = openwb_pro_session.start_wakeup_step_contract(
        method,
        cmd.get("amp", 0.0),
        data,
        st,
        cfg,
        now_ts=now_ts,
        cp_payload=cp_payload,
    )
    data["_openwb_pro_start_wakeup_contract"] = contract
    state_patch = contract.get("state_patch") if isinstance(contract.get("state_patch"), dict) else {}
    if state_patch:
        data.update(state_patch)
    command_patch = contract.get("command_patch") if isinstance(contract.get("command_patch"), dict) else {}
    if command_patch:
        cmd.update(command_patch)
    if str(contract.get("action") or "") != "send_cp_interrupt":
        return bool(contract.get("allow", True))

    # Der Receipt darf erst verbraucht werden, wenn der logische Ausgang dieses
    # Managerzyklus noch frei ist. Andernfalls würde ein nur intern abgewiesener
    # CP-Versuch das begrenzte Wake-up-Budget der Stecksession aufbrauchen.
    output_ledger = data.get(wallbox_output_ledger.LEDGER_KEY)
    output_blocker = ""
    if (
        not isinstance(output_ledger, dict)
        or not str(output_ledger.get("cycle_token") or "").strip()
        or output_ledger.get("token_valid") is not True
    ):
        output_blocker = "missing_cycle_token"
    elif bool(output_ledger.get("normal_locked")) or bool(
        output_ledger.get("emergency_claimed")
    ):
        output_blocker = "normal_blocked_after_emergency"
    elif bool(output_ledger.get("normal_claimed")):
        output_blocker = "normal_already_claimed"
    if output_blocker:
        data["_openwb_pro_start_wakeup_output_block"] = {
            "contract": "openwb_pro_start_wakeup_output_block_v1",
            "action": "deferred_before_receipt",
            "reason": output_blocker,
            "ts": now_ts,
        }
        return False
    data.pop("_openwb_pro_start_wakeup_output_block", None)

    # Den Versuch *vor* dem CP-Ausgang persistent verbrauchen. Damit kann ein
    # Managerabsturz direkt nach dem Hardwareaufruf den Zähler nicht wieder auf
    # den alten Stand zurücksetzen und dieselbe Stecksession neu bewaffnen.
    success_patch = contract.get("success_state_patch")
    previous_values = {}
    if isinstance(success_patch, dict):
        for key, value in success_patch.items():
            previous_values[key] = (key in data, deepcopy(data.get(key)))
            data[key] = value
    if not _save_wallbox_phase_state([data]):
        for key, (present, value) in previous_values.items():
            if present:
                data[key] = value
            else:
                data.pop(key, None)
        data["_openwb_pro_start_cp_persistence_blocked"] = True
        logger.error(
            "WB%s openWB Pro Wake-up-Receipt nicht vorab persistierbar; "
            "CP-Impulse dieser Stecksession werden fail-closed gesperrt.",
            c_id if c_id is not None else "?",
        )
        return True

    ok_cp = _execute_wallbox_driver_command(
        data,
        contract.get("command") or {},
        c_id=c_id,
        reason="openwb_pro_start_wakeup",
    )
    if ok_cp:
        cp_number = int(contract.get("sent_count", 0) or 0) + 1
        cp_trigger = (
            "direkt nach erster Stromfreigabe"
            if cp_number == 1
            else "nach weiter ausbleibender Ladeannahme"
        )
        logger.info(
            "WB%s openWB Pro Wake-up %d/%d: CP-Interrupt %s gesendet, "
            "%ds Einschaltverzögerung"
            % (
                c_id if c_id is not None else "?",
                cp_number,
                int(contract.get("max_retries", 3) or 3),
                cp_trigger,
                int(round(contract.get("delay_s", 0.0) or 0.0)),
            )
        )
        return False
    output_gate = data.get("_openwb_pro_connected_output_gate")
    connection_blocked = bool(
        isinstance(output_gate, dict)
        and str(output_gate.get("action") or "") == "start_cp_interrupt"
        and output_gate.get("allowed") is False
    )
    if connection_blocked:
        consumed_values = {
            key: (key in data, deepcopy(data.get(key)))
            for key in previous_values
        }
        for key, (present, value) in previous_values.items():
            if present:
                data[key] = value
            else:
                data.pop(key, None)
        if _save_wallbox_phase_state([data]):
            data.pop("_openwb_pro_start_cp_persistence_blocked", None)
        else:
            for key, (present, value) in consumed_values.items():
                if present:
                    data[key] = value
                else:
                    data.pop(key, None)
            data["_openwb_pro_start_cp_persistence_blocked"] = True
        data["_openwb_pro_start_wakeup_output_block"] = {
            "contract": "openwb_pro_start_wakeup_output_block_v1",
            "action": "blocked_disconnected_before_cp_output",
            "reason": "vehicle_disconnected_before_cp_output",
            "ts": time.time(),
        }
        return False
    data["_openwb_pro_start_wakeup_output_block"] = {
        "contract": "openwb_pro_start_wakeup_output_block_v1",
        "action": "dispatch_unconfirmed_attempt_consumed",
        "reason": "driver_output_unconfirmed_after_receipt",
        "ts": time.time(),
    }
    logger.warning(
        "WB%s openWB Pro Wake-up-Ausgang blieb nach vorab persistiertem "
        "Versuch unbestätigt; der Versuch bleibt fail-closed verbraucht.",
        c_id if c_id is not None else "?",
    )
    return True


def _multi_allocation_cap_value(c_data, requested_amp):
    """Wende den aktuellen ladepunktspezifischen Allokationsdeckel an.

    Der Deckel ist innerhalb eines Managerzyklus unveränderlich. Damit können
    Start-Holds, Rampen, Keepalives und Retry-Pfade einen bereits phasen- oder
    leistungsbegrenzt zugeteilten Strom nicht später wieder anheben.
    """

    box = c_data if isinstance(c_data, dict) else {}
    contract = box.get("_multi_allocation_output_cap")
    requested = max(0.0, _cfg_float(requested_amp, 0.0))
    if not isinstance(contract, dict) or not contract.get("active", False):
        return requested
    cap_amp = max(0.0, _cfg_float(contract.get("cap_amp"), 0.0))
    if cap_amp < 6.0:
        return 0.0
    return min(requested, cap_amp)


def _multi_allocation_cycle_cap_amp(
    c_data,
    cycle_cap_amp,
    charger_max_amp,
    *,
    min_amp=6,
):
    """Verwende bei Multi-WB den Ladepunkt- statt des Gruppen-Amperewerts."""

    box = c_data if isinstance(c_data, dict) else {}
    contract = box.get("_multi_allocation_output_cap")
    maximum = max(0, int(_cfg_float(charger_max_amp, 0.0)))
    if not isinstance(contract, dict) or not contract.get("active", False):
        return min(maximum, max(0, int(_cfg_float(cycle_cap_amp, 0.0))))
    slot_amp = max(0, int(_cfg_float(contract.get("cap_amp"), 0.0)))
    if slot_amp < max(1, int(_cfg_float(min_amp, 6.0))):
        return 0
    return min(maximum, slot_amp)


_EFFECTIVE_CURRENT_METHODS = frozenset({
    "set_amp_and_state",
    "set_current",
    "set_direct_current",
    "set_amp_sonnenmodus",
    "set_amp_autonomous_solar",
})

_STORAGE_BUDGET_CHARGE_SIDE_EFFECT_METHODS = frozenset({
    "take_control",
    "set_amp_and_state",
    "set_current",
    "set_direct_current",
    "set_amp_sonnenmodus",
    "set_amp_autonomous_solar",
    "set_pv_mode",
    "set_phases",
    "trigger_cp_interrupt",
    "cp_interrupt",
    "release_to_e3dc",
    "release_to_default",
})

_GROUP_DEFICIT_ACTION_BINDING_SCHEMA = (
    "wallbox_group_deficit_action_binding_v1"
)
_GROUP_DEFICIT_DOWNWARD_AUTHORITY_SCHEMA = (
    "wallbox_group_deficit_downward_authority_v1"
)
_GROUP_DEFICIT_STOP_COMPLETION_SCHEMA = (
    "wallbox_group_deficit_stop_completion_v1"
)
_SOURCE_SESSION_CONTEXT_SCHEMA = "wallbox_source_session_context_v1"


def _wallbox_group_deficit_current_session_id(c_data):
    data = c_data if isinstance(c_data, dict) else {}
    return str(
        data.get(wallbox_start_hold.SESSION_KEY)
        or data.get("_openwb_pro_plug_session_id")
        or data.get("_wallbox_plug_episode_id")
        or ""
    ).strip()


def _wallbox_group_deficit_complete_confirmed_stop(
    runtime,
    chargers,
    statuses,
    *,
    now_ts,
):
    """Terminalisiert genau einen physisch bestätigten Gruppen-Stop.

    Der Gruppenregler hält ``STOP_PENDING`` absichtlich bis zu einem echten
    Hardware-Readback. Ohne diese Abschlusskante blieb jedoch der gebundene
    Stop-Latch auch nach einem erfolgreich beendeten Ladevorgang bestehen. Ein
    späterer, regulärer Start derselben Stecksession konnte dadurch den alten
    Stop erneut auslösen. Terminalisiert wird ausschließlich der eigene
    bestätigte Stop-Receipt zusammen mit einem neueren, frischen
    ``not_charging``-Sample. Ein späterer Start-Receipt ist ohne eigenen neuen
    Policyvertrag keine Abschlussautorität. Es gibt weder eine Zeitfreigabe
    noch einen Hardwareausgang.
    """

    result = {
        "schema": _GROUP_DEFICIT_STOP_COMPLETION_SCHEMA,
        "evaluated": False,
        "completed": False,
        "owner_id": 0,
        "plug_session_id": "",
        "reason": "group_stop_not_pending",
        "output_authority": False,
    }
    state = getattr(runtime, "group_deficit_state", None)
    state = state if isinstance(state, dict) else {}
    cascade = state.get("cascade")
    cascade = cascade if isinstance(cascade, dict) else {}
    if str(cascade.get("stage") or "") != (
        wallbox_deficit_control.STAGE_STOP_PENDING
    ):
        return result

    result["evaluated"] = True
    owner_id = int(_cfg_float(state.get("marginal_wb_id"), 0.0))
    result["owner_id"] = owner_id
    boxes = [item for item in (chargers or ()) if isinstance(item, dict)]
    owner_boxes = [
        item
        for item in boxes
        if int(_cfg_float(item.get("id"), 0.0)) == owner_id
    ]
    owner_statuses = [
        item.get("status")
        for item in (statuses or ())
        if isinstance(item, dict)
        and int(_cfg_float(item.get("id"), 0.0)) == owner_id
        and isinstance(item.get("status"), dict)
    ]
    if owner_id <= 0 or not owner_boxes:
        result["reason"] = "pending_owner_missing"
        return result
    if len(owner_boxes) != 1:
        result["reason"] = "pending_owner_not_unique"
        return result
    owner_box = owner_boxes[0]
    if not owner_statuses:
        result["reason"] = "pending_owner_status_missing"
        owner_box["_wallbox_group_deficit_stop_completion"] = dict(result)
        return result
    if len(owner_statuses) != 1:
        result["reason"] = "pending_owner_status_not_unique"
        owner_box["_wallbox_group_deficit_stop_completion"] = dict(result)
        return result
    owner_status = owner_statuses[0]

    native_driver = e3dc_session.is_e3dc_native_charger(
        owner_box.get("charger")
    )
    session_id = _wallbox_group_deficit_current_session_id(owner_box)
    result["plug_session_id"] = session_id
    action_binding = owner_box.get("_wallbox_group_deficit_action_binding")
    action_binding = (
        action_binding if isinstance(action_binding, dict) else {}
    )
    stop_receipt = owner_box.get(
        "_wallbox_group_deficit_stop_receipt_binding"
    )
    stop_receipt = stop_receipt if isinstance(stop_receipt, dict) else {}
    generation = getattr(runtime, "group_deficit_binding", None)
    generation = generation if isinstance(generation, dict) else {}
    binding_generation = int(
        _cfg_float(action_binding.get("binding_generation"), 0.0)
    )
    runtime_owner_id = int(
        _cfg_float(generation.get("owner_id"), 0.0)
    )
    cascade_generation = int(
        _cfg_float(cascade.get("generation"), 0.0)
    )
    action_cascade_generation = int(
        _cfg_float(action_binding.get("cascade_generation"), 0.0)
    )
    state_snapshot_id = str(state.get("snapshot_id") or "")
    action_origin_snapshot_id = str(
        action_binding.get("origin_snapshot_id") or ""
    )
    attempt_origin_snapshot_id = str(
        action_binding.get("attempt_origin_snapshot_id") or ""
    )
    attempt_cycle_token = str(
        action_binding.get("attempt_cycle_token") or ""
    )
    attempt_ts = _cfg_float(action_binding.get("attempt_ts"), 0.0)
    attempt_status_ts = _cfg_float(
        action_binding.get("attempt_status_ts"),
        0.0,
    )
    stop_toggle_ts = _cfg_float(stop_receipt.get("stop_toggle_ts"), 0.0)
    stop_wire_receipt_ts = _cfg_float(
        stop_receipt.get("stop_wire_receipt_ts"),
        0.0,
    )
    action_latch_id = str(action_binding.get("action_latch_id") or "")
    expected_action_latch_id = _wallbox_group_deficit_action_latch_id({
        "action": wallbox_deficit_control.ACTION_STOP,
        "wb_id": owner_id,
        "plug_session_id": session_id,
        "binding_generation": binding_generation,
        "cascade_generation": action_cascade_generation,
        "origin_snapshot_id": action_origin_snapshot_id,
        "target_amp": action_binding.get("target_amp"),
        "target_phases": action_binding.get("target_phases"),
    })
    binding_valid = bool(
        action_binding.get("schema") == _GROUP_DEFICIT_ACTION_BINDING_SCHEMA
        and action_binding.get("active") is True
        and str(action_binding.get("action") or "")
        == wallbox_deficit_control.ACTION_STOP
        and owner_id > 0
        and int(_cfg_float(action_binding.get("wb_id"), 0.0)) == owner_id
        and session_id
        and str(action_binding.get("plug_session_id") or "") == session_id
        and binding_generation > 0
        and binding_generation
        == int(_cfg_float(generation.get("binding_generation"), 0.0))
        and runtime_owner_id == owner_id
        and generation.get("binding_ready") is True
        and cascade_generation > 0
        and action_cascade_generation == cascade_generation
        # ``state_snapshot_id`` schreitet während STOP_PENDING weiter. Der
        # Action-Origin bleibt absichtlich unveränderlich und wird daher über
        # sein Hashmaterial sowie den wirklichen Versuch gebunden, nicht an
        # den aktuellen Pending-Snapshot zurückgebogen.
        and state_snapshot_id
        and action_origin_snapshot_id
        and attempt_origin_snapshot_id == action_origin_snapshot_id
        and attempt_cycle_token
        and action_latch_id == expected_action_latch_id
    )
    receipt_valid = bool(
        stop_receipt.get("schema")
        == "wallbox_group_deficit_stop_receipt_binding_v1"
        and stop_receipt.get("confirmed") is True
        and int(_cfg_float(stop_receipt.get("owner_id"), 0.0)) == owner_id
        and int(_cfg_float(stop_receipt.get("wb_id"), 0.0)) == owner_id
        and str(stop_receipt.get("plug_session_id") or "") == session_id
        and int(_cfg_float(stop_receipt.get("binding_generation"), 0.0))
        == binding_generation
        and str(stop_receipt.get("action_latch_id") or "")
        == action_latch_id
        and str(stop_receipt.get("origin_snapshot_id") or "")
        == attempt_origin_snapshot_id
        and str(stop_receipt.get("receipt_cycle_token") or "")
        == attempt_cycle_token
        and attempt_ts > 0.0
        # Der Manager-Zeitanker wird im selben Aufruf wie der Versuch
        # geschrieben und darf deshalb exakt gleich sein. Der tatsächliche
        # native Wire-Receipt muss dagegen strikt danach eintreffen.
        and stop_toggle_ts >= attempt_ts
        and stop_toggle_ts > attempt_status_ts
        and (
            not native_driver
            or (
                stop_receipt.get("stop_wire_receipt_contract")
                == "e3dc_wbchar6_wire_receipt_v1"
                and int(
                    _cfg_float(
                        stop_receipt.get("stop_wire_receipt_seq"),
                        0.0,
                    )
                )
                > 0
                and stop_wire_receipt_ts
                > max(attempt_ts, attempt_status_ts)
            )
        )
    )
    if not binding_valid or not receipt_valid:
        result["reason"] = (
            "pending_stop_binding_invalid"
            if not binding_valid
            else "pending_stop_receipt_invalid"
        )
        owner_box["_wallbox_group_deficit_stop_completion"] = dict(result)
        return result
    if not _wallbox_demand_status_fresh(owner_status, now_ts=now_ts):
        result["reason"] = "pending_stop_status_not_fresh"
        owner_box["_wallbox_group_deficit_stop_completion"] = dict(result)
        return result

    observation = wallbox_decision.charge_observation_contract(
        owner_status,
        now_ts=now_ts,
    )
    sample = (
        {
            "seq": max(
                0,
                int(
                    _cfg_float(
                        owner_status.get("native_status_sample_seq"),
                        0.0,
                    )
                ),
            ),
            "ts": max(
                0.0,
                _cfg_float(
                    owner_status.get("native_status_sample_ts"),
                    0.0,
                ),
            ),
        }
        if native_driver
        else _wallbox_group_deficit_status_sample_identity(owner_status)
    )
    sample_ts = _cfg_float(sample.get("ts"), 0.0)
    sample_seq = int(_cfg_float(sample.get("seq"), 0.0))
    pre_stop_sample_ts = _cfg_float(
        action_binding.get("attempt_status_ts"),
        0.0,
    )
    pre_stop_sample_seq = int(
        _cfg_float(action_binding.get("attempt_status_seq"), 0.0)
    )
    newer_sample = bool(
        stop_toggle_ts > 0.0
        and sample_ts
        > max(stop_toggle_ts, stop_wire_receipt_ts, pre_stop_sample_ts)
    )
    if native_driver:
        newer_sample = bool(
            newer_sample
            and sample_seq > 0
            and sample_seq > pre_stop_sample_seq
        )
    physically_stopped = bool(
        observation.get("truth") == "not_charging"
        and observation.get("hardware_charging") is False
        and _cfg_float(observation.get("raw_power_w"), 0.0) <= 500.0
    )
    result.update({
        "status_sample_seq": sample_seq,
        "status_sample_ts": sample_ts,
        "stop_toggle_ts": stop_toggle_ts,
        "stop_wire_receipt_ts": (
            stop_wire_receipt_ts if stop_wire_receipt_ts > 0.0 else None
        ),
        "pre_stop_status_sample_seq": pre_stop_sample_seq,
        "pre_stop_status_sample_ts": pre_stop_sample_ts,
        "fresh_post_stop_sample": newer_sample,
        "charge_truth": str(observation.get("truth") or "unknown"),
        "raw_power_w": round(
            max(0.0, _cfg_float(observation.get("raw_power_w"), 0.0)),
            3,
        ),
    })
    if not newer_sample:
        result["reason"] = "fresh_post_stop_sample_missing"
        owner_box["_wallbox_group_deficit_stop_completion"] = dict(result)
        return result
    if not physically_stopped:
        result["reason"] = "physical_stop_not_confirmed"
        owner_box["_wallbox_group_deficit_stop_completion"] = dict(result)
        return result

    result.update({
        "completed": True,
        "reason": "confirmed_stop_terminalized",
        "completion_basis": "newer_fresh_physical_stop_readback",
        "cleared_action_latch_id": action_latch_id,
    })
    runtime.group_deficit_state = {}
    runtime.group_deficit_binding = {}
    for item in boxes:
        item.pop("_wallbox_group_deficit_action_binding", None)
        item.pop("_wallbox_group_deficit_downward_authority", None)
        item.pop("_wallbox_group_deficit_stop_receipt_binding", None)
        item.pop(_GROUP_DEFICIT_CURRENT_DOWN_SETTLE_KEY, None)
        item["_wallbox_group_deficit_stop_completion"] = dict(result)
    return result


def _wallbox_source_session_context(c_data):
    """Versiegelt alle Session-Namensräume ohne sie gleichzusetzen.

    Start-Haltevertrag, generische Steckepisode und openWB-Pro-Stecksession
    haben absichtlich verschiedene Lebenszyklen und Bezeichner. Fachlicher
    Primärschlüssel bleibt deshalb exakt die bereits für die Defizitaktion
    verwendete Regelsession. Der zusätzliche Kontext-Hash bindet alle aktuell
    vorhandenen Quellen samt ihrer Rollen; jede Rotation verwirft den alten
    Quellen-Wattdeckel, ohne fälschlich String-Gleichheit zu verlangen.
    """

    data = c_data if isinstance(c_data, dict) else {}
    charger = data.get("charger")
    charger_class = (
        charger.__class__.__name__ if charger is not None else ""
    )
    try:
        wb_id = int(data.get("id", 0) or 0)
    except (TypeError, ValueError, OverflowError):
        wb_id = 0
    start_hold_session = str(
        data.get(wallbox_start_hold.SESSION_KEY) or ""
    ).strip()
    openwb_pro_session_id = str(
        data.get("_openwb_pro_plug_session_id") or ""
    ).strip()
    generic_plug_episode_id = str(
        data.get("_wallbox_plug_episode_id") or ""
    ).strip()
    openwb_pro = openwb_pro_session.is_openwb_pro_charger(charger)
    physical_session_id = (
        openwb_pro_session_id if openwb_pro else generic_plug_episode_id
    )
    physical_session_source = (
        "openwb_pro" if openwb_pro else "generic_plug_episode"
    )
    primary_session_id = _wallbox_group_deficit_current_session_id(data)
    if start_hold_session:
        primary_source = "start_hold"
    elif openwb_pro_session_id:
        primary_source = "openwb_pro"
    elif generic_plug_episode_id:
        primary_source = "generic_plug_episode"
    else:
        primary_source = ""

    blockers = []
    if wb_id <= 0:
        blockers.append("wb_id_invalid")
    if not charger_class:
        blockers.append("charger_class_unbound")
    if not primary_session_id or not primary_source:
        blockers.append("primary_session_unbound")
    if not physical_session_id:
        blockers.append("physical_session_unbound")
    for name, value in (
        ("primary_session", primary_session_id),
        ("start_hold_session", start_hold_session),
        ("openwb_pro_session", openwb_pro_session_id),
        ("generic_plug_episode", generic_plug_episode_id),
    ):
        if len(value) > 256:
            blockers.append("%s_invalid" % name)
    if openwb_pro and not openwb_pro_session_id:
        blockers.append("openwb_pro_session_unbound")

    material = {
        "schema": _SOURCE_SESSION_CONTEXT_SCHEMA,
        "wb_id": wb_id,
        "charger_class": charger_class,
        "primary_session_id": primary_session_id,
        "primary_session_source": primary_source,
        "physical_session_id": physical_session_id,
        "physical_session_source": physical_session_source,
        "start_hold_session_id": start_hold_session,
        "openwb_pro_session_id": openwb_pro_session_id,
        "generic_plug_episode_id": generic_plug_episode_id,
    }
    valid = not blockers
    return {
        **material,
        "valid": valid,
        "blockers": blockers,
        "session_context_key": revision_hash(material) if valid else "",
    }


def _materialize_pending_source_watt_caps(chargers):
    """Versiegelt vorbereitete Caps nach Stabilisierung aller Sessions."""

    result = {
        "contract": "wallbox_source_watt_cap_materialization_v1",
        "slots": {},
        "output_authority": False,
    }
    for box in chargers or ():
        if not isinstance(box, dict):
            continue
        pending = box.pop(
            "_pending_session_source_watt_cap_material",
            None,
        )
        if not isinstance(pending, dict):
            continue
        session_context = _wallbox_source_session_context(box)
        material = dict(pending)
        material.update({
            "plug_session_id": str(
                session_context.get("primary_session_id") or ""
            ),
            "session_context_key": str(
                session_context.get("session_context_key") or ""
            ),
            "source_contract_valid": bool(
                pending.get("source_contract_valid") is True
                and session_context.get("valid") is True
            ),
        })
        cap = wallbox_source_watt_cap.build_source_watt_cap(**material)
        box["_session_source_watt_cap"] = cap
        wb_id = int(_cfg_float(box.get("id"), 0.0))
        result["slots"][wb_id] = {
            "valid": cap.get("valid") is True,
            "reason": str(cap.get("reason") or ""),
            "session_context": dict(session_context),
        }
    result["all_valid"] = bool(
        result["slots"]
        and all(
            item.get("valid") is True
            for item in result["slots"].values()
        )
    )
    return result


def _wallbox_group_deficit_downward_authority_matches(
    c_data,
    command,
    *,
    c_id=None,
):
    """Erlaubt ausschließlich die exakt gebundene positive Absenkung.

    Diese eng typisierte Ausnahme öffnet weder einen Start noch eine
    Hochregelung. Sie erlaubt lediglich, dass der zentrale PCC-Defizit-Owner
    trotz eines bereits auf 0 W gefallenen Storage-/Allokationsdeckels den
    physisch noch laufenden Ladestrom reduzieren kann.
    """

    box = c_data if isinstance(c_data, dict) else {}
    cmd = command if isinstance(command, dict) else {}
    method = str(cmd.get("method") or cmd.get("kind") or "").strip()
    if method not in _EFFECTIVE_CURRENT_METHODS:
        return False
    binding = box.get("_wallbox_group_deficit_action_binding")
    authority = box.get("_wallbox_group_deficit_downward_authority")
    generation = box.get("_wallbox_group_deficit_generation_contract")
    if not (
        isinstance(binding, dict)
        and binding.get("schema") == _GROUP_DEFICIT_ACTION_BINDING_SCHEMA
        and binding.get("active") is True
        and binding.get("action") == wallbox_deficit_control.ACTION_CURRENT_DOWN
        and isinstance(authority, dict)
        and authority.get("schema")
        == _GROUP_DEFICIT_DOWNWARD_AUTHORITY_SCHEMA
        and authority.get("active") is True
        and isinstance(generation, dict)
        and generation.get("contract")
        == "wallbox_group_deficit_generation_v1"
        and generation.get("binding_ready") is True
    ):
        return False
    try:
        expected_wb_id = int(
            c_id if c_id is not None else box.get("id", 0)
        )
        binding_generation = int(binding.get("binding_generation", 0))
        authority_generation = int(authority.get("binding_generation", 0))
        current_generation = int(generation.get("binding_generation", 0))
        binding_wb_id = int(binding.get("wb_id", 0))
        authority_wb_id = int(authority.get("wb_id", 0))
        effective_owner_id = int(generation.get("effective_owner_id", 0))
    except (TypeError, ValueError, OverflowError):
        return False
    cycle_token = str(box.get("_wallbox_cycle_token") or "")
    snapshot_id = str(binding.get("snapshot_id") or "")
    session_id = _wallbox_group_deficit_current_session_id(box)
    if not (
        expected_wb_id > 0
        and expected_wb_id == binding_wb_id == authority_wb_id
        and expected_wb_id == effective_owner_id
        and binding_generation > 0
        and binding_generation == authority_generation == current_generation
        and cycle_token
        and cycle_token == str(binding.get("cycle_token") or "")
        and cycle_token == str(authority.get("cycle_token") or "")
        and snapshot_id
        and snapshot_id == str(authority.get("snapshot_id") or "")
        and session_id
        and session_id == str(binding.get("plug_session_id") or "")
        and session_id == str(authority.get("plug_session_id") or "")
    ):
        return False
    requested = _cfg_float(cmd.get("amp"), -1.0)
    target = _cfg_float(authority.get("target_amp"), -1.0)
    bound_target = _cfg_float(binding.get("target_amp"), -1.0)
    observed = _cfg_float(authority.get("observed_amp"), -1.0)
    minimum = max(1.0, _cfg_float(authority.get("min_amp"), 6.0))
    return bool(
        math.isfinite(requested)
        and math.isfinite(target)
        and math.isfinite(observed)
        and requested >= minimum
        and abs(requested - target) <= 0.051
        and abs(bound_target - target) <= 0.051
        and target + 0.051 < observed
    )


def _openwb_pro_mode0_output_binding_matches(
    c_data,
    command,
    *,
    expected_action=None,
):
    """Bindet eine sichere Modus-0-Kante exakt an Lease und Managerzyklus."""

    box = c_data if isinstance(c_data, dict) else {}
    cmd = command if isinstance(command, dict) else {}
    charger = box.get("charger") or cmd.get("charger")
    if not openwb_pro_session.is_openwb_pro_charger(charger):
        return False
    scoped = command_gate.default_release_binding(charger)
    supplied = cmd.get("_openwb_pro_mode0_release_binding")
    if not isinstance(scoped, dict) or not isinstance(supplied, dict):
        return False
    if supplied != scoped:
        return False
    action = str(scoped.get("action") or "")
    if expected_action is not None and action != str(expected_action):
        return False
    if (
        scoped.get("schema") != OPENWB_PRO_MODE0_OUTPUT_BINDING_SCHEMA
        or str(scoped.get("cycle_token") or "")
        != str(box.get("_wallbox_cycle_token") or "")
        or int(scoped.get("wb_id", 0) or 0) != int(box.get("id", 0) or 0)
    ):
        return False
    method = str(cmd.get("method") or cmd.get("kind") or "").strip()
    reason = str(cmd.get("reason") or "")
    if reason != "mode0_default_release":
        return False
    if action == openwb_pro_control_lease.ACTION_SEND_ZERO:
        return bool(
            method == "release_to_default"
            and abs(_cfg_float(cmd.get("max_amp"), 0.0)) <= 1e-9
        )
    if action == openwb_pro_control_lease.ACTION_SEND_HEARTBEAT_OFF:
        return bool(method == "set_heartbeat" and cmd.get("enabled") is False)
    return False


def _canonical_guarded_stop_command(command):
    cmd = command if isinstance(command, dict) else {}
    return bool(
        str(cmd.get("kind") or "").strip() == "stop"
        and cmd.get("_canonical_stop_command") is True
        and cmd.get("_control_guard_checked") is True
    )


def _emergency_wallbox_output_command(command):
    cmd = command if isinstance(command, dict) else {}
    method = str(cmd.get("method") or cmd.get("kind") or "").strip()
    reason = str(cmd.get("reason") or "").strip()
    typed_pre_guard_stop = bool(
        method == "stop"
        and cmd.get("_typed_emergency_stop_intent") is True
        and _valid_typed_wallbox_stop_authority(cmd.get("stop_authority"))
    )
    return bool(
        (
            method == "emergency_stop"
            or _canonical_guarded_stop_command(cmd)
            or typed_pre_guard_stop
        )
        and (
            cmd.get("_emergency_override") is True
            or reason in ("emergency_stop", "not_aus", "webui_not_aus")
        )
    )


def _native_e3dc_floor_no_io_handoff_command(
    c_data,
    command,
    *,
    charger=None,
    c_id=None,
):
    """Erkennt nur den expliziten Nutzer-Aus-Handoff ohne WBchar6-Ausgang."""

    box = c_data if isinstance(c_data, dict) else {}
    cmd = command if isinstance(command, dict) else {}
    device = charger if charger is not None else box.get("charger")
    method = str(cmd.get("method") or cmd.get("kind") or "").strip()
    if method not in ("release_to_e3dc", "release_to_default"):
        return False
    context = getattr(device, "_command_gate_context", None)
    try:
        context_mode = int((context or {}).get("mode", -1))
        context_wb_id = int((context or {}).get("wb_id", 0))
        expected_wb_id = int(
            c_id if c_id is not None else box.get("id", 0)
        )
    except (TypeError, ValueError):
        return False
    return bool(
        str(cmd.get("reason") or "") == "mode0_default_release"
        and device is not None
        and command_gate.is_default_release_allowed(device)
        and str(
            getattr(device, "_command_gate_release_type", "") or ""
        )
        == "user_off_handoff"
        and str(
            getattr(device, "_command_gate_release_reason", "") or ""
        )
        == "mode0_user_switch"
        and isinstance(context, dict)
        and context_mode == MODE_OFF
        and str(context.get("owner") or "") == "wallbox_manager"
        and expected_wb_id > 0
        and context_wb_id == expected_wb_id
    )


def _native_e3dc_floor_output_authority_contract(
    c_data,
    command,
    *,
    charger=None,
    c_id=None,
    stage="",
):
    """Sperrt am Floor-Anker jeden nativen Ausgang außer sicheren Kanten."""

    box = c_data if isinstance(c_data, dict) else {}
    cmd = command if isinstance(command, dict) else {}
    device = charger if charger is not None else box.get("charger")
    method = str(cmd.get("method") or cmd.get("kind") or "").strip()
    amp_field = "max_amp" if method in (
        "release_to_e3dc",
        "release_to_default",
    ) else "amp"
    requested_amp = _cfg_float(cmd.get(amp_field), 0.0)
    native_floor_anchor = bool(
        e3dc_session.is_e3dc_native_charger(device)
        and _native_e3dc_floor_zero_anchor_active(box)
    )
    canonical_stop = _canonical_guarded_stop_command(cmd)
    typed_not_aus = _emergency_wallbox_output_command(cmd)
    typed_deficit_downward = (
        _wallbox_group_deficit_downward_authority_matches(
            box,
            cmd,
            c_id=c_id,
        )
    )
    no_io_handoff = _native_e3dc_floor_no_io_handoff_command(
        box,
        cmd,
        charger=device,
        c_id=c_id,
    )
    # ``method=stop`` führt an dieser Ebene selbst kein I/O aus. Erst der
    # rekursive, guard-geprüfte kanonische Stop darf den Treiber erreichen und
    # wird dort erneut durch diesen Vertrag geprüft.
    stop_intent_to_canonical = bool(
        method == "stop" and not canonical_stop
    )
    safe_exception = bool(
        canonical_stop
        or typed_not_aus
        or typed_deficit_downward
        or no_io_handoff
        or stop_intent_to_canonical
    )
    allowed = bool(not native_floor_anchor or safe_exception)
    contract = {
        "contract": "native_e3dc_floor_output_authority_v1",
        "active": native_floor_anchor,
        "allowed": allowed,
        "stage": str(stage or "driver_executor"),
        "cycle_token": str(box.get("_wallbox_cycle_token") or ""),
        "method": method,
        "amp_field": amp_field,
        "requested_amp": requested_amp,
        "take_control": method == "take_control",
        "effective_current_method": method in _EFFECTIVE_CURRENT_METHODS,
        "canonical_stop": canonical_stop,
        "typed_not_aus": typed_not_aus,
        "typed_group_deficit_downward": typed_deficit_downward,
        "explicit_no_io_handoff": no_io_handoff,
        "stop_intent_to_canonical": stop_intent_to_canonical,
        "dispatch_allowed": allowed,
        "hardware_output_allowed": bool(
            allowed
            and not no_io_handoff
            and not stop_intent_to_canonical
        ),
        "release_status": (
            "not_required" if allowed else "EVIDENCE_LIMIT"
        ),
        "blocker": (
            "" if allowed else "native_floor_zero_anchor_retry_not_released"
        ),
    }
    return contract


def _apply_native_e3dc_floor_output_authority_gate(
    c_data,
    command,
    *,
    charger=None,
    c_id=None,
    stage="",
):
    """Wendet den typisierten Floor-Ausgangsvertrag ohne Zustandsprojektion an."""

    box = c_data if isinstance(c_data, dict) else {}
    contract = _native_e3dc_floor_output_authority_contract(
        box,
        command,
        charger=charger,
        c_id=c_id,
        stage=stage,
    )
    box["_native_e3dc_floor_output_authority"] = dict(contract)
    stage_key = str(stage or "driver_executor").strip().lower()
    if stage_key:
        box[
            "_native_e3dc_floor_output_authority_%s" % stage_key
        ] = dict(contract)
    if contract.get("allowed") is True:
        return True
    release = _native_e3dc_floor_retry_not_released_contract(
        box,
        source="driver_executor_%s" % (stage_key or "authority"),
    )
    box["_native_e3dc_floor_zero_anchor_retry_release"] = dict(release)
    dispatch = box.get("_wallbox_driver_dispatch_contract")
    if isinstance(dispatch, dict):
        dispatch.update({
            "blocked": True,
            "blocker": "native_floor_zero_anchor_retry_not_released",
            "release_status": "EVIDENCE_LIMIT",
            "wire_attempted": False,
        })
    _discard_wallbox_command_guard_pending(box)
    return False


def _bind_effective_current_output_contract(
    c_data,
    target_amp,
    reason="",
    *,
    base_target_amp=None,
    allocated_budget_w=None,
    target_phases=None,
    target_power_w=None,
):
    """Versiegle den finalen Stromdeckel für genau einen Managerzyklus."""

    box = c_data if isinstance(c_data, dict) else {}
    cycle_token = str(box.get("_wallbox_cycle_token") or "")
    target = max(0.0, _cfg_float(target_amp, 0.0))
    contract = {
        "contract": "wallbox_effective_current_output_contract_v1",
        "active": bool(cycle_token),
        "cycle_token": cycle_token,
        "target_amp": target,
        "reason": str(reason or "effective_current_output"),
    }
    if base_target_amp is not None:
        contract["base_target_amp"] = max(
            0.0,
            _cfg_float(base_target_amp, 0.0),
        )
    if allocated_budget_w is not None:
        contract["allocated_budget_w"] = max(
            0.0,
            _cfg_float(allocated_budget_w, 0.0),
        )
    if target_phases is not None:
        contract["target_phases"] = _valid_phase_count(target_phases, 0)
    if target_power_w is not None:
        contract["target_power_w"] = max(
            0.0,
            _cfg_float(target_power_w, 0.0),
        )
    box["_effective_current_output_contract"] = contract
    box.pop("_effective_current_output_gate", None)
    return contract


def _flush_openwb_primary_start_after_readback(c_data, *, c_id=None):
    """Aktiviert Primary-Sofortladen erst nach aktuellem Strom-Readback."""

    box = c_data if isinstance(c_data, dict) else {}
    charger = box.get("charger")
    if not (
        charger is not None
        and charger.__class__.__name__ == "OpenWBCharger"
        and bool(getattr(charger, "primary_mode_enabled", False))
    ):
        return None
    try:
        pending_amp = float(
            getattr(charger, "_primary_pending_current_amp", 0.0) or 0.0
        )
        pending_sent_ts = float(
            getattr(charger, "_primary_pending_current_sent_ts", 0.0) or 0.0
        )
    except (TypeError, ValueError, OverflowError):
        return None
    if pending_amp < 6.0 or pending_sent_ts <= 0.0:
        return None

    cycle_token = str(box.get("_wallbox_cycle_token") or "")
    effective = box.get("_effective_current_output_contract")
    allocation = box.get("_multi_allocation_output_cap")
    if not (
        cycle_token
        and isinstance(effective, dict)
        and effective.get("active") is True
        and str(effective.get("cycle_token") or "") == cycle_token
        and abs(
            _cfg_float(effective.get("target_amp"), 0.0) - pending_amp
        ) <= 0.051
        and isinstance(allocation, dict)
        and allocation.get("active") is True
        and str(allocation.get("cycle_token") or "") == cycle_token
        and _cfg_float(allocation.get("cap_amp"), 0.0) + 0.051
        >= pending_amp
    ):
        return None

    ledger = box.get(wallbox_output_ledger.LEDGER_KEY)
    if not (
        isinstance(ledger, dict)
        and ledger.get("token_valid") is True
        and str(ledger.get("cycle_token") or "") == cycle_token
        and not bool(ledger.get("normal_claimed"))
        and not bool(ledger.get("normal_locked"))
        and not bool(ledger.get("emergency_claimed"))
    ):
        return None

    driver_state = getattr(charger, "state", {})
    driver_state = driver_state if isinstance(driver_state, dict) else {}
    readback_check = getattr(
        charger,
        "_primary_current_readback_confirmed",
        None,
    )
    if (
        not callable(readback_check)
        or driver_state.get("driver_status_glitch") is True
        or not bool(readback_check(pending_amp))
    ):
        return None

    sent = bool(
        _execute_wallbox_driver_command(
            box,
            {
                "method": "set_amp_and_state",
                "amp": pending_amp,
                "force_state": 2,
                "reason": "openwb_primary_start_after_current_readback",
            },
            c_id=c_id,
        )
    )
    if sent:
        # Der echte Treiber räumt den Übergang beim bestätigten Moduswechsel
        # bereits auf. Der zusätzliche Abschluss macht auch Adapter/Fakes
        # strikt one-shot, ohne einen fehlgeschlagenen Versuch zu verbrauchen.
        clear_transition = getattr(
            charger,
            "_clear_primary_start_transition",
            None,
        )
        if callable(clear_transition):
            clear_transition()
    return sent


def _openwb_pro_keepalive_due(
    *,
    hw_charging,
    offered_amp,
    keepalive_amp,
    over_target=False,
):
    """Erlaube Keepalive nur für echte Ladung oder sichere Absenkung."""

    target = max(0.0, _cfg_float(keepalive_amp, 0.0))
    offered = max(0.0, _cfg_float(offered_amp, 0.0))
    if target < 6.0:
        return False
    if bool(over_target) or offered > target + 0.5:
        return True
    if not bool(hw_charging):
        # Im wartenden Start gehört der einzige Ausgangsslot dem expliziten
        # Start-/CP-Orakel und nicht einem vermeintlichen Keepalive.
        return False
    return offered < target - 0.5


def _apply_effective_current_output_gate(c_data, command, *, c_id=None):
    """Erzwinge den post-Policy-Stromdeckel unmittelbar vor Treiber-I/O."""

    box = c_data if isinstance(c_data, dict) else {}
    cmd = dict(command or {})
    method = str(cmd.get("method") or cmd.get("kind") or "").strip()
    requested = max(0.0, _cfg_float(cmd.get("amp"), 0.0))
    deficit_downward_authority = (
        _wallbox_group_deficit_downward_authority_matches(
            box,
            cmd,
            c_id=c_id,
        )
    )
    gate = {
        "contract": "wallbox_effective_current_output_gate_v1",
        "authoritative": True,
        "method": method,
        "requested_amp": requested,
        "cycle_token": str(box.get("_wallbox_cycle_token") or ""),
        "blocked": False,
        "limited": False,
    }

    if _canonical_guarded_stop_command(cmd):
        gate.update({
            "active": True,
            "reason": "stop_command_unchanged",
            "applied_amp": requested,
        })
        box["_effective_current_output_gate"] = gate
        return cmd, True
    if _emergency_wallbox_output_command(cmd):
        gate.update({
            "active": True,
            "reason": "emergency_command_unchanged",
            "applied_amp": requested,
        })
        box["_effective_current_output_gate"] = gate
        return cmd, True
    # Der abstrakte Stop wird erst nach dem allgemeinen Command-Guard in einen
    # exakt markierten kanonischen Treiberbefehl übersetzt und dort erneut
    # geprüft. Er ist an dieser Stelle noch keine Hardwarekante.
    if method == "stop":
        gate.update({
            "active": True,
            "reason": "stop_intent_requires_canonical_dispatch",
            "applied_amp": 0.0,
        })
        box["_effective_current_output_gate"] = gate
        return cmd, True

    if (
        box.get("_storage_power_budget_hard_block") is True
        and method in _STORAGE_BUDGET_CHARGE_SIDE_EFFECT_METHODS
        and not deficit_downward_authority
        and not _openwb_pro_mode0_output_binding_matches(
            box,
            cmd,
            expected_action=openwb_pro_control_lease.ACTION_SEND_ZERO,
        )
    ):
        gate.update({
            "active": True,
            "blocked": True,
            "reason": "storage_power_budget_readback_blocked",
            "applied_amp": requested,
        })
        box["_effective_current_output_gate"] = gate
        return cmd, False

    if method not in _EFFECTIVE_CURRENT_METHODS:
        gate.update({
            "active": False,
            "reason": "not_a_current_output",
            "applied_amp": requested,
        })
        box["_effective_current_output_gate"] = gate
        return cmd, True

    contract = box.get("_effective_current_output_contract")
    active = bool(
        isinstance(contract, dict)
        and contract.get("active") is True
        and str(contract.get("cycle_token") or "")
        == str(box.get("_wallbox_cycle_token") or "")
        and bool(str(box.get("_wallbox_cycle_token") or ""))
    )
    if not active:
        gate.update({
            "active": False,
            "blocked": True,
            "reason": "effective_current_contract_missing_or_stale",
            "applied_amp": requested,
        })
        box["_effective_current_output_gate"] = gate
        return cmd, False

    target = max(0.0, _cfg_float(contract.get("target_amp"), 0.0))
    gate.update({
        "active": True,
        "target_amp": target,
        "reason": str(contract.get("reason") or "effective_current_output"),
        "typed_group_deficit_downward": deficit_downward_authority,
    })
    if requested > 0.0 and target < 6.0:
        gate.update({
            "blocked": True,
            "applied_amp": requested,
        })
        box["_effective_current_output_gate"] = gate
        return cmd, False
    applied = min(requested, target)
    if applied < requested:
        cmd["amp"] = applied
        gate["limited"] = True
    gate["applied_amp"] = applied
    box["_effective_current_output_gate"] = gate
    return cmd, True


def _apply_multi_allocation_output_gate(c_data, command, *, c_id=None):
    """Begrenze jeden stromsetzenden Treiberbefehl am finalen I/O-Rand."""

    box = c_data if isinstance(c_data, dict) else {}
    cmd = dict(command or {})
    method = str(cmd.get("method") or cmd.get("kind") or "").strip()
    field = None
    if method in (
        "set_amp_and_state",
        "set_current",
        "set_direct_current",
        "set_amp_sonnenmodus",
        "set_amp_autonomous_solar",
    ):
        field = "amp"
    elif method in ("release_to_e3dc", "release_to_default"):
        field = "max_amp"
    if field is None:
        return cmd, True

    # Ein vom zentralen Stop-Pfad erzeugter und bereits vom Command-Guard
    # geprüfter Stop darf nicht durch einen 0-A-Allokationsdeckel verhindert
    # werden. Bei nativen E3DC-Treibern ist der positive Ampereparameter Teil
    # des Stop-/Release-Protokolls und keine Ladefreigabe. Die Ausnahme ist
    # absichtlich an den kanonischen Stopmarker gebunden; ein beliebiges
    # ``kind=stop`` oder ``force_state`` genügt nicht.
    canonical_stop = bool(
        str(cmd.get("kind") or "").strip() == "stop"
        and cmd.get("_canonical_stop_command") is True
        and cmd.get("_control_guard_checked") is True
    )
    if canonical_stop:
        return cmd, True

    requested = max(0.0, _cfg_float(cmd.get(field), 0.0))
    deficit_downward_authority = (
        _wallbox_group_deficit_downward_authority_matches(
            box,
            cmd,
            c_id=c_id,
        )
    )
    contract = box.get("_multi_allocation_output_cap")
    cycle_token = str(box.get("_wallbox_cycle_token") or "")
    active = bool(
        isinstance(contract, dict)
        and contract.get("active") is True
        and cycle_token
        and str(contract.get("cycle_token") or "") == cycle_token
    )
    charger = box.get("charger")
    charger_context = (
        getattr(charger, "_command_gate_context", None)
        if charger is not None
        else None
    )
    try:
        context_mode = int((charger_context or {}).get("mode", -1))
        context_wb_id = int((charger_context or {}).get("wb_id", 0))
        expected_wb_id = int(
            c_id if c_id is not None else box.get("id", 0)
        )
    except (TypeError, ValueError):
        context_mode = -1
        context_wb_id = 0
        expected_wb_id = 0
    typed_openwb_pro_handoff = _openwb_pro_mode0_output_binding_matches(
        box,
        cmd,
        expected_action=openwb_pro_control_lease.ACTION_SEND_ZERO,
    )
    default_release_handoff = bool(
        typed_openwb_pro_handoff
        or (
            method in ("release_to_e3dc", "release_to_default")
            and str(cmd.get("reason") or "") == "mode0_default_release"
            and math.isfinite(requested)
            and requested >= 6.0
            and charger is not None
            and command_gate.is_default_release_allowed(charger)
            and str(
                getattr(charger, "_command_gate_release_type", "") or ""
            ) == "user_off_handoff"
            and str(
                getattr(charger, "_command_gate_release_reason", "") or ""
            ) == "mode0_user_switch"
            and isinstance(charger_context, dict)
            and context_mode == MODE_OFF
            and str(charger_context.get("owner") or "") == "wallbox_manager"
            and expected_wb_id > 0
            and context_wb_id == expected_wb_id
        )
    )
    gate = {
        "authoritative": True,
        "active": active,
        "method": method,
        "requested_amp": requested,
        "applied_amp": requested,
        "cap_amp": _cfg_float((contract or {}).get("cap_amp"), 0.0),
        "reason": (
            str((contract or {}).get("reason") or "allocation_cap_active")
            if active
            else "per_wallbox_allocation_missing_or_stale"
        ),
        "default_release_handoff": default_release_handoff,
    }
    box["_multi_allocation_output_gate"] = gate
    if deficit_downward_authority:
        gate.update({
            "active": True,
            "typed_group_deficit_downward": True,
            "reason": "typed_group_deficit_downward",
        })
        return cmd, True
    if default_release_handoff:
        gate["reason"] = (
            "typed_openwb_pro_mode0_zero"
            if typed_openwb_pro_handoff
            else "user_mode0_default_release"
        )
        return cmd, True
    if not active:
        gate["blocked"] = True
        return cmd, False
    applied = _multi_allocation_cap_value(box, requested)
    gate["applied_amp"] = applied
    if requested > 0.0 and applied < 6.0:
        gate["blocked"] = True
        logger.warning(
            "WB%s Allokationsausgang blockiert %s: %.1fA angefordert, 0A zugeteilt.",
            c_id if c_id is not None else box.get("id", "?"),
            method,
            requested,
        )
        return cmd, False
    if applied < requested:
        cmd[field] = applied
        gate["limited"] = True
    return cmd, True


def _authorized_wallbox_output_phase_count(c_data, command=None):
    """Bindet den Strombefehl an die höchste aktuell wirksame Phasenzahl.

    Die vorherige Allokation versiegelt ihre frisch geprüfte Phasenzahl
    zusammen mit Wattbudget und Zyklustoken. Das ist insbesondere bei einem
    einphasigen Fahrzeug an einer festen dreiphasigen E3/DC-Wallbox relevant:
    ``phases_target=3`` beschreibt dort die Wallbox, nicht die tatsächlich
    mögliche Fahrzeuglast. Explizite Phasenbefehle und laufende
    Übergangsreservierungen bleiben dennoch die konservative Obergrenze.
    """

    box = c_data if isinstance(c_data, dict) else {}
    cmd = command if isinstance(command, dict) else {}
    candidates = []
    for value in (cmd.get("target_phases"), cmd.get("phases")):
        phase_count = _valid_phase_count(value, 0)
        if phase_count:
            candidates.append(phase_count)
    for key in (
        "_wallbox_phase_transition_reservation",
        "_openwb_pro_phase_sequence",
        "_openwb_pro_phase_output_intent",
    ):
        item = box.get(key)
        if not isinstance(item, dict):
            continue
        for field in ("target_phases", "target", "phases"):
            phase_count = _valid_phase_count(item.get(field), 0)
            if phase_count:
                candidates.append(phase_count)

    watt_contract = (
        box.get("_authorized_wallbox_watt_output_cap")
        if isinstance(box.get("_authorized_wallbox_watt_output_cap"), dict)
        else {}
    )
    sealed_phases = _valid_phase_count(
        watt_contract.get("authorized_phases"),
        0,
    )
    sealed_phase_authority = bool(
        sealed_phases
        and watt_contract.get("active") is True
        and watt_contract.get("cycle_token") == box.get("_wallbox_cycle_token")
    )
    if sealed_phase_authority:
        candidates.append(sealed_phases)
        return max(candidates or [sealed_phases])

    status = box.get("last_valid") if isinstance(box.get("last_valid"), dict) else {}
    for field in (
        "phases_target",
        "physical_phases",
        "phases_actual",
        "phases_in_use",
        "phase_effective_phases",
    ):
        phase_count = _valid_phase_count(status.get(field), 0)
        if phase_count:
            candidates.append(phase_count)
    return max(candidates or [1])


def _apply_authorized_wallbox_watt_output_gate(c_data, command, *, c_id=None):
    """Begrenzt jeden positiven Stromausgang am versiegelten Wattbudget."""

    box = c_data if isinstance(c_data, dict) else {}
    cmd = dict(command or {})
    method = str(cmd.get("method") or cmd.get("kind") or "").strip()
    if method not in (
        "set_amp_and_state",
        "set_current",
        "set_direct_current",
        "set_amp_sonnenmodus",
        "set_amp_autonomous_solar",
    ):
        return cmd, True
    canonical_stop = bool(
        str(cmd.get("kind") or "").strip() == "stop"
        and cmd.get("_canonical_stop_command") is True
        and cmd.get("_control_guard_checked") is True
    )
    if canonical_stop:
        return cmd, True

    deficit_downward_authority = (
        _wallbox_group_deficit_downward_authority_matches(
            box,
            cmd,
            c_id=c_id,
        )
    )
    if deficit_downward_authority:
        requested = max(0.0, _cfg_float(cmd.get("amp"), 0.0))
        box["_authorized_wallbox_watt_output_gate"] = {
            "contract": "authorized_wallbox_watt_output_gate_v1",
            "authoritative": True,
            "active": True,
            "method": method,
            "requested_amp": requested,
            "applied_amp": requested,
            "cycle_token": box.get("_wallbox_cycle_token"),
            "reason": "typed_group_deficit_downward",
            "typed_group_deficit_downward": True,
        }
        return cmd, True

    contract = box.get("_authorized_wallbox_watt_output_cap")
    active = bool(
        isinstance(contract, dict)
        and contract.get("active") is True
        and contract.get("cycle_token") == box.get("_wallbox_cycle_token")
    )
    if not active:
        return cmd, True
    requested = max(0.0, _cfg_float(cmd.get("amp"), 0.0))
    phases = _authorized_wallbox_output_phase_count(box, cmd)
    autonomous_projection = box.get("_autonomous_solar_watt_projection")
    autonomous_method_bound = bool(
        method == "set_amp_autonomous_solar"
        and _current_autonomous_solar_output_contract(box)
        and isinstance(autonomous_projection, dict)
        and autonomous_projection.get("active") is True
        and autonomous_projection.get("method") == method
        and autonomous_projection.get("cycle_token")
        == box.get("_wallbox_cycle_token")
    )
    if autonomous_method_bound:
        phases = 1
    cap_w = max(0.0, _cfg_float(contract.get("cap_w"), 0.0))
    step = _current_step_amp_for_charger(box.get("charger"), default=1.0)
    cap_amp = _round_amp_down_to_step(cap_w / (230.0 * phases), step)
    if cap_amp < 6.0:
        cap_amp = 0.0
    applied = min(requested, cap_amp)
    gate = {
        "contract": "authorized_wallbox_watt_output_gate_v1",
        "authoritative": True,
        "active": True,
        "method": method,
        "requested_amp": requested,
        "applied_amp": applied,
        "cap_amp": cap_amp,
        "cap_w": cap_w,
        "phases": phases,
        "cycle_token": box.get("_wallbox_cycle_token"),
        "reason": str(contract.get("reason") or "storage_wallbox_budget"),
        "watt_budget_semantics": (
            "autonomous_pv_sink"
            if autonomous_method_bound
            else "strict_phase_projection"
        ),
        "strict_watt_cap": not autonomous_method_bound,
    }
    box["_authorized_wallbox_watt_output_gate"] = gate
    if requested > 0.0 and applied < 6.0:
        gate["blocked"] = True
        logger.warning(
            "WB%s Wattbudget-Ausgang blockiert %s: %.1f A angefordert, "
            "%.0f W reichen bei %dp nicht für 6 A.",
            c_id if c_id is not None else box.get("id", "?"),
            method,
            requested,
            cap_w,
            phases,
        )
        return cmd, False
    if applied < requested:
        cmd["amp"] = applied
        gate["limited"] = True
    return cmd, True


def _peak_shaving_cap_value(c_data, requested_amp):
    """Wende den zyklusgebundenen Viertelstunden-Deckel strikt an."""

    box = c_data if isinstance(c_data, dict) else {}
    contract = box.get("_peak_shaving_output_cap")
    requested = max(0.0, _cfg_float(requested_amp, 0.0))
    if (
        not isinstance(contract, dict)
        or contract.get("active") is not True
        or contract.get("cycle_token") != box.get("_wallbox_cycle_token")
    ):
        return requested
    cap_amp = max(0.0, _cfg_float(contract.get("cap_amp"), 0.0))
    if cap_amp < 6.0:
        return 0.0
    return min(requested, cap_amp)


def _apply_peak_shaving_output_gate(c_data, command, *, c_id=None):
    """Verhindere, dass Komfortpfade den 15-Minuten-Rahmen wieder öffnen.

    Base-6-A, Start-Holds, Keepalives und sanfte Abregelrampen liegen bewusst
    vor diesem letzten I/O-Deckel. Eine kanonische Abschaltung bleibt dagegen
    immer zulässig.
    """

    box = c_data if isinstance(c_data, dict) else {}
    cmd = dict(command or {})
    method = str(cmd.get("method") or cmd.get("kind") or "").strip()
    field = None
    if method in (
        "set_amp_and_state",
        "set_current",
        "set_direct_current",
        "set_amp_sonnenmodus",
        "set_amp_autonomous_solar",
    ):
        field = "amp"
    elif method in ("release_to_e3dc", "release_to_default"):
        field = "max_amp"
    if field is None:
        return cmd, True

    canonical_stop = bool(
        str(cmd.get("kind") or "").strip() == "stop"
        and cmd.get("_canonical_stop_command") is True
        and cmd.get("_control_guard_checked") is True
    )
    if canonical_stop:
        return cmd, True

    requested = max(0.0, _cfg_float(cmd.get(field), 0.0))
    deficit_downward_authority = (
        _wallbox_group_deficit_downward_authority_matches(
            box,
            cmd,
            c_id=c_id,
        )
    )
    if deficit_downward_authority:
        box["_peak_shaving_output_gate"] = {
            "contract": "peak_shaving_wallbox_output_gate_v1",
            "authoritative": True,
            "active": True,
            "method": method,
            "requested_amp": requested,
            "applied_amp": requested,
            "cycle_token": box.get("_wallbox_cycle_token"),
            "reason": "typed_group_deficit_downward",
            "typed_group_deficit_downward": True,
        }
        return cmd, True
    applied = _peak_shaving_cap_value(box, requested)
    contract = box.get("_peak_shaving_output_cap")
    active = bool(
        isinstance(contract, dict)
        and contract.get("active") is True
        and contract.get("cycle_token") == box.get("_wallbox_cycle_token")
    )
    gate = {
        "contract": "peak_shaving_wallbox_output_gate_v1",
        "authoritative": True,
        "active": active,
        "method": method,
        "requested_amp": requested,
        "applied_amp": applied,
        "cap_amp": _cfg_float((contract or {}).get("cap_amp"), 0.0),
        "cap_w": (contract or {}).get("cap_w"),
        "reason": str((contract or {}).get("reason") or "inactive"),
    }
    box["_peak_shaving_output_gate"] = gate
    if active and requested > 0.0 and applied < 6.0:
        gate["blocked"] = True
        logger.warning(
            "WB%s Viertelstunden-Ausgang blockiert %s: %.1fA angefordert, "
            "Restspielraum unter Mindestleistung.",
            c_id if c_id is not None else box.get("id", "?"),
            method,
            requested,
        )
        return cmd, False
    if active and applied < requested:
        cmd[field] = applied
        gate["limited"] = True
    return cmd, True


def _openwb_pro_output_phase_count(c_data, command):
    """Bestimme die für einen Strombefehl belegte Phasenzahl.

    Ein aktueller 1p-Deckel ist selbst ein belastbarer 1p-Nachweis. Danach
    gelten nur explizite Befehls- oder frische Treiberfelder. Bleibt die
    Phasenzahl beim Start unbekannt, wird konservativ wie 1p begrenzt, bis der
    Treiber drei aktive Phasen bestätigt.
    """

    box = c_data if isinstance(c_data, dict) else {}
    cmd = command if isinstance(command, dict) else {}
    cycle_token = box.get("_wallbox_cycle_token")
    contract = box.get("_openwb_pro_one_phase_cap")
    if (
        isinstance(contract, dict)
        and contract.get("active") is True
        and contract.get("cycle_token") == cycle_token
        and int(contract.get("charger_phases", 0) or 0) == 1
    ):
        return 1, "current_cycle_contract"

    for key in ("target_phases", "phases"):
        try:
            value = int(cmd.get(key, 0) or 0)
        except (TypeError, ValueError):
            value = 0
        if value == 1:
            return value, f"command_{key}"

    status = box.get("last_valid")
    if isinstance(status, dict):
        status_fresh = bool(
            status.get("driver_status_valid") is True
            and status.get("driver_status_stale") is False
            and not bool(status.get("stale", False))
            and not bool(status.get("driver_status_glitch", False))
        )
        if status_fresh:
            active_phases = 0
            measured_phases = 0
            for phase in (1, 2, 3):
                current = status.get(f"phase_current_l{phase}_a")
                power = status.get(f"phase_power_l{phase}_w")
                if current is None and power is None:
                    continue
                measured_phases += 1
                current_a = max(0.0, _cfg_float(current, 0.0))
                power_w = abs(_cfg_float(power, 0.0))
                if current_a > 0.2 or power_w > 50.0:
                    active_phases += 1
            if measured_phases == 3 and active_phases == 3:
                return 3, "driver_three_measured_active_phases"
            if measured_phases > 0:
                return 1, "driver_not_three_measured_active_phases"

    return 1, "unknown_conservative_one_phase"


def _apply_openwb_pro_one_phase_output_gate(
    c_data,
    command,
    *,
    charger=None,
    c_id=None,
):
    """Wende den 1p-PCC-Vertrag am letzten openWB-Pro-I/O-Rand an."""

    box = c_data if isinstance(c_data, dict) else {}
    cmd = dict(command or {})
    if not openwb_pro_session.is_openwb_pro_charger(charger):
        return cmd, True

    method = str(cmd.get("method") or cmd.get("kind") or "").strip()
    if method not in (
        "set_amp_and_state",
        "set_current",
        "set_direct_current",
        "set_amp_sonnenmodus",
        "set_amp_autonomous_solar",
    ):
        return cmd, True
    requested = max(0.0, _cfg_float(cmd.get("amp"), 0.0))
    if requested <= 0.0:
        return cmd, True

    phase_count, phase_source = _openwb_pro_output_phase_count(box, cmd)
    if phase_count != 1:
        box["_openwb_pro_one_phase_output_gate"] = {
            "authoritative": True,
            "active": False,
            "method": method,
            "requested_amp": requested,
            "applied_amp": requested,
            "phase_count": phase_count,
            "phase_source": phase_source,
            "reason": "confirmed_multi_phase",
        }
        return cmd, True

    cycle_token = box.get("_wallbox_cycle_token")
    contract = box.get("_openwb_pro_one_phase_cap")
    contract_current = bool(
        isinstance(contract, dict)
        and contract.get("active") is True
        and contract.get("cycle_token") == cycle_token
        and int(contract.get("charger_phases", 0) or 0) == 1
    )
    if not contract_current:
        context = box.get("_openwb_pro_one_phase_output_context")
        context_current = bool(
            isinstance(context, dict)
            and context.get("cycle_token") == cycle_token
        )
        cfg = box.get("_openwb_pro_config")
        cfg = cfg if isinstance(cfg, dict) else {}
        charger_limit = _cfg_float(
            (context or {}).get("charger_max_amp") if context_current else None,
            _cfg_float(getattr(charger, "max_amp", 0.0), 0.0),
        )
        if charger_limit <= 0.0:
            _limit_cid = int(c_id or box.get("id", 1) or 1)
            _limit_global = _amp_limit(
                cfg.get("wbmaxladestrom", cfg.get("wb_max_amp", 16)),
                16,
            )
            charger_limit = float(
                _charger_max_amp(
                    cfg,
                    _limit_cid,
                    _limit_global,
                )
            )
        status = box.get("last_valid")
        live = (context or {}).get("live") if context_current else None
        if context_current and isinstance(live, dict):
            _cap_openwb_pro_one_phase_amp(
                requested,
                1,
                cfg,
                c_id if c_id is not None else box.get("id", 1),
                charger_limit,
                live=live,
                live_data_fresh=bool(context.get("live_data_fresh", False)),
                live_sample_invalid=bool(
                    context.get("live_sample_invalid", True)
                ),
                charger_status=status,
                c_data=box,
                grid_max_amps=cfg.get("grid_max_amps"),
            )
            contract = box.get("_openwb_pro_one_phase_cap")
            contract_current = bool(
                isinstance(contract, dict)
                and contract.get("active") is True
                and contract.get("cycle_token") == cycle_token
            )

        if not contract_current:
            # Keine aktuelle Messbindung: niemals einen Nutzerwert >20 A
            # direkt an die Hardware durchreichen.
            contract = wallbox_phase_balancing.openwb_pro_one_phase_current_cap(
                user_limit_a=_openwb_pro_one_phase_user_limit(
                    cfg,
                    c_id if c_id is not None else box.get("id", 1),
                ),
                charger_limit_a=charger_limit,
                grid_max_amps=cfg.get("grid_max_amps"),
                grid_max_phase_amps=_phase_config_vector(
                    cfg,
                    "grid_max_amps",
                ),
                reserve_a=cfg.get("grid_wallbox_reserve_amps", 2.0),
                reserve_phase_amps=_phase_config_vector(
                    cfg,
                    "grid_wallbox_reserve_amps",
                ),
                data_valid=False,
                data_fresh=False,
                hard_rms_current_measurement=False,
                grid_phase=cfg.get(
                    f"wb{int(c_id or box.get('id', 1) or 1)}_grid_phase"
                ),
                fallback_cap_a=20.0,
                min_amp=6.0,
                require_phase_specific_grid_limit=True,
            )
            contract.update(
                {
                    "active": True,
                    "charger_phases": 1,
                    "cycle_token": cycle_token,
                    "requested_amp": requested,
                    "applied_amp": min(
                        requested,
                        float(contract.get("cap_amp", 0.0) or 0.0),
                    ),
                    "measurement_basis": "fallback_no_current_cycle_measurement",
                    "hard_rms_current_measurement": False,
                }
            )
            box["_openwb_pro_one_phase_cap"] = contract

    cap_amp = max(0.0, _cfg_float((contract or {}).get("cap_amp"), 0.0))
    applied = min(requested, cap_amp)
    gate = {
        "authoritative": True,
        "active": True,
        "method": method,
        "requested_amp": requested,
        "applied_amp": applied,
        "cap_amp": cap_amp,
        "phase_count": 1,
        "phase_source": phase_source,
        "dynamic": bool((contract or {}).get("dynamic", False)),
        "reason": str((contract or {}).get("reason") or "fallback"),
    }
    box["_openwb_pro_one_phase_output_gate"] = gate
    if applied < 6.0:
        cmd["amp"] = 0.0
        gate["forced_zero"] = True
        logger.warning(
            "WB%s openWB-Pro-1p-Ausgang setzt %s auf 0A: %.1fA angefordert, "
            "kein sicherer Phasenstrom verfügbar.",
            c_id if c_id is not None else box.get("id", "?"),
            method,
            requested,
        )
        return cmd, True
    if applied < requested:
        cmd["amp"] = applied
        gate["limited"] = True
    return cmd, True


_VEHICLE_CURRENT_OUTPUT_METHODS = frozenset({
    "set_amp_and_state",
    "set_amp_sonnenmodus",
    "set_amp_autonomous_solar",
    "set_current",
    "set_direct_current",
})


def _apply_vehicle_current_output_gate(c_data, command, *, c_id=None):
    """Deckele einen Strombefehl mit dem zyklusaktuellen OBC-Vertrag.

    Der Gate ist bewusst wirkungslos, wenn Fahrzeugidentität, Phase oder
    bestätigte Profilgrenze fehlen. Alle Ladepunkt-, Kabel-, Nutzer-, Netz- und
    Hausanschlussgrenzen bleiben davon unabhängig davor beziehungsweise danach
    wirksam.
    """

    box = c_data if isinstance(c_data, dict) else {}
    cmd = dict(command) if isinstance(command, dict) else {}
    method = str(cmd.get("method") or cmd.get("kind") or "").strip()
    try:
        requested = max(0.0, float(cmd.get("amp", 0.0) or 0.0))
    except (TypeError, ValueError):
        requested = 0.0
    stop_command = bool(
        str(cmd.get("kind") or "").strip() == "stop"
        and cmd.get("_canonical_stop_command") is True
        and cmd.get("_control_guard_checked") is True
    )
    contract = box.get("_vehicle_current_capability")
    contract = dict(contract) if isinstance(contract, dict) else {}
    cycle_bound = bool(
        contract.get("cycle_token")
        and contract.get("cycle_token") == box.get("_wallbox_cycle_token")
    )
    cap_active = bool(
        contract.get("active", False)
        and contract.get("identity_confirmed", False)
        and cycle_bound
    )
    gate = {
        "contract": "vehicle_current_output_gate_v1",
        "authoritative": True,
        "active": False,
        "method": method,
        "requested_amp": requested,
        "applied_amp": requested,
        "phase_count": int(contract.get("phase_count", 0) or 0),
        "cap_amp": contract.get("cap_amp"),
        "cap_source": str(contract.get("cap_source") or "none"),
        "reason": str(contract.get("reason") or "vehicle_cap_not_active"),
        "session_latched": bool(contract.get("session_latched", False)),
    }
    box["_vehicle_current_output_gate"] = gate
    if (
        method not in _VEHICLE_CURRENT_OUTPUT_METHODS
        or requested <= 0.0
        or stop_command
        or not cap_active
    ):
        if stop_command:
            gate["reason"] = "stop_command_unchanged"
        return cmd, True

    try:
        cap_amp = float(contract.get("cap_amp"))
    except (TypeError, ValueError):
        cap_amp = 0.0
    if not math.isfinite(cap_amp) or cap_amp < 6.0:
        gate["reason"] = "vehicle_cap_invalid"
        return cmd, True

    applied = min(requested, cap_amp)
    cmd["amp"] = applied
    gate.update({
        "active": True,
        "applied_amp": applied,
        "limited": bool(applied < requested),
        "reason": "confirmed_session_vehicle_phase_cap",
    })
    return cmd, True


def _apply_driver_max_current_output_gate(c_data, command, *, charger=None, c_id=None):
    """Begrenze den finalen Stromauftrag erneut an der Treibergrenze."""

    box = c_data if isinstance(c_data, dict) else {}
    cmd = dict(command or {})
    method = str(cmd.get("method") or cmd.get("kind") or "").strip()
    gate = {
        "contract": "wallbox_driver_max_current_output_gate_v1",
        "authoritative": True,
        "method": method,
        "active": False,
        "limited": False,
    }
    if method not in _EFFECTIVE_CURRENT_METHODS:
        gate["reason"] = "not_current_output"
        box["_driver_max_current_output_gate"] = gate
        return cmd, True
    field = "max_amp" if "max_amp" in cmd and "amp" not in cmd else "amp"
    requested = max(0.0, _cfg_float(cmd.get(field), 0.0))
    maximum = _cfg_float(getattr(charger, "max_amp", 16.0), 16.0)
    if not math.isfinite(maximum):
        maximum = 16.0
    maximum = max(6.0, min(32.0, maximum))
    applied = requested if requested < 0.5 else max(6.0, min(maximum, requested))
    cmd[field] = applied
    gate.update({
        "active": True,
        "requested_amp": requested,
        "applied_amp": applied,
        "max_amp": maximum,
        "limited": bool(applied < requested),
        "reason": "driver_bound_limit",
    })
    box["_driver_max_current_output_gate"] = gate
    return cmd, True


def _bind_admitted_actuator_intent(c_data, command, *, c_id=None):
    """Projiziere den tatsächlich zugelassenen Ausgang als typisierten Intent.

    Die Funktion blockiert in Welle 1 noch keinen Legacy-Pfad. Sie markiert
    aber, wenn die bestehende Ledger-Ausnahme im selben Zyklus mehr als einen
    normalen Aktorauftrag zulässt. Ein späterer Notfall darf einen normalen
    Auftrag weiterhin typisiert verdrängen.
    """

    box = c_data if isinstance(c_data, dict) else {}
    capability = WallboxCapability.from_mapping(box.get("_wallbox_capability"))
    decision_payload = box.get("_decision_payload")
    decision_payload = decision_payload if isinstance(decision_payload, dict) else {}
    inputs = decision_payload.get("inputs")
    inputs = inputs if isinstance(inputs, dict) else {}
    method = str(command.get("method") or command.get("kind") or "").strip()
    authorized_output_cap_w = None
    if method in _EFFECTIVE_CURRENT_METHODS:
        watt_gate = box.get("_authorized_wallbox_watt_output_gate")
        watt_gate = watt_gate if isinstance(watt_gate, dict) else {}
        if watt_gate.get("strict_watt_cap") is not False:
            applied_amp = max(
                0.0,
                _cfg_float(
                    command.get("max_amp", command.get("amp", 0.0)),
                    0.0,
                ),
            )
            output_phases = _valid_phase_count(watt_gate.get("phases"), 0)
            if not output_phases:
                output_phases = _authorized_wallbox_output_phase_count(
                    box,
                    command,
                )
            authorized_output_cap_w = applied_amp * 230.0 * output_phases
    intent = ActuatorIntent.from_command(
        command,
        wb_id=c_id if c_id is not None else box.get("id", 0),
        cycle_token=box.get("_wallbox_cycle_token"),
        decision_allowed_w=inputs.get("allowed_w"),
        authorized_output_cap_w=authorized_output_cap_w,
        capability=capability,
        source="wallbox_driver_dispatch",
        stage="admitted",
    ).as_dict()
    previous = box.get("_admitted_actuator_intent")
    previous = previous if isinstance(previous, dict) else {}
    same_cycle = bool(
        previous
        and str(previous.get("cycle_token") or "")
        and str(previous.get("cycle_token") or "")
        == str(intent.get("cycle_token") or "")
    )
    previous_output = bool(previous.get("wire_output_expected", False))
    current_output = bool(intent.get("wire_output_expected", False))
    emergency_preemption = bool(
        same_cycle
        and previous_output
        and current_output
        and intent.get("emergency") is True
    )
    multiple_normal_intent = bool(
        same_cycle
        and previous_output
        and current_output
        and not emergency_preemption
    )
    intent["legacy_multiple_normal_intent_detected"] = multiple_normal_intent
    intent["emergency_preemption"] = emergency_preemption
    if multiple_normal_intent:
        intent["previous_intent"] = {
            key: previous.get(key)
            for key in (
                "action",
                "method",
                "target_current_a",
                "target_phases",
                "reason",
            )
        }
    box["_admitted_actuator_intent"] = intent
    audit = box.get("_admitted_actuator_intent_audit")
    audit = list(audit) if isinstance(audit, list) else []
    audit.append(dict(intent))
    box["_admitted_actuator_intent_audit"] = audit[-16:]
    return intent


def _execute_wallbox_driver_command(c_data, command, c_id=None, reason=""):
    """Einzelne Kante für Schreibzugriffe des Wallbox-Treibers.

    Der Aufrufer besitzt die Regelentscheidung. Dieser Helfer dispatcht nur die
    bereits gewählte Treibermethode mit den bereits gewählten Parametern. An
    dieser letzten I/O-Kante ist ein gültiges äußeres Manager-Zyklustoken Pflicht.
    """
    box = c_data if isinstance(c_data, dict) else {}
    cmd = command if isinstance(command, dict) else {}
    previous_command_receipt = box.get("_last_executed_command")
    raw_method = str(cmd.get("method") or cmd.get("kind") or "").strip()
    raw_reason = str(cmd.get("reason", reason or raw_method) or raw_method)
    box["_wallbox_driver_dispatch_contract"] = {
        "contract": "wallbox_driver_dispatch_contract_v1",
        "method": raw_method,
        "reason": raw_reason,
        "cycle_token": str(box.get("_wallbox_cycle_token") or ""),
        "wire_attempted": False,
        "attempt_ts": 0.0,
    }
    requested_amp_input = _cfg_float(
        cmd.get("max_amp", cmd.get("amp", 0.0)),
        0.0,
    )
    charger = box.get("charger")
    if charger is None:
        charger = cmd.get("charger")
    if charger is None:
        return False
    if bool(
        box.get("_physical_output_blocked", False)
        or getattr(charger, "_physical_output_blocked", False)
    ):
        blocker = str(
            box.get("_physical_output_block_reason")
            or getattr(charger, "_physical_output_block_reason", "")
            or "physical_output_identity_blocked"
        )
        box["_wallbox_driver_dispatch_contract"].update({
            "blocked": True,
            "blocker": blocker,
            "wire_attempted": False,
        })
        return False
    controller_admission = _charger_controller.authorize_driver_command(cmd)
    box["_charger_controller_output_gate"] = {
        "authoritative": True,
        "valid": bool(controller_admission.valid),
        "reason": controller_admission.reason,
        "error": controller_admission.error,
    }
    if not controller_admission.valid:
        logger.warning(
            "WB%s Controller blockiert unbekannten Treiberbefehl (%s).",
            c_id if c_id is not None else "?",
            controller_admission.error or "missing_driver_method",
        )
        return False
    cmd = controller_admission.command
    method = str(cmd.get("method") or cmd.get("kind") or "").strip()
    kind = str(cmd.get("kind") or method or "driver_command").strip()
    command_reason = str(cmd.get("reason", reason or kind) or kind)
    openwb_pro_internal = bool(cmd.get("_openwb_pro_sequence_internal", False))
    existing_session_hold = bool(
        cmd.get("_openwb_pro_existing_session_hold", False)
    )
    openwb_pro_mode0_scope = bool(
        openwb_pro_session.is_openwb_pro_charger(charger)
        and command_gate.is_default_release_allowed(charger)
        and str(getattr(charger, "_command_gate_release_type", "") or "")
        == "user_off_handoff"
    )
    if openwb_pro_mode0_scope and not _openwb_pro_mode0_output_binding_matches(
        box,
        cmd,
    ):
        box["_wallbox_driver_dispatch_contract"].update({
            "blocked": True,
            "blocker": "openwb_pro_mode0_release_binding_mismatch",
            "wire_attempted": False,
        })
        return False

    if (
        method == "emergency_stop"
        and e3dc_session.is_e3dc_native_charger(charger)
        and not _e3dc_native_verified_active_charge(box)
    ):
        # E3DC verwendet auch für NOT-AUS eine Toggle-Flanke. Ohne frischen,
        # plausiblen Ladebeleg könnte derselbe Ausgang eine stehende Wallbox
        # starten. Absolute Stopbefehle anderer Treiber bleiben unberührt.
        box["_wallbox_driver_dispatch_contract"].update({
            "blocked": True,
            "blocker": "native_emergency_stop_without_verified_active_charge",
            "wire_attempted": False,
        })
        return False

    # Observe-only ist ein reiner, autorisierter NOOP. Er darf weder einen
    # Strom-/Budgetvertrag noch HA- oder Ledger-Autorität benötigen, weil an
    # dieser Kante garantiert kein Treiber- oder Hardwareausgang stattfindet.
    if _wallbox_driver_observe_only_noop(box, cmd):
        if not _wallbox_command_guard_allows(
            box,
            cmd,
            c_id=c_id,
            reason=command_reason,
        ):
            return False
        if not _wallbox_command_guard_is_observe_only_noop(box, cmd):
            return False
        box["_wallbox_driver_dispatch_contract"].update({
            "noop": True,
            "decision": "observe_only_noop",
            "wire_attempted": False,
        })
        _bind_admitted_actuator_intent(box, cmd, c_id=c_id)
        return True

    if not _apply_native_e3dc_floor_output_authority_gate(
        box,
        cmd,
        charger=charger,
        c_id=c_id,
        stage="early",
    ):
        return False

    positive_current = method in (
        "set_amp_and_state",
        "set_current",
        "set_direct_current",
    ) and _cfg_float(cmd.get("amp"), 0.0) > 0.0
    priority_stop_latch = box.get(
        "_priority_forced_stop_output_latch"
    )
    priority_stop_same_cycle = bool(
        isinstance(priority_stop_latch, dict)
        and priority_stop_latch.get("active") is True
        and str(priority_stop_latch.get("cycle_token") or "")
        and str(priority_stop_latch.get("cycle_token") or "")
        == str(box.get("_wallbox_cycle_token") or "")
    )
    priority_positive_current = bool(
        method in _EFFECTIVE_CURRENT_METHODS
        and _cfg_float(
            cmd.get("max_amp", cmd.get("amp", 0.0)),
            0.0,
        ) > 0.0
        and not _canonical_guarded_stop_command(cmd)
    )
    if priority_stop_same_cycle and (
        priority_positive_current
        or method in (
            "set_phases",
            "trigger_cp_interrupt",
            "cp_interrupt",
        )
    ):
        box["_wallbox_driver_dispatch_contract"].update({
            "blocked": True,
            "blocker": "priority_forced_stop_output_latch",
            "wire_attempted": False,
        })
        return False
    if openwb_pro_session.is_openwb_pro_charger(charger):
        if _openwb_pro_phase_generation_cycle_blocked(box) and (
            positive_current
            or method in (
                "set_phases",
                "trigger_cp_interrupt",
                "cp_interrupt",
            )
        ):
            # Eine alte Lease-/Recovery-Generation wurde in diesem Zyklus
            # gerade erst terminalisiert. Nur Safety-Null bleibt zulässig;
            # positiver Strom, Phase und CP gehören frühestens zum Folgezyklus.
            box["_wallbox_driver_dispatch_contract"].update({
                "blocked": True,
                "blocker": "same_cycle_phase_generation_block",
                "wire_attempted": False,
            })
            return False
        same_cycle_recovery_terminal = bool(
            str(box.get("_wallbox_cycle_token") or "")
            and str(box.get("_phase_output_recovery_cycle_token") or "")
            == str(box.get("_wallbox_cycle_token") or "")
            and box.get("_phase_output_recovery_cycle_resolved") is True
        )
        if same_cycle_recovery_terminal and (
            positive_current
            or method in (
                "set_phases",
                "trigger_cp_interrupt",
                "cp_interrupt",
            )
        ):
            # Der Readback terminalisiert nur die alte Ausgangsgeneration.
            # Ein neuer Strom-, Phasen- oder CP-Ausgang gehört frühestens in
            # den nächsten vollständigen Managerzyklus; 0-A-Safety-Ausgänge
            # bleiben davon unberührt.
            box["_wallbox_driver_dispatch_contract"].update({
                "blocked": True,
                "blocker": "same_cycle_phase_recovery_terminal",
                "wire_attempted": False,
            })
            return False
        cp_output_edge = method in ("trigger_cp_interrupt", "cp_interrupt")
        if cp_output_edge:
            _, connected_edge = _openwb_pro_fresh_connected_output_status(
                box,
                charger,
                action="start_cp_interrupt",
                c_id=c_id,
            )
            if not connected_edge:
                return False

    recovery = box.get("_openwb_pro_phase_recovery_hold")
    recovery_active = isinstance(recovery, dict) and recovery.get("active")
    restart_probe = box.get("_openwb_pro_phase_preoutput_restart_probe")
    if (
        isinstance(restart_probe, dict)
        and restart_probe.get("active") is True
        and (
            (
                method in _EFFECTIVE_CURRENT_METHODS
                and _cfg_float(cmd.get("amp"), 0.0) > 0.0
            )
            or method in ("set_phases", "trigger_cp_interrupt", "cp_interrupt")
        )
    ):
        box["_wallbox_driver_dispatch_contract"].update({
            "blocked": True,
            "blocker": "process_restart_preoutput_readback_required",
            "wire_attempted": False,
        })
        return False
    session_persistence_recovery = box.get(
        "_openwb_pro_session_persistence_recovery_hold"
    )
    session_persistence_recovery_active = bool(
        isinstance(session_persistence_recovery, dict)
        and session_persistence_recovery.get("active")
    )
    if session_persistence_recovery_active and (
        positive_current
        or method in (
            "set_phases",
            "trigger_cp_interrupt",
            "cp_interrupt",
        )
    ):
        logger.error(
            "WB%s Ausgang im Session-Persistenz-Recovery-Hold blockiert "
            "(%s, %s).",
            c_id if c_id is not None else box.get("id", "?"),
            method,
            session_persistence_recovery.get(
                "reason",
                "session_persistence_restore_failed",
            ),
        )
        return False
    recovery_readback_probe = bool(
        recovery_active
        and method == "set_phases"
        and openwb_pro_session.is_openwb_pro_charger(charger)
    )
    if recovery_active and (
        positive_current
        or method in ("set_phases", "trigger_cp_interrupt", "cp_interrupt")
    ) and not recovery_readback_probe:
        logger.error(
            "WB%s Ausgang im Phasen-Recovery-Hold blockiert (%s, %s).",
            c_id if c_id is not None else box.get("id", "?"),
            method,
            recovery.get("reason", "phase_recovery_hold"),
        )
        return False

    cmd, effective_current_allowed = _apply_effective_current_output_gate(
        box,
        cmd,
        c_id=c_id,
    )
    if not effective_current_allowed:
        return False

    cmd, edge_decision = _guard_e3dc_native_driver_edge(
        box,
        cmd,
        charger=charger,
        c_id=c_id,
        reason=command_reason,
    )
    if not edge_decision.get("execute", True):
        return False

    cmd, allocation_allowed = _apply_multi_allocation_output_gate(
        box,
        cmd,
        c_id=c_id,
    )
    if not allocation_allowed:
        return False
    cmd, watt_budget_allowed = _apply_authorized_wallbox_watt_output_gate(
        box,
        cmd,
        c_id=c_id,
    )
    if not watt_budget_allowed:
        return False
    cmd, peak_shaving_allowed = _apply_peak_shaving_output_gate(
        box,
        cmd,
        c_id=c_id,
    )
    if not peak_shaving_allowed:
        return False
    cmd, phase_cap_allowed = _apply_openwb_pro_one_phase_output_gate(
        box,
        cmd,
        charger=charger,
        c_id=c_id,
    )
    if not phase_cap_allowed:
        return False

    def _cmd_int(name, default=0):
        try:
            return int(round(float(cmd.get(name, default) or 0)))
        except Exception:
            return int(default)

    def _cmd_amp(name="amp", default=0.0):
        try:
            return float(cmd.get(name, default) or 0.0)
        except Exception:
            return float(default)

    native_wire_receipt_before = {}
    native_wire_receipt_after = {}
    native_dispatch_outcome_before = {}
    native_dispatch_outcome_after = {}

    def _remember_executed_command():
        if not isinstance(c_data, dict):
            return
        try:
            amp_value = (
                cmd.get("amp", 0.0)
                if method == "set_amp_and_state"
                else (cmd.get("max_amp") or cmd.get("amp") or 0.0)
            )
            amp = float(amp_value or 0.0)
        except Exception:
            amp = 0.0
        try:
            target_phases = int(cmd.get("target_phases", cmd.get("phases", 0)) or 0)
        except Exception:
            target_phases = 0
        executed_ts = time.time()
        before_wire_seq = int(native_wire_receipt_before.get("seq", 0) or 0)
        after_wire_seq = int(native_wire_receipt_after.get("seq", 0) or 0)
        wire_receipt_new = bool(
            native_wire_receipt_after
            and after_wire_seq == before_wire_seq + 1
        )
        start_hold_binding = {}
        start_hold_request = c_data.get(wallbox_start_hold.STATE_KEY)
        if (
            method in {
                "set_amp_and_state",
                "set_current",
                "set_direct_current",
                "set_amp_sonnenmodus",
                "set_amp_autonomous_solar",
            }
            and isinstance(start_hold_request, dict)
        ):
            reservation_id = str(
                start_hold_request.get("reservation_id") or ""
            )
            plug_session_id = str(
                start_hold_request.get("plug_session_id") or ""
            )
            current_session_id = str(
                c_data.get(wallbox_start_hold.SESSION_KEY)
                or c_data.get("_openwb_pro_plug_session_id")
                or ""
            )
            request_cycle_token = str(
                start_hold_request.get("request_cycle_token") or ""
            )
            current_cycle_token = str(
                c_data.get("_wallbox_cycle_token") or ""
            )
            if (
                start_hold_request.get("schema_version")
                == wallbox_start_hold.REQUEST_SCHEMA
                and str(start_hold_request.get("stage") or "")
                == "await_receipt"
                and reservation_id
                and plug_session_id
                and plug_session_id == current_session_id
                and request_cycle_token
                and request_cycle_token == current_cycle_token
            ):
                start_hold_binding = {
                    "start_hold_reservation_id": reservation_id,
                    "start_hold_plug_session_id": plug_session_id,
                }
        receipt = {
            "method": method,
            "amp": amp,
            "requested_amp": requested_amp_input,
            "forced_zero": bool(requested_amp_input >= 6.0 and amp < 6.0),
            "target_phases": target_phases,
            "force_state": cmd.get("force_state"),
            "wire_receipt_contract": str(
                native_wire_receipt_after.get("contract") or ""
            ),
            "wire_receipt_seq": after_wire_seq,
            "wire_receipt_ts": _cfg_float(
                native_wire_receipt_after.get("ts"),
                0.0,
            ),
            "wire_receipt_new": wire_receipt_new,
            "wire_abort_flag": int(
                native_wire_receipt_after.get("abort_flag", 0) or 0
            ),
            "wire_heartbeat": bool(
                native_wire_receipt_after.get("heartbeat", False)
            ),
            "stop_edge_issued": bool(
                wire_receipt_new
                and native_wire_receipt_after.get("stop_edge_issued") is True
            ),
            "reason": command_reason,
            "cycle_token": c_data.get("_wallbox_cycle_token"),
            # Derselbe Primärschlüssel wird auch vom Owner- und
            # Defizitvertrag gelesen. Damit erhalten nicht nur openWB Pro,
            # sondern ebenso native und weitere Treiber einen gebundenen
            # Wire-Receipt ihrer aktuellen Stecksession.
            "plug_session_id": _wallbox_group_deficit_current_session_id(
                c_data
            ),
            "ts": executed_ts,
        }
        receipt.update(start_hold_binding)
        c_data["_last_executed_command"] = receipt
        if start_hold_binding:
            wallbox_start_hold.commit_receipt(
                c_data,
                receipt,
                now_ts=executed_ts,
            )
        if c_data.get("_bev_full_blocked") is True and (
            amp >= 6.0
            or method in (
                "set_phases",
                "trigger_cp_interrupt",
                "cp_interrupt",
                "release_to_default",
                "release_to_e3dc",
            )
        ):
            # Eine spätere reale Leistungsaufnahme ist dann nicht mehr als
            # externer Fahrzeugneustart beweisbar. Der Marker bleibt bis zur
            # expliziten Latch-Freigabe erhalten.
            c_data["_charge_end_manager_output_after_latch"] = True
        if (
            amp >= 6.0
            and method in ("set_amp_and_state", "set_current", "set_direct_current")
            and openwb_pro_session.is_openwb_pro_charger(charger)
            and not existing_session_hold
        ):
            phase_restart = box.get("_openwb_pro_phase_restart_authorized")
            if isinstance(phase_restart, dict) and phase_restart.get("active"):
                box.pop("_openwb_pro_phase_restart_authorized", None)
            connected, charging, real_power_w = _openwb_pro_status_connected_idle(
                box,
                charger,
            )
            if connected and not charging and real_power_w <= 500.0:
                plug_session_id = str(box.get("_openwb_pro_plug_session_id") or "")
                if not plug_session_id:
                    plug_session_id = "wb%s:%d" % (
                        c_id if c_id is not None else box.get("id", 0),
                        # Die Stecksession wird auch als fail-closed Zeitgrenze
                        # für sitzungsgebundene SoC-Anker verwendet. Deshalb
                        # muss die Kennung eine Epochzeit und keine nur lokal
                        # interpretierbare monotone Prozessuhr enthalten.
                        time.time_ns(),
                    )
                    box["_openwb_pro_plug_session_id"] = plug_session_id
                if (
                    str(box.get("_openwb_pro_start_current_session_id") or "")
                    != plug_session_id
                    or float(box.get("_openwb_pro_start_current_issued_ts", 0.0) or 0.0) <= 0.0
                ):
                    box["_openwb_pro_start_current_session_id"] = plug_session_id
                    box["_openwb_pro_start_current_issued_ts"] = executed_ts
                    box["_openwb_pro_start_wakeup_receipt"] = {}
                    box["_openwb_pro_start_wakeup_count"] = 0
                    if not _save_wallbox_phase_state([box]):
                        box["_openwb_pro_start_cp_persistence_blocked"] = True
                        logger.error(
                            "WB%s openWB Pro Startbeleg nicht persistierbar; "
                            "automatische CP-Wakeups werden fail-closed gesperrt.",
                            c_id if c_id is not None else box.get("id", "?"),
                        )
                    else:
                        box.pop("_openwb_pro_start_cp_persistence_blocked", None)
        # Phasenabsicht/-ACK und Wiederanlauffreigabe bleiben crashsicher, bis
        # frisches Laden auf der Zielphase die Reservierung abgeschlossen hat.
        # Erfolgreiches Senden allein belegt keine Anwendung durch das Gerät.

    def _return_executed(result):
        ok = bool(result)
        if ok:
            _remember_executed_command()
        return ok

    if openwb_pro_session.is_openwb_pro_charger(charger) and not openwb_pro_internal:
        if method in ("trigger_cp_interrupt", "cp_interrupt"):
            now_guard_ts = time.time()
            status_now = _openwb_pro_driver_status(box, charger)
            status_power_w = max(
                _cfg_float(status_now.get("real_power_w"), 0.0),
                _cfg_float(status_now.get("phase_power_sum_w"), 0.0),
                _cfg_float(status_now.get("power_w"), 0.0),
            )
            if _openwb_pro_phase_wait_active(
                box,
                status_now,
                now_guard_ts,
                stable_hw_power_w=status_power_w,
            ):
                return False
        if (
            method in ("set_amp_and_state", "set_current", "set_direct_current")
            and _cmd_amp("amp") >= 6.0
            and not existing_session_hold
        ):
            wakeup_allowed_after = float(box.get("_openwb_pro_start_wakeup_allowed_after", 0.0) or 0.0)
            if wakeup_allowed_after > time.time():
                status_now = _openwb_pro_driver_status(box, charger)
                status_power_w = max(
                    _cfg_float(status_now.get("real_power_w"), 0.0),
                    _cfg_float(status_now.get("phase_power_sum_w"), 0.0),
                    _cfg_float(status_now.get("power_w"), 0.0),
                )
                if status_power_w <= 500.0:
                    return False
            sequence = box.get("_openwb_pro_phase_sequence")
            sequence_stage = str(sequence.get("stage") or "") if isinstance(sequence, dict) else ""
            if isinstance(sequence, dict) and sequence and sequence_stage not in ("", "ready"):
                return False
        if method == "set_phases":
            return bool(_openwb_pro_phase_sequence_step(
                box,
                cmd,
                charger=charger,
                c_id=c_id,
                reason=command_reason,
            ))
        if (
            method in ("set_amp_and_state", "set_current", "set_direct_current")
            and _cmd_amp("amp") >= 6.0
            and not existing_session_hold
        ):
            if not _openwb_pro_start_wakeup_ready(
                box,
                cmd,
                charger=charger,
                c_id=c_id,
                reason=command_reason,
            ):
                return False
            _, connected_edge = _openwb_pro_fresh_connected_output_status(
                box,
                charger,
                action="start_current",
                c_id=c_id,
            )
            if not connected_edge:
                return False

    # Das openWB-Pro-Wakeup-Orakel darf den Befehl patchen. Deshalb werden der
    # post-Policy-Stromvertrag und die unveränderlichen Budgetdeckel direkt vor
    # dem allgemeinen Command-Guard ein zweites Mal angewendet.
    cmd, effective_current_allowed = _apply_effective_current_output_gate(
        box,
        cmd,
        c_id=c_id,
    )
    if not effective_current_allowed:
        return False
    cmd, allocation_allowed = _apply_multi_allocation_output_gate(
        box,
        cmd,
        c_id=c_id,
    )
    if not allocation_allowed:
        return False
    cmd, watt_budget_allowed = _apply_authorized_wallbox_watt_output_gate(
        box,
        cmd,
        c_id=c_id,
    )
    if not watt_budget_allowed:
        return False
    cmd, peak_shaving_allowed = _apply_peak_shaving_output_gate(
        box,
        cmd,
        c_id=c_id,
    )
    if not peak_shaving_allowed:
        return False
    cmd, phase_cap_allowed = _apply_openwb_pro_one_phase_output_gate(
        box,
        cmd,
        charger=charger,
        c_id=c_id,
    )
    if not phase_cap_allowed:
        return False

    cmd, vehicle_cap_allowed = _apply_vehicle_current_output_gate(
        box,
        cmd,
        c_id=c_id,
    )
    if not vehicle_cap_allowed:
        _discard_wallbox_command_guard_pending(box)
        return False
    cmd, driver_limit_allowed = _apply_driver_max_current_output_gate(
        box,
        cmd,
        charger=charger,
        c_id=c_id,
    )
    if not driver_limit_allowed:
        _discard_wallbox_command_guard_pending(box)
        return False

    # Alle Session-, Wake-up- und Deckelpfade dürfen den Befehlsinhalt
    # verändern. Die Floor-Autorität liest deshalb Methodik und Strom aus dem
    # endgültigen Befehl erneut und sitzt vor HA, Command-Guard, Owner-Ledger
    # und jedem Treiber-/Wire-Ausgang.
    method = str(cmd.get("method") or cmd.get("kind") or "").strip()
    kind = str(cmd.get("kind") or method or "driver_command").strip()
    command_reason = str(
        cmd.get("reason", reason or kind) or kind
    )
    if not _apply_native_e3dc_floor_output_authority_gate(
        box,
        cmd,
        charger=charger,
        c_id=c_id,
        stage="final",
    ):
        return False

    ha_admission = evaluate_writer_admission()
    box["_ha_writer_admission"] = dict(ha_admission)
    if ha_admission.get("allowed") is not True:
        box["_wallbox_driver_dispatch_contract"].update({
            "blocked": True,
            "blocker": "ha_writer_admission",
            "block_reason": str(
                ha_admission.get("reason") or "ha_writer_admission_blocked"
            ),
        })
        admission_sig = (
            str(ha_admission.get("reason") or ""),
            str(ha_admission.get("mode") or ""),
        )
        if box.get("_ha_writer_admission_last_block") != admission_sig:
            logger.warning(
                "WB%s Hardwareausgang durch HA-Rollenvertrag blockiert: %s (Rolle=%s).",
                c_id if c_id is not None else box.get("id", "?"),
                admission_sig[0] or "unbekannt",
                admission_sig[1] or "nicht gebunden",
            )
            box["_ha_writer_admission_last_block"] = admission_sig
        _discard_wallbox_command_guard_pending(box)
        return False
    box.pop("_ha_writer_admission_last_block", None)

    if method == "set_phases" and (
        charger.__class__.__name__ == "E3DCMultiConnectCharger"
        or str(getattr(charger, "driver_variant", "") or "") == "e3dc_multi_connect"
    ):
        box.pop("_wallbox_phase_transition_reservation", None)
        box.pop("_phase_transition_grant", None)
        logger.error(
            "E3DC Multi Connect Phasenumschaltung gesperrt: "
            "CP-Readback und 480-s-Unterbrechungsvertrag sind nicht belegt."
        )
        return False

    if method == "stop":
        if not _wallbox_command_guard_allows(box, cmd, c_id=c_id, reason=command_reason):
            return False
        if _wallbox_command_guard_is_observe_only_noop(box, cmd):
            return True
        return _send_wallbox_stop_command(
            box,
            c_id=c_id,
            reason=command_reason,
            _guard_checked=True,
            stop_authority=cmd.get("stop_authority"),
            require_typed_stop_authority=True,
        )

    if not _wallbox_command_guard_allows(box, cmd, c_id=c_id, reason=command_reason):
        return False
    if _wallbox_command_guard_is_observe_only_noop(box, cmd):
        return True
    if not _seal_autonomous_solar_driver_command(box, cmd):
        box["_wallbox_driver_dispatch_contract"].update({
            "blocked": True,
            "blocker": "autonomous_solar_output_contract_not_current",
            "wire_attempted": False,
        })
        _discard_wallbox_command_guard_pending(box)
        return False

    native_floor_marker = cmd.get(
        "_native_e3dc_floor_start_edge_marker"
    )
    if isinstance(native_floor_marker, dict) and native_floor_marker:
        release = _native_e3dc_floor_retry_not_released_contract(
            box,
            source="driver_executor_marker_failsafe",
        )
        box[
            "_native_e3dc_floor_zero_anchor_retry_release"
        ] = dict(release)
        box["_wallbox_driver_dispatch_contract"].update({
            "blocked": True,
            "blocker": "native_floor_zero_anchor_retry_not_released",
            "release_status": "EVIDENCE_LIMIT",
            "wire_attempted": False,
        })
        _discard_wallbox_command_guard_pending(box)
        return False

    target_phases = _cmd_int("phases", _cmd_int("target_phases", 0)) if method == "set_phases" else 0
    status_before = box.get("last_valid") if isinstance(box.get("last_valid"), dict) else {}
    if method == "take_control" and e3dc_session.is_e3dc_native_charger(charger):
        # take_control() bereitet ausschließlich den lokalen WBchar6-Modus vor.
        # Es sendet selbst keinen Hardwarebefehl und darf deshalb den einzigen
        # Ausgangsslot des Managerzyklus nicht vor dem Sollstrom verbrauchen.
        _wallbox_command_executor.execute(charger, cmd, c_id=c_id)
        prepared = getattr(charger, "sonnenmodus", None) is False
        box["_wallbox_output_preamble"] = {
            "method": method,
            "reason": command_reason,
            "prepared": bool(prepared),
            "ts": time.time(),
        }
        if prepared:
            _remember_executed_command()
            _commit_wallbox_command_guard_after_receipt(
                box,
                cmd,
                previous_receipt=previous_command_receipt,
            )
        else:
            _discard_wallbox_command_guard_pending(box)
        return bool(prepared)
    if method == "set_phases" and not status_before:
        status_before = _openwb_pro_driver_status(box, charger)
    if method == "set_phases" and not openwb_pro_internal and not openwb_pro_session.is_openwb_pro_charger(charger):
        reservation = box.get("_wallbox_phase_transition_reservation")
        reservation_created = False
        if not isinstance(reservation, dict) or not reservation.get("active"):
            reservation = begin_phase_transition_reservation(
                box,
                target_phases,
                status=status_before,
                now_ts=time.time(),
                charger_max_amp=getattr(charger, "max_amp", box.get("max_amp", 16)),
                source="%s_phase_command" % charger.__class__.__name__,
                reason=command_reason,
                wb_id=c_id if c_id is not None else box.get("id", 0),
                restart_amp=max(
                    6.0,
                    _cfg_float(box.get("current_set_amp"), 0.0),
                    _cfg_float(status_before.get("offered_current_raw"), 0.0),
                    _cfg_float(status_before.get("evse_current"), 0.0),
                    _cfg_float(status_before.get("amp"), 0.0),
                ),
                current_step_amp=_current_step_amp_for_charger(charger, default=1.0),
            )
            reservation_created = bool(reservation)
        if reservation_created:
            _save_wallbox_phase_state([box])
        grant = box.get("_phase_transition_grant")
        if isinstance(grant, dict):
            reservation = wallbox_phase_transition.apply_grant(box, grant, now_ts=time.time())
        if not wallbox_phase_transition.grant_is_sufficient(reservation):
            if not wallbox_phase_transition.grant_recovery_blocked(
                reservation
            ):
                wallbox_phase_transition.set_stage(
                    box,
                    "await_budget",
                    now_ts=time.time(),
                )
            _discard_wallbox_command_guard_pending(box)
            return False
        wallbox_phase_transition.mark_committed(box, stage="set_phase", now_ts=time.time())
    emergency_output = _emergency_wallbox_output_command(cmd)
    output_claim = wallbox_output_ledger.claim(
        box,
        method=method,
        reason=command_reason,
        emergency=emergency_output,
    )
    box["_wallbox_output_ledger_last_claim"] = output_claim
    if not output_claim.get("allowed", False):
        logger.warning(
            "WB%s zweiter logischer Hardwareausgang im Managerzyklus blockiert (%s/%s, %s).",
            c_id if c_id is not None else box.get("id", "?"),
            method or kind,
            command_reason,
            output_claim.get("blocker", "output_slot_blocked"),
        )
        _discard_wallbox_command_guard_pending(box)
        return False
    _bind_admitted_actuator_intent(box, cmd, c_id=c_id)
    if (
        method in (
            "set_amp_sonnenmodus",
            "set_amp_autonomous_solar",
            "set_amp_and_state",
        )
        and e3dc_session.is_e3dc_native_charger(charger)
        and hasattr(charger, "lock")
    ):
        # Das E3DC-abort_flag ist eine Flanke, kein absoluter Zustand. Der
        # Treiberreceipt wird deshalb unter demselben RLock vor und nach dem
        # tatsächlichen RSCP-Ausgang gebunden; ein paralleler Heartbeat darf
        # den Beleg zwischen Wire-I/O und Managerreceipt nicht überschreiben.
        with charger.lock:
            native_wire_receipt_before = dict(
                getattr(charger, "_wbchar6_last_wire_receipt", {}) or {}
            )
            native_dispatch_outcome_before = dict(
                getattr(charger, "_wbchar6_last_dispatch_outcome", {}) or {}
            )
            driver_result = _wallbox_command_executor.execute(
                charger,
                cmd,
                c_id=c_id,
            )
            native_wire_receipt_after = dict(
                getattr(charger, "_wbchar6_last_wire_receipt", {}) or {}
            )
            native_dispatch_outcome_after = dict(
                getattr(charger, "_wbchar6_last_dispatch_outcome", {}) or {}
            )
            before_dispatch_seq = int(
                native_dispatch_outcome_before.get("seq", 0) or 0
            )
            after_dispatch_seq = int(
                native_dispatch_outcome_after.get("seq", 0) or 0
            )
            dispatch_outcome_new = bool(
                native_dispatch_outcome_after
                and after_dispatch_seq == before_dispatch_seq + 1
            )
            dispatch_state = str(
                native_dispatch_outcome_after.get("state") or "not_attempted"
            ) if dispatch_outcome_new else "not_attempted"
            box["_wallbox_driver_dispatch_contract"].update({
                "method": method,
                "reason": command_reason,
                "cycle_token": str(box.get("_wallbox_cycle_token") or ""),
                "wire_attempted": bool(
                    dispatch_state in ("attempted_ambiguous", "confirmed")
                ),
                "wire_outcome": dispatch_state,
                "driver_dispatch_seq": after_dispatch_seq,
                "attempt_ts": _cfg_float(
                    native_dispatch_outcome_after.get("wire_attempt_ts"),
                    0.0,
                ),
            })
            ok = _return_executed(driver_result)
    else:
        box["_wallbox_driver_dispatch_contract"].update({
            "method": method,
            "reason": command_reason,
            "cycle_token": str(box.get("_wallbox_cycle_token") or ""),
            "wire_attempted": True,
            "attempt_ts": time.time(),
        })
        if _emergency_wallbox_output_command(cmd):
            with command_gate.emergency_stop_scope(charger):
                driver_result = _wallbox_command_executor.execute(
                    charger,
                    cmd,
                    c_id=c_id,
                )
        else:
            driver_result = _wallbox_command_executor.execute(
                charger,
                cmd,
                c_id=c_id,
            )
        ok = _return_executed(driver_result)
    if not ok and method == "set_phases" and not openwb_pro_internal:
        wallbox_phase_transition.set_stage(
            box,
            "recovery_hold",
            now_ts=time.time(),
            reason_code="phase_command_failed",
        )
    if ok:
        _commit_wallbox_command_guard_after_receipt(
            box,
            cmd,
            previous_receipt=previous_command_receipt,
        )
    elif not _canonical_guarded_stop_command(cmd):
        _discard_wallbox_command_guard_pending(box)
    return ok


def _execute_wallbox_current_with_receipt(
    c_data,
    command,
    c_id=None,
    reason="",
):
    """Sende einen Strombefehl und liefere nur den neuen Ausgangsbeleg.

    Der letzte Hardware-Guard darf den angeforderten Strom reduzieren oder
    auf 0 A setzen. Aufrufer dürfen deshalb keine Soll-, Start- oder
    Haltezustände aus ihrer ursprünglichen Wunschvariable ableiten.
    """

    box = c_data if isinstance(c_data, dict) else {}
    cmd = command if isinstance(command, dict) else {}
    method = str(cmd.get("method") or cmd.get("kind") or "").strip()
    if method not in (
        "set_amp_and_state",
        "set_current",
        "set_direct_current",
        "set_amp_sonnenmodus",
        "set_amp_autonomous_solar",
    ):
        return None
    expected_reason = str(
        cmd.get("reason", reason or method) or method
    )
    previous = box.get("_last_executed_command")
    if not _execute_wallbox_driver_command(
        box,
        cmd,
        c_id=c_id,
        reason=reason,
    ):
        return None
    receipt = box.get("_last_executed_command")
    if not isinstance(receipt, dict) or receipt is previous:
        return None
    if str(receipt.get("method") or "") != method:
        return None
    if str(receipt.get("reason") or "") != expected_reason:
        return None
    if receipt.get("cycle_token") != box.get("_wallbox_cycle_token"):
        return None
    try:
        executed_amp = float(receipt.get("amp"))
    except (TypeError, ValueError):
        return None
    if not math.isfinite(executed_amp) or executed_amp < 0.0:
        return None
    return dict(receipt)


def _confirmed_native_current_amp(c_data, previous_receipt):
    """Projiziert nur den nach allen Gates bestätigten WBchar6-Strom."""

    data = c_data if isinstance(c_data, dict) else {}
    receipt = data.get("_last_executed_command")
    if not (
        isinstance(receipt, dict)
        and receipt is not previous_receipt
        and receipt.get("cycle_token") == data.get("_wallbox_cycle_token")
        and str(receipt.get("method") or "")
        in (
            "set_amp_and_state",
            "set_amp_sonnenmodus",
            "set_amp_autonomous_solar",
        )
        and receipt.get("wire_receipt_contract")
        == "e3dc_wbchar6_wire_receipt_v1"
        and receipt.get("wire_receipt_new") is True
    ):
        return None
    amp = _cfg_float(receipt.get("amp"), -1.0)
    if not math.isfinite(amp) or amp < 0.0:
        return None
    requested = _cfg_float(receipt.get("requested_amp"), amp)
    data["_wallbox_current_gate_projection"] = {
        "contract": "wallbox_current_gate_projection_v1",
        "requested_amp": requested,
        "executed_amp": amp,
        "gate_limited": amp < requested,
        "wire_receipt_seq": int(receipt.get("wire_receipt_seq", 0) or 0),
    }
    return amp


def _execute_wallbox_hold_current_enforcement(
    c_data,
    enforcement,
    *,
    action="",
    c_id=None,
):
    """Sende höchstens eine bestätigte Absenkung für einen Haltezustand."""

    box = c_data if isinstance(c_data, dict) else {}
    result = dict(enforcement) if isinstance(enforcement, dict) else {}
    enforcement_action = str(result.get("action") or "none")
    result["hold_action"] = str(action or result.get("hold_action") or "")
    result["command_confirmed"] = False
    if enforcement_action != "set_current":
        return result
    if result.get("reported_offer_known") is not True:
        result["blocker"] = "fresh_reported_offer_missing"
        return result
    target_amp = max(0.0, _cfg_float(result.get("target_amp"), 0.0))
    output_method = "set_current"
    if hasattr(box.get("charger"), "set_amp_sonnenmodus"):
        output_method = _native_solar_output_method(box)
        if not output_method:
            result["blocker"] = "native_solar_output_contract_not_current"
            return result
    receipt = _execute_wallbox_current_with_receipt(
        box,
        {
            "method": output_method,
            "amp": target_amp,
            "force_state": None,
            "reason": "hold_cap_down_%s" % str(
                action or result.get("hold_action") or "hold"
            ).lower(),
            "_openwb_pro_existing_session_hold": True,
        },
        c_id=c_id,
    )
    confirmed = bool(
        isinstance(receipt, dict)
        and str(receipt.get("method") or "") == output_method
        and _cfg_float(receipt.get("amp"), -1.0) >= 0.0
        and _cfg_float(receipt.get("amp"), 0.0) <= target_amp + 1e-6
    )
    result["command_confirmed"] = confirmed
    if confirmed:
        applied_amp = max(0.0, _cfg_float(receipt.get("amp"), 0.0))
        box["current_set_amp"] = applied_amp
        result["applied_amp"] = applied_amp
        result["receipt"] = dict(receipt)
    return result


def _release_wallbox_to_default(charger, max_amp, c_data=None):
    """Gibt eine Wallbox im Aus-Modus an ihren lokalen Grundzustand zurueck."""
    if charger is None:
        return False
    max_amp = _amp_limit(max_amp, 16)
    try:
        command_box = c_data if isinstance(c_data, dict) else {"charger": charger}
        if hasattr(charger, "release_to_default"):
            return _execute_wallbox_driver_command(
                command_box,
                {"method": "release_to_default", "max_amp": max_amp, "reason": "mode0_default_release"},
            )
        if hasattr(charger, "release_to_e3dc"):
            return _execute_wallbox_driver_command(
                command_box,
                {"method": "release_to_e3dc", "max_amp": max_amp, "reason": "mode0_default_release"},
            )
        if hasattr(charger, "set_pv_mode"):
            ok_current = True
            if hasattr(charger, "set_amp_and_state"):
                ok_current = _execute_wallbox_driver_command(
                    command_box,
                    {"method": "set_amp_and_state", "amp": max_amp, "force_state": None, "reason": "mode0_default_release"},
                )
            ok_pv = _execute_wallbox_driver_command(
                command_box,
                {"method": "set_pv_mode", "reason": "mode0_default_release"},
            )
            return ok_current or ok_pv
    except Exception as exc:
        logger.debug("Wallbox Default-Freigabe fehlgeschlagen: %s", exc)
    return False

def _house_fuse_autonomous_handoff_safe(hardware_max_amp, static_cap_amp):
    """Prüft, ob eine Wallbox im Mode 0 / autonom gefahrlos freigegeben werden darf."""
    if hardware_max_amp is None or static_cap_amp is None:
        return False
    try:
        hw = float(hardware_max_amp)
        cap = float(static_cap_amp)
    except (TypeError, ValueError):
        return False
    return 0 < hw <= cap and cap > 0


def _release_wallbox_to_default_once(c_data, max_amp, reason="mode0"):
    """Mode 0/Aus darf nur einmal freigeben und danach schweigen."""
    if not isinstance(c_data, dict):
        return False
    now_ts = time.time()
    raw_max_amp = _cfg_float(max_amp, 0.0)
    if not math.isfinite(raw_max_amp) or raw_max_amp < 6.0:
        c_data["_mode0_default_release_attempted"] = True
        c_data["_mode0_default_release_sent"] = False
        c_data["_mode0_default_release_ok"] = False
        c_data["_mode0_default_release_amp"] = 0
        c_data["_mode0_default_release_reason"] = str(reason)
        c_data["_mode0_default_release_blocker"] = (
            "configured_house_fuse_cap_below_minimum"
        )
        c_data["_mode0_default_release_ts"] = now_ts
        logger.error(
            "Wallbox Default-Freigabe verweigert: konfigurierte "
            "Hausanschlussgrenze erlaubt weniger als 6 A."
        )
        return False
    max_amp = _amp_limit(max_amp, 16)
    same_default = (
        bool(c_data.get("_mode0_default_release_attempted", False))
        and int(c_data.get("_mode0_default_release_amp", 0) or 0) == int(max_amp)
        and str(c_data.get("_mode0_default_release_reason", "")) == str(reason)
    )
    if same_default:
        return False
    with command_gate.default_release_scope(c_data.get("charger"), reason=reason):
        ok = _release_wallbox_to_default(c_data.get("charger"), max_amp, c_data=c_data)
    c_data["_mode0_default_release_attempted"] = True
    c_data["_mode0_default_release_sent"] = bool(ok)
    c_data["_mode0_default_release_ok"] = bool(ok)
    c_data["_mode0_default_release_amp"] = int(max_amp)
    c_data["_mode0_default_release_reason"] = str(reason)
    c_data["_mode0_default_release_ts"] = now_ts
    return ok

def _load_mode0_default_release_requests():
    try:
        if not os.path.exists(WB_DEFAULT_RELEASE_REQUEST_FILE):
            return {}
        with open(WB_DEFAULT_RELEASE_REQUEST_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}

def _save_mode0_default_release_requests(data):
    try:
        tmp = WB_DEFAULT_RELEASE_REQUEST_FILE + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(data if isinstance(data, dict) else {}, f)
        os.replace(tmp, WB_DEFAULT_RELEASE_REQUEST_FILE)
    except Exception:
        pass

def _consume_mode0_default_release_request(charger_id, max_age_s=86400.0):
    """Consumes the explicit WebUI switch-to-off request for one charger.

    Aus/NGNA must not send defaults after restarts, connection loss or a normal
    mode-0 loop. The release is allowed only when Wallbox.php recorded a fresh
    user action.
    """
    data = _load_mode0_default_release_requests()
    key = str(int(charger_id or 1))
    request = data.pop(key, None)
    changed = request is not None
    now_ts = time.time()
    for stale_key, stale_request in list(data.items()):
        try:
            if now_ts - float((stale_request or {}).get("ts", 0.0) or 0.0) > max_age_s:
                data.pop(stale_key, None)
                changed = True
        except Exception:
            data.pop(stale_key, None)
            changed = True
    if changed:
        _save_mode0_default_release_requests(data)
    if not isinstance(request, dict):
        return None
    try:
        if now_ts - float(request.get("ts", 0.0) or 0.0) > max_age_s:
            return None
    except Exception:
        return None
    return request

def _wallbox_user_mode_request_path(request_file=None):
    return str(request_file or WB_USER_MODE_REQUEST_FILE or "")


def _repair_mode5_user_start_legacy_parent(
    directory,
    parent,
    *,
    expected_mode,
    allowed_owner_uids,
    trusted_gid,
):
    """Ergänzt nur beim exakt passenden Legacy-Modus das Setgid-Bit."""

    legacy_mode = int(expected_mode) & 0o777
    if stat.S_IMODE(parent.st_mode) != legacy_mode:
        return False
    descriptor = None
    try:
        flags = os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
        flags |= getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0)
        descriptor = os.open(directory, flags)
        current = os.fstat(descriptor)
        if (
            not stat.S_ISDIR(current.st_mode)
            or (current.st_dev, current.st_ino) != (parent.st_dev, parent.st_ino)
            or current.st_uid not in allowed_owner_uids
            or current.st_gid != trusted_gid
            or stat.S_IMODE(current.st_mode) != legacy_mode
        ):
            return False
        os.fchmod(descriptor, int(expected_mode))
        changed = os.fstat(descriptor)
        named = os.lstat(directory)
        return bool(
            stat.S_ISDIR(changed.st_mode)
            and not stat.S_ISLNK(named.st_mode)
            and stat.S_ISDIR(named.st_mode)
            and (named.st_dev, named.st_ino) == (changed.st_dev, changed.st_ino)
            and named.st_uid in allowed_owner_uids
            and named.st_gid == trusted_gid
            and stat.S_IMODE(changed.st_mode) == int(expected_mode)
            and stat.S_IMODE(named.st_mode) == int(expected_mode)
        )
    except (OSError, TypeError, ValueError):
        return False
    finally:
        if descriptor is not None:
            os.close(descriptor)


def _mode5_user_start_surface_contract(request_file):
    """Prüft die gruppengebundene persistente PHP->Manager-Fläche."""

    target = _wallbox_user_mode_request_path(request_file)
    directory = os.path.dirname(target)
    try:
        parent = os.lstat(directory)
        trusted_gid = int(WB_MODE5_REQUEST_GROUP_GID)
        allowed_parent_uids = {
            int(os.geteuid()),
            int(WB_MODE5_REQUEST_OWNER_UID),
        }
        allowed_parent_uids.discard(-1)
        runtime_group_allowed = bool(
            os.geteuid() == 0 or os.getegid() == trusted_gid
        )
        expected_parent_mode = int(config_secret_dir_mode())
        if (
            stat.S_ISLNK(parent.st_mode)
            or not stat.S_ISDIR(parent.st_mode)
            or trusted_gid < 0
            or parent.st_uid not in allowed_parent_uids
            or parent.st_gid != trusted_gid
            or not runtime_group_allowed
            or int(WB_MODE5_REQUEST_OWNER_UID) < 0
            or expected_parent_mode not in {0o2770, 0o2775}
        ):
            return False
        if stat.S_IMODE(parent.st_mode) != expected_parent_mode:
            if not _repair_mode5_user_start_legacy_parent(
                directory,
                parent,
                expected_mode=expected_parent_mode,
                allowed_owner_uids=allowed_parent_uids,
                trusted_gid=trusted_gid,
            ):
                return False
        if not os.path.lexists(target):
            return True
        current = os.lstat(target)
        return bool(
            not stat.S_ISLNK(current.st_mode)
            and stat.S_ISREG(current.st_mode)
            and current.st_nlink == 1
            and 1 <= current.st_size <= 65536
            and stat.S_IMODE(current.st_mode) == 0o660
            and int(WB_MODE5_REQUEST_OWNER_UID) >= 0
            and current.st_uid == int(WB_MODE5_REQUEST_OWNER_UID)
            and current.st_gid == parent.st_gid
        )
    except Exception:
        return False


def _acquire_wallbox_user_mode_request_lock(
    timeout_s=0.25,
    request_file=None,
    *,
    lock_mode=0o664,
    required_gid=None,
):
    """Gemeinsame PHP/Python-Sperre für Peek, Persistenz und exaktes ACK."""

    path = _wallbox_user_mode_request_path(request_file) + ".lock"
    if not path:
        return None
    fd = None
    try:
        directory = os.path.dirname(path)
        if not os.path.isdir(directory) or os.path.islink(directory):
            return None
        strict_shared_lock = required_gid is not None
        allowed_owner_uids = {
            0,
            int(os.geteuid()),
            int(WB_MODE5_REQUEST_OWNER_UID),
        }
        allowed_owner_uids.discard(-1)
        before = None
        if os.path.lexists(path):
            before = os.lstat(path)
            if (
                stat.S_ISLNK(before.st_mode)
                or not stat.S_ISREG(before.st_mode)
                or before.st_nlink != 1
                or (
                    strict_shared_lock
                    and (
                        stat.S_IMODE(before.st_mode)
                        != (int(lock_mode) & 0o777)
                        or before.st_size > 65536
                        or before.st_gid != int(required_gid)
                        or before.st_uid not in allowed_owner_uids
                    )
                )
            ):
                return None
        flags = os.O_RDWR
        if strict_shared_lock:
            if before is None:
                flags |= os.O_CREAT | os.O_EXCL
        else:
            flags |= os.O_CREAT
        flags |= getattr(os, "O_CLOEXEC", 0)
        flags |= getattr(os, "O_NOFOLLOW", 0)
        expected_mode = int(lock_mode) & 0o777
        fd = os.open(path, flags, expected_mode)
        meta = os.fstat(fd)
        if not stat.S_ISREG(meta.st_mode) or meta.st_nlink != 1:
            os.close(fd)
            return None
        if before is not None:
            if (meta.st_dev, meta.st_ino) != (before.st_dev, before.st_ino):
                os.close(fd)
                return None
            if not strict_shared_lock:
                os.fchmod(fd, expected_mode)
        else:
            if strict_shared_lock and (
                meta.st_gid != int(required_gid)
                or meta.st_uid not in allowed_owner_uids
            ):
                os.close(fd)
                return None
            os.fchmod(fd, expected_mode)
        meta = os.fstat(fd)
        if (
            stat.S_IMODE(meta.st_mode) != expected_mode
            or (strict_shared_lock and meta.st_size > 65536)
            or (required_gid is not None and meta.st_gid != int(required_gid))
            or (
                strict_shared_lock
                and meta.st_uid not in allowed_owner_uids
            )
        ):
            os.close(fd)
            return None
        if strict_shared_lock:
            named = os.lstat(path)
            if (
                stat.S_ISLNK(named.st_mode)
                or not stat.S_ISREG(named.st_mode)
                or named.st_nlink != 1
                or (named.st_dev, named.st_ino) != (meta.st_dev, meta.st_ino)
                or named.st_size != meta.st_size
                or named.st_size > 65536
                or stat.S_IMODE(named.st_mode) != expected_mode
                or named.st_gid != int(required_gid)
                or named.st_uid not in allowed_owner_uids
            ):
                os.close(fd)
                return None
        if fcntl is None:
            return fd
        deadline = time.monotonic() + max(
            0.05,
            min(5.0, float(timeout_s or 0.0)),
        )
        while True:
            try:
                fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
                if strict_shared_lock:
                    locked_meta = os.fstat(fd)
                    locked_named = os.lstat(path)
                    if (
                        stat.S_ISLNK(locked_named.st_mode)
                        or not stat.S_ISREG(locked_meta.st_mode)
                        or not stat.S_ISREG(locked_named.st_mode)
                        or locked_meta.st_nlink != 1
                        or locked_named.st_nlink != 1
                        or (locked_meta.st_dev, locked_meta.st_ino)
                        != (locked_named.st_dev, locked_named.st_ino)
                        or locked_meta.st_size != locked_named.st_size
                        or locked_meta.st_size > 65536
                        or stat.S_IMODE(locked_meta.st_mode) != expected_mode
                        or stat.S_IMODE(locked_named.st_mode) != expected_mode
                        or locked_meta.st_gid != int(required_gid)
                        or locked_named.st_gid != int(required_gid)
                        or locked_meta.st_uid not in allowed_owner_uids
                        or locked_named.st_uid not in allowed_owner_uids
                    ):
                        fcntl.flock(fd, fcntl.LOCK_UN)
                        os.close(fd)
                        return None
                return fd
            except BlockingIOError:
                if time.monotonic() >= deadline:
                    os.close(fd)
                    return None
                time.sleep(0.01)
    except Exception:
        try:
            if fd is not None:
                os.close(fd)
        except Exception:
            pass
        return None


def _release_wallbox_user_mode_request_lock(fd):
    if fd is None:
        return
    if fcntl is not None:
        try:
            fcntl.flock(fd, fcntl.LOCK_UN)
        except Exception:
            pass
    try:
        os.close(fd)
    except Exception:
        pass


def _load_wallbox_user_mode_requests_unlocked(request_file=None):
    request_path = _wallbox_user_mode_request_path(request_file)
    try:
        if not os.path.lexists(request_path):
            return {}
        meta = os.lstat(request_path)
        if (
            stat.S_ISLNK(meta.st_mode)
            or not stat.S_ISREG(meta.st_mode)
            or meta.st_nlink != 1
            or meta.st_size > 65536
        ):
            return {}
        flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
        flags |= getattr(os, "O_NOFOLLOW", 0)
        fd = os.open(request_path, flags)
        try:
            current = os.fstat(fd)
            if (
                not stat.S_ISREG(current.st_mode)
                or current.st_nlink != 1
                or current.st_ino != meta.st_ino
                or current.st_size != meta.st_size
            ):
                return {}
            payload = b""
            while len(payload) < current.st_size:
                chunk = os.read(fd, min(65536, current.st_size - len(payload)))
                if not chunk:
                    break
                payload += chunk
        finally:
            os.close(fd)
        if len(payload) != meta.st_size:
            return {}
        data = json.loads(payload.decode("utf-8"))
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def _save_wallbox_user_mode_requests_unlocked(data, request_file=None):
    request_path = _wallbox_user_mode_request_path(request_file)
    tmp = ""
    try:
        directory = os.path.dirname(request_path)
        if not os.path.isdir(directory) or os.path.islink(directory):
            return False
        if os.path.lexists(request_path):
            meta = os.lstat(request_path)
            if stat.S_ISLNK(meta.st_mode) or not stat.S_ISREG(meta.st_mode):
                return False
        tmp = "%s.tmp.%d.%d" % (
            request_path,
            os.getpid(),
            time.time_ns(),
        )
        payload = json.dumps(
            data if isinstance(data, dict) else {},
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ) + "\n"
        with open(tmp, "x", encoding="utf-8") as handle:
            handle.write(payload)
            handle.flush()
            os.fsync(handle.fileno())
        os.chmod(tmp, 0o664)
        os.replace(tmp, request_path)
        directory_fd = os.open(directory, os.O_RDONLY)
        try:
            os.fsync(directory_fd)
        finally:
            os.close(directory_fd)
        return True
    except Exception:
        try:
            if tmp and os.path.exists(tmp):
                os.unlink(tmp)
        except Exception:
            pass
        return False


def _delete_wallbox_user_mode_request_unlocked(request_file=None):
    """Löscht die exakt gelockte Request-Datei und persistiert den Dir-Eintrag."""

    request_path = _wallbox_user_mode_request_path(request_file)
    try:
        current = os.lstat(request_path)
        if (
            stat.S_ISLNK(current.st_mode)
            or not stat.S_ISREG(current.st_mode)
            or current.st_nlink != 1
        ):
            return False
        os.unlink(request_path)
        directory_fd = os.open(os.path.dirname(request_path), os.O_RDONLY)
        try:
            os.fsync(directory_fd)
        finally:
            os.close(directory_fd)
        return True
    except Exception:
        return False


def _load_wallbox_user_mode_requests():
    lock_fd = _acquire_wallbox_user_mode_request_lock()
    if lock_fd is None:
        return {}
    try:
        return _load_wallbox_user_mode_requests_unlocked()
    finally:
        _release_wallbox_user_mode_request_lock(lock_fd)


def _save_wallbox_user_mode_requests(data):
    lock_fd = _acquire_wallbox_user_mode_request_lock()
    if lock_fd is None:
        return False
    try:
        return _save_wallbox_user_mode_requests_unlocked(data)
    finally:
        _release_wallbox_user_mode_request_lock(lock_fd)


def _prune_wallbox_user_mode_requests(data, *, now_ts, max_age_s):
    changed = False
    for stale_key, stale_request in list((data or {}).items()):
        try:
            request_ts = float((stale_request or {}).get("ts", 0.0) or 0.0)
            if (
                not math.isfinite(request_ts)
                or request_ts <= 0.0
                or request_ts > float(now_ts) + 5.0
                or float(now_ts) - request_ts > float(max_age_s)
            ):
                data.pop(stale_key, None)
                changed = True
        except Exception:
            data.pop(stale_key, None)
            changed = True
    return changed


def _peek_wallbox_user_mode_request(
    charger_id,
    target_mode=None,
    max_age_s=86400.0,
    request_file=None,
    strict_mode5_surface=False,
    now_ts=None,
):
    """Liest eine Request-Generation, ohne sie vor dem Zustandscommit zu löschen."""

    if strict_mode5_surface and not _mode5_user_start_surface_contract(
        request_file
    ):
        return None
    required_gid = (
        int(WB_MODE5_REQUEST_GROUP_GID)
        if strict_mode5_surface
        else None
    )
    lock_fd = _acquire_wallbox_user_mode_request_lock(
        request_file=request_file,
        lock_mode=0o660 if strict_mode5_surface else 0o664,
        required_gid=required_gid,
    )
    if lock_fd is None:
        return None
    try:
        if strict_mode5_surface and not _mode5_user_start_surface_contract(
            request_file
        ):
            return None
        data = _load_wallbox_user_mode_requests_unlocked(request_file)
        now_value = _cfg_float(now_ts, 0.0)
        if not math.isfinite(now_value) or now_value <= 0.0:
            now_value = time.time()
        changed = _prune_wallbox_user_mode_requests(
            data,
            now_ts=now_value,
            max_age_s=max_age_s,
        )
        request = data.get(str(int(charger_id or 1)))
        if isinstance(request, dict) and target_mode is not None:
            try:
                if normalize_wb_mode(request.get("target_mode")) != normalize_wb_mode(target_mode):
                    request = None
            except Exception:
                request = None
        if changed:
            if strict_mode5_surface:
                if data or not _delete_wallbox_user_mode_request_unlocked(
                    request_file
                ):
                    return None
            elif not _save_wallbox_user_mode_requests_unlocked(
                data,
                request_file,
            ):
                return None
        return deepcopy(request) if isinstance(request, dict) else None
    finally:
        _release_wallbox_user_mode_request_lock(lock_fd)


def _ack_wallbox_user_mode_request(
    charger_id,
    request_id,
    request_file=None,
    *,
    strict_mode5_surface=False,
    delete_exact_file=False,
):
    """Entfernt ausschließlich die zuvor persistierte Request-Generation."""

    expected_id = str(request_id or "")
    if not expected_id:
        return False
    if strict_mode5_surface and not _mode5_user_start_surface_contract(
        request_file
    ):
        return False
    lock_fd = _acquire_wallbox_user_mode_request_lock(
        request_file=request_file,
        lock_mode=0o660 if strict_mode5_surface else 0o664,
        required_gid=(
            int(WB_MODE5_REQUEST_GROUP_GID)
            if strict_mode5_surface
            else None
        ),
    )
    if lock_fd is None:
        return False
    try:
        if strict_mode5_surface and not _mode5_user_start_surface_contract(
            request_file
        ):
            return False
        data = _load_wallbox_user_mode_requests_unlocked(request_file)
        key = str(int(charger_id or 1))
        current = data.get(key)
        if not (
            isinstance(current, dict)
            and str(current.get("request_id") or "") == expected_id
        ):
            return False
        if delete_exact_file:
            if set(data) != {key}:
                return False
            return _delete_wallbox_user_mode_request_unlocked(request_file)
        data.pop(key, None)
        return _save_wallbox_user_mode_requests_unlocked(data, request_file)
    finally:
        _release_wallbox_user_mode_request_lock(lock_fd)


def _openwb_pro_mode0_current_public_mode(config, charger_id):
    cfg = config if isinstance(config, dict) else {}
    key = "wb%d_mode" % int(charger_id or 0)
    value = cfg.get(key)
    if value is not None and str(value).strip() != "":
        return normalize_wb_mode(value)
    legacy = int(_cfg_float(cfg.get("wb_native_mode"), 0.0))
    return normalize_wb_mode(legacy) if legacy > 2 else MODE_OFF


def _openwb_pro_mode0_private_state_dir():
    """Erzeugt genau einen privaten, serviceeigenen Lease-Ordner (0700)."""

    euid = int(getattr(os, "geteuid", lambda: 0)())
    if int(WB_MODE5_REQUEST_OWNER_UID) >= 0 and euid == int(
        WB_MODE5_REQUEST_OWNER_UID
    ):
        raise openwb_pro_control_lease.ControlLeasePersistenceError(
            "web_user_must_not_own_control_lease"
        )
    configured = str(os.environ.get(OPENWB_PRO_MODE0_STATE_DIR_ENV, "") or "").strip()
    if configured:
        directory = os.path.abspath(configured)
    else:
        home = ""
        if pwd is not None:
            try:
                home = str(pwd.getpwuid(euid).pw_dir or "")
            except Exception:
                home = ""
        if not home:
            home = os.path.dirname(os.path.abspath(INSTALL_DIR))
        directory = os.path.abspath(
            os.path.join(home, OPENWB_PRO_MODE0_STATE_DIR_BASENAME)
        )
    parent = os.path.dirname(directory)
    if (
        not parent
        or os.path.realpath(parent) != os.path.abspath(parent)
        or not os.path.isdir(parent)
        or os.path.islink(parent)
    ):
        raise openwb_pro_control_lease.ControlLeasePersistenceError(
            "control_lease_parent_unsafe"
        )
    try:
        os.mkdir(directory, 0o700)
    except FileExistsError:
        pass
    meta = os.lstat(directory)
    if (
        stat.S_ISLNK(meta.st_mode)
        or not stat.S_ISDIR(meta.st_mode)
        or meta.st_uid != euid
        or os.path.realpath(directory) != directory
    ):
        raise openwb_pro_control_lease.ControlLeasePersistenceError(
            "control_lease_directory_unsafe"
        )
    if stat.S_IMODE(meta.st_mode) != 0o700:
        os.chmod(directory, 0o700)
        meta = os.lstat(directory)
    if stat.S_IMODE(meta.st_mode) != 0o700 or meta.st_uid != euid:
        raise openwb_pro_control_lease.ControlLeasePersistenceError(
            "control_lease_directory_mode_invalid"
        )
    return directory


def _openwb_pro_mode0_state_path(charger_id):
    wb_id = int(charger_id or 0)
    if wb_id < 1 or wb_id > 64:
        raise openwb_pro_control_lease.ControlLeasePersistenceError(
            "control_lease_wallbox_id_invalid"
        )
    return os.path.join(
        _openwb_pro_mode0_private_state_dir(),
        "wallbox_openwb_pro_control_lease_wb%d.json" % wb_id,
    )


def _openwb_pro_mode0_request_validation(
    c_data,
    request,
    *,
    current_config,
    expected_public_mode,
    now_ts,
):
    box = c_data if isinstance(c_data, dict) else {}
    item = request if isinstance(request, dict) else {}
    result = {
        "valid": False,
        "blocker": "request_invalid",
        "request_id": str(item.get("request_id") or ""),
    }
    expected_keys = {
        "schema",
        "request_id",
        "candidate_config_sha256",
        "wb",
        "target_mode",
        "previous_mode",
        "ts",
        "source",
        "reason",
    }
    request_id = str(item.get("request_id") or "").lower()
    candidate_sha = str(item.get("candidate_config_sha256") or "").lower()
    if (
        set(item) != expected_keys
        or item.get("schema") != OPENWB_PRO_MODE0_REQUEST_SCHEMA
        or item.get("source") != "Wallbox.php"
        or item.get("reason") != "mode0_user_switch"
        or item.get("target_mode") != "0"
        or str(item.get("previous_mode") or "") not in {"2", "3", "4", "5", "12"}
        or len(request_id) != 32
        or any(char not in "0123456789abcdef" for char in request_id)
        or len(candidate_sha) != 64
        or any(char not in "0123456789abcdef" for char in candidate_sha)
    ):
        return result
    try:
        request_wb = int(item.get("wb"))
        request_ts = float(item.get("ts"))
        expected_wb = int(box.get("id", 0) or 0)
    except (TypeError, ValueError, OverflowError):
        return result
    if isinstance(item.get("wb"), bool) or request_wb != expected_wb or expected_wb < 1:
        result["blocker"] = "wallbox_binding_mismatch"
        return result
    if (
        not math.isfinite(request_ts)
        or request_ts <= 0.0
        or request_ts > float(now_ts) + 5.0
        or float(now_ts) - request_ts > 86400.0
    ):
        result["blocker"] = "request_timestamp_invalid"
        return result
    charger = box.get("charger")
    if not openwb_pro_session.is_openwb_pro_charger(charger):
        result["blocker"] = "openwb_pro_driver_required"
        return result
    type_key = "wb_native_type" if expected_wb == 1 else "wb_native_type2"
    ip_key = "wb_native_ip" if expected_wb == 1 else "wb_native_ip2"
    configured_type = str(
        (current_config or {}).get(type_key, "") or ""
    ).strip().lower().replace("-", "_")
    if configured_type not in {"openwb_pro", "openwbpro"}:
        result["blocker"] = "configured_driver_binding_mismatch"
        return result
    current_mode = _openwb_pro_mode0_current_public_mode(
        current_config,
        expected_wb,
    )
    if (
        normalize_wb_mode(expected_public_mode) != MODE_OFF
        or current_mode != MODE_OFF
    ):
        result["blocker"] = "current_mode_not_off"
        return result
    current_sha = _sha256_regular_file(V4_CONFIG_FILE)
    if not current_sha or current_sha != candidate_sha:
        result["blocker"] = "candidate_config_generation_mismatch"
        return result
    endpoint = str(getattr(charger, "ip", "") or "").strip().lower()
    if not endpoint or len(endpoint) > 512:
        result["blocker"] = "configured_endpoint_missing"
        return result
    configured_endpoint = str(
        (current_config or {}).get(ip_key, "") or ""
    ).strip().lower()
    if configured_endpoint != endpoint:
        result["blocker"] = "configured_endpoint_binding_mismatch"
        return result
    device_identity = openwb_pro_control_lease.device_identity_hash({
        "driver": "OpenWBProCharger",
        "wb_id": expected_wb,
        "endpoint": endpoint,
    })
    result.update({
        "valid": True,
        "blocker": "",
        "request_id": request_id,
        "candidate_config_hash": "sha256:" + candidate_sha,
        "candidate_config_sha256": candidate_sha,
        "wb_id": expected_wb,
        "device_identity": device_identity,
        "request_ts": request_ts,
    })
    return result


def _openwb_pro_mode0_operation_id(validation, generation, action):
    material = {
        "schema": "openwb_pro_mode0_operation_v1",
        "request_id": str(validation.get("request_id") or ""),
        "generation": int(generation),
        "action": str(action or ""),
    }
    digest = hashlib.sha256(
        json.dumps(
            material,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    return "mode0:" + digest


def _openwb_pro_mode0_output_binding(
    c_data,
    record,
    *,
    action,
    operation_id,
):
    state = openwb_pro_control_lease.validate_state(record)
    return {
        "schema": OPENWB_PRO_MODE0_OUTPUT_BINDING_SCHEMA,
        "request_id": state["request_id"],
        "candidate_config_hash": state["candidate_config_hash"],
        "wb_id": state["wb_id"],
        "device_identity": state["device_identity"],
        "generation": state["generation"],
        "action": str(action),
        "operation_id": str(operation_id),
        "lease_record_hash": state["record_hash"],
        "cycle_token": str((c_data or {}).get("_wallbox_cycle_token") or ""),
    }


def _openwb_pro_mode0_zero_readback_contract(status):
    st = status if isinstance(status, dict) else {}
    result = {
        "confirmed": False,
        "blocker": "fresh_connect_readback_missing",
    }
    required = (
        "offered_current_raw",
        "evse_current",
        "real_power_w",
        "phase_power_sum_w",
        "phase_current_l1_a",
        "phase_current_l2_a",
        "phase_current_l3_a",
    )
    if (
        not st
        or st.get("connect_php_payload_valid") is not True
        or st.get("driver_status_plausible") is not True
        or st.get("driver_status_glitch") is True
        or any(st.get(key) is None for key in required)
    ):
        return result
    try:
        offered_a = max(
            abs(float(st.get("offered_current_raw"))),
            abs(float(st.get("evse_current"))),
            abs(float(st.get("amp", 0.0))),
        )
        power_w = max(
            abs(float(st.get("real_power_w"))),
            abs(float(st.get("phase_power_sum_w"))),
        )
        phase_current_a = max(
            abs(float(st.get("phase_current_l1_a"))),
            abs(float(st.get("phase_current_l2_a"))),
            abs(float(st.get("phase_current_l3_a"))),
        )
    except (TypeError, ValueError, OverflowError):
        result["blocker"] = "zero_readback_non_numeric"
        return result
    if not all(math.isfinite(value) for value in (offered_a, power_w, phase_current_a)):
        result["blocker"] = "zero_readback_non_finite"
        return result
    charging = bool(
        st.get("charging") is True
        or st.get("charge_state") is True
        or st.get("phase_power_verified") is True
    )
    result.update({
        "offered_a": round(offered_a, 3),
        "power_w": round(power_w, 3),
        "max_phase_current_a": round(phase_current_a, 3),
        "charging": charging,
    })
    if offered_a > 0.5:
        result["blocker"] = "zero_offer_not_confirmed"
    elif charging:
        result["blocker"] = "charging_still_active"
    elif power_w > 100.0:
        result["blocker"] = "power_not_zero"
    elif phase_current_a > 0.5:
        result["blocker"] = "phase_current_not_zero"
    else:
        result.update({"confirmed": True, "blocker": ""})
    return result


def _ack_openwb_pro_mode0_request_locked(charger_id, expected_request):
    data = _load_wallbox_user_mode_requests_unlocked(
        WB_DEFAULT_RELEASE_REQUEST_FILE
    )
    key = str(int(charger_id or 0))
    current = data.get(key)
    if not isinstance(current, dict) or current != expected_request:
        return False
    data.pop(key, None)
    if data:
        return _save_wallbox_user_mode_requests_unlocked(
            data,
            WB_DEFAULT_RELEASE_REQUEST_FILE,
        )
    return _delete_wallbox_user_mode_request_unlocked(
        WB_DEFAULT_RELEASE_REQUEST_FILE
    )


def _advance_openwb_pro_mode0_handoff(
    c_data,
    *,
    current_config,
    public_mode,
    now_ts=None,
):
    """Führt höchstens eine Pro-Gerätekante eines expliziten Aus-Handoffs aus."""

    box = c_data if isinstance(c_data, dict) else {}
    charger = box.get("charger")
    cycle_token = str(box.get("_wallbox_cycle_token") or "")
    now_value = time.time() if now_ts is None else float(now_ts)
    result = {
        "contract": "openwb_pro_mode0_control_handoff_v1",
        "active": False,
        "public_mode": normalize_wb_mode(public_mode),
        "state": "inactive",
        "action": "none",
        "device_io": "none",
        "wire_attempted": False,
        "read_attempted": False,
        "acknowledged": False,
        "cycle_token": cycle_token,
        "blocker": "not_openwb_pro_or_not_off",
    }
    box.pop("_openwb_pro_mode0_status_override", None)
    if (
        not openwb_pro_session.is_openwb_pro_charger(charger)
        or normalize_wb_mode(public_mode) != MODE_OFF
    ):
        box["_openwb_pro_control_handoff"] = deepcopy(result)
        return result
    result.update({
        "active": True,
        "state": "silent",
        "blocker": "request_missing",
    })
    # Mode 0 darf connect.php nicht zyklisch als versteckten Heartbeat
    # verwenden. Nur der explizite Null-Readback-Zustand erhält genau einen GET.
    box["_openwb_pro_mode0_status_override"] = {
        "cycle_token": cycle_token,
        "attempted": False,
        "raw_status": None,
    }
    lock_fd = _acquire_wallbox_user_mode_request_lock(
        request_file=WB_DEFAULT_RELEASE_REQUEST_FILE,
        lock_mode=0o664,
    )
    if lock_fd is None:
        result["blocker"] = "request_lock_unavailable"
        box["_openwb_pro_control_handoff"] = deepcopy(result)
        return result
    try:
        request_data = _load_wallbox_user_mode_requests_unlocked(
            WB_DEFAULT_RELEASE_REQUEST_FILE
        )
        request = request_data.get(str(int(box.get("id", 0) or 0)))
        if not isinstance(request, dict):
            return result
        validation = _openwb_pro_mode0_request_validation(
            box,
            request,
            current_config=current_config,
            expected_public_mode=public_mode,
            now_ts=now_value,
        )
        result["request_id"] = str(validation.get("request_id") or "")
        if validation.get("valid") is not True:
            result["blocker"] = str(validation.get("blocker") or "request_invalid")
            return result
        state_path = _openwb_pro_mode0_state_path(validation["wb_id"])
        existing = openwb_pro_control_lease.read_state(
            state_path,
            allow_missing=True,
        )
        if existing is None:
            requested = openwb_pro_control_lease.request_handoff(
                None,
                request_id=validation["request_id"],
                candidate_hash=validation["candidate_config_hash"],
                wb_id=validation["wb_id"],
                device_identity=validation["device_identity"],
                generation=1,
                timestamp_ns=time.time_ns(),
            )
            state = openwb_pro_control_lease.write_state(
                state_path,
                requested,
                expected_record_hash=None,
            )
        else:
            same_request = str(existing.get("request_id") or "") == validation["request_id"]
            if same_request:
                state = openwb_pro_control_lease.require_binding(
                    existing,
                    {
                        "request_id": validation["request_id"],
                        "candidate_config_hash": validation["candidate_config_hash"],
                        "wb_id": validation["wb_id"],
                        "device_identity": validation["device_identity"],
                        "generation": existing["generation"],
                    },
                )
            else:
                requested = openwb_pro_control_lease.request_handoff(
                    existing,
                    request_id=validation["request_id"],
                    candidate_hash=validation["candidate_config_hash"],
                    wb_id=validation["wb_id"],
                    device_identity=validation["device_identity"],
                    generation=int(existing["generation"]) + 1,
                    timestamp_ns=time.time_ns(),
                )
                state = openwb_pro_control_lease.write_state(
                    state_path,
                    requested,
                    expected_record_hash=existing["record_hash"],
                )
        result.update({
            "generation": int(state["generation"]),
            "state": str(state["state"]),
            "blocker": "",
        })
        if state["state"] == openwb_pro_control_lease.STATE_RELEASED:
            result["acknowledged"] = _ack_openwb_pro_mode0_request_locked(
                validation["wb_id"],
                request,
            )
            if not result["acknowledged"]:
                result["blocker"] = "exact_request_ack_failed_or_superseded"
            return result
        if state["state"] == openwb_pro_control_lease.STATE_HEARTBEAT_OFF_SENT:
            finalized = openwb_pro_control_lease.finalize_release(
                state,
                timestamp_ns=time.time_ns(),
            )
            state = openwb_pro_control_lease.write_state(
                state_path,
                finalized,
                expected_record_hash=state["record_hash"],
            )
            result.update({
                "state": state["state"],
                "action": openwb_pro_control_lease.ACTION_FINALIZE_RELEASE,
            })
            result["acknowledged"] = _ack_openwb_pro_mode0_request_locked(
                validation["wb_id"],
                request,
            )
            if not result["acknowledged"]:
                result["blocker"] = "exact_request_ack_failed_or_superseded"
            return result

        transition = openwb_pro_control_lease.expected_next(state)
        action = transition["action"]
        operation_id = _openwb_pro_mode0_operation_id(
            validation,
            state["generation"],
            action,
        )
        pending = state.get("pending_intent")
        if pending is None:
            prepared = openwb_pro_control_lease.prepare_transition(
                state,
                action=action,
                operation_id=operation_id,
                timestamp_ns=time.time_ns(),
            )
            prepared = openwb_pro_control_lease.write_state(
                state_path,
                prepared,
                expected_record_hash=state["record_hash"],
            )
        else:
            if (
                str(pending.get("action") or "") != action
                or str(pending.get("operation_id") or "") != operation_id
            ):
                raise openwb_pro_control_lease.ControlLeaseTransitionError(
                    "pending_intent_binding_mismatch"
                )
            prepared = state

        # Dieselbe Web-Transaktion und derselbe Config-Bytebestand werden
        # unmittelbar vor genau einem Gerätezugriff unter derselben PHP/Python-
        # Sperre erneut gebunden. Der Prozess-Singleton fencet andere Manager.
        current_requests = _load_wallbox_user_mode_requests_unlocked(
            WB_DEFAULT_RELEASE_REQUEST_FILE
        )
        if current_requests.get(str(validation["wb_id"])) != request:
            raise openwb_pro_control_lease.ControlLeaseBindingMismatch(
                "request_superseded_before_output"
            )
        repeated_validation = _openwb_pro_mode0_request_validation(
            box,
            request,
            current_config=get_config(),
            expected_public_mode=public_mode,
            now_ts=time.time(),
        )
        if repeated_validation.get("valid") is not True:
            raise openwb_pro_control_lease.ControlLeaseBindingMismatch(
                str(repeated_validation.get("blocker") or "revalidation_failed")
            )

        success = False
        receipt_prefix = "failed"
        result["action"] = action
        if action == openwb_pro_control_lease.ACTION_SEND_ZERO:
            binding = _openwb_pro_mode0_output_binding(
                box,
                prepared,
                action=action,
                operation_id=operation_id,
            )
            command = {
                "method": "release_to_default",
                "max_amp": 0,
                "reason": "mode0_default_release",
                "_openwb_pro_mode0_release_binding": binding,
            }
            result.update({"device_io": "post_zero", "wire_attempted": True})
            with command_gate.default_release_scope(
                charger,
                reason="mode0_user_switch",
                binding=binding,
            ):
                success = bool(_execute_wallbox_driver_command(
                    box,
                    command,
                    c_id=validation["wb_id"],
                ))
            receipt_prefix = "wire"
        elif action == openwb_pro_control_lease.ACTION_CONFIRM_ZERO_READBACK:
            result.update({"device_io": "get_connect", "read_attempted": True})
            raw_status = charger.get_control_handoff_status()
            box["_openwb_pro_mode0_status_override"] = {
                "cycle_token": cycle_token,
                "attempted": True,
                "raw_status": raw_status,
            }
            zero_readback = _openwb_pro_mode0_zero_readback_contract(raw_status)
            result["zero_readback"] = zero_readback
            success = zero_readback.get("confirmed") is True
            receipt_prefix = "readback"
        elif action == openwb_pro_control_lease.ACTION_SEND_HEARTBEAT_OFF:
            binding = _openwb_pro_mode0_output_binding(
                box,
                prepared,
                action=action,
                operation_id=operation_id,
            )
            command = {
                "method": "set_heartbeat",
                "enabled": False,
                "reason": "mode0_default_release",
                "_openwb_pro_mode0_release_binding": binding,
            }
            result.update({
                "device_io": "post_heartbeat_off",
                "wire_attempted": True,
            })
            with command_gate.default_release_scope(
                charger,
                reason="mode0_user_switch",
                binding=binding,
            ):
                success = bool(_execute_wallbox_driver_command(
                    box,
                    command,
                    c_id=validation["wb_id"],
                ))
            receipt_prefix = "wire"
        else:
            raise openwb_pro_control_lease.ControlLeaseTransitionError(
                "unsupported_mode0_action"
            )

        received = openwb_pro_control_lease.record_receipt(
            prepared,
            operation_id=operation_id,
            receipt_id="%s:%s:%s" % (
                receipt_prefix,
                operation_id,
                "ok" if success else "failed",
            ),
            success=bool(success),
            timestamp_ns=time.time_ns(),
        )
        state = openwb_pro_control_lease.write_state(
            state_path,
            received,
            expected_record_hash=prepared["record_hash"],
        )
        result.update({
            "success": bool(success),
            "state": state["state"],
            "blocker": "" if success else "%s_failed" % action,
        })
        return result
    except openwb_pro_control_lease.ControlLeaseError as exc:
        result["blocker"] = "%s:%s" % (
            exc.__class__.__name__,
            str(exc),
        )
        return result
    except Exception as exc:
        result["blocker"] = "handoff_internal_error:%s" % exc.__class__.__name__
        return result
    finally:
        _release_wallbox_user_mode_request_lock(lock_fd)
        box["_openwb_pro_control_handoff"] = deepcopy(result)


def _consume_wallbox_user_mode_request(charger_id, target_mode=None, max_age_s=60.0):
    """Verbraucht den bestehenden Mode-2-Auftrag atomar unter derselben Sperre."""

    lock_fd = _acquire_wallbox_user_mode_request_lock()
    if lock_fd is None:
        return None
    try:
        data = _load_wallbox_user_mode_requests_unlocked()
        key = str(int(charger_id or 1))
        now_ts = time.time()
        changed = _prune_wallbox_user_mode_requests(
            data,
            now_ts=now_ts,
            max_age_s=max_age_s,
        )
        request = data.get(key)
        if isinstance(request, dict) and target_mode is not None:
            try:
                if normalize_wb_mode(request.get("target_mode")) != normalize_wb_mode(target_mode):
                    request = None
            except Exception:
                request = None
        if isinstance(request, dict):
            data.pop(key, None)
            changed = True
        if changed and not _save_wallbox_user_mode_requests_unlocked(data):
            return None
        return request if isinstance(request, dict) else None
    finally:
        _release_wallbox_user_mode_request_lock(lock_fd)

def _wallbox_curve_switch_quiet_until(request, *, now_ts=None, hold_s=60.0):
    """Return the quiet-until timestamp after an explicit switch to PV curve."""
    if not isinstance(request, dict):
        return 0.0
    try:
        request_ts = float(request.get("ts", 0.0) or 0.0)
    except Exception:
        return 0.0
    if request_ts <= 0.0:
        return 0.0
    now = time.time() if now_ts is None else float(now_ts or 0.0)
    hold = max(0.0, float(hold_s or 0.0))
    quiet_until = request_ts + hold
    return quiet_until if quiet_until > now else 0.0

def _apply_pv_curve_mode_switch_quiet_request(
    c_data,
    charger_id,
    public_mode,
    quiet_supported,
    *,
    now_ts=None,
    hold_s=60.0,
):
    """Consume an explicit user switch to PV curve and debounce the next start.

    openWB Pro has no separate "set PV mode" API command in our HAL path. It
    still needs the same UI-visible quiet window after returning from wbminSoC
    support, otherwise the request file stays behind and the next cycle can
    immediately re-enter start/phase logic.
    """
    if not quiet_supported or normalize_wb_mode(public_mode) != MODE_CURVE:
        return None
    request = _consume_wallbox_user_mode_request(charger_id, MODE_CURVE)
    quiet_until = _wallbox_curve_switch_quiet_until(
        request,
        now_ts=now_ts,
        hold_s=hold_s,
    )
    if quiet_until > float(now_ts if now_ts is not None else time.time()):
        c_data["_pv_curve_mode_switch_quiet_until"] = max(
            float(c_data.get("_pv_curve_mode_switch_quiet_until", 0.0) or 0.0),
            quiet_until,
        )
    return request


def _charger_min_amp(config, c_id=1, default=6):
    """Ermittelt den konfigurierten Mindestladestrom fuer die angegebene Wallbox (Standard: 6A)."""
    if not isinstance(config, dict):
        return default
    val = (
        config.get(f"wb{c_id}_min_amp")
        or config.get(f"wb{c_id}_minladestrom")
        or config.get("wbminladestrom")
        or config.get("wb_min_amp")
    )
    try:
        if val is not None and str(val).strip() != "":
            return max(6, min(16, int(float(str(val).strip().replace(",", ".")))))
    except Exception:
        pass
    return default


def _apply_wallbox_force_start_request(c_data, chargers, c_id, now_ts=None):
    """Verarbeitet einen expliziten Force-Start- / Entsperr-Befehl des Nutzers."""
    if not isinstance(c_data, dict):
        return False
    request = _consume_wallbox_user_mode_request(c_id, "force_start", max_age_s=60.0)
    if not isinstance(request, dict):
        request = _consume_wallbox_user_mode_request(c_id, "start_now", max_age_s=60.0)
    if not isinstance(request, dict):
        request = _consume_wallbox_user_mode_request(c_id, 1, max_age_s=60.0)
    if not isinstance(request, dict):
        return False
    logger.info(
        "WB%d Force-Start-Anforderung empfangen: hebe alle Lade- und Start-Latches auf.",
        c_id,
    )
    openwb_pro = openwb_pro_session.is_openwb_pro_charger(
        c_data.get("charger")
    )
    plug_session_id = str(
        c_data.get("_openwb_pro_plug_session_id") or ""
    )
    anchor_state = (
        _mode5_user_start_anchor_contract(c_data, plug_session_id)
        if openwb_pro
        else {"active": False, "exact": False, "blocker": ""}
    )
    if anchor_state.get("blocker"):
        logger.warning(
            "WB%d Force-Start blockiert: fremder oder geschützter 0-A-Anker bleibt aktiv.",
            c_id,
        )
        return False

    def apply_request():
        _reset_wallbox_start_reject_episode(c_data)
        c_data["_bev_full_blocked"] = False
        c_data["_bev_full_block_reason"] = ""
        c_data["_had_real_charge_in_session"] = False
        c_data.pop("_charge_end_latched_plug_session_id", None)
        c_data.pop("_start_rejected_generic_release_blocked", None)
        c_data.pop("_last_start_rejected_hold", None)
        c_data["_openwb_pro_start_wakeup_pending"] = False
        c_data["_openwb_pro_start_wakeup_count"] = 0
        c_data["_openwb_pro_unserved_since"] = 0.0
        c_data["_openwb_pro_unserved_pause_since"] = 0.0
        c_data["_openwb_pro_unserved_paused_s"] = 0.0
        if openwb_pro and not _clear_exact_mode5_start_rejected_anchor(
            c_data,
            plug_session_id,
        ):
            raise RuntimeError("force_start_zero_anchor_generation_changed")
        start_hold_rearmed = False
        if openwb_pro and plug_session_id:
            # Ein ausdrücklicher Benutzer-Start ist eine neue, eng begrenzte
            # Startautorität innerhalb derselben physischen Stecksession. Er
            # darf genau einen neuen 40-Wh-Start-Halteversuch eröffnen, ohne
            # Nutzer-Aus, Floor-, Netz- oder Hardware-Sperren zu umgehen.
            # Der nachgelagerte Request bindet sich erneut an den frischen
            # Geräte-/Phasenvertrag; ein alter 1p-Grant wird nicht übernommen.
            c_data.pop(wallbox_start_hold.STATE_KEY, None)
            c_data.pop(wallbox_start_hold.GRANT_KEY, None)
            c_data.pop(wallbox_start_hold.SESSION_KEY, None)
            c_data.pop(wallbox_start_hold.CONSUMED_SESSION_KEY, None)
            c_data[wallbox_start_hold.DISCONNECT_SEEN_KEY] = True
            start_hold_rearmed = True
        return {
            "plug_session_id": plug_session_id,
            "exact_start_rejected_anchor_cleared": bool(
                anchor_state.get("exact")
            ),
            "start_hold_rearmed": start_hold_rearmed,
            "hardware_write": False,
        }

    if openwb_pro:
        persistence = _persist_openwb_pro_session_transaction(
            c_data,
            apply_request,
            name="force_start_reset",
        )
        c_data["_wallbox_force_start_apply_contract"] = {
            "contract": "wallbox_force_start_apply_v1",
            "applied": persistence.get("committed") is True,
            "persisted": persistence.get("committed") is True,
            "plug_session_id": plug_session_id,
            "exact_start_rejected_anchor_cleared": bool(
                anchor_state.get("exact")
                and persistence.get("committed") is True
            ),
            "start_hold_rearmed": bool(
                persistence.get("committed") is True
                and c_data.get(wallbox_start_hold.DISCONNECT_SEEN_KEY)
                is True
            ),
            "hardware_write": False,
            "reason": str(persistence.get("reason") or ""),
        }
        if persistence.get("committed") is not True:
            logger.error(
                "WB%d Force-Start konnte nicht atomar persistiert werden: %s",
                c_id,
                persistence.get("reason") or "unbekannt",
            )
            return False
        return True

    apply_request()
    return bool(_save_wallbox_abort_state(chargers))


def _apply_openwb_primary_curve_user_request(c_data, charger, charger_id):
    """Projiziert nur einen frischen expliziten Mode-2-Intent zum Driver-Gate."""

    data = c_data if isinstance(c_data, dict) else {}
    result = {
        "contract": "openwb_primary_curve_user_request_v1",
        "request_present": False,
        "applied": False,
        "hardware_write": False,
        "ok": False,
        "blocker": "request_missing_or_stale",
    }
    request = _consume_wallbox_user_mode_request(
        charger_id,
        MODE_CURVE,
        max_age_s=60.0,
    )
    if not isinstance(request, dict):
        return result
    result["request_present"] = True
    if charger is None or not hasattr(charger, "set_pv_mode"):
        result["blocker"] = "set_pv_mode_not_supported"
        return result
    with command_gate.default_release_scope(
        charger,
        reason="mode2_user_switch_pv",
    ):
        ok = bool(_execute_wallbox_driver_command(
            data,
            {
                "method": "set_pv_mode",
                "reason": "mode2_user_switch_pv",
            },
            c_id=charger_id,
        ))
    data["_pv_mode_active"] = ok
    data["_openwb_primary_pv_mode_set_ts"] = time.time()
    result.update({
        "applied": True,
        "hardware_write": True,
        "ok": ok,
        "blocker": "",
    })
    return result

def _reset_mode0_default_release(c_data):
    if isinstance(c_data, dict):
        c_data["_mode0_default_release_attempted"] = False
        c_data["_mode0_default_release_sent"] = False
        c_data["_mode0_default_release_ok"] = False

WALLBOX_COMMAND_OWNER_LEASE_S = 30.0


def _wallbox_narrow_runtime_context_status():
    """Prüft nur die lokale Manager-/Konfigurationsidentität für Wallboxschreibvorgänge.

    Dies hängt bewusst nicht von der allgemeinen Installer-Laufzeitauflösung ab,
    damit die Schutzlogik ohne Änderung der Produktverdrahtung nutzbar bleibt.
    """
    ha_admission = evaluate_writer_admission()
    if ha_admission.get("allowed") is not True:
        return {
            "valid": False,
            "reason": str(
                ha_admission.get("reason") or "ha_writer_admission_blocked"
            ),
            "hard_authority_block": True,
            "authority_confirmed": False,
            "ha_writer_admission": dict(ha_admission),
        }
    lexical_manager = os.path.abspath(__file__)
    actual_manager = os.path.realpath(lexical_manager)
    if lexical_manager != actual_manager or not os.path.isfile(actual_manager):
        return {
            "valid": False,
            "reason": "wallbox_manager_identity_mismatch",
            "authority_confirmed": True,
        }
    install_root = os.path.dirname(os.path.dirname(actual_manager))
    markers = (
        os.path.join(install_root, "VERSION"),
        os.path.join(install_root, "installer_main.py"),
        os.path.join(install_root, "Installer", "Wallbox", "config.py"),
    )
    if not all(os.path.isfile(path) and not os.path.islink(path) for path in markers):
        return {
            "valid": False,
            "reason": "wallbox_product_markers_missing",
            "authority_confirmed": True,
        }
    config_sources = tuple(path for path in (V4_CONFIG_FILE, CONFIG_FILE) if path)
    if not any(os.path.isfile(path) and not os.path.islink(path) for path in config_sources):
        return {
            "valid": False,
            "reason": "wallbox_config_source_missing",
            "authority_confirmed": True,
        }
    try:
        current = get_config()
    except Exception:
        return {
            "valid": False,
            "reason": "wallbox_config_unreadable",
            "authority_confirmed": True,
        }
    if not isinstance(current, dict) or str(current.get("path_context_valid", "1")).strip().lower() in (
        "0", "false", "no", "off",
    ):
        return {
            "valid": False,
            "reason": "wallbox_path_context_invalid",
            "authority_confirmed": True,
        }
    if str(current.get("wb_native_enable", "0")).strip().lower() not in ("1", "true"):
        return {
            "valid": False,
            "reason": "wallbox_native_control_disabled",
            "authority_confirmed": True,
        }
    return {
        "valid": True,
        "reason": "wallbox_runtime_context_valid",
        "authority_confirmed": True,
    }


def _wallbox_context_safe_handoff(charger, reason):
    """Treiberweise Übergabe in Befehlsruhe; sendet nie WB-/Phasen-/CP-Schreibzugriffe."""
    driver_name = charger.__class__.__name__ if charger is not None else "unknown"
    result = {
        "driver": driver_name,
        "reason": str(reason or "runtime_context_invalid"),
        "hardware_write": False,
        "phase_action": False,
        "control_pilot_action": False,
        "heatpump_action": False,
    }
    if charger is not None and hasattr(charger, "suspend_external_control"):
        charger.suspend_external_control("Runtime-Kontext/Owner ungültig")
        result.update({
            "status": "confirmed",
            "confirmed": True,
            "strategy": "stop_set_extern_refresh_and_close_rscp",
        })
    elif driver_name == "OpenWBCharger":
        # openWB bleibt Owner des Ladepunkts. Es wird weder ein weiterer
        # Secondary-Heartbeat noch ein Primary-Befehl gesendet; der eigene
        # Timeout-/Autonomievertrag gilt.
        state = getattr(charger, "state", None)
        if isinstance(state, dict):
            state["control_status"] = "context_invalid_command_silence"
            state["last_heartbeat_ok"] = False
        result.update({
            "status": "timeout_pending",
            "confirmed": False,
            "strategy": "stop_openwb_commands_and_heartbeat",
        })
    elif driver_name == "OpenWBProCharger":
        result.update({
            "status": "timeout_pending",
            "confirmed": False,
            "strategy": "stop_openwb_pro_get_and_post_wait_for_device_timeout",
        })
    elif driver_name == "GoECharger":
        # go-e FRC kann persistent bleiben. Ohne Readback/HIL ist ein geratener
        # neutraler Schreibzugriff verboten; dies bleibt daher ein explizites
        # hartes Feldgate.
        result.update({
            "status": "unconfirmed_persistent_driver",
            "confirmed": False,
            "strategy": "block_new_commands_no_guessed_frc_write",
        })
    else:
        result.update({
            "status": "unconfirmed_unknown_driver",
            "confirmed": False,
            "strategy": "block_new_commands",
        })
    try:
        charger._command_gate_safe_handoff = dict(result)
    except Exception:
        pass
    return result


def _wallbox_runtime_validator(c_data, charger, owner_token):
    def validate():
        authority = _wallbox_narrow_runtime_context_status()
        if authority.get("hard_authority_block") is True:
            return authority
        if not isinstance(c_data, dict) or c_data.get("charger") is not charger:
            authority.update({"valid": False, "reason": "wallbox_owner_binding_lost"})
            return authority
        if c_data.get("_command_owner_lease_token") is not owner_token:
            authority.update({"valid": False, "reason": "wallbox_owner_lease_replaced"})
            return authority
        return authority
    return validate


def _update_command_gate_context(chargers, wb_charge_mode=None, wb_locked=None, native_enabled=True):
    """Keep the driver-level command gate aligned with the current public mode."""
    wb_charge_mode = wb_charge_mode if isinstance(wb_charge_mode, dict) else {}
    wb_locked = wb_locked if isinstance(wb_locked, dict) else {}
    for c_data in chargers or []:
        try:
            c_id = int(c_data.get("id", 0) or 0)
            charger = c_data.get("charger")
            public_mode = normalize_wb_mode(wb_charge_mode.get(c_id, MODE_OFF))
            owner_token = c_data.get("_command_owner_lease_token")
            if owner_token is None:
                owner_token = object()
                c_data["_command_owner_lease_token"] = owner_token
            owner_lease_expires_ts = time.time() + WALLBOX_COMMAND_OWNER_LEASE_S
            c_data["_command_owner_lease_expires_ts"] = owner_lease_expires_ts
            command_gate.configure_charger(
                charger,
                wb_id=c_id,
                mode=public_mode,
                native_enabled=bool(native_enabled),
                locked=bool(wb_locked.get(c_id, False)),
                owner="wallbox_manager",
                runtime_validation_required=True,
                runtime_validator=_wallbox_runtime_validator(c_data, charger, owner_token),
                safe_handoff=_wallbox_context_safe_handoff,
                owner_lease_token=owner_token,
                owner_lease_expires_ts=owner_lease_expires_ts,
            )
        except Exception:
            pass

def _set_command_gate_observe_only(chargers, observe_only=False):
    for c_data in chargers or []:
        try:
            charger = c_data.get("charger")
            if charger is None:
                continue
            ctx = getattr(charger, "_command_gate_context", {}) or {}
            if not isinstance(ctx, dict):
                ctx = {}
            primary_openwb = bool(
                charger.__class__.__name__ == "OpenWBCharger"
                and getattr(charger, "primary_mode_enabled", False)
            )
            physical_blocked = bool(c_data.get("_physical_output_blocked", False))
            ctx["observe_only"] = bool(
                physical_blocked or (observe_only and primary_openwb)
            )
            if physical_blocked:
                ctx["reason"] = str(
                    c_data.get("_physical_output_block_reason")
                    or "physical_output_identity_blocked"
                )
            elif ctx["observe_only"]:
                ctx["reason"] = "openwb_primary_observe_only"
            elif ctx.get("reason") in (
                "openwb_primary_observe_only",
                "physical_output_identity_blocked",
            ):
                ctx.pop("reason", None)
            charger._command_gate_context = ctx
        except Exception:
            pass

_NATIVE_E3DC_HARD_STOP_REASON_PREFIXES = (
    "battery_departure",
    "bev_full_blocked",
    "emergency",
    "grid_window_end",
    "manual",
    "mode0",
    "no_vehicle_connected",
    "native_battery_drain_zero_budget",
    "planned",
    "predump_exit",
    "priority",
    "schedule",
    "start_rejected",
    "target_kwh_reached",
    "target_soc_reached",
    "user",
    "vehicle_charge_ended",
    "wbminsoc_floor_battery_stop",
    "wbminsoc_floor_cloud_stop",
    "wbminsoc_floor_grid_stop",
    "zero_budget_stop",
)


def _native_e3dc_hard_stop_allowed(reason):
    """Return True only for native E3DC stops that may toggle force_state=1."""
    reason_text = str(reason or "").strip().lower()
    if not reason_text:
        return False
    return any(reason_text.startswith(prefix) for prefix in _NATIVE_E3DC_HARD_STOP_REASON_PREFIXES)


def _valid_typed_wallbox_stop_authority(value):
    """Akzeptiere ausschließlich den vollständigen finalen Stopvertrag."""

    if not isinstance(value, dict):
        return False
    return value == wallbox_decision.final_stop_authority_contract()


def _e3dc_native_verified_active_charge(c_data):
    """Return true when independent wallbox telemetry proves an active charge."""
    if not isinstance(c_data, dict):
        return False
    status = c_data.get("last_valid")
    if not isinstance(status, dict) or not status:
        return False
    if (
        status.get("driver_status_valid") is not True
        or status.get("driver_status_stale") is not False
        or status.get("driver_status_degraded") is not False
        or status.get("driver_status_glitch") is not False
        or status.get("driver_status_plausible") is False
    ):
        return False
    # Ein älterer, abgeleiteter Charge-Contract darf keine native Abort-Flanke
    # autorisieren. Maßgeblich ist ausschließlich der frische Treiberstatus.
    return bool(
        status.get("charge_counts_as_real") is True
        or _wb_status_real_charging(status)
        or _wb_status_real_power(status) > 500.0
    )


def _mark_manager_stop_display_pending(c_data, reason="", *, now_ts=None, hold_s=30.0):
    if not isinstance(c_data, dict):
        return
    now_value = time.time() if now_ts is None else float(now_ts)
    hold_value = max(5.0, min(45.0, _cfg_float(hold_s, 30.0)))
    c_data["_manager_stop_display_since_ts"] = now_value
    c_data["_manager_stop_display_until_ts"] = now_value + hold_value
    c_data["_manager_stop_display_reason"] = str(reason or "stop")


def _manager_stop_display_state(c_data, *, now_ts=None):
    if not isinstance(c_data, dict):
        return {"active": False}
    now_value = time.time() if now_ts is None else float(now_ts)
    until_ts = _cfg_float(c_data.get("_manager_stop_display_until_ts"), 0.0)
    if until_ts <= now_value:
        return {"active": False}
    since_ts = _cfg_float(c_data.get("_manager_stop_display_since_ts"), 0.0)
    if since_ts <= 0.0:
        since_ts = _cfg_float(c_data.get("_last_manager_stop_request_ts"), now_value)
    return {
        "active": True,
        "since_ts": since_ts,
        "until_ts": until_ts,
        "age_s": max(0.0, now_value - since_ts),
        "remaining_s": max(0.0, until_ts - now_value),
        "reason": str(c_data.get("_manager_stop_display_reason") or c_data.get("_last_manager_zero_anchor_reason") or "stop"),
    }


def _wallbox_countdown_remaining_s(until_ts, now_ts):
    try:
        until_value = float(until_ts or 0.0)
        now_value = float(now_ts)
    except (TypeError, ValueError):
        return 0
    if until_value <= now_value:
        return 0
    return max(0, int(round(until_value - now_value)))


def _attach_wallbox_countdown_diagnostics(wb_detail, c_data, *, now_ts=None):
    """Ergänzt Diagnose-Restzeiten aus aktiven Schutz- und Haltefenstern."""
    if not isinstance(wb_detail, dict) or not isinstance(c_data, dict):
        return
    now_value = time.time() if now_ts is None else float(now_ts)
    countdown_sources = {
        "openwb_pro_session_phase_wait_remaining_s": "_openwb_pro_phase_wait_until",
        "openwb_pro_session_stop_remaining_s": "_manager_stop_display_until_ts",
        "openwb_pro_session_start_hold_remaining_s": "_phase_1p_start_hold_until",
        "openwb_pro_session_wakeup_remaining_s": "_openwb_pro_start_wakeup_allowed_after",
    }
    for detail_key, source_key in countdown_sources.items():
        wb_detail[detail_key] = _wallbox_countdown_remaining_s(c_data.get(source_key, 0.0), now_value)
    last_executed_command = c_data.get("_last_executed_command")
    wb_detail["last_executed_command"] = (
        last_executed_command
        if isinstance(last_executed_command, dict)
        else None
    )
    status_valid = bool(
        wb_detail.get("driver_status_valid", True)
        and not wb_detail.get("driver_status_stale", False)
    )
    offered_amp = max(
        _cfg_float(wb_detail.get("offered_current_raw"), 0.0),
        _cfg_float(wb_detail.get("evse_current"), 0.0),
        _cfg_float(wb_detail.get("amp"), 0.0),
    )
    charge_truth = wallbox_phase_transition.normalize_charge_truth(
        wb_detail.get("charge_truth"),
        connected=wb_detail.get("plug") if "plug" in wb_detail else None,
        offered_amp=offered_amp,
        status_valid=status_valid,
    )
    inhibit_evidence = c_data.get("_inhibit_owner_evidence")
    inhibit_owner = wallbox_phase_transition.explicit_inhibit_owner(
        inhibit_evidence,
        status_valid=status_valid,
    )
    dimensions = wallbox_phase_transition.status_dimensions(
        c_data.get("_wallbox_phase_transition_reservation"),
        charge_truth=charge_truth,
        inhibit_owner=inhibit_owner,
        now_ts=now_value,
    )
    wb_detail.update(dimensions)
    wb_detail["charge_truth"] = charge_truth


def _attach_wallbox_actuator_contract_diagnostics(wb_detail, c_data):
    """Projiziere die neue Aktorkette kompakt in die bestehende Diagnose.

    Der vollständige Audit-Verlauf bleibt intern. Im Live-Payload erscheinen
    nur Capability, geplantes und tatsächlich zugelassenes Final-Intent sowie
    ein Zähler für erkannte Legacy-Mehrfachausgänge.
    """

    if not isinstance(wb_detail, dict) or not isinstance(c_data, dict):
        return
    for source_key, target_key in (
        ("_wallbox_capability", "wallbox_capability"),
        ("_wallbox_demand_contract", "wallbox_demand_contract"),
        ("_planned_actuator_intent", "planned_actuator_intent"),
        ("_admitted_actuator_intent", "admitted_actuator_intent"),
    ):
        value = c_data.get(source_key)
        if isinstance(value, dict):
            wb_detail[target_key] = dict(value)
    audit = c_data.get("_admitted_actuator_intent_audit")
    audit = audit if isinstance(audit, list) else []
    conflicts = sum(
        1
        for item in audit
        if isinstance(item, dict)
        and item.get("legacy_multiple_normal_intent_detected") is True
    )
    wb_detail["admitted_actuator_intent_audit_count"] = len(audit)
    wb_detail["admitted_actuator_intent_conflict_count"] = conflicts


def _wallbox_stop_observation_contract(status, *, now_ts=None):
    """Erzeuge einen nicht mutierenden Vertrag nur aus dem aktuellen Readback."""

    status_sample = dict(status) if isinstance(status, dict) else {}
    for key in (
        "charge_contract",
        "charge_truth",
        "charge_is_charging",
        "charge_counts_as_real",
        "charge_confidence",
        "charge_source",
        "charge_power_w",
        "charge_raw_power_w",
        "phantom_power_w",
        "charge_energy_increasing",
        "charge_energy_delta_wh",
        "charge_energy_source",
    ):
        status_sample.pop(key, None)
    return wallbox_decision.charge_observation_contract(
        status_sample,
        previous=None,
        now_ts=time.time() if now_ts is None else now_ts,
    )


def _wallbox_detail_charge_contract(status, c_data, stop_state, *, now_ts=None):
    """Binde das Stop-Overlay vor jeder Cache-Projektion an den Rohstatus."""

    now_value = time.time() if now_ts is None else now_ts
    stop_active = bool(
        isinstance(stop_state, dict) and stop_state.get("active", False)
    )
    stop_observation = (
        _wallbox_stop_observation_contract(status, now_ts=now_value)
        if stop_active
        else None
    )
    data = c_data if isinstance(c_data, dict) else {}
    charge_contract = dict(data.get("_charge_contract") or {})
    if not charge_contract:
        charge_contract = _wallbox_charge_observation_contract(
            status,
            data,
            now_ts=now_value,
        )
    _apply_charge_contract_to_status(status, charge_contract)
    if stop_active:
        charge_contract = _apply_manager_stop_display_to_status(
            status,
            charge_contract,
            stop_state,
            observation_contract=stop_observation,
        )
    return charge_contract


def _apply_manager_stop_display_to_status(
    status,
    charge_contract,
    stop_state,
    *,
    observation_contract,
):
    if not isinstance(stop_state, dict) or not stop_state.get("active", False):
        return charge_contract
    pending_contract = dict(observation_contract or {})
    status_item = status if isinstance(status, dict) else {}
    fresh_real_charging = bool(
        status_item.get("driver_status_valid") is True
        and status_item.get("driver_status_stale") is False
        and status_item.get("driver_status_degraded") is False
        and status_item.get("driver_status_glitch") is False
        and pending_contract.get("status_valid") is True
        and pending_contract.get("truth") == "charging"
        and pending_contract.get("is_charging") is True
        and pending_contract.get("counts_as_real_charge") is True
    )
    if fresh_real_charging:
        # Der bestätigte Stop-Receipt beschreibt nur die gesendete Absicht.
        # Solange ein ausdrücklich frischer Hardware-Readback weiterhin reale
        # Ladeleistung belegt, bleibt diese physische Wahrheit sichtbar. Der
        # Stop ist in diesem kurzen Fenster ausschließlich ein Diagnoseoverlay.
        pending_contract.update({
            "manager_stop_pending": True,
            "manager_stop_reason": stop_state.get("reason", "stop"),
            "manager_stop_age_s": round(
                _cfg_float(stop_state.get("age_s"), 0.0),
                1,
            ),
        })
        if status is not None:
            status["manager_stop_pending"] = True
            status["manager_stop_reason"] = pending_contract[
                "manager_stop_reason"
            ]
            status["manager_stop_age_s"] = pending_contract[
                "manager_stop_age_s"
            ]
            _apply_charge_contract_to_status(status, pending_contract)
        return pending_contract
    raw_power_w = max(
        _cfg_float(pending_contract.get("raw_power_w"), 0.0),
        _cfg_float(pending_contract.get("power_w"), 0.0),
        _cfg_float(pending_contract.get("phantom_power_w"), 0.0),
    )
    pending_contract.update({
        "truth": "stop_pending",
        "is_charging": False,
        "counts_as_real_charge": False,
        "confidence": "manager_stop_pending",
        "source": "manager_stop_pending",
        "power_w": 0.0,
        "phantom_power_w": raw_power_w,
        "manager_stop_pending": True,
        "manager_stop_reason": stop_state.get("reason", "stop"),
        "manager_stop_age_s": round(_cfg_float(stop_state.get("age_s"), 0.0), 1),
    })
    if status is not None:
        status["charging"] = False
        status["charge_state"] = False
        status["real_power_w"] = 0.0
        status["power_w"] = 0.0
        status["phase_power_l1_w"] = 0.0
        status["phase_power_l2_w"] = 0.0
        status["phase_power_l3_w"] = 0.0
        status["phase_power_sum_w"] = 0.0
        status["phase_power_verified"] = False
        status["manager_stop_pending"] = True
        status["manager_stop_reason"] = pending_contract["manager_stop_reason"]
        status["manager_stop_age_s"] = pending_contract["manager_stop_age_s"]
        _apply_charge_contract_to_status(status, pending_contract)
    return pending_contract


def _record_unconfirmed_wallbox_stop(
    c_data,
    *,
    reason,
    blocker,
    driver_command_ok=False,
    typed_stop_authority=False,
    cycle_token="",
):
    """Bewahrt bei einem unbelegten Stop ausschließlich frische Istwerte."""

    data = c_data if isinstance(c_data, dict) else {}
    status = data.get("last_valid")
    status = status if isinstance(status, dict) else {}
    projection = _project_wallbox_current_state(data, status)
    hardware_charging = bool(
        _wb_status_real_charging(status)
        or _wb_status_real_power(status) > 500.0
    )
    data["_wallbox_stop_outcome"] = {
        "contract": "wallbox_stop_outcome_v1",
        "reason": str(reason or "stop"),
        "typed_stop_authority": bool(typed_stop_authority),
        "driver_command_ok": bool(driver_command_ok),
        "command_ok": False,
        "command_receipt_confirmed": False,
        "applied_confirmed": False,
        "hardware_charging": hardware_charging,
        "projection_source": str((projection or {}).get("source") or ""),
        "cycle_token": str(cycle_token or data.get("_wallbox_cycle_token") or ""),
        "blocker": str(blocker or "stop_receipt_missing"),
    }
    return False


def _send_wallbox_stop_command(
    c_data,
    c_id=None,
    reason="",
    _guard_checked=False,
    stop_authority=None,
    require_typed_stop_authority=False,
):
    """Sende einen Stop und bestätige ihn nur über einen neuen Zyklusbeleg."""

    if not isinstance(c_data, dict):
        return False
    charger = c_data.get("charger")
    reason_code = str(reason or "stop")
    if charger is None:
        return _record_unconfirmed_wallbox_stop(
            c_data,
            reason=reason_code,
            blocker="charger_missing",
        )
    typed_authority = (
        dict(stop_authority)
        if _valid_typed_wallbox_stop_authority(stop_authority)
        else {}
    )
    if typed_authority:
        # Ein finaler Stop widerruft zuerst jeden alten positiven
        # Treiber-Heartbeat. Der typisierte Stop selbst bleibt unter diesem
        # Veto zulässig und wird weiterhin nur bei frischem Ladebeleg als
        # native Abort-Flanke gesendet.
        command_gate.set_storage_power_budget_hard_block(
            charger,
            True,
            reason=reason_code,
        )

    if not _guard_checked:
        stop_intent = {
            "kind": "stop",
            "method": "stop",
            "reason": reason_code,
        }
        if (
            typed_authority
            and reason_code in ("emergency_stop", "not_aus", "webui_not_aus")
        ):
            # Die bereits validierte Stop-Autorität muss vor dem ersten
            # Anti-Flatter-Guard sichtbar sein. Ein Freitextgrund allein
            # erhält diesen Marker nie und bleibt bei Guardfehler fail-closed.
            stop_intent["stop_authority"] = dict(typed_authority)
            stop_intent["_typed_emergency_stop_intent"] = True
        if not _wallbox_command_guard_allows(
            c_data,
            stop_intent,
            c_id=c_id,
            reason=reason_code,
        ):
            return _record_unconfirmed_wallbox_stop(
                c_data,
                reason=reason_code,
                blocker="command_guard",
            )

    hard_stop_allowed = bool(
        (
            not require_typed_stop_authority
            and _native_e3dc_hard_stop_allowed(reason_code)
        )
        or typed_authority
    )
    command = _wallbox_command_executor.stop_command(
        charger,
        hard_stop_allowed=hard_stop_allowed,
        stop_authority=typed_authority,
        reason=reason_code,
    )
    if not command:
        _discard_wallbox_command_guard_pending(c_data)
        return _record_unconfirmed_wallbox_stop(
            c_data,
            reason=reason_code,
            blocker="stop_command_unavailable",
            typed_stop_authority=bool(typed_authority),
        )
    command["_canonical_stop_command"] = True
    command["_control_guard_checked"] = True
    previous_receipt = c_data.get("_last_executed_command")
    driver_ok = bool(
        _execute_wallbox_driver_command(
            c_data,
            command,
            c_id=c_id,
            reason=reason_code,
        )
    )
    receipt = c_data.get("_last_executed_command")
    cycle_token = str(c_data.get("_wallbox_cycle_token") or "")
    receipt_is_new = bool(
        cycle_token
        and isinstance(receipt, dict)
        and receipt is not previous_receipt
        and str(receipt.get("cycle_token") or "") == cycle_token
        and str(receipt.get("method") or "")
        == str(command.get("method") or "")
        and str(receipt.get("reason") or "") == reason_code
    )
    native_stop_edge_confirmed = bool(
        receipt_is_new
        and command.get("method") == "set_amp_sonnenmodus"
        and receipt.get("force_state") == 1
        and receipt.get("wire_receipt_contract")
        == "e3dc_wbchar6_wire_receipt_v1"
        and receipt.get("wire_receipt_new") is True
        and int(receipt.get("wire_receipt_seq", 0) or 0) > 0
        and _cfg_float(receipt.get("wire_receipt_ts"), 0.0) > 0.0
        and int(receipt.get("wire_abort_flag", 0) or 0) == 1
        and receipt.get("wire_heartbeat") is False
        and receipt.get("stop_edge_issued") is True
    )
    non_native_stop_confirmed = bool(
        receipt_is_new
        and (
            (
                command.get("method") == "set_amp_and_state"
                and _cfg_float(command.get("amp"), 0.0) <= 0.0
                and command.get("force_state") == 1
            )
            or (
                command.get("method") == "set_direct_current"
                and _cfg_float(command.get("amp"), 0.0) <= 0.0
            )
        )
    )
    receipt_confirmed = bool(
        driver_ok
        and (native_stop_edge_confirmed or non_native_stop_confirmed)
    )
    c_data["_wallbox_stop_outcome"] = {
        "contract": "wallbox_stop_outcome_v1",
        "reason": reason_code,
        "typed_stop_authority": bool(typed_authority),
        "driver_command_ok": bool(driver_ok),
        "command_ok": bool(receipt_confirmed),
        "command_receipt_confirmed": bool(receipt_confirmed),
        "applied_confirmed": False,
        "hardware_charging": bool(
            _wb_status_real_charging(c_data.get("last_valid"))
            or _wb_status_real_power(c_data.get("last_valid")) > 500.0
        ),
        "cycle_token": str(c_data.get("_wallbox_cycle_token") or ""),
    }
    if receipt_confirmed:
        _commit_wallbox_command_guard_after_receipt(
            c_data,
            command,
            previous_receipt=previous_receipt,
            stop_receipt_confirmed=True,
        )
    else:
        _discard_wallbox_command_guard_pending(c_data)
    if not receipt_confirmed:
        if command.get("method") == "set_amp_sonnenmodus":
            c_data["_native_e3dc_hard_stop_suppressed"] = reason_code
        return _record_unconfirmed_wallbox_stop(
            c_data,
            reason=reason_code,
            blocker=(
                "physical_stop_receipt_missing"
                if driver_ok
                else "driver_command_failed"
            ),
            driver_command_ok=driver_ok,
            typed_stop_authority=bool(typed_authority),
            cycle_token=cycle_token,
        )

    now_value = time.time()
    # Erst der neue Beleg macht den Stop zu Managerzustand. Ein blockierter
    # oder nur auf 6 A entschärfter Versuch darf weder Ladeende-Evidenz löschen
    # noch Wiederanlaufzeiten erneuern.
    _clear_wallbox_vehicle_finished_candidates(c_data)
    c_data["_last_manager_stop_request_ts"] = now_value
    c_data["_last_manager_zero_anchor_ts"] = now_value
    c_data["_last_manager_zero_anchor_reason"] = reason_code
    c_data.pop("_native_e3dc_floor_replug_evidence", None)
    c_data["_manager_zero_anchor_active"] = True
    c_data["_manager_zero_anchor_contract"] = {
        "contract": "wallbox_manager_zero_anchor_v1",
        "owner": "wallbox_manager",
        "class": (
            "temporary_policy_zero"
            if reason_code in openwb_pro_session.RELEASABLE_ZERO_ANCHOR_REASONS
            else "hard_stop"
        ),
        "reason_code": reason_code,
        "session_vehicle_key": str(c_data.get("_session_vehicle_key") or ""),
        "plug_session_id": str(
            c_data.get("_openwb_pro_plug_session_id")
            or c_data.get("_wallbox_plug_episode_id")
            or ""
        ),
        "created_ts": now_value,
        "release_condition": (
            "next_positive_executable_policy"
            if reason_code in openwb_pro_session.RELEASABLE_ZERO_ANCHOR_REASONS
            else "explicit_policy_or_session_release"
        ),
    }
    c_data["_aha_real_charge_confirmed"] = False
    c_data["_aha_real_charge_confirmed_since"] = 0.0
    c_data["_real_charge_since"] = 0.0
    c_data["_openwb_start_reject_anchor_ts"] = 0.0
    c_data.pop("_native_e3dc_hard_stop_suppressed", None)
    _mark_manager_stop_display_pending(
        c_data,
        reason_code,
        now_ts=now_value,
    )
    return True


def _send_wallbox_stop_command_if_due(
    c_data,
    *,
    c_id=None,
    reason="",
    stop_authority=None,
    e3dc_native_toggle=False,
    stop_edge_due=False,
    now_ts=None,
):
    """Sende die finalisierte Stopkante höchstens bei expliziter Fälligkeit."""

    if not isinstance(c_data, dict):
        return False
    if not stop_edge_due:
        return None
    charger = c_data.get("charger")
    native_charger = e3dc_session.is_e3dc_native_charger(charger)
    typed_authority = _valid_typed_wallbox_stop_authority(stop_authority)
    if not typed_authority and not native_charger:
        return _record_unconfirmed_wallbox_stop(
            c_data,
            reason=str(reason or "stop"),
            blocker="typed_stop_authority_missing",
        )
    confirmed = bool(
        _send_wallbox_stop_command(
            c_data,
            c_id=c_id,
            reason=reason,
            stop_authority=stop_authority,
            require_typed_stop_authority=True,
        )
    )
    if not confirmed:
        return False
    confirmed_ts = float(now_ts if now_ts is not None else time.time())
    c_data["current_set_amp"] = 0
    c_data["is_charging"] = False
    c_data["last_start_ts"] = 0.0
    c_data["_wb_stop_sent_active"] = True
    _record_wallbox_restart_cooldown(
        c_data,
        stop_ts=confirmed_ts,
        reason=str(reason or "stop"),
    )
    if native_charger or bool(e3dc_native_toggle):
        c_data["abort_cooldown_ts"] = confirmed_ts
    return True


def _record_wallbox_restart_cooldown(c_data, *, stop_ts, reason=""):
    """Bindet den generischen Wiederanlaufabstand an Stopart und Stecksession.

    ``_last_stop_toggle_ts`` bleibt als bestehender Receipt-Zeitstempel für
    Gruppen- und Legacylogik erhalten. Nur der daraus abgeleitete Startblock
    wird für openWB Pro typisiert: vorübergehende Policy-Nullanker gehören
    genau zu der Stecksession, in der der Stop bestätigt wurde. Ein reiner
    ``hold_target_below_minimum``-Stop bei einem frisch verbundenen, noch nie
    ladenden Fahrzeug ist keine Wiederanlaufkante und erzeugt deshalb keinen
    zusätzlichen 60-s-Block. Nutzer-, Safety-, Recovery-, CP- und
    Phasenbarrieren werden hier weder gelöst noch verändert.
    """

    data = c_data if isinstance(c_data, dict) else {}
    stop_value = _cfg_float(stop_ts, 0.0)
    reason_code = str(reason or "stop")
    data["_last_stop_toggle_ts"] = stop_value

    anchor = data.get("_manager_zero_anchor_contract")
    anchor = anchor if isinstance(anchor, dict) else {}
    plug_session_id = str(
        data.get("_openwb_pro_plug_session_id")
        or data.get("_wallbox_plug_episode_id")
        or ""
    )
    anchor_is_exact = bool(
        anchor.get("contract") == "wallbox_manager_zero_anchor_v1"
        and anchor.get("owner") == "wallbox_manager"
        and str(anchor.get("reason_code") or "") == reason_code
        and str(anchor.get("plug_session_id") or "") == plug_session_id
    )
    temporary_policy_zero = bool(
        anchor_is_exact
        and anchor.get("class") == "temporary_policy_zero"
        and reason_code in openwb_pro_session.RELEASABLE_ZERO_ANCHOR_REASONS
    )
    status = data.get("last_valid")
    status = status if isinstance(status, dict) else {}
    fresh_connected_idle = bool(
        status.get("driver_status_valid") is True
        and status.get("driver_status_stale") is not True
        and status.get("driver_status_degraded") is not True
        and status.get("driver_status_glitch") is not True
        and status.get("driver_status_plausible") is not False
        and _wb_status_connected(status)
        and not _wb_status_real_charging(status)
        and _wb_status_real_power(status) <= 100.0
    )
    initial_idle_policy_hold = bool(
        openwb_pro_session.is_openwb_pro_charger(data.get("charger"))
        and temporary_policy_zero
        and reason_code == "hold_target_below_minimum"
        and plug_session_id
        and not bool(data.get("_had_real_charge_in_session", False))
        and fresh_connected_idle
    )
    data["_wallbox_restart_cooldown_contract"] = {
        "contract": "wallbox_restart_cooldown_v1",
        "stop_ts": stop_value,
        "reason_code": reason_code,
        "stop_class": (
            "temporary_policy_zero"
            if temporary_policy_zero
            else "protected_or_unclassified_stop"
        ),
        "scope": (
            "plug_session"
            if temporary_policy_zero
            else "protected_global"
        ),
        "plug_session_id": plug_session_id,
        "had_real_charge_in_session": bool(
            data.get("_had_real_charge_in_session", False)
        ),
        "fresh_connected_idle": fresh_connected_idle,
        "initial_idle_policy_hold": initial_idle_policy_hold,
        "restart_delay_required": not initial_idle_policy_hold,
    }
    return dict(data["_wallbox_restart_cooldown_contract"])


def _release_wallbox_restart_cooldown_for_active_mode_change(
    c_data,
    *,
    previous_public_mode,
    new_public_mode,
    now_ts,
    restart_delay_s,
):
    """Löst nur einen typisierten Policy-Stop bei echtem Aktivmoduswechsel.

    Der Stop-Zeitstempel bleibt als Receipt und Generationsbeleg erhalten.
    Freigegeben wird ausschließlich der generische Stop/Start-Abstand; Nutzer-
    Aus, Safety-/Recovery-Sperren, CP-Sequenzen und der persistente
    Phasenwechsel-Schutz werden weder gelesen noch verändert.
    """

    data = c_data if isinstance(c_data, dict) else {}
    previous_mode = normalize_wb_mode(previous_public_mode)
    new_mode = normalize_wb_mode(new_public_mode)
    now_value = _cfg_float(now_ts, 0.0)
    delay_value = max(0.0, _cfg_float(restart_delay_s, 0.0))
    stop_ts = _cfg_float(data.get("_last_stop_toggle_ts"), 0.0)
    remaining_s = max(
        0.0,
        delay_value - max(0.0, now_value - stop_ts),
    )
    result = {
        "contract": "wallbox_restart_cooldown_mode_change_release_v1",
        "released": False,
        "reason": "release_conditions_not_met",
        "previous_public_mode": previous_mode,
        "new_public_mode": new_mode,
        "remaining_s": remaining_s,
        "hardware_write": False,
    }
    if not openwb_pro_session.is_openwb_pro_charger(data.get("charger")):
        result["reason"] = "openwb_pro_required"
        return result
    if (
        previous_mode == MODE_OFF
        or new_mode == MODE_OFF
        or previous_mode == new_mode
    ):
        result["reason"] = "active_public_mode_unchanged_or_off"
        return result
    if stop_ts <= 0.0 or remaining_s <= 0.0 or now_value < stop_ts:
        result["reason"] = "restart_delay_not_active"
        return result

    binding = data.get("_wallbox_restart_cooldown_contract")
    binding = binding if isinstance(binding, dict) else {}
    bound_session_id = str(binding.get("plug_session_id") or "")
    current_session_id = str(
        data.get("_openwb_pro_plug_session_id")
        or data.get("_wallbox_plug_episode_id")
        or ""
    )
    reason_code = str(binding.get("reason_code") or "")
    binding_valid = bool(
        binding.get("contract") == "wallbox_restart_cooldown_v1"
        and abs(_cfg_float(binding.get("stop_ts"), 0.0) - stop_ts)
        <= 0.001
        and binding.get("scope") == "plug_session"
        and binding.get("stop_class") == "temporary_policy_zero"
        and reason_code in openwb_pro_session.RELEASABLE_ZERO_ANCHOR_REASONS
        and binding.get("restart_delay_required") is True
        and bound_session_id
        and bound_session_id == current_session_id
    )
    if not binding_valid:
        result["reason"] = "typed_temporary_stop_binding_invalid"
        return result

    release = {
        "contract": "wallbox_restart_cooldown_active_mode_release_v1",
        "reason": "operator_active_mode_change",
        "stop_ts": stop_ts,
        "reason_code": reason_code,
        "plug_session_id": bound_session_id,
        "previous_public_mode": previous_mode,
        "new_public_mode": new_mode,
        "released_ts": now_value,
        "hardware_write": False,
    }
    updated = dict(binding)
    updated["active_mode_change_release"] = release
    data["_wallbox_restart_cooldown_contract"] = updated
    result.update({
        "released": True,
        "reason": "operator_active_mode_change",
        "release": dict(release),
    })
    return result


def _wallbox_restart_cooldown_gate_contract(
    c_data,
    *,
    now_ts,
    restart_delay_s,
):
    """Bewertet nur den generischen Stop/Start-Abstand, fail-closed bei Altstand."""

    data = c_data if isinstance(c_data, dict) else {}
    now_value = _cfg_float(now_ts, 0.0)
    delay_value = max(0.0, _cfg_float(restart_delay_s, 0.0))
    stop_ts = _cfg_float(data.get("_last_stop_toggle_ts"), 0.0)
    remaining_s = max(0.0, delay_value - max(0.0, now_value - stop_ts))
    result = {
        "contract": "wallbox_restart_cooldown_gate_v1",
        "active": bool(stop_ts > 0.0 and remaining_s > 0.0),
        "remaining_s": remaining_s,
        "reason": "legacy_restart_delay",
        "stop_ts": stop_ts,
        "hardware_write": False,
    }
    if not result["active"]:
        result["reason"] = "restart_delay_elapsed_or_missing"
        return result
    if not openwb_pro_session.is_openwb_pro_charger(data.get("charger")):
        return result

    binding = data.get("_wallbox_restart_cooldown_contract")
    binding = binding if isinstance(binding, dict) else {}
    bound_session_id = str(binding.get("plug_session_id") or "")
    current_session_id = str(
        data.get("_openwb_pro_plug_session_id")
        or data.get("_wallbox_plug_episode_id")
        or ""
    )
    binding_valid = bool(
        binding.get("contract") == "wallbox_restart_cooldown_v1"
        and _cfg_float(binding.get("stop_ts"), 0.0) > 0.0
        and abs(_cfg_float(binding.get("stop_ts"), 0.0) - stop_ts) <= 0.001
        and str(binding.get("reason_code") or "")
        and binding.get("scope") in ("plug_session", "protected_global")
    )
    result.update({
        "binding_valid": binding_valid,
        "bound_session_id": bound_session_id,
        "current_session_id": current_session_id,
        "stop_reason": str(binding.get("reason_code") or ""),
        "stop_class": str(binding.get("stop_class") or ""),
    })
    if not binding_valid:
        result["reason"] = "unbound_restart_delay_preserved"
        return result

    initial_idle_release = bool(
        binding.get("scope") == "plug_session"
        and binding.get("stop_class") == "temporary_policy_zero"
        and str(binding.get("reason_code") or "")
        == "hold_target_below_minimum"
        and binding.get("initial_idle_policy_hold") is True
        and binding.get("restart_delay_required") is False
        and binding.get("had_real_charge_in_session") is False
        and binding.get("fresh_connected_idle") is True
        and bound_session_id
        and bound_session_id == current_session_id
    )
    if initial_idle_release:
        result.update({
            "active": False,
            "remaining_s": 0.0,
            "reason": "initial_idle_policy_hold_not_a_restart",
        })
        return result

    previous_session_release = bool(
        binding.get("scope") == "plug_session"
        and binding.get("stop_class") == "temporary_policy_zero"
        and bound_session_id
        and current_session_id
        and bound_session_id != current_session_id
    )
    if previous_session_release:
        result.update({
            "active": False,
            "remaining_s": 0.0,
            "reason": "temporary_stop_from_previous_plug_session",
        })
        return result

    mode_release = binding.get("active_mode_change_release")
    mode_release = mode_release if isinstance(mode_release, dict) else {}
    release_stop_ts = _cfg_float(mode_release.get("stop_ts"), 0.0)
    release_ts = _cfg_float(mode_release.get("released_ts"), 0.0)
    release_previous_mode = normalize_wb_mode(
        mode_release.get("previous_public_mode")
    )
    release_new_mode = normalize_wb_mode(
        mode_release.get("new_public_mode")
    )
    active_mode_release_valid = bool(
        mode_release.get("contract")
        == "wallbox_restart_cooldown_active_mode_release_v1"
        and mode_release.get("reason") == "operator_active_mode_change"
        and abs(release_stop_ts - stop_ts) <= 0.001
        and str(mode_release.get("reason_code") or "")
        == str(binding.get("reason_code") or "")
        and str(mode_release.get("plug_session_id") or "")
        == bound_session_id
        and bound_session_id == current_session_id
        and binding.get("scope") == "plug_session"
        and binding.get("stop_class") == "temporary_policy_zero"
        and str(binding.get("reason_code") or "")
        in openwb_pro_session.RELEASABLE_ZERO_ANCHOR_REASONS
        and binding.get("restart_delay_required") is True
        and release_previous_mode != MODE_OFF
        and release_new_mode != MODE_OFF
        and release_previous_mode != release_new_mode
        and release_ts >= stop_ts
        and release_ts <= now_value + 5.0
    )
    if active_mode_release_valid:
        result.update({
            "active": False,
            "remaining_s": 0.0,
            "reason": "active_public_mode_change_restart_release",
        })
        return result

    result["reason"] = (
        "same_plug_session_restart_delay"
        if binding.get("scope") == "plug_session"
        else "protected_restart_delay"
    )
    return result


def _native_rscp_session_status_fresh(status):
    """Akzeptiert nur eine aktuelle, plausible RSCP-Beobachtung als Wahrheit."""

    st = status if isinstance(status, dict) else {}
    return bool(
        st
        and st.get("driver_status_valid") is True
        and st.get("driver_status_stale") is False
        and st.get("driver_status_degraded") is not True
        and st.get("driver_status_glitch") is False
        and st.get("driver_status_plausible") is not False
        and st.get("wb_status_valid") is True
        and st.get("rscp_error_active") is not True
    )


def _native_rscp_session_transition(previous, status, *, now_ts=None):
    """Projiziert genau eine frische RSCP-Beobachtung in den Sessionvertrag.

    ``None`` bedeutet bewusst "nicht schreiben": Eine unbekannte
    Steckerbeobachtung oder ein stale/glitch Frame darf weder eine laufende
    Sitzung beenden noch eine frische Wahrheit durch einen gehaltenen Wert
    ersetzen.
    """

    if not _native_rscp_session_status_fresh(status):
        return None
    st = status if isinstance(status, dict) else {}
    connected_observation = st.get("car_connected_rscp")
    if type(connected_observation) is not bool:
        return None

    current_ts = int(time.time() if now_ts is None else float(now_ts))
    prev = (
        dict(previous)
        if isinstance(previous, dict) and previous.get("source") == "rscp"
        else {}
    )
    charge_contract = (
        st.get("charge_contract")
        if isinstance(st.get("charge_contract"), dict)
        else {}
    )
    charge_truth = str(
        charge_contract.get("truth") or st.get("charge_truth") or ""
    ).strip().lower()
    if charge_truth not in ("charging", "not_charging"):
        if st.get("charging") is True:
            charge_truth = "charging"
        elif st.get("charging") is False:
            charge_truth = "not_charging"
        else:
            charge_truth = "unknown"

    try:
        measured_power_w = float(st.get("real_power_w", 0.0) or 0.0)
    except (TypeError, ValueError, OverflowError):
        measured_power_w = 0.0
    if not math.isfinite(measured_power_w) or measured_power_w < 0.0:
        measured_power_w = 0.0

    measured_charging = bool(
        connected_observation
        and charge_truth == "charging"
        and measured_power_w > 50.0
    )
    power_w = round(measured_power_w) if measured_charging else 0
    power_source = (
        "rscp_real"
        if measured_charging
        else (
            "idle"
            if not connected_observation or charge_truth == "not_charging"
            else "rscp_fresh_zero"
        )
    )

    previous_connected = prev.get("car_connected") is True
    session_start_ts = prev.get("session_start_ts")
    if connected_observation:
        rscp_start = st.get("session_start_ts")
        if rscp_start not in (None, "", 0, 0.0):
            session_start_ts = rscp_start
        elif not previous_connected or session_start_ts in (None, "", 0, 0.0):
            session_start_ts = current_ts

    session_kwh = prev.get("session_kwh", 0.0)
    rscp_session_kwh = st.get("session_kwh")
    try:
        candidate_session_kwh = float(rscp_session_kwh)
    except (TypeError, ValueError, OverflowError):
        candidate_session_kwh = None
    if (
        candidate_session_kwh is not None
        and math.isfinite(candidate_session_kwh)
        and candidate_session_kwh >= 0.0
    ):
        session_kwh = candidate_session_kwh

    last_real_power_w = prev.get("last_real_power_w", 0)
    last_real_power_ts = prev.get("last_real_power_ts", 0)
    if measured_charging:
        last_real_power_w = round(measured_power_w)
        last_real_power_ts = current_ts

    return {
        "schema_version": "wb_native_rscp_session_v1",
        "source": "rscp",
        "power_w": power_w,
        "power_source": power_source,
        "power_measurement_ts": current_ts if measured_charging else 0,
        "session_kwh": session_kwh,
        "session_start_ts": session_start_ts,
        "car_connected": connected_observation,
        "charge_truth": charge_truth,
        "ts": current_ts,
        # Letzter Realwert ist ausschließlich Diagnose und wird nie als
        # kanonische Leistung oder Integrationsquelle zurückprojiziert.
        "last_real_power_w": last_real_power_w,
        "last_real_power_ts": last_real_power_ts,
    }


def _wallbox_group_deficit_phase_cooldown_remaining_s(c_data, *, now_ts):
    """Der 480-s-Schutz sperrt ausschließlich einen weiteren Phasenwechsel."""

    data = c_data if isinstance(c_data, dict) else {}
    now_value = _cfg_float(now_ts, 0.0)
    until_values = [
        _cfg_float(data.get("_phase_3p_block_until"), 0.0),
        _cfg_float(data.get("_openwb_pro_phase_change_block_until"), 0.0),
    ]
    for key in (
        "_wallbox_phase_transition_reservation",
        "_openwb_pro_phase_sequence",
    ):
        item = data.get(key)
        if not isinstance(item, dict):
            continue
        until_values.extend((
            _cfg_float(item.get("cooldown_until_ts"), 0.0),
            _cfg_float(item.get("phase_change_block_until"), 0.0),
        ))
    last_switch = max(
        _cfg_float(data.get("_last_phase_switch_ts"), 0.0),
        _cfg_float(data.get("last_phase_switch_ts"), 0.0),
    )
    if last_switch > 0.0:
        until_values.append(last_switch + 480.0)
    return max(0.0, max(until_values or [0.0]) - now_value)


def _wallbox_group_deficit_phase_switch_confirmed(c_data, status):
    data = c_data if isinstance(c_data, dict) else {}
    st = status if isinstance(status, dict) else {}
    charger = data.get("charger")
    return bool(
        openwb_pro_session.is_openwb_pro_charger(charger)
        and openwb_pro_session.phase_target_readback_confirmed(st, 1)
    )


def _wallbox_group_deficit_phase_progress_contract(
    c_data,
    status,
    *,
    now_ts,
):
    """Bindet Pending nur an eine nachweislich laufende Pro-Sequenz."""

    data = c_data if isinstance(c_data, dict) else {}
    st = status if isinstance(status, dict) else {}
    charger = data.get("charger")
    if not openwb_pro_session.is_openwb_pro_charger(charger):
        return {
            "contract": "wallbox_group_deficit_phase_progress_v1",
            "sequence_active": False,
            "sequence_failed": False,
            "stage": "unsupported",
            "cp_interrupt_active": False,
        }
    reservation = data.get("_wallbox_phase_transition_reservation")
    reservation = reservation if isinstance(reservation, dict) else {}
    stage = str(reservation.get("stage") or "")
    now_value = _cfg_float(now_ts, 0.0)
    lease_until_ts = max(
        _cfg_float(reservation.get("lease_until_ts"), 0.0),
        _cfg_float(reservation.get("expires_ts"), 0.0),
    )
    lease_current = bool(
        lease_until_ts > 0.0
        and now_value >= 0.0
        and now_value < lease_until_ts
    )
    cp_interrupt_active = bool(
        st.get("cp_interrupt_isactive") is True
        or st.get("phase_transition_active") is True
        or st.get("phase_switch_in_progress") is True
    )
    reservation_active = bool(
        reservation.get("active") is True
        and stage in wallbox_phase_transition.ACTIVE_STAGES
        and stage != "recovery_hold"
        and lease_current
    )
    recovery = data.get("_openwb_pro_phase_recovery_hold")
    recovery = recovery if isinstance(recovery, dict) else {}
    terminal_failure = bool(
        not cp_interrupt_active
        and (
            stage in wallbox_phase_transition.TERMINAL_STAGES
            or stage == "recovery_hold"
            or recovery.get("active") is True
            or (
                bool(reservation)
                and lease_until_ts > 0.0
                and not lease_current
            )
        )
    )
    return {
        "contract": "wallbox_group_deficit_phase_progress_v1",
        "sequence_active": bool(
            cp_interrupt_active or reservation_active
        ),
        "sequence_failed": terminal_failure,
        "stage": stage or "idle",
        "cp_interrupt_active": cp_interrupt_active,
        "sample_ts": max(
            _cfg_float(st.get("native_status_sample_ts"), 0.0),
            _cfg_float(st.get("driver_status_last_ok_ts"), 0.0),
        ),
        "lease_until_ts": lease_until_ts,
        "lease_current": lease_current,
        "now_ts": now_value,
    }


def _wallbox_group_deficit_action_latch_id(material):
    payload = material if isinstance(material, dict) else {}
    encoded = json.dumps(
        payload,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    return "sha256:" + hashlib.sha256(encoded).hexdigest()


def _wallbox_group_deficit_action_binding_matches(
    c_data,
    *,
    expected_action=None,
):
    data = c_data if isinstance(c_data, dict) else {}
    binding = data.get("_wallbox_group_deficit_action_binding")
    generation = data.get("_wallbox_group_deficit_generation_contract")
    if not (
        isinstance(binding, dict)
        and binding.get("schema") == _GROUP_DEFICIT_ACTION_BINDING_SCHEMA
        and binding.get("active") is True
        and isinstance(generation, dict)
        and generation.get("contract")
        == "wallbox_group_deficit_generation_v1"
        and generation.get("binding_ready") is True
    ):
        return False
    if expected_action is not None and str(binding.get("action") or "") != str(
        expected_action
    ):
        return False
    try:
        wb_id = int(data.get("id", 0) or 0)
        binding_wb_id = int(binding.get("wb_id", 0) or 0)
        owner_id = int(generation.get("effective_owner_id", 0) or 0)
        binding_generation = int(binding.get("binding_generation", 0) or 0)
        current_generation = int(generation.get("binding_generation", 0) or 0)
    except (TypeError, ValueError, OverflowError):
        return False
    cycle_token = str(data.get("_wallbox_cycle_token") or "")
    session_id = _wallbox_group_deficit_current_session_id(data)
    return bool(
        wb_id > 0
        and wb_id == binding_wb_id == owner_id
        and binding_generation > 0
        and binding_generation == current_generation
        and cycle_token
        and cycle_token == str(binding.get("cycle_token") or "")
        and session_id
        and session_id == str(binding.get("plug_session_id") or "")
        and str(binding.get("origin_snapshot_id") or "")
        and str(binding.get("action_latch_id") or "").startswith("sha256:")
    )


def _bind_wallbox_group_deficit_action(
    c_data,
    decision,
    generation,
    candidate,
    *,
    now_ts,
):
    """Latcht eine Aktion; Pending-Zyklen schreiben nur dieselbe fort."""

    data = c_data if isinstance(c_data, dict) else {}
    state = decision if isinstance(decision, dict) else {}
    gen = generation if isinstance(generation, dict) else {}
    owner = candidate if isinstance(candidate, dict) else {}
    action = state.get("action")
    action = action if isinstance(action, dict) else {}
    cascade = state.get("cascade")
    cascade = cascade if isinstance(cascade, dict) else {}
    action_type = str(action.get("type") or wallbox_deficit_control.ACTION_HOLD)
    stage = str(cascade.get("stage") or action.get("stage") or "")
    pending_action = (
        wallbox_deficit_control.ACTION_PHASE_DOWN
        if stage == wallbox_deficit_control.STAGE_PHASE_DOWN_PENDING
        else wallbox_deficit_control.ACTION_STOP
        if stage == wallbox_deficit_control.STAGE_STOP_PENDING
        else ""
    )
    existing = data.get("_wallbox_group_deficit_action_binding")
    existing = dict(existing) if isinstance(existing, dict) else {}
    session_id = str(owner.get("plug_session_id") or "")
    wb_id = int(_cfg_float(owner.get("id"), 0.0))
    binding_generation = int(
        _cfg_float(gen.get("binding_generation"), 0.0)
    )
    cascade_generation = int(_cfg_float(cascade.get("generation"), 0.0))
    current_cycle = str(data.get("_wallbox_cycle_token") or "")
    current_snapshot = str(state.get("snapshot_id") or "")
    same_pending_latch = bool(
        pending_action
        and action_type == wallbox_deficit_control.ACTION_HOLD
        and existing.get("schema") == _GROUP_DEFICIT_ACTION_BINDING_SCHEMA
        and existing.get("active") is True
        and existing.get("action") == pending_action
        and int(_cfg_float(existing.get("wb_id"), 0.0)) == wb_id
        and str(existing.get("plug_session_id") or "") == session_id
        and int(_cfg_float(existing.get("binding_generation"), 0.0))
        == binding_generation
        and int(_cfg_float(existing.get("cascade_generation"), 0.0))
        == cascade_generation
    )
    if same_pending_latch:
        existing.update({
            "cycle_token": current_cycle,
            "decision_snapshot_id": current_snapshot,
            "last_seen_ts": _cfg_float(now_ts, 0.0),
            "stage": stage,
            "pending_retry": True,
        })
        data["_wallbox_group_deficit_action_binding"] = existing
        return dict(existing)

    if action_type not in (
        wallbox_deficit_control.ACTION_CURRENT_DOWN,
        wallbox_deficit_control.ACTION_PHASE_DOWN,
        wallbox_deficit_control.ACTION_STOP,
    ):
        data.pop("_wallbox_group_deficit_action_binding", None)
        data.pop("_wallbox_group_deficit_downward_authority", None)
        return {}
    if not (
        wb_id > 0
        and int(_cfg_float(gen.get("effective_owner_id"), 0.0)) == wb_id
        and gen.get("binding_ready") is True
        and binding_generation > 0
        and session_id
        and current_cycle
        and current_snapshot
    ):
        data.pop("_wallbox_group_deficit_action_binding", None)
        data.pop("_wallbox_group_deficit_downward_authority", None)
        return {}
    latch_material = {
        "action": action_type,
        "wb_id": wb_id,
        "plug_session_id": session_id,
        "binding_generation": binding_generation,
        "cascade_generation": cascade_generation,
        "origin_snapshot_id": current_snapshot,
        "target_amp": action.get("target_amp"),
        "target_phases": action.get("target_phases"),
    }
    binding = {
        "schema": _GROUP_DEFICIT_ACTION_BINDING_SCHEMA,
        "active": True,
        **latch_material,
        "action_latch_id": _wallbox_group_deficit_action_latch_id(
            latch_material
        ),
        "cycle_token": current_cycle,
        "decision_snapshot_id": current_snapshot,
        "stage": stage,
        "reason": str(action.get("reason") or ""),
        "created_ts": _cfg_float(now_ts, 0.0),
        "last_seen_ts": _cfg_float(now_ts, 0.0),
        "pending_retry": False,
        "attempt_ts": 0.0,
        "attempt_status_seq": 0,
        "attempt_status_ts": 0.0,
        "attempt_cycle_token": "",
        "attempt_origin_snapshot_id": "",
    }
    data["_wallbox_group_deficit_action_binding"] = binding
    return dict(binding)


def _wallbox_group_deficit_stop_edge_contract(
    c_data,
    status,
    *,
    now_ts,
    retry_s=30.0,
):
    data = c_data if isinstance(c_data, dict) else {}
    st = status if isinstance(status, dict) else {}
    binding = data.get("_wallbox_group_deficit_action_binding")
    binding = binding if isinstance(binding, dict) else {}
    now_value = _cfg_float(now_ts, 0.0)
    native_toggle = e3dc_session.is_e3dc_native_charger(data.get("charger"))
    fresh = _wallbox_demand_status_fresh(st, now_ts=now_value)
    real_charging = bool(
        fresh
        and (
            _wb_status_real_charging(st)
            or _wb_status_real_power(st) > 500.0
        )
    )
    attempt_ts = _cfg_float(binding.get("attempt_ts"), 0.0)
    status_seq = int(_cfg_float(st.get("native_status_sample_seq"), 0.0))
    native_status_ts = _cfg_float(
        st.get("native_status_sample_ts"),
        0.0,
    )
    status_ts = max(
        native_status_ts,
        _cfg_float(st.get("driver_status_last_ok_ts"), 0.0),
    )
    native_sample_current = bool(
        status_seq > 0
        and native_status_ts > 0.0
        and native_status_ts <= now_value + 2.0
        and now_value - native_status_ts <= 15.0
    )
    if native_toggle:
        status_ts = native_status_ts
    fresh_after_attempt = bool(
        status_ts > max(
            attempt_ts,
            _cfg_float(binding.get("attempt_status_ts"), 0.0),
        )
        and (
            not native_toggle
            or status_seq
            > int(_cfg_float(binding.get("attempt_status_seq"), 0.0))
        )
    )
    first_edge = bool(
        attempt_ts <= 0.0
        and real_charging
        and (not native_toggle or native_sample_current)
    )
    retry_edge = bool(
        attempt_ts > 0.0
        and now_value - attempt_ts >= max(30.0, _cfg_float(retry_s, 30.0))
        and real_charging
        and fresh_after_attempt
    )
    return {
        "contract": "wallbox_group_deficit_stop_edge_v1",
        "stop_edge_due": bool(first_edge or retry_edge),
        "first_edge": first_edge,
        "retry_edge": retry_edge,
        "fresh_real_charging": real_charging,
        "fresh_after_attempt": fresh_after_attempt,
        "native_toggle": native_toggle,
        "native_sample_current": native_sample_current,
        "native_status_sample_ts": native_status_ts,
        "status_seq": status_seq,
        "status_ts": status_ts,
        "attempt_ts": attempt_ts,
    }


def _advance_wallbox_group_deficit_action(
    c_data,
    status,
    candidate,
    *,
    now_ts,
):
    """Führt genau die gebundene Gruppenaktion über bestehende I/O-Pfade aus."""

    data = c_data if isinstance(c_data, dict) else {}
    st = status if isinstance(status, dict) else {}
    owner = candidate if isinstance(candidate, dict) else {}
    binding = data.get("_wallbox_group_deficit_action_binding")
    binding = binding if isinstance(binding, dict) else {}
    action_type = str(binding.get("action") or "")
    result = {
        "contract": "wallbox_group_deficit_action_dispatch_v1",
        "action": action_type,
        "allowed": False,
        "attempted": False,
        "confirmed": False,
        "cycle_token": str(data.get("_wallbox_cycle_token") or ""),
        "action_latch_id": str(binding.get("action_latch_id") or ""),
    }
    if not _wallbox_group_deficit_action_binding_matches(
        data,
        expected_action=action_type,
    ):
        result["blocker"] = "action_binding_mismatch"
        data["_wallbox_group_deficit_action_dispatch"] = result
        return result
    output_blocker = str(owner.get("current_output_blocker") or "")
    if output_blocker:
        result["blocker"] = output_blocker
        result["fail_closed_no_output"] = True
        data["_wallbox_group_deficit_action_dispatch"] = result
        return result
    wb_id = int(_cfg_float(data.get("id"), 0.0))
    charger = data.get("charger")
    if action_type == wallbox_deficit_control.ACTION_CURRENT_DOWN:
        target = _cfg_float(binding.get("target_amp"), -1.0)
        observed = _cfg_float(owner.get("current_amp"), -1.0)
        minimum = max(1.0, _cfg_float(owner.get("minimum_amp"), 6.0))
        output_current = owner.get("output_current_contract")
        output_current = (
            output_current if isinstance(output_current, dict) else {}
        )
        output_ceiling = _cfg_float(
            output_current.get("ceiling_amp"),
            -1.0,
        )
        monotonic_ceiling = min(observed, output_ceiling)
        current_step = _normalize_current_step_amp(
            owner.get("current_step_amp"),
            default=1.0,
        )
        quantized_target = _round_amp_down_to_step(target, current_step)
        target_is_driver_quantized = bool(
            math.isfinite(target)
            and abs(quantized_target - target) <= 1e-6
        )
        effective_drop = monotonic_ceiling - quantized_target
        result["monotonic_output_ceiling_amp"] = (
            round(monotonic_ceiling, 6)
            if math.isfinite(monotonic_ceiling)
            and monotonic_ceiling >= 0.0
            else None
        )
        result["current_step_amp"] = current_step
        result["quantized_target_amp"] = quantized_target
        result["effective_drop_amp"] = (
            round(effective_drop, 6)
            if math.isfinite(effective_drop)
            else None
        )
        result["monotonic_output_source"] = str(
            output_current.get("source") or ""
        )
        if not (
            output_current.get("available") is True
            and math.isfinite(output_ceiling)
            and output_ceiling + 1e-6 >= minimum
            and target >= minimum
            and target_is_driver_quantized
            and effective_drop + 1e-6 >= current_step
        ):
            result["blocker"] = "downward_target_not_monotonic"
            data["_wallbox_group_deficit_action_dispatch"] = result
            return result
        authority = {
            "schema": _GROUP_DEFICIT_DOWNWARD_AUTHORITY_SCHEMA,
            "active": True,
            "owner_id": wb_id,
            "wb_id": wb_id,
            "plug_session_id": str(binding.get("plug_session_id") or ""),
            "binding_generation": int(
                _cfg_float(binding.get("binding_generation"), 0.0)
            ),
            "cycle_token": str(binding.get("cycle_token") or ""),
            "snapshot_id": str(binding.get("origin_snapshot_id") or ""),
            "action_latch_id": str(binding.get("action_latch_id") or ""),
            "target_amp": target,
            "observed_amp": observed,
            "min_amp": minimum,
        }
        # Der Output-Gate-Vertrag erwartet denselben Snapshotschlüssel wie die
        # kurzlebige Authority; bei einer Stromabsenkung ist dies immer der
        # gerade einmal ausgewertete Ursprungssnapshot.
        binding["snapshot_id"] = authority["snapshot_id"]
        data["_wallbox_group_deficit_action_binding"] = binding
        data["_wallbox_group_deficit_downward_authority"] = authority
        _bind_effective_current_output_contract(
            data,
            target,
            reason="group_deficit_current_down",
            base_target_amp=observed,
            target_phases=owner.get("actual_phases"),
            target_power_w=(
                target
                * 230.0
                * max(1, int(_cfg_float(owner.get("actual_phases"), 1.0)))
            ),
        )
        if e3dc_session.is_e3dc_native_charger(charger):
            method = _native_group_deficit_current_output_method(data, st)
        elif hasattr(charger, "set_direct_current"):
            method = "set_direct_current"
        elif hasattr(charger, "set_amp_and_state"):
            method = "set_amp_and_state"
        else:
            method = "set_current"
        if not method:
            result["blocker"] = "safe_current_output_method_missing"
            data["_wallbox_group_deficit_action_dispatch"] = result
            return result
        command = {
            "method": method,
            "amp": target,
            "force_state": None,
            "reason": "group_deficit_current_down",
            "_openwb_pro_existing_session_hold": True,
        }
        result["allowed"] = True
        result["attempted"] = True
        expected_binding = {
            "schema": _GROUP_DEFICIT_DOWNWARD_AUTHORITY_SCHEMA,
            "active": True,
            "owner_id": int(
                _cfg_float(
                    (data.get("_wallbox_group_deficit_generation_contract") or {}).get(
                        "effective_owner_id"
                    ),
                    0.0,
                )
            ),
            "wb_id": int(_cfg_float(data.get("id"), 0.0)),
            "plug_session_id": _wallbox_group_deficit_current_session_id(data),
            "binding_generation": int(
                _cfg_float(
                    (data.get("_wallbox_group_deficit_generation_contract") or {}).get(
                        "binding_generation"
                    ),
                    0.0,
                )
            ),
            "cycle_token": str(data.get("_wallbox_cycle_token") or ""),
            "snapshot_id": str(binding.get("origin_snapshot_id") or ""),
            "action_latch_id": str(binding.get("action_latch_id") or ""),
            "target_amp": _cfg_float(binding.get("target_amp"), -1.0),
            "observed_amp": _cfg_float(owner.get("current_amp"), -1.0),
            "min_amp": max(
                1.0,
                _cfg_float(owner.get("minimum_amp"), 6.0),
            ),
        }
        try:
            with command_gate.group_deficit_downward_scope(
                charger,
                authority,
                expected_binding=expected_binding,
            ):
                receipt = _execute_wallbox_current_with_receipt(
                    data,
                    command,
                    c_id=wb_id,
                )
        except ValueError as error:
            receipt = {}
            result["allowed"] = False
            result["attempted"] = False
            result["blocker"] = str(error)
        result["confirmed"] = bool(
            isinstance(receipt, dict)
            and _cfg_float(receipt.get("amp"), -1.0) <= target + 0.051
            and _cfg_float(receipt.get("amp"), -1.0) >= minimum
        )
        if result["confirmed"]:
            executed_amp = _cfg_float(receipt.get("amp"), target)
            data["current_set_amp"] = executed_amp
            data["last_ramp_ts"] = _cfg_float(now_ts, 0.0)
            data["last_storage_guided_amp_down_ts"] = _cfg_float(
                now_ts,
                0.0,
            )
            result["current_down_settle"] = (
                _mint_wallbox_group_deficit_current_down_settle(
                    data,
                    receipt,
                    candidate=owner,
                    status=st,
                    now_ts=now_ts,
                )
            )
    elif action_type == wallbox_deficit_control.ACTION_PHASE_DOWN:
        if not (
            openwb_pro_session.is_openwb_pro_charger(charger)
            and owner.get("supports_phase_switch") is True
            and owner.get("prevent_phase_switch") is not True
            and int(_cfg_float(binding.get("target_phases"), 0.0)) == 1
        ):
            result["blocker"] = "confirmed_phase_output_surface_missing"
            data["_wallbox_group_deficit_action_dispatch"] = result
            return result
        result["allowed"] = True
        result["attempted"] = True
        result["confirmed"] = bool(
            _execute_wallbox_driver_command(
                data,
                {
                    "method": "set_phases",
                    "phases": 1,
                    "target_phases": 1,
                    "reason": "group_deficit_phase_down",
                },
                c_id=wb_id,
            )
        )
    elif action_type == wallbox_deficit_control.ACTION_STOP:
        edge = _wallbox_group_deficit_stop_edge_contract(
            data,
            st,
            now_ts=now_ts,
        )
        result["stop_edge"] = dict(edge)
        result["allowed"] = bool(edge.get("stop_edge_due"))
        if edge.get("stop_edge_due"):
            binding["attempt_ts"] = _cfg_float(now_ts, 0.0)
            binding["attempt_status_seq"] = int(edge.get("status_seq", 0) or 0)
            binding["attempt_status_ts"] = _cfg_float(
                edge.get("status_ts"),
                0.0,
            )
            binding["attempt_cycle_token"] = str(
                data.get("_wallbox_cycle_token") or ""
            )
            binding["attempt_origin_snapshot_id"] = str(
                binding.get("origin_snapshot_id") or ""
            )
            data["_wallbox_group_deficit_action_binding"] = binding
            result["attempted"] = True
            result["confirmed"] = bool(
                _send_wallbox_stop_command_if_due(
                    data,
                    c_id=wb_id,
                    reason="group_deficit_minimum_stop",
                    stop_authority=(
                        wallbox_decision.final_stop_authority_contract()
                    ),
                    e3dc_native_toggle=edge.get("native_toggle", False),
                    stop_edge_due=True,
                    now_ts=now_ts,
                )
            )
            if result["confirmed"]:
                stop_toggle_ts = _cfg_float(
                    data.get("_last_stop_toggle_ts"),
                    0.0,
                )
                if stop_toggle_ts > 0.0:
                    executed_stop = data.get("_last_executed_command")
                    executed_stop = (
                        executed_stop
                        if isinstance(executed_stop, dict)
                        else {}
                    )
                    data[
                        "_wallbox_group_deficit_stop_receipt_binding"
                    ] = {
                        "schema": (
                            "wallbox_group_deficit_stop_receipt_binding_v1"
                        ),
                        "confirmed": True,
                        "owner_id": wb_id,
                        "wb_id": wb_id,
                        "plug_session_id": str(
                            binding.get("plug_session_id") or ""
                        ),
                        "binding_generation": int(
                            _cfg_float(
                                binding.get("binding_generation"),
                                0.0,
                            )
                        ),
                        "action_latch_id": str(
                            binding.get("action_latch_id") or ""
                        ),
                        "origin_snapshot_id": str(
                            binding.get("attempt_origin_snapshot_id") or ""
                        ),
                        "receipt_cycle_token": str(
                            binding.get("attempt_cycle_token") or ""
                        ),
                        "stop_toggle_ts": stop_toggle_ts,
                        "stop_wire_receipt_contract": str(
                            executed_stop.get("wire_receipt_contract") or ""
                        ),
                        "stop_wire_receipt_seq": int(
                            _cfg_float(
                                executed_stop.get("wire_receipt_seq"),
                                0.0,
                            )
                        ),
                        "stop_wire_receipt_ts": _cfg_float(
                            executed_stop.get("wire_receipt_ts"),
                            0.0,
                        ),
                    }
    else:
        result["blocker"] = "unsupported_group_deficit_action"
    data["_wallbox_group_deficit_action_dispatch"] = result
    return result


def _wallbox_group_deficit_global_exclusion_contract(
    *,
    price_boost_wallbox_active=False,
    curve_forecast_wallbox_stop_active=False,
    house_fuse_limited=False,
    force_wallbox_stop=False,
    predump_floor_hold=False,
):
    """Trennt harte/explizite Stopkanten vom weichen Speicher-Floor.

    Der Pre-Dump-/wbminSoC-Floor beendet ausschließlich die weitere
    Akkuunterstützung. Eine physisch laufende Wallbox bleibt dagegen Eigentum
    der zentralen Defizitkaskade: erst Strom absenken, danach gegebenenfalls
    3p→1p wechseln und erst am 1p-Mindeststrom stoppen. Würde der Floor die
    Kandidaten hier entfernen, könnte ein nachgelagerter Nullbudgetpfad diese
    Reihenfolge mit einem Sofort-Stopp überholen.
    """

    reasons = []
    for active, reason in (
        (price_boost_wallbox_active, "price_boost_active"),
        (
            curve_forecast_wallbox_stop_active,
            "curve_forecast_wallbox_stop_active",
        ),
        (house_fuse_limited, "house_fuse_limited"),
        (force_wallbox_stop, "force_wallbox_stop"),
    ):
        if bool(active):
            reasons.append(reason)
    return {
        "contract": "wallbox_group_deficit_global_exclusion_v1",
        "active": bool(reasons),
        "reasons": reasons,
        "predump_floor_hold": bool(predump_floor_hold),
        "predump_floor_handoff": bool(predump_floor_hold),
        "predump_floor_excludes_cascade": False,
    }


def _run_wallbox_group_deficit_cutover(
    runtime,
    chargers,
    statuses,
    charge_modes,
    *,
    config,
    vehicle_profiles,
    allocatable_by_id,
    priority_mode,
    allocation_contract,
    excluded_ids,
    live,
    grid_power_w,
    live_snapshot_fresh,
    live_sample_invalid,
    min_amp,
    now_ts,
    snapshot_contract=None,
    budget_revision="",
    decision_generation="",
):
    """Einzige Manager-Entscheidungsstelle für das PCC-Defizitkonto."""

    boxes = [item for item in (chargers or []) if isinstance(item, dict)]
    for item in boxes:
        item["_central_deficit_cutover_active"] = False
        item["_central_deficit_legacy_suppressed"] = False
        item["_central_deficit_effective_owner"] = False
        item["_central_deficit_grid_sequence_active"] = False
        item["_central_deficit_current_down_settle_active"] = False
        item["_central_deficit_current_down_settle_cycle_token"] = ""
        item.pop("_wallbox_group_deficit_downward_authority", None)

    stop_completion = _wallbox_group_deficit_complete_confirmed_stop(
        runtime,
        boxes,
        statuses,
        now_ts=now_ts,
    )
    if stop_completion.get("completed") is True:
        reset_legacy_integral = getattr(
            runtime,
            "reset_min_current_import_integral",
            None,
        )
        if callable(reset_legacy_integral):
            reset_legacy_integral(
                int(_cfg_float(stop_completion.get("owner_id"), 0.0))
            )
            reset_legacy_integral(0)

    snapshot = (
        dict(snapshot_contract)
        if isinstance(snapshot_contract, dict)
        else _wallbox_group_deficit_snapshot_contract(live)
    )
    current_down_settle = (
        _wallbox_group_deficit_current_down_settle_retention(
            runtime,
            boxes,
            statuses,
            charge_modes,
            excluded_ids=excluded_ids,
            priority_mode=priority_mode,
            allocation_contract=allocation_contract,
            min_amp=min_amp,
            live_snapshot_valid=bool(snapshot.get("valid") is True),
            live_snapshot_fresh=live_snapshot_fresh,
            live_sample_invalid=live_sample_invalid,
            now_ts=now_ts,
        )
    )
    if current_down_settle:
        settle_owner_id = int(
            _cfg_float(current_down_settle.get("owner_id"), 0.0)
        )
        previous = getattr(runtime, "group_deficit_state", None)
        previous = previous if isinstance(previous, dict) else {}
        generation = next(
            (
                item.get("_wallbox_group_deficit_generation_contract")
                for item in boxes
                if int(_cfg_float(item.get("id"), 0.0))
                == settle_owner_id
                and isinstance(
                    item.get("_wallbox_group_deficit_generation_contract"),
                    dict,
                )
            ),
            {},
        )
        result = {
            "contract": "wallbox_group_deficit_manager_cutover_v1",
            "binding_ready": True,
            "effective_owner_id": settle_owner_id,
            "candidate_ids": [settle_owner_id],
            "snapshot": dict(snapshot),
            "owner": {},
            "generation": dict(generation),
            "step_called": False,
            "duplicate_snapshot_skipped": False,
            "authorized_budget_overrun": {},
            "stop_completion": dict(stop_completion),
            "active": True,
            "sequence_active": True,
            "current_down_settle": dict(current_down_settle),
            "decision": dict(previous),
            "blocker": "current_down_settle_no_output",
        }
        for item in boxes:
            wb_id = int(_cfg_float(item.get("id"), 0.0))
            claimed = wb_id == settle_owner_id
            item["_central_deficit_cutover_active"] = claimed
            item["_central_deficit_legacy_suppressed"] = claimed
            # Der Receipt ist bereits gesendet. Während der kurzen
            # Readback-Beruhigung besitzt deshalb niemand eine neue
            # Hardware-Ausgangsautorität.
            item["_central_deficit_effective_owner"] = False
            item["_central_deficit_grid_sequence_active"] = claimed
            item["_central_deficit_current_down_settle_active"] = claimed
            item[
                "_central_deficit_current_down_settle_cycle_token"
            ] = (
                str(item.get("_wallbox_cycle_token") or "")
                if claimed
                else ""
            )
            item["_wallbox_group_deficit_cutover"] = dict(result)
            if claimed:
                runtime.reset_min_current_import_integral(wb_id)
        runtime.reset_min_current_import_integral(0)
        return result
    owner_contract = _wallbox_group_deficit_owner_contract(
        boxes,
        statuses,
        charge_modes,
        config=config,
        vehicle_profiles=vehicle_profiles,
        allocatable_by_id=allocatable_by_id,
        priority_mode=priority_mode,
        min_amp=min_amp,
        allocation_contract=allocation_contract,
        excluded_ids=excluded_ids,
        pending_retention=_wallbox_group_deficit_pending_retention(runtime),
    )
    generation = _wallbox_group_deficit_generation_contract(
        runtime,
        owner_contract,
        boxes,
    )
    effective_owner_id = int(
        _cfg_float(generation.get("effective_owner_id"), 0.0)
    )
    candidate_ids = {
        int(_cfg_float(value, 0.0))
        for value in (owner_contract.get("candidate_ids") or ())
        if int(_cfg_float(value, 0.0)) > 0
    }
    authorized_budget_overrun = (
        _wallbox_authorized_budget_overrun_contract(
            boxes,
            statuses,
            owner_contract,
            snapshot=snapshot,
            charge_modes=charge_modes,
            budget_revision=budget_revision,
            decision_generation=decision_generation,
        )
    )
    _pending_owner_retention = _wallbox_group_deficit_pending_retention(
        runtime
    )
    _grid_tolerance_w = max(
        0.0,
        _cfg_float(
            config.get("wb_min_current_import_tolerance_w"),
            200.0,
        ),
    )
    _grid_deficit_active = bool(
        max(0.0, _cfg_float(grid_power_w, 0.0) - _grid_tolerance_w)
        > 0.0
    )
    _source_marginal_wb_id = int(
        _cfg_float(
            authorized_budget_overrun.get("marginal_wb_id"),
            0.0,
        )
    )
    _source_owner_override = bool(
        generation.get("binding_ready") is True
        and not _grid_deficit_active
        and not _pending_owner_retention
        and authorized_budget_overrun.get("available") is True
        and _cfg_float(
            authorized_budget_overrun.get("value_w"),
            0.0,
        )
        > 0.0
        and _source_marginal_wb_id in candidate_ids
    )
    if _source_owner_override:
        effective_owner_id = _source_marginal_wb_id
        generation = dict(generation)
        generation.update({
            "effective_owner_id": effective_owner_id,
            "configured_owner_id": effective_owner_id,
            "action_owner_basis": "largest_bound_source_overrun",
            "base_generation_owner_id": int(
                _cfg_float(
                    (getattr(runtime, "group_deficit_binding", {}) or {}).get(
                        "owner_id"
                    ),
                    0.0,
                )
            ),
        })
        for item in boxes:
            item["_wallbox_group_deficit_generation_contract"] = dict(
                generation
            )
    else:
        generation = dict(generation)
        generation["action_owner_basis"] = (
            "pending_action_owner"
            if _pending_owner_retention
            else "pcc_marginal_owner"
        )
        for item in boxes:
            item["_wallbox_group_deficit_generation_contract"] = dict(
                generation
            )
    candidate = next(
        (
            item
            for item in (owner_contract.get("candidates") or ())
            if isinstance(item, dict)
            and int(_cfg_float(item.get("id"), 0.0)) == effective_owner_id
        ),
        None,
    )
    result = {
        "contract": "wallbox_group_deficit_manager_cutover_v1",
        "binding_ready": bool(generation.get("binding_ready") is True),
        "effective_owner_id": effective_owner_id,
        "candidate_ids": sorted(candidate_ids),
        "snapshot": dict(snapshot),
        "owner": dict(owner_contract),
        "generation": dict(generation),
        "step_called": False,
        "duplicate_snapshot_skipped": False,
        "authorized_budget_overrun": dict(authorized_budget_overrun),
        "stop_completion": dict(stop_completion),
        "active": False,
        "blocker": "",
    }
    ready = bool(
        generation.get("binding_ready") is True
        and effective_owner_id > 0
        and isinstance(candidate, dict)
        and snapshot.get("valid") is True
        and live_snapshot_fresh
        and not live_sample_invalid
    )
    if not ready:
        # Schon der erste eindeutige, frische Armierungszyklus übernimmt die
        # Defizitdomäne output-fail-closed. Die zentrale Zustandsmaschine darf
        # erst im Folgetakt ausgeben; konkurrierende Legacy-Strom-, Phasen-
        # oder Stopkanten dürfen dieses eine Fenster aber nicht nutzen.
        arming_hold = bool(
            generation.get("binding_ready") is not True
            and int(_cfg_float(generation.get("configured_owner_id"), 0.0))
            > 0
            and candidate_ids
            and snapshot.get("valid") is True
            and live_snapshot_fresh
            and not live_sample_invalid
        )
        result["arming_hold"] = arming_hold
        result["sequence_active"] = arming_hold
        if arming_hold:
            configured_owner_id = int(
                _cfg_float(generation.get("configured_owner_id"), 0.0)
            )
            for item in boxes:
                wb_id = int(_cfg_float(item.get("id"), 0.0))
                claimed = wb_id in candidate_ids
                item["_central_deficit_cutover_active"] = claimed
                item["_central_deficit_legacy_suppressed"] = claimed
                # Kein effektiver Hardware-Owner vor abgeschlossener
                # Armierung; dieses Feld darf keinen Ausgang autorisieren.
                item["_central_deficit_effective_owner"] = False
                item["_central_deficit_grid_sequence_active"] = claimed
                if claimed:
                    runtime.reset_min_current_import_integral(wb_id)
            runtime.reset_min_current_import_integral(0)
            result["arming_owner_id"] = configured_owner_id
        result["blocker"] = (
            "binding_not_ready"
            if generation.get("binding_ready") is not True
            else "marginal_owner_missing"
            if not isinstance(candidate, dict)
            else "live_snapshot_invalid_or_stale"
        )
        for item in boxes:
            item["_wallbox_group_deficit_cutover"] = dict(result)
        return result

    previous = getattr(runtime, "group_deficit_state", None)
    previous = previous if isinstance(previous, dict) else {}
    snapshot_id = str(snapshot.get("snapshot_id") or "")
    owner_box_for_phase = next(
        (
            item
            for item in boxes
            if int(_cfg_float(item.get("id"), 0.0)) == effective_owner_id
        ),
        {},
    )
    owner_status_for_phase = next(
        (
            item.get("status")
            for item in (statuses or ())
            if isinstance(item, dict)
            and int(_cfg_float(item.get("id"), 0.0)) == effective_owner_id
        ),
        {},
    )
    phase_progress = _wallbox_group_deficit_phase_progress_contract(
        owner_box_for_phase,
        owner_status_for_phase,
        now_ts=now_ts,
    )
    result["phase_progress"] = dict(phase_progress)
    if str(previous.get("snapshot_id") or "") == snapshot_id:
        decision = previous
        result["duplicate_snapshot_skipped"] = True
    else:
        try:
            decision = wallbox_deficit_control.step_group_deficit(
                previous,
                snapshot_id=snapshot_id,
                sample_ts=snapshot.get("sample_ts"),
                sample_valid=True,
                sample_fresh=True,
                pcc_import_w=grid_power_w,
                marginal_wb_id=effective_owner_id,
                current_amp=candidate.get("current_amp"),
                actual_phases=candidate.get("actual_phases"),
                # Der Netzpunkt bleibt vorrangig. Das zweite Konto erhält
                # ausschließlich die Summe positiver, je Ladepunkt gebundener
                # Quellenüberziehungen; bei nur einer unvollständigen
                # Evidenz bleibt es unbekannt und eingefroren.
                authorized_budget_overrun_w=(
                    authorized_budget_overrun.get("value_w")
                ),
                authorized_budget_contract_valid=bool(
                    authorized_budget_overrun.get("available") is True
                    and authorized_budget_overrun.get("complete") is True
                ),
                supports_phase_switch=bool(
                    candidate.get("supports_phase_switch") is True
                ),
                prevent_phase_switch=bool(
                    candidate.get("prevent_phase_switch") is True
                ),
                phase_switch_confirmed=(
                    _wallbox_group_deficit_phase_switch_confirmed(
                        owner_box_for_phase,
                        owner_status_for_phase,
                    )
                ),
                phase_switch_sequence_active=bool(
                    phase_progress.get("sequence_active") is True
                ),
                phase_switch_failed=bool(
                    phase_progress.get("sequence_failed") is True
                ),
                phase_switch_pending_timeout_s=max(
                    30.0,
                    _cfg_float(
                        config.get("wb_phase_confirm_timeout_s"),
                        240.0,
                    ),
                ),
                phase_switch_cooldown_remaining_s=(
                    _wallbox_group_deficit_phase_cooldown_remaining_s(
                        next(
                            (
                                item
                                for item in boxes
                                if int(_cfg_float(item.get("id"), 0.0))
                                == effective_owner_id
                            ),
                            {},
                        ),
                        now_ts=now_ts,
                    )
                ),
                min_amp=max(1.0, _cfg_float(min_amp, 6.0)),
                current_step_amp=candidate.get("current_step_amp", 1.0),
                threshold_wh=max(
                    5.0,
                    _cfg_float(
                        config.get("wb_min_current_import_stop_wh"),
                        40.0,
                    ),
                ),
                leak_w=max(
                    0.0,
                    _cfg_float(
                        config.get("wb_min_current_import_release_w"),
                        80.0,
                    ),
                ),
                tolerance_w=max(
                    0.0,
                    _cfg_float(
                        config.get("wb_min_current_import_tolerance_w"),
                        200.0,
                    ),
                ),
                max_dt_s=max(
                    3.0,
                    min(
                        30.0,
                        _cfg_float(
                            config.get("wb_min_current_import_max_step_s"),
                            10.0,
                        ),
                    ),
                ),
            )
        except wallbox_deficit_control.DeficitControlInputError as error:
            result["blocker"] = "deficit_input_invalid:%s" % error
            for item in boxes:
                item["_wallbox_group_deficit_cutover"] = dict(result)
            return result
        runtime.group_deficit_state = decision
        result["step_called"] = True

    ledger = decision.get("ledger") if isinstance(decision, dict) else {}
    ledger = ledger if isinstance(ledger, dict) else {}
    cascade = decision.get("cascade") if isinstance(decision, dict) else {}
    cascade = cascade if isinstance(cascade, dict) else {}
    action = decision.get("action") if isinstance(decision, dict) else {}
    action = action if isinstance(action, dict) else {}
    sequence_active = bool(
        _cfg_float(ledger.get("grid_deficit_w"), 0.0) > 0.0
        or _cfg_float(ledger.get("grid_bucket_wh"), 0.0) > 0.0
        or _cfg_float(
            ledger.get("authorized_budget_bucket_wh"),
            0.0,
        ) > 0.0
        or str(cascade.get("stage") or "")
        in (
            wallbox_deficit_control.STAGE_PHASE_DOWN_PENDING,
            wallbox_deficit_control.STAGE_STOP_PENDING,
        )
        or str(action.get("type") or "")
        in (
            wallbox_deficit_control.ACTION_CURRENT_DOWN,
            wallbox_deficit_control.ACTION_PHASE_DOWN,
            wallbox_deficit_control.ACTION_STOP,
        )
    )
    result.update({
        "active": True,
        "decision": dict(decision),
        "sequence_active": sequence_active,
    })
    for item in boxes:
        wb_id = int(_cfg_float(item.get("id"), 0.0))
        claimed = wb_id in candidate_ids
        item["_central_deficit_cutover_active"] = claimed
        item["_central_deficit_legacy_suppressed"] = claimed
        item["_central_deficit_effective_owner"] = (
            claimed and wb_id == effective_owner_id
        )
        item["_central_deficit_grid_sequence_active"] = bool(
            claimed and sequence_active
        )
        item["_wallbox_group_deficit_cutover"] = dict(result)
        if claimed:
            runtime.reset_min_current_import_integral(wb_id)
    runtime.reset_min_current_import_integral(0)

    # Ein unveränderter Dateisnapshot erzeugt weder eine neue Policyaktion
    # noch einen zweiten Ausgang. Pending wird erst mit dem nächsten echten
    # Status-/PCC-Snapshot über denselben Latch fortgeschrieben.
    if result["duplicate_snapshot_skipped"]:
        return result

    owner_box = next(
        (
            item
            for item in boxes
            if int(_cfg_float(item.get("id"), 0.0)) == effective_owner_id
        ),
        None,
    )
    owner_status = next(
        (
            item.get("status")
            for item in (statuses or ())
            if isinstance(item, dict)
            and int(_cfg_float(item.get("id"), 0.0)) == effective_owner_id
        ),
        {},
    )
    if isinstance(owner_box, dict):
        result["action_binding"] = _bind_wallbox_group_deficit_action(
            owner_box,
            decision,
            generation,
            candidate,
            now_ts=now_ts,
        )
        if result["action_binding"]:
            result["dispatch"] = _advance_wallbox_group_deficit_action(
                owner_box,
                owner_status,
                candidate,
                now_ts=now_ts,
            )
        owner_box["_wallbox_group_deficit_cutover"] = dict(result)
    return result


def _wallbox_group_deficit_display_contract(cutover, threshold_wh):
    """Projiziert genau das aktuell gezählte Defizitkonto für die WebUI."""

    result = {
        "schema_version": "wallbox_deficit_counter_display_v1",
        "valid": False,
        "active": False,
        "component": "none",
    }
    data = cutover if isinstance(cutover, dict) else {}
    decision = data.get("decision") if isinstance(data.get("decision"), dict) else {}
    ledger = decision.get("ledger") if isinstance(decision.get("ledger"), dict) else {}
    cascade = decision.get("cascade") if isinstance(decision.get("cascade"), dict) else {}
    action = decision.get("action") if isinstance(decision.get("action"), dict) else {}
    if (
        data.get("active") is not True
        or ledger.get("schema_version") != wallbox_deficit_control.LEDGER_SCHEMA
        or ledger.get("sample_valid") is not True
        or ledger.get("sample_fresh") is not True
    ):
        return result
    try:
        threshold = max(5.0, float(threshold_wh))
        component = str(ledger.get("counted_component") or "none")
        if component == "grid":
            used_wh = float(ledger.get("grid_bucket_wh", 0.0) or 0.0)
        elif component == "authorized_budget":
            used_wh = float(
                ledger.get("authorized_budget_bucket_wh", 0.0) or 0.0
            )
        else:
            component = "none"
            used_wh = 0.0
        deficit_w = float(ledger.get("counted_total_w", 0.0) or 0.0)
        leak_w = float(ledger.get("leak_applied_w", 0.0) or 0.0)
        sample_ts = float(decision.get("sample_ts", 0.0) or 0.0)
    except (TypeError, ValueError, OverflowError):
        return result
    if not all(
        math.isfinite(value)
        for value in (threshold, used_wh, deficit_w, leak_w, sample_ts)
    ):
        return result
    used_wh = max(0.0, used_wh)
    remaining_wh = max(0.0, threshold - used_wh)
    accumulating = bool(component != "none" and deficit_w > leak_w + 0.01)
    action_type = str(action.get("type") or wallbox_deficit_control.ACTION_HOLD)
    cascade_stage = str(cascade.get("stage") or "")
    pending_stages = {
        wallbox_deficit_control.STAGE_PHASE_DOWN_PENDING,
        wallbox_deficit_control.STAGE_STOP_PENDING,
    }
    counter_active = bool(
        accumulating
        and used_wh > 0.01
        and remaining_wh > 0.01
        and ledger.get("threshold_reached") is not True
        and action_type == wallbox_deficit_control.ACTION_HOLD
        and cascade_stage not in pending_stages
    )
    result.update({
        "valid": True,
        "active": counter_active,
        "component": component,
        "used_wh": round(used_wh, 2),
        "threshold_wh": round(threshold, 2),
        "remaining_wh": round(remaining_wh, 2),
        "deficit_w": round(max(0.0, deficit_w), 1),
        "accumulating": accumulating,
        "owner_wb_id": int(data.get("effective_owner_id", 0) or 0),
        "stage": cascade_stage,
        "action": action_type,
        "sample_ts": sample_ts,
    })
    return result


def _bev_full_block_stop_reason(c_data):
    """Bindet den exakten persistenten Terminalgrund an die Stop-Session."""

    data = c_data if isinstance(c_data, dict) else {}
    reason = str(data.get("_bev_full_block_reason") or "")
    if data.get("_bev_full_blocked") is True and reason in (
        "vehicle_charge_ended",
        "start_rejected",
        "target_soc_reached",
        "target_kwh_reached",
        "battery_departure_target_reached",
    ):
        return reason
    return "bev_full_blocked"


def _mark_manager_zero_anchor(c_data, reason="zero_anchor"):
    if not isinstance(c_data, dict):
        return
    now_value = time.time()
    c_data["_last_manager_stop_request_ts"] = now_value
    c_data["_last_manager_zero_anchor_ts"] = now_value
    c_data["_last_manager_zero_anchor_reason"] = str(reason or "zero_anchor")
    c_data.pop("_native_e3dc_floor_replug_evidence", None)
    c_data["_manager_zero_anchor_active"] = True
    reason_code = str(reason or "zero_anchor")
    c_data["_manager_zero_anchor_contract"] = {
        "contract": "wallbox_manager_zero_anchor_v1",
        "owner": "wallbox_manager",
        "class": (
            "temporary_policy_zero"
            if reason_code in openwb_pro_session.RELEASABLE_ZERO_ANCHOR_REASONS
            else "hard_stop"
        ),
        "reason_code": reason_code,
        "session_vehicle_key": str(c_data.get("_session_vehicle_key") or ""),
        "plug_session_id": str(
            c_data.get("_openwb_pro_plug_session_id")
            or c_data.get("_wallbox_plug_episode_id")
            or ""
        ),
        "created_ts": now_value,
        "release_condition": (
            "next_positive_executable_policy"
            if reason_code in openwb_pro_session.RELEASABLE_ZERO_ANCHOR_REASONS
            else "explicit_policy_or_session_release"
        ),
    }
    c_data["_aha_real_charge_confirmed"] = False
    c_data["_aha_real_charge_confirmed_since"] = 0.0
    c_data["_real_charge_since"] = 0.0
    c_data["_openwb_start_reject_anchor_ts"] = 0.0

def _mark_manager_charge_anchor(
    c_data,
    amp=0,
    reason="charge_anchor",
    reset_real_marker=False,
    *,
    floor_release_authority=None,
):
    if not isinstance(c_data, dict):
        return False
    now_value = time.time()
    try:
        amp_value = int(round(float(amp or 0)))
    except (TypeError, ValueError):
        amp_value = 0
    if (
        amp_value > 0
        and _native_e3dc_floor_zero_anchor_active(c_data)
        and not _native_e3dc_floor_release_authority_valid(
            floor_release_authority
        )
    ):
        _record_native_e3dc_floor_hardstop_not_yet_effective(
            c_data,
            source="manager_charge_anchor_without_release_authority",
            observed_amp=amp_value,
        )
        return False
    c_data["_last_manager_charge_anchor_ts"] = now_value
    c_data["_last_manager_charge_anchor_amp"] = max(0, amp_value)
    c_data["_last_manager_charge_anchor_reason"] = str(reason or "charge_anchor")
    if amp_value > 0:
        c_data["_manager_zero_anchor_active"] = False
        c_data.pop("_manager_zero_anchor_contract", None)
    if reset_real_marker:
        c_data["_real_charge_since"] = 0.0
        c_data["_aha_real_charge_confirmed"] = False
        c_data["_aha_real_charge_confirmed_since"] = 0.0
    return True

def _openwb_pro_start_hold_s(config=None):
    return openwb_pro_session.start_hold_s(config)


