def _stop_grid_session_after_window(
    c_data,
    current_amp=0,
    hw_charging=False,
    stable_hw_power_w=0.0,
    now_ts=None,
    last_change_ts=None,
    c_id=None,
):
    """Stop one grid-charge session when its planned/price window has ended."""
    if not isinstance(c_data, dict) or not c_data.get("_grid_session_active_last", False):
        return False
    need_window_stop = bool(
        c_data.get("is_charging", False)
        or int(c_data.get("current_set_amp", 0) or 0) > 0
        or int(current_amp or 0) > 0
        or hw_charging
        or float(stable_hw_power_w or 0.0) > 500.0
    )
    if not need_window_stop:
        c_data["_grid_session_active_last"] = False
        return False

    stop_confirmed = bool(
        _send_wallbox_stop_command(
            c_data,
            c_id=c_id,
            reason="grid_window_end",
            stop_authority=wallbox_decision.final_stop_authority_contract(),
            require_typed_stop_authority=True,
        )
    )
    if not stop_confirmed:
        _project_wallbox_current_state(
            c_data,
            c_data.get("last_valid"),
        )
        return False

    now_value = float(now_ts if now_ts is not None else time.time())
    physical_projection = _project_wallbox_current_state(
        c_data,
        c_data.get("last_valid"),
    )
    if not (
        isinstance(physical_projection, dict)
        and physical_projection.get("is_charging") is True
    ):
        c_data["current_set_amp"] = 0
        c_data["is_charging"] = False
    c_data["_grid_session_active_last"] = False
    c_data["_pv_mode_active"] = False
    c_data["_wb_stop_sent_active"] = True
    _record_wallbox_restart_cooldown(
        c_data,
        stop_ts=now_value,
        reason="grid_window_end",
    )
    c_data["_openwb_zero_budget_since"] = 0.0
    c_data["_native_multi_zero_budget_since"] = 0.0
    if isinstance(last_change_ts, dict) and c_id is not None:
        last_change_ts[c_id] = now_value
    if c_id is not None:
        logger.info("WB%d Netzladefenster beendet: Wallbox gestoppt" % c_id)
    return True

def _wallbox_start_generation(chargers, statuses):
    """Bindet eine Startlease an Stecksession und terminale Phasengeneration."""

    status_by_id = {
        int(entry.get("id", 0) or 0): entry.get("status")
        for entry in (statuses if isinstance(statuses, list) else [])
        if isinstance(entry, dict)
        and int(entry.get("id", 0) or 0) > 0
        and isinstance(entry.get("status"), dict)
    }
    generations = []
    ordered = sorted(
        (
            box for box in (chargers if isinstance(chargers, list) else [])
            if isinstance(box, dict)
        ),
        key=lambda box: int(box.get("id", 0) or 0),
    )
    for box in ordered:
        wb_id = int(box.get("id", 0) or 0)
        status = status_by_id.get(wb_id)
        if wb_id <= 0 or not isinstance(status, dict):
            continue
        if not _wb_status_connected(status):
            continue
        session_id = str(
            box.get("_openwb_pro_plug_session_id")
            or box.get("_wallbox_plug_episode_id")
            or status.get("plug_session_id")
            or ""
        )
        if not session_id:
            continue
        terminal_ts = _cfg_float(
            box.get("_openwb_pro_phase_terminal_expired_ts"),
            0.0,
        )
        if not math.isfinite(terminal_ts) or terminal_ts < 0.0:
            terminal_ts = 0.0
        generations.append(
            "%d:%s:%.6f" % (wb_id, session_id, terminal_ts)
        )
    return "|".join(generations)


def write_storage_intent(data):
    """Meldet Wallbox-Wuensche an den Storage Manager.

    Der Wallbox Manager steuert keine Hausbatterie direkt. Er beschreibt nur,
    ob die Wallbox wegen wbminSoC/Modus einen Batterieschutz wuenscht. Der
    Storage Manager priorisiert diesen Wunsch gegen Ladekurve, Pre-Dump,
    Preisfenster und Abregelschutz und sendet als einzige Stelle EMS-Befehle.
    """
    return _storage_intent_publisher.publish(data)


def _wallbox_observed_phase_count(status):
    st = status if isinstance(status, dict) else {}
    # Rohe Phasenleistungen sind wegen Treiber-Fallbacks, Messwertalter und
    # möglicher Summenwert-Projektion kein Phasenbeleg. Nur der normalisierte
    # Treibervertrag darf sie zur Phasenerkennung freigeben.
    if st.get("phase_power_verified") is True:
        phase_powers = [
            abs(_cfg_float(st.get(key), 0.0))
            for key in (
                "phase_power_l1_w",
                "phase_power_l2_w",
                "phase_power_l3_w",
            )
        ]
        measured = sum(1 for value in phase_powers if value > 100.0)
        if measured in (1, 2, 3):
            return measured
    for key in ("phase_actual_phases", "phases_actual", "phases_in_use", "number_phases"):
        phases = _valid_phase_count(st.get(key), 0)
        if phases:
            return phases
    pha = int(_cfg_float(st.get("pha"), 0.0))
    return 3 if pha == 56 else (2 if pha == 24 else (1 if pha in (8, 16, 32) else 0))


def _wallbox_allocation_phase_count(
    c_data,
    status,
    *,
    phase_contract=None,
    fallback_phases=3,
):
    """Bepreise das aktuelle Wattbudget nur mit gebundener Phasenevidenz."""

    data = c_data if isinstance(c_data, dict) else {}
    st = status if isinstance(status, dict) else {}
    fallback = _valid_phase_count(fallback_phases, 3) or 3
    status_fresh = bool(
        st
        and st.get("driver_status_valid") is True
        and not bool(st.get("driver_status_stale", False))
        and not bool(st.get("driver_status_degraded", False))
        and not bool(st.get("driver_status_glitch", False))
        and st.get("valid") is not False
        and not bool(st.get("stale", False))
    )

    fresh_real_charging = _wallbox_status_fresh_real_charging(st)
    observed = (
        _wallbox_observed_phase_count(st)
        if fresh_real_charging
        else 0
    )

    reservation = data.get("_wallbox_phase_transition_reservation")
    if isinstance(reservation, dict) and reservation.get("active") is True:
        target = _valid_phase_count(reservation.get("target_phases"), 0)
        # Ein aktiver, aber unvollständiger Recovery-/Transitionsvertrag darf
        # niemals still als günstiger 1p-Start neu bepreist werden.
        if not target:
            return 3
        return max(target, observed)

    recovery = data.get("_openwb_pro_phase_recovery_hold")
    if isinstance(recovery, dict) and recovery.get("active") is True:
        return 3

    sequence = data.get("_openwb_pro_phase_sequence")
    if isinstance(sequence, dict) and sequence:
        sequence_target = _valid_phase_count(sequence.get("target"), 0)
        return max(sequence_target or 3, observed)

    if fresh_real_charging:
        return observed or fallback

    contract = phase_contract if isinstance(phase_contract, dict) else {}
    if (
        status_fresh
        and _wb_status_connected(st)
        and contract.get("vehicle_profile_phase_bound") is True
    ):
        vehicle_phases = _valid_phase_count(
            contract.get("effective_load_phases", contract.get("effective_phases")),
            0,
        )
        if vehicle_phases:
            return vehicle_phases

    if (
        status_fresh
        and _wb_status_connected(st)
        and not _wb_status_real_charging(st)
        and openwb_pro_session.is_openwb_pro_charger(data.get("charger"))
    ):
        # Vor dem ersten Ladestrom gibt es keine belastbaren Istphasen. Das
        # connect.php-Phasenziel kann aus einem früheren Ladevorgang stammen
        # und darf das gemeinsame Wattbudget daher nicht auf das 3p-Minimum
        # von 4.140 W verteuern. Für die reine Startzuteilung wird 1p
        # projektiert; der physische Phasenvertrag bleibt separat konservativ
        # und aktive Transitionen, Recovery sowie laufende Ladung wurden oben
        # bereits hart gebunden.
        return 1

    if _is_e3dc_shared_rscp_charger(data.get("charger"), st):
        # Ohne bestätigten Phasenbeleg bleibt der gemeinsame RSCP-Pfad konservativ 3p.
        return 3

    return fallback


def _is_e3dc_shared_rscp_charger(charger, status=None):
    """Erkennt das gemeinsame E3/DC-RSCP-Backend, ohne ein Modell zu behaupten."""
    st = status if isinstance(status, dict) else {}
    return bool(
        (charger is not None and charger.__class__.__name__ == "E3DCMultiConnectCharger")
        or str(getattr(charger, "transport", "") or "") == "e3dc_rscp_via_home_power_station"
        or str(st.get("e3dc_transport") or "") == "e3dc_rscp_via_home_power_station"
    )


def _observe_wallbox_phase_transition(c_data, previous_status, status, *, now_ts=None):
    """Erkenne auch Phasenwechsel, die ein externer Wallbox-Master ausführt."""

    if not isinstance(c_data, dict) or not isinstance(status, dict):
        return {}
    charger = c_data.get("charger")
    if _is_e3dc_shared_rscp_charger(charger, status):
        c_data.pop("_wallbox_phase_transition_reservation", None)
        c_data.pop("_phase_transition_grant", None)
        return {}
    if status.get("driver_status_valid") is False or status.get("driver_status_stale"):
        return {}
    terminal_start_blocked = bool(c_data.get("_bev_full_blocked", False))
    raw_reservation = c_data.get("_wallbox_phase_transition_reservation")
    raw_reservation_active = bool(
        isinstance(raw_reservation, dict)
        and raw_reservation.get("active") is True
    )
    if terminal_start_blocked and not raw_reservation_active:
        inactive = wallbox_phase_transition.inactive_reservation(
            "terminal_vehicle_latch"
        )
        inactive["terminal_vehicle_latch"] = True
        return inactive
    now_value = float(now_ts if now_ts is not None else time.time())
    clock_sample = _openwb_pro_control_time_sample(wall_ts=now_value)
    current = status
    previous = previous_status if isinstance(previous_status, dict) else {}
    connected = _wb_status_connected(current)
    if (
        not connected
        and openwb_pro_session.is_openwb_pro_charger(charger)
    ):
        terminal_contract = (
            openwb_pro_session.disconnected_phase_terminalization_contract(
                c_data,
                current,
                now_ts=now_value,
            )
        )
        c_data[
            "_openwb_pro_disconnected_phase_terminalization_contract"
        ] = terminal_contract
        if terminal_contract.get("allow", False):
            terminalized = (
                _finalize_disconnected_openwb_pro_phase_transition(
                    c_data,
                    target=terminal_contract.get("target", 0),
                    now_ts=now_value,
                )
            )
            if terminalized:
                return {
                    "active": False,
                    "reason": "disconnected_phase_terminalized",
                    "target_phases": int(
                        terminal_contract.get("target", 0) or 0
                    ),
                }
            return {
                "active": True,
                "reason": (
                    "disconnected_phase_terminalization_persist_failed"
                ),
                "target_phases": int(
                    terminal_contract.get("target", 0) or 0
                ),
            }
        existing_sequence = c_data.get("_openwb_pro_phase_sequence")
        if (
            isinstance(existing_sequence, dict)
            and str(existing_sequence.get("stage") or "") == "zero_wait"
        ):
            sequence_target = _valid_phase_count(
                existing_sequence.get("target"), 0
            )
            cfg = (
                c_data.get("_openwb_pro_config")
                if isinstance(c_data.get("_openwb_pro_config"), dict)
                else {}
            )
            disconnect_contract = (
                openwb_pro_session.phase_sequence_step_contract(
                    sequence_target,
                    existing_sequence,
                    now_ts=now_value,
                    hold_s=openwb_pro_session.phase_wait_s(cfg),
                    restart_delay_s=(
                        openwb_pro_session.phase_restart_delay_s(cfg)
                    ),
                    current_set_amp=c_data.get("current_set_amp", 0),
                    status=current,
                    config=cfg,
                    reason=str(
                        existing_sequence.get("reason")
                        or "phase_switch"
                    ),
                )
            )
            c_data[
                "_openwb_pro_phase_disconnect_contract"
            ] = disconnect_contract
            if (
                str(disconnect_contract.get("action") or "")
                == "abort_disconnected_before_phase_output"
            ):
                aborted = _abort_openwb_pro_phase_transition_before_output(
                    c_data,
                    target=sequence_target,
                    reason=str(
                        disconnect_contract.get("reason")
                        or "vehicle_disconnected_before_phase_output"
                    ),
                    now_ts=now_value,
                )
                return {
                    "active": not aborted,
                    "reason": (
                        "disconnected_phase_output_aborted"
                        if aborted
                        else "disconnected_phase_output_abort_persist_failed"
                    ),
                    "target_phases": int(sequence_target or 0),
                }
    existing = phase_transition_reservation(
        c_data,
        status=current,
        now_ts=now_value,
        connected=connected,
        clock_sample=clock_sample,
    )
    if terminal_start_blocked:
        if existing.get("active"):
            existing["terminal_vehicle_latch"] = True
            return existing
        inactive = wallbox_phase_transition.inactive_reservation(
            "terminal_vehicle_latch"
        )
        inactive["terminal_vehicle_latch"] = True
        return inactive
    if existing.get("active"):
        return existing

    current_target = _valid_phase_count(current.get("phases_target"), 0)
    previous_target = _valid_phase_count(previous.get("phases_target"), 0)
    current_actual = _wallbox_observed_phase_count(current)
    previous_actual = _wallbox_observed_phase_count(previous)
    previous_power_w = _wb_status_real_power(previous)
    current_power_w = _wb_status_real_power(current)
    was_active = bool(_wb_status_real_charging(previous) or previous_power_w > 500.0)
    is_active = bool(_wb_status_real_charging(current) or current_power_w > 500.0)
    explicit_transition = bool(
        current.get("phase_transition_active")
        or current.get("phase_switch_active")
        or current.get("phase_switch_in_progress")
    )

    target = 0
    reason = ""
    if explicit_transition and current_target in (1, 3):
        target = current_target
        reason = "driver_reports_phase_transition"
    elif (
        current_target in (1, 3)
        and previous_target in (1, 3)
        and current_target != previous_target
        and (was_active or is_active)
    ):
        target = current_target
        reason = "observed_phase_target_change"
    elif (
        current_target in (1, 3)
        and previous_actual in (1, 3)
        and current_target != previous_actual
        and was_active
    ):
        target = current_target
        reason = "observed_target_actual_mismatch"
    elif (
        current_actual in (1, 3)
        and previous_actual in (1, 3)
        and current_actual != previous_actual
        and (was_active or is_active)
    ):
        target = current_actual
        reason = "observed_actual_phase_change"
    if target not in (1, 3):
        return existing

    reservation_status = dict(current)
    reservation_status["real_power_w"] = max(current_power_w, previous_power_w)
    charger_name = charger.__class__.__name__ if charger is not None else "Wallbox"
    begin_phase_transition_reservation(
        c_data,
        target,
        status=reservation_status,
        now_ts=now_value,
        charger_max_amp=getattr(charger, "max_amp", c_data.get("max_amp", 16)),
        source="%s_observed_phase_change" % charger_name,
        reason=reason,
        clock_sample=clock_sample,
    )
    return phase_transition_reservation(
        c_data,
        status=current,
        now_ts=now_value,
        connected=connected,
        clock_sample=clock_sample,
    )


_OPENWB_PRO_TERMINAL_PHASE_KEYS = (
    "_wallbox_phase_transition_reservation",
    "_phase_transition_grant",
    "_openwb_pro_phase_sequence",
    "_openwb_pro_phase_sequence_contract",
    "_openwb_pro_phase_sequence_last",
    "_openwb_pro_phase_sequence_stage",
    "_openwb_pro_phase_sequence_target",
    "_openwb_pro_phase_sequence_current_allowed_after",
    "_openwb_pro_phase_sequence_phase_sent_ts",
    "_openwb_pro_phase_sequence_cp_sent_ts",
    "_openwb_pro_phase_output_intent",
    "_openwb_pro_phase_output_ack",
    "_openwb_pro_phase_recovery_hold",
    "_openwb_pro_phase_restart_authorized",
    "_openwb_pro_start_wakeup_cp_ts",
    "_openwb_pro_start_wakeup_allowed_after",
    "_openwb_cp_start_sent",
    "_openwb_last_cp_start_ts",
)

_OPENWB_PRO_COMPLETED_PHASE_WAIT_KEYS = (
    "_openwb_pro_phase_wait_target",
    "_openwb_pro_phase_wait_until",
    "_openwb_pro_phase_wait_min_until",
    "_openwb_pro_phase_wait_amp",
    "_openwb_pro_phase_wait_since",
)


def _terminalize_openwb_pro_phase_for_priority_stop(
    chargers,
    c_data,
    *,
    now_ts=None,
):
    """Beendet eine alte Pro-Phasengeneration ohne Hardwareausgang.

    Der Prioritätsstopp darf im Folgezyklus kein zuvor geplantes Phasenziel
    wiederaufnehmen. Die kurze Sequenz und ihre Ausgangsbelege werden deshalb
    crashfest terminalisiert; die getrennte 480-s-Sperre für den nächsten
    Phasenwechsel bleibt ausdrücklich unangetastet. Scheitert die Persistenz,
    wird der RAM-Stand exakt restauriert. Der zyklusgebundene I/O-Latch bleibt
    außerhalb dieses Helfers aktiv und verhindert dann weiterhin Ausgänge.
    """

    data = c_data if isinstance(c_data, dict) else {}
    if not openwb_pro_session.is_openwb_pro_charger(data.get("charger")):
        return {
            "contract": "openwb_pro_priority_phase_terminal_v1",
            "needed": False,
            "terminalized": False,
            "persisted": False,
            "hardware_write": False,
            "reason": "not_openwb_pro",
        }
    sequence = data.get("_openwb_pro_phase_sequence")
    reservation = data.get("_wallbox_phase_transition_reservation")
    needed = bool(
        (isinstance(sequence, dict) and sequence)
        or (
            isinstance(reservation, dict)
            and reservation.get("active") is True
        )
    )
    result = {
        "contract": "openwb_pro_priority_phase_terminal_v1",
        "needed": needed,
        "terminalized": False,
        "persisted": False,
        "hardware_write": False,
        "reason": "priority_forced_stop" if needed else "no_active_generation",
    }
    if not needed:
        return result

    phase_preimage = _snapshot_wallbox_state_file_preimage(
        WB_PHASE_STATE_FILE
    )
    if phase_preimage.get("valid") is not True:
        result["reason"] = "phase_state_preimage_invalid"
        return result

    touched_keys = tuple(dict.fromkeys(
        _OPENWB_PRO_TERMINAL_PHASE_KEYS
        + _OPENWB_PRO_COMPLETED_PHASE_WAIT_KEYS
    ))
    previous = {
        key: (key in data, deepcopy(data.get(key)))
        for key in touched_keys
    }
    PhaseSwitchSequencer(data).reset(clear_phase_wait=True)
    wallbox_phase_transition.set_stage(
        data,
        "aborted",
        now_ts=float(now_ts if now_ts is not None else time.time()),
        reason_code="priority_forced_stop",
    )
    for key in (
        "_phase_transition_grant",
        "_openwb_pro_phase_output_intent",
        "_openwb_pro_phase_output_ack",
        "_openwb_pro_phase_recovery_hold",
        "_openwb_pro_phase_restart_authorized",
    ):
        data.pop(key, None)

    if _save_wallbox_phase_state(chargers):
        result.update({
            "terminalized": True,
            "persisted": True,
            "reservation_stage": str(
                (data.get("_wallbox_phase_transition_reservation") or {}).get(
                    "stage",
                    "",
                )
            ),
        })
        return result

    disk_restored = _restore_wallbox_state_file_preimage(
        WB_PHASE_STATE_FILE,
        phase_preimage,
    )
    for key, (present, value) in previous.items():
        if present:
            data[key] = value
        else:
            data.pop(key, None)
    result["disk_restored"] = bool(disk_restored)
    if not disk_restored:
        _apply_openwb_pro_persistence_recovery_hold(
            data,
            "priority_phase_terminal_rollback_failed",
        )
        result["fail_closed"] = True
    result["reason"] = "phase_state_persist_failed"
    return result


_OPENWB_PRO_REPLUG_SESSION_KEYS = (
    "_session_1p_only",
    "_phase_change_seen_session",
    "_openwb_disconnected_since",
    "_openwb_pro_disconnect_candidate",
)

_OPENWB_PRO_REPLUG_TERMINALIZED_STOP_KEYS = (
    "_bev_full_blocked",
    "_bev_full_block_reason",
    "_charge_end_latched_plug_session_id",
    "_charge_end_latched_ts",
    "abort_count",
    "abort_cooldown_ts",
) + _CHARGE_END_RUNTIME_EPHEMERAL_KEYS

_OPENWB_PRO_REPLUG_OWN_STOP_KEYS = (
    "_manager_zero_anchor_active",
    "_manager_zero_anchor_contract",
    "_last_manager_zero_anchor_reason",
    "_last_manager_zero_anchor_ts",
    "_last_manager_stop_request_ts",
    "_last_manager_stop_request_reason",
    "_manager_stop_display_since_ts",
    "_manager_stop_display_until_ts",
    "_manager_stop_display_reason",
    "_wb_stop_sent_active",
)

_OPENWB_PRO_REPLUG_OWN_STOP_REASONS = frozenset({
    "no_vehicle_connected",
    "unplugged",
    "vehicle_charge_ended",
    "start_rejected",
    "target_soc_reached",
    "target_kwh_reached",
    "battery_departure_target_reached",
    "vehicle_start_rejected_soft",
}) | frozenset(openwb_pro_session.RELEASABLE_ZERO_ANCHOR_REASONS)


def _reset_openwb_pro_vehicle_identity_session(c_data):
    """Setzt nur fahrzeugbezogene Laufzeitfelder einer neuen Identität zurück.

    Ein Identitätswechsel ist kein Freigabesignal für einen aktiven
    Nullanker. Insbesondere Nutzer-Aus, Not-Aus und Safety-Anker bleiben daher
    bytegleich erhalten.
    """

    data = c_data if isinstance(c_data, dict) else {}
    for key, value in (
        ("_session_1p_only", False),
        ("_phase_3p_block_until", 0.0),
        ("_openwb_pro_phase_retry_block_until", 0.0),
        ("_phase_3p_pending_since", 0.0),
        ("_phase_up_budget_since", 0.0),
        ("_phase_down_since", 0.0),
        ("_openwb_cp_start_sent", False),
        ("_real_charge_since", 0.0),
        ("_aha_real_charge_confirmed", False),
        ("_aha_real_charge_confirmed_since", 0.0),
        ("_openwb_start_reject_soft_until", 0.0),
        ("_openwb_pro_phase_sequence", {}),
        ("_openwb_pro_phase_sequence_stage", ""),
        ("abort_count", 0),
        ("abort_cooldown_ts", 0.0),
    ):
        data[key] = value
    for key in (
        "_session_vehicle_key",
        "_session_vehicle_identity_source",
        "_session_vehicle_binding_id",
        "_vehicle_current_capability",
        "_vehicle_current_output_gate",
    ):
        data.pop(key, None)


def _terminalize_openwb_pro_previous_session_stop(c_data):
    """Löst nur den eigenen Stop der nachweislich alten Stecksession.

    Nutzer-Aus, NOT-AUS, Safety- und sonstige Policy-Anker dürfen durch ein
    Ab-/Anstecken nicht verschwinden. Ein fahrzeugbezogenes Ladeende oder der
    eigene weiche Startabbruch gehört dagegen ausschließlich zur beendeten
    physischen Stecksession.
    """

    data = c_data if isinstance(c_data, dict) else {}
    typed_anchor_present = "_manager_zero_anchor_contract" in data
    typed_anchor_raw = data.get("_manager_zero_anchor_contract")
    typed_anchor = (
        typed_anchor_raw if isinstance(typed_anchor_raw, dict) else {}
    )
    anchor_reason = str(typed_anchor.get("reason_code") or "")
    legacy_anchor_reason = str(
        data.get("_last_manager_zero_anchor_reason") or ""
    )
    plug_session_id = str(data.get("_openwb_pro_plug_session_id") or "")
    latched_plug_session_id = str(
        data.get("_charge_end_latched_plug_session_id") or ""
    )
    anchor_plug_session_id = str(typed_anchor.get("plug_session_id") or "")
    anchor_active = data.get("_manager_zero_anchor_active") is True
    current_latch_reason = str(data.get("_bev_full_block_reason") or "")
    protected_latch = bool(
        data.get("_bev_full_blocked") is True
        and current_latch_reason not in _CHARGE_END_TERMINAL_REASONS
    )
    exact_terminal_latch = bool(
        plug_session_id
        and latched_plug_session_id == plug_session_id
        and data.get("_bev_full_blocked") is True
        and str(data.get("_bev_full_block_reason") or "")
        in (
            "vehicle_charge_ended",
            "start_rejected",
            "target_soc_reached",
            "target_kwh_reached",
            "battery_departure_target_reached",
        )
    )
    own_typed_anchor = bool(
        anchor_active
        and str(typed_anchor.get("contract") or "")
        == "wallbox_manager_zero_anchor_v1"
        and str(typed_anchor.get("owner") or "") == "wallbox_manager"
        and plug_session_id
        and anchor_plug_session_id == plug_session_id
    )
    latch_only_terminal = bool(
        exact_terminal_latch
        and not anchor_active
        and not typed_anchor_present
        and not legacy_anchor_reason
    )
    rehydrated_terminal_anchor = bool(
        own_typed_anchor
        and anchor_reason == "bev_full_blocked"
        and exact_terminal_latch
    )
    terminalized = bool(
        not protected_latch
        and not _native_e3dc_floor_zero_anchor_active(data)
        and
        (
            (
                own_typed_anchor
                and anchor_reason in _OPENWB_PRO_REPLUG_OWN_STOP_REASONS
            )
            or rehydrated_terminal_anchor
            or latch_only_terminal
        )
    )
    if terminalized:
        for key in _OPENWB_PRO_REPLUG_OWN_STOP_KEYS:
            data.pop(key, None)
    return {
        "reason": anchor_reason,
        "legacy_reason": legacy_anchor_reason,
        "anchor_active": anchor_active,
        "typed_anchor_present": typed_anchor_present,
        "own_typed_anchor": own_typed_anchor,
        "exact_vehicle_end_latch": exact_terminal_latch,
        "latch_only_vehicle_end": latch_only_terminal,
        "rehydrated_vehicle_end_anchor": rehydrated_terminal_anchor,
        "exact_terminal_latch": exact_terminal_latch,
        "plug_session_id": plug_session_id,
        "latched_plug_session_id": latched_plug_session_id,
        "anchor_plug_session_id": anchor_plug_session_id,
        "protected_latch": protected_latch,
        "current_latch_reason": current_latch_reason,
        "terminalized": terminalized,
    }


def _snapshot_wallbox_state_file_preimage(path):
    """Liest einen regulären JSON-State als exaktes Rollback-Preimage."""

    target = str(path or "")
    if not target:
        return {"valid": False, "exists": False, "reason": "path_missing"}
    try:
        if not os.path.lexists(target):
            return {
                "valid": True,
                "exists": False,
                "payload": b"",
                "mode": 0o664,
            }
        meta = os.lstat(target)
        if stat.S_ISLNK(meta.st_mode) or not stat.S_ISREG(meta.st_mode):
            return {
                "valid": False,
                "exists": True,
                "reason": "state_preimage_not_regular",
            }
        with open(target, "rb") as handle:
            payload = handle.read()
        decoded = json.loads(payload.decode("utf-8"))
        if not isinstance(decoded, dict):
            return {
                "valid": False,
                "exists": True,
                "reason": "state_preimage_not_mapping",
            }
        return {
            "valid": True,
            "exists": True,
            "payload": payload,
            "mode": stat.S_IMODE(meta.st_mode),
        }
    except Exception as exc:
        return {
            "valid": False,
            "exists": os.path.lexists(target),
            "reason": "state_preimage_read_failed:%s" % exc.__class__.__name__,
        }


def _restore_wallbox_state_file_preimage(path, snapshot):
    """Stellt ein exaktes State-Preimage per Same-FS-Replace wieder her."""

    target = str(path or "")
    state = snapshot if isinstance(snapshot, dict) else {}
    if not target or state.get("valid") is not True:
        return False
    tmp = ""
    try:
        directory = os.path.dirname(target)
        os.makedirs(directory, mode=0o775, exist_ok=True)
        if os.path.islink(directory):
            return False
        if state.get("exists") is True:
            if os.path.lexists(target):
                current = os.lstat(target)
                if stat.S_ISLNK(current.st_mode) or not stat.S_ISREG(current.st_mode):
                    return False
            tmp = "%s.restore.%d" % (target, os.getpid())
            with open(tmp, "wb") as handle:
                handle.write(bytes(state.get("payload") or b""))
                handle.flush()
                os.fsync(handle.fileno())
            os.chmod(tmp, int(state.get("mode", 0o664) or 0o664))
            os.replace(tmp, target)
        elif os.path.lexists(target):
            current = os.lstat(target)
            if stat.S_ISLNK(current.st_mode) or not stat.S_ISREG(current.st_mode):
                return False
            os.unlink(target)
        dir_fd = os.open(directory, os.O_RDONLY)
        try:
            os.fsync(dir_fd)
        finally:
            os.close(dir_fd)
        return True
    except Exception as exc:
        logger.error("Wallbox-State-Preimage konnte nicht restauriert werden: %s", exc)
        try:
            if tmp and os.path.exists(tmp):
                os.unlink(tmp)
        except Exception:
            pass
        return False


def _apply_openwb_pro_persistence_recovery_hold(c_data, reason):
    """Blockiert Ausgänge, wenn die Zwei-Dateien-Restauration unvollständig ist."""

    data = c_data if isinstance(c_data, dict) else {}
    reason_code = str(reason or "session_persistence_restore_failed")
    data["_openwb_pro_session_persistence_recovery_hold"] = {
        "active": True,
        "reason": reason_code,
        "hardware_write": False,
    }
    if not bool(data.get("_manager_zero_anchor_active", False)):
        data["_manager_zero_anchor_active"] = True
        data["_manager_zero_anchor_contract"] = {
            "contract": "wallbox_manager_zero_anchor_v1",
            "owner": "wallbox_manager",
            "class": "hard_stop",
            "reason_code": reason_code,
            "plug_session_id": str(
                data.get("_openwb_pro_plug_session_id") or ""
            ),
            "release_condition": "manual_recovery_after_persistence_failure",
        }
        data["_last_manager_zero_anchor_reason"] = reason_code
    # Der Recovery-Hold sperrt ausschließlich zukünftige Ausgänge. Ohne
    # Treiber-I/O und neuen Receipt ist weder ein physischer Stop noch 0 A
    # bestätigt; der vorhandene Hardwarezustand bleibt daher unangetastet.
    _project_wallbox_current_state(data, data.get("last_valid"))


def _persist_openwb_pro_session_transaction(c_data, mutate, *, name):
    """Persistiert Phase und Abbruchstatus als rollbackfähige Einheit."""

    data = c_data if isinstance(c_data, dict) else {}
    result = {
        "contract": "openwb_pro_dual_state_transaction_v1",
        "name": str(name or "session_state_change"),
        "committed": False,
        "phase_saved": False,
        "abort_saved": False,
        "phase_restored": False,
        "abort_restored": False,
        "restore_failed": False,
        "mutation": {},
    }
    charger_id = str(data.get("id") or "")
    if not charger_id:
        result["reason"] = "charger_id_missing"
        _apply_openwb_pro_persistence_recovery_hold(
            data,
            "session_persistence_charger_id_missing",
        )
        return result
    try:
        previous = {
            key: (value if key == "charger" else deepcopy(value))
            for key, value in data.items()
        }
    except Exception as exc:
        result["reason"] = "memory_preimage_failed:%s" % (
            exc.__class__.__name__
        )
        _apply_openwb_pro_persistence_recovery_hold(
            data,
            "session_persistence_memory_preimage_failed",
        )
        return result
    phase_preimage = _snapshot_wallbox_state_file_preimage(
        WB_PHASE_STATE_FILE
    )
    abort_preimage = _snapshot_wallbox_state_file_preimage(
        WB_ABORT_STATE_FILE
    )
    if (
        phase_preimage.get("valid") is not True
        or abort_preimage.get("valid") is not True
    ):
        result["reason"] = "state_preimage_invalid"
        _apply_openwb_pro_persistence_recovery_hold(
            data,
            "session_persistence_preimage_invalid",
        )
        return result

    try:
        mutation = mutate()
        result["mutation"] = (
            dict(mutation) if isinstance(mutation, dict) else {}
        )
    except Exception as exc:
        data.clear()
        data.update(previous)
        result["reason"] = "mutation_failed:%s" % exc.__class__.__name__
        return result

    result["phase_saved"] = bool(_save_wallbox_phase_state([data]))
    if result["phase_saved"]:
        result["abort_saved"] = bool(
            _save_wallbox_abort_state([data], preserve_existing=True)
        )
    if result["phase_saved"] and result["abort_saved"]:
        result["committed"] = True
        result["reason"] = "dual_state_committed"
        return result

    data.clear()
    data.update(previous)
    result["abort_restored"] = bool(
        _restore_wallbox_state_file_preimage(
            WB_ABORT_STATE_FILE,
            abort_preimage,
        )
    )
    # Der Freigabe-Latch muss auf Platte wieder aktiv sein, bevor ein
    # vorbereitetes Receipt/Wakeup-Reset zurückgerollt werden darf. Ein Kill
    # zwischen den beiden Restores bleibt damit fail-closed: entweder ist der
    # alte Abort-Latch wieder da oder das vorbereitete WAL bleibt erhalten.
    if result["abort_restored"]:
        result["phase_restored"] = bool(
            _restore_wallbox_state_file_preimage(
                WB_PHASE_STATE_FILE,
                phase_preimage,
            )
        )
    result["restore_failed"] = not bool(
        result["phase_restored"] and result["abort_restored"]
    )
    result["reason"] = (
        "dual_state_restore_failed"
        if result["restore_failed"]
        else "dual_state_save_failed_preimages_restored"
    )
    if result["restore_failed"]:
        _apply_openwb_pro_persistence_recovery_hold(
            data,
            "session_persistence_restore_failed",
        )
    return result


def _rotate_openwb_pro_plug_session_after_reconnect(
    c_data,
    status,
    config=None,
    *,
    c_id=None,
    now_ts=None,
):
    """Persistiert eine entprellte neue Stecksession atomar und ohne Geräte-I/O."""

    data = c_data if isinstance(c_data, dict) else {}
    now_value = float(now_ts if now_ts is not None else time.time())
    contract = openwb_pro_session.start_reconnect_confirmation_contract(
        data,
        status,
        config,
        now_ts=now_value,
    )
    result = {
        **contract,
        "rotated": False,
        "persisted": False,
        "persist_failed": False,
        "previous_session_id": str(data.get("_openwb_pro_plug_session_id") or ""),
        "new_session_id": "",
    }
    if not contract.get("confirmed", False):
        return result

    def mutate():
        stop_release = _terminalize_openwb_pro_previous_session_stop(data)
        _clear_openwb_pro_start_session(
            data,
            preserve_stop_barriers=not stop_release.get(
                "terminalized",
                False,
            ),
        )
        for key in _OPENWB_PRO_TERMINAL_PHASE_KEYS:
            data.pop(key, None)
        for key in _OPENWB_PRO_REPLUG_SESSION_KEYS:
            data.pop(key, None)
        if stop_release.get("terminalized", False):
            for key in _OPENWB_PRO_REPLUG_TERMINALIZED_STOP_KEYS:
                data.pop(key, None)
        _reset_wallbox_confirmed_disconnect_runtime(data)
        data["_openwb_pro_disconnect_confirmed_ts"] = now_value
        _ensure_openwb_pro_plug_session(data, c_id)
        return {
            "stop_release": stop_release,
            "new_session_id": str(
                data.get("_openwb_pro_plug_session_id") or ""
            ),
        }

    persistence = _persist_openwb_pro_session_transaction(
        data,
        mutate,
        name="quick_replug_session_rotation",
    )
    result["persistence"] = persistence
    mutation = (
        persistence.get("mutation")
        if isinstance(persistence.get("mutation"), dict)
        else {}
    )
    stop_release = (
        mutation.get("stop_release")
        if isinstance(mutation.get("stop_release"), dict)
        else {}
    )
    new_session_id = str(mutation.get("new_session_id") or "")
    result["previous_stop_reason"] = str(stop_release.get("reason") or "")
    result["previous_session_stop_terminalized"] = bool(
        stop_release.get("terminalized", False)
    )
    if persistence.get("committed") is True and new_session_id:
        result.update({
            "rotated": True,
            "persisted": True,
            "new_session_id": new_session_id,
        })
        data["_openwb_pro_reconnect_contract"] = dict(result)
        return result

    result["persist_failed"] = True
    return result


def _rotate_openwb_pro_plug_session_after_meter_reset(
    c_data,
    *,
    c_id=None,
    now_ts=None,
):
    """Persistiert eine durch den Pro-Sitzungszähler belegte neue Session.

    Der Zählerreset ersetzt ausschließlich verpasste Disconnect-Frames. Alte
    Start-, Wake-up- und Phasenausgangsgenerationen werden gemeinsam mit der
    alten Stecksession terminalisiert; Safety-/Nutzeranker und die persistente
    480-s-Sperre gegen einen weiteren Phasenwechsel bleiben unangetastet.
    """

    data = c_data if isinstance(c_data, dict) else {}
    now_value = float(now_ts if now_ts is not None else time.time())
    previous_session_id = str(
        data.get("_openwb_pro_plug_session_id") or ""
    )
    result = {
        "contract": "openwb_pro_meter_reset_session_rotation_v1",
        "rotated": False,
        "persisted": False,
        "persist_failed": False,
        "previous_session_id": previous_session_id,
        "new_session_id": "",
        "hardware_write": False,
    }
    if not previous_session_id:
        result["blocker"] = "previous_session_missing"
        return result

    def mutate():
        stop_release = _terminalize_openwb_pro_previous_session_stop(data)
        _clear_openwb_pro_start_session(
            data,
            preserve_stop_barriers=not stop_release.get(
                "terminalized",
                False,
            ),
        )
        for key in _OPENWB_PRO_TERMINAL_PHASE_KEYS:
            data.pop(key, None)
        for key in _OPENWB_PRO_REPLUG_SESSION_KEYS:
            data.pop(key, None)
        if stop_release.get("terminalized", False):
            for key in _OPENWB_PRO_REPLUG_TERMINALIZED_STOP_KEYS:
                data.pop(key, None)
        _reset_wallbox_confirmed_disconnect_runtime(data)
        data["_openwb_pro_meter_reset_rotated_ts"] = now_value
        _ensure_openwb_pro_plug_session(data, c_id)
        return {
            "stop_release": stop_release,
            "new_session_id": str(
                data.get("_openwb_pro_plug_session_id") or ""
            ),
        }

    persistence = _persist_openwb_pro_session_transaction(
        data,
        mutate,
        name="connected_meter_reset_session_rotation",
    )
    result["persistence"] = persistence
    mutation = (
        persistence.get("mutation")
        if isinstance(persistence.get("mutation"), dict)
        else {}
    )
    stop_release = (
        mutation.get("stop_release")
        if isinstance(mutation.get("stop_release"), dict)
        else {}
    )
    new_session_id = str(mutation.get("new_session_id") or "")
    result["previous_stop_reason"] = str(
        stop_release.get("reason") or ""
    )
    result["previous_session_stop_terminalized"] = bool(
        stop_release.get("terminalized", False)
    )
    if (
        persistence.get("committed") is True
        and new_session_id
        and new_session_id != previous_session_id
    ):
        result.update({
            "rotated": True,
            "persisted": True,
            "new_session_id": new_session_id,
        })
        data["_openwb_pro_meter_reset_rotation"] = dict(result)
        return result

    result["persist_failed"] = True
    result["blocker"] = str(
        persistence.get("reason") or "dual_state_persist_failed"
    )
    return result


def _finalize_confirmed_openwb_pro_disconnect(
    c_data,
    *,
    now_ts=None,
):
    """Schließt die lange bestätigte Trennung in beiden State-Dateien."""

    data = c_data if isinstance(c_data, dict) else {}
    now_value = float(now_ts if now_ts is not None else time.time())

    def mutate():
        stop_release = _terminalize_openwb_pro_previous_session_stop(data)
        _clear_openwb_pro_start_session(
            data,
            preserve_stop_barriers=not stop_release.get(
                "terminalized",
                False,
            ),
        )
        for key in _OPENWB_PRO_TERMINAL_PHASE_KEYS:
            data.pop(key, None)
        for key in _OPENWB_PRO_REPLUG_SESSION_KEYS:
            data.pop(key, None)
        if stop_release.get("terminalized", False):
            for key in _OPENWB_PRO_REPLUG_TERMINALIZED_STOP_KEYS:
                data.pop(key, None)
        _reset_wallbox_confirmed_disconnect_runtime(data)
        data["_openwb_pro_disconnect_confirmed_ts"] = now_value
        data["_openwb_pro_phase_sequence"] = {}
        data["_openwb_pro_phase_sequence_stage"] = ""
        data["_last_phase_switch_ts"] = 0.0
        for key in (
            "_session_vehicle_key",
            "_session_vehicle_identity_source",
            "_session_vehicle_binding_id",
            "_vehicle_current_capability",
            "_vehicle_current_output_gate",
        ):
            data.pop(key, None)
        _remember_phase_target(data, 0)
        return {"stop_release": stop_release}

    return _persist_openwb_pro_session_transaction(
        data,
        mutate,
        name="confirmed_long_disconnect",
    )


def _observe_openwb_pro_start_session_edge(
    c_data,
    status,
    config=None,
    *,
    previous_status=None,
    c_id=None,
    now_ts=None,
):
    """Beobachtet die physische Pro-Steckkante vor jeder Wallbox-Policy.

    Der transiente Absteckkandidat bleibt absichtlich im RAM. Erst die
    bestätigte Trennung beziehungsweise neue Stecksession wird crashfest
    gespeichert; dadurch erzeugt der Status-Takt keine zusätzlichen
    Datenträgerschreibzugriffe.
    """

    data = c_data if isinstance(c_data, dict) else {}
    st = status if isinstance(status, dict) else {}
    active = data.get("charger")
    now_value = float(now_ts if now_ts is not None else time.time())
    result = {
        "contract": "openwb_pro_start_session_edge_v1",
        "observed": False,
        "connected": False,
        "status_fresh": False,
        "action": "not_openwb_pro",
        "candidate": {},
        "disconnect_confirmed": False,
        "rotated": False,
        "session_changed": False,
        "persisted": False,
        "persist_failed": False,
    }
    if not openwb_pro_session.is_openwb_pro_charger(active):
        return result

    result["observed"] = True
    connected = _wb_status_connected(st)
    result["connected"] = bool(connected)
    if not connected:
        if not str(data.get("_openwb_pro_plug_session_id") or ""):
            data.pop("_openwb_pro_disconnect_candidate", None)
            result["action"] = "disconnected_without_bound_session"
            return result
        if float(data.get("_openwb_disconnected_since", 0.0) or 0.0) <= 0.0:
            data["_openwb_disconnected_since"] = now_value
        disconnect_step = openwb_pro_session.start_disconnect_candidate_step(
            data,
            st,
            config,
            now_ts=now_value,
        )
        guard = (
            disconnect_step.get("guard")
            if isinstance(disconnect_step.get("guard"), dict)
            else {}
        )
        result["status_fresh"] = bool(guard.get("status_fresh", False))
        candidate = disconnect_step.get("candidate")
        candidate = dict(candidate) if isinstance(candidate, dict) else {}
        result["candidate"] = candidate
        result["guard"] = guard
        if candidate:
            data["_openwb_pro_disconnect_candidate"] = candidate
            result["action"] = "disconnect_candidate"
        else:
            data.pop("_openwb_pro_disconnect_candidate", None)
            result["action"] = "disconnect_not_confirmable"
        if disconnect_step.get("confirmed", False):
            persistence = _finalize_confirmed_openwb_pro_disconnect(
                data,
                now_ts=now_value,
            )
            result["disconnect_confirmed"] = True
            result["persistence"] = persistence
            result["persisted"] = bool(persistence.get("committed", False))
            result["persist_failed"] = not result["persisted"]
            result["action"] = (
                "disconnect_finalized"
                if result["persisted"]
                else "disconnect_persistence_failed"
            )
            if result["persist_failed"]:
                logger.error(
                    "WB%d bestätigte Trennung blieb fail-closed: %s",
                    c_id if c_id is not None else int(data.get("id", 0) or 0),
                    persistence.get("reason")
                    or "dual_state_persist_failed",
                )
        return result

    meter_reset = openwb_pro_session.connected_session_meter_reset_contract(
        previous_status,
        st,
    )
    reset_barriers = openwb_pro_session._start_session_reset_barriers(
        data,
        st,
        config,
        now_ts=now_value,
    )
    output_evidence_active = any(
        isinstance(data.get(key), dict) and bool(data.get(key))
        for key in (
            "_openwb_pro_phase_output_intent",
            "_openwb_pro_phase_output_ack",
            "_openwb_pro_phase_recovery_hold",
        )
    )
    short_phase_settle_active = bool(
        _cfg_float(data.get("_openwb_pro_phase_wait_until"), 0.0)
        > now_value
    )
    meter_reset_blockers = []
    if reset_barriers.get("cp_inactive") is not True:
        meter_reset_blockers.append("cp_active_or_unknown")
    if reset_barriers.get("wakeup_active") is True:
        meter_reset_blockers.append("wakeup_active")
    if reset_barriers.get("reservation_active") is True:
        meter_reset_blockers.append("phase_reservation_active")
    if reset_barriers.get("sequence_active") is True:
        meter_reset_blockers.append("phase_sequence_active")
    if output_evidence_active:
        meter_reset_blockers.append("phase_output_evidence_active")
    if short_phase_settle_active:
        meter_reset_blockers.append("phase_settle_active")
    result["meter_reset"] = {
        **meter_reset,
        "reset_barriers": dict(reset_barriers),
        "manager_blockers": list(meter_reset_blockers),
    }
    if meter_reset.get("confirmed") is True:
        if meter_reset_blockers:
            result["status_fresh"] = True
            result["action"] = "meter_reset_session_blocked"
            return result
        meter_rotation = (
            _rotate_openwb_pro_plug_session_after_meter_reset(
                data,
                c_id=c_id,
                now_ts=now_value,
            )
        )
        result["meter_reset_rotation"] = meter_rotation
        result["status_fresh"] = True
        result["rotated"] = bool(meter_rotation.get("rotated", False))
        result["persisted"] = bool(
            meter_rotation.get("persisted", False)
        )
        result["persist_failed"] = bool(
            meter_rotation.get("persist_failed", False)
        )
        result["action"] = (
            "meter_reset_session_rotated"
            if result["rotated"]
            else "meter_reset_session_persistence_failed"
        )
        return result

    replug_result = _rotate_openwb_pro_plug_session_after_reconnect(
        data,
        st,
        config,
        c_id=c_id,
        now_ts=now_value,
    )
    result["status_fresh"] = bool(replug_result.get("status_fresh", False))
    result["reconnect"] = replug_result
    result["rotated"] = bool(replug_result.get("rotated", False))
    result["persist_failed"] = bool(replug_result.get("persist_failed", False))
    if result["persist_failed"]:
        result["action"] = "reconnect_persistence_failed"
        return result
    if not (
        result["status_fresh"]
        and replug_result.get("connection_state") is True
    ):
        result["action"] = "wait_fresh_connection"
        return result

    data["_openwb_disconnected_since"] = 0.0
    data.pop("_openwb_pro_disconnect_candidate", None)
    if result["rotated"]:
        result["persisted"] = True
        result["action"] = "reconnect_rotated"
        return result

    session_changed = _ensure_openwb_pro_plug_session(data, c_id)
    result["session_changed"] = bool(session_changed)
    if not session_changed:
        result["action"] = "connected_session_unchanged"
        return result
    persisted = bool(_save_wallbox_phase_state([data]))
    result["persisted"] = persisted
    result["persist_failed"] = not persisted
    result["action"] = (
        "connected_session_created"
        if persisted
        else "connected_session_persistence_failed"
    )
    if persisted:
        data.pop("_openwb_pro_start_cp_persistence_blocked", None)
    else:
        data["_openwb_pro_start_cp_persistence_blocked"] = True
        logger.error(
            "WB%d neue openWB-Pro-Stecksession nicht persistierbar; "
            "automatische CP-Wakeups bleiben fail-closed gesperrt.",
            c_id if c_id is not None else int(data.get("id", 0) or 0),
        )
    return result


_OPENWB_PRO_DISCONNECTED_PHASE_TERMINAL_KEYS = (
    "_wallbox_phase_transition_reservation",
    "_phase_transition_grant",
    "_openwb_pro_phase_sequence",
    "_openwb_pro_phase_sequence_contract",
    "_openwb_pro_phase_sequence_last",
    "_openwb_pro_phase_sequence_stage",
    "_openwb_pro_phase_sequence_target",
    "_openwb_pro_phase_sequence_current_allowed_after",
    "_openwb_pro_phase_sequence_phase_sent_ts",
    "_openwb_pro_phase_sequence_cp_sent_ts",
    "_openwb_pro_phase_output_intent",
    "_openwb_pro_phase_output_ack",
    "_openwb_pro_phase_recovery_hold",
    "_openwb_pro_phase_restart_authorized",
    "_openwb_pro_phase_wait_target",
    "_openwb_pro_phase_wait_until",
    "_openwb_pro_phase_wait_min_until",
    "_openwb_pro_phase_wait_amp",
    "_openwb_pro_phase_wait_since",
    "_openwb_pro_phase_change_block_until",
    "_phase_target_cmd",
    "_phase_target_cmd_until",
    "_last_phase_switch_ts",
)


def _finalize_disconnected_openwb_pro_phase_transition(
    c_data,
    *,
    target,
    now_ts=None,
):
    """Beendet einen vollständig abgelaufenen Phasenvertrag ohne Geräte-I/O.

    Die aufrufende Phasenprüfung hat bereits frisches Abstecken, 0 A/0 W,
    inaktives CP, den gebundenen Ausgangs-ACK und den abgelaufenen
    480-Sekunden-Vertrag bewiesen. Stecksession und Wake-up-Budget bleiben
    davon getrennt und werden erst durch den bestehenden Replug-Vertrag
    erneuert. Die Phasenbereinigung wird vor einer Rückkehr persistent
    gesichert; bei einem Fehler bleibt die alte, fail-closed Generation
    vollständig erhalten.
    """

    data = c_data if isinstance(c_data, dict) else {}
    if not data or _valid_phase_count(target, 0) not in (1, 3):
        return False
    now_value = float(now_ts if now_ts is not None else time.time())
    previous = {
        key: (key in data, deepcopy(data.get(key)))
        for key in _OPENWB_PRO_DISCONNECTED_PHASE_TERMINAL_KEYS
    }

    for key in _OPENWB_PRO_DISCONNECTED_PHASE_TERMINAL_KEYS:
        data.pop(key, None)
    openwb_pro_session.clear_phase_wait(data)
    data["_openwb_pro_phase_change_block_until"] = 0.0
    data["_last_phase_switch_ts"] = 0.0
    _remember_phase_target(data, 0)
    data["_openwb_pro_disconnected_phase_terminalized_ts"] = now_value
    data["_openwb_pro_disconnected_phase_terminalized_target"] = int(target)
    data.pop("_openwb_pro_disconnected_phase_terminalize_persist_failed", None)

    if _save_wallbox_phase_state([data]):
        return True

    for key, (present, value) in previous.items():
        if present:
            data[key] = value
        else:
            data.pop(key, None)
    data.pop("_openwb_pro_disconnected_phase_terminalized_ts", None)
    data.pop("_openwb_pro_disconnected_phase_terminalized_target", None)
    data["_openwb_pro_disconnected_phase_terminalize_persist_failed"] = True
    return False


def _finalize_completed_openwb_pro_phase_transition(c_data, status, *, now_ts=None):
    """Persistiere den terminal bestätigten Phasenwechsel genau einmal.

    Der Abschluss ist nur zulässig, nachdem die bestehende Reservierung über
    mehrere frische Frames reale Ladeleistung auf der Zielphase bestätigt
    hat. Ein bloß erfolgreich zurückgekehrter Send-Aufruf genügt nicht.
    """

    data = c_data if isinstance(c_data, dict) else {}
    st = status if isinstance(status, dict) else {}
    reservation = data.get("_wallbox_phase_transition_reservation")
    if not isinstance(reservation, dict):
        return False
    target = _valid_phase_count(reservation.get("target_phases"), 0)
    if (
        reservation.get("active")
        or str(reservation.get("stage") or "") != "completed"
        or target not in (1, 3)
        or not openwb_pro_session.phase_target_readback_confirmed(st, target)
    ):
        return False

    is_idle_transition = bool(
        _cfg_float(reservation.get("restart_amp"), 0.0) <= 0.5
        or _cfg_int(reservation.get("requested_w"), 0) == 0
        or _cfg_float(data.get("current_set_amp"), 0.0) <= 0.5
        or _cfg_float(st.get("evse_current"), 0.0) <= 0.5
    )
    if not is_idle_transition and wallbox_phase_transition.status_power_w(st) <= 500.0:
        return False

    cleanup_keys = (
        _OPENWB_PRO_TERMINAL_PHASE_KEYS
        + _OPENWB_PRO_COMPLETED_PHASE_WAIT_KEYS
    )
    previous = {
        key: data[key]
        for key in cleanup_keys
        if key in data
    }
    for key in cleanup_keys:
        data.pop(key, None)
    if _save_wallbox_phase_state([data]):
        data["_openwb_pro_phase_terminal_completed_ts"] = float(
            now_ts if now_ts is not None else time.time()
        )
        data["_openwb_pro_phase_terminal_target"] = target
        return True

    data.update(previous)
    intent = previous.get("_openwb_pro_phase_output_intent")
    _phase_output_recovery_hold(
        data,
        "phase_terminal_cleanup_persist_failed",
        intent if isinstance(intent, dict) else None,
    )
    return False


def _finalize_process_restart_preoutput_openwb_pro_phase_transition(
    c_data, status, *, now_ts=None
):
    """Supersediert eine alte No-output-Generation ohne Geräteausgang."""

    data = c_data if isinstance(c_data, dict) else {}
    st = status if isinstance(status, dict) else {}
    marker = data.get("_openwb_pro_phase_preoutput_restart_probe")
    marker = marker if isinstance(marker, dict) else {}
    readback_ts = _cfg_float(st.get("driver_status_last_ok_ts"), 0.0)
    if readback_ts > 100_000_000_000.0:
        readback_ts /= 1000.0
    target = _valid_phase_count(marker.get("target_phases"), 0)
    observed = _wallbox_observed_phase_count(st)
    if not (
        marker.get("active") is True
        and _wallbox_status_fresh_real_charging(st)
        and readback_ts > _cfg_float(marker.get("restored_ts"), 0.0) > 0.0
        and st.get("cp_interrupt_isactive") in (False, 0)
        and _wb_status_connected(st)
        and _wb_status_real_power(st) > 500.0
        and st.get("phase_power_verified") is True
        and target in (1, 3)
        and observed in (1, 3)
        and observed != target
        and (_fresh_wallbox_reported_current_amp(st) or 0.0) >= 5.5
    ):
        return False
    result = _supersede_openwb_pro_preoutput_phase_reservation(
        data,
        observed,
        now_ts=float(now_ts if now_ts is not None else time.time()),
    )
    result.update({
        "source": "process_restart_fresh_opposite_phase_charge",
        "observed_phases": observed,
        "observed_power_w": round(_wb_status_real_power(st), 3),
        "hardware_write": False,
    })
    data["_openwb_pro_phase_preoutput_restart_terminal"] = dict(result)
    done = result.get("superseded") is True and result.get("persisted") is True
    if done:
        data.pop("_openwb_pro_phase_preoutput_restart_probe", None)
    return done


def _finalize_expired_uncommitted_openwb_pro_phase_transition(
    c_data,
    status,
    *,
    now_ts=None,
):
    """Entfernt persistent einen abgelaufenen Phasenauftrag, der nie einen Ausgang besaß.

    Dieser Terminalizer führt kein Geräte-I/O aus. Mehrdeutige Sequenz-, Intent-,
    CP- oder Readback-Generationen bleiben fail-closed. Bei einem Persistenzfehler
    wird die vorige Generation wiederhergestellt und in einen Recovery-Hold überführt.
    """

    data = c_data if isinstance(c_data, dict) else {}
    st = status if isinstance(status, dict) else {}
    if not openwb_pro_session.is_openwb_pro_charger(data.get("charger")):
        return False
    reservation = data.get("_wallbox_phase_transition_reservation")
    if not isinstance(reservation, dict):
        return False
    now_value = float(now_ts if now_ts is not None else time.time())
    wakeup_until = max(
        _cfg_float(data.get("_openwb_pro_start_wakeup_allowed_after"), 0.0),
        _cfg_float(data.get("_openwb_pro_phase_wait_until"), 0.0),
    )
    resolution = wallbox_phase_transition.expiration_resolution_contract(
        reservation,
        status=st,
        now_ts=now_value,
        sequence=data.get("_openwb_pro_phase_sequence"),
        output_intent=data.get("_openwb_pro_phase_output_intent"),
        output_ack=data.get("_openwb_pro_phase_output_ack"),
        recovery_hold=data.get("_openwb_pro_phase_recovery_hold"),
        restart_authorized=data.get("_openwb_pro_phase_restart_authorized"),
        wakeup_active=bool(
            wakeup_until > now_value
            or data.get("_openwb_cp_start_sent", False)
        ),
        clock_sample=_openwb_pro_control_time_sample(wall_ts=now_value),
    )
    data["_openwb_pro_phase_expiration_contract"] = resolution
    if not resolution.get("terminal", False):
        return False

    previous = {
        key: data[key]
        for key in _OPENWB_PRO_TERMINAL_PHASE_KEYS
        if key in data
    }
    for key in _OPENWB_PRO_TERMINAL_PHASE_KEYS:
        data.pop(key, None)
    if _save_wallbox_phase_state([data]):
        data["_openwb_pro_phase_terminal_expired_ts"] = now_value
        data["_openwb_pro_phase_terminal_expired_reason"] = str(
            resolution.get("reason") or "expired_uncommitted_idle_confirmed"
        )
        return True

    data.update(previous)
    intent = previous.get("_openwb_pro_phase_output_intent")
    _phase_output_recovery_hold(
        data,
        "phase_expiration_cleanup_persist_failed",
        intent if isinstance(intent, dict) else None,
    )
    data["_openwb_pro_phase_expiration_contract"] = {
        **resolution,
        "action": "recovery_hold",
        "terminal": False,
        "reason": "phase_expiration_cleanup_persist_failed",
    }
    return False


def _wallbox_phase_transition_reservation(chargers, statuses=None, now_ts=None):
    """Aggregiere Phasenwechsel-Reservierungen aller überwachten Wallboxen."""

    now_value = float(now_ts if now_ts is not None else time.time())
    clock_sample = _openwb_pro_control_time_sample(wall_ts=now_value)
    status_by_id = {
        int(entry.get("id", 0) or 0): entry.get("status")
        for entry in (statuses if isinstance(statuses, list) else []) if isinstance(entry, dict)
        if int(entry.get("id", 0) or 0) > 0 and isinstance(entry.get("status"), dict)
    }
    for box in chargers if isinstance(chargers, list) else []:
        if not isinstance(box, dict):
            continue
        charger = box.get("charger")
        charger_id = int(box.get("id", 0) or 0)
        status = status_by_id.get(charger_id) or _openwb_pro_driver_status(box, charger)
        if _is_e3dc_shared_rscp_charger(charger, status):
            box.pop("_wallbox_phase_transition_reservation", None)
            box.pop("_phase_transition_grant", None)
            continue
        has_connection_state = any(
            key in status
            for key in ("plug_state", "car", "connected", "plugged")
        )
        connected = (
            bool(openwb_pro_session.status_connected(status))
            if has_connection_state
            else None
        )
        terminalized = (
            _finalize_process_restart_preoutput_openwb_pro_phase_transition(
                box, status, now_ts=now_value
            )
        )
        restart_probe = box.get("_openwb_pro_phase_preoutput_restart_probe")
        if terminalized:
            updated = wallbox_phase_transition.inactive_reservation(
                "process_restart_preoutput_superseded"
            )
        elif isinstance(restart_probe, dict) and restart_probe.get("active") is True:
            # Den alten Guard bis zum frischen Readback nicht auf 720 s rearmen.
            updated = wallbox_phase_transition.public_reservation(
                box.get("_wallbox_phase_transition_reservation"), now_value
            )
        else:
            updated = phase_transition_reservation(
                box,
                status=status,
                now_ts=now_value,
                connected=connected,
                clock_sample=clock_sample,
            )
            if _finalize_expired_uncommitted_openwb_pro_phase_transition(
                box, status, now_ts=now_value
            ):
                updated = wallbox_phase_transition.inactive_reservation(
                    "expired_uncommitted_idle_confirmed"
                )
        if str(updated.get("stage") or "") == "completed" and not updated.get("active"):
            _finalize_completed_openwb_pro_phase_transition(
                box,
                status,
                now_ts=now_value,
            )
    aggregate = wallbox_phase_transition.aggregate_reservations(
        chargers,
        now_ts=now_value,
    )
    reservations = aggregate.get("reservations", [])
    box_by_id = {
        int(box.get("id", 0) or 0): box
        for box in chargers if isinstance(box, dict)
        if int(box.get("id", 0) or 0) > 0
    }
    for item in reservations:
        if not isinstance(item, dict):
            continue
        source_box = box_by_id.get(int(item.get("wb_id", 0) or 0), {})
        item["bev_full_blocked"] = bool(
            source_box.get("_bev_full_blocked", False)
        )
        item["bev_full_block_reason"] = str(
            source_box.get("_bev_full_block_reason") or ""
        )
    targets = aggregate.get("targets", [])
    sources = sorted({str(item.get("source") or "") for item in reservations if str(item.get("source") or "")})
    aggregate.update({
        "target_phases": targets[0] if len(targets) == 1 else 0,
        "source": sources[0] if len(sources) == 1 else ("manager_phase_commands" if sources else ""),
        "details": [
            dict(item, charger_id=int(item.get("wb_id", 0) or 0))
            for item in reservations
        ],
    })
    return aggregate


def _apply_phase_transition_grants(chargers, budget_surface, *, now_ts=None):
    """Ordnet Storage-Manager-Freigaben den passenden Wallboxreservierungen zu."""

    budget = budget_surface if isinstance(budget_surface, dict) else {}
    nested = budget.get("wallbox_phase_transition_grants")
    grants = (
        nested.get("grants")
        if isinstance(nested, dict)
        else budget.get("phase_transition_grants")
    )
    grants = grants if isinstance(grants, list) else []
    by_id = {str(item.get("reservation_id") or ""): item for item in grants if isinstance(item, dict)}
    now_value = time.time() if now_ts is None else float(now_ts)
    for box in chargers if isinstance(chargers, list) else []:
        reservation = box.get("_wallbox_phase_transition_reservation") if isinstance(box, dict) else None
        reservation_id = str(reservation.get("reservation_id") or "") if isinstance(reservation, dict) else ""
        grant = by_id.get(reservation_id)
        if grant is None:
            if isinstance(box, dict):
                box.pop("_phase_transition_grant", None)
            continue
        box["_phase_transition_grant"] = dict(grant)
        wallbox_phase_transition.apply_grant(box, grant, now_ts=now_value)


def _apply_start_hold_grants(chargers, budget_surface, *, now_ts=None):
    """Bindet ausschließlich aktuelle Storage-Start-Haltefreigaben.

    Ein fehlender, inaktiver oder durch den finalen Storage-Runtime-Cap
    entfernter Grant widerruft die lokale Freigabe im selben Managerzyklus.
    """

    budget = budget_surface if isinstance(budget_surface, dict) else {}
    nested = budget.get("wallbox_start_hold_grants")
    nested = nested if isinstance(nested, dict) else {}
    grants = (
        nested.get("grants")
        if (
            nested.get("schema_version") == wallbox_start_hold.GRANT_SCHEMA
            and nested.get("active") is True
        )
        else []
    )
    grants = grants if isinstance(grants, list) else []
    by_reservation = {
        str(item.get("reservation_id") or ""): item
        for item in grants
        if isinstance(item, dict) and str(item.get("reservation_id") or "")
    }
    now_value = time.time() if now_ts is None else float(now_ts)
    applied_ids = []
    revoked_ids = []
    for box in chargers if isinstance(chargers, list) else []:
        if not isinstance(box, dict):
            continue
        request = box.get(wallbox_start_hold.STATE_KEY)
        reservation_id = (
            str(request.get("reservation_id") or "")
            if isinstance(request, dict)
            else ""
        )
        grant = by_reservation.get(reservation_id)
        applied = (
            wallbox_start_hold.apply_grant(
                box,
                grant,
                now_ts=now_value,
            )
            if isinstance(grant, dict)
            else {}
        )
        wb_id = int(_cfg_float(box.get("id"), 0.0))
        if applied:
            applied_ids.append(wb_id)
        else:
            box.pop(wallbox_start_hold.GRANT_KEY, None)
            if wb_id > 0:
                revoked_ids.append(wb_id)
    return {
        "schema_version": "wallbox_start_hold_grant_binding_v1",
        "active": bool(applied_ids),
        "applied_ids": sorted(set(applied_ids)),
        "revoked_ids": sorted(set(revoked_ids)),
    }


def _wallbox_start_hold_status_fresh(status):
    st = status if isinstance(status, dict) else {}
    return bool(
        st
        and st.get("driver_status_valid") is True
        and not bool(st.get("driver_status_stale", False))
        and not bool(st.get("driver_status_degraded", False))
        and not bool(st.get("driver_status_glitch", False))
        and st.get("valid") is not False
        and not bool(st.get("stale", False))
    )


def _fresh_non_native_idle_zero_confirmed(status):
    """Bestätigt einen frischen gemessenen 0-A-/0-W-Ruhezustand.

    Fehlende Stromfelder dürfen nicht wie eine echte Null behandelt werden.
    Nur dieser positive Readback-Beleg unterdrückt die einmalige konservative
    Stopkante eines Nicht-E3DC-Treibers.
    """

    st = status if isinstance(status, dict) else {}
    if not _wallbox_start_hold_status_fresh(st):
        return False
    measured_currents = []
    for key in ("offered_current_raw", "offered_current", "evse_current", "amp"):
        if key not in st or st.get(key) is None or isinstance(st.get(key), bool):
            continue
        try:
            value = float(st.get(key))
        except (TypeError, ValueError, OverflowError):
            return False
        if not math.isfinite(value):
            return False
        measured_currents.append(abs(value))
    if not measured_currents:
        return False
    return bool(
        max(measured_currents) <= 0.5
        and not _wb_status_real_charging(st)
        and _wb_status_real_power(st) <= 100.0
    )


def _wallbox_start_hold_requests(
    chargers,
    chargers_status,
    allocations,
    phase_count_by_id,
    watts_per_amp_by_id,
    *,
    enabled_by_id=None,
    blocked_by_id=None,
    min_amp=6,
    now_ts=None,
):
    """Öffnet pro physischer Stecksession höchstens einen Start-Halteversuch.

    Nach einem Managerneustart wird eine bereits verbundene Session nur
    übernommen und als verbraucht markiert. Erst eine danach frisch gesehene
    Absteck-/Ansteckkante darf einen neuen Versuch erzeugen.
    """

    now_value = time.time() if now_ts is None else float(now_ts)
    boxes = [item for item in (chargers or []) if isinstance(item, dict)]
    status_by_id = {
        int(_cfg_float(item.get("id"), 0.0)): item.get("status")
        for item in (chargers_status or [])
        if isinstance(item, dict) and int(_cfg_float(item.get("id"), 0.0)) > 0
    }
    allocation_by_id = allocations if isinstance(allocations, dict) else {}
    phases_by_id = phase_count_by_id if isinstance(phase_count_by_id, dict) else {}
    enabled = enabled_by_id if isinstance(enabled_by_id, dict) else {}
    blocked = blocked_by_id if isinstance(blocked_by_id, dict) else {}
    watts_per_amp = (
        watts_per_amp_by_id
        if isinstance(watts_per_amp_by_id, dict)
        else {}
    )
    minimum_amp = max(1, int(_cfg_float(min_amp, 6.0)))

    connected_by_id = {}
    fresh_by_id = {}
    for box in boxes:
        wb_id = int(_cfg_float(box.get("id"), 0.0))
        if wb_id <= 0:
            continue
        status = status_by_id.get(wb_id)
        fresh = _wallbox_start_hold_status_fresh(status)
        connected = bool(fresh and _wb_status_connected(status))
        fresh_by_id[wb_id] = fresh
        connected_by_id[wb_id] = connected
        if fresh and not connected:
            box[wallbox_start_hold.DISCONNECT_SEEN_KEY] = True
            box.pop(wallbox_start_hold.SESSION_KEY, None)
            box.pop(wallbox_start_hold.STATE_KEY, None)
            box.pop(wallbox_start_hold.GRANT_KEY, None)
            continue
        if not connected:
            continue

        external_session = str(
            box.get("_openwb_pro_plug_session_id") or ""
        )
        session_id = str(box.get(wallbox_start_hold.SESSION_KEY) or "")
        disconnect_seen = bool(
            box.get(wallbox_start_hold.DISCONNECT_SEEN_KEY, False)
        )
        consumed_session = str(
            box.get(wallbox_start_hold.CONSUMED_SESSION_KEY) or ""
        )
        if disconnect_seen:
            candidate = external_session
            if not candidate or candidate == consumed_session:
                candidate = "start-hold:%d:%d:%d" % (
                    wb_id,
                    int(max(0.0, now_value) * 1000.0),
                    time.monotonic_ns(),
                )
            session_id = candidate
            box[wallbox_start_hold.SESSION_KEY] = session_id
            box[wallbox_start_hold.DISCONNECT_SEEN_KEY] = False
        elif not session_id:
            # Fail-closed Restart-Adoption: ohne nach diesem Prozessstart
            # beobachtete Trennung darf die bestehende Verbindung keinen
            # neuen 40-Wh-Vertrag eröffnen.
            session_id = external_session or "start-hold:%d:%d:%d" % (
                wb_id,
                int(max(0.0, now_value) * 1000.0),
                time.monotonic_ns(),
            )
            box[wallbox_start_hold.SESSION_KEY] = session_id
            box[wallbox_start_hold.CONSUMED_SESSION_KEY] = session_id
            box.pop(wallbox_start_hold.STATE_KEY, None)
            box.pop(wallbox_start_hold.GRANT_KEY, None)
        elif external_session and external_session != session_id:
            # Ein Sessionwechsel ohne bestätigte Disconnect-Kante wird nur
            # adoptiert, niemals als neuer Start interpretiert.
            session_id = external_session
            box[wallbox_start_hold.SESSION_KEY] = session_id
            box[wallbox_start_hold.CONSUMED_SESSION_KEY] = session_id
            box.pop(wallbox_start_hold.STATE_KEY, None)
            box.pop(wallbox_start_hold.GRANT_KEY, None)

    group_members = []
    allocation_ready_by_id = {}
    for box in boxes:
        wb_id = int(_cfg_float(box.get("id"), 0.0))
        allocation = allocation_by_id.get(
            wb_id,
            allocation_by_id.get(str(wb_id), {}),
        )
        allocation = allocation if isinstance(allocation, dict) else {}
        amp = _cfg_float(
            allocation.get(
                "target_amp_per_phase",
                allocation.get("target_amp", 0.0),
            ),
            0.0,
        )
        phases = int(
            _cfg_float(
                allocation.get(
                    "target_phases",
                    phases_by_id.get(wb_id, phases_by_id.get(str(wb_id), 0)),
                ),
                0.0,
            )
        )
        is_enabled = bool(enabled.get(wb_id, enabled.get(str(wb_id), True)))
        is_blocked = bool(blocked.get(wb_id, blocked.get(str(wb_id), False)))
        allocation_ready = bool(
            connected_by_id.get(wb_id, False)
            and fresh_by_id.get(wb_id, False)
            and is_enabled
            and not is_blocked
            and phases in (1, 3)
            and (
                abs(amp - float(minimum_amp)) <= 0.001
                or (amp == 0.0 and not _wb_status_real_charging(status_by_id.get(wb_id)))
            )
        )
        allocation_ready_by_id[wb_id] = allocation_ready
        session_id = str(box.get(wallbox_start_hold.SESSION_KEY) or "")
        if not allocation_ready or not session_id:
            continue
        per_amp_w = max(
            1.0,
            _cfg_float(
                watts_per_amp.get(wb_id, watts_per_amp.get(str(wb_id), 230.0)),
                230.0,
            ),
        )
        group_members.append({
            "wb_id": wb_id,
            "plug_session_id": session_id,
            "target_phases": phases,
            "minimum_amp": minimum_amp,
            "minimum_power_w": int(
                round(minimum_amp * per_amp_w * phases)
            ),
        })
    group_members.sort(key=lambda item: item["wb_id"])
    group_minimum_w = sum(
        int(item.get("minimum_power_w", 0) or 0)
        for item in group_members
    )

    projected = []
    for box in boxes:
        wb_id = int(_cfg_float(box.get("id"), 0.0))
        session_id = str(box.get(wallbox_start_hold.SESSION_KEY) or "")
        is_enabled = bool(enabled.get(wb_id, enabled.get(str(wb_id), True)))
        is_blocked = bool(blocked.get(wb_id, blocked.get(str(wb_id), False)))
        allocation_ready = bool(allocation_ready_by_id.get(wb_id, False))
        request = box.get(wallbox_start_hold.STATE_KEY)
        consumed_session = str(
            box.get(wallbox_start_hold.CONSUMED_SESSION_KEY) or ""
        )
        current_member = next(
            (
                item
                for item in group_members
                if int(item.get("wb_id", 0) or 0) == wb_id
            ),
            None,
        )
        request_member = next(
            (
                item
                for item in (
                    request.get("group_members")
                    if isinstance(request, dict)
                    and isinstance(request.get("group_members"), list)
                    else []
                )
                if isinstance(item, dict)
                and int(item.get("wb_id", 0) or 0) == wb_id
            ),
            None,
        )
        request_matches_allocation = bool(
            not isinstance(request, dict)
            or (
                isinstance(current_member, dict)
                and isinstance(request_member, dict)
                and int(request.get("target_phases", 0) or 0)
                == int(current_member.get("target_phases", 0) or 0)
                == int(request_member.get("target_phases", 0) or 0)
                and int(request.get("minimum_amp", 0) or 0)
                == int(current_member.get("minimum_amp", 0) or 0)
                == int(request_member.get("minimum_amp", 0) or 0)
                and int(request.get("minimum_quantum_w", 0) or 0)
                == int(current_member.get("minimum_power_w", 0) or 0)
                == int(request_member.get("minimum_power_w", 0) or 0)
            )
        )
        if (
            allocation_ready
            and session_id
            and consumed_session != session_id
            and not isinstance(request, dict)
        ):
            member = current_member
            if isinstance(member, dict):
                request = wallbox_start_hold.begin_request(
                    box,
                    wb_id=wb_id,
                    plug_session_id=session_id,
                    request_cycle_token=str(
                        box.get("_wallbox_cycle_token") or ""
                    ),
                    group_id="start-hold:%s" % str(
                        box.get("_wallbox_cycle_token") or ""
                    ),
                    group_minimum_w=group_minimum_w,
                    minimum_quantum_w=int(
                        member.get("minimum_power_w", 0) or 0
                    ),
                    group_members=group_members,
                    target_phases=int(member.get("target_phases", 0) or 0),
                    minimum_amp=minimum_amp,
                    now_ts=now_value,
                )
                if request:
                    box[wallbox_start_hold.CONSUMED_SESSION_KEY] = session_id
        if not isinstance(request, dict):
            continue
        item = wallbox_start_hold.request_for_intent(
            box,
            now_ts=now_value,
            connected=bool(connected_by_id.get(wb_id, False)),
            status_fresh=bool(fresh_by_id.get(wb_id, False)),
            enabled=is_enabled,
            blocked=bool(
                is_blocked
                or not allocation_ready
                or not request_matches_allocation
            ),
        )
        if item:
            projected.append(item)
    return wallbox_start_hold.aggregate_requests(projected)


def _wallbox_materialized_start_hold_budget_contract(
    box,
    *,
    base_budget_w,
    allocated_amp,
    allocated_phases,
    minimum_amp=6,
    now_ts=None,
):
    """Belegt eine Storage-Freigabe nur aus dem bereits zentralen Ausgang."""

    now_value = time.time() if now_ts is None else float(now_ts)
    data = box if isinstance(box, dict) else {}
    bound = wallbox_start_hold.committed_grant_budget(
        data,
        base_budget_w=base_budget_w,
        now_ts=now_value,
    )
    try:
        amp = float(allocated_amp or 0.0)
        phases = int(round(float(allocated_phases or 0)))
        budget_w = max(0.0, float(base_budget_w or 0.0))
    except (TypeError, ValueError):
        amp = 0.0
        phases = 0
        budget_w = 0.0
    member = next(
        (
            item
            for item in (bound.get("group_members") or [])
            if isinstance(item, dict)
            and int(_cfg_float(item.get("wb_id"), 0.0))
            == int(_cfg_float(data.get("id"), 0.0))
        ),
        None,
    )
    expected_phases = int(
        _cfg_float((member or {}).get("target_phases"), 0.0)
    )
    expected_amp = int(
        _cfg_float((member or {}).get("minimum_amp"), 0.0)
    )
    minimum_w = max(
        0.0,
        _cfg_float((member or {}).get("minimum_power_w"), 0.0),
    )
    materialized = bool(
        bound.get("bound") is True
        and isinstance(member, dict)
        and expected_phases in (1, 3)
        and phases == expected_phases
        and expected_amp == int(_cfg_float(minimum_amp, 6.0)) == 6
        and minimum_w + 0.001
        >= float(expected_amp * 230 * expected_phases)
        and abs(amp - float(expected_amp)) <= 0.001
        and budget_w + 0.001 >= minimum_w
    )
    return {
        **bound,
        "active": materialized,
        "materialized_in_central_budget": materialized,
        "allocated_amp": amp,
        "allocated_phases": phases,
        "contract_phases": expected_phases,
        "contract_minimum_amp": expected_amp,
        "contract_minimum_power_w": minimum_w,
        "base_budget_w": budget_w,
        # Der Manager bestätigt hier nur die vorhandene Storage-Allokation.
        # Er erzeugt ausdrücklich kein zweites Leistungsbudget.
        "extension_w": 0,
        "reason": (
            "storage_grant_already_materialized"
            if materialized
            else "minimum_not_materialized"
            if bound.get("bound") is True
            else str(bound.get("reason") or "no_committed_matching_grant")
        ),
    }


def _wallbox_start_hold_granted_allocation(
    allocations,
    *,
    base_fresh_budget_w,
    gross_base_budget_w,
    grace_reserved_w,
    chargers,
    chargers_status,
    priority_mode,
    max_amp,
    charge_modes,
    grid_allowed_charger_ids,
    max_amp_by_id,
    phase_count_by_id,
    watts_per_amp_by_id,
    min_amp=6,
    now_ts=None,
):
    """Validiert Start-Hold gegen die zentrale Allocation ohne Neuberechnung."""

    del priority_mode, max_amp, charge_modes, grid_allowed_charger_ids
    del max_amp_by_id, phase_count_by_id, watts_per_amp_by_id
    now_value = time.time() if now_ts is None else float(now_ts)
    result = {
        key: (dict(value) if isinstance(value, dict) else value)
        for key, value in (
            allocations.items() if isinstance(allocations, dict) else ()
        )
    }
    box_by_id = {
        int(_cfg_float(box.get("id"), 0.0)): box
        for box in (chargers or [])
        if isinstance(box, dict) and int(_cfg_float(box.get("id"), 0.0)) > 0
    }
    rejected = {}
    accepted = []
    for wb_id in sorted(box_by_id):
        box = box_by_id[wb_id]
        bound = wallbox_start_hold.committed_grant_budget(
            box,
            base_budget_w=base_fresh_budget_w,
            now_ts=now_value,
        )
        if bound.get("bound") is not True:
            continue
        grant = box.get(wallbox_start_hold.GRANT_KEY)
        members = (
            grant.get("group_members")
            if isinstance(grant, dict)
            else []
        )
        materialized_w = 0.0
        protected_ids = []
        member_missing = False
        for member in members if isinstance(members, list) else []:
            member_id = int(_cfg_float(member.get("wb_id"), 0.0))
            allocation = result.get(
                member_id,
                result.get(str(member_id), {}),
            )
            allocation = allocation if isinstance(allocation, dict) else {}
            target_amp = _cfg_float(
                allocation.get(
                    "target_amp_per_phase",
                    allocation.get("target_amp", 0.0),
                ),
                0.0,
            )
            target_phases = int(
                _cfg_float(allocation.get("target_phases"), 0.0)
            )
            target_power_w = max(
                0.0,
                _cfg_float(allocation.get("target_power_w"), 0.0),
            )
            member_min_amp = int(_cfg_float(member.get("minimum_amp"), min_amp))
            member_phases = int(
                _cfg_float(member.get("target_phases"), 0.0)
            )
            member_min_w = max(
                0.0,
                _cfg_float(member.get("minimum_power_w"), 0.0),
            )
            member_ok = bool(
                member_id > 0
                and member_phases in (1, 3)
                and target_phases == member_phases
                and abs(target_amp - float(member_min_amp)) <= 0.001
                and member_min_w + 0.001
                >= float(member_min_amp * 230 * member_phases)
                and target_power_w + 0.001 >= member_min_w
            )
            if not member_ok:
                member_missing = True
                continue
            protected_ids.append(member_id)
            materialized_w += target_power_w
        grant_total_w = max(
            0.0,
            _cfg_float(
                grant.get("granted_total_budget_w")
                if isinstance(grant, dict)
                else 0.0,
                0.0,
            ),
        )
        centrally_funded = bool(
            max(0.0, _cfg_float(base_fresh_budget_w, 0.0)) + 0.001
            >= grant_total_w
            and max(0.0, _cfg_float(gross_base_budget_w, 0.0)) + 0.001
            >= grant_total_w
        )
        materialized = bool(
            members
            and not member_missing
            and centrally_funded
            and materialized_w + 0.001 >= grant_total_w
        )
        if not materialized:
            rejected.setdefault(wb_id, []).append("minimum_not_materialized")
            continue
        accepted.append({
            "wb_id": wb_id,
            "protected_ids": sorted(set(protected_ids)),
            "materialized_w": materialized_w,
            "grant_total_w": grant_total_w,
        })
    selected = max(
        accepted,
        key=lambda item: (
            len(item.get("protected_ids") or []),
            float(item.get("grant_total_w", 0.0) or 0.0),
            int(item.get("wb_id", 0) or 0),
        ),
        default=None,
    )
    active = isinstance(selected, dict)
    return result, {
        "schema_version": "wallbox_start_hold_materialization_v1",
        "active": active,
        "bound": bool(accepted or rejected),
        "reason": (
            "storage_grant_already_materialized"
            if active
            else "minimum_not_materialized"
            if rejected
            else "no_committed_matching_grant"
        ),
        "selected_wb_id": int((selected or {}).get("wb_id", 0) or 0),
        "protected_ids": list((selected or {}).get("protected_ids") or []),
        "materialized_w": float((selected or {}).get("materialized_w", 0.0) or 0.0),
        "base_fresh_budget_w": max(0.0, _cfg_float(base_fresh_budget_w, 0.0)),
        "gross_base_budget_w": max(0.0, _cfg_float(gross_base_budget_w, 0.0)),
        "grace_reserved_w": max(0.0, _cfg_float(grace_reserved_w, 0.0)),
        "extension_w": 0.0,
        "rejected": rejected,
    }


def _start_hold_member_materialization(
    box,
    status,
    *,
    minimum_amp=6,
    grant_owner_box=None,
    now_ts=None,
):
    data = box if isinstance(box, dict) else {}
    grant_owner = (
        grant_owner_box
        if isinstance(grant_owner_box, dict)
        else data
    )
    st = status if isinstance(status, dict) else {}
    now_value = time.time() if now_ts is None else float(now_ts)
    blockers = []
    if not _wallbox_start_hold_status_fresh(st) or not _wb_status_real_charging(st):
        blockers.append("status_not_fresh")
    if not _wb_status_connected(st):
        blockers.append("not_connected")
    phases = _wallbox_observed_phase_count(st)
    amp = max(
        _cfg_float(st.get("offered_current_raw"), 0.0),
        _cfg_float(st.get("offered_current"), 0.0),
        _cfg_float(st.get("evse_current"), 0.0),
        _cfg_float(st.get("amp"), 0.0),
        _cfg_float(data.get("current_set_amp"), 0.0),
    )
    cap = data.get("_multi_allocation_output_cap")
    cap = cap if isinstance(cap, dict) else {}
    cap_amp = _cfg_float(cap.get("cap_amp"), 0.0)
    cycle_token = str(data.get("_wallbox_cycle_token") or "")
    bound = wallbox_start_hold.committed_grant_budget(
        grant_owner,
        base_budget_w=0,
        now_ts=now_value,
    )
    member = next(
        (
            item
            for item in (bound.get("group_members") or [])
            if isinstance(item, dict)
            and int(_cfg_float(item.get("wb_id"), 0.0))
            == int(_cfg_float(data.get("id"), 0.0))
        ),
        None,
    )
    expected_phases = int(
        _cfg_float((member or {}).get("target_phases"), 0.0)
    )
    expected_amp = int(
        _cfg_float((member or {}).get("minimum_amp"), 0.0)
    )
    current_session_id = str(
        data.get(wallbox_start_hold.SESSION_KEY)
        or data.get("_openwb_pro_plug_session_id")
        or ""
    )
    expected_session_id = str(
        (member or {}).get("plug_session_id") or ""
    )
    if (
        bound.get("bound") is not True
        or not isinstance(member, dict)
        or expected_phases not in (1, 3)
        or expected_amp != int(_cfg_float(minimum_amp, 6.0))
    ):
        blockers.append("start_hold_member_not_bound")
    if (
        not current_session_id
        or current_session_id != expected_session_id
    ):
        blockers.append("start_hold_member_session_mismatch")
    if (
        cap.get("active") is not True
        or not cycle_token
        or str(cap.get("cycle_token") or "") != cycle_token
        or abs(cap_amp - float(minimum_amp)) > 0.001
    ):
        blockers.append("six_amp_not_authorized")
    if (
        phases != expected_phases
        or abs(amp - float(expected_amp)) > 0.001
    ):
        blockers.append("not_exact_6a_contract_phases")
    return {
        "active": not blockers,
        "blockers": blockers,
        "amp": amp,
        "phases": phases,
        "contract_phases": expected_phases,
        "cap_amp": cap_amp,
    }


def _suspend_min_current_import_integral_for_start_hold(
    runtime,
    box,
    status,
    *,
    current_amp,
    grid_power_w,
    hard_grid_import_w=wallbox_start_hold.DEFAULT_HARD_IMPORT_W,
    now_ts=None,
):
    """Gibt das gemeinsame 40-Wh-Konto an einen gebundenen StartHold ab."""

    now_value = time.time() if now_ts is None else float(now_ts)
    data = box if isinstance(box, dict) else {}
    blockers = []
    if float(grid_power_w or 0.0) >= max(0.0, float(hard_grid_import_w or 0.0)):
        blockers.append("hard_grid_import")
    member = _start_hold_member_materialization(
        data,
        status,
        minimum_amp=6,
        now_ts=now_value,
    )
    blockers.extend(member.get("blockers") or [])
    if abs(float(current_amp or 0.0) - 6.0) > 0.001:
        blockers.append("not_exact_6a_contract_phases")
    if data.get("_wb_stop_sent_active") is True:
        blockers.append("stop_sent_active")
    if isinstance(status, dict) and status.get("manager_stop_pending") is True:
        blockers.append("manager_stop_pending")
    materialized = _wallbox_materialized_start_hold_budget_contract(
        data,
        base_budget_w=(
            float(member.get("cap_amp", 0.0) or 0.0)
            * 230.0
            * max(0, int(member.get("contract_phases", 0) or 0))
        ),
        allocated_amp=member.get("cap_amp", 0.0),
        allocated_phases=member.get("phases", 0),
        minimum_amp=6,
        now_ts=now_value,
    )
    if materialized.get("active") is not True:
        blockers.append(str(materialized.get("reason") or "grant_not_materialized"))
    blockers = list(dict.fromkeys(blockers))
    active = not blockers
    if active:
        reset = getattr(runtime, "reset_min_current_import_integral", None)
        if callable(reset):
            reset(0)
    return {
        "schema_version": "wallbox_start_hold_integral_owner_v1",
        "active": active,
        "wb_id": int(_cfg_float(data.get("id"), 0.0)),
        "protected_ids": [int(_cfg_float(data.get("id"), 0.0))] if active else [],
        "blockers": blockers,
        "grant": materialized,
    }


def _suspend_group_min_current_import_integral_for_start_hold(
    runtime,
    chargers,
    chargers_status,
    group_contract,
    *,
    grid_power_w,
    hard_grid_import_w=wallbox_start_hold.DEFAULT_HARD_IMPORT_W,
    now_ts=None,
):
    """Suspendiert das eine PCC-Integral für eine materialisierte Grant-Gruppe."""

    now_value = time.time() if now_ts is None else float(now_ts)
    group = group_contract if isinstance(group_contract, dict) else {}
    boxes = {
        int(_cfg_float(item.get("id"), 0.0)): item
        for item in (chargers or [])
        if isinstance(item, dict) and int(_cfg_float(item.get("id"), 0.0)) > 0
    }
    statuses = {
        int(_cfg_float(item.get("id"), 0.0)): item.get("status")
        for item in (chargers_status or [])
        if isinstance(item, dict) and int(_cfg_float(item.get("id"), 0.0)) > 0
    }
    candidate_ids = sorted({
        int(_cfg_float(item, 0.0))
        for item in (group.get("candidate_ids") or [])
        if int(_cfg_float(item, 0.0)) > 0
    })
    legacy_owner_id = int(
        _cfg_float(group.get("effective_owner_id"), 0.0)
    )
    blockers = []
    if group.get("binding_ready") is not True or legacy_owner_id <= 0:
        blockers.append("group_owner_not_bound")
    if float(grid_power_w or 0.0) >= max(0.0, float(hard_grid_import_w or 0.0)):
        blockers.append("hard_grid_import")

    candidates = []
    for wb_id, box in boxes.items():
        bound = wallbox_start_hold.committed_grant_budget(
            box,
            base_budget_w=0,
            now_ts=now_value,
        )
        if bound.get("bound") is not True:
            continue
        grant = box.get(wallbox_start_hold.GRANT_KEY)
        members = grant.get("group_members") if isinstance(grant, dict) else []
        member_ids = sorted({
            int(_cfg_float(member.get("wb_id"), 0.0))
            for member in (members if isinstance(members, list) else [])
            if isinstance(member, dict)
            and int(_cfg_float(member.get("wb_id"), 0.0)) > 0
        })
        if not member_ids or legacy_owner_id not in member_ids:
            continue
        candidates.append({
            "wb_id": wb_id,
            "grant": grant,
            "member_ids": member_ids,
            "episode_id": str(grant.get("episode_id") or ""),
            "expires_ts": _cfg_float(grant.get("expires_ts"), 0.0),
        })
    selected = max(
        candidates,
        key=lambda item: (
            len(item.get("member_ids") or []),
            float(item.get("expires_ts", 0.0) or 0.0),
            int(item.get("wb_id", 0) or 0),
        ),
        default=None,
    )
    protected_ids = []
    if isinstance(selected, dict):
        grant_owner_box = boxes.get(
            int((selected or {}).get("wb_id", 0) or 0)
        )
        for member in selected["grant"].get("group_members", []):
            member_id = int(_cfg_float(member.get("wb_id"), 0.0))
            box = boxes.get(member_id)
            status = statuses.get(member_id)
            evidence = _start_hold_member_materialization(
                box,
                status,
                minimum_amp=int(_cfg_float(member.get("minimum_amp"), 6.0)),
                grant_owner_box=grant_owner_box,
                now_ts=now_value,
            )
            session_id = str(
                (box or {}).get(wallbox_start_hold.SESSION_KEY)
                or (box or {}).get("_openwb_pro_plug_session_id")
                or ""
            )
            if (
                evidence.get("active") is True
                and session_id == str(member.get("plug_session_id") or "")
            ):
                protected_ids.append(member_id)
    else:
        blockers.append("no_committed_matching_group_grant")

    selected_member_ids = set((selected or {}).get("member_ids") or [])
    if isinstance(selected, dict) and set(protected_ids) != selected_member_ids:
        blockers.append("grant_group_not_fully_materialized")
    runtime_materialization_present = any(
        "_wallbox_start_hold_allocation_contract" in box
        for box in boxes.values()
    )
    runtime_materialization = (
        boxes.get(int((selected or {}).get("wb_id", 0) or 0), {}).get(
            "_wallbox_start_hold_allocation_contract"
        )
        if isinstance(selected, dict)
        else None
    )
    if runtime_materialization_present and not (
        isinstance(runtime_materialization, dict)
        and runtime_materialization.get("active") is True
        and int(
            runtime_materialization.get("selected_wb_id", 0) or 0
        ) == int((selected or {}).get("wb_id", 0) or 0)
        and set(protected_ids) == selected_member_ids
        and set(runtime_materialization.get("protected_ids") or [])
        == selected_member_ids
    ):
        blockers.append("central_allocation_not_materialized")
    if legacy_owner_id not in protected_ids:
        blockers.append("legacy_owner_not_protected")
    if any(
        boxes.get(wb_id, {}).get("_wb_stop_sent_active") is True
        for wb_id in protected_ids
    ):
        blockers.append("group_stop_sent_active")
    if any(
        isinstance(statuses.get(wb_id), dict)
        and statuses[wb_id].get("manager_stop_pending") is True
        for wb_id in protected_ids
    ):
        blockers.append("group_manager_stop_pending")
    blockers = list(dict.fromkeys(blockers))
    active = not blockers
    if active:
        reset = getattr(runtime, "reset_min_current_import_integral", None)
        if callable(reset):
            reset(0)
    return {
        "schema_version": "wallbox_start_hold_group_integral_owner_v1",
        "active": active,
        "legacy_owner_id": legacy_owner_id,
        "selected_wb_id": int((selected or {}).get("wb_id", 0) or 0),
        "episode_id": str((selected or {}).get("episode_id") or ""),
        "protected_ids": sorted(set(protected_ids)),
        "unprotected_candidates": sorted(
            set(candidate_ids).difference(protected_ids)
        ),
        "blockers": blockers,
    }


def _validated_native_wallbox_floor_soc(live):
    """Liefert eine frische geprüfte native Untergrenze oder ``None`` und erfindet nie Null."""
    live_data = live if isinstance(live, dict) else {}
    if live_data.get("e3dc_wb_discharge_bat_until_soc_valid") is not True:
        return None
    value = live_data.get("e3dc_wb_discharge_bat_until_soc")
    if isinstance(value, bool) or not isinstance(value, int) or not 0 <= value <= 100:
        return None
    return float(value)


def _effective_wallbox_floor_soc(config, live, wb_minsoc, *extra_floors):
    """Liefert eine monotone Wallbox-Entladeuntergrenze mit harten Reservegrenzen."""
    live_data = live if isinstance(live, dict) else {}
    cfg = config if isinstance(config, dict) else {}

    def _num(value, default=0.0):
        try:
            text = str(value).strip().replace(",", ".") if value is not None else ""
            return float(text) if text else float(default)
        except Exception:
            return float(default)

    def _pct(value):
        return max(0.0, min(100.0, _num(value, 0.0)))

    floor = _pct(wb_minsoc)
    for key in ("emergency_power_reserve", "ep_reserve_pct", "notstrom_reserve"):
        if cfg.get(key) not in (None, ""):
            floor = max(floor, _pct(cfg.get(key)))
    e3dc_wb_floor = _validated_native_wallbox_floor_soc(live_data)
    if e3dc_wb_floor is not None:
        floor = max(floor, e3dc_wb_floor)
    for extra in extra_floors:
        floor = max(floor, _pct(extra))
    return floor

def _load_wallbox_abort_state():
    try:
        if not os.path.lexists(WB_ABORT_STATE_FILE):
            return {}
        meta = os.lstat(WB_ABORT_STATE_FILE)
        if stat.S_ISLNK(meta.st_mode) or not stat.S_ISREG(meta.st_mode):
            return {"__load_error__": "abort_state_not_regular_file"}
        with open(WB_ABORT_STATE_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
        if not isinstance(data, dict):
            return {"__load_error__": "abort_state_not_mapping"}
        schema = data.get("schema")
        if schema not in (None, "wallbox_abort_state_v2"):
            return {"__load_error__": "abort_state_schema_invalid"}
        return data
    except Exception as exc:
        return {
            "__load_error__":
            "abort_state_read_failed:%s" % exc.__class__.__name__
        }

def _save_wallbox_abort_state(chargers, *, preserve_existing=False):
    try:
        now = time.time()
        existing = _load_wallbox_abort_state() if preserve_existing else {}
        data = {"schema": "wallbox_abort_state_v2"}
        if isinstance(existing, dict):
            data.update({
                str(key): dict(value)
                for key, value in existing.items()
                if isinstance(value, dict) and not str(key).startswith("__")
            })
        for c_data in chargers or []:
            c_id = str(c_data.get("id", ""))
            if not c_id:
                continue
            count = int(c_data.get("abort_count", 0) or 0)
            cooldown_ts = float(c_data.get("abort_cooldown_ts", 0.0) or 0.0)
            full_blocked = bool(c_data.get("_bev_full_blocked", False))
            full_block_reason = str(c_data.get("_bev_full_block_reason") or "")
            soft_until = float(c_data.get("_openwb_start_reject_soft_until", 0.0) or 0.0)
            plug_session_id = str(
                (
                    c_data.get("_charge_end_latched_plug_session_id")
                    if full_blocked
                    else c_data.get("_openwb_pro_plug_session_id")
                )
                or ""
            )
            charge_end_latched_ts = float(
                c_data.get("_charge_end_latched_ts", 0.0) or 0.0
            )
            charge_end_release_token = str(
                c_data.get("_charge_end_release_token") or ""
            )
            native_stop_contract = c_data.get(
                "_native_charge_end_stop_contract"
            )
            native_stop_contract = (
                dict(native_stop_contract)
                if full_blocked
                and isinstance(native_stop_contract, dict)
                and native_stop_contract.get("contract")
                == "wallbox_native_stop_edge_wal_v1"
                else {}
            )
            floor_replug_present = (
                "_native_e3dc_floor_replug_evidence" in c_data
            )
            floor_replug_evidence = (
                _validated_native_e3dc_floor_replug_evidence(
                    c_data.get("_native_e3dc_floor_replug_evidence"),
                    current_episode_id=c_data.get(
                        "_wallbox_plug_episode_id"
                    ),
                )
                if floor_replug_present
                else {}
            )
            if floor_replug_present and not floor_replug_evidence:
                return False
            if floor_replug_evidence:
                current_floor_anchor = c_data.get(
                    "_manager_zero_anchor_contract"
                )
                if not (
                    c_data.get("_manager_zero_anchor_active") is True
                    and isinstance(current_floor_anchor, dict)
                    and current_floor_anchor
                    == floor_replug_evidence.get("anchor_contract")
                ):
                    return False
            if (
                count > 0
                or cooldown_ts > now
                or full_blocked
                or soft_until > now
                or bool(floor_replug_evidence)
            ):
                data[c_id] = {
                    "abort_count": count,
                    "abort_cooldown_ts": cooldown_ts,
                    "bev_full_blocked": full_blocked,
                    "bev_full_block_reason": full_block_reason,
                    "openwb_start_reject_soft_until": soft_until,
                    "plug_session_id": plug_session_id,
                    "_charge_end_latched_ts": charge_end_latched_ts,
                    "charge_end_release_token": charge_end_release_token,
                    **(
                        {"native_stop_contract": native_stop_contract}
                        if native_stop_contract
                        else {}
                    ),
                    **(
                        {
                            "native_e3dc_floor_replug_evidence": (
                                floor_replug_evidence
                            )
                        }
                        if floor_replug_evidence
                        else {}
                    ),
                }
            else:
                data.pop(c_id, None)
        directory = os.path.dirname(WB_ABORT_STATE_FILE)
        os.makedirs(directory, mode=0o775, exist_ok=True)
        if os.path.islink(directory):
            return False
        tmp = WB_ABORT_STATE_FILE + ".tmp.%d" % os.getpid()
        with open(tmp, "w", encoding="utf-8") as f:
            f.write(
                json.dumps(
                    data,
                    ensure_ascii=False,
                    sort_keys=True,
                    separators=(",", ":"),
                )
                + "\n"
            )
            f.flush()
            os.fsync(f.fileno())
        os.chmod(tmp, 0o664)
        os.replace(tmp, WB_ABORT_STATE_FILE)
        dir_fd = os.open(directory, os.O_RDONLY)
        try:
            os.fsync(dir_fd)
        finally:
            os.close(dir_fd)
        return True
    except Exception as exc:
        logger.error(
            "Wallbox-Abbruchstatus konnte nicht crashfest gespeichert werden: %s",
            exc,
        )
        try:
            if os.path.exists(locals().get("tmp", "")):
                os.unlink(tmp)
        except Exception:
            pass
        return False

def _restored_abort_fields(abort_state, charger_id):
    def _recovery(reason):
        return {
            "abort_count": 0,
            "abort_cooldown_ts": 0.0,
            "_bev_full_blocked": True,
            "_bev_full_block_reason": "abort_state_recovery_hold",
            "_openwb_start_reject_soft_until": 0.0,
            "_charge_end_latched_ts": 0.0,
            "_charge_end_restore_error": str(reason or "abort_state_entry_invalid"),
        }

    try:
        if (
            isinstance(abort_state, dict)
            and abort_state.get("__load_error__")
        ):
            return _recovery(abort_state.get("__load_error__"))
        if not isinstance(abort_state, dict):
            return _recovery("abort_state_not_mapping")
        entry_key = str(charger_id)
        if entry_key not in abort_state:
            return {}
        raw = abort_state.get(entry_key)
        if not isinstance(raw, dict):
            return _recovery("abort_state_entry_not_mapping")
        cooldown_ts = float(raw.get("abort_cooldown_ts", 0.0) or 0.0)
        count = int(raw.get("abort_count", 0) or 0)
        full_blocked = bool(raw.get("bev_full_blocked", False))
        full_block_reason = str(raw.get("bev_full_block_reason") or "")
        if full_blocked and not full_block_reason:
            return _recovery("abort_state_block_reason_missing")
        soft_until = float(raw.get("openwb_start_reject_soft_until", 0.0) or 0.0)
        plug_session_id_present = "plug_session_id" in raw
        plug_session_id = str(raw.get("plug_session_id") or "")
        charge_end_latched_ts = float(
            raw.get(
                "_charge_end_latched_ts",
                raw.get("charge_end_latched_ts", 0.0),
            )
            or 0.0
        )
        charge_end_release_token_present = "charge_end_release_token" in raw
        charge_end_release_token = str(raw.get("charge_end_release_token") or "")
        floor_replug_present = (
            "native_e3dc_floor_replug_evidence" in raw
        )
        floor_replug_evidence = raw.get(
            "native_e3dc_floor_replug_evidence"
        )
        if floor_replug_present:
            candidate_episode_id = str(
                (
                    floor_replug_evidence
                    if isinstance(floor_replug_evidence, dict)
                    else {}
                ).get("new_episode_id")
                or ""
            )
            floor_replug_evidence = (
                _validated_native_e3dc_floor_replug_evidence(
                    floor_replug_evidence,
                    current_episode_id=candidate_episode_id,
                )
            )
            if not floor_replug_evidence:
                return _recovery(
                    "native_e3dc_floor_replug_evidence_invalid"
                )
        else:
            floor_replug_evidence = {}
        native_stop_contract_present = "native_stop_contract" in raw
        native_stop_contract = raw.get("native_stop_contract")
        if native_stop_contract_present:
            if not isinstance(native_stop_contract, dict):
                return _recovery("native_stop_contract_not_mapping")
            native_stop_contract = dict(native_stop_contract)
            native_state = str(native_stop_contract.get("state") or "")
            native_reason = str(native_stop_contract.get("reason") or "")
            native_sample_ts = float(
                native_stop_contract.get("sample_ts", 0.0) or 0.0
            )
            native_created_ts = float(
                native_stop_contract.get("created_ts", 0.0) or 0.0
            )
            native_wire_ts = float(
                native_stop_contract.get("wire_receipt_ts", 0.0) or 0.0
            )
            native_wire_seq = int(
                native_stop_contract.get("wire_receipt_seq", 0) or 0
            )
            native_plug_session_id = str(
                native_stop_contract.get("plug_session_id") or ""
            )
            native_release_token = str(
                native_stop_contract.get("release_token") or ""
            )
            native_state_valid = bool(
                (
                    native_state == "pending"
                    and native_wire_seq == 0
                    and native_wire_ts == 0.0
                )
                or (
                    native_state == "issued_unconfirmed"
                    and native_wire_seq > 0
                    and native_wire_ts > max(
                        native_sample_ts,
                        native_created_ts,
                    )
                )
            )
            if (
                native_stop_contract.get("contract")
                != "wallbox_native_stop_edge_wal_v1"
                or not full_blocked
                or native_state not in ("pending", "issued_unconfirmed")
                or not native_reason
                or (full_blocked and native_reason != full_block_reason)
                or not plug_session_id_present
                or not charge_end_release_token_present
                or not plug_session_id
                or not charge_end_release_token
                or native_plug_session_id != plug_session_id
                or native_release_token != charge_end_release_token
                or native_sample_ts <= 0.0
                or native_created_ts < native_sample_ts
                or not native_state_valid
                or not all(
                    math.isfinite(value) and value >= 0.0
                    for value in (
                        native_sample_ts,
                        native_created_ts,
                        native_wire_ts,
                    )
                )
            ):
                return _recovery("native_stop_contract_invalid")
        if not all(
            math.isfinite(value)
            for value in (
                cooldown_ts,
                soft_until,
                charge_end_latched_ts,
            )
        ):
            return _recovery("abort_state_entry_non_finite")
        if (
            cooldown_ts <= 0.0
            and count <= 0
            and not full_blocked
            and soft_until <= 0.0
            and not floor_replug_evidence
        ):
            return {}
        if (
            not full_blocked
            and not floor_replug_evidence
            and time.time() - max(cooldown_ts, soft_until) > 900.0
        ):
            return {}
        floor_anchor = (
            dict(floor_replug_evidence.get("anchor_contract") or {})
            if floor_replug_evidence
            else {}
        )
        return {
            "abort_count": max(0, count),
            "abort_cooldown_ts": max(0.0, cooldown_ts),
            "_bev_full_blocked": full_blocked,
            "_bev_full_block_reason": full_block_reason,
            "_openwb_start_reject_soft_until": max(0.0, soft_until),
            "_charge_end_latched_ts": max(0.0, charge_end_latched_ts),
            **(
                {"_charge_end_release_token": charge_end_release_token}
                if charge_end_release_token_present
                else {}
            ),
            **(
                {"_charge_end_latched_plug_session_id": plug_session_id}
                if plug_session_id_present
                else {}
            ),
            **(
                {"_native_charge_end_stop_contract": native_stop_contract}
                if native_stop_contract_present
                else {}
            ),
            **(
                {
                    "_native_e3dc_floor_replug_evidence": (
                        floor_replug_evidence
                    ),
                    "_wallbox_plug_episode_id": str(
                        floor_replug_evidence.get("new_episode_id") or ""
                    ),
                    "_manager_zero_anchor_active": True,
                    "_manager_zero_anchor_contract": floor_anchor,
                    "_session_vehicle_key": str(
                        floor_anchor.get("session_vehicle_key") or ""
                    ),
                    "_last_manager_zero_anchor_reason": str(
                        floor_anchor.get("reason_code") or ""
                    ),
                    "_last_manager_zero_anchor_ts": float(
                        floor_anchor.get("created_ts", 0.0) or 0.0
                    ),
                }
                if floor_replug_evidence
                else {}
            ),
        }
    except Exception as exc:
        return _recovery(
            "abort_state_entry_parse_failed:%s" % exc.__class__.__name__
        )


def _reconcile_persisted_wallbox_terminal_latch(
    c_data,
    abort_state,
    *,
    now_ts=None,
):
    """Rehydriert einen persistierten Same-Session-Latch vor der Policy.

    Der Abort-State ist die crashfeste Autorität für ein terminales Ladeende.
    Ein Runtime-Rebuild darf diesen Zustand nicht verlieren. Eine abweichende
    bestätigte Stecksession wird hier ausdrücklich nicht freigegeben; deren
    bestehender Replug-/Nutzervertrag besitzt die Freigabe. Bei unklarer
    Persistenz bleibt die Runtime fail-closed, ohne einen Phasenvertrag zu
    löschen.
    """

    data = c_data if isinstance(c_data, dict) else {}
    now_value = time.time() if now_ts is None else float(now_ts)
    result = {
        "contract": "wallbox_persisted_terminal_latch_reconcile_v1",
        "reconciled": False,
        "same_session": False,
        "fail_closed": False,
        "phase_supersession": {},
        "blocker": "",
        "ts": now_value,
    }
    charger_id = int(data.get("id", 0) or 0)
    if charger_id <= 0:
        result["blocker"] = "charger_id_missing"
        return result

    restored = _restored_abort_fields(abort_state, charger_id)
    result["persisted_entry_present"] = bool(restored)
    if not restored:
        result["blocker"] = "persisted_entry_missing"
        return result
    if restored.get("_bev_full_blocked") is not True:
        result["blocker"] = "persisted_terminal_latch_inactive"
        return result

    reason = str(restored.get("_bev_full_block_reason") or "")
    persisted_session_id = str(
        restored.get("_charge_end_latched_plug_session_id") or ""
    )
    result["reason"] = reason
    result["persisted_session_id"] = persisted_session_id
    terminal_reason = reason in _CHARGE_END_TERMINAL_REASONS
    recovery_reason = reason == "abort_state_recovery_hold"

    charger = data.get("charger")
    openwb_pro = bool(
        openwb_pro_session.is_openwb_pro_charger(charger)
        or str(data.get("_openwb_pro_plug_session_id") or "")
    )
    runtime_session_key = (
        "_openwb_pro_plug_session_id"
        if openwb_pro
        else "_wallbox_plug_episode_id"
    )
    runtime_session_id = str(data.get(runtime_session_key) or "")
    result["runtime_session_id"] = runtime_session_id

    if recovery_reason or not terminal_reason:
        # Beschädigte oder unbekannte persistierte Latches dürfen niemals
        # still in eine Startfreigabe umgedeutet werden. Der aktive
        # Phasenvertrag bleibt dabei unangetastet, weil seine Output-Evidenz
        # nicht sicher klassifiziert werden kann.
        data["_bev_full_blocked"] = True
        data["_bev_full_block_reason"] = (
            reason or "abort_state_recovery_hold"
        )
        data["_charge_end_restore_error"] = str(
            restored.get("_charge_end_restore_error")
            or "persisted_terminal_latch_unclassified"
        )
        result.update({
            "reconciled": True,
            "fail_closed": True,
            "blocker": "persisted_latch_recovery_hold",
        })
        return result

    if not persisted_session_id:
        data["_bev_full_blocked"] = True
        data["_bev_full_block_reason"] = "abort_state_recovery_hold"
        data["_charge_end_restore_error"] = (
            "persisted_terminal_session_missing"
        )
        result.update({
            "reconciled": True,
            "fail_closed": True,
            "blocker": "persisted_terminal_session_missing",
        })
        return result

    if runtime_session_id and runtime_session_id != persisted_session_id:
        result["blocker"] = "different_runtime_session"
        return result

    if not runtime_session_id:
        # Ohne bestätigten Replug gilt die persistierte physische Session
        # weiter. So erzeugt ein verlorener Phase-State keine künstliche neue
        # Stecksession und damit keine Startfreigabe.
        data[runtime_session_key] = persisted_session_id
        runtime_session_id = persisted_session_id
        result["runtime_session_seeded"] = True

    result["same_session"] = runtime_session_id == persisted_session_id
    if not result["same_session"]:
        result["blocker"] = "same_session_not_proven"
        return result

    data["abort_count"] = max(
        int(data.get("abort_count", 0) or 0),
        int(restored.get("abort_count", 0) or 0),
    )
    data["abort_cooldown_ts"] = max(
        _cfg_float(data.get("abort_cooldown_ts"), 0.0),
        _cfg_float(restored.get("abort_cooldown_ts"), 0.0),
    )
    data["_bev_full_blocked"] = True
    data["_bev_full_block_reason"] = reason
    data["_charge_end_latched_plug_session_id"] = persisted_session_id
    data["_charge_end_latched_ts"] = max(
        _cfg_float(data.get("_charge_end_latched_ts"), 0.0),
        _cfg_float(restored.get("_charge_end_latched_ts"), 0.0),
    )
    data["_openwb_start_reject_soft_until"] = 0.0
    if restored.get("_charge_end_release_token"):
        data["_charge_end_release_token"] = str(
            restored.get("_charge_end_release_token")
        )

    legacy_preoutput_bridge = (
        _persist_openwb_pro_legacy_preoutput_evidence_bridge(
            data,
            now_ts=now_value,
        )
    )
    if (
        legacy_preoutput_bridge.get("matched") is True
        and legacy_preoutput_bridge.get("persisted") is not True
    ):
        phase_supersession = {
            "contract": "openwb_pro_preoutput_phase_supersession_v1",
            "matched": False,
            "superseded": False,
            "persisted": False,
            "terminal_latch": True,
            "blocker": "legacy_preoutput_proof_not_persisted",
        }
    else:
        phase_supersession = (
            _supersede_openwb_pro_preoutput_phase_reservation(
                data,
                0,
                now_ts=now_value,
                terminal_latch=True,
            )
        )
    result.update({
        "reconciled": True,
        "legacy_preoutput_bridge": dict(legacy_preoutput_bridge),
        "phase_supersession": dict(phase_supersession),
        "blocker": "",
    })
    data["_persisted_terminal_latch_reconcile"] = dict(result)
    return result


def _persist_wallbox_charge_end_before_stop(
    chargers,
    c_data,
    *,
    c_id,
    reason,
    stop_sender=None,
    status=None,
    now_ts=None,
):
    """Versiegelt das Ladeende vor dem ersten Stop-Ausgang.

    Ein erfolgreicher Stop ohne crashfesten Ladeende-Latch würde nach einem
    Manager-Neustart dieselbe physische Stecksession erneut freigeben. Darum
    darf der Geräteausgang erst nach bestätigter Persistenz versucht werden.
    """

    data = c_data if isinstance(c_data, dict) else {}
    result = {
        "persisted": False,
        "stop_attempted": False,
        "stop_handled": False,
        "reason": str(reason or "vehicle_charge_ended"),
    }
    if (
        data.get("_bev_full_blocked") is not True
        or str(data.get("_bev_full_block_reason") or "")
        not in (
            "vehicle_charge_ended",
            "start_rejected",
            "target_soc_reached",
            "target_kwh_reached",
            "battery_departure_target_reached",
        )
    ):
        data["_charge_end_persist_failed"] = "latch_not_active"
        return result
    if not _ensure_wallbox_latch_persisted(chargers, data, result["reason"]):
        return result
    result["persisted"] = True
    enforced = _enforce_wallbox_latched_stop(
        chargers,
        data,
        status,
        c_id=c_id,
        reason=result["reason"],
        stop_sender=stop_sender,
        now_ts=now_ts,
    )
    result.update(enforced)
    return result


def _wallbox_start_rejected_hold_supported(c_data):
    """Begrenzt den persistenten Start-Reject-Hold auf Manager-Aktoren."""

    data = c_data if isinstance(c_data, dict) else {}
    charger = data.get("charger")
    if charger is None or bool(getattr(charger, "primary_mode_enabled", False)):
        return False
    return bool(
        openwb_pro_session.is_openwb_pro_charger(charger)
        or e3dc_session.is_e3dc_native_charger(charger)
        or hasattr(charger, "set_amp_and_state")
        or hasattr(charger, "set_direct_current")
    )


def _wallbox_start_rejected_session_id(c_data):
    """Liefert ausschließlich die bereits beobachtete physische Steckepisode."""

    data = c_data if isinstance(c_data, dict) else {}
    if openwb_pro_session.is_openwb_pro_charger(data.get("charger")):
        return str(data.get("_openwb_pro_plug_session_id") or "")
    return str(data.get("_wallbox_plug_episode_id") or "")


def _latch_wallbox_start_rejected_hold(
    chargers,
    c_data,
    status,
    *,
    c_id,
    config,
    public_mode,
    now_ts=None,
    stop_sender=None,
):
    """Beendet genau eine erfolglose Start-Episode crashfest.

    Ein positives Budget beweist nicht, dass das Fahrzeug eine weitere
    Startfolge benötigt. Wenn die vollständig abgewartete
    Start-Episode keine reale Leistung erzeugt, wird deshalb ein eigener
    ``start_rejected``-Zustand an die aktuelle Stecksession gebunden. Er ist
    ausdrücklich kein Fahrzeug-Ladeende und wird nur durch eine bestätigte
    neue Stecksession oder eine bewusste Nutzer-/Profilfreigabe gelöst.
    """

    data = c_data if isinstance(c_data, dict) else {}
    now_value = float(now_ts if now_ts is not None else time.time())
    result = {
        "contract": "wallbox_start_rejected_hold_v1",
        "latched": False,
        "persisted": False,
        "stop_attempted": False,
        "stop_handled": False,
        "reason": "start_rejected",
        "blocker": "",
    }
    if not _wallbox_start_rejected_hold_supported(data):
        result["blocker"] = "start_rejected_hold_not_supported"
        return result
    st = status if isinstance(status, dict) else {}
    if not (
        st.get("driver_status_valid") is True
        and not bool(st.get("driver_status_stale", False))
        and not bool(st.get("driver_status_glitch", False))
        and _wb_status_connected(st)
    ):
        result["blocker"] = "connected_fresh_status_missing"
        return result
    plug_session_id = _wallbox_start_rejected_session_id(data)
    if not plug_session_id:
        result["blocker"] = "plug_session_id_missing"
        return result
    release_token = _wallbox_charge_end_release_token(
        config,
        c_id,
        public_mode,
    )
    if not release_token:
        result["blocker"] = "release_token_missing"
        return result

    data["abort_count"] = max(
        1,
        int(data.get("abort_count", 0) or 0) + 1,
    )
    data["abort_cooldown_ts"] = now_value
    data["_bev_full_blocked"] = True
    data["_bev_full_block_reason"] = "start_rejected"
    data["_charge_end_latched_ts"] = now_value
    data["_charge_end_latched_plug_session_id"] = plug_session_id
    data["_charge_end_release_token"] = release_token
    data["_openwb_start_reject_soft_until"] = 0.0
    data["_openwb_start_reject_anchor_ts"] = 0.0
    data["_openwb_start_retry_count"] = 0
    data["_openwb_cp_start_sent"] = False
    data["_openwb_pro_start_hold_until"] = 0.0
    data["_openwb_pro_start_hold_amp"] = 0
    result["latched"] = True

    enforced = _persist_wallbox_charge_end_before_stop(
        chargers,
        data,
        c_id=c_id,
        reason="start_rejected",
        stop_sender=stop_sender,
        status=status,
        now_ts=now_value,
    )
    result.update(enforced)
    if openwb_pro_session.is_openwb_pro_charger(data.get("charger")):
        # Der persistente Latch ist ab hier die autoritative Wahrheit. Der
        # aufrufende Managerzweig beendet den Zyklus unmittelbar mit
        # ``continue``; ohne diese gleichzyklische Neuprojektion bliebe in der
        # Web-/Statusfläche fälschlich der zuvor berechnete Zustand
        # ``starting`` sichtbar.
        data["current_set_amp"] = 0
        data["cap_amp"] = 0
        data["is_charging"] = False
        _evaluate_openwb_pro_session_for_manager(
            data,
            st,
            cap_amp=0,
            budget_ready=False,
            mode_off=int(public_mode or 0) <= 0,
            now_ts=now_value,
            stable_hw_power_w=_wb_status_real_power(st),
        )
    if not result.get("persisted", False):
        result["blocker"] = str(
            data.get("_charge_end_persist_failed")
            or "abort_state_write_failed"
        )
    return result


def _load_wallbox_phase_state():
    path = WB_PHASE_STATE_FILE
    try:
        if not os.path.lexists(path):
            return {}
        meta = os.lstat(path)
        if stat.S_ISLNK(meta.st_mode) or not stat.S_ISREG(meta.st_mode):
            return {"__load_error__": "phase_state_not_regular_file"}
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
        if not isinstance(data, dict) or data.get("schema") != "wallbox_phase_state_v3":
            return {"__load_error__": "phase_state_schema_invalid"}
        return data
    except Exception as exc:
        return {"__load_error__": "phase_state_read_failed:%s" % exc.__class__.__name__}


def _wallbox_phase_boot_id():
    try:
        with open("/proc/sys/kernel/random/boot_id", "r", encoding="ascii") as handle:
            value = handle.read().strip()
        return value or "unknown"
    except Exception:
        return "unknown"


def _phase_state_entry(c_data, now):
    entry = {
        "phase_3p_block_until": float(c_data.get("_phase_3p_block_until", 0.0) or 0.0),
        "openwb_pro_phase_retry_block_until": float(
            c_data.get("_openwb_pro_phase_retry_block_until", 0.0) or 0.0
        ),
        "openwb_pro_phase_change_block_until": float(
            c_data.get("_openwb_pro_phase_change_block_until", 0.0) or 0.0
        ),
        "openwb_pro_phase_wait_until": float(c_data.get("_openwb_pro_phase_wait_until", 0.0) or 0.0),
        "openwb_pro_phase_wait_target": int(c_data.get("_openwb_pro_phase_wait_target", 0) or 0),
        "openwb_pro_phase_wait_amp": float(c_data.get("_openwb_pro_phase_wait_amp", 0.0) or 0.0),
        "openwb_pro_plug_session_id": str(
            c_data.get("_openwb_pro_plug_session_id") or ""
        ),
        "openwb_pro_start_current_issued_ts": float(
            c_data.get("_openwb_pro_start_current_issued_ts", 0.0) or 0.0
        ),
        "openwb_pro_start_current_session_id": str(
            c_data.get("_openwb_pro_start_current_session_id") or ""
        ),
        "openwb_pro_start_wakeup_count": int(
            c_data.get("_openwb_pro_start_wakeup_count", 0) or 0
        ),
        "openwb_pro_start_wakeup_allowed_after": float(
            c_data.get("_openwb_pro_start_wakeup_allowed_after", 0.0) or 0.0
        ),
        "openwb_pro_start_wakeup_pending": bool(
            c_data.get("_openwb_pro_start_wakeup_pending", False)
        ),
        "openwb_pro_start_phase_target": int(
            c_data.get("_openwb_pro_start_phase_target", 0) or 0
        ),
        "openwb_pro_unserved_since": float(
            c_data.get("_openwb_pro_unserved_since", 0.0) or 0.0
        ),
        "openwb_pro_unserved_pause_since": float(
            c_data.get("_openwb_pro_unserved_pause_since", 0.0) or 0.0
        ),
        "openwb_pro_unserved_paused_s": float(
            c_data.get("_openwb_pro_unserved_paused_s", 0.0) or 0.0
        ),
    }
    for source_key, target_key in (
        ("_wallbox_phase_transition_reservation", "phase_transition_reservation"),
        ("_openwb_pro_phase_sequence", "openwb_pro_phase_sequence"),
        ("_openwb_pro_phase_output_intent", "openwb_pro_phase_output_intent"),
        ("_openwb_pro_phase_output_ack", "openwb_pro_phase_output_ack"),
        ("_openwb_pro_phase_recovery_hold", "openwb_pro_phase_recovery_hold"),
        (
            "_openwb_pro_phase_stranded_zero_recovery",
            "openwb_pro_phase_stranded_zero_recovery",
        ),
        ("_openwb_pro_phase_restart_authorized", "openwb_pro_phase_restart_authorized"),
        ("_openwb_pro_start_wakeup_receipt", "openwb_pro_start_wakeup_receipt"),
        ("_mode5_user_start_request_receipt", "mode5_user_start_request_receipt"),
        (
            "_openwb_pro_session_persistence_recovery_hold",
            "openwb_pro_session_persistence_recovery_hold",
        ),
    ):
        value = c_data.get(source_key)
        if isinstance(value, dict) and value:
            entry[target_key] = value
    active = bool(
        entry["phase_3p_block_until"] > now
        or entry["openwb_pro_phase_retry_block_until"] > now
        or entry["openwb_pro_phase_change_block_until"] > now
        or entry["openwb_pro_phase_wait_until"] > now
        or bool(entry["openwb_pro_plug_session_id"])
        or entry["openwb_pro_start_current_issued_ts"] > 0.0
        or entry["openwb_pro_start_wakeup_count"] > 0
        or entry["openwb_pro_start_wakeup_pending"]
        or "openwb_pro_start_wakeup_receipt" in entry
        or "mode5_user_start_request_receipt" in entry
        or "openwb_pro_session_persistence_recovery_hold" in entry
        or any(key in entry for key in (
            "phase_transition_reservation",
            "openwb_pro_phase_sequence",
            "openwb_pro_phase_output_intent",
            "openwb_pro_phase_recovery_hold",
            "openwb_pro_phase_restart_authorized",
        ))
    )
    return entry if active else {}


def _phase_entry_is_terminal_restart_only(raw):
    """Erkennt ausschließlich vollständig terminalisierte Phasengenerationen.

    Eine bestätigte ``send_phase``-Kante darf nach einem reinen
    Managerneustart nicht erneut als unklarer Hardwareausgang behandelt
    werden. Der Beleg muss dafür Reservierung, Intent, ACK, Wire-Receipt,
    Zielphase und Wiederanlauffreigabe eindeutig an dieselbe Generation
    binden. Ein älterer, rein diagnostischer Recovery-Umschlag ist nur mit
    seinen exakt bekannten Prozessneustart-Markern zulässig.
    """

    item = raw if isinstance(raw, dict) else {}
    reservation = item.get("phase_transition_reservation")
    reservation = reservation if isinstance(reservation, dict) else {}
    sequence = item.get("openwb_pro_phase_sequence")
    sequence = sequence if isinstance(sequence, dict) else {}
    intent = item.get("openwb_pro_phase_output_intent")
    intent = intent if isinstance(intent, dict) else {}
    ack = item.get("openwb_pro_phase_output_ack")
    ack = ack if isinstance(ack, dict) else {}
    recovery = item.get("openwb_pro_phase_recovery_hold")
    recovery = recovery if isinstance(recovery, dict) else {}
    restart = item.get("openwb_pro_phase_restart_authorized")
    restart = restart if isinstance(restart, dict) else {}

    if sequence or restart.get("active") is not True:
        return False
    restart_target = _valid_phase_count(restart.get("target"), 0)
    if restart_target not in (1, 3):
        return False

    restart_source = str(restart.get("source") or "")
    if restart_source == "expired_sequence_fresh_idle_target_confirmed":
        return bool(
            not intent
            and not ack
            and reservation.get("active") is True
            and str(reservation.get("stage") or "") == "recovery_hold"
            and str(reservation.get("grant_state") or "") == "waiting"
            and int(_cfg_float(reservation.get("requested_w"), 0.0)) == 0
            and int(_cfg_float(reservation.get("granted_w"), 0.0)) == 0
            and int(_cfg_float(reservation.get("committed_w"), 0.0)) == 0
            and _cfg_float(reservation.get("committed_ts"), 0.0) <= 0.0
            and int(_cfg_float(reservation.get("valid_frames"), 0.0)) == 0
            and _valid_phase_count(reservation.get("target_phases"), 0) == 0
            and recovery.get("active") is True
            and str(recovery.get("reason") or "")
            == "process_restart_recovery_hold"
            and str(recovery.get("recovery_class") or "")
            == "output_ambiguous"
            and _valid_phase_count(recovery.get("target"), 0) == 0
        )

    if restart_source != "phase_target_settle_readback_confirmed":
        return False
    reservation_id = str(
        reservation.get("transition_id")
        or reservation.get("reservation_id")
        or ""
    )
    requested_w = int(_cfg_float(reservation.get("requested_w"), 0.0))
    committed_ts = _cfg_float(reservation.get("committed_ts"), 0.0)
    reservation_stage = str(reservation.get("stage") or "")
    intent_id = str(intent.get("intent_id") or "")
    intent_transition_id = str(intent.get("transition_id") or "")
    intent_wall_ts = _cfg_float(intent.get("wall_ts"), 0.0)
    intent_wire_ts = _cfg_float(intent.get("wire_receipt_ts"), 0.0)
    ack_wire_ts = _cfg_float(ack.get("wire_receipt_ts"), 0.0)
    ack_wall_ts = _cfg_float(ack.get("wall_ts"), 0.0)
    restart_wire_ts = _cfg_float(restart.get("phase_sent_ts"), 0.0)
    authorized_ts = _cfg_float(restart.get("authorized_ts"), 0.0)
    timestamps = (
        committed_ts,
        intent_wall_ts,
        intent_wire_ts,
        ack_wire_ts,
        ack_wall_ts,
        restart_wire_ts,
        authorized_ts,
    )
    recovery_valid = bool(
        not recovery
        and reservation_stage == "confirm_target"
    ) or bool(
        recovery.get("active") is True
        and reservation_stage == "recovery_hold"
        and str(recovery.get("reason") or "")
        == "process_restart_recovery_hold"
        and str(recovery.get("recovery_class") or "")
        == "output_ambiguous"
        and _valid_phase_count(recovery.get("target"), 0)
        in (0, restart_target)
        and all(
            str(reservation.get(key) or "")
            == "process_restart_recovery_hold"
            for key in ("blocker", "reason", "reason_code")
        )
    )
    return bool(
        reservation.get("schema_version")
        == "wallbox_phase_transition_v2"
        and reservation.get("active") is True
        and reservation_id
        and str(reservation.get("reservation_id") or "") == reservation_id
        and str(reservation.get("transition_id") or "") == reservation_id
        and str(reservation.get("grant_state") or "") == "committed"
        and _valid_phase_count(reservation.get("target_phases"), 0)
        == restart_target
        and requested_w > 0
        and int(_cfg_float(reservation.get("granted_w"), 0.0)) >= requested_w
        and int(_cfg_float(reservation.get("committed_w"), 0.0)) >= requested_w
        and intent.get("schema") == "openwb_pro_phase_output_intent_v1"
        and intent_id.startswith(reservation_id + ":send_phase:")
        and (not intent_transition_id or intent_transition_id == reservation_id)
        and str(intent.get("action") or "") == "send_phase"
        and str(intent.get("method") or "") == "set_phases"
        and _valid_phase_count(intent.get("target"), 0) == restart_target
        and ack.get("schema") == "openwb_pro_phase_output_ack_v1"
        and str(ack.get("intent_id") or "") == intent_id
        and ack.get("success") is True
        and all(math.isfinite(value) and value > 0.0 for value in timestamps)
        and committed_ts <= intent_wall_ts <= intent_wire_ts
        and abs(intent_wire_ts - ack_wire_ts) <= 1e-6
        and abs(intent_wire_ts - restart_wire_ts) <= 1e-6
        and ack_wall_ts >= intent_wire_ts
        and authorized_ts >= ack_wall_ts
        and recovery_valid
    )


def _phase_entry_is_process_restart_preoutput(raw):
    """True nur für eine persistiert belegte, ausgangslose Generation."""

    item = raw if isinstance(raw, dict) else {}
    reservation = item.get("phase_transition_reservation")
    reservation = reservation if isinstance(reservation, dict) else {}
    hold = item.get("openwb_pro_phase_recovery_hold")
    hold = hold if isinstance(hold, dict) else {}
    reservation_id = str(reservation.get("reservation_id") or "")
    target = _valid_phase_count(reservation.get("target_phases"), 0)
    synthetic_hold = bool(
        str(reservation.get("stage") or "") == "recovery_hold"
        and hold.get("active") is True
        and str(hold.get("reason") or "") == "process_restart_recovery_hold"
        and str(hold.get("recovery_class") or "") == "output_ambiguous"
        and str(hold.get("reservation_id") or "") == reservation_id
        and str(hold.get("transition_id") or "") == reservation_id
        and _valid_phase_count(hold.get("target"), 0) == target
        and not str(hold.get("intent_id") or "")
    )
    if not (
        str(reservation.get("stage") or "") == "await_budget" and not hold
        or synthetic_hold
    ):
        return False
    candidate = dict(reservation)
    candidate["stage"] = "await_budget"
    evidence = wallbox_phase_transition.preoutput_supersession_evidence_contract(
        candidate,
        sequence=item.get("openwb_pro_phase_sequence"),
        output_intent=item.get("openwb_pro_phase_output_intent"),
        output_ack=item.get("openwb_pro_phase_output_ack"),
        restart_authorized=item.get("openwb_pro_phase_restart_authorized"),
    )
    return bool(
        evidence.get("eligible") is True
        and reservation_id
        and reservation.get("transition_id") == reservation_id
        and reservation.get("owner") == "wallbox_manager"
        and reservation.get("source") == "openwb_pro_phase_sequence"
        and int(_cfg_float(reservation.get("requested_w"), 0.0)) > 0
        and _cfg_float(reservation.get("cooldown_wire_receipt_ts"), 0.0)
        <= 0.0
        and not str(reservation.get("cooldown_source") or "")
        and wallbox_phase_transition.preoutput_supersession_evidence_is_bound(
            candidate
        )
    )


def _phase_preoutput_process_restart_fields(raw, now):
    item = raw if isinstance(raw, dict) else {}
    if not _phase_entry_is_process_restart_preoutput(item):
        return {}
    reservation = dict(item["phase_transition_reservation"])
    expires_ts = _cfg_float(
        reservation.get("lease_until_ts", reservation.get("expires_ts")),
        0.0,
    )
    if expires_ts > 0.0 and float(now) >= expires_ts:
        # Ein reiner Budgetauftrag ohne Commit, Sequenz oder Wire-Receipt darf
        # nach seiner Wallclock-Lease beim Managerneustart keinen möglichen
        # 1p-Ladestart blockieren. Da die obige Evidenzprüfung jeden
        # Hardwareausgang ausgeschlossen hat, ist hier weder ein Stop noch
        # ein elektromechanischer 480-s-Cooldown erforderlich.
        result = _phase_passive_reboot_fields(item, now)
        for key in (
            "_phase_3p_block_until",
            "_openwb_pro_phase_retry_block_until",
            "_openwb_pro_phase_change_block_until",
        ):
            result.pop(key, None)
        result.update({
            "_openwb_pro_phase_terminal_expired_ts": float(now),
            "_openwb_pro_phase_terminal_expired_reason": (
                "expired_preoutput_process_restart"
            ),
        })
        return result
    result = _phase_passive_reboot_fields(item, now)
    for key in (
        "_phase_3p_block_until",
        "_openwb_pro_phase_retry_block_until",
        "_openwb_pro_phase_change_block_until",
    ):
        result.pop(key, None)
    reservation.update({
        "stage": "await_budget",
        "blocker": "process_restart_preoutput_readback_required",
        "reason": "process_restart_preoutput_readback_required",
        "reason_code": "process_restart_preoutput_readback_required",
        "cooldown_until_ts": 0.0,
    })
    target = _valid_phase_count(reservation.get("target_phases"), 0)
    result.update({
        "_wallbox_phase_transition_reservation": reservation,
        "_openwb_pro_phase_sequence_stage": "await_budget",
        "_openwb_pro_phase_preoutput_restart_probe": {
            "active": True,
            "reservation_id": str(reservation.get("reservation_id") or ""),
            "target_phases": target,
            "restored_ts": float(now),
            "hardware_write": False,
        },
    })
    return result


def _phase_entry_requires_output_recovery(raw):
    item = raw if isinstance(raw, dict) else {}
    if _phase_entry_is_terminal_restart_only(item):
        return False
    reservation = item.get("phase_transition_reservation")
    reservation = reservation if isinstance(reservation, dict) else {}
    generation_binding = wallbox_phase_transition.output_evidence_binding_contract(
        reservation,
        sequence=item.get("openwb_pro_phase_sequence"),
        output_intent=item.get("openwb_pro_phase_output_intent"),
        output_ack=item.get("openwb_pro_phase_output_ack"),
        recovery_hold=item.get("openwb_pro_phase_recovery_hold"),
        restart_authorized=item.get("openwb_pro_phase_restart_authorized"),
    )
    if any(
        generation_binding.get(key, False)
        for key in (
            "sequence_bound",
            "output_intent_bound",
            "output_ack_bound",
            "recovery_hold_bound",
            "restart_authorized_bound",
        )
    ):
        return True
    uncommitted_wait = bool(
        reservation
        and int(_cfg_float(reservation.get("granted_w"), 0.0)) == 0
        and int(_cfg_float(reservation.get("committed_w"), 0.0)) == 0
        and _cfg_float(reservation.get("committed_ts"), 0.0) <= 0.0
        and int(_cfg_float(reservation.get("valid_frames"), 0.0)) == 0
        and str(reservation.get("stage") or "") in ("", "await_budget")
    )
    return bool(
        reservation
        and not uncommitted_wait
        and (
            reservation.get("active")
            or str(reservation.get("stage") or "") not in ("", "idle", "completed", "aborted")
        )
    )


def _phase_passive_reboot_fields(
    raw,
    now,
    *,
    preserve_future_deadlines=False,
):
    """Erhalte Hardware-Cooldown und typisierten Retry ohne Output-Intent.

    Nur bei einem belegten Prozesswechsel innerhalb desselben Boots dürfen
    bereits in Wallclock gespeicherte, noch laufende Fristen unverändert
    übernommen werden. Ein abgelaufener Timer wird dabei niemals ab dem
    Prozessstart neu auf 480 Sekunden gesetzt. Für Host-Reboots oder eine
    ungebundene Zeitbasis bleibt die konservative Neuanordnung unverändert.
    """

    item = raw if isinstance(raw, dict) else {}
    now_value = float(now)
    phase_wait_until = float(
        item.get("openwb_pro_phase_wait_until", 0.0) or 0.0
    )
    had_wait = bool(
        phase_wait_until > (
            now_value if preserve_future_deadlines else 0.0
        )
    )
    phase_block_until = float(
        item.get("phase_3p_block_until", 0.0) or 0.0
    )
    phase_change_block_until = float(
        item.get("openwb_pro_phase_change_block_until", 0.0) or 0.0
    )
    retry_block_until = float(
        item.get("openwb_pro_phase_retry_block_until", 0.0) or 0.0
    )
    typed_retry_block = bool(
        retry_block_until > 0.0
        and abs(phase_block_until - retry_block_until) <= 1e-6
    )
    active_deadline_floor = (
        now_value if preserve_future_deadlines else 0.0
    )
    had_hardware_block = bool(
        phase_change_block_until > active_deadline_floor
        or (
            phase_block_until > active_deadline_floor
            and (
                not typed_retry_block
                or phase_block_until > retry_block_until + 1e-6
            )
        )
    )
    start_fields = {}
    plug_session_id = str(item.get("openwb_pro_plug_session_id") or "")
    if plug_session_id:
        start_fields.update({
            "_openwb_pro_plug_session_id": plug_session_id,
            "_openwb_pro_start_current_issued_ts": float(
                item.get("openwb_pro_start_current_issued_ts", 0.0) or 0.0
            ),
            "_openwb_pro_start_current_session_id": str(
                item.get("openwb_pro_start_current_session_id") or ""
            ),
            "_openwb_pro_start_wakeup_count": int(
                item.get("openwb_pro_start_wakeup_count", 0) or 0
            ),
            "_openwb_pro_start_wakeup_allowed_after": 0.0,
            "_openwb_pro_start_wakeup_pending": False,
            "_openwb_pro_start_phase_target": int(
                item.get("openwb_pro_start_phase_target", 0) or 0
            ),
        })
        receipt = item.get("openwb_pro_start_wakeup_receipt")
        if isinstance(receipt, dict) and receipt:
            start_fields["_openwb_pro_start_wakeup_receipt"] = dict(receipt)
        mode5_receipt = item.get("mode5_user_start_request_receipt")
        if isinstance(mode5_receipt, dict) and mode5_receipt:
            start_fields["_mode5_user_start_request_receipt"] = dict(
                mode5_receipt
            )
            if str(mode5_receipt.get("state") or "") == "prepared":
                start_fields[
                    "_openwb_pro_session_persistence_recovery_hold"
                ] = {
                    "active": True,
                    "reason": "mode5_user_start_unfinished_replay",
                    "request_id": str(mode5_receipt.get("request_id") or ""),
                    "hardware_write": False,
                }
        persisted_session_hold = item.get(
            "openwb_pro_session_persistence_recovery_hold"
        )
        if isinstance(persisted_session_hold, dict) and persisted_session_hold:
            start_fields[
                "_openwb_pro_session_persistence_recovery_hold"
            ] = dict(persisted_session_hold)
    retry_still_active = retry_block_until > now_value
    if not (had_wait or had_hardware_block or retry_still_active):
        return start_fields
    result = dict(start_fields)
    if retry_still_active:
        # Ein fehlgeschlagener POST ohne Wire-Receipt ist nur eine Policy-
        # Wiederholsperre. Sie darf bei einem Neustart niemals zum Beleg eines
        # elektromechanischen Phasenwechsels oder zu dessen 480-s-Cooldown
        # umgedeutet werden.
        result["_openwb_pro_phase_retry_block_until"] = retry_block_until
        result["_phase_3p_block_until"] = retry_block_until
    if not (had_wait or had_hardware_block):
        return result
    if preserve_future_deadlines:
        hardware_phase_block_until = (
            phase_block_until
            if (
                phase_block_until > now_value
                and not typed_retry_block
            )
            else 0.0
        )
        conservative_until = max(
            phase_wait_until if phase_wait_until > now_value else 0.0,
            (
                phase_change_block_until
                if phase_change_block_until > now_value
                else 0.0
            ),
            hardware_phase_block_until,
        )
    else:
        conservative_until = now_value + 480.0
    # Ein passiver Neustart kann den zuvor wirksamen Geräteausgang nicht
    # zweifelsfrei rekonstruieren. Er übernimmt daher weder Wartephase,
    # Zielphase noch Sollstrom. Das bloße Vorhandensein eines früheren
    # Phasen-Waits bleibt ausschließlich als konservative Sperre gegen den
    # nächsten Phasenwechsel erhalten.
    result["_phase_3p_block_until"] = max(
        _cfg_float(result.get("_phase_3p_block_until"), 0.0),
        conservative_until,
    )
    result["_openwb_pro_phase_change_block_until"] = conservative_until
    return result


def _phase_terminal_restart_fields(
    raw,
    now,
    *,
    saved_wall_ts=0.0,
    saved_monotonic_ts=0.0,
    current_monotonic_ts=0.0,
):
    """Entfernt den fertigen Ausgang und erhält nur die Rest-Schutzfrist."""

    item = raw if isinstance(raw, dict) else {}
    now_value = float(now)
    result = _phase_passive_reboot_fields(item, now_value)
    for key in (
        "_openwb_pro_phase_wait_until",
        "_openwb_pro_phase_wait_target",
        "_openwb_pro_phase_wait_amp",
        "_phase_3p_block_until",
        "_openwb_pro_phase_retry_block_until",
        "_openwb_pro_phase_change_block_until",
    ):
        result.pop(key, None)
    cooldown_until = max(
        _cfg_float(item.get("phase_3p_block_until"), 0.0),
        _cfg_float(item.get("openwb_pro_phase_change_block_until"), 0.0),
    )
    saved_wall = _cfg_float(saved_wall_ts, 0.0)
    saved_monotonic = _cfg_float(saved_monotonic_ts, 0.0)
    current_monotonic = _cfg_float(current_monotonic_ts, 0.0)
    remaining_at_save_s = max(0.0, cooldown_until - saved_wall)
    monotonic_elapsed_s = current_monotonic - saved_monotonic
    wall_elapsed_s = now_value - saved_wall
    timebase_bound = bool(
        math.isfinite(cooldown_until)
        and saved_wall > 0.0
        and all(math.isfinite(value) and value >= 0.0 for value in (
            saved_monotonic,
            current_monotonic,
        ))
        and wall_elapsed_s >= -1.0
        and monotonic_elapsed_s >= -1.0
        and abs(wall_elapsed_s - monotonic_elapsed_s) <= 60.0
    )
    if cooldown_until <= 0.0 or remaining_at_save_s <= 0.0:
        remaining_s = 0.0
    elif timebase_bound:
        remaining_s = max(0.0, remaining_at_save_s - monotonic_elapsed_s)
    else:
        # Eine ungebundene Wallclock darf die physische 480-s-Sperre niemals
        # verkürzen. Nur der nächste Phasenwechsel wird neu verankert; der
        # bestätigte Wiederanlaufstrom bleibt weiterhin freigegeben.
        remaining_s = max(480.0, remaining_at_save_s)
    projected_cooldown_until = now_value + remaining_s
    result["_openwb_pro_phase_cooldown_remaining_s"] = remaining_s
    if remaining_s > 0.0:
        result["_phase_3p_block_until"] = projected_cooldown_until
        result["_openwb_pro_phase_change_block_until"] = (
            projected_cooldown_until
        )
    return result

def _save_wallbox_phase_state(chargers):
    try:
        now = time.time()
        boot_id = _wallbox_phase_boot_id()
        process_epoch = control_time.process_epoch()
        existing = _load_wallbox_phase_state()
        if isinstance(existing, dict) and existing.get("__load_error__"):
            return False
        entries = {}
        if isinstance(existing, dict):
            previous_entries = existing.get("wallboxes")
            if isinstance(previous_entries, dict):
                entries = {
                    str(key): dict(value)
                    for key, value in previous_entries.items()
                    if isinstance(value, dict)
                }
                if existing.get("boot_id") != boot_id:
                    for key, value in list(entries.items()):
                        if _phase_entry_requires_output_recovery(value):
                            reboot_fields = _phase_recovery_fields(
                                "host_reboot_recovery_hold", value
                            )
                        else:
                            reboot_fields = _phase_passive_reboot_fields(value, now)
                        entries[key] = _phase_state_entry(
                            {"id": key, **reboot_fields}, now
                        )
        for c_data in chargers or []:
            c_id = str(c_data.get("id", ""))
            if not c_id:
                continue
            entry = _phase_state_entry(c_data, now)
            if entry:
                entries[c_id] = entry
            else:
                entries.pop(c_id, None)
        if (
            isinstance(existing, dict)
            and not existing.get("__load_error__")
            and existing.get("boot_id") == boot_id
            and existing.get("process_epoch") == process_epoch
            and existing.get("wallboxes") == entries
        ):
            return True
        data = {
            "schema": "wallbox_phase_state_v3",
            "boot_id": boot_id,
            "process_epoch": process_epoch,
            "saved_wall_ts": now,
            "saved_monotonic_ts": time.monotonic(),
            "wallboxes": entries,
        }
        directory = os.path.dirname(WB_PHASE_STATE_FILE)
        os.makedirs(directory, mode=0o775, exist_ok=True)
        if os.path.islink(directory):
            return False
        tmp = WB_PHASE_STATE_FILE + ".tmp.%d" % os.getpid()
        payload = json.dumps(data, ensure_ascii=False, sort_keys=True, separators=(",", ":")) + "\n"
        with open(tmp, "w", encoding="utf-8") as f:
            f.write(payload)
            f.flush()
            os.fsync(f.fileno())
        os.chmod(tmp, 0o664)
        os.replace(tmp, WB_PHASE_STATE_FILE)
        dir_fd = os.open(directory, os.O_RDONLY)
        try:
            os.fsync(dir_fd)
        finally:
            os.close(dir_fd)
        return True
    except Exception as exc:
        logger.error("Wallbox-Phasenstatus konnte nicht crashfest gespeichert werden: %s", exc)
        try:
            if os.path.exists(locals().get("tmp", "")):
                os.unlink(tmp)
        except Exception:
            pass
        return False


def _phase_entry_is_cross_generation_stranded_zero(raw):
    """Erkennt den einzigen alten Output-/neuen Pre-output-Umschlag."""

    item = raw if isinstance(raw, dict) else {}
    reservation = item.get("phase_transition_reservation")
    reservation = reservation if isinstance(reservation, dict) else {}
    hold = item.get("openwb_pro_phase_recovery_hold")
    hold = hold if isinstance(hold, dict) else {}
    intent = item.get("openwb_pro_phase_output_intent")
    intent = intent if isinstance(intent, dict) else {}
    ack = item.get("openwb_pro_phase_output_ack")
    ack = ack if isinstance(ack, dict) else {}
    current_id = str(
        reservation.get("transition_id")
        or reservation.get("reservation_id")
        or ""
    )
    old_id = str(intent.get("transition_id") or "")
    intent_id = str(intent.get("intent_id") or "")
    target = _valid_phase_count(intent.get("target"), 0)
    sequence_after = intent.get("sequence_after")
    sequence_after = sequence_after if isinstance(sequence_after, dict) else {}
    intent_ts = _cfg_float(intent.get("wall_ts"), 0.0)
    ack_ts = _cfg_float(ack.get("wall_ts"), 0.0)
    started_ts = _cfg_float(reservation.get("started_ts"), 0.0)
    if intent_ts > 100_000_000_000.0:
        intent_ts /= 1000.0
    if ack_ts > 100_000_000_000.0:
        ack_ts /= 1000.0
    if started_ts > 100_000_000_000.0:
        started_ts /= 1000.0
    return bool(
        reservation.get("schema_version")
        == "wallbox_phase_transition_v2"
        and reservation.get("active") is True
        and str(reservation.get("stage") or "") == "await_budget"
        and current_id
        and current_id != old_id
        and str(reservation.get("reservation_id") or "") == current_id
        and str(reservation.get("transition_id") or "") == current_id
        and str(reservation.get("owner") or "") == "wallbox_manager"
        and str(reservation.get("source") or "")
        == "openwb_pro_phase_sequence"
        and _valid_phase_count(reservation.get("target_phases"), 0)
        == target
        and target in (1, 3)
        and str(reservation.get("grant_state") or "") == "waiting"
        and int(_cfg_float(reservation.get("requested_w"), 0.0)) > 0
        and int(_cfg_float(reservation.get("granted_w"), 0.0)) == 0
        and int(_cfg_float(reservation.get("committed_w"), 0.0)) == 0
        and _cfg_float(reservation.get("committed_ts"), 0.0) <= 0.0
        and int(_cfg_float(reservation.get("valid_frames"), 0.0)) == 0
        and _cfg_float(
            reservation.get("cooldown_wire_receipt_ts"),
            0.0,
        )
        <= 0.0
        and not str(reservation.get("cooldown_source") or "")
        and hold.get("active") is True
        and str(hold.get("reason") or "") == "phase_zero_unconfirmed"
        and str(hold.get("reservation_id") or "") == old_id
        and str(hold.get("transition_id") or "") == old_id
        and str(hold.get("intent_id") or "") == intent_id
        and _valid_phase_count(hold.get("target"), 0) == target
        and intent.get("schema") == "openwb_pro_phase_output_intent_v1"
        and old_id
        and intent_id.startswith(old_id + ":send_zero:")
        and str(intent.get("action") or "") == "send_zero"
        and str(intent.get("method") or "") == "set_amp_and_state"
        and sequence_after.get("stage") == "zero_wait"
        and _valid_phase_count(sequence_after.get("target"), 0) == target
        and ack.get("schema") == "openwb_pro_phase_output_ack_v1"
        and str(ack.get("intent_id") or "") == intent_id
        and ack.get("success") is False
        and str(ack.get("reason") or "") == "phase_zero_unconfirmed"
        and all(
            math.isfinite(value) and value > 0.0
            for value in (intent_ts, ack_ts, started_ts)
        )
        and intent_ts <= ack_ts < started_ts
        and not (
            isinstance(item.get("openwb_pro_phase_sequence"), dict)
            and item.get("openwb_pro_phase_sequence")
        )
        and not (
            isinstance(item.get("openwb_pro_phase_restart_authorized"), dict)
            and item["openwb_pro_phase_restart_authorized"].get("active")
            is True
        )
    )


def _phase_stranded_zero_process_restart_fields(raw, now):
    """Erhält den Umschlag bis zum ersten frischen post-intent Readback."""

    item = raw if isinstance(raw, dict) else {}
    if not _phase_entry_is_cross_generation_stranded_zero(item):
        return {}
    result = _phase_passive_reboot_fields(item, now)
    result.update({
        "_wallbox_phase_transition_reservation": dict(
            item["phase_transition_reservation"]
        ),
        "_openwb_pro_phase_recovery_hold": dict(
            item["openwb_pro_phase_recovery_hold"]
        ),
        "_openwb_pro_phase_output_intent": dict(
            item["openwb_pro_phase_output_intent"]
        ),
        "_openwb_pro_phase_output_ack": dict(
            item["openwb_pro_phase_output_ack"]
        ),
        "_openwb_pro_phase_sequence_stage": "await_budget",
    })
    return result


def _phase_recovery_fields(reason, raw=None):
    item = raw if isinstance(raw, dict) else {}
    target = int(item.get("openwb_pro_phase_wait_target", 0) or 0)
    sequence = item.get("openwb_pro_phase_sequence")
    if isinstance(sequence, dict):
        target = int(sequence.get("target", target) or target or 0)
    reservation_raw = item.get("phase_transition_reservation")
    reservation_raw = (
        dict(reservation_raw) if isinstance(reservation_raw, dict) else {}
    )
    target = int(
        reservation_raw.get("target_phases", target)
        or target
        or 0
    )
    intent_raw = item.get("openwb_pro_phase_output_intent")
    intent_raw = dict(intent_raw) if isinstance(intent_raw, dict) else {}
    reservation_id = str(
        reservation_raw.get("transition_id")
        or reservation_raw.get("reservation_id")
        or ""
    )
    uncommitted = bool(
        reservation_raw
        and int(_cfg_float(reservation_raw.get("granted_w"), 0.0)) == 0
        and int(_cfg_float(reservation_raw.get("committed_w"), 0.0)) == 0
        and _cfg_float(reservation_raw.get("committed_ts"), 0.0) <= 0.0
        and int(_cfg_float(reservation_raw.get("valid_frames"), 0.0)) == 0
    )
    expired = bool(
        str(reservation_raw.get("grant_state") or "") == "expired"
        or str(reservation_raw.get("blocker") or "") == "lease_expired"
    )
    has_output_evidence = any(
        isinstance(item.get(key), dict) and bool(item.get(key))
        for key in (
            "openwb_pro_phase_sequence",
            "openwb_pro_phase_output_intent",
            "openwb_pro_phase_output_ack",
        )
    )
    hold = {
        "active": True,
        "reason": str(reason),
        "target": target if target in (1, 3) else 0,
        "intent_id": str(intent_raw.get("intent_id") or ""),
        "reservation_id": reservation_id,
        "transition_id": reservation_id,
        "recovery_class": (
            "expired_uncommitted_no_output"
            if expired and uncommitted and not has_output_evidence
            else "output_ambiguous"
        ),
    }
    reservation = reservation_raw or {
        "schema_version": "wallbox_phase_transition_v2",
        "active": True,
        "stage": "recovery_hold",
        "grant_state": "waiting",
        "requested_w": 0,
        "granted_w": 0,
        "committed_w": 0,
        "target_phases": hold["target"],
    }
    reservation.update({
        "active": True,
        "stage": "recovery_hold",
        "blocker": str(reason),
        "reason_code": str(reason),
        "reason": str(reason),
    })
    return {
        "_openwb_pro_phase_recovery_hold": hold,
        "_openwb_pro_phase_sequence": (
            dict(item.get("openwb_pro_phase_sequence"))
            if isinstance(item.get("openwb_pro_phase_sequence"), dict)
            else {}
        ),
        "_openwb_pro_phase_sequence_stage": "recovery_hold",
        "_wallbox_phase_transition_reservation": reservation,
        **(
            {"_openwb_pro_phase_output_intent": dict(item["openwb_pro_phase_output_intent"])}
            if isinstance(item.get("openwb_pro_phase_output_intent"), dict)
            else {}
        ),
        **(
            {"_openwb_pro_phase_output_ack": dict(item["openwb_pro_phase_output_ack"])}
            if isinstance(item.get("openwb_pro_phase_output_ack"), dict)
            else {}
        ),
        **(
            {
                "_openwb_pro_phase_restart_authorized": dict(
                    item["openwb_pro_phase_restart_authorized"]
                )
            }
            if isinstance(item.get("openwb_pro_phase_restart_authorized"), dict)
            else {}
        ),
        **(
            {
                "_mode5_user_start_request_receipt": dict(
                    item["mode5_user_start_request_receipt"]
                )
            }
            if isinstance(item.get("mode5_user_start_request_receipt"), dict)
            else {}
        ),
        **(
            {
                "_openwb_pro_session_persistence_recovery_hold": dict(
                    item["openwb_pro_session_persistence_recovery_hold"]
                )
            }
            if isinstance(
                item.get("openwb_pro_session_persistence_recovery_hold"),
                dict,
            )
            else (
                {
                    "_openwb_pro_session_persistence_recovery_hold": {
                        "active": True,
                        "reason": "mode5_user_start_unfinished_replay",
                        "request_id": str(
                            (
                                item.get("mode5_user_start_request_receipt")
                                or {}
                            ).get("request_id")
                            or ""
                        ),
                        "hardware_write": False,
                    }
                }
                if isinstance(
                    item.get("mode5_user_start_request_receipt"),
                    dict,
                )
                and str(
                    item["mode5_user_start_request_receipt"].get("state")
                    or ""
                )
                == "prepared"
                else {}
            )
        ),
    }

def _restored_phase_fields(phase_state, charger_id):
    try:
        if not isinstance(phase_state, dict):
            return _phase_recovery_fields("phase_state_not_mapping")
        if phase_state.get("__load_error__"):
            return _phase_recovery_fields(str(phase_state.get("__load_error__")))
        raw = phase_state.get("wallboxes", {}).get(str(charger_id), {})
        if not isinstance(raw, dict) or not raw:
            return {}
        current_boot = _wallbox_phase_boot_id()
        if str(phase_state.get("boot_id") or "") != current_boot:
            if _phase_entry_requires_output_recovery(raw):
                return _phase_recovery_fields("host_reboot_recovery_hold", raw)
            return _phase_passive_reboot_fields(raw, time.time())
        now_value = time.time()
        saved_wall_ts = float(
            phase_state.get("saved_wall_ts", 0.0) or 0.0
        )
        saved_monotonic_ts = float(
            phase_state.get("saved_monotonic_ts", 0.0) or 0.0
        )
        current_monotonic_ts = time.monotonic()
        saved_process_epoch = str(phase_state.get("process_epoch") or "")
        current_process_epoch = str(control_time.process_epoch() or "")
        wall_elapsed = now_value - saved_wall_ts
        monotonic_elapsed = current_monotonic_ts - saved_monotonic_ts
        same_boot_timebase_bound = bool(
            saved_wall_ts > 0.0
            and saved_monotonic_ts >= 0.0
            and current_monotonic_ts >= 0.0
            and wall_elapsed >= -1.0
            and monotonic_elapsed >= -1.0
            and abs(wall_elapsed - monotonic_elapsed) <= 60.0
        )
        # Ein v3-Altstand ohne Prozessepoche stammt zwingend aus einem
        # früheren Managerstand. Er wird deshalb wie ein Prozesswechsel
        # behandelt und nicht als aktuelle In-Memory-Generation imputiert.
        process_changed = bool(
            current_process_epoch
            and saved_process_epoch != current_process_epoch
        )
        if process_changed:
            preoutput_fields = _phase_preoutput_process_restart_fields(
                raw,
                now_value,
            )
            if preoutput_fields:
                return preoutput_fields
            if _phase_entry_is_terminal_restart_only(raw):
                return _phase_terminal_restart_fields(
                    raw,
                    now_value,
                    saved_wall_ts=saved_wall_ts,
                    saved_monotonic_ts=saved_monotonic_ts,
                    current_monotonic_ts=current_monotonic_ts,
                )
            if _phase_entry_is_cross_generation_stranded_zero(raw):
                return _phase_stranded_zero_process_restart_fields(
                    raw,
                    now_value,
                )
            if _phase_entry_requires_output_recovery(raw):
                return _phase_recovery_fields(
                    "process_restart_recovery_hold",
                    raw,
                )
            return _phase_passive_reboot_fields(
                raw,
                now_value,
                preserve_future_deadlines=same_boot_timebase_bound,
            )
        if monotonic_elapsed < -1.0 or abs(wall_elapsed - monotonic_elapsed) > 60.0:
            if _phase_entry_requires_output_recovery(raw):
                return _phase_recovery_fields("clock_jump_recovery_hold", raw)
            return _phase_passive_reboot_fields(raw, time.time())
        intent = raw.get("openwb_pro_phase_output_intent")
        ack = raw.get("openwb_pro_phase_output_ack")
        if isinstance(intent, dict) and intent:
            ack_bound = bool(
                isinstance(ack, dict)
                and ack.get("schema") == "openwb_pro_phase_output_ack_v1"
                and ack.get("intent_id") == intent.get("intent_id")
                and (
                    ack.get("success") is True
                    or ack.get("success") is False
                )
            )
            negative_reason = {
                "send_zero": "phase_zero_unconfirmed",
                "send_phase": "phase_target_unconfirmed",
            }.get(str(intent.get("action") or ""), "")
            if (
                ack_bound
                and ack.get("success") is False
                and negative_reason
                and str(ack.get("reason") or "") == negative_reason
            ):
                return _phase_recovery_fields(negative_reason, raw)
            if not ack_bound or ack.get("success") is not True:
                return _phase_recovery_fields("unconfirmed_output_recovery_hold", raw)
        block_until = float(raw.get("phase_3p_block_until", 0.0) or 0.0)
        result = {}
        if block_until > now_value:
            result["_phase_3p_block_until"] = block_until
        retry_block_until = float(
            raw.get("openwb_pro_phase_retry_block_until", 0.0) or 0.0
        )
        if retry_block_until > now_value:
            result["_openwb_pro_phase_retry_block_until"] = (
                retry_block_until
            )
            result["_phase_3p_block_until"] = max(
                _cfg_float(result.get("_phase_3p_block_until"), 0.0),
                retry_block_until,
            )
        phase_change_block_until = float(
            raw.get("openwb_pro_phase_change_block_until", 0.0) or 0.0
        )
        if phase_change_block_until > now_value:
            result["_openwb_pro_phase_change_block_until"] = phase_change_block_until
        phase_wait_until = float(raw.get("openwb_pro_phase_wait_until", 0.0) or 0.0)
        if phase_wait_until > now_value:
            result.update({
                "_openwb_pro_phase_wait_until": phase_wait_until,
                "_openwb_pro_phase_wait_target": int(raw.get("openwb_pro_phase_wait_target", 0) or 0),
                "_openwb_pro_phase_wait_amp": float(raw.get("openwb_pro_phase_wait_amp", 0.0) or 0.0),
            })
        reservation = raw.get("phase_transition_reservation")
        if isinstance(reservation, dict) and reservation:
            result["_wallbox_phase_transition_reservation"] = dict(reservation)
        sequence = raw.get("openwb_pro_phase_sequence")
        if isinstance(sequence, dict) and sequence:
            result["_openwb_pro_phase_sequence"] = dict(sequence)
            result["_openwb_pro_phase_sequence_stage"] = str(sequence.get("stage") or "")
            result["_openwb_pro_phase_sequence_target"] = int(sequence.get("target", 0) or 0)
            result["_openwb_pro_phase_sequence_current_allowed_after"] = float(sequence.get("current_allowed_after", 0.0) or 0.0)
        if isinstance(intent, dict) and intent:
            result["_openwb_pro_phase_output_intent"] = dict(intent)
        if isinstance(ack, dict) and ack:
            result["_openwb_pro_phase_output_ack"] = dict(ack)
        recovery_hold = raw.get("openwb_pro_phase_recovery_hold")
        if isinstance(recovery_hold, dict) and recovery_hold:
            result["_openwb_pro_phase_recovery_hold"] = dict(recovery_hold)
        stranded_zero_recovery = raw.get(
            "openwb_pro_phase_stranded_zero_recovery"
        )
        if isinstance(stranded_zero_recovery, dict) and stranded_zero_recovery:
            result["_openwb_pro_phase_stranded_zero_recovery"] = dict(
                stranded_zero_recovery
            )
        phase_restart = raw.get("openwb_pro_phase_restart_authorized")
        if isinstance(phase_restart, dict) and phase_restart:
            result["_openwb_pro_phase_restart_authorized"] = dict(phase_restart)
        scalar_restore = (
            ("openwb_pro_plug_session_id", "_openwb_pro_plug_session_id", str),
            ("openwb_pro_start_current_issued_ts", "_openwb_pro_start_current_issued_ts", float),
            ("openwb_pro_start_current_session_id", "_openwb_pro_start_current_session_id", str),
            ("openwb_pro_start_wakeup_count", "_openwb_pro_start_wakeup_count", int),
            ("openwb_pro_start_wakeup_allowed_after", "_openwb_pro_start_wakeup_allowed_after", float),
            ("openwb_pro_start_wakeup_pending", "_openwb_pro_start_wakeup_pending", bool),
            ("openwb_pro_start_phase_target", "_openwb_pro_start_phase_target", int),
            ("openwb_pro_unserved_since", "_openwb_pro_unserved_since", float),
            ("openwb_pro_unserved_pause_since", "_openwb_pro_unserved_pause_since", float),
            ("openwb_pro_unserved_paused_s", "_openwb_pro_unserved_paused_s", float),
        )
        for source_key, target_key, converter in scalar_restore:
            if source_key in raw:
                raw_value = raw.get(source_key)
                result[target_key] = (
                    str(raw_value or "")
                    if converter is str
                    else converter(raw_value or 0)
                )
        receipt = raw.get("openwb_pro_start_wakeup_receipt")
        if isinstance(receipt, dict) and receipt:
            result["_openwb_pro_start_wakeup_receipt"] = dict(receipt)
        mode5_receipt = raw.get("mode5_user_start_request_receipt")
        if isinstance(mode5_receipt, dict) and mode5_receipt:
            result["_mode5_user_start_request_receipt"] = dict(mode5_receipt)
        session_persistence_hold = raw.get(
            "openwb_pro_session_persistence_recovery_hold"
        )
        if isinstance(session_persistence_hold, dict) and session_persistence_hold:
            result["_openwb_pro_session_persistence_recovery_hold"] = dict(
                session_persistence_hold
            )
        return result
    except Exception as exc:
        return _phase_recovery_fields("phase_state_restore_failed:%s" % exc.__class__.__name__)

def read_price_boost_allow(device, config=None):
    try:
        if config is not None and str(config.get("cheap_grid_boost_enable", 0)).strip().lower() not in ("1", "true", "yes", "on"):
            return False
        if not os.path.exists(PRICE_BOOST_PLAN_FILE):
            return False
        with open(PRICE_BOOST_PLAN_FILE, "r", encoding="utf-8") as f:
            plan = json.load(f)
        win = plan.get("active_window") or {}
        now_ms = int(time.time() * 1000)
        start_ms = int(win.get("start_timestamp", 0) or 0)
        end_ms = int(win.get("end_timestamp", 0) or 0)
        return bool(plan.get("enabled") and plan.get("active")
                    and start_ms <= now_ms < end_ms
                    and plan.get("allow", {}).get(device, False))
    except Exception:
        return False

def read_market_plan_allow(device, storage_plan=None, config=None):
    try:
        ctx = current_market_consumer_release(storage_plan or {}, device, config)
        return ctx if isinstance(ctx, dict) else {"allowed": False}
    except Exception:
        return {"allowed": False, "reason": "market_plan_error"}


def _wallbox_market_price_mode_ids(wb_charge_mode, charger_ids):
    """Return chargers that explicitly opted into price-controlled grid charging."""
    result = set()
    for c_id in charger_ids or []:
        try:
            cid = int(c_id)
            if normalize_wb_mode(wb_charge_mode.get(cid, MODE_OFF)) == MODE_PRICE:
                result.add(cid)
        except Exception:
            continue
    return result

def read_predump_allow(device, config=None):
    """Pre-Dump-Verbraucherfreigabe lesen.

    Kein Netzmodus: die Wallbox darf nur Speicher/PV nutzen und wird wie
    C++ Mode 10 behandelt.
    """
    try:
        if config is not None:
            key = "predump_%s_enable" % device
            if str(config.get(key, 0)).strip().lower() not in ("1", "true", "yes", "on"):
                return False
        if not os.path.exists(PREDUMP_PLAN_FILE):
            return False
        with open(PREDUMP_PLAN_FILE, "r", encoding="utf-8") as f:
            plan = json.load(f)
        now = int(time.time())
        expires_ts = int(plan.get("expires_ts", 0) or 0)
        return bool(plan.get("enabled") and plan.get("active")
                    and now <= expires_ts
                    and plan.get("allow", {}).get(device, False))
    except Exception:
        return False


def _wb_status_connected(status):
    """True nur bei physischer oder streng gebundener CP-Verbindung.

    Während eines von diesem Manager selbst ausgelösten kurzen CP-Wake-ups
    meldet die openWB Pro vorübergehend einen scheinbaren Unplug. Der
    typisierte Receipt-Vertrag darf diesen Zustand für die Policy als weiter
    verbunden halten; das rohe Steckerfeld bleibt unverändert und der
    Hardware-Output-Gate verlangt weiterhin einen frischen echten
    Anschlussbeleg.
    """

    if wallbox_decision.status_connected(status):
        return True
    st = status if isinstance(status, dict) else {}
    contract = st.get("openwb_pro_manager_wakeup_disconnect_contract")
    return bool(
        isinstance(contract, dict)
        and str(contract.get("contract") or "")
        == "openwb_pro_manager_wakeup_disconnect_v1"
        and contract.get("synthetic_disconnect") is True
        and contract.get("receipt_bound") is True
        and contract.get("session_bound") is True
        and contract.get("current_receipt_bound") is True
        and contract.get("timeline_valid") is True
        and contract.get("count_valid") is True
        and st.get("driver_status_valid") is True
        and not bool(st.get("driver_status_stale", False))
        and not bool(st.get("driver_status_degraded", False))
        and not bool(st.get("driver_status_glitch", False))
    )


def _wallbox_price_mode_grid_allowed_for_charger(wb_charge_mode, c_id, mode5_grid_allowed=False):
    """True when this concrete charger is in open price-limit mode."""
    if not bool(mode5_grid_allowed):
        return False
    try:
        return normalize_wb_mode(wb_charge_mode.get(int(c_id), MODE_OFF)) == MODE_PRICE
    except Exception:
        return False


def _clear_wallbox_manual_pause_text_config(path, key):
    if not path or not os.path.exists(path):
        return True
    try:
        with open(path, "r", encoding="utf-8", errors="ignore") as f:
            lines = f.read().splitlines()
        changed = False
        found = False
        new_lines = []
        for line in lines:
            stripped = line.strip()
            if stripped and not stripped.startswith("#") and not stripped.startswith("//") and "=" in line:
                name, raw_value = line.split("=", 1)
                if name.strip().lower() == key:
                    found = True
                    value_part = raw_value.split("//", 1)[0].split("#", 1)[0].strip()
                    if _truthy_config(value_part):
                        new_lines.append(f"{name.rstrip()} = 0")
                        changed = True
                        continue
            new_lines.append(line)
        if not found or not changed:
            return True
        tmp_path = path + ".tmp"
        with open(tmp_path, "w", encoding="utf-8") as f:
            f.write("\n".join(new_lines) + "\n")
        os.replace(tmp_path, path)
        try:
            os.chmod(path, 0o664)
        except Exception:
            pass
        return True
    except Exception as exc:
        logger.warning(f"Manuelle Wallbox-Pause konnte in {path} nicht geloescht werden: {exc}")
        return False


def _clear_wallbox_manual_pause_json_config(path, key):
    if not path or not os.path.exists(path):
        return True
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
        if not isinstance(data, dict):
            return True
        changed = False
        containers = [data]
        if isinstance(data.get("config"), dict):
            containers.append(data["config"])
        for container in containers:
            for existing_key in list(container.keys()):
                if str(existing_key).strip().lower() == key and _truthy_config(container.get(existing_key)):
                    container[existing_key] = "0"
                    changed = True
        if not changed:
            return True
        tmp_path = path + ".tmp"
        with open(tmp_path, "w", encoding="utf-8") as f:
            json.dump(data, f, indent=2, ensure_ascii=False)
            f.write("\n")
        os.replace(tmp_path, path)
        try:
            if os.path.abspath(path) == os.path.abspath(V4_CONFIG_FILE):
                apply_config_secret_permissions(path, data=data)
            else:
                os.chmod(path, 0o664)
        except Exception:
            pass
        return True
    except Exception as exc:
        logger.warning(f"Manuelle Wallbox-Pause konnte in {path} nicht geloescht werden: {exc}")
        return False


def _clear_wallbox_manual_pause_config(wb_id):
    key = f"wb{int(wb_id)}_manual_pause"
    text_ok = _clear_wallbox_manual_pause_text_config(CONFIG_FILE, key)
    json_ok = _clear_wallbox_manual_pause_json_config(V4_CONFIG_FILE, key)
    return bool(text_ok and json_ok)


def _auto_clear_manual_pause_after_unplug(wb_manual_pause, valid_chargers_status, dyn_config):
    changed = False
    for item in valid_chargers_status or []:
        try:
            cid = int(item.get("id", 0) or 0)
        except Exception:
            cid = 0
        if cid not in (1, 2) or not bool(wb_manual_pause.get(cid, False)):
            continue
        status = item.get("status")
        if not isinstance(status, dict) or _wb_status_connected(status):
            continue
        if _clear_wallbox_manual_pause_config(cid):
            wb_manual_pause[cid] = False
            if isinstance(dyn_config, dict):
                dyn_config[f"wb{cid}_manual_pause"] = "0"
            changed = True
            logger.info(f"[WB{cid}] Manuelle Pause nach Abstecken automatisch beendet.")
        else:
            logger.warning(f"[WB{cid}] Manuelle Pause bleibt aktiv: Konfiguration konnte nicht aktualisiert werden.")
    return changed


def _wb_status_real_power(status):
    """Echte gemessene Wallboxleistung, keine Ableitung aus Soll-Ampere."""
    return wallbox_decision.status_real_power(status)


def _wb_status_real_charging(status):
    """Laden zaehlt nur mit Hardware-Ladebit oder verifizierter Phasenleistung."""
    return wallbox_decision.status_real_charging(status)


def _fresh_wallbox_reported_current_amp(status):
    """Liefert nur aus einem frischen Treiberstatus den angebotenen Strom."""
    st = status if isinstance(status, dict) else {}
    if (
        not st
        or st.get("driver_status_valid") is not True
        or st.get("driver_status_stale") is not False
        or st.get("driver_status_degraded") is True
        or st.get("driver_status_glitch") is not False
        or st.get("valid") is False
        or bool(st.get("stale", False))
    ):
        return None
    return max(
        0.0,
        _cfg_float(st.get("offered_current_raw"), 0.0),
        _cfg_float(st.get("offered_current"), 0.0),
        _cfg_float(st.get("evse_current"), 0.0),
        _cfg_float(st.get("amp"), 0.0),
    )


def _startup_adopted_current_amp(status, *, charging, charger_max_amp=16):
    """Übernehme einen Startup-Strom nur frisch und innerhalb der WB-Grenze."""

    if not charging:
        return {
            "contract": "wallbox_startup_current_adoption_v1",
            "observed_amp": None,
            "adopted_amp": 0,
            "charger_max_amp": _amp_limit(charger_max_amp, 16),
            "source": "not_charging",
        }
    observed = _fresh_wallbox_reported_current_amp(status)
    maximum = max(6, _amp_limit(charger_max_amp, 16))
    adopted = int(max(6, min(observed if observed is not None else 6, maximum)))
    return {
        "contract": "wallbox_startup_current_adoption_v1",
        "observed_amp": observed,
        "adopted_amp": adopted,
        "charger_max_amp": maximum,
        "source": (
            "fresh_driver_current_capped"
            if observed is not None
            else "minimum_hold_without_fresh_current"
        ),
    }


def _project_wallbox_current_state(c_data, status, *, receipt=None):
    """Projiziere Stromzustand nur aus Receipt oder frischem Readback."""

    box = c_data if isinstance(c_data, dict) else {}
    st = status if isinstance(status, dict) else {}
    current_receipt = receipt if isinstance(receipt, dict) else {}
    cycle_token = str(box.get("_wallbox_cycle_token") or "")
    receipt_valid = bool(
        current_receipt
        and cycle_token
        and str(current_receipt.get("cycle_token") or "") == cycle_token
        and str(current_receipt.get("method") or "")
        in _EFFECTIVE_CURRENT_METHODS
    )
    if (
        not receipt_valid
        and _native_e3dc_floor_zero_anchor_active(box)
    ):
        # Native E3DC meldet nach dem Hardstop protokollbedingt weiterhin
        # mindestens 6 A. Ohne neuen Hardwarebeleg ist das keine physische
        # Ladefreigabe und darf weder Nullanker noch Stop-Latch aufheben.
        box["_wallbox_current_state_projection_blocked"] = {
            "contract": "wallbox_current_state_projection_block_v1",
            "reason": "native_floor_zero_anchor_retry_not_released",
            "release_status": "EVIDENCE_LIMIT",
            "cycle_token": cycle_token,
            "preserve_hard_stop_anchor": True,
        }
        return None
    if receipt_valid:
        projected_amp = max(
            0.0,
            _cfg_float(current_receipt.get("amp"), 0.0),
        )
        source = "same_cycle_output_receipt"
    else:
        projected_amp = _fresh_wallbox_reported_current_amp(st)
        if projected_amp is None:
            return None
        source = "fresh_driver_readback"
    box["current_set_amp"] = projected_amp
    box["is_charging"] = bool(
        _wb_status_real_charging(st)
        or _wb_status_real_power(st) > 500.0
    )
    if projected_amp > 0.0 or box["is_charging"]:
        box["_wb_stop_sent_active"] = False
    projection = {
        "contract": "wallbox_current_state_projection_v1",
        "source": source,
        "amp": projected_amp,
        "is_charging": bool(box["is_charging"]),
        "cycle_token": cycle_token,
    }
    box["_wallbox_current_state_projection"] = projection
    return projection


def _e3dc_native_reconciled_current_set_amp(
    c_data,
    status,
    *,
    reported_amp=0,
    max_amp=16,
):
    """Bewahrt einen physisch bestätigten Direkt-Sollstrom bei stale 6-A-Status.

    Die Easy Connect kann in PARAM1 weiterhin 6 A melden, obwohl ein zuvor
    gesendeter Direktstrom bereits als deutlich höhere, verifizierte
    Phasenleistung wirkt. Nur für den eng gebundenen PV+Akku-Direktpfad bleibt
    dann der letzte tatsächlich gesendete Sollstrom führend. Ohne frische
    Ladephysik, bei Statusfehlern oder nach jeder anderen Kommandokante bleibt
    der normale Hardware-Readback maßgeblich.
    """
    box = c_data if isinstance(c_data, dict) else {}
    st = status if isinstance(status, dict) else {}
    try:
        status_amp = max(0, int(round(float(reported_amp or 0))))
    except (TypeError, ValueError):
        status_amp = 0
    try:
        limit_amp = max(0, int(round(float(max_amp or 0))))
    except (TypeError, ValueError):
        limit_amp = 0
    if limit_amp > 0:
        status_amp = min(status_amp, limit_amp)

    charger = box.get("charger")
    native_e3dc = bool(
        charger is not None
        and hasattr(charger, "set_amp_sonnenmodus")
        and not hasattr(charger, "set_pv_mode")
    )
    last_command = box.get("_last_executed_command")
    if not native_e3dc or not isinstance(last_command, dict):
        return status_amp
    if (
        str(last_command.get("method") or "") != "set_amp_and_state"
        or str(last_command.get("reason") or "") != "native_storage_floor_current"
    ):
        return status_amp
    if (
        st.get("driver_status_valid") is False
        or bool(st.get("driver_status_stale", False))
        or st.get("valid") is False
        or bool(st.get("stale", False))
        or not _wb_status_connected(st)
        or not _wb_status_real_charging(st)
        or not bool(st.get("phase_power_verified", False))
    ):
        return status_amp

    try:
        command_amp = max(0, int(round(float(last_command.get("amp", 0) or 0))))
    except (TypeError, ValueError):
        command_amp = 0
    if limit_amp > 0:
        command_amp = min(command_amp, limit_amp)
    if command_amp <= status_amp:
        return status_amp

    try:
        phases = int(st.get("phases_in_use", 0) or st.get("phases_actual", 0) or 1)
    except (TypeError, ValueError):
        phases = 1
    phases = max(1, min(3, phases))
    real_power_w = _wb_status_real_power(st)
    stale_status_ceiling_w = float(status_amp) * 230.0 * float(phases)
    confirmation_margin_w = 460.0 * float(phases)
    if real_power_w <= stale_status_ceiling_w + confirmation_margin_w:
        return status_amp
    return command_amp


def _wallbox_status_stale_guard_s(config, default_s=WALLBOX_STATUS_STALE_DEFAULT_S):
    try:
        raw = (config or {}).get("wallbox_status_stale_guard_s", default_s)
        return max(10.0, min(300.0, float(str(raw).strip().replace(",", ".") or default_s)))
    except Exception:
        return float(default_s)


_copy_wallbox_status_diagnostics = _wallbox_status_service.copy_diagnostics
_safe_stale_wallbox_status = _wallbox_status_service.safe_stale_status
_wallbox_driver_status_or_stale = _wallbox_status_service.status_or_stale


def _evaluate_e3dc_session_for_manager(
    c_data,
    status,
    *,
    cap_amp=0,
    budget_ready=False,
    switch_to_1p_ready=False,
    grid_allowed=False,
    price_active=False,
    price_boost_active=False,
    predump_active=False,
    mode_off=False,
    priority_forced_stop=False,
    min_amp=6,
    now_ts=None,
    start_verify_s=180,
):
    """Attach the pure E3DC session state to the live status dict."""

    if not e3dc_session.is_e3dc_native_charger((c_data or {}).get("charger")):
        return {}
    contract = _wallbox_e3dc_native_production_contract(c_data, status, None)
    if contract.get("enabled", False):
        c_data["_e3dc_native_contract"] = contract
    session = e3dc_session.evaluate_session(
        status,
        current_set_amp=(c_data or {}).get("current_set_amp", 0),
        cap_amp=cap_amp,
        min_amp=min_amp,
        budget_ready=bool(budget_ready),
        switch_to_1p_ready=bool(switch_to_1p_ready),
        grid_allowed=bool(grid_allowed),
        price_active=bool(price_active),
        price_boost_active=bool(price_boost_active),
        predump_active=bool(predump_active),
        mode_off=bool(mode_off),
        priority_forced_stop=bool(priority_forced_stop),
        stop_sent_active=bool((c_data or {}).get("_wb_stop_sent_active", False)),
        ended_latched=bool((c_data or {}).get("_bev_full_blocked", False)),
        end_reason=str((c_data or {}).get("_bev_full_block_reason") or ""),
        last_start_ts=(c_data or {}).get("last_start_ts", 0.0),
        now_ts=time.time() if now_ts is None else now_ts,
        start_verify_s=start_verify_s,
    )
    if status is not None:
        _apply_e3dc_native_production_contract_to_status(status, contract)
        e3dc_session.apply_session_to_status(status, session)
    c_data["_e3dc_session_state"] = session.get("state", e3dc_session.STATE_IDLE)
    c_data["_e3dc_session"] = session
    return session


def _evaluate_openwb_pro_session_for_manager(
    c_data,
    status,
    *,
    cap_amp=0,
    budget_ready=False,
    switch_to_1p_ready=False,
    grid_allowed=False,
    price_active=False,
    price_boost_active=False,
    predump_active=False,
    mode_off=False,
    priority_forced_stop=False,
    min_amp=6,
    now_ts=None,
    start_verify_s=180,
    stable_hw_power_w=0.0,
):
    """Attach the pure openWB Pro session contract to the live status dict."""

    if not openwb_pro_session.is_openwb_pro_charger((c_data or {}).get("charger")):
        return {}
    session_now = time.time() if now_ts is None else float(now_ts)
    stop_display = _manager_stop_display_state(c_data, now_ts=now_ts)
    if isinstance(status, dict) and not stop_display.get("active", False):
        # Statusobjekte werden wiederverwendet. Nach Ablauf des autoritativen
        # Manager-Stopps muss der vorige reine Anzeigemarker verschwinden,
        # sonst kann er eine bereits ladende openWB Pro fälschlich auf dem
        # Startstrom halten.
        status.pop("manager_stop_pending", None)
        status.pop("manager_stop_reason", None)
        status.pop("manager_stop_age_s", None)
    session = openwb_pro_session.evaluate_session(
        status,
        state_data=c_data,
        current_set_amp=(c_data or {}).get("current_set_amp", 0),
        cap_amp=cap_amp,
        min_amp=min_amp,
        budget_ready=bool(budget_ready),
        switch_to_1p_ready=bool(switch_to_1p_ready),
        grid_allowed=bool(grid_allowed),
        price_active=bool(price_active),
        price_boost_active=bool(price_boost_active),
        predump_active=bool(predump_active),
        mode_off=bool(mode_off),
        priority_forced_stop=bool(priority_forced_stop),
        stop_sent_active=bool((c_data or {}).get("_wb_stop_sent_active", False)),
        manager_stop_pending=bool(stop_display.get("active", False)),
        manager_stop_reason=str(stop_display.get("reason", "") or ""),
        ended_latched=bool((c_data or {}).get("_bev_full_blocked", False)),
        end_reason=str((c_data or {}).get("_bev_full_block_reason") or ""),
        last_start_ts=(c_data or {}).get("last_start_ts", 0.0),
        now_ts=session_now,
        start_verify_s=start_verify_s,
        stable_hw_power_w=stable_hw_power_w,
    )
    liveness = openwb_pro_session.start_liveness_contract(
        session,
        c_data,
        status,
        now_ts=session_now,
        timeout_s=start_verify_s,
    )
    liveness_patch = liveness.get("state_patch")
    if isinstance(liveness_patch, dict):
        for key, value in liveness_patch.items():
            if value is None:
                c_data.pop(key, None)
            else:
                c_data[key] = value
    c_data["_openwb_pro_start_liveness_contract"] = liveness
    session["start_liveness"] = liveness
    start_reject_episode = (c_data or {}).get(
        "_openwb_pro_start_reject_episode_contract"
    )
    if isinstance(start_reject_episode, dict):
        session["start_reject_episode"] = dict(start_reject_episode)
        session["start_reject_episode_complete"] = bool(
            start_reject_episode.get("complete", False)
        )
    else:
        session.pop("start_reject_episode", None)
        session.pop("start_reject_episode_complete", None)
    if status is not None:
        openwb_pro_session.apply_session_to_status(status, session)
        if isinstance(start_reject_episode, dict):
            status["openwb_pro_start_reject_episode_contract"] = dict(
                start_reject_episode
            )
            status["openwb_pro_start_reject_episode_complete"] = bool(
                start_reject_episode.get("complete", False)
            )
            status["openwb_pro_start_reject_episode_attempts"] = int(
                start_reject_episode.get("sent_count", 0) or 0
            )
            status["openwb_pro_start_reject_episode_max_attempts"] = int(
                start_reject_episode.get("max_retries", 0) or 0
            )
        else:
            _clear_stale_openwb_pro_start_reject_episode_status(
                c_data,
                status,
            )
        finished_contract = (c_data or {}).get("_openwb_pro_vehicle_finished_contract")
        if isinstance(finished_contract, dict):
            openwb_pro_session.apply_vehicle_finished_drop_to_status(status, finished_contract)
        retry_contract = (c_data or {}).get("_openwb_pro_start_retry_guard_contract")
        if isinstance(retry_contract, dict):
            status["openwb_pro_start_retry_guard_contract"] = retry_contract
    c_data["_openwb_pro_session_state"] = session.get("state", openwb_pro_session.STATE_IDLE)
    c_data["_openwb_pro_session"] = session
    return session


def _reconcile_openwb_pro_manager_zero_anchor(
    c_data,
    status,
    *,
    cap_amp=0,
    min_amp=6,
    budget_ready=False,
    fresh_budget_authorized=False,
    mode_off=False,
    priority_forced_stop=False,
    manual_pause=False,
    locked=False,
    emergency_stop=False,
    now_ts=None,
):
    """Löst einen überholten temporären Nullanker ohne Hardware-I/O."""

    data = c_data if isinstance(c_data, dict) else {}
    st = status if isinstance(status, dict) else {}
    if not openwb_pro_session.is_openwb_pro_charger(data.get("charger")):
        return {}
    now_value = time.time() if now_ts is None else float(now_ts)
    stop_display = _manager_stop_display_state(data, now_ts=now_value)
    legacy_commit = _normalize_openwb_pro_legacy_phase_commit(
        data,
        st,
        now_ts=now_value,
    )
    data["_openwb_pro_legacy_phase_commit_normalization"] = legacy_commit
    reservation = data.get("_wallbox_phase_transition_reservation")
    preoutput_grant_ready = _phase_transition_preoutput_grant_ready(data)
    phase_restart = _openwb_pro_phase_restart_current_contract(
        data,
        st,
        now_ts=now_value,
    )
    data["_openwb_pro_phase_restart_current_contract"] = phase_restart
    phase_restart_ready = bool(phase_restart.get("authorized", False))
    committed_transition = (
        _openwb_pro_committed_transition_waits_for_charge_contract(
            data,
            st,
            now_ts=now_value,
        )
    )
    data[
        "_openwb_pro_committed_transition_waits_for_charge_contract"
    ] = committed_transition
    committed_transition_authorized = bool(
        committed_transition.get("authorized", False)
    )
    shadow_reconcile = (
        _reconcile_openwb_pro_committed_idle_zero_current_shadow(
            data,
            st,
            committed_transition,
            min_amp=min_amp,
        )
    )
    data[
        "_openwb_pro_committed_idle_zero_shadow_reconcile_contract"
    ] = shadow_reconcile
    committed_transition_ready = bool(
        committed_transition_authorized
        and (
            shadow_reconcile.get("reconciled") is True
            or _cfg_float(data.get("current_set_amp"), 0.0) < 0.5
        )
    )
    phase_execution_ready = bool(
        phase_restart_ready or committed_transition_ready
    )
    phase_transition_active = bool(
        isinstance(reservation, dict) and reservation.get("active")
        and not preoutput_grant_ready
        and not phase_execution_ready
    )
    phase_recovery_ambiguous = bool(
        not phase_execution_ready
        and (
            (
                isinstance(data.get("_openwb_pro_phase_recovery_hold"), dict)
                and data["_openwb_pro_phase_recovery_hold"].get("active") is True
            )
            or (
                isinstance(data.get("_openwb_pro_phase_sequence"), dict)
                and str(data["_openwb_pro_phase_sequence"].get("stage") or "") not in ("", "ready", "completed", "aborted", "idle")
            )
            or (
                isinstance(reservation, dict)
                and reservation.get("active")
                and not preoutput_grant_ready
                and str(reservation.get("stage") or "") not in (
                    "", "idle", "completed", "aborted", "expired"
                )
            )
        )
    )
    contract = openwb_pro_session.manager_zero_anchor_release_contract(
        st,
        data,
        cap_amp=cap_amp,
        min_amp=min_amp,
        budget_ready=bool(budget_ready),
        fresh_budget_authorized=bool(fresh_budget_authorized),
        mode_off=bool(mode_off),
        priority_forced_stop=bool(priority_forced_stop),
        ended_latched=bool(data.get("_bev_full_blocked", False)),
        manual_pause=bool(manual_pause),
        locked=bool(locked),
        emergency_stop=bool(emergency_stop),
        manager_stop_pending=bool(stop_display.get("active", False)),
        phase_transition_active=phase_transition_active,
        phase_recovery_ambiguous=phase_recovery_ambiguous,
        allow_soft_start_reject=True,
        now_ts=now_value,
    )
    data["_openwb_pro_manager_zero_anchor_release_contract"] = contract
    data["_openwb_pro_phase_preoutput_grant_ready"] = bool(
        preoutput_grant_ready
    )
    if isinstance(status, dict):
        status["openwb_pro_manager_zero_anchor_release_contract"] = contract
    if not contract.get("allow_release", False):
        return contract

    released_reason = str(contract.get("anchor_reason") or "")
    release_patch = contract.get("state_patch")
    if isinstance(release_patch, dict):
        for key, value in release_patch.items():
            if value is None:
                data.pop(key, None)
            else:
                data[key] = value
    data["_last_manager_zero_anchor_release_ts"] = now_value
    data["_last_manager_zero_anchor_release_reason"] = released_reason
    _log_state_once(
        data,
        "openwb_pro_zero_anchor_released",
        (released_reason, int(round(float(cap_amp or 0)))),
        "WB%d temporärer 0-A-Anker freigegeben: %s, neue ausführbare Freigabe %.1f A"
        % (
            int(data.get("id", 0) or 0),
            released_reason,
            float(cap_amp or 0),
        ),
        min_interval_s=60.0,
    )
    return contract


def _openwb_pro_no_vehicle_stop_guard(c_data, status, *, now_ts=None):
    """Erkennt ausschließlich den eigenen kurzen CP-Wake-up-Unplug."""

    data = c_data if isinstance(c_data, dict) else {}
    st = status if isinstance(status, dict) else {}
    now_value = time.time() if now_ts is None else float(now_ts)
    if not openwb_pro_session.is_openwb_pro_charger(data.get("charger")):
        return False
    contract = openwb_pro_session.manager_owned_wakeup_disconnect_contract(
        st,
        data,
        now_ts=now_value,
    )
    data["_openwb_pro_manager_wakeup_disconnect_contract"] = contract
    if isinstance(status, dict):
        status["openwb_pro_manager_wakeup_disconnect_contract"] = contract
    return bool(contract.get("synthetic_disconnect", False))


def _release_openwb_pro_confirmed_charge_soft_stop(
    c_data,
    status,
    *,
    mode_off=False,
    priority_forced_stop=False,
    manual_pause=False,
    locked=False,
    emergency_stop=False,
    now_ts=None,
):
    """Räumt einen widersprüchlichen Soft-Stop ohne Hardware-I/O auf."""

    data = c_data if isinstance(c_data, dict) else {}
    st = status if isinstance(status, dict) else {}
    if not openwb_pro_session.is_openwb_pro_charger(data.get("charger")):
        return {}
    now_value = time.time() if now_ts is None else float(now_ts)
    contract = openwb_pro_session.confirmed_charge_soft_stop_release_contract(
        st,
        data,
        now_ts=now_value,
        mode_off=bool(mode_off),
        priority_forced_stop=bool(priority_forced_stop),
        manual_pause=bool(manual_pause),
        locked=bool(locked),
        emergency_stop=bool(emergency_stop),
    )
    data["_openwb_pro_confirmed_charge_soft_stop_release_contract"] = contract
    if isinstance(status, dict):
        status[
            "openwb_pro_confirmed_charge_soft_stop_release_contract"
        ] = contract
    if not contract.get("allow_release", False):
        return contract
    for key, value in (contract.get("state_patch") or {}).items():
        if value is None:
            data.pop(key, None)
        else:
            data[key] = value
    session = data.get("_openwb_pro_session")
    if isinstance(session, dict):
        session.update(contract.get("session_patch") or {})
    data["_last_confirmed_charge_soft_stop_release_ts"] = now_value
    return contract


def _refresh_disconnected_openwb_pro_session_contract(c_data, status, *, now_ts=None):
    """Neutralisiert einen frischen abgesteckten openWB-Pro-Status ohne Ausgangsbefehl."""

    if not openwb_pro_session.is_openwb_pro_charger((c_data or {}).get("charger")):
        return {}
    if (
        not bool((status or {}).get("driver_status_valid", False))
        or bool((status or {}).get("driver_status_stale", False))
    ):
        return {}
    return _evaluate_openwb_pro_session_for_manager(
        c_data,
        status,
        cap_amp=0,
        budget_ready=False,
        switch_to_1p_ready=False,
        grid_allowed=False,
        price_active=False,
        price_boost_active=False,
        predump_active=False,
        mode_off=False,
        priority_forced_stop=False,
        now_ts=now_ts,
        stable_hw_power_w=0.0,
    )


